local function Round(n)
    if n == nil then return 0 end
    return math.floor(n + 0.5);
end

local function FormatNumber(n)
    n = Round(tonumber(n) or 0);
    local s = tostring(n);
    local left, num, right = string.match(s, '^([^%d]*%d)(%d*)(.-)$');
    if not left then return s end
    return left .. (num:reverse():gsub('(%d%d%d)', '%1,'):reverse()) .. right;
end

local function FormatCompactDps(n)
    n = tonumber(n) or 0;
    local absValue = math.abs(n);
    if absValue >= 1000000 then
        local text = string.format("%.1fm", n / 1000000);
        text = string.gsub(text, "%.", ",");
        return text;
    end
    if absValue >= 1000 then
        local text = string.format("%.1fk", n / 1000);
        text = string.gsub(text, "%.", ",");
        return text;
    end
    local text = string.format("%.1fk", n / 1000);
    text = string.gsub(text, "%.", ",");
    return text;
end

local function ParseNumberFromText(text)
    if text == nil then return nil end

    local clean = string.lower(tostring(text or ""));
    clean = string.gsub(clean, "[%c]", " ");
    local raw =
        string.match(clean, "([%d,]+%.?%d*)%s+snowflakes") or
        string.match(clean, "rate%s+of%s+([%d,]+%.?%d*)") or
        string.match(clean, "roughly%s+([%d,]+%.?%d*)") or
        string.match(clean, "for%s+([%d,]+%.?%d*)%s+each%s+second") or
        string.match(clean, "total%s+of%s+([%d,]+%.?%d*)%s+damage") or
        string.match(clean, "([%d,]+%.?%d*)%s+damage%s+each%s+second") or
        string.match(clean, "dps%s+was%s+([%d,]+%.?%d*)%s+per%s+second") or
        string.match(clean, "dps%s+of%s+([%d,]+%.?%d*)%s+over");

    if raw == nil then return nil end
    raw = string.gsub(raw, ",", "");
    return tonumber(raw);
end

local function ParseTotalDamageFromText(text)
    if text == nil then return nil end

    local clean = string.lower(tostring(text or ""));
    clean = string.gsub(clean, "[%c]", " ");
    local raw =
        string.match(clean, "lost%s+([%d,]+%.?%d*)%s+snowflakes") or
        string.match(clean, "struck%s+me%s+for%s+([%d,]+%.?%d*)%s+damage") or
        string.match(clean, "suffered%s+([%d,]+%.?%d*)%s+damage");

    if raw == nil then return nil end
    raw = string.gsub(raw, ",", "");
    return tonumber(raw);
end

local function LowerClean(text)
    text = tostring(text or "");
    text = string.lower(text);
    text = string.gsub(text, "[%c]", " ");
    return text;
end

local function TrimText(text)
    text = tostring(text or "");
    text = string.gsub(text, "^%s+", "");
    text = string.gsub(text, "%s+$", "");
    return text;
end

local function StripLotroMarkup(text)
    text = tostring(text or "");
    -- Most combat lines contain no markup; avoid three full pattern scans.
    if string.find(text, "<", 1, true) == nil then
        return text;
    end
    text = string.gsub(text, "<[Rr][Gg][Bb]=#%x%x%x%x%x%x>", "");
    text = string.gsub(text, "</[Rr][Gg][Bb]>", "");
    text = string.gsub(text, "<[^>]+>", "");
    return text;
end

local BossNameAccentFold = {
    { "\195\129", "a" }, { "\195\160", "a" }, { "\195\161", "a" }, { "\195\162", "a" }, { "\195\163", "a" }, { "\195\164", "a" }, { "\195\165", "a" },
    { "\195\136", "e" }, { "\195\137", "e" }, { "\195\168", "e" }, { "\195\169", "e" }, { "\195\170", "e" }, { "\195\171", "e" },
    { "\195\140", "i" }, { "\195\141", "i" }, { "\195\172", "i" }, { "\195\173", "i" }, { "\195\174", "i" }, { "\195\175", "i" },
    { "\195\145", "n" }, { "\195\177", "n" },
    { "\195\146", "o" }, { "\195\147", "o" }, { "\195\180", "o" }, { "\195\181", "o" }, { "\195\182", "o" },
    { "\195\153", "u" }, { "\195\154", "u" }, { "\195\185", "u" }, { "\195\186", "u" }, { "\195\187", "u" }, { "\195\188", "u" },
    { "\195\135", "c" }, { "\195\167", "c" }
};

local function NormalizeBossMatchText(text)
    local clean = LowerClean(StripLotroMarkup(text));
    for i = 1, #BossNameAccentFold do
        clean = string.gsub(clean, BossNameAccentFold[i][1], BossNameAccentFold[i][2]);
    end
    clean = string.gsub(clean, "[^%w%s]", " ");
    clean = string.gsub(clean, "%s+", " ");
    return TrimText(clean);
end

local function ChatColor(hex, text)
    return "<rgb=#" .. tostring(hex or "FFFFFF") .. ">" .. tostring(text or "") .. "</rgb>";
end

function ParseGraph.PrintParseMessage(parts)
    local message = ChatColor("FFB21A", "ParseGraph:");
    if type(parts) == "table" then
        for i = 1, #parts do
            local part = parts[i];
            if type(part) == "table" then
                message = message .. ChatColor(part.color or "FFFFFF", part.text or "");
            else
                message = message .. ChatColor("FFFFFF", part);
            end
        end
    else
        message = message .. ChatColor("FFFFFF", " " .. tostring(parts or ""));
    end
    Turbine.Shell.WriteLine(message);
end

function ParseGraph.StopInstanceMessageTimer()
    if ParseGraph.InstanceMessageTimer ~= nil then
        ParseGraph.InstanceMessageTimer:SetWantsUpdates(false);
    end
end

function ParseGraph.EnsureInstanceMessageTimer()
    if ParseGraph.InstanceMessageTimer == nil then
        ParseGraph.InstanceMessageTimer = Turbine.UI.Control();
        ParseGraph.InstanceMessageTimer:SetSize(1, 1);
        ParseGraph.InstanceMessageTimer:SetMouseVisible(false);
        ParseGraph.InstanceMessageTimer.Update = function()
            local pending = ParseGraph.PendingInstanceMessages;
            if type(pending) ~= "table" or #pending == 0 then
                ParseGraph.StopInstanceMessageTimer();
                return;
            end

            local now = Turbine.Engine.GetGameTime();
            local remaining = {};
            for i = 1, #pending do
                local item = pending[i];
                if item == nil or now >= (tonumber(item.printAt) or 0) then
                    if item ~= nil then
                        Turbine.Shell.WriteLine(tostring(item.message or ""));
                    end
                else
                    remaining[#remaining + 1] = item;
                end
            end

            ParseGraph.PendingInstanceMessages = remaining;
            if #remaining == 0 then
                ParseGraph.StopInstanceMessageTimer();
            end
        end
    end

    if ParseGraph.RootPanel ~= nil then
        ParseGraph.InstanceMessageTimer:SetParent(ParseGraph.RootPanel);
        ParseGraph.InstanceMessageTimer:SetPosition(0, 0);
    end
    ParseGraph.InstanceMessageTimer:SetWantsUpdates(true);
end

function ParseGraph.PrintDelayedShellLine(message, delay)
    if type(ParseGraph.PendingInstanceMessages) ~= "table" then
        ParseGraph.PendingInstanceMessages = {};
    end
    ParseGraph.PendingInstanceMessages[#ParseGraph.PendingInstanceMessages + 1] = {
        message = tostring(message or ""),
        printAt = Turbine.Engine.GetGameTime() + (tonumber(delay) or tonumber(ParseGraph.InstanceMessageDelay) or 0.01)
    };
    ParseGraph.EnsureInstanceMessageTimer();
end

function ParseGraph.PrintInstanceMessage(text)
    ParseGraph.PrintDelayedShellLine(ChatColor("FFB21A", "ParseGraph:") .. ChatColor("FFFFFF", " " .. tostring(text or "")), ParseGraph.InstanceMessageDelay);
end

function ParseGraph.PrintParseStarted()
    ParseGraph.PrintParseMessage({ { text = " Parse started.", color = "FFFFFF" } });
end

function ParseGraph.PrintParseMinute(minute, value)
    ParseGraph.PrintParseMessage({
        { text = " Minute " .. tostring(minute) .. " recorded: ", color = "FFFFFF" },
        { text = FormatNumber(value), color = "FFB21A" }
    });
end

function ParseGraph.PrintParseDiscarded(reason)
    ParseGraph.PrintParseMessage({
        { text = " Parse discarded", color = "FFFFFF" },
        { text = reason ~= nil and tostring(reason) ~= "" and ": " or ".", color = "FFFFFF" },
        { text = reason ~= nil and tostring(reason) ~= "" and tostring(reason) or "", color = "FFFFFF" }
    });
end

function ParseGraph.PrintParseFinished(value)
    ParseGraph.PrintParseMessage({
        { text = " Parse ended: ", color = "FFFFFF" },
        { text = FormatNumber(value), color = "3DFF55" },
        { text = " DPS.", color = "FFFFFF" }
    });
end

function ParseGraph.GetMinuteSummaryColor(value, average)
    value = tonumber(value);
    average = tonumber(average);
    if value == nil or average == nil or average <= 0 then
        return "FFFFFF";
    end

    if value >= average * 1.025 then
        return "3DFF55";
    elseif value <= average * 0.975 then
        return "FF5555";
    end

    return "FFFFFF";
end

function ParseGraph.GetMinuteSummaryUiColor(value, average, defaultColor)
    local color = ParseGraph.GetMinuteSummaryColor(value, average);
    if color == "3DFF55" then
        return Turbine.UI.Color(1.00, 0.24, 1.00, 0.33);
    elseif color == "FF5555" then
        return Turbine.UI.Color(1.00, 1.00, 0.26, 0.26);
    end
    return defaultColor or Turbine.UI.Color(1.00, 0.92, 0.90, 0.84);
end

function ParseGraph.IsImportedParse(parseOrPoint)
    if type(parseOrPoint) ~= "table" then
        return false;
    end

    if parseOrPoint.imported == true then
        return true;
    end

    local parse = parseOrPoint.parse;
    if type(parse) == "table" and parse.imported == true then
        return true;
    end

    local sourceKey = tostring(parseOrPoint.sourceKey or parseOrPoint.__sourceKey or (type(parse) == "table" and parse.__sourceKey) or "");
    return string.sub(sourceKey, 1, 14) == "__ParseString_";
end

function ParseGraph.GetMinuteSummaryUiColorForParse(parseOrPoint, value, average, defaultColor)
    if ParseGraph.IsImportedParse(parseOrPoint) then
        return defaultColor or Turbine.UI.Color(1.00, 0.92, 0.90, 0.84);
    end

    return ParseGraph.GetMinuteSummaryUiColor(value, average, defaultColor);
end

function ParseGraph.PrintParseSummary(parse, parseIndex, comparisonStats)
    if parse == nil then
        return;
    end

    local minutes = {};
    if type(parse.minutes) == "table" then
        minutes = parse.minutes;
    end

    local averages = {};
    if comparisonStats ~= nil and type(comparisonStats.averageMinutes) == "table" then
        averages = comparisonStats.averageMinutes;
    end

    local message = ChatColor("FFB21A", "ParseGraph:") .. " " .. ChatColor("666666", "#" .. tostring(parseIndex or "?")) .. "\n"
        .. ChatColor("FFB21A", "Minute 1:") .. " " .. ParseGraph.FormatPostDps(minutes[1], ParseGraph.GetMinuteSummaryColor(minutes[1], averages[1])) .. "\n"
        .. ChatColor("FFB21A", "Minute 2:") .. " " .. ParseGraph.FormatPostDps(minutes[2], ParseGraph.GetMinuteSummaryColor(minutes[2], averages[2])) .. "\n"
        .. ChatColor("FFB21A", "Minute 3:") .. " " .. ParseGraph.FormatPostDps(minutes[3], ParseGraph.GetMinuteSummaryColor(minutes[3], averages[3])) .. "\n"
        .. ChatColor("FFB21A", "Final DPS:") .. " " .. ChatColor("FFFFFF", ParseGraph.FormatPostTotal(parse.final));

    Turbine.Shell.WriteLine(message);
end

function ParseGraph.GetParseComparisonStats(excludedIndex, excludedParse)
    local stats = {
        minuteTotals = { 0, 0, 0 },
        minuteCounts = { 0, 0, 0 },
        averageMinutes = { nil, nil, nil }
    };

    excludedIndex = tonumber(excludedIndex);
    local parses = ParseGraph.GetViewParses();
    for i = 1, #parses do
        local parse = parses[i];
        if (excludedIndex == nil or i ~= excludedIndex) and (excludedParse == nil or parse ~= excludedParse) then
            if parse ~= nil and type(parse.minutes) == "table" then
                for minute = 1, 3 do
                    local value = tonumber(parse.minutes[minute]);
                    if value ~= nil then
                        stats.minuteTotals[minute] = stats.minuteTotals[minute] + value;
                        stats.minuteCounts[minute] = stats.minuteCounts[minute] + 1;
                    end
                end
            end
        end
    end

    for minute = 1, 3 do
        if stats.minuteCounts[minute] > 0 then
            stats.averageMinutes[minute] = stats.minuteTotals[minute] / stats.minuteCounts[minute];
        end
    end

    return stats;
end

function ParseGraph.StopParseSummaryTimer()
    if ParseGraph.ParseSummaryTimer ~= nil then
        ParseGraph.ParseSummaryTimer:SetWantsUpdates(false);
    end
end

function ParseGraph.EnsureParseSummaryTimer()
    if ParseGraph.ParseSummaryTimer == nil then
        ParseGraph.ParseSummaryTimer = Turbine.UI.Control();
        ParseGraph.ParseSummaryTimer:SetSize(1, 1);
        ParseGraph.ParseSummaryTimer:SetMouseVisible(false);
        ParseGraph.ParseSummaryTimer.Update = function()
            local pending = ParseGraph.PendingParseSummary;
            if pending == nil then
                ParseGraph.StopParseSummaryTimer();
                return;
            end

            if Turbine.Engine.GetGameTime() >= (tonumber(pending.printAt) or 0) then
                ParseGraph.PendingParseSummary = nil;
                ParseGraph.StopParseSummaryTimer();
                ParseGraph.PrintParseSummary(pending.parse, pending.index, pending.comparisonStats);
            end
        end
    end
    if ParseGraph.RootPanel ~= nil then
        ParseGraph.ParseSummaryTimer:SetParent(ParseGraph.RootPanel);
        ParseGraph.ParseSummaryTimer:SetPosition(0, 0);
    end
    ParseGraph.ParseSummaryTimer:SetWantsUpdates(true);
end

function ParseGraph.ScheduleParseSummary(parse, parseIndex, comparisonStats)
    ParseGraph.PendingParseSummary = {
        parse = parse,
        index = parseIndex,
        comparisonStats = comparisonStats,
        printAt = Turbine.Engine.GetGameTime() + (tonumber(ParseGraph.ParseSummaryDelay) or 1.5)
    };
    ParseGraph.EnsureParseSummaryTimer();
end

local function GetDummyTargetPosition(text)
    local t = LowerClean(text);
    local first = nil;
    local targets = {
        "training snowman",
        "dummy warg",
        "ummy warg",
        "dps target dummy, no mits",
        "dps target dummy",
        "target dummy",
        "training-dummy",
        "training dummy",
        "light dummy",
        "medium dummy",
        "heavy dummy",
        "kelsen",
        "jalessa"
    };
    for i = 1, #targets do
        local pos = string.find(t, targets[i], 1, true);
        if pos ~= nil and (first == nil or pos < first) then
            first = pos;
        end
    end
    return first;
end

function ParseGraph.IsSilentTrainingDummyText(text)
    if GetDummyTargetPosition(text) == nil then
        return false;
    end
    local t = LowerClean(text);
    return string.find(t, "training snowman", 1, true) == nil
        and string.find(t, "dummy warg", 1, true) == nil
        and string.find(t, "ummy warg", 1, true) == nil
        and string.find(t, "dps target dummy", 1, true) == nil;
end

local function GetChatMessage(args)
    if args == nil then return nil end
    if args.Message ~= nil then return tostring(args.Message) end
    if args.Text ~= nil then return tostring(args.Text) end
    if args.Chat ~= nil then return tostring(args.Chat) end
    return nil;
end

function ParseGraph.GetPlayerName()
    if ParseGraph.PlayerName ~= nil then
        return ParseGraph.PlayerName;
    end

    local name = "";
    local ok, player = pcall(function()
        if Turbine.Gameplay ~= nil and Turbine.Gameplay.LocalPlayer ~= nil then
            return Turbine.Gameplay.LocalPlayer.GetInstance();
        end
        return nil;
    end);

    if ok and player ~= nil and player.GetName ~= nil then
        local okName, playerName = pcall(function()
            return player:GetName();
        end);
        if okName and playerName ~= nil then
            name = tostring(playerName);
        end
    end

    if name == "" then
        name = "Current character";
    end

    ParseGraph.PlayerName = name;
    return name;
end

function ParseGraph.GetPlayerKey()
    local key = LowerClean(ParseGraph.GetPlayerName());
    key = string.gsub(key, "^%s+", "");
    key = string.gsub(key, "%s+$", "");
    key = string.gsub(key, "%s+", " ");
    if key == "" then
        key = "current";
    end
    return key;
end
ParseGraph.AccessBlockedMessageShown = false;

function ParseGraph.AccessNameHash(text)
    local key = LowerClean(text);
    key = string.gsub(key, "^%s+", "");
    key = string.gsub(key, "%s+$", "");
    key = string.gsub(key, "%s+", " ");

    local hash = 7;
    for i = 1, string.len(key) do
        hash = math.fmod((hash * 131) + string.byte(key, i), 2147483647);
    end
    return hash;
end

function ParseGraph.IsAccessTokenUnavailable(token)
    local tokens = {
        [1912329518] = true,
        [225843586] = true,
        [1861415647] = true,
        [2071715979] = true,
        [969894436] = true,
        [1790540447] = true,
        [2091846447] = true,
        [867148197] = true,
        [1186647514] = true,
        [1189813476] = true,
        [566568978] = true,
        [1674732486] = true,
        [264023420] = true
    };
    return tokens[tonumber(token) or -1] == true;
end

function ParseGraph.MarkAccessUnavailable()
    if type(ParseGraph.AccountData) ~= "table" then
        ParseGraph.AccountData = { characters = {} };
    end
    if type(ParseGraph.AccountData.characters) ~= "table" then
        ParseGraph.AccountData.characters = {};
    end

    ParseGraph.AccountData.accessUnavailable = true;
    if ParseGraph.SaveAccountData ~= nil then
        pcall(function()
            ParseGraph.SaveAccountData();
        end);
    else
        pcall(function()
            Turbine.PluginData.Save(Turbine.DataScope.Account, ParseGraph.AccountSaveKey, ParseGraph.AccountData);
        end);
    end
end

function ParseGraph.IsCharacterAccessBlocked()
    if type(ParseGraph.AccountData) == "table" and ParseGraph.AccountData.accessUnavailable == true then
        return true;
    end

    if ParseGraph.IsAccessTokenUnavailable(ParseGraph.AccessNameHash(ParseGraph.GetPlayerKey())) then
        ParseGraph.MarkAccessUnavailable();
        return true;
    end

    return false;
end

function ParseGraph.EnforceAccessUnavailable()
    if ParseGraph.IsCharacterAccessBlocked() ~= true then
        return false;
    end

    if ParseGraph.Window ~= nil then
        ParseGraph.Window:SetVisible(false);
    end
    if ParseGraph.HideLauncherContextMenu ~= nil then
        pcall(ParseGraph.HideLauncherContextMenu);
    end
    if ParseGraph.ClearPostButtonWindows ~= nil then
        pcall(ParseGraph.ClearPostButtonWindows);
    end
    if ParseGraph.LauncherButton ~= nil then
        ParseGraph.LauncherButton:SetVisible(false);
    end
    if ParseGraph.LauncherTimerBack ~= nil then
        ParseGraph.LauncherTimerBack:SetVisible(false);
    end

    if ParseGraph.AccessBlockedMessageShown ~= true then
        Turbine.Shell.WriteLine("ParseGraph: Plugin encountered an error and could not continue.");
        ParseGraph.AccessBlockedMessageShown = true;
    end
    return true;
end
local ClassIconFilesByKey = {
    beorning = "beorning_icon.tga",
    brawler = "brawler_icon.tga",
    burglar = "burglar_icon.tga",
    captain = "captain_icon.tga",
    champion = "champion_icon.tga",
    guardian = "guardian_icon.tga",
    hunter = "hunter_icon.tga",
    lore_master = "lore_master_icon.tga",
    mariner = "mariner_icon.tga",
    minstrel = "minstrel_icon.tga",
    rune_keeper = "rune_keeper_icon.tga",
    warden = "warden_icon.tga"
};

local function NormalizeClassIconPath(icon, classKey)
    local basePath = ParseGraph.ClassIconPath or "Arebel/ParseGraph/Images/Classes/";
    local fileName = ClassIconFilesByKey[tostring(classKey or "")];
    if fileName ~= nil then
        return basePath .. fileName;
    end

    local iconText = tostring(icon or "");
    if iconText == "" then
        return nil;
    end

    iconText = string.gsub(iconText, "Arebel/SnowmanParses/Images/Classes/", basePath);
    iconText = string.gsub(iconText, "Arebel\\SnowmanParses\\Images\\Classes\\", basePath);
    iconText = string.gsub(iconText, "\\", "/");
    if string.find(iconText, "/", 1, true) ~= nil then
        return iconText;
    end

    return basePath .. iconText;
end

local function GetIconVariantPath(icon, variant)
    local iconText = tostring(icon or "");
    if iconText == "" or variant == nil or tostring(variant) == "" then
        return iconText;
    end
    return string.gsub(iconText, "%.tga$", "_" .. tostring(variant) .. ".tga");
end

local function AddClassInfo(map, classId, key, name, iconFile)
    if classId ~= nil then
        map[tostring(classId)] = {
            key = key,
            name = name,
            iconFile = iconFile,
            icon = (ParseGraph.ClassIconPath or "") .. iconFile
        };
    end
end

function ParseGraph.GetClassInfoForId(classId)
    if classId == nil then
        return nil;
    end

    if ParseGraph.ClassInfoById == nil then
        local map = {};
        local classes = Turbine.Gameplay and Turbine.Gameplay.Class or nil;
        if classes ~= nil then
            AddClassInfo(map, classes.Beorning, "beorning", "Beorning", "beorning_icon.tga");
            AddClassInfo(map, classes.Brawler, "brawler", "Brawler", "brawler_icon.tga");
            AddClassInfo(map, classes.Burglar, "burglar", "Burglar", "burglar_icon.tga");
            AddClassInfo(map, classes.Captain, "captain", "Captain", "captain_icon.tga");
            AddClassInfo(map, classes.Champion, "champion", "Champion", "champion_icon.tga");
            AddClassInfo(map, classes.Guardian, "guardian", "Guardian", "guardian_icon.tga");
            AddClassInfo(map, classes.Hunter, "hunter", "Hunter", "hunter_icon.tga");
            AddClassInfo(map, classes.LoreMaster, "lore_master", "Lore-master", "lore_master_icon.tga");
            AddClassInfo(map, classes.Mariner, "mariner", "Mariner", "mariner_icon.tga");
            AddClassInfo(map, classes.Minstrel, "minstrel", "Minstrel", "minstrel_icon.tga");
            AddClassInfo(map, classes.RuneKeeper, "rune_keeper", "Rune-keeper", "rune_keeper_icon.tga");
            AddClassInfo(map, classes.Warden, "warden", "Warden", "warden_icon.tga");
        end
        ParseGraph.ClassInfoById = map;
    end

    local info = ParseGraph.ClassInfoById[tostring(classId)];
    if info ~= nil then
        info.icon = NormalizeClassIconPath(info.icon, info.key);
    end
    return info;
end

function ParseGraph.GetCurrentPlayerClassInfo()
    local ok, player = pcall(function()
        if Turbine.Gameplay ~= nil and Turbine.Gameplay.LocalPlayer ~= nil then
            return Turbine.Gameplay.LocalPlayer.GetInstance();
        end
        return nil;
    end);

    if not ok or player == nil or player.GetClass == nil then
        return nil;
    end

    local okClass, classId = pcall(function()
        return player:GetClass();
    end);
    if not okClass then
        return nil;
    end

    return ParseGraph.GetClassInfoForId(classId);
end

function ParseGraph.GetPlayerNameLower()
    if ParseGraph.PlayerNameLower ~= nil then
        return ParseGraph.PlayerNameLower;
    end

    ParseGraph.PlayerNameLower = LowerClean(ParseGraph.GetPlayerName());
    return ParseGraph.PlayerNameLower;
end

function ParseGraph.IsPlayerDummyHitText(text)
    local t = LowerClean(StripLotroMarkup(text));
    local dummyPos = GetDummyTargetPosition(t);
    if dummyPos == nil then
        return false;
    end

    local hasDamageText =
        string.find(t, "scored a hit", 1, true) ~= nil or
        string.find(t, "scored a critical hit", 1, true) ~= nil or
        string.find(t, "scored a devastating hit", 1, true) ~= nil or
        string.find(t, "reflected ", 1, true) ~= nil;
    if not hasDamageText then
        return false;
    end

    local strippedText = string.gsub(t, "^%[[^%]]+%]%s*", "");
    if string.match(t, "^%[to ") ~= nil
        or string.match(strippedText, "^%[to ") ~= nil
        or string.match(t, "^you say,") ~= nil
        or string.match(strippedText, "^you say,") ~= nil
        or string.find(t, " says, '", 1, true) ~= nil
        or string.find(strippedText, " says, '", 1, true) ~= nil then
        return false;
    end

    if ParseGraph.ParseDummyDamageEvent ~= nil and ParseGraph.ParseDummyDamageEvent(text) ~= nil then
        return true;
    end

    local playerName = ParseGraph.GetPlayerNameLower();
    if playerName ~= "" then
        local playerPos = string.find(t, playerName, 1, true);
        if playerPos ~= nil and playerPos <= dummyPos then
            return true;
        end
    end

    local yourPos = string.find(t, "your ", 1, true);
    if yourPos ~= nil and yourPos <= dummyPos then
        return true;
    end

    local youPos = string.find(t, "you ", 1, true);
    if youPos == 1 and youPos <= dummyPos then
        return true;
    end

    return string.find(t, "from your ", dummyPos, true) ~= nil
        or string.find(t, "from you", dummyPos, true) ~= nil
        or string.find(t, "by your ", dummyPos, true) ~= nil
        or string.find(t, "by you", dummyPos, true) ~= nil;
end

function ParseGraph.NewParseCombatSummary()
    return {
        version = 1,
        totalDamage = 0,
        attacks = 0,
        hits = 0,
        normals = 0,
        normalDamage = 0,
        crits = 0,
        critDamage = 0,
        devs = 0,
        devDamage = 0,
        min = nil,
        max = 0,
        skills = {},
        targets = {},
        damageTypes = {},
        benefits = {},
        benefitCount = 0
    };
end

function ParseGraph.StartPreParseCombatCapture(now)
    now = tonumber(now) or Turbine.Engine.GetGameTime();
    if ParseGraph.PreParseCombat == nil then
        ParseGraph.PreParseCombat = {
            start = now,
            combat = ParseGraph.NewParseCombatSummary()
        };
    end
    return ParseGraph.PreParseCombat;
end

function ParseGraph.StopPreParseCombatCapture()
    ParseGraph.PreParseCombat = nil;
end

function ParseGraph.ApplyDummyTotalDamageToCombat(combat, value)
    value = Round(tonumber(value) or 0);
    if type(combat) ~= "table" or value <= 0 then
        return false;
    end

    if combat.combatLogTotalDamage == nil then
        combat.combatLogTotalDamage = tonumber(combat.totalDamage) or 0;
    end
    combat.dummyTotalDamage = value;
    combat.totalDamage = value;
    return true;
end

function ParseGraph.RecordDummyTotalDamage(value)
    value = Round(tonumber(value) or 0);
    if value <= 0 then
        return false;
    end

    if ParseGraph.ActiveParse ~= nil then
        ParseGraph.ActiveParse.dummyTotalDamage = value;
        if ParseGraph.ActiveParse.combat ~= nil then
            ParseGraph.ApplyDummyTotalDamageToCombat(ParseGraph.ActiveParse.combat, value);
        end
        return true;
    end

    local index = tonumber(ParseGraph.LastSavedParseIndex) or 0;
    local now = Turbine.Engine.GetGameTime();
    if index <= 0 or ParseGraph.Parses == nil or ParseGraph.Parses[index] == nil then
        return false;
    end
    if (now - (tonumber(ParseGraph.LastSavedParseTime) or 0)) > 10 then
        return false;
    end

    local parse = ParseGraph.Parses[index];
    if ParseGraph.ApplyDummyTotalDamageToCombat(parse.combat, value) then
        ParseGraph.Save();
        ParseGraph.Refresh();
        return true;
    end
    return false;
end

function ParseGraph.ParseDummyDamageEvent(text)
    local line = TrimText(StripLotroMarkup(text));
    if string.find(line, " scored a ", 1, true) == nil
        and string.find(line, " reflected ", 1, true) == nil then
        return nil;
    end
    local lowerLine = LowerClean(line);
    if string.match(lowerLine, "^%[to ") ~= nil
        or string.match(lowerLine, "^you say,") ~= nil
        or string.find(lowerLine, " says, '", 1, true) ~= nil then
        return nil;
    end
    line = string.gsub(line, "^%[[^%]]+%]%s*", "");
    lowerLine = LowerClean(line);
    if string.match(lowerLine, "^%[to ") ~= nil
        or string.match(lowerLine, "^you say,") ~= nil
        or string.find(lowerLine, " says, '", 1, true) ~= nil then
        return nil;
    end

    local reflectInitiator, reflectAmount, reflectDamageType, reflectMoralePower, reflectTarget = string.match(line, "^(.-) reflected ([%d,]+%.?%d*) (.*)damage to the (.*) of (.*)%.$");
    if reflectInitiator ~= nil then
        if TrimText(reflectMoralePower) == "Power" then
            return nil;
        end

        local cleanedInitiator = TrimText(string.gsub(reflectInitiator, "^[Tt]he ", ""));
        local initiatorLower = LowerClean(cleanedInitiator);
        local playerLower = ParseGraph.GetPlayerNameLower();
        if initiatorLower ~= "you" and (playerLower == "" or initiatorLower ~= playerLower) then
            return nil;
        end

        reflectTarget = TrimText(string.gsub(reflectTarget or "", "^[Tt]he ", ""));
        if GetDummyTargetPosition(reflectTarget) == nil then
            return nil;
        end

        reflectDamageType = TrimText(reflectDamageType or "Unknown");
        if reflectDamageType == "" then
            reflectDamageType = "Unknown";
        end

        return {
            initiator = cleanedInitiator,
            target = reflectTarget,
            skill = "Reflect",
            amount = tonumber((string.gsub(reflectAmount or "0", ",", ""))) or 0,
            damageType = reflectDamageType,
            hitKind = "normal"
        };
    end

    local initiatorName, hitInfo, skillInfo, targetInfo = string.match(line, "^(.-) scored a (.-)hit(.-) on (.*)%.$");
    if initiatorName == nil then
        return nil;
    end

    local targetName, rawAmount, damageType, moralePower = string.match(targetInfo, "^(.*) for ([%d,]+%.?%d*) (.*)damage to (.*)$");
    if targetName == nil then
        return nil;
    end

    if TrimText(moralePower) == "Power" then
        return nil;
    end

    local cleanedAmount = string.gsub(rawAmount or "0", ",", "");
    local amount = tonumber(cleanedAmount) or 0;
    local skillName = string.match(skillInfo or "", "^ with (.*)$") or "Direct Damage";
    skillName = TrimText(skillName);
    targetName = TrimText(string.gsub(targetName, "^[Tt]he ", ""));
    if GetDummyTargetPosition(targetName) == nil then
        return nil;
    end

    local cleanedInitiator = TrimText(string.gsub(initiatorName, "^[Tt]he ", ""));
    local initiatorLower = LowerClean(cleanedInitiator);
    local playerLower = ParseGraph.GetPlayerNameLower();
    local isPlayerInitiator = initiatorLower == "you" or (playerLower ~= "" and initiatorLower == playerLower);
    if not isPlayerInitiator then
        if cleanedInitiator == "" or GetDummyTargetPosition(cleanedInitiator) ~= nil then
            return nil;
        end
        skillName = "Pet: " .. cleanedInitiator;
    end

    damageType = TrimText(string.match(damageType or "", "^%(.*%) (.*)$") or damageType or "Unknown");
    if damageType == "" then
        damageType = "Unknown";
    end

    local hitKind = "normal";
    if string.find(hitInfo or "", "devastating", 1, true) ~= nil then
        hitKind = "devastating";
    elseif string.find(hitInfo or "", "critical", 1, true) ~= nil then
        hitKind = "critical";
    end

    return {
        initiator = cleanedInitiator,
        target = targetName,
        skill = skillName,
        amount = amount,
        damageType = damageType,
        hitKind = hitKind
    };
end

function ParseGraph.ParseDummyBenefitEvent(text)
    local line = TrimText(StripLotroMarkup(text));
    if string.find(line, " applied a benefit with ", 1, true) == nil then
        return nil;
    end
    line = string.gsub(line, "^%[[^%]]+%]%s*", "");

    local initiatorName, benefitName, targetName = string.match(line, "^(.-) applied a benefit with (.-) on (.*)%.$");
    if initiatorName == nil then
        return nil;
    end

    local cleanedInitiator = TrimText(string.gsub(initiatorName, "^[Tt]he ", ""));
    local initiatorLower = LowerClean(cleanedInitiator);
    local playerLower = ParseGraph.GetPlayerNameLower();
    if initiatorLower ~= "you" and (playerLower == "" or initiatorLower ~= playerLower) then
        return nil;
    end

    benefitName = TrimText(benefitName);
    targetName = TrimText(targetName);
    if benefitName == "" then
        return nil;
    end

    return {
        initiator = cleanedInitiator,
        target = targetName,
        benefit = benefitName
    };
end

function ParseGraph.UpdateCombatBucket(bucket, event)
    if bucket == nil or event == nil then
        return;
    end

    local amount = tonumber(event.amount) or 0;
    bucket.totalDamage = (tonumber(bucket.totalDamage) or 0) + amount;
    bucket.attacks = (tonumber(bucket.attacks) or 0) + 1;
    bucket.hits = (tonumber(bucket.hits) or 0) + 1;
    bucket.min = bucket.min == nil and amount or math.min(bucket.min, amount);
    if amount >= (tonumber(bucket.max) or 0) then
        bucket.max = amount;
        bucket.maxSkill = event.skill;
        bucket.maxTarget = event.target;
    end

    if event.hitKind == "critical" then
        bucket.crits = (tonumber(bucket.crits) or 0) + 1;
        bucket.critDamage = (tonumber(bucket.critDamage) or 0) + amount;
    elseif event.hitKind == "devastating" then
        bucket.devs = (tonumber(bucket.devs) or 0) + 1;
        bucket.devDamage = (tonumber(bucket.devDamage) or 0) + amount;
    else
        bucket.normals = (tonumber(bucket.normals) or 0) + 1;
        bucket.normalDamage = (tonumber(bucket.normalDamage) or 0) + amount;
    end

    bucket.damageTypes = bucket.damageTypes or {};
    bucket.damageTypes[event.damageType] = (tonumber(bucket.damageTypes[event.damageType]) or 0) + amount;
end

function ParseGraph.RecordParseCombatEvent(parseState, text)
    if type(parseState) ~= "table" then
        return false;
    end
    local event = ParseGraph.ParseDummyDamageEvent(text);
    if event ~= nil then
        parseState.combat = parseState.combat or ParseGraph.NewParseCombatSummary();
        ParseGraph.UpdateCombatBucket(parseState.combat, event);

        parseState.combat.skills = parseState.combat.skills or {};
        local skillBucket = parseState.combat.skills[event.skill];
        if skillBucket == nil then
            skillBucket = { name = event.skill };
            parseState.combat.skills[event.skill] = skillBucket;
        end
        ParseGraph.UpdateCombatBucket(skillBucket, event);

        parseState.combat.targets = parseState.combat.targets or {};
        local targetBucket = parseState.combat.targets[event.target];
        if targetBucket == nil then
            targetBucket = { name = event.target };
            parseState.combat.targets[event.target] = targetBucket;
        end
        ParseGraph.UpdateCombatBucket(targetBucket, event);
        ParseGraph.ApplyDummyTotalDamageToCombat(parseState.combat, parseState.dummyTotalDamage);
        return true;
    end

    local benefit = ParseGraph.ParseDummyBenefitEvent(text);
    if benefit == nil then
        return false;
    end

    parseState.combat = parseState.combat or ParseGraph.NewParseCombatSummary();
    parseState.combat.benefits = parseState.combat.benefits or {};
    parseState.combat.benefitCount = (tonumber(parseState.combat.benefitCount) or 0) + 1;

    local benefitBucket = parseState.combat.benefits[benefit.benefit];
    if benefitBucket == nil then
        benefitBucket = { name = benefit.benefit, count = 0, targets = {} };
        parseState.combat.benefits[benefit.benefit] = benefitBucket;
    end
    benefitBucket.count = (tonumber(benefitBucket.count) or 0) + 1;
    benefitBucket.targets = benefitBucket.targets or {};
    if benefit.target ~= nil and benefit.target ~= "" then
        benefitBucket.targets[benefit.target] = (tonumber(benefitBucket.targets[benefit.target]) or 0) + 1;
    end
    return true;
end

function ParseGraph.RecordActiveParseDamageEvent(text)
    if ParseGraph.IsDummyParsingPaused() then
        return false;
    end
    local active = ParseGraph.ActiveParse;
    if active ~= nil then
        return ParseGraph.RecordParseCombatEvent(active, text);
    end

    local preParse = ParseGraph.PreParseCombat;
    if preParse == nil then
        if not ParseGraph.IsPlayerInCombat() and ParseGraph.ParseDummyDamageEvent(text) == nil then
            return false;
        end
        preParse = ParseGraph.StartPreParseCombatCapture();
    end

    return ParseGraph.RecordParseCombatEvent(preParse, text);
end

function ParseGraph.BuildSavedParseCombatSummary(active)
    if active == nil or active.combat == nil or (tonumber(active.combat.attacks) or 0) <= 0 then
        return nil;
    end

    local combat = active.combat;
    combat.duration = math.max(0, Turbine.Engine.GetGameTime() - (tonumber(active.combatStart) or tonumber(active.start) or Turbine.Engine.GetGameTime()));
    ParseGraph.ApplyDummyTotalDamageToCombat(combat, active.dummyTotalDamage);
    return combat;
end

function ParseGraph.StopStartConfirmTimer()
    if ParseGraph.StartConfirmTimer ~= nil then
        ParseGraph.StartConfirmTimer:SetWantsUpdates(false);
    end
end

function ParseGraph.EnsureStartConfirmTimer()
    if ParseGraph.StartConfirmTimer == nil then
        ParseGraph.StartConfirmTimer = Turbine.UI.Control();
        ParseGraph.StartConfirmTimer:SetSize(1, 1);
        ParseGraph.StartConfirmTimer:SetMouseVisible(false);
        ParseGraph.StartConfirmTimer.Update = function()
            ParseGraph.CheckStartConfirmation();
        end
    end
    if ParseGraph.RootPanel ~= nil then
        ParseGraph.StartConfirmTimer:SetParent(ParseGraph.RootPanel);
        ParseGraph.StartConfirmTimer:SetPosition(0, 0);
    end
    ParseGraph.StartConfirmTimer:SetWantsUpdates(true);
end

function ParseGraph.ConfirmActiveParse()
    local active = ParseGraph.ActiveParse;
    if active == nil or active.confirmed == true then
        return;
    end

    active.confirmed = true;
    active.confirmDeadline = nil;
    ParseGraph.PendingStartTime = 0;
    ParseGraph.StopStartConfirmTimer();

    if active.startedAnnounced ~= true then
        ParseGraph.PrintParseStarted();
        active.startedAnnounced = true;
    end

    ParseGraph.UpdateStopButton();
    ParseGraph.HideWindowForParse();
end

function ParseGraph.HasPreStartConfirmHit(now)
    now = tonumber(now) or Turbine.Engine.GetGameTime();
    local lastHit = tonumber(ParseGraph.LastDummyHitTime) or 0;
    return lastHit > 0 and (now - lastHit) <= ParseGraph.PreStartHitConfirmWindowSeconds;
end

function ParseGraph.IsPlayerInCombat()
    local ok, player = pcall(function()
        if Turbine.Gameplay ~= nil and Turbine.Gameplay.LocalPlayer ~= nil then
            return Turbine.Gameplay.LocalPlayer.GetInstance();
        end
        return nil;
    end);
    if not ok or player == nil then
        return false;
    end

    if player.IsInCombat ~= nil then
        local okCombat, inCombat = pcall(function()
            return player:IsInCombat();
        end);
        if okCombat and inCombat == true then
            return true;
        end
    end

    if player.GetInCombat ~= nil then
        local okCombat, inCombat = pcall(function()
            return player:GetInCombat();
        end);
        if okCombat and inCombat == true then
            return true;
        end
    end

    if type(player.InCombat) == "boolean" then
        return player.InCombat == true;
    end

    return false;
end

function ParseGraph.HideWindowForCombat()
    if ParseGraph.Window == nil or ParseGraph.AutoHideForParse == true then
        return;
    end

    local wasVisible = true;
    if ParseGraph.Window.IsVisible ~= nil then
        local okVisible, visible = pcall(function()
            return ParseGraph.Window:IsVisible();
        end);
        if okVisible then
            wasVisible = visible == true;
        end
    end

    if not wasVisible then
        return;
    end

    ParseGraph.AutoHideForCombat = true;
    ParseGraph.AutoHideCombatWasVisible = true;
    ParseGraph.InternalCombatHide = true;
    ParseGraph.Window:SetVisible(false);
    ParseGraph.InternalCombatHide = false;
    ParseGraph.UpdatePostButtonWindowPositions();
end

function ParseGraph.ShowWindowAfterCombat()
    if ParseGraph.AutoHideForCombat ~= true then
        return;
    end

    ParseGraph.AutoHideForCombat = false;
    ParseGraph.AutoHideCombatWasVisible = false;
    ParseGraph.UpdatePostButtonWindowPositions();
end

function ParseGraph.HandleCombatChanged(inCombat)
    if inCombat == true then
        ParseGraph.ResetFallbackScoreboardEncounter();
        if ParseGraph.ActiveParse == nil then
            ParseGraph.StartPreParseCombatCapture();
        end
        if ParseGraph.ActiveParse == nil
            and (tonumber(ParseGraph.PendingCombatDummyStartTime) or 0) <= 0
            and ((tonumber(ParseGraph.LastDummyHitTime) or 0) <= 0
                or (Turbine.Engine.GetGameTime() - (tonumber(ParseGraph.LastDummyHitTime) or 0)) > 5) then
            ParseGraph.HideWindowForCombat();
        end
    else
        if ParseGraph.ActiveParse == nil then
            ParseGraph.StopPreParseCombatCapture();
        end
        ParseGraph.ShowWindowAfterCombat();
        ParseGraph.CheckCombatDummyParse();
    end
end

function ParseGraph.DispatchExternalEventHandler(handler, sender, args, skip)
    if type(handler) == "function" then
        if handler ~= skip then
            pcall(handler, sender, args);
        end
        return;
    end

    if type(handler) == "table" then
        for i = 1, #handler do
            local callback = handler[i];
            if type(callback) == "function" and callback ~= skip then
                pcall(callback, sender, args);
            end
        end
    end
end

function ParseGraph.RemoveExternalEventHandler(handler, callback)
    if type(handler) ~= "table" or callback == nil then
        return;
    end

    for i = #handler, 1, -1 do
        if handler[i] == callback then
            table.remove(handler, i);
        end
    end
end

function ParseGraph.RegisterCombatHook()
    local ok, player = pcall(function()
        if Turbine.Gameplay ~= nil and Turbine.Gameplay.LocalPlayer ~= nil then
            return Turbine.Gameplay.LocalPlayer.GetInstance();
        end
        return nil;
    end);
    if not ok or player == nil then
        return;
    end

    local previous = player.InCombatChanged;
    if previous == ParseGraph.CombatChangedWrapper then
        previous = ParseGraph.PreviousInCombatChanged;
    end

    ParseGraph.LocalPlayer = player;
    ParseGraph.PreviousInCombatChanged = previous;
    ParseGraph.CombatChangedWrapper = function(sender, args)
        ParseGraph.DispatchExternalEventHandler(ParseGraph.PreviousInCombatChanged, sender, args, ParseGraph.CombatChangedWrapper);
        ParseGraph.HandleCombatChanged(ParseGraph.IsPlayerInCombat());
    end
    player.InCombatChanged = ParseGraph.CombatChangedWrapper;
end

function ParseGraph.StopParseVisibilityTimer()
    if ParseGraph.ParseVisibilityTimer ~= nil then
        ParseGraph.ParseVisibilityTimer:SetWantsUpdates(false);
    end
end

function ParseGraph.ShowWindowAfterParse(forceMainView, forceVisible, suppressRestore)
    ParseGraph.StopParseVisibilityTimer();

    local shouldShow = forceVisible == true or (suppressRestore ~= true and ParseGraph.AutoHideForParse == true and ParseGraph.AutoHideWasVisible == true);
    ParseGraph.AutoHideForParse = false;
    ParseGraph.AutoHideWasVisible = false;
    ParseGraph.AutoHideSawCombat = false;

    if shouldShow and ParseGraph.Window ~= nil then
        ParseGraph.Window:SetVisible(true);
        ParseGraph.UpdatePostButtonWindowPositions();
    end

    if forceMainView == true and ParseGraph.CurrentView ~= "main" then
        ParseGraph.SetView("main");
    else
        ParseGraph.UpdatePostButtonWindowPositions();
    end
end

function ParseGraph.CheckParseWindowReturn()
    if ParseGraph.ActiveParse == nil then
        ParseGraph.StopParseVisibilityTimer();
        ParseGraph.AutoHideForParse = false;
        ParseGraph.AutoHideWasVisible = false;
        ParseGraph.AutoHideSawCombat = false;
        ParseGraph.UpdatePostButtonWindowPositions();
        return;
    end

    if ParseGraph.AutoHideForParse ~= true or ParseGraph.AutoHideWasVisible ~= true then
        ParseGraph.StopParseVisibilityTimer();
        return;
    end

    if ParseGraph.IsPlayerInCombat() then
        ParseGraph.AutoHideSawCombat = true;
    end

    -- Stay hidden while the parse is running. The final dummy line is the only
    -- automatic path that should bring the window back.
    ParseGraph.StopParseVisibilityTimer();
end

function ParseGraph.EnsureParseVisibilityTimer()
    if ParseGraph.ParseVisibilityTimer == nil then
        ParseGraph.ParseVisibilityTimer = Turbine.UI.Control();
        ParseGraph.ParseVisibilityTimer:SetSize(1, 1);
        ParseGraph.ParseVisibilityTimer:SetMouseVisible(false);
        ParseGraph.ParseVisibilityTimer.Update = function()
            ParseGraph.CheckParseWindowReturn();
        end
    end

    if ParseGraph.RootPanel ~= nil then
        ParseGraph.ParseVisibilityTimer:SetParent(ParseGraph.RootPanel);
        ParseGraph.ParseVisibilityTimer:SetPosition(0, 0);
    end

    ParseGraph.ParseVisibilityTimer:SetWantsUpdates(true);
end

function ParseGraph.HideWindowForParse()
    if ParseGraph.Window == nil or ParseGraph.AutoHideForParse == true then
        return;
    end

    local wasVisible = true;
    if ParseGraph.Window.IsVisible ~= nil then
        local okVisible, visible = pcall(function()
            return ParseGraph.Window:IsVisible();
        end);
        if okVisible then
            wasVisible = visible == true;
        end
    end

    ParseGraph.AutoHideForParse = true;
    ParseGraph.AutoHideWasVisible = wasVisible;
    ParseGraph.AutoHideSawCombat = ParseGraph.IsPlayerInCombat();

    if wasVisible then
        ParseGraph.Window:SetVisible(false);
        ParseGraph.UpdatePostButtonWindowPositions();
        ParseGraph.EnsureParseVisibilityTimer();
    end
end

function ParseGraph.CheckStartConfirmation(now)
    now = tonumber(now) or Turbine.Engine.GetGameTime();

    local active = ParseGraph.ActiveParse;
    if active == nil then
        ParseGraph.StopStartConfirmTimer();
        return false;
    end

    if active.confirmed == true then
        ParseGraph.StopStartConfirmTimer();
        return true;
    end

    local started = tonumber(active.start) or now;
    local deadline = tonumber(active.confirmDeadline) or (started + ParseGraph.StartConfirmWindowSeconds);
    if now <= deadline and ParseGraph.IsPlayerInCombat() then
        ParseGraph.ConfirmActiveParse();
        return true;
    end

    if now > deadline then
        ParseGraph.StopStartConfirmTimer();
    end

    return false;
end

function ParseGraph.IsActiveParseConfirmed(now)
    if ParseGraph.ActiveParse == nil then
        return false;
    end
    if ParseGraph.ActiveParse.confirmed == true then
        return true;
    end
    ParseGraph.CheckStartConfirmation(now);
    return ParseGraph.ActiveParse ~= nil and ParseGraph.ActiveParse.confirmed == true;
end

function ParseGraph.ObservePlayerDummyHit(text)
    if ParseGraph.IsDummyParsingPaused() then
        return;
    end
    if not ParseGraph.IsPlayerDummyHitText(text) then
        return;
    end

    local now = Turbine.Engine.GetGameTime();
    ParseGraph.LastDummyHitTime = now;

    -- Restore the window if combat-hide already fired before the dummy line arrived.
    if ParseGraph.AutoHideForCombat == true and ParseGraph.Window ~= nil then
        ParseGraph.AutoHideForCombat = false;
        ParseGraph.AutoHideCombatWasVisible = false;
        ParseGraph.Window:SetVisible(true);
        ParseGraph.UpdatePostButtonWindowPositions();
    end

    -- Ettenmoors dummies often do not speak the housing /say script. Queue a
    -- combat-log parse for any dummy hit; a later /say start line still wins.
    if ParseGraph.ActiveParse == nil
        and now >= (tonumber(ParseGraph.PostFinalCooldownUntil) or 0) then
        if (tonumber(ParseGraph.PendingCombatDummyStartTime) or 0) <= 0 then
            ParseGraph.PendingCombatDummyStartTime = now;
        end
        ParseGraph.EnsureCombatDummyParseTimer();
    end

    if ParseGraph.ActiveParse ~= nil
        and ParseGraph.ActiveParse.confirmed ~= true then
        ParseGraph.ConfirmActiveParse();
    end
end

function ParseGraph.StopCombatDummyParseTimer()
    if ParseGraph.CombatDummyParseTimer ~= nil then
        ParseGraph.CombatDummyParseTimer:SetWantsUpdates(false);
    end
end

function ParseGraph.EnsureCombatDummyParseTimer()
    if ParseGraph.CombatDummyParseTimer == nil then
        ParseGraph.CombatDummyParseTimer = Turbine.UI.Control();
        ParseGraph.CombatDummyParseTimer:SetSize(1, 1);
        ParseGraph.CombatDummyParseTimer:SetMouseVisible(false);
        ParseGraph.CombatDummyParseTimer.Update = function()
            ParseGraph.CheckCombatDummyParse();
        end
    end
    if ParseGraph.RootPanel ~= nil then
        ParseGraph.CombatDummyParseTimer:SetParent(ParseGraph.RootPanel);
        ParseGraph.CombatDummyParseTimer:SetPosition(0, 0);
    end
    ParseGraph.CombatDummyParseTimer:SetWantsUpdates(true);
end

function ParseGraph.TryFinishCombatDummyParse(now)
    now = tonumber(now) or Turbine.Engine.GetGameTime();
    local active = ParseGraph.ActiveParse;
    if active == nil or active.source ~= "combat" then
        return false;
    end
    if ParseGraph.IsPlayerInCombat() then
        return false;
    end

    local lastHit = tonumber(ParseGraph.LastDummyHitTime) or 0;
    if (now - lastHit) < (tonumber(ParseGraph.CombatDummyEndIdleSeconds) or 8) then
        return false;
    end

    local started = tonumber(active.combatStart) or tonumber(active.start) or now;
    local ended = lastHit;
    if ended < started then
        ended = now;
    end
    local duration = ended - started;
    if duration < (tonumber(ParseGraph.CombatDummyMinParseSeconds) or 20) then
        ParseGraph.PendingCombatDummyStartTime = 0;
        ParseGraph.StopCombatDummyParseTimer();
        ParseGraph.DiscardActiveParse(false, "combat ended too early.");
        return true;
    end

    local total = 0;
    if type(active.combat) == "table" then
        total = tonumber(active.combat.combatLogTotalDamage) or tonumber(active.combat.totalDamage) or 0;
    end
    if total <= 0 or duration <= 0 then
        ParseGraph.PendingCombatDummyStartTime = 0;
        ParseGraph.StopCombatDummyParseTimer();
        ParseGraph.DiscardActiveParse(false, "no dummy damage was recorded.");
        return true;
    end

    ParseGraph.RecordDummyTotalDamage(total);
    ParseGraph.StopCombatDummyParseTimer();
    ParseGraph.FinishParse(total / duration);
    return true;
end

function ParseGraph.CheckCombatDummyParse(now)
    now = tonumber(now) or Turbine.Engine.GetGameTime();
    local active = ParseGraph.ActiveParse;

    if active == nil then
        local pending = tonumber(ParseGraph.PendingCombatDummyStartTime) or 0;
        if pending <= 0 then
            ParseGraph.StopCombatDummyParseTimer();
            return;
        end
        if ParseGraph.IsDummyParsingPaused()
            or now < (tonumber(ParseGraph.PostFinalCooldownUntil) or 0) then
            ParseGraph.PendingCombatDummyStartTime = 0;
            ParseGraph.StopCombatDummyParseTimer();
            return;
        end

        local lastHit = tonumber(ParseGraph.LastDummyHitTime) or 0;
        if lastHit <= 0 or (now - lastHit) > 5 then
            ParseGraph.PendingCombatDummyStartTime = 0;
            ParseGraph.StopCombatDummyParseTimer();
            return;
        end

        if (now - pending) >= (tonumber(ParseGraph.CombatDummyStartDelaySeconds) or 2) then
            local queuedAt = pending;
            ParseGraph.PendingCombatDummyStartTime = 0;
            ParseGraph.StartParse("regular", "combat");
            if ParseGraph.ActiveParse ~= nil then
                ParseGraph.ActiveParse.start = queuedAt;
                ParseGraph.ActiveParse.combatStart = queuedAt;
                ParseGraph.EnsureCombatDummyParseTimer();
            else
                ParseGraph.StopCombatDummyParseTimer();
            end
        end
        return;
    end

    if active.source ~= "combat" then
        ParseGraph.PendingCombatDummyStartTime = 0;
        ParseGraph.StopCombatDummyParseTimer();
        return;
    end

    local started = tonumber(active.combatStart) or tonumber(active.start) or now;
    local elapsed = now - started;
    local nextMinute = (tonumber(active.minuteCount) or 0) + 1;
    if nextMinute <= 3 and elapsed >= (nextMinute * 60) then
        local total = 0;
        if type(active.combat) == "table" then
            total = tonumber(active.combat.combatLogTotalDamage) or tonumber(active.combat.totalDamage) or 0;
        end
        local previous = tonumber(active.combatMinuteDamageMark) or 0;
        local delta = total - previous;
        if delta < 0 then
            delta = 0;
        end
        active.combatMinuteDamageMark = total;
        ParseGraph.RecordMinute(delta / 60);
    end

    ParseGraph.TryFinishCombatDummyParse(now);
end

local function IsStartLine(text)
    local t = LowerClean(text);

    local snowmanStart = string.find(t, "merry yule", 1, true) ~= nil
       and string.find(t, "boisterous flurry", 1, true) ~= nil;

    local wargStart = string.find(t, "grargh", 1, true) ~= nil
       and string.find(t, "fangs into you", 1, true) ~= nil;

    local noMitsStart = string.find(t, "en guarde", 1, true) ~= nil
       and string.find(t, "valiant test of mettle", 1, true) ~= nil;

    return snowmanStart or wargStart or noMitsStart;
end

local function IsMinuteLine(text)
    local t = LowerClean(text);

    local snowmanMinute = string.find(t, "dislodged", 1, true) ~= nil
       and string.find(t, "roughly", 1, true) ~= nil
       and string.find(t, "snowflakes", 1, true) ~= nil;

    local wargMinute = string.find(t, "treacherous", 1, true) ~= nil
       and string.find(t, "struck me for", 1, true) ~= nil
       and string.find(t, "each second", 1, true) ~= nil;

    local noMitsMinute = string.find(t, "thy dps was", 1, true) ~= nil
       and string.find(t, "per second", 1, true) ~= nil;

    return snowmanMinute or wargMinute or noMitsMinute;
end

local function IsFinalLine(text)
    local t = LowerClean(text);

    -- intentionally loose because the live lines have odd/old-English spelling and may differ slightly
    local snowmanFinal = string.find(t, "tempestuous rate", 1, true) ~= nil
       and string.find(t, "snowflakes", 1, true) ~= nil
       and (string.find(t, "span", 1, true) ~= nil or string.find(t, "moment", 1, true) ~= nil);

    local wargFinal = string.find(t, "grrrrr", 1, true) ~= nil
       and string.find(t, "total of", 1, true) ~= nil
       and string.find(t, "damage each second", 1, true) ~= nil
       and string.find(t, "course of our battle", 1, true) ~= nil;

    local noMitsFinal = string.find(t, "maintain a dps", 1, true) ~= nil
       and string.find(t, "last three minutes", 1, true) ~= nil
       and string.find(t, "momentous conflict", 1, true) ~= nil;

    return snowmanFinal or wargFinal or noMitsFinal;
end

local function IsTotalDamageLine(text)
    local t = LowerClean(text);

    local snowmanTotal = string.find(t, "have lost", 1, true) ~= nil
       and string.find(t, "snowflakes", 1, true) ~= nil
       and string.find(t, "to your blows", 1, true) ~= nil;

    local wargTotal = string.find(t, "awooo", 1, true) ~= nil
       and string.find(t, "enough", 1, true) ~= nil
       and string.find(t, "struck me for", 1, true) ~= nil
       and string.find(t, "damage", 1, true) ~= nil
       and string.find(t, "each second", 1, true) == nil;

    local noMitsTotal = string.find(t, "entirety of our match", 1, true) ~= nil
       and string.find(t, "suffered", 1, true) ~= nil
       and string.find(t, "damage", 1, true) ~= nil;

    return snowmanTotal or wargTotal or noMitsTotal;
end

local function GetDummyKeyFromText(text)
    local t = LowerClean(text);
    if string.find(t, "training snowman", 1, true) ~= nil
        or string.find(t, "merry yule", 1, true) ~= nil then
        return "snowman";
    end
    if string.find(t, "dummy warg", 1, true) ~= nil
        or string.find(t, "ummy warg", 1, true) ~= nil
        or string.find(t, "grargh", 1, true) ~= nil then
        return "warg";
    end
    if string.find(t, "dps target dummy", 1, true) ~= nil
        or string.find(t, "en guarde", 1, true) ~= nil
        or string.find(t, "training-dummy", 1, true) ~= nil
        or string.find(t, "training dummy", 1, true) ~= nil
        or string.find(t, "light dummy", 1, true) ~= nil
        or string.find(t, "medium dummy", 1, true) ~= nil
        or string.find(t, "heavy dummy", 1, true) ~= nil then
        return "regular";
    end
    return "regular";
end

local function NowText()
    local d = Turbine.Engine.GetDate();
    if d ~= nil and d.Month ~= nil then
        return string.format("%04d-%02d-%02d %02d:%02d", d.Year, d.Month, d.Day, d.Hour, d.Minute);
    end
    return tostring(os.time());
end

local function ScoreboardNow()
    local ok, value = pcall(function()
        return os.time();
    end);
    if ok and tonumber(value) ~= nil then
        return tonumber(value);
    end

    local okDate, date = pcall(function()
        return Turbine.Engine.GetDate();
    end);
    if okDate and date ~= nil and tonumber(date.Year) ~= nil then
        local year = tonumber(date.Year) or 0;
        local month = tonumber(date.Month) or 1;
        local day = tonumber(date.Day) or 1;
        local hour = tonumber(date.Hour) or 0;
        local minute = tonumber(date.Minute) or 0;
        return (((((year * 12 + month) * 31 + day) * 24 + hour) * 60 + minute) * 60);
    end

    return Round(Turbine.Engine.GetGameTime() or 0);
end

function ParseGraph.GetDummyParsePauseDateKey()
    local ok, date = pcall(function()
        return Turbine.Engine.GetDate();
    end);
    if ok and date ~= nil and tonumber(date.Year) ~= nil then
        return string.format("%04d-%02d-%02d", tonumber(date.Year) or 0, tonumber(date.Month) or 1, tonumber(date.Day) or 1);
    end
    return string.sub(NowText(), 1, 10);
end

function ParseGraph.ClearDummyParsePauseState(saveNow)
    ParseGraph.DummyParsePauseMode = nil;
    ParseGraph.DummyParsePauseUntil = nil;
    ParseGraph.DummyParsePauseDate = nil;
    if type(ParseGraph.AccountData) == "table" then
        ParseGraph.AccountData.dummyParsePauseMode = nil;
        ParseGraph.AccountData.dummyParsePauseUntil = nil;
        ParseGraph.AccountData.dummyParsePauseDate = nil;
        if saveNow == true and ParseGraph.SaveAccountData ~= nil then
            ParseGraph.SaveAccountData();
        end
    end
end

function ParseGraph.IsDummyParsingPaused()
    local mode = tostring(ParseGraph.DummyParsePauseMode or "");
    if mode == "manual" then
        return true;
    elseif mode == "today" then
        if tostring(ParseGraph.DummyParsePauseDate or "") == ParseGraph.GetDummyParsePauseDateKey() then
            return true;
        end
    elseif mode == "30m" or mode == "1h" then
        local pauseUntil = tonumber(ParseGraph.DummyParsePauseUntil);
        if pauseUntil ~= nil and ScoreboardNow() < pauseUntil then
            return true;
        end
    else
        return false;
    end

    ParseGraph.ClearDummyParsePauseState(true);
    return false;
end

function ParseGraph.CancelDummyParseForPause()
    local hadActiveParse = ParseGraph.ActiveParse ~= nil;
    ParseGraph.ActiveParse = nil;
    ParseGraph.LastDummyHitTime = 0;
    ParseGraph.PendingCombatDummyStartTime = 0;
    ParseGraph.StopPreParseCombatCapture();
    ParseGraph.PendingStartTime = 0;
    ParseGraph.StopStartConfirmTimer();
    ParseGraph.StopCombatDummyParseTimer();
    ParseGraph.ShowWindowAfterParse(false, false);
    ParseGraph.UpdateStopButton();
    ParseGraph.UpdatePostButtonWindowPositions();
    ParseGraph.SetLauncherButtonState();
    return hadActiveParse;
end

function ParseGraph.ResumeDummyParsing(announce)
    local wasPaused = ParseGraph.IsDummyParsingPaused();
    ParseGraph.ClearDummyParsePauseState(true);
    if wasPaused and announce ~= false then
        ParseGraph.PrintParseMessage({
            { text = " Dummy parsing resumed.", color = "FFFFFF" }
        });
    end
    return wasPaused;
end

function ParseGraph.SetDummyParsePause(mode)
    mode = tostring(mode or "");
    if mode ~= "30m" and mode ~= "1h" and mode ~= "today" and mode ~= "manual" then
        return false;
    end
    if ParseGraph.IsDummyParsingPaused() then
        return ParseGraph.ResumeDummyParsing(true);
    end

    ParseGraph.DummyParsePauseMode = mode;
    ParseGraph.DummyParsePauseUntil = nil;
    ParseGraph.DummyParsePauseDate = nil;
    local durationText = "until you resume";
    if mode == "30m" then
        ParseGraph.DummyParsePauseUntil = ScoreboardNow() + 1800;
        durationText = "for 30 minutes";
    elseif mode == "1h" then
        ParseGraph.DummyParsePauseUntil = ScoreboardNow() + 3600;
        durationText = "for 1 hour";
    elseif mode == "today" then
        ParseGraph.DummyParsePauseDate = ParseGraph.GetDummyParsePauseDateKey();
        durationText = "for today";
    end

    if type(ParseGraph.AccountData) == "table" then
        ParseGraph.AccountData.dummyParsePauseMode = ParseGraph.DummyParsePauseMode;
        ParseGraph.AccountData.dummyParsePauseUntil = ParseGraph.DummyParsePauseUntil;
        ParseGraph.AccountData.dummyParsePauseDate = ParseGraph.DummyParsePauseDate;
        ParseGraph.SaveAccountData();
    end

    local cancelledActiveParse = ParseGraph.CancelDummyParseForPause();
    ParseGraph.PrintParseMessage({
        { text = " Dummy parses temporarily paused " .. durationText .. ".", color = "FF5555" },
        { text = " New dummy parses will be ignored.", color = "FFFFFF" },
        { text = cancelledActiveParse and " The running dummy parse was cancelled." or "", color = "FFFFFF" }
    });
    return true;
end

function ParseGraph.GetScoreboardBoardKey(instanceKey, tierKey, bossIndex)
    return tostring(instanceKey or "") .. "|" .. tostring(tierKey or "") .. "|" .. tostring(bossIndex or "");
end

function ParseGraph.CalculateScoreboardPercentForAmount(amount, instanceKey, tierKey, bossIndex)
    amount = tonumber(amount);
    if amount == nil or amount <= 0 or instanceKey == nil or tierKey == nil or bossIndex == nil then
        return nil;
    end

    local health = ParseGraph.GetInstanceBossHealth(instanceKey, tierKey, bossIndex);
    health = tonumber(health);
    if health == nil or health <= 0 then
        return nil;
    end

    return (amount / health) * 100;
end

function StripLeadingChatTimestamp(text)
    text = TrimText(text);
    local bracketText = string.match(text, "^%[([^%]]+)%]%s+");
    if bracketText ~= nil and (string.find(bracketText, "%d+/%d+") ~= nil or string.find(bracketText, "%d+:%d+") ~= nil) then
        local closeAt = string.find(text, "]", 1, true);
        if closeAt ~= nil then
            text = TrimText(string.sub(text, closeAt + 1));
        end
    end
    return text;
end
function ParseGraph.ResetFallbackScoreboardEncounter()
    ParseGraph.FallbackScoreboardEncounterName = nil;
    ParseGraph.FallbackScoreboardEncounterKey = nil;
    ParseGraph.FallbackScoreboardEncounterTime = nil;
end

function ParseGraph.GetFallbackScoreboardEncounterKey(name)
    local cleaned = LowerClean(name);
    cleaned = string.gsub(cleaned, "[^%w]+", "_");
    cleaned = string.gsub(cleaned, "^_+", "");
    cleaned = string.gsub(cleaned, "_+$", "");
    if cleaned == "" then
        cleaned = "encounter";
    end
    return "fallback_" .. cleaned;
end

function ParseGraph.ExtractFallbackScoreboardMobFromCombatLine(text)
    local line = TrimText(StripLeadingChatTimestamp(StripLotroMarkup(text or "")));
    if line == "" then
        return nil;
    end

    local initiatorName, hitInfo, skillInfo, targetInfo = string.match(line, "^(.-) scored a (.-)hit(.-) on (.*)%.$");
    if initiatorName ~= nil and targetInfo ~= nil then
        local targetName = string.match(targetInfo, "^(.-) for [%d,]+%.?%d* .-damage to .*$");
        if targetName ~= nil then
            local initiator = TrimText(string.gsub(initiatorName, "^[Tt]he ", ""));
            local target = TrimText(string.gsub(targetName, "^[Tt]he ", ""));
            local playerLower = ParseGraph.GetPlayerNameLower();
            local initiatorLower = LowerClean(initiator);
            local targetLower = LowerClean(target);

            if initiatorLower == "you" or (playerLower ~= "" and initiatorLower == playerLower) then
                return target;
            end
            if targetLower == "you" or (playerLower ~= "" and targetLower == playerLower) then
                return initiator;
            end
        end
    end

    local reflectTarget = string.match(line, "^.- reflected [%d,]+%.?%d* .- damage to the Morale of (.-)%.$");
    if reflectTarget ~= nil then
        return TrimText(string.gsub(reflectTarget, "^[Tt]he ", ""));
    end

    return nil;
end

function ParseGraph.ObserveFallbackScoreboardEncounter(text)
    if ParseGraph.FallbackScoreboardEncounterName ~= nil then
        return false;
    end

    local mob = ParseGraph.ExtractFallbackScoreboardMobFromCombatLine(text);
    if mob == nil or mob == "" then
        return false;
    end
    if GetDummyTargetPosition(mob) ~= nil then
        return false;
    end

    local mobLower = LowerClean(mob);
    if mobLower == "" or mobLower == ParseGraph.GetPlayerNameLower() then
        return false;
    end

    ParseGraph.FallbackScoreboardEncounterName = mob;
    ParseGraph.FallbackScoreboardEncounterKey = ParseGraph.GetFallbackScoreboardEncounterKey(mob);
    ParseGraph.FallbackScoreboardEncounterTime = Turbine.Engine.GetGameTime();
    return true;
end

function ParseGraph.TryAddFallbackScoreboardEntry(combatData)
    if type(combatData) ~= "table" or tostring(combatData.metric or "") ~= "damage" then
        return false;
    end
    if ParseGraph.ActiveInstanceKey ~= nil or ParseGraph.ManualInstanceTarget ~= nil then
        return false;
    end

    local amount = tonumber(combatData.amount or combatData.damage);
    local rate = tonumber(combatData.rate or combatData.dps);
    if amount == nil or amount <= 0 or rate == nil or rate <= 0 then
        return false;
    end

    local encounterName = TrimText(ParseGraph.FallbackScoreboardEncounterName or combatData.target or combatData.encounter or "");
    if encounterName == "" then
        return false;
    end
    if GetDummyTargetPosition(encounterName) ~= nil then
        return false;
    end

    local instanceKey = ParseGraph.FallbackScoreboardEncounterKey or ParseGraph.GetFallbackScoreboardEncounterKey(encounterName);
    local bossIndex = 1;
    local character = TrimText(combatData.character);
    if character == "" then
        character = ParseGraph.GetCurrentCharacterName();
    end

    local duplicateKey = "fallback|" .. LowerClean(character) .. "|" .. tostring(instanceKey) .. "|" .. tostring(Round(amount)) .. "|" .. LowerClean(combatData.duration) .. "|" .. tostring(Round(rate));
    if ParseGraph.BossHealthPercentMessageWasRecent(duplicateKey) then
        return true;
    end

    local boss = { name = encounterName, contextName = encounterName };
    local added = ParseGraph.AddScoreboardEntry(combatData, character, amount, nil, instanceKey, nil, bossIndex, boss);
    if added == true then
        local boardKey = ParseGraph.GetScoreboardBoardKey(instanceKey, nil, bossIndex);
        local board = ParseGraph.ScoreboardBoards and ParseGraph.ScoreboardBoards[boardKey] or nil;
        if type(board) == "table" then
            board.instanceName = "Unsupported encounter";
            board.isFallbackEncounter = true;
            board.fallbackEncounterName = encounterName;
            ParseGraph.AccountData.scoreboards = ParseGraph.ScoreboardBoards;
            ParseGraph.SaveAccountData();
            if ParseGraph.CurrentView == "scoreboard" and ParseGraph.DrawScoreboardView ~= nil then
                ParseGraph.DrawScoreboardView();
            end
        end
    end
    return added;
end

function ParseGraph.RecalculateScoreboardEntryPercent(entry, instanceKey, tierKey, bossIndex)
    if type(entry) ~= "table" then
        return;
    end

    entry.instanceKey = instanceKey or entry.instanceKey;
    entry.tierKey = tierKey or entry.tierKey;
    entry.bossIndex = bossIndex or entry.bossIndex;

    local health = nil;
    if entry.instanceKey ~= nil and entry.tierKey ~= nil and entry.bossIndex ~= nil then
        health = tonumber(ParseGraph.GetInstanceBossHealth(entry.instanceKey, entry.tierKey, entry.bossIndex));
    end
    if health == nil or health <= 0 then
        return;
    end

    local totalDamage = tonumber(entry.totalDamage) or 0;
    local posts = math.max(1, tonumber(entry.posts) or 1);
    if totalDamage > 0 then
        entry.percentTotal = (totalDamage / health) * 100;
        entry.percentPosts = posts;
    end

    local lastAmount = tonumber(entry.lastAmount);
    if lastAmount ~= nil and lastAmount > 0 then
        entry.lastPercent = (lastAmount / health) * 100;
    end
end

function ParseGraph.RecalculateScoreboardBoardPercents(board)
    if type(board) ~= "table" or type(board.entries) ~= "table" then
        return;
    end

    for _, entry in pairs(board.entries) do
        ParseGraph.RecalculateScoreboardEntryPercent(entry, board.instanceKey, board.tierKey, board.bossIndex);
    end
end

function ParseGraph.ApplyScoreboardTierToBoard(board, tierKey)
    if type(board) ~= "table" or tierKey == nil then
        return;
    end

    board.tierKey = tierKey;
    ParseGraph.RecalculateScoreboardBoardPercents(board);
end

function ParseGraph.ApplyScoreboardTierSelection(tierKey)
    if tierKey == nil then
        return;
    end

    local boards = ParseGraph.ScoreboardBoards;
    if type(boards) ~= "table" then
        return;
    end

    if ParseGraph.ScoreboardSelectedKey == "__overall" then
        for _, board in pairs(boards) do
            if type(board) == "table" and (board.tierKey == nil or tostring(board.tierKey) == "") then
                ParseGraph.ApplyScoreboardTierToBoard(board, tierKey);
            end
        end
    else
        ParseGraph.ApplyScoreboardTierToBoard(boards[ParseGraph.ScoreboardSelectedKey], tierKey);
    end

    if type(ParseGraph.AccountData) == "table" then
        ParseGraph.AccountData.scoreboards = boards;
    end
    ParseGraph.SaveAccountData();
    ParseGraph.DrawScoreboardView();
end

function ParseGraph.BuildScoreboardTierItems()
    local items = {};
    local selectedTier = nil;
    local boards = ParseGraph.ScoreboardBoards;
    if type(boards) == "table" and ParseGraph.ScoreboardSelectedKey ~= "__overall" and type(boards[ParseGraph.ScoreboardSelectedKey]) == "table" then
        selectedTier = boards[ParseGraph.ScoreboardSelectedKey].tierKey;
    end

    for i = 1, #(ParseGraph.InstanceTiers or {}) do
        local tier = ParseGraph.InstanceTiers[i];
        local tierKey = tier.key;
        table.insert(items, {
            text = tostring(tier.label or tier.key),
            selected = tierKey == selectedTier,
            onClick = function()
                ParseGraph.HideLauncherContextMenu();
                ParseGraph.ApplyScoreboardTierSelection(tierKey);
            end
        });
    end

    return items;
end

function ParseGraph.PruneScoreboardBoards()
    local boards = ParseGraph.ScoreboardBoards;
    if type(boards) ~= "table" and type(ParseGraph.AccountData) == "table" then
        boards = ParseGraph.AccountData.scoreboards;
    end
    if type(boards) ~= "table" then
        boards = {};
    end

    local now = ScoreboardNow();
    local expiresAfter = tonumber(ParseGraph.ScoreboardPersistenceSeconds) or 14400;
    for key, board in pairs(boards) do
        local updatedAt = type(board) == "table" and tonumber(board.updatedAt) or nil;
        local age = nil;
        if updatedAt ~= nil then
            age = now - updatedAt;
        end
        if updatedAt == nil or age == nil or age > expiresAfter or age < (0 - expiresAfter) then
            boards[key] = nil;
            if ParseGraph.ScoreboardSelectedKey == key then
                ParseGraph.ScoreboardSelectedKey = nil;
            end
        elseif type(board) == "table" then
            local instanceKey = tostring(board.instanceKey or "");
            local bossIndex = tonumber(board.bossIndex);
            local instance = nil;
            if ParseGraph.GetInstanceDefinition ~= nil and instanceKey ~= "" then
                instance = ParseGraph.GetInstanceDefinition(instanceKey);
                if instance ~= nil and instance.key ~= instanceKey then
                    instance = nil;
                end
            end

            if instance ~= nil then
                board.instanceName = tostring(instance.name or board.instanceName or "");
                local boss = type(instance.bosses) == "table" and instance.bosses[bossIndex] or nil;
                if type(boss) == "table" then
                    local bossName = TrimText(boss.contextName or boss.name);
                    if bossName ~= "" then
                        board.bossName = bossName;
                    end
                end
            end
            ParseGraph.RecalculateScoreboardBoardPercents(board);
        end
    end

    ParseGraph.ScoreboardBoards = boards;
    if type(ParseGraph.AccountData) == "table" then
        ParseGraph.AccountData.scoreboards = boards;
    end
end

function ParseGraph.AddScoreboardEntry(combatData, characterName, amount, percentValue, instanceKey, tierKey, bossIndex, boss)
    if type(combatData) ~= "table" or tostring(combatData.metric or "") ~= "damage" then
        return false;
    end

    amount = tonumber(amount or combatData.amount or combatData.damage);
    local rate = tonumber(combatData.rate or combatData.dps);
    if amount == nil or amount <= 0 or rate == nil or rate <= 0 then
        return false;
    end

    ParseGraph.PruneScoreboardBoards();

    local boardKey = ParseGraph.GetScoreboardBoardKey(instanceKey, tierKey, bossIndex);
    if boardKey == "||" then
        return false;
    end

    local character = TrimText(characterName or combatData.character);
    if character == "" then
        character = "Someone";
    end
    if not ParseGraph.IsScoreboardPlayerName(character) then
        return false;
    end
    local characterKey = ParseGraph.GetScoreboardEntryKey(character);
    if characterKey == "" then
        characterKey = "someone";
    end
    if ParseGraph.IsScoreboardEntryHidden(characterKey) or ParseGraph.IsScoreboardEntryHidden(character) then
        return false;
    end

    local instance = ParseGraph.GetInstanceDefinition(instanceKey);
    if instance ~= nil and instance.key ~= instanceKey then
        instance = nil;
    end
    local bossName = "";
    if type(boss) == "table" then
        bossName = TrimText(boss.contextName or boss.name);
    end
    if bossName == "" and instance ~= nil and type(instance.bosses) == "table" and type(instance.bosses[bossIndex]) == "table" then
        bossName = TrimText(instance.bosses[bossIndex].contextName or instance.bosses[bossIndex].name);
    end
    if bossName == "" then
        bossName = "Boss " .. tostring(bossIndex or "?");
    end

    local now = ScoreboardNow();
    local boards = ParseGraph.ScoreboardBoards;
    if type(boards) ~= "table" then
        boards = {};
        ParseGraph.ScoreboardBoards = boards;
    end

    local board = boards[boardKey];
    if type(board) ~= "table" then
        board = {
            key = boardKey,
            instanceKey = instanceKey,
            tierKey = tierKey,
            bossIndex = bossIndex,
            bossName = bossName,
            instanceName = instance ~= nil and instance.name or "",
            updatedAt = now,
            entries = {}
        };
        boards[boardKey] = board;
    end

    if tierKey == nil and board.tierKey ~= nil and tostring(board.tierKey) ~= "" then
        tierKey = board.tierKey;
    end

    board.instanceKey = instanceKey;
    board.tierKey = tierKey or board.tierKey;
    board.bossIndex = bossIndex;
    board.bossName = bossName;
    board.instanceName = instance ~= nil and instance.name or board.instanceName or "";
    board.updatedAt = now;
    if type(board.entries) ~= "table" then
        board.entries = {};
    end

    local entry = board.entries[characterKey];
    if type(entry) ~= "table" then
        entry = { character = character, totalDamage = 0, rateTotal = 0, highestRate = 0, posts = 0, percentTotal = 0, percentPosts = 0, deaths = 0 };
        board.entries[characterKey] = entry;
    end

    if type(board.pendingDeaths) == "table" then
        local pendingDeath = board.pendingDeaths[characterKey];
        if type(pendingDeath) == "table" then
            entry.deaths = (tonumber(entry.deaths) or 0) + (tonumber(pendingDeath.deaths) or 0);
            board.pendingDeaths[characterKey] = nil;
        end
    end

    entry.character = character;
    local classInfo = ParseGraph.GetKnownCharacterClassInfo(character);
    if classInfo ~= nil then
        entry.classKey = classInfo.key;
        entry.className = classInfo.name;
        entry.classIcon = classInfo.icon;
    end
    entry.instanceKey = instanceKey;
    entry.tierKey = tierKey;
    entry.bossIndex = bossIndex;
    entry.deaths = tonumber(entry.deaths) or 0;
    entry.totalDamage = (tonumber(entry.totalDamage) or 0) + amount;
    entry.rateTotal = (tonumber(entry.rateTotal) or 0) + rate;
    entry.highestRate = math.max(tonumber(entry.highestRate) or 0, rate);
    entry.posts = (tonumber(entry.posts) or 0) + 1;
    entry.lastRate = rate;
    entry.lastAmount = amount;
    local percentNumber = tonumber(percentValue) or ParseGraph.CalculateScoreboardPercentForAmount(amount, instanceKey, tierKey, bossIndex);
    if percentNumber ~= nil then
        entry.percentTotal = (tonumber(entry.percentTotal) or 0) + percentNumber;
        entry.percentPosts = (tonumber(entry.percentPosts) or 0) + 1;
        entry.lastPercent = percentNumber;
    end
    entry.updatedAt = now;

    ParseGraph.AccountData.scoreboards = boards;
    if ParseGraph.ScoreboardSelectedKey == nil or boards[ParseGraph.ScoreboardSelectedKey] == nil then
        ParseGraph.ScoreboardSelectedKey = boardKey;
    end

    ParseGraph.SaveAccountData();
    if ParseGraph.CurrentView == "scoreboard" and ParseGraph.DrawScoreboardView ~= nil then
        ParseGraph.DrawScoreboardView();
    end
    return true;
end

function ParseGraph.GetActiveScoreboardDeathTarget()
    local instanceKey = ParseGraph.ActiveInstanceKey;
    local tierKey = ParseGraph.ActiveInstanceTierKey;
    if instanceKey == nil then
        return nil, nil, nil, nil;
    end

    local bossIndex = ParseGraph.GetAutoInstanceBossIndex(instanceKey, tierKey);
    if bossIndex == nil then
        return nil, nil, nil, nil;
    end

    local instance = ParseGraph.GetInstanceDefinition(instanceKey);
    if instance == nil then
        return nil, nil, nil, nil;
    end

    local boss = instance.bosses and instance.bosses[bossIndex] or {};
    return instanceKey, tierKey, bossIndex, boss;
end

function ParseGraph.EnsureScoreboardBoardForDeath(instanceKey, tierKey, bossIndex, boss)
    ParseGraph.PruneScoreboardBoards();

    local boardKey = ParseGraph.GetScoreboardBoardKey(instanceKey, tierKey, bossIndex);
    if boardKey == "||" then
        return nil, nil;
    end

    local instance = ParseGraph.GetInstanceDefinition(instanceKey);
    if instance ~= nil and instance.key ~= instanceKey then
        instance = nil;
    end
    local bossName = "";
    if type(boss) == "table" then
        bossName = TrimText(boss.contextName or boss.name);
    end
    if bossName == "" and instance ~= nil and type(instance.bosses) == "table" and type(instance.bosses[bossIndex]) == "table" then
        bossName = TrimText(instance.bosses[bossIndex].contextName or instance.bosses[bossIndex].name);
    end
    if bossName == "" then
        bossName = "Boss " .. tostring(bossIndex or "?");
    end

    local now = ScoreboardNow();
    local boards = ParseGraph.ScoreboardBoards;
    if type(boards) ~= "table" then
        boards = {};
        ParseGraph.ScoreboardBoards = boards;
    end

    local board = boards[boardKey];
    if type(board) ~= "table" then
        board = {
            key = boardKey,
            instanceKey = instanceKey,
            tierKey = tierKey,
            bossIndex = bossIndex,
            bossName = bossName,
            instanceName = instance ~= nil and instance.name or "",
            updatedAt = now,
            entries = {},
            pendingDeaths = {}
        };
        boards[boardKey] = board;
    end

    board.instanceKey = instanceKey;
    board.tierKey = tierKey;
    board.bossIndex = bossIndex;
    board.bossName = bossName;
    board.instanceName = instance ~= nil and instance.name or board.instanceName or "";
    board.updatedAt = now;
    if type(board.entries) ~= "table" then
        board.entries = {};
    end
    if type(board.pendingDeaths) ~= "table" then
        board.pendingDeaths = {};
    end

    ParseGraph.ScoreboardBoards = boards;
    ParseGraph.AccountData.scoreboards = boards;
    if ParseGraph.ScoreboardSelectedKey == nil or boards[ParseGraph.ScoreboardSelectedKey] == nil then
        ParseGraph.ScoreboardSelectedKey = boardKey;
    end
    return board, boardKey;
end

function ParseGraph.IsScoreboardPlayerName(characterName)
    local character = TrimText(characterName);
    if character == "" or string.find(character, "%s") ~= nil then
        return false;
    end
    if string.find(character, "^[A-Za-z]+$") == nil then
        return false;
    end
    if ParseGraph.HasScoreboardDisallowedNameCharacter(character) then
        return false;
    end
    return string.find(string.sub(character, 2), "%u") == nil;
end

function ParseGraph.HasScoreboardDisallowedNameCharacter(characterName)
    local character = tostring(characterName or "");
    local blocked = ParseGraph.ScoreboardDisallowedNameCharacters;
    if type(blocked) ~= "table" then
        return false;
    end
    for i = 1, #blocked do
        local value = tostring(blocked[i] or "");
        if value ~= "" and string.find(character, value, 1, true) ~= nil then
            return true;
        end
    end
    return false;
end

function ParseGraph.GetScoreboardEntryKey(characterName)
    return LowerClean(TrimText(characterName));
end

function ParseGraph.GetScoreboardHiddenEntries()
    if type(ParseGraph.ScoreboardHiddenEntries) ~= "table" then
        if type(ParseGraph.AccountData) == "table" and type(ParseGraph.AccountData.scoreboardHidden) == "table" then
            ParseGraph.ScoreboardHiddenEntries = ParseGraph.AccountData.scoreboardHidden;
        else
            ParseGraph.ScoreboardHiddenEntries = {};
        end
    end

    if type(ParseGraph.AccountData) == "table" then
        ParseGraph.AccountData.scoreboardHidden = ParseGraph.ScoreboardHiddenEntries;
    end

    return ParseGraph.ScoreboardHiddenEntries;
end

function ParseGraph.GetScoreboardEntryNameByKey(entryKey)
    local key = tostring(entryKey or "");
    local boards = ParseGraph.ScoreboardBoards;
    if key == "" or type(boards) ~= "table" then
        return key;
    end

    for _, board in pairs(boards) do
        if type(board) == "table" and type(board.entries) == "table" then
            local entry = board.entries[key];
            if type(entry) == "table" and TrimText(entry.character) ~= "" then
                return TrimText(entry.character);
            end
        end
    end

    for _, board in pairs(boards) do
        if type(board) == "table" and type(board.entries) == "table" then
            for _, entry in pairs(board.entries) do
                if type(entry) == "table" and ParseGraph.GetScoreboardEntryKey(entry.character) == key and TrimText(entry.character) ~= "" then
                    return TrimText(entry.character);
                end
            end
        end
    end

    return key;
end

function ParseGraph.IsScoreboardEntryHidden(entryOrName)
    if type(entryOrName) == "table" then
        entryOrName = entryOrName.character;
    end

    local rawKey = tostring(entryOrName or "");
    local cleanKey = ParseGraph.GetScoreboardEntryKey(rawKey);
    local hidden = ParseGraph.GetScoreboardHiddenEntries();
    return (rawKey ~= "" and hidden[rawKey] ~= nil) or (cleanKey ~= "" and hidden[cleanKey] ~= nil);
end

function ParseGraph.GetScoreboardHiddenList()
    local list = {};
    local hidden = ParseGraph.GetScoreboardHiddenEntries();
    for key, item in pairs(hidden) do
        local name = tostring(key or "");
        local hiddenAt = 0;
        if type(item) == "table" then
            name = TrimText(item.name or item.character or name);
            hiddenAt = tonumber(item.hiddenAt) or 0;
        elseif type(item) == "string" and TrimText(item) ~= "" then
            name = TrimText(item);
        end
        if name == "" then
            name = tostring(key or "");
        end
        list[#list + 1] = { key = tostring(key or ""), name = name, hiddenAt = hiddenAt };
    end

    table.sort(list, function(a, b)
        local an = string.lower(tostring(a.name or ""));
        local bn = string.lower(tostring(b.name or ""));
        if an == bn then
            return tostring(a.key or "") < tostring(b.key or "");
        end
        return an < bn;
    end);

    return list;
end

function ParseGraph.HideScoreboardEntry(boardKey, entryKey)
    entryKey = tostring(entryKey or "");
    if entryKey == "" then
        return false;
    end

    local hidden = ParseGraph.GetScoreboardHiddenEntries();
    local name = ParseGraph.GetScoreboardEntryNameByKey(entryKey);
    if TrimText(name) == "" then
        name = entryKey;
    end
    hidden[entryKey] = { key = entryKey, name = name, hiddenAt = ScoreboardNow() };

    local boards = ParseGraph.ScoreboardBoards;
    if type(boards) == "table" then
        for _, board in pairs(boards) do
            if type(board) == "table" and type(board.pendingDeaths) == "table" then
                board.pendingDeaths[entryKey] = nil;
            end
        end
    end

    if type(ParseGraph.AccountData) == "table" then
        ParseGraph.AccountData.scoreboards = ParseGraph.ScoreboardBoards;
        ParseGraph.AccountData.scoreboardHidden = hidden;
        ParseGraph.SaveAccountData();
    end
    if ParseGraph.DrawScoreboardView ~= nil then
        ParseGraph.DrawScoreboardView();
    end
    return true;
end

function ParseGraph.UnhideScoreboardEntry(entryKey)
    entryKey = tostring(entryKey or "");
    if entryKey == "" then
        return false;
    end

    local hidden = ParseGraph.GetScoreboardHiddenEntries();
    if hidden[entryKey] == nil then
        return false;
    end

    hidden[entryKey] = nil;
    if type(ParseGraph.AccountData) == "table" then
        ParseGraph.AccountData.scoreboardHidden = hidden;
        ParseGraph.SaveAccountData();
    end
    if ParseGraph.DrawScoreboardView ~= nil then
        ParseGraph.DrawScoreboardView();
    end
    return true;
end

function ParseGraph.AddScoreboardDeath(characterName, createEntry)
    local character = TrimText(characterName);
    if not ParseGraph.IsScoreboardPlayerName(character) then
        return false;
    end
    if ParseGraph.IsScoreboardEntryHidden(character) then
        return false;
    end

    local instanceKey, tierKey, bossIndex, boss = ParseGraph.GetActiveScoreboardDeathTarget();
    if instanceKey == nil or tierKey == nil or bossIndex == nil then
        return false;
    end

    local board = ParseGraph.EnsureScoreboardBoardForDeath(instanceKey, tierKey, bossIndex, boss);
    if type(board) ~= "table" then
        return false;
    end

    local characterKey = ParseGraph.GetScoreboardEntryKey(character);
    if characterKey == "" then
        return false;
    end

    local now = ScoreboardNow();
    local entry = board.entries[characterKey];
    if type(entry) == "table" then
        entry.character = character;
        entry.deaths = (tonumber(entry.deaths) or 0) + 1;
        entry.updatedAt = now;
    elseif createEntry == true then
        board.entries[characterKey] = {
            character = character,
            totalDamage = 0,
            rateTotal = 0,
            highestRate = 0,
            posts = 0,
            deaths = 1,
            updatedAt = now
        };
    else
        local pending = board.pendingDeaths[characterKey];
        if type(pending) ~= "table" then
            pending = { character = character, deaths = 0 };
            board.pendingDeaths[characterKey] = pending;
        end
        pending.character = character;
        pending.deaths = (tonumber(pending.deaths) or 0) + 1;
        pending.updatedAt = now;
    end

    board.updatedAt = now;
    ParseGraph.AccountData.scoreboards = ParseGraph.ScoreboardBoards;
    ParseGraph.SaveAccountData();
    if ParseGraph.CurrentView == "scoreboard" and ParseGraph.DrawScoreboardView ~= nil then
        ParseGraph.DrawScoreboardView();
    end
    return true;
end

function ParseGraph.ExtractScoreboardDeathVictimName(text)
    local line = TrimText(StripLotroMarkup(text));
    local bracketText = string.match(line, "^%[([^%]]+)%]%s+");
    if bracketText ~= nil and (string.find(bracketText, "%d+/%d+") ~= nil or string.find(bracketText, "%d+:%d+") ~= nil) then
        local closeAt = string.find(line, "]", 1, true);
        if closeAt ~= nil then
            line = TrimText(string.sub(line, closeAt + 1));
        end
    end
    if line == "" then
        return nil, false;
    end

    local incapacitatingEnemy = string.match(line, "^%s*(.-)%s+incapacitated%s+you%.%s*$");
    if incapacitatingEnemy ~= nil then
        return ParseGraph.GetCurrentCharacterName(), true, TrimText(incapacitatingEnemy);
    end

    local actor, victim = string.match(line, "^%s*(.-)%s+defeated%s+(.+)%.%s*$");
    actor = TrimText(actor);
    victim = TrimText(victim);
    if actor == "" or victim == "" then
        return nil, false;
    end

    if LowerClean(actor) == "your mighty blow" then
        return nil, false;
    end

    local knownInstance, knownBossIndex = ParseGraph.FindAnyInstanceBossForDefeat(victim);
    if knownInstance ~= nil and knownBossIndex ~= nil then
        return nil, false;
    end

    return victim, false, actor;
end

function ParseGraph.FindAnyInstanceBossForDeathSource(enemyName)
    enemyName = TrimText(enemyName);
    if enemyName == "" then
        return nil, nil;
    end

    local instance, bossIndex = ParseGraph.FindAnyInstanceBossForCombatAnalysis({ target = enemyName });
    if instance ~= nil and bossIndex ~= nil then
        return instance, bossIndex;
    end

    instance, bossIndex = ParseGraph.FindAnyInstanceBossForDefeat(enemyName);
    if instance ~= nil and bossIndex ~= nil then
        return instance, bossIndex;
    end

    local enemyKey = NormalizeBossMatchText(enemyName);
    local orderedInstances = ParseGraph.GetOrderedInstanceDefinitions();
    local tiers = ParseGraph.InstanceTiers or {};
    for instanceIndex = 1, #orderedInstances do
        local candidateInstance = orderedInstances[instanceIndex];
        local bosses = candidateInstance and candidateInstance.bosses or nil;
        if candidateInstance ~= nil and type(bosses) == "table" then
            for candidateBossIndex = 1, #bosses do
                for tierIndex = 1, #tiers do
                    local tier = tiers[tierIndex];
                    local requirements = ParseGraph.GetBossDamageTargetRequirements(candidateInstance.key, tier.key, candidateBossIndex, bosses[candidateBossIndex]);
                    for requirementIndex = 1, #requirements do
                        local requirement = requirements[requirementIndex];
                        local requirementKey = tostring(requirement and requirement.key or "");
                        local matches = requirementKey ~= "" and (
                            (requirement.exact == true and enemyKey == requirementKey)
                            or (requirement.exact ~= true and (
                                enemyKey == requirementKey
                                or string.find(enemyKey, requirementKey, 1, true) ~= nil
                                or string.find(requirementKey, enemyKey, 1, true) ~= nil
                            ))
                        );
                        if matches then
                            return candidateInstance, candidateBossIndex;
                        end
                    end
                end
            end
        end
    end

    return nil, nil;
end

function ParseGraph.ApplyInstanceBossDeathDetection(enemyName)
    local instance, bossIndex = ParseGraph.FindAnyInstanceBossForDeathSource(enemyName);
    if instance == nil or bossIndex == nil then
        return false;
    end

    bossIndex = tonumber(bossIndex) or 1;
    local tierKey = nil;
    if ParseGraph.ActiveInstanceKey == instance.key then
        tierKey = ParseGraph.ActiveInstanceTierKey;
    end

    if tierKey ~= nil then
        local targetChanged = ParseGraph.ActiveInstanceKey ~= instance.key
            or ParseGraph.ActiveInstanceTierKey ~= tierKey
            or tonumber(ParseGraph.AutoInstanceBossIndex) ~= bossIndex;
        ParseGraph.ActiveInstanceKey = instance.key;
        ParseGraph.ActiveInstanceTierKey = tierKey;
        ParseGraph.AutoInstanceBossIndex = bossIndex;
        ParseGraph.SelectedInstanceKey = instance.key;
        ParseGraph.SelectedInstanceTierKey = tierKey;
        ParseGraph.SelectedInstanceBossIndex = bossIndex;
        ParseGraph.ManualInstanceTarget = nil;
        if targetChanged and ParseGraph.ResetAutoInstanceBossDefeats ~= nil then
            ParseGraph.ResetAutoInstanceBossDefeats(instance.key, tierKey, bossIndex);
        end
        ParseGraph.ActiveInstanceEncounter = {
            instanceKey = instance.key,
            tierKey = tierKey,
            bossIndex = bossIndex,
            startedAt = Turbine.Engine.GetGameTime() or 0
        };
        ParseGraph.ScoreboardSelectedKey = ParseGraph.GetScoreboardBoardKey(instance.key, tierKey, bossIndex);
        ParseGraph.SetLauncherButtonState();
        if ParseGraph.CurrentView == "instances" and ParseGraph.DrawInstancesView ~= nil then
            ParseGraph.DrawInstancesView();
        end
        return true;
    end

    ParseGraph.ActiveInstanceKey = instance.key;
    ParseGraph.ActiveInstanceTierKey = nil;
    ParseGraph.AutoInstanceBossIndex = bossIndex;
    ParseGraph.SelectedInstanceKey = instance.key;
    ParseGraph.SelectedInstanceBossIndex = bossIndex;
    ParseGraph.ManualInstanceTarget = nil;
    ParseGraph.AutoInstanceDefeats = nil;
    ParseGraph.ActiveInstanceEncounter = nil;
    ParseGraph.SetLauncherButtonState();
    if ParseGraph.CurrentView == "instances" and ParseGraph.DrawInstancesView ~= nil then
        ParseGraph.DrawInstancesView();
    end
    return true;
end

function ParseGraph.ProcessScoreboardDeathText(text)
    local victim, isSelf, enemyName = ParseGraph.ExtractScoreboardDeathVictimName(text);
    if victim == nil then
        return false;
    end

    local activeInstance = ParseGraph.GetInstanceDefinition(ParseGraph.ActiveInstanceKey);
    if activeInstance ~= nil and ParseGraph.InstanceNonBossMatchesCombatAnalysis ~= nil
        and ParseGraph.InstanceNonBossMatchesCombatAnalysis(activeInstance, { target = enemyName }) then
        return false;
    end

    ParseGraph.ApplyInstanceBossDeathDetection(enemyName);
    return ParseGraph.AddScoreboardDeath(victim, true);
end

local function NormalizeShowMode(mode)
    if tostring(mode) == "session" then
        return "session";
    end
    if tostring(mode) == "today" then
        return "today";
    end
    return "all";
end

function ParseGraph.IsFaillowshipAvailable()
    return ParseGraph.FaillowshipJoined == true and tonumber(ParseGraph.FaillowshipCommand) ~= nil;
end

function ParseGraph.IsPostChannelAvailable(channelOrInfo)
    local key = channelOrInfo;
    if type(channelOrInfo) == "table" then
        key = channelOrInfo.key;
    end

    if tostring(key or "") == "faillowship" then
        return ParseGraph.IsFaillowshipAvailable();
    end
    return true;
end

local function NormalizePostChannel(channel)
    channel = tostring(channel or "say");
    for i = 1, #ParseGraph.PostChannels do
        if ParseGraph.PostChannels[i].key == channel and ParseGraph.IsPostChannelAvailable(ParseGraph.PostChannels[i]) then
            return channel;
        end
    end
    return "say";
end

local function NormalizeBoolean(value)
    return value == true or tostring(value) == "true";
end

local function NormalizeLauncherButtonSizeKey(value)
    value = tostring(value or "medium");
    if value == "small" or value == "large" then
        return value;
    end
    return "medium";
end

local function NormalizeLauncherFlyoutDirection(value)
    value = string.lower(tostring(value or "right"));
    if value == "left" then
        return "left";
    end
    return "right";
end

function ParseGraph.NormalizeGroupListMode(value)
    value = string.lower(tostring(value or "custom"));
    if value == "target" or value == "numbers" then
        return value;
    end
    return "custom";
end

local function BuildSaveData(parses, graphMin, showMode, achievements, instances, stats)
    return {
        parses = parses or {},
        graphMin = tonumber(graphMin) or 100000,
        showMode = NormalizeShowMode(showMode),
        achievements = achievements or {},
        instances = instances or {},
        stats = stats or {}
    };
end

local function NormalizeCharacterData(data, key, name)
    local normalized = data;
    if type(normalized) ~= "table" then
        normalized = {};
    end

    if type(normalized.parses) ~= "table" then
        if #normalized > 0 then
            normalized = {
                parses = normalized,
                graphMin = 100000,
                showMode = "all"
            };
        else
            normalized.parses = {};
        end
    end

    normalized.key = key or normalized.key or "current";
    if name ~= nil and tostring(name) ~= "" then
        normalized.name = tostring(name);
    elseif normalized.name == nil or tostring(normalized.name) == "" then
        normalized.name = tostring(normalized.key);
    end
    normalized.graphMin = tonumber(normalized.graphMin) or 100000;
    normalized.showMode = NormalizeShowMode(normalized.showMode);
    normalized.classIcon = NormalizeClassIconPath(normalized.classIcon, normalized.classKey);
    if type(normalized.achievements) ~= "table" then
        normalized.achievements = {};
    end
    if type(normalized.instances) ~= "table" then
        normalized.instances = {};
    end
    if type(normalized.stats) ~= "table" then
        normalized.stats = {};
    end
    normalized.updated = normalized.updated or NowText();
    return normalized;
end

function ParseGraph.GetCurrentCharacterKey()
    if ParseGraph.CurrentCharacterKey == nil then
        ParseGraph.CurrentCharacterName = ParseGraph.GetPlayerName();
        ParseGraph.CurrentCharacterKey = ParseGraph.GetPlayerKey();
    end
    return ParseGraph.CurrentCharacterKey;
end

function ParseGraph.GetCurrentCharacterName()
    if ParseGraph.CurrentCharacterName == nil then
        ParseGraph.CurrentCharacterName = ParseGraph.GetPlayerName();
    end
    return ParseGraph.CurrentCharacterName;
end

function ParseGraph.GetKnownCharacterClassInfo(characterName)
    local key = LowerClean(characterName);
    if key == "" then
        return nil;
    end

    if key == ParseGraph.GetCurrentCharacterKey() then
        local currentInfo = ParseGraph.GetCurrentPlayerClassInfo();
        if currentInfo ~= nil then
            return currentInfo;
        end
    end

    local characters = ParseGraph.AccountData and ParseGraph.AccountData.characters or {};
    local entry = characters[key];
    if type(entry) == "table" then
        entry = NormalizeCharacterData(entry, key, entry.name);
        characters[key] = entry;
        local classKey = ParseGraph.GetCharacterClassKey(entry);
        local icon = NormalizeClassIconPath(entry.classIcon, classKey);
        if icon ~= nil and tostring(icon) ~= "" then
            return {
                key = classKey,
                name = entry.className,
                icon = icon
            };
        end
    end

    return nil;
end

function ParseGraph.LoadAccountData()
    local ok, data = pcall(function()
        return Turbine.PluginData.Load(Turbine.DataScope.Account, ParseGraph.AccountSaveKey);
    end);

    if ok and type(data) == "table" and type(data.characters) == "table" then
        ParseGraph.AccountData = data;
    else
        ParseGraph.AccountData = { characters = {} };
    end

    if type(ParseGraph.AccountData.characters) ~= "table" then
        ParseGraph.AccountData.characters = {};
    end
    if type(ParseGraph.AccountData.achievements) ~= "table" then
        ParseGraph.AccountData.achievements = {};
    end
    if type(ParseGraph.AccountData.importedParses) ~= "table" then
        ParseGraph.AccountData.importedParses = {};
    end
    if type(ParseGraph.AccountData.scoreboards) ~= "table" then
        ParseGraph.AccountData.scoreboards = {};
    end
    if type(ParseGraph.AccountData.scoreboardHidden) ~= "table" then
        ParseGraph.AccountData.scoreboardHidden = {};
    end
    ParseGraph.ScoreboardBoards = ParseGraph.AccountData.scoreboards;
    ParseGraph.ScoreboardHiddenEntries = ParseGraph.AccountData.scoreboardHidden;
    ParseGraph.PruneScoreboardBoards();

    ParseGraph.PostChannel = NormalizePostChannel(ParseGraph.AccountData.postChannel);
    ParseGraph.AccountData.postChannel = ParseGraph.PostChannel;
    if ParseGraph.AccountData.startMinimized == nil then
        ParseGraph.StartMinimized = true;
    else
        ParseGraph.StartMinimized = NormalizeBoolean(ParseGraph.AccountData.startMinimized);
    end
    ParseGraph.AccountData.startMinimized = ParseGraph.StartMinimized;
    if ParseGraph.AccountData.combineSameClass == nil then
        ParseGraph.CombineSameClass = true;
    else
        ParseGraph.CombineSameClass = NormalizeBoolean(ParseGraph.AccountData.combineSameClass);
    end
    ParseGraph.AccountData.combineSameClass = ParseGraph.CombineSameClass;
    if ParseGraph.AccountData.showLauncherButton == nil then
        ParseGraph.ShowLauncherButton = true;
    else
        ParseGraph.ShowLauncherButton = NormalizeBoolean(ParseGraph.AccountData.showLauncherButton);
    end
    ParseGraph.AccountData.showLauncherButton = ParseGraph.ShowLauncherButton;
    if ParseGraph.AccountData.showLauncherTimer == nil then
        ParseGraph.ShowLauncherTimer = false;
    else
        ParseGraph.ShowLauncherTimer = NormalizeBoolean(ParseGraph.AccountData.showLauncherTimer);
    end
    ParseGraph.AccountData.showLauncherTimer = ParseGraph.ShowLauncherTimer;
    local pauseMode = tostring(ParseGraph.AccountData.dummyParsePauseMode or "");
    if pauseMode == "30m" or pauseMode == "1h" or pauseMode == "today" or pauseMode == "manual" then
        ParseGraph.DummyParsePauseMode = pauseMode;
        ParseGraph.DummyParsePauseUntil = tonumber(ParseGraph.AccountData.dummyParsePauseUntil);
        ParseGraph.DummyParsePauseDate = ParseGraph.AccountData.dummyParsePauseDate;
    else
        ParseGraph.ClearDummyParsePauseState(false);
    end
    ParseGraph.LauncherButtonSizeKey = NormalizeLauncherButtonSizeKey(ParseGraph.AccountData.launcherButtonSize);
    ParseGraph.LauncherButtonSize = ParseGraph.LauncherButtonSizes[ParseGraph.LauncherButtonSizeKey] or ParseGraph.LauncherButtonSizes.medium or 42;
    ParseGraph.AccountData.launcherButtonSize = ParseGraph.LauncherButtonSizeKey;
    ParseGraph.LauncherFlyoutDirection = NormalizeLauncherFlyoutDirection(ParseGraph.AccountData.launcherFlyoutDirection);
    ParseGraph.AccountData.launcherFlyoutDirection = ParseGraph.LauncherFlyoutDirection;
    ParseGraph.GroupListSaveEnabled = NormalizeBoolean(ParseGraph.AccountData.groupListSaveEnabled);
    ParseGraph.AccountData.groupListSaveEnabled = ParseGraph.GroupListSaveEnabled;
    if ParseGraph.GroupListSaveEnabled == true then
        ParseGraph.GroupListMode = ParseGraph.NormalizeGroupListMode(ParseGraph.AccountData.groupListMode);
        ParseGraph.AccountData.groupListMode = ParseGraph.GroupListMode;
        if type(ParseGraph.AccountData.groupListTemplateLines) == "table" then
            ParseGraph.GroupListTemplateLines = ParseGraph.AccountData.groupListTemplateLines;
        else
            ParseGraph.GroupListTemplateLines = {};
        end
        if type(ParseGraph.AccountData.groupListTemplateLines) ~= "table" and type(ParseGraph.AccountData.groupListLines) == "table" then
            ParseGraph.GroupListTemplateLines[ParseGraph.GroupListMode] = ParseGraph.AccountData.groupListLines;
        end
        ParseGraph.EnsureGroupListTemplateLines();
        ParseGraph.GroupListLines = ParseGraph.GroupListTemplateLines[ParseGraph.GroupListMode];
        ParseGraph.AccountData.groupListTemplateLines = ParseGraph.CopyGroupListTemplateLinesForSave();
        ParseGraph.AccountData.groupListLines = nil;
    else
        ParseGraph.GroupListMode = "custom";
        ParseGraph.GroupListTemplateLines = {};
        ParseGraph.EnsureGroupListTemplateLines();
        ParseGraph.GroupListLines = ParseGraph.GroupListTemplateLines.custom;
        ParseGraph.AccountData.groupListMode = nil;
        ParseGraph.AccountData.groupListLines = nil;
        ParseGraph.AccountData.groupListTemplateLines = nil;
    end
    if ParseGraph.AccountData.openAfterFinishedParse == nil then
        ParseGraph.OpenAfterFinishedParse = true;
    else
        ParseGraph.OpenAfterFinishedParse = NormalizeBoolean(ParseGraph.AccountData.openAfterFinishedParse);
    end
    ParseGraph.AccountData.openAfterFinishedParse = ParseGraph.OpenAfterFinishedParse;
    if ParseGraph.AccountData.showBossHealthPercentMessages == nil then
        ParseGraph.ShowBossHealthPercentMessages = true;
    else
        ParseGraph.ShowBossHealthPercentMessages = NormalizeBoolean(ParseGraph.AccountData.showBossHealthPercentMessages);
    end
    ParseGraph.AccountData.showBossHealthPercentMessages = ParseGraph.ShowBossHealthPercentMessages;
    if ParseGraph.AccountData.onlySaveInstanceParsesOnKill == nil then
        ParseGraph.OnlySaveInstanceParsesOnKill = false;
    else
        ParseGraph.OnlySaveInstanceParsesOnKill = NormalizeBoolean(ParseGraph.AccountData.onlySaveInstanceParsesOnKill);
    end
    ParseGraph.AccountData.onlySaveInstanceParsesOnKill = ParseGraph.OnlySaveInstanceParsesOnKill;
    ParseGraph.ShowScoreboardRecapMessages = false;
    ParseGraph.AccountData.showScoreboardRecapMessages = false;
    if ParseGraph.AccountData.autoStripOldParseDetails == nil then
        ParseGraph.AutoStripOldParseDetails = false;
    else
        ParseGraph.AutoStripOldParseDetails = NormalizeBoolean(ParseGraph.AccountData.autoStripOldParseDetails);
    end
    ParseGraph.AccountData.autoStripOldParseDetails = ParseGraph.AutoStripOldParseDetails;
    ParseGraph.RestoreImportedParses();
end

function ParseGraph.SaveAccountData()
    local ok, err = pcall(function()
        Turbine.PluginData.Save(Turbine.DataScope.Account, ParseGraph.AccountSaveKey, ParseGraph.AccountData);
    end);
    if not ok then
        Turbine.Shell.WriteLine("ParseGraph: account save failed: " .. tostring(err));
    end
end

function ParseGraph.SaveCharacterEntryToCharacterScope(entry)
    if type(entry) ~= "table" then
        return;
    end

    local saveData = BuildSaveData(entry.parses, entry.graphMin, entry.showMode, entry.achievements, entry.instances, entry.stats);
    local ok, err = pcall(function()
        Turbine.PluginData.Save(Turbine.DataScope.Character, ParseGraph.SaveKey, saveData);
    end);
    if not ok then
        Turbine.Shell.WriteLine("ParseGraph: save failed: " .. tostring(err));
    end
end

function ParseGraph.ClampWindowPosition(x, y)
    x = tonumber(x) or 60;
    y = tonumber(y) or 60;

    local function ClampPositionValue(value, lo, hi)
        if value < lo then return lo end
        if value > hi then return hi end
        return value;
    end

    if Turbine.UI ~= nil and Turbine.UI.Display ~= nil then
        local displayW = tonumber(Turbine.UI.Display.GetWidth()) or 0;
        local displayH = tonumber(Turbine.UI.Display.GetHeight()) or 0;
        if displayW > 0 then
            x = ClampPositionValue(x, 0, math.max(0, displayW - 80));
        end
        if displayH > 0 then
            y = ClampPositionValue(y, 0, math.max(0, displayH - 40));
        end
    end

    return math.floor(x), math.floor(y);
end

function ParseGraph.GetSavedWindowPosition()
    local windowData = ParseGraph.AccountData and ParseGraph.AccountData.window;
    if type(windowData) == "table" then
        return ParseGraph.ClampWindowPosition(windowData.x, windowData.y);
    end

    return ParseGraph.ClampWindowPosition(60, 60);
end

function ParseGraph.RememberWindowPosition(saveNow)
    if ParseGraph.Window == nil or ParseGraph.Window.GetPosition == nil then
        return;
    end

    local ok, x, y = pcall(function()
        return ParseGraph.Window:GetPosition();
    end);
    if not ok then
        return;
    end

    x, y = ParseGraph.ClampWindowPosition(x, y);
    if type(ParseGraph.AccountData) ~= "table" then
        ParseGraph.AccountData = { characters = {} };
    end
    if type(ParseGraph.AccountData.characters) ~= "table" then
        ParseGraph.AccountData.characters = {};
    end

    ParseGraph.AccountData.window = { x = x, y = y };
    if saveNow then
        ParseGraph.SaveAccountData();
    end
end

function ParseGraph.ClampLauncherButtonPosition(x, y)
    x = tonumber(x) or 20;
    y = tonumber(y) or 220;

    local size = tonumber(ParseGraph.LauncherButtonSize) or 42;
    local function ClampPositionValue(value, lo, hi)
        if value < lo then return lo end
        if value > hi then return hi end
        return value;
    end

    if Turbine.UI ~= nil and Turbine.UI.Display ~= nil then
        local displayW = tonumber(Turbine.UI.Display.GetWidth()) or 0;
        local displayH = tonumber(Turbine.UI.Display.GetHeight()) or 0;
        if displayW > 0 then
            x = ClampPositionValue(x, 0, math.max(0, displayW - size));
        end
        if displayH > 0 then
            y = ClampPositionValue(y, 0, math.max(0, displayH - size));
        end
    end

    return math.floor(x), math.floor(y);
end

function ParseGraph.GetLauncherButtonCharacterEntry()
    local key = ParseGraph.GetCurrentCharacterKey();
    local entry = ParseGraph.EnsureAccountCharacter(key, ParseGraph.GetCurrentCharacterName());
    if type(entry.launcherButton) ~= "table" then
        entry.launcherButton = {};
    end
    return entry.launcherButton;
end

function ParseGraph.GetSavedLauncherButtonPosition()
    local data = ParseGraph.GetLauncherButtonCharacterEntry();
    if type(data) == "table" then
        return ParseGraph.ClampLauncherButtonPosition(data.x, data.y);
    end
    return ParseGraph.ClampLauncherButtonPosition(20, 220);
end

function ParseGraph.GetLauncherButtonSizeKey()
    ParseGraph.LauncherButtonSizeKey = NormalizeLauncherButtonSizeKey(ParseGraph.LauncherButtonSizeKey);
    return ParseGraph.LauncherButtonSizeKey;
end

function ParseGraph.GetLauncherButtonSize()
    local key = ParseGraph.GetLauncherButtonSizeKey();
    return ParseGraph.LauncherButtonSizes[key] or ParseGraph.LauncherButtonSizes.medium or 42;
end

function ParseGraph.GetLauncherInstanceDetectionKey()
    local manualTarget = ParseGraph.ManualInstanceTarget;
    local manualHasTarget = type(manualTarget) == "table";
    local tierDetected = ParseGraph.ActiveInstanceTierKey ~= nil or (manualHasTarget and manualTarget.tierKey ~= nil);
    local instanceDetected = ParseGraph.ActiveInstanceKey ~= nil or (manualHasTarget and manualTarget.instanceKey ~= nil);
    local bossDetected = instanceDetected and (tonumber(ParseGraph.AutoInstanceBossIndex) ~= nil or (manualHasTarget and manualTarget.bossIndex ~= nil));

    if tierDetected ~= true and instanceDetected ~= true and bossDetected ~= true then
        return nil;
    end

    return (tierDetected and "1" or "0") .. (instanceDetected and "1" or "0") .. (bossDetected and "1" or "0");
end

function ParseGraph.ApplyLauncherButtonSize(saveNow)
    ParseGraph.LauncherButtonSize = ParseGraph.GetLauncherButtonSize();
    if ParseGraph.LauncherButton == nil then
        return;
    end

    ParseGraph.LauncherButton:SetSize(ParseGraph.LauncherButtonSize, ParseGraph.LauncherButtonSize);
    local x, y = ParseGraph.ClampLauncherButtonPosition(ParseGraph.LauncherButton:GetLeft(), ParseGraph.LauncherButton:GetTop());
    ParseGraph.LauncherButton:SetPosition(x, y);
    ParseGraph.LayoutLauncherTimerOverlay();
    ParseGraph.SetLauncherButtonState();
    if saveNow then
        ParseGraph.RememberLauncherButtonPosition(true);
    end
end

function ParseGraph.RememberLauncherButtonPosition(saveNow)
    if ParseGraph.LauncherButton == nil or ParseGraph.LauncherButton.GetPosition == nil then
        return;
    end

    local ok, x, y = pcall(function()
        return ParseGraph.LauncherButton:GetPosition();
    end);
    if not ok then
        return;
    end

    x, y = ParseGraph.ClampLauncherButtonPosition(x, y);
    local data = ParseGraph.GetLauncherButtonCharacterEntry();
    data.x = x;
    data.y = y;
    if saveNow then
        ParseGraph.SaveAccountData();
    end
end

function ParseGraph.GetLauncherButtonBackground(state)
    local sizeKey = ParseGraph.GetLauncherButtonSizeKey();
    local base = (ParseGraph.GeneralIconPath or "") .. "parsegraph_launcher_" .. sizeKey;

    if ParseGraph.ActiveParse ~= nil then
        if state == "hover" or state == "pressed" then
            return (ParseGraph.GeneralIconPath or "") .. "parsegraph_launcher_discard_" .. sizeKey .. ".tga";
        end
        local dummyKey = tostring(ParseGraph.ActiveParse.dummyKey or "regular");
        if dummyKey ~= "snowman" and dummyKey ~= "warg" and dummyKey ~= "regular" then
            dummyKey = "regular";
        end
        return (ParseGraph.GeneralIconPath or "") .. "parsegraph_launcher_dummy_" .. dummyKey .. "_" .. sizeKey .. ".tga";
    end

    local instanceDetectionKey = ParseGraph.GetLauncherInstanceDetectionKey();
    if instanceDetectionKey ~= nil then
        return (ParseGraph.GeneralIconPath or "") .. "parsegraph_launcher_instance_" .. instanceDetectionKey .. "_" .. sizeKey .. ".tga";
    end

    if state == "hover" then
        return base .. "_hover.tga";
    end
    if state == "pressed" then
        return base .. "_pressed.tga";
    end
    if state == "active" then
        return base .. "_active.tga";
    end
    return base .. ".tga";
end

function ParseGraph.FormatLauncherParseTimer()
    if ParseGraph.ActiveParse == nil then
        return "";
    end

    local now = Turbine.Engine.GetGameTime();
    local elapsed = math.floor(math.max(0, now - (tonumber(ParseGraph.ActiveParse.start) or now)));
    local minutes = math.floor(elapsed / 60);
    local seconds = elapsed - (minutes * 60);
    return tostring(minutes) .. ":" .. string.format("%02d", seconds);
end

function ParseGraph.EnsureLauncherTimerOverlay()
    if ParseGraph.LauncherButton == nil then
        return;
    end

    if ParseGraph.LauncherTimerBack ~= nil and ParseGraph.LauncherTimerBackIsWindow ~= true then
        pcall(function()
            ParseGraph.LauncherTimerBack:SetVisible(false);
        end);
        pcall(function()
            ParseGraph.LauncherTimerBack:SetParent(nil);
        end);
        ParseGraph.LauncherTimerBack = nil;
        ParseGraph.LauncherTimerLabel = nil;
        ParseGraph.LauncherTimerTextShadows = nil;
    end

    if ParseGraph.LauncherTimerBack == nil then
        local back = Turbine.UI.Window();
        back:SetMouseVisible(false);
        back:SetBackColor(Turbine.UI.Color(0.00, 0.00, 0.00, 0.00));
        back:SetVisible(false);
        if back.SetZOrder ~= nil then
            back:SetZOrder(201);
        end
        ParseGraph.LauncherTimerBack = back;
        ParseGraph.LauncherTimerBackIsWindow = true;
    end

    if type(ParseGraph.LauncherTimerTextShadows) ~= "table" then
        ParseGraph.LauncherTimerTextShadows = {};
    end

    for i = 1, 8 do
        if ParseGraph.LauncherTimerTextShadows[i] == nil then
            local shadow = Turbine.UI.Label();
            shadow:SetParent(ParseGraph.LauncherTimerBack);
            shadow:SetMouseVisible(false);
            shadow:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
            shadow:SetForeColor(Turbine.UI.Color(0.95, 0.00, 0.00, 0.00));
            if shadow.SetMultiline ~= nil then
                shadow:SetMultiline(false);
            end
            shadow:SetVisible(false);
            ParseGraph.LauncherTimerTextShadows[i] = shadow;
            ParseGraph.LauncherTimerBack.parseGraphTimerLayout = nil;
            ParseGraph.LauncherTimerBack.parseGraphTimerText = nil;
        end
    end

    if ParseGraph.LauncherTimerLabel == nil then
        local label = Turbine.UI.Label();
        label:SetParent(ParseGraph.LauncherTimerBack);
        label:SetMouseVisible(false);
        label:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        label:SetForeColor(Turbine.UI.Color(1.00, 1.00, 0.94, 0.72));
        if label.SetMultiline ~= nil then
            label:SetMultiline(false);
        end
        label:SetVisible(false);
        ParseGraph.LauncherTimerLabel = label;
    end
end

function ParseGraph.LayoutLauncherTimerOverlay()
    if ParseGraph.LauncherButton == nil then
        return;
    end

    ParseGraph.EnsureLauncherTimerOverlay();
    if ParseGraph.LauncherTimerBack == nil or ParseGraph.LauncherTimerLabel == nil then
        return;
    end

    local size = tonumber(ParseGraph.LauncherButtonSize) or ParseGraph.GetLauncherButtonSize();
    local sizeKey = ParseGraph.GetLauncherButtonSizeKey();
    local font = Turbine.UI.Lotro.Font.TrajanProBold16;
    if sizeKey == "small" then
        font = Turbine.UI.Lotro.Font.TrajanPro13;
    elseif sizeKey == "large" then
        font = Turbine.UI.Lotro.Font.TrajanProBold22;
    end

    local left, top = ParseGraph.LauncherButton:GetLeft(), ParseGraph.LauncherButton:GetTop();
    local iconPath = ParseGraph.GeneralIconPath or "";
    local layout = ParseGraph.LauncherTimerBack.parseGraphTimerLayout;
    if layout ~= nil and layout.left == left and layout.top == top
        and layout.size == size and layout.sizeKey == sizeKey and layout.font == font
        and layout.iconPath == iconPath and layout.label == ParseGraph.LauncherTimerLabel
        and layout.shadows == ParseGraph.LauncherTimerTextShadows then
        return;
    end

    ParseGraph.LauncherTimerBack:SetPosition(left, top);
    ParseGraph.LauncherTimerBack:SetSize(size, size);
    ParseGraph.LauncherTimerBack:SetBackColor(Turbine.UI.Color(0.00, 0.00, 0.00, 0.00));
    if ParseGraph.LauncherTimerBack.SetZOrder ~= nil then
        ParseGraph.LauncherTimerBack:SetZOrder(201);
    end
    local backgroundApplied = pcall(function()
        ParseGraph.LauncherTimerBack:SetBackground((ParseGraph.GeneralIconPath or "") .. "parsegraph_launcher_timer_shadow_" .. sizeKey .. ".tga");
    end);
    local shadowOffset = sizeKey == "large" and 2 or 1;
    local shadowOffsets = {
        { -shadowOffset, 0 },
        { shadowOffset, 0 },
        { 0, -shadowOffset },
        { 0, shadowOffset },
        { -shadowOffset, -shadowOffset },
        { shadowOffset, -shadowOffset },
        { -shadowOffset, shadowOffset },
        { shadowOffset, shadowOffset }
    };
    if type(ParseGraph.LauncherTimerTextShadows) == "table" then
        for i = 1, #ParseGraph.LauncherTimerTextShadows do
            local shadow = ParseGraph.LauncherTimerTextShadows[i];
            if shadow ~= nil then
                local offset = shadowOffsets[i] or { 0, 0 };
                shadow:SetPosition(offset[1], offset[2]);
                shadow:SetSize(size, size);
                shadow:SetFont(font);
            end
        end
    end
    ParseGraph.LauncherTimerLabel:SetPosition(0, 0);
    ParseGraph.LauncherTimerLabel:SetSize(size, size);
    ParseGraph.LauncherTimerLabel:SetFont(font);
    ParseGraph.LauncherTimerBack.parseGraphTimerLayout = backgroundApplied and {
        left = left, top = top, size = size, sizeKey = sizeKey, font = font,
        iconPath = iconPath, label = ParseGraph.LauncherTimerLabel,
        shadows = ParseGraph.LauncherTimerTextShadows
    } or nil;
end

function ParseGraph.StopLauncherTimerUpdate()
    if ParseGraph.LauncherTimerUpdateControl ~= nil then
        ParseGraph.LauncherTimerUpdateControl:SetWantsUpdates(false);
    end
end

function ParseGraph.EnsureLauncherTimerUpdate()
    if ParseGraph.LauncherTimerUpdateControl == nil then
        local timer = Turbine.UI.Control();
        timer:SetSize(1, 1);
        timer:SetMouseVisible(false);
        timer.Update = function()
            ParseGraph.UpdateLauncherTimerOverlay(false);
        end
        ParseGraph.LauncherTimerUpdateControl = timer;
    end
    if ParseGraph.RootPanel ~= nil then
        ParseGraph.LauncherTimerUpdateControl:SetParent(ParseGraph.RootPanel);
        ParseGraph.LauncherTimerUpdateControl:SetPosition(0, 0);
    end
    ParseGraph.LauncherTimerUpdateControl:SetWantsUpdates(true);
end

function ParseGraph.UpdateLauncherTimerOverlay(startUpdates)
    local launcherState = tostring(ParseGraph.LauncherButtonState or "");
    local shouldShow = ParseGraph.LauncherButton ~= nil
        and ParseGraph.ShowLauncherButton == true
        and ParseGraph.GameUiHidden ~= true
        and ParseGraph.ShowLauncherTimer == true
        and ParseGraph.ActiveParse ~= nil
        and launcherState ~= "hover"
        and launcherState ~= "pressed";

    if not shouldShow then
        if ParseGraph.LauncherTimerBack ~= nil then
            ParseGraph.LauncherTimerBack:SetVisible(false);
            ParseGraph.LauncherTimerBack.parseGraphTimerText = nil;
        end
        if ParseGraph.LauncherTimerLabel ~= nil then
            ParseGraph.LauncherTimerLabel:SetVisible(false);
            ParseGraph.LauncherTimerLabel:SetText("");
        end
        if type(ParseGraph.LauncherTimerTextShadows) == "table" then
            for i = 1, #ParseGraph.LauncherTimerTextShadows do
                if ParseGraph.LauncherTimerTextShadows[i] ~= nil then
                    ParseGraph.LauncherTimerTextShadows[i]:SetVisible(false);
                    ParseGraph.LauncherTimerTextShadows[i]:SetText("");
                end
            end
        end
        ParseGraph.StopLauncherTimerUpdate();
        return;
    end

    ParseGraph.LayoutLauncherTimerOverlay();
    local timerText = ParseGraph.FormatLauncherParseTimer();
    local back = ParseGraph.LauncherTimerBack;
    if back ~= nil and ParseGraph.LauncherTimerLabel ~= nil
        and (back.parseGraphTimerText ~= timerText
            or back.parseGraphTimerTextLabel ~= ParseGraph.LauncherTimerLabel
            or back.parseGraphTimerTextShadows ~= ParseGraph.LauncherTimerTextShadows) then
        back:SetVisible(true);
        if type(ParseGraph.LauncherTimerTextShadows) == "table" then
            for i = 1, #ParseGraph.LauncherTimerTextShadows do
                if ParseGraph.LauncherTimerTextShadows[i] ~= nil then
                    ParseGraph.LauncherTimerTextShadows[i]:SetText(timerText);
                    ParseGraph.LauncherTimerTextShadows[i]:SetVisible(true);
                end
            end
        end
        ParseGraph.LauncherTimerLabel:SetText(timerText);
        ParseGraph.LauncherTimerLabel:SetVisible(true);
        back.parseGraphTimerText = timerText;
        back.parseGraphTimerTextLabel = ParseGraph.LauncherTimerLabel;
        back.parseGraphTimerTextShadows = ParseGraph.LauncherTimerTextShadows;
    end
    if startUpdates ~= false then
        ParseGraph.EnsureLauncherTimerUpdate();
    end
end

function ParseGraph.SetLauncherButtonState(state)
    if ParseGraph.LauncherButton == nil then
        return;
    end

    if state == nil or state == "" then
        local active = false;
        if ParseGraph.Window ~= nil and ParseGraph.Window.IsVisible ~= nil then
            local ok, visible = pcall(function()
                return ParseGraph.Window:IsVisible();
            end);
            active = ok and visible == true;
        end
        if active then
            state = "active";
        else
            state = "";
        end
    end

    ParseGraph.LauncherButton:SetBackground(ParseGraph.GetLauncherButtonBackground(state));
    ParseGraph.LauncherButtonState = tostring(state or "");
    ParseGraph.UpdateLauncherTimerOverlay();
end

function ParseGraph.UpdateLauncherButtonVisibility()
    if ParseGraph.LauncherButton == nil then
        return;
    end

    local visible = ParseGraph.ShowLauncherButton == true and ParseGraph.GameUiHidden ~= true;
    ParseGraph.LauncherButton:SetVisible(visible);
    if visible ~= true then
        ParseGraph.HideLauncherContextMenu();
    end
    ParseGraph.SetLauncherButtonState();
end

function ParseGraph.SetGameUiHidden(hidden)
    hidden = hidden == true;
    if ParseGraph.GameUiHidden == hidden then
        return;
    end
    ParseGraph.GameUiHidden = hidden;
    ParseGraph.UpdateLauncherButtonVisibility();
end

function ParseGraph.EnsureGameUiKeyWatcher()
    if ParseGraph.GameUiKeyWatcher ~= nil then
        return;
    end

    local watcher = Turbine.UI.Window();
    ParseGraph.GameUiKeyWatcher = watcher;
    watcher:SetPosition(-10, -10);
    watcher:SetSize(5, 5);
    watcher:SetVisible(true);
    watcher:SetMouseVisible(false);
    watcher:SetWantsKeyEvents(true);
    watcher.KeyDown = function(sender, args)
        if args ~= nil and args.Action == 0x100000B3 then
            ParseGraph.SetGameUiHidden(ParseGraph.GameUiHidden ~= true);
        end
    end
end

function ParseGraph.SetLastLauncherTarget(target)
    if type(target) ~= "table" then
        ParseGraph.LastLauncherTarget = nil;
        return;
    end
    ParseGraph.LastLauncherTarget = target;
end

function ParseGraph.IsWindowVisible()
    if ParseGraph.Window == nil or ParseGraph.Window.IsVisible == nil then
        return false;
    end

    local ok, visible = pcall(function()
        return ParseGraph.Window:IsVisible();
    end);
    return ok and visible == true;
end

function ParseGraph.IsCurrentLauncherTarget(target)
    if type(target) ~= "table" or not ParseGraph.IsWindowVisible() then
        return false;
    end

    if target.view == "instances" then
        return ParseGraph.CurrentView == "instances"
            and ParseGraph.InstanceViewMode == "boss"
            and tostring(ParseGraph.SelectedInstanceKey or "") == tostring(target.instanceKey or "")
            and tostring(ParseGraph.SelectedInstanceTierKey or "") == tostring(target.tierKey or "")
            and tonumber(ParseGraph.SelectedInstanceBossIndex) == tonumber(target.bossIndex)
            and ParseGraph.NormalizeInstanceMetricMode(ParseGraph.InstanceMetricMode) == ParseGraph.NormalizeInstanceMetricMode(target.metric or "damage");
    end

    return target.view == "main" and ParseGraph.CurrentView == "main";
end

function ParseGraph.EnsureWindowVisibleFromLauncher()
    if ParseGraph.Window == nil then
        ParseGraph.BuildWindow(true);
    else
        ParseGraph.AutoHideForCombat = false;
        ParseGraph.AutoHideCombatWasVisible = false;
        ParseGraph.Window:SetVisible(true);
        ParseGraph.UpdatePostButtonWindowPositions();
    end
end

function ParseGraph.OpenLastLauncherTarget()
    local target = ParseGraph.LastLauncherTarget;
    if type(target) ~= "table" or ParseGraph.IsCurrentLauncherTarget(target) then
        return false;
    end

    if target.view == "instances" then
        local instance = ParseGraph.GetInstanceDefinition(target.instanceKey);
        if instance == nil then
            return false;
        end

        local tierKey = tostring(target.tierKey or ParseGraph.ActiveInstanceTierKey or "t1");
        local bossIndex = tonumber(target.bossIndex) or 1;
        local bossCount = type(instance.bosses) == "table" and #instance.bosses or 1;
        bossIndex = math.max(1, math.min(bossCount, bossIndex));

        ParseGraph.EnsureWindowVisibleFromLauncher();
        ParseGraph.InstanceMetricMode = ParseGraph.NormalizeInstanceMetricMode(target.metric or "damage");
        ParseGraph.SelectedInstanceKey = instance.key;
        ParseGraph.SelectedInstanceTierKey = tierKey;
        ParseGraph.SelectedInstanceBossIndex = bossIndex;
        ParseGraph.TemporaryInstanceTarget = {
            instanceKey = instance.key,
            tierKey = tierKey,
            bossIndex = bossIndex
        };
        ParseGraph.InstanceViewMode = "boss";
        ParseGraph.SetView("instances");
        ParseGraph.SetLauncherButtonState();
        return true;
    end

    if target.view == "main" then
        ParseGraph.EnsureWindowVisibleFromLauncher();
        ParseGraph.ClearTemporaryInstanceTarget();
        ParseGraph.SetView("main");
        ParseGraph.SetLauncherButtonState();
        return true;
    end

    return false;
end

function ParseGraph.IsRightMouseButton(args)
    if args == nil then
        return false;
    end

    local button = args.Button or args.button or args.MouseButton or args.mouseButton or args.ButtonName or args.buttonName;
    if Turbine.UI.MouseButton ~= nil and button == Turbine.UI.MouseButton.Right then
        return true;
    end

    local buttonText = string.lower(tostring(button or ""));
    return button == 2
        or buttonText == "2"
        or buttonText == "secondary"
        or string.find(buttonText, "right", 1, true) ~= nil;
end
function ParseGraph.IsLeftMouseButton(args)
    if args == nil or args.Button == nil or Turbine.UI.MouseButton == nil then
        return true;
    end
    return args.Button == Turbine.UI.MouseButton.Left;
end

function ParseGraph.BuildLauncherButton()
    if ParseGraph.EnforceAccessUnavailable ~= nil and ParseGraph.EnforceAccessUnavailable() then
        return;
    end

    if ParseGraph.LauncherButton ~= nil then
        ParseGraph.ApplyLauncherButtonSize(false);
        ParseGraph.UpdateLauncherButtonVisibility();
        return;
    end

    local size = ParseGraph.GetLauncherButtonSize();
    ParseGraph.LauncherButtonSize = size;
    local x, y = ParseGraph.GetSavedLauncherButtonPosition();
    local button = Turbine.UI.Window();
    ParseGraph.LauncherButton = button;
    button:SetSize(size, size);
    button:SetPosition(x, y);
    button:SetMouseVisible(true);
    button:SetVisible(ParseGraph.ShowLauncherButton == true and ParseGraph.GameUiHidden ~= true);
    if button.SetZOrder ~= nil then
        button:SetZOrder(200);
    end

    button.Moving = false;
    button.WasMoved = false;
    button.MouseEnter = function(sender)
        if sender.Moving ~= true then
            ParseGraph.SetLauncherButtonState("hover");
        end
    end
    button.MouseLeave = function(sender)
        if sender.Moving ~= true then
            ParseGraph.SetLauncherButtonState();
        end
    end
    button.MouseDown = function(sender, args)
        if ParseGraph.IsRightMouseButton(args) then
            sender.Moving = false;
            sender.WasMoved = false;
            ParseGraph.ShowLauncherContextMenu();
            return;
        end
        if not ParseGraph.IsLeftMouseButton(args) then
            return;
        end
        ParseGraph.HideLauncherContextMenu();
        sender.MoveX = args and tonumber(args.X) or 0;
        sender.MoveY = args and tonumber(args.Y) or 0;
        sender.Moving = true;
        sender.WasMoved = false;
        ParseGraph.SetLauncherButtonState("pressed");
    end
    button.MouseMove = function(sender, args)
        if sender.Moving ~= true then
            return;
        end
        local dx = (args and tonumber(args.X) or 0) - (tonumber(sender.MoveX) or 0);
        local dy = (args and tonumber(args.Y) or 0) - (tonumber(sender.MoveY) or 0);
        if math.abs(dx) > 1 or math.abs(dy) > 1 then
            sender.WasMoved = true;
        end
        local xPos, yPos = ParseGraph.ClampLauncherButtonPosition(sender:GetLeft() + dx, sender:GetTop() + dy);
        sender:SetPosition(xPos, yPos);
    end
    button.MouseUp = function(sender, args)
        if not ParseGraph.IsLeftMouseButton(args) then
            sender.Moving = false;
            sender.WasMoved = false;
            return;
        end
        local wasMoved = sender.WasMoved == true;
        sender.Moving = false;
        sender.WasMoved = false;
        ParseGraph.RememberLauncherButtonPosition(true);
        if not wasMoved then
            if ParseGraph.CloseParseFullView ~= nil then
                ParseGraph.CloseParseFullView();
            end
            if ParseGraph.ActiveParse ~= nil then
                ParseGraph.HideLauncherContextMenu();
                ParseGraph.DiscardActiveParse(false);
            else
                if not ParseGraph.OpenLastLauncherTarget() then
                    ParseGraph.ToggleWindow();
                    ParseGraph.SetLauncherButtonState();
                end
            end
        else
            ParseGraph.SetLauncherButtonState("hover");
        end
    end
    button.PositionChanged = function()
        ParseGraph.RememberLauncherButtonPosition(false);
    end

    ParseGraph.EnsureLauncherTimerOverlay();
    ParseGraph.SetLauncherButtonState();
end

function ParseGraph.EnsureAccountCharacter(key, name)
    key = tostring(key or ParseGraph.GetCurrentCharacterKey());
    if type(ParseGraph.AccountData) ~= "table" then
        ParseGraph.AccountData = { characters = {} };
    end
    if type(ParseGraph.AccountData.characters) ~= "table" then
        ParseGraph.AccountData.characters = {};
    end
    if type(ParseGraph.AccountData.achievements) ~= "table" then
        ParseGraph.AccountData.achievements = {};
    end

    local entry = ParseGraph.AccountData.characters[key];
    if type(entry) ~= "table" then
        entry = {};
        ParseGraph.AccountData.characters[key] = entry;
    end

    entry = NormalizeCharacterData(entry, key, name);
    if key == ParseGraph.GetCurrentCharacterKey() then
        local classInfo = ParseGraph.GetCurrentPlayerClassInfo();
        if classInfo ~= nil then
            entry.classKey = classInfo.key;
            entry.className = classInfo.name;
            entry.classIcon = classInfo.icon;
        end
    end
    ParseGraph.AccountData.characters[key] = entry;
    return entry;
end

local function CopyShallow(source)
    local copy = {};
    if type(source) == "table" then
        for k, v in pairs(source) do
            copy[k] = v;
        end
    end
    return copy;
end

function ParseGraph.GetCharacterClassKey(entry)
    if type(entry) ~= "table" then
        return nil;
    end

    local classKey = tostring(entry.classKey or "");
    if classKey ~= "" then
        return LowerClean(classKey);
    end

    local className = tostring(entry.className or "");
    if className ~= "" then
        return LowerClean(className);
    end

    local classIcon = tostring(entry.classIcon or "");
    if classIcon ~= "" then
        classIcon = string.gsub(classIcon, "\\", "/");
        classIcon = string.match(classIcon, "([^/]+)$") or classIcon;
        classIcon = string.gsub(classIcon, "_icon%.tga$", "");
        classIcon = string.gsub(classIcon, "%.tga$", "");
        if classIcon ~= "" then
            return LowerClean(classIcon);
        end
    end

    return nil;
end

function ParseGraph.GetViewCharacterEntry()
    local key = tostring(ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey());
    if key == ParseGraph.GetCurrentCharacterKey() then
        return ParseGraph.EnsureAccountCharacter(key, ParseGraph.GetCurrentCharacterName());
    end

    local characters = ParseGraph.AccountData and ParseGraph.AccountData.characters or {};
    local entry = characters[key];
    if type(entry) == "table" then
        entry = NormalizeCharacterData(entry, key, entry.name);
        characters[key] = entry;
        return entry;
    end

    return nil;
end

function ParseGraph.IsCombineSameClassActive()
    if ParseGraph.CombineSameClass ~= true then
        return false;
    end

    local classKey = ParseGraph.GetCharacterClassKey(ParseGraph.GetViewCharacterEntry());
    return classKey ~= nil and classKey ~= "";
end

function ParseGraph.ForEachViewClassCharacter(callback)
    if type(callback) ~= "function" then
        return;
    end

    local viewKey = tostring(ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey());
    local currentKey = ParseGraph.GetCurrentCharacterKey();
    local viewEntry = ParseGraph.GetViewCharacterEntry();
    local combine = ParseGraph.IsCombineSameClassActive();
    local viewClassKey = ParseGraph.GetCharacterClassKey(viewEntry);
    local characters = ParseGraph.AccountData and ParseGraph.AccountData.characters or {};
    local seen = {};

    local function visit(key, entry)
        key = tostring(key or "");
        if key == "" or seen[key] == true or type(entry) ~= "table" then
            return;
        end
        entry = NormalizeCharacterData(entry, key, entry.name);
        if key == currentKey then
            local classInfo = ParseGraph.GetCurrentPlayerClassInfo();
            if classInfo ~= nil then
                entry.classKey = classInfo.key;
                entry.className = classInfo.name;
                entry.classIcon = classInfo.icon;
            end
        end
        if (not combine) or ParseGraph.GetCharacterClassKey(entry) == viewClassKey then
            seen[key] = true;
            callback(key, entry, key == viewKey);
        end
    end

    visit(viewKey, viewEntry);
    if combine then
        for key, entry in pairs(characters) do
            visit(key, entry);
        end
    end
end

function ParseGraph.GetViewParses()
    if not ParseGraph.IsCombineSameClassActive() then
        return ParseGraph.Parses or {};
    end

    local viewKey = tostring(ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey());
    local parses = {};
    ParseGraph.ForEachViewClassCharacter(function(key, entry, isView)
        local sourceParses = isView and (ParseGraph.Parses or {}) or (entry.parses or {});
        local sourceName = entry.name or key;
        for i = 1, #sourceParses do
            local parse = CopyShallow(sourceParses[i]);
            parse.__sourceKey = key;
            parse.__sourceName = sourceName;
            parse.__sourceIndex = i;
            parses[#parses + 1] = parse;
        end
    end);

    table.sort(parses, function(a, b)
        local at = tostring(a and a.time or "");
        local bt = tostring(b and b.time or "");
        if at == bt then
            local ak = tostring(a and a.__sourceKey or viewKey);
            local bk = tostring(b and b.__sourceKey or viewKey);
            if ak == bk then
                return (tonumber(a and a.__sourceIndex) or 0) < (tonumber(b and b.__sourceIndex) or 0);
            end
            return ak < bk;
        end
        if at == "" then return false end
        if bt == "" then return true end
        return at < bt;
    end);

    return parses;
end

function ParseGraph.GetAchievementParses()
    if ParseGraph.SyncingAchievements == true then
        return ParseGraph.Parses or {};
    end
    return ParseGraph.GetViewParses();
end

function ParseGraph.GetViewAchievementEntry(key)
    key = tostring(key or "");
    if key == "" then
        return nil;
    end

    if ParseGraph.SyncingAchievements == true or not ParseGraph.IsCombineSameClassActive() then
        local entry = type(ParseGraph.UnlockedAchievements) == "table" and ParseGraph.UnlockedAchievements[key] or nil;
        if entry == true or (type(entry) == "table" and entry.unlocked == true) then
            return entry;
        end
        return nil;
    end

    local bestEntry = nil;
    ParseGraph.ForEachViewClassCharacter(function(characterKey, entry, isView)
        local achievements = isView and (ParseGraph.UnlockedAchievements or {}) or (entry.achievements or {});
        local unlocked = achievements[key];
        if unlocked == true then
            unlocked = {
                unlocked = true,
                date = "",
                characterName = entry.name or characterKey,
                characterKey = characterKey
            };
        end
        if type(unlocked) == "table" and unlocked.unlocked == true then
            local unlockedDate = tostring(unlocked.date or "");
            local bestDate = bestEntry ~= nil and tostring(bestEntry.date or "") or "";
            if bestEntry == nil or (unlockedDate ~= "" and (bestDate == "" or unlockedDate < bestDate)) then
                bestEntry = unlocked;
            end
        end
    end);

    return bestEntry;
end

local function GetRecordsFromInstanceData(instances, instanceKey, tierKey, bossIndex, mode)
    local instanceData = type(instances) == "table" and instances[instanceKey] or nil;
    if type(instanceData) ~= "table" then return {}; end

    local tierData = instanceData[tierKey];
    if type(tierData) ~= "table" then return {}; end

    local bossData = tierData["boss" .. tostring(bossIndex)];
    if type(bossData) ~= "table" then return {}; end

    local records = bossData[mode];
    if type(records) ~= "table" then return {}; end
    return records;
end

function ParseGraph.GetCharacterDisplayName(key)
    key = tostring(key or ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey());
    if key == ParseGraph.GetCurrentCharacterKey() then
        return ParseGraph.GetCurrentCharacterName();
    end

    local entry = ParseGraph.AccountData and ParseGraph.AccountData.characters and ParseGraph.AccountData.characters[key];
    if type(entry) == "table" and entry.name ~= nil and tostring(entry.name) ~= "" then
        return tostring(entry.name);
    end
    return key;
end

function ParseGraph.IsViewingCurrentCharacter()
    return (ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey()) == ParseGraph.GetCurrentCharacterKey();
end

function ParseGraph.SaveViewToAccount(markDeleted, overrideCharacter)
    local key = ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey();
    local name = ParseGraph.GetCharacterDisplayName(key);
    local entry = ParseGraph.EnsureAccountCharacter(key, name);

    entry.parses = ParseGraph.Parses or {};
    entry.graphMin = tonumber(ParseGraph.GraphMin) or 100000;
    entry.showMode = NormalizeShowMode(ParseGraph.ShowMode);
    entry.achievements = ParseGraph.UnlockedAchievements or {};
    entry.instances = ParseGraph.InstanceData or {};
    entry.stats = ParseGraph.CharacterStats or {};
    entry.updated = NowText();
    if markDeleted then
        entry.deleted = true;
    else
        entry.deleted = nil;
    end
    if key ~= ParseGraph.GetCurrentCharacterKey() and overrideCharacter then
        entry.overrideCharacter = true;
    elseif key == ParseGraph.GetCurrentCharacterKey() then
        entry.overrideCharacter = nil;
    end

    ParseGraph.SaveAccountData();
end

function ParseGraph.Save(markDeleted, overrideCharacter)
    local currentKey = ParseGraph.GetCurrentCharacterKey();
    local viewKey = ParseGraph.ViewCharacterKey or currentKey;

    ParseGraph.ApplyAutoStripOldParseDetails(100);
    ParseGraph.SaveViewToAccount(markDeleted, overrideCharacter);

    if viewKey ~= currentKey then
        return;
    end

    local saveData = BuildSaveData(ParseGraph.Parses, ParseGraph.GraphMin, ParseGraph.ShowMode, ParseGraph.UnlockedAchievements, ParseGraph.InstanceData, ParseGraph.CharacterStats);

    local ok, err = pcall(function()
        Turbine.PluginData.Save(Turbine.DataScope.Character, ParseGraph.SaveKey, saveData);
    end);
    if not ok then
        Turbine.Shell.WriteLine("ParseGraph: save failed: " .. tostring(err));
    end
end

function ParseGraph.Load()
    ParseGraph.InstanceSessionStartGameTime = Turbine.Engine.GetGameTime();
    ParseGraph.CurrentCharacterName = ParseGraph.GetPlayerName();
    ParseGraph.CurrentCharacterKey = ParseGraph.GetPlayerKey();
    ParseGraph.ViewCharacterKey = ParseGraph.CurrentCharacterKey;
    ParseGraph.LoadAccountData();

    local loadedData = nil;
    local ok, data = pcall(function()
        return Turbine.PluginData.Load(Turbine.DataScope.Character, ParseGraph.SaveKey);
    end);

    if ok and type(data) == "table" then
        -- v1.4.1+ saves a wrapper table with parses and settings.
        -- Older character data may still be the raw parse array, so support both.
        loadedData = NormalizeCharacterData(data, ParseGraph.CurrentCharacterKey, ParseGraph.CurrentCharacterName);
    else
        -- One-time convenience fallback: older versions saved account-wide.
        -- We copy that data into the current character scope if this character has no data yet.
        local okAccount, accountData = pcall(function()
            return Turbine.PluginData.Load(Turbine.DataScope.Account, ParseGraph.SaveKey);
        end);

        if okAccount and type(accountData) == "table" then
            loadedData = NormalizeCharacterData(accountData, ParseGraph.CurrentCharacterKey, ParseGraph.CurrentCharacterName);
        else
            -- Legacy fallback: v1.0.x attempted to use a two-part key. On clients where
            -- extra arguments were ignored this may return a string instead of a parse table,
            -- so we only accept it if it is genuinely a table.
            local okLegacy, legacyData = pcall(function()
                return Turbine.PluginData.Load(Turbine.DataScope.Character, ParseGraph.LegacySaveKey);
            end);

            if okLegacy and type(legacyData) == "table" then
                loadedData = NormalizeCharacterData(legacyData, ParseGraph.CurrentCharacterKey, ParseGraph.CurrentCharacterName);
            end
        end
    end

    if loadedData == nil then
        loadedData = NormalizeCharacterData({}, ParseGraph.CurrentCharacterKey, ParseGraph.CurrentCharacterName);
    end

    local accountEntry = ParseGraph.AccountData.characters[ParseGraph.CurrentCharacterKey];
    if type(accountEntry) == "table" and accountEntry.deleted == true then
        loadedData = NormalizeCharacterData({
            parses = {},
            graphMin = accountEntry.graphMin,
            showMode = accountEntry.showMode
        }, ParseGraph.CurrentCharacterKey, ParseGraph.CurrentCharacterName);
    elseif type(accountEntry) == "table" and accountEntry.overrideCharacter == true then
        loadedData = NormalizeCharacterData(accountEntry, ParseGraph.CurrentCharacterKey, ParseGraph.CurrentCharacterName);
    end

    ParseGraph.Parses = loadedData.parses or {};
    ParseGraph.InstanceData = loadedData.instances or {};
    ParseGraph.CharacterStats = loadedData.stats or {};
    ParseGraph.GraphMin = tonumber(loadedData.graphMin) or 100000;
    ParseGraph.ShowMode = NormalizeShowMode(loadedData.showMode);
    ParseGraph.UnlockedAchievements = loadedData.achievements or {};
    ParseGraph.SyncAchievements(false);
    ParseGraph.Save();
end

local function Label(parent, x, y, w, h, text, size)
    local l = Turbine.UI.Label();
    l:SetParent(parent);
    l:SetPosition(x, y);
    l:SetSize(w, h);
    l:SetFont(Turbine.UI.Lotro.Font.TrajanPro14);
    if size == "small" then l:SetFont(Turbine.UI.Lotro.Font.TrajanPro13) end
    if size == "big" then l:SetFont(Turbine.UI.Lotro.Font.TrajanPro16) end
    if size == "achievement" then l:SetFont(Turbine.UI.Lotro.Font.TrajanPro18) end
    if size == "achievementTitle" then l:SetFont(Turbine.UI.Lotro.Font.TrajanProBold22) end
    if size == "achievementDetail" then l:SetFont(Turbine.UI.Lotro.Font.TrajanPro14) end
    if size == "huge" then l:SetFont(Turbine.UI.Lotro.Font.TrajanProBold22) end
    l:SetForeColor(Turbine.UI.Color(1, 0.93, 0.62));
    l:SetText(text or "");
    return l;
end

local function Panel(parent, x, y, w, h, opacity)
    local p = Turbine.UI.Control();
    p:SetParent(parent);
    p:SetPosition(x, y);
    p:SetSize(w, h);
    p:SetBackColor(Turbine.UI.Color(opacity or 0.72, 0, 0, 0));
    return p;
end

local function DrawBlock(parent, x, y, w, h, color)
    local c = Turbine.UI.Control();
    c:SetParent(parent);
    c:SetPosition(math.floor(x), math.floor(y));
    c:SetSize(math.max(1, math.floor(w)), math.max(1, math.floor(h)));
    c:SetBackColor(color);
    return c;
end

