function ParseGraph.FindAchievementByKey(key)
    key = tostring(key or "");
    for categoryIndex = 1, #ParseGraph.AchievementCategories do
        local category = ParseGraph.AchievementCategories[categoryIndex];
        local data = ParseGraph.Achievements[category.key];
        local items = data and data.items or {};
        for i = 1, #items do
            if tostring(items[i].key or "") == key then
                return items[i], category.key;
            end
        end
    end
    return nil, nil;
end

function ParseGraph.IsAccountWideAchievement(achievement)
    return achievement ~= nil and achievement.parseCount ~= nil;
end

function ParseGraph.GetAccountAchievements()
    if type(ParseGraph.AccountData) ~= "table" then
        ParseGraph.AccountData = { characters = {} };
    end
    if type(ParseGraph.AccountData.characters) ~= "table" then
        ParseGraph.AccountData.characters = {};
    end
    if type(ParseGraph.AccountData.achievements) ~= "table" then
        ParseGraph.AccountData.achievements = {};
    end

    local accountAchievements = ParseGraph.AccountData.achievements;
    local function migrate(source)
        if type(source) ~= "table" then return end
        for key, unlocked in pairs(source) do
            if unlocked == true or (type(unlocked) == "table" and unlocked.unlocked == true) then
                local achievement = ParseGraph.FindAchievementByKey(key);
                if ParseGraph.IsAccountWideAchievement(achievement) then
                    if type(accountAchievements[key]) ~= "table" then
                        if type(unlocked) == "table" then
                            accountAchievements[key] = unlocked;
                        else
                            accountAchievements[key] = true;
                        end
                    end
                end
            end
        end
    end

    migrate(ParseGraph.UnlockedAchievements);
    for _, entry in pairs(ParseGraph.AccountData.characters) do
        if type(entry) == "table" then
            migrate(entry.achievements);
        end
    end

    return accountAchievements;
end

function ParseGraph.GetAccountParseCount()
    local total = 0;
    local viewKey = tostring(ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey());
    local countedView = false;
    local characters = ParseGraph.AccountData and ParseGraph.AccountData.characters or {};

    for key, entry in pairs(characters) do
        if type(entry) == "table" then
            if tostring(key) == viewKey then
                total = total + #ParseGraph.Parses;
                countedView = true;
            else
                total = total + #(entry.parses or {});
            end
        end
    end

    if not countedView then
        total = total + #ParseGraph.Parses;
    end

    return total;
end

local DateKeyToDayNumber;

local function GetParseDateKey(parse)
    return string.match(tostring(parse and parse.time or ""), "^(%d%d%d%d%-%d%d%-%d%d)");
end

local function GetTimestampResetDayNumber(timestamp)
    local text = tostring(timestamp or "");
    local dateKey, hourText = string.match(text, "^(%d%d%d%d%-%d%d%-%d%d)%s+(%d%d)");
    if dateKey == nil then
        dateKey = string.match(text, "^(%d%d%d%d%-%d%d%-%d%d)");
    end

    local dayNumber = DateKeyToDayNumber(dateKey);
    if dayNumber == nil then
        return nil;
    end

    local hour = tonumber(hourText);
    if hour ~= nil and hour < (tonumber(ParseGraph.DayResetHour) or 5) then
        dayNumber = dayNumber - 1;
    end
    return dayNumber;
end

local function GetParseResetDayNumber(parse)
    return GetTimestampResetDayNumber(parse and parse.time);
end

local function GetCurrentResetDayNumber()
    local d = Turbine.Engine.GetDate();
    if d ~= nil and d.Month ~= nil then
        local dayNumber = DateKeyToDayNumber(string.format("%04d-%02d-%02d", d.Year, d.Month, d.Day));
        local hour = tonumber(d.Hour);
        if dayNumber ~= nil and hour ~= nil and hour < (tonumber(ParseGraph.DayResetHour) or 5) then
            dayNumber = dayNumber - 1;
        end
        return dayNumber;
    end
    return GetTimestampResetDayNumber(NowText());
end

DateKeyToDayNumber = function(dateKey)
    local year, month, day = string.match(tostring(dateKey or ""), "^(%d%d%d%d)%-(%d%d)%-(%d%d)$");
    year = tonumber(year);
    month = tonumber(month);
    day = tonumber(day);
    if year == nil or month == nil or day == nil then
        return nil;
    end

    if month <= 2 then
        year = year - 1;
        month = month + 12;
    end

    return math.floor(365 * year)
        + math.floor(year / 4)
        - math.floor(year / 100)
        + math.floor(year / 400)
        + math.floor((153 * (month - 3) + 2) / 5)
        + day - 1;
end

local function HasConsecutiveParseDayStreak(requiredDays)
    return ParseGraph.GetCurrentParseDayStreak() >= requiredDays;
end

local function HasParsesInOneDay(requiredCount)
    local counts = {};
    local parses = ParseGraph.GetAchievementParses();
    for i = 1, #parses do
        local dayNumber = GetParseResetDayNumber(parses[i]);
        if dayNumber ~= nil then
            counts[dayNumber] = (counts[dayNumber] or 0) + 1;
            if counts[dayNumber] >= requiredCount then
                return true;
            end
        end
    end

    return false;
end

local function GetCurrentResetDayParseCount()
    local currentDay = GetCurrentResetDayNumber();
    local count = 0;
    local parses = ParseGraph.GetAchievementParses();
    for i = 1, #parses do
        if GetParseResetDayNumber(parses[i]) == currentDay then
            count = count + 1;
        end
    end

    return count;
end

local function HasNearPersonalBestMiss(tolerance)
    local best = 0;
    tolerance = tonumber(tolerance) or 0;

    local parses = ParseGraph.GetAchievementParses();
    for i = 1, #parses do
        local value = tonumber(parses[i].final) or 0;
        if best > 0 and value < best then
            local missedBy = (best - value) / best;
            if missedBy <= tolerance then
                return true;
            end
        end

        if value > best then
            best = value;
        end
    end

    return false;
end

local function GetNearPersonalBestMiss(tolerance)
    local best = 0;
    local closest = nil;
    tolerance = tonumber(tolerance) or 0;

    local parses = ParseGraph.GetAchievementParses();
    for i = 1, #parses do
        local value = tonumber(parses[i].final) or 0;
        if best > 0 and value < best then
            local missedByValue = best - value;
            local missedBy = missedByValue / best;
            if closest == nil or missedBy < closest.percent then
                closest = {
                    value = value,
                    best = best,
                    difference = missedByValue,
                    percent = missedBy,
                    qualified = missedBy <= tolerance
                };
            end
        end

        if value > best then
            best = value;
        end
    end

    return closest;
end

local function HasFlatParseRun(requiredCount, tolerance)
    requiredCount = tonumber(requiredCount) or 10;
    tolerance = tonumber(tolerance) or 0.01;
    local parses = ParseGraph.GetAchievementParses();
    if #parses < requiredCount then
        return false;
    end

    for startIndex = 1, (#parses - requiredCount + 1) do
        local lowest = nil;
        local highest = nil;
        for i = startIndex, (startIndex + requiredCount - 1) do
            local value = tonumber(parses[i].final) or 0;
            if lowest == nil or value < lowest then
                lowest = value;
            end
            if highest == nil or value > highest then
                highest = value;
            end
        end

        if highest ~= nil and highest > 0 and lowest ~= nil then
            if ((highest - lowest) / highest) <= tolerance then
                return true;
            end
        end
    end

    return false;
end

local function GetFlatParseRunLength(tolerance)
    tolerance = tonumber(tolerance) or 0.01;
    local bestLength = 0;
    local parses = ParseGraph.GetAchievementParses();

    for startIndex = 1, #parses do
        local lowest = nil;
        local highest = nil;
        for endIndex = startIndex, #parses do
            local value = tonumber(parses[endIndex].final) or 0;
            if lowest == nil or value < lowest then
                lowest = value;
            end
            if highest == nil or value > highest then
                highest = value;
            end

            if highest ~= nil and highest > 0 and lowest ~= nil and ((highest - lowest) / highest) <= tolerance then
                local length = endIndex - startIndex + 1;
                if length > bestLength then
                    bestLength = length;
                end
            end
        end
    end

    return bestLength;
end

function ParseGraph.GetCurrentParseDayStreak()
    local daySeen = {};
    local days = {};
    local parses = ParseGraph.GetAchievementParses();

    for i = 1, #parses do
        local dayNumber = DateKeyToDayNumber(GetParseDateKey(parses[i]));
        if dayNumber ~= nil and daySeen[dayNumber] ~= true then
            daySeen[dayNumber] = true;
            table.insert(days, dayNumber);
        end
    end

    table.sort(days);

    local streak = 0;
    local lastDay = nil;
    for i = 1, #days do
        if lastDay ~= nil and days[i] == lastDay + 1 then
            streak = streak + 1;
        else
            streak = 1;
        end
        lastDay = days[i];
    end

    return streak;
end

local function GetDuplicateParseValue()
    local counts = {};
    local parses = ParseGraph.GetAchievementParses();
    for i = 1, #parses do
        local value = Round(parses[i].final);
        counts[value] = (counts[value] or 0) + 1;
        if counts[value] >= 2 then
            return value, counts[value];
        end
    end

    return nil, 0;
end

local function GetDrySpellStats()
    local best = 0;
    local drySpell = 0;
    local longestDrySpell = 0;
    local finallyDrySpell = nil;
    local parses = ParseGraph.GetAchievementParses();

    for i = 1, #parses do
        local value = tonumber(parses[i].final) or 0;
        if value > best then
            if best > 0 and drySpell >= 100 and finallyDrySpell == nil then
                finallyDrySpell = drySpell;
            end
            best = value;
            drySpell = 0;
        else
            drySpell = drySpell + 1;
            if drySpell > longestDrySpell then
                longestDrySpell = drySpell;
            end
        end
    end

    return {
        longestDrySpell = longestDrySpell,
        finallyDrySpell = finallyDrySpell
    };
end

local function GetOneAndDoneParse()
    local dayCounts = {};
    local currentDay = GetCurrentResetDayNumber();
    local parses = ParseGraph.GetAchievementParses();
    for i = 1, #parses do
        local dayNumber = GetParseResetDayNumber(parses[i]);
        if dayNumber ~= nil and dayNumber ~= currentDay then
            dayCounts[dayNumber] = (dayCounts[dayNumber] or 0) + 1;
        end
    end

    local best = 0;
    for i = 1, #parses do
        local parse = parses[i];
        local dayNumber = GetParseResetDayNumber(parse);
        local value = tonumber(parse and parse.final) or 0;
        if i > 25 and dayNumber ~= nil and dayNumber ~= currentDay and dayCounts[dayNumber] == 1 and value > best then
            return parse, dayNumber;
        end
        if value > best then
            best = value;
        end
    end

    return nil, nil;
end

local function GetParseEarnedInfo(parse)
    if parse == nil then
        return nil;
    end

    local viewKey = tostring(ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey());
    return {
        date = tostring(parse.time or NowText()),
        characterName = tostring(parse.__sourceName or ParseGraph.GetCharacterDisplayName(viewKey)),
        characterKey = tostring(parse.__sourceKey or viewKey)
    };
end

local function GetLateBloomerParse()
    local parses = ParseGraph.GetAchievementParses();
    for i = 1, #parses do
        local parse = parses[i];
        local minutes = parse and parse.minutes;
        local m1 = minutes ~= nil and tonumber(minutes[1]) or nil;
        local m2 = minutes ~= nil and tonumber(minutes[2]) or nil;
        local m3 = minutes ~= nil and tonumber(minutes[3]) or nil;
        if m1 ~= nil and m2 ~= nil and m3 ~= nil and m3 > m1 and m3 > m2 then
            return parse;
        end
    end

    return nil;
end

local function GetMathematicallySuspiciousParse()
    local parses = ParseGraph.GetAchievementParses();
    for i = 1, #parses do
        local value = Round(parses[i].final);
        if value > 0 and (value % 1000) == 0 then
            return parses[i];
        end
    end

    return nil;
end

local function GetComebackArcParse()
    local best = 0;
    local previousBestDay = nil;
    local parses = ParseGraph.GetAchievementParses();
    for i = 1, #parses do
        local parse = parses[i];
        local value = tonumber(parse and parse.final) or 0;
        local dayNumber = GetParseResetDayNumber(parse);
        if value > best then
            if best > 0 and previousBestDay ~= nil and dayNumber ~= nil and (dayNumber - previousBestDay) >= 30 then
                return parse;
            end
            best = value;
            if dayNumber ~= nil then
                previousBestDay = dayNumber;
            end
        end
    end

    return nil;
end

local function GetAchievementDiscardCount()
    if ParseGraph.SyncingAchievements == true or not ParseGraph.IsCombineSameClassActive() then
        return tonumber(ParseGraph.CharacterStats and ParseGraph.CharacterStats.discardedRunningParses) or 0;
    end

    local total = 0;
    ParseGraph.ForEachViewClassCharacter(function(key, entry, isView)
        local stats = isView and (ParseGraph.CharacterStats or {}) or (entry.stats or {});
        total = total + (tonumber(stats.discardedRunningParses) or 0);
    end);
    return total;
end

function ParseGraph.GetAchievementDetailText(achievement)
    if achievement == nil then
        return "";
    end

    return tostring(achievement.detail or "");
end

function ParseGraph.GetAchievementProgressText(achievement)
    if achievement == nil then
        return "";
    end

    local key = tostring(achievement.key or "");

    local function Progress(current, required, label)
        current = tonumber(current) or 0;
        required = tonumber(required) or 0;
        return FormatNumber(math.min(current, required)) .. "/" .. FormatNumber(required);
    end

    local function CompletedProgress(required)
        return Progress(required, required);
    end

    if achievement.parseCount ~= nil or achievement.dps ~= nil then
        return "";
    elseif key == "weeklyWarrior" then
        if ParseGraph.IsAchievementUnlocked(key) then
            return CompletedProgress(7);
        end
        local streak = ParseGraph.GetCurrentParseDayStreak();
        return Progress(streak, 7);
    elseif key == "seekHelp" then
        if ParseGraph.IsAchievementUnlocked(key) then
            return CompletedProgress(30);
        end
        local streak = ParseGraph.GetCurrentParseDayStreak();
        return Progress(streak, 30);
    elseif key == "dejaVu" then
        if ParseGraph.IsAchievementUnlocked(key) then
            local value = GetDuplicateParseValue();
            if value ~= nil then
                return FormatNumber(value);
            end
        end
        return "";
    elseif key == "surelyTheNextOne" then
        local stats = GetDrySpellStats();
        return Progress(stats.longestDrySpell, 100);
    elseif key == "finally" then
        local stats = GetDrySpellStats();
        if stats.finallyDrySpell ~= nil then
            return Progress(stats.finallyDrySpell, 100);
        end
        return Progress(stats.longestDrySpell, 100);
    elseif key == "sequentialDamage" then
        if ParseGraph.IsAchievementUnlocked(key) then
            return "1/1";
        end
        return "0/1";
    elseif key == "oneAndDone" then
        local parse = GetOneAndDoneParse();
        if parse ~= nil then
            return "1/1";
        end
        return "0/1";
    elseif key == "soCloseItHurts" then
        local miss = GetNearPersonalBestMiss(0.001);
        if miss ~= nil and miss.qualified == true then
            return "1/1";
        end
        return "0/1";
    elseif key == "refuelRequired" then
        if ParseGraph.IsAchievementUnlocked(key) then
            return CompletedProgress(50);
        end
        local currentDayCount = GetCurrentResetDayParseCount();
        return Progress(currentDayCount, 50);
    elseif key == "touchGrassReminder" then
        if ParseGraph.IsAchievementUnlocked(key) then
            return CompletedProgress(100);
        end
        local currentDayCount = GetCurrentResetDayParseCount();
        return Progress(currentDayCount, 100);
    elseif key == "flatlined" then
        if ParseGraph.IsAchievementUnlocked(key) then
            return CompletedProgress(10);
        end
        local runLength = GetFlatParseRunLength(0.02);
        return Progress(runLength, 10);
    elseif key == "theComebackArc" then
        if GetComebackArcParse() ~= nil then
            return "1/1";
        end
        return "0/1";
    elseif key == "lateBloomer" then
        if GetLateBloomerParse() ~= nil then
            return "1/1";
        end
        return "0/1";
    elseif key == "weGoAgain" then
        if ParseGraph.IsAchievementUnlocked(key) then
            return CompletedProgress(10);
        end
        return Progress(ParseGraph.SessionDiscardCount, 10);
    elseif key == "weDontTalkAboutThose" then
        if ParseGraph.IsAchievementUnlocked(key) then
            return CompletedProgress(100);
        end
        return Progress(GetAchievementDiscardCount(), 100);
    elseif key == "mathematicallySuspicious" then
        if GetMathematicallySuspiciousParse() ~= nil then
            return "1/1";
        end
        return "0/1";
    end

    return "";
end

function ParseGraph.IsAchievementUnlocked(key)
    local achievement = ParseGraph.FindAchievementByKey(key);
    if ParseGraph.IsAccountWideAchievement(achievement) then
        local accountAchievements = ParseGraph.GetAccountAchievements();
        local entry = accountAchievements[key];
        return entry == true or (type(entry) == "table" and entry.unlocked == true) or ParseGraph.IsAchievementEarned(achievement);
    end

    local entry = ParseGraph.GetViewAchievementEntry(key);
    return entry == true or (type(entry) == "table" and entry.unlocked == true) or ParseGraph.IsAchievementEarned(achievement);
end

function ParseGraph.GetAchievementStorage(achievement)
    if ParseGraph.IsAccountWideAchievement(achievement) then
        return ParseGraph.GetAccountAchievements();
    end

    if type(ParseGraph.UnlockedAchievements) ~= "table" then
        ParseGraph.UnlockedAchievements = {};
    end
    return ParseGraph.UnlockedAchievements;
end

function ParseGraph.GetAchievementFirstEarnedInfo(achievement)
    if achievement == nil then
        return nil;
    end

    local viewKey = tostring(ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey());
    if achievement.dps ~= nil then
        local required = tonumber(achievement.dps) or 0;
        local parses = ParseGraph.GetAchievementParses();
        for i = 1, #parses do
            local parse = parses[i];
            if parse ~= nil and (tonumber(parse.final) or 0) >= required then
                return {
                    date = tostring(parse.time or NowText()),
                    characterName = tostring(parse.__sourceName or ParseGraph.GetCharacterDisplayName(viewKey)),
                    characterKey = tostring(parse.__sourceKey or viewKey)
                };
            end
        end
    elseif achievement.parseCount ~= nil then
        local requiredCount = tonumber(achievement.parseCount) or 0;
        local records = {};

        local function addParses(key, name, parses)
            if type(parses) ~= "table" then return end
            for i = 1, #parses do
                local parse = parses[i];
                if parse ~= nil then
                    table.insert(records, {
                        date = tostring(parse.time or ""),
                        characterName = tostring(name or key),
                        characterKey = tostring(key or ""),
                        order = #records + 1
                    });
                end
            end
        end

        local characters = ParseGraph.AccountData and ParseGraph.AccountData.characters or {};
        for key, entry in pairs(characters) do
            key = tostring(key);
            if key ~= viewKey and type(entry) == "table" then
                addParses(key, entry.name or key, entry.parses);
            end
        end
        addParses(viewKey, ParseGraph.GetCharacterDisplayName(viewKey), ParseGraph.Parses);

        table.sort(records, function(a, b)
            if a.date == b.date then
                return (tonumber(a.order) or 0) < (tonumber(b.order) or 0);
            end
            if a.date == "" then return false end
            if b.date == "" then return true end
            return a.date < b.date;
        end);

        if requiredCount > 0 and records[requiredCount] ~= nil then
            return records[requiredCount];
        end
    elseif achievement.key == "theComebackArc" then
        return GetParseEarnedInfo(GetComebackArcParse());
    elseif achievement.key == "lateBloomer" then
        return GetParseEarnedInfo(GetLateBloomerParse());
    elseif achievement.key == "mathematicallySuspicious" then
        return GetParseEarnedInfo(GetMathematicallySuspiciousParse());
    end

    return nil;
end

function ParseGraph.BuildAchievementUnlockEntry(achievement)
    local earnedInfo = ParseGraph.GetAchievementFirstEarnedInfo(achievement) or {};
    return {
        unlocked = true,
        date = earnedInfo.date or NowText(),
        characterName = earnedInfo.characterName or ParseGraph.GetCurrentCharacterName(),
        characterKey = earnedInfo.characterKey or ParseGraph.GetCurrentCharacterKey()
    };
end

function ParseGraph.RepairAchievementUnlockInfo(achievement)
    if achievement == nil then
        return false;
    end

    local storage = ParseGraph.GetAchievementStorage(achievement);
    local entry = storage[achievement.key];
    if entry == nil then
        return false;
    end

    if entry == true then
        storage[achievement.key] = ParseGraph.BuildAchievementUnlockEntry(achievement);
        return true;
    end
    if type(entry) ~= "table" then
        return false;
    end

    local changed = false;
    if entry.unlocked ~= true then
        entry.unlocked = true;
        changed = true;
    end

    local earnedInfo = ParseGraph.GetAchievementFirstEarnedInfo(achievement);
    if type(earnedInfo) == "table" and earnedInfo.date ~= nil and tostring(earnedInfo.date) ~= "" then
        local currentDate = tostring(entry.date or "");
        if currentDate == "" or tostring(earnedInfo.date) < currentDate then
            entry.date = earnedInfo.date;
            entry.characterName = earnedInfo.characterName or entry.characterName;
            entry.characterKey = earnedInfo.characterKey or entry.characterKey;
            changed = true;
        end
    elseif entry.date == nil or tostring(entry.date) == "" then
        entry.date = NowText();
        changed = true;
    end

    if entry.characterName == nil or tostring(entry.characterName) == "" then
        entry.characterName = ParseGraph.GetCurrentCharacterName();
        changed = true;
    end
    if entry.characterKey == nil or tostring(entry.characterKey) == "" then
        entry.characterKey = ParseGraph.GetCurrentCharacterKey();
        changed = true;
    end

    return changed;
end

function ParseGraph.IsAchievementRecordedUnlocked(achievement)
    if achievement == nil then
        return false;
    end

    local storage = ParseGraph.GetAchievementStorage(achievement);
    local entry = storage[achievement.key];
    return entry == true or (type(entry) == "table" and entry.unlocked == true);
end

function ParseGraph.RecordAchievementUnlocked(achievement)
    if achievement == nil then
        return;
    end

    local storage = ParseGraph.GetAchievementStorage(achievement);
    if type(storage[achievement.key]) ~= "table" then
        storage[achievement.key] = ParseGraph.BuildAchievementUnlockEntry(achievement);
    else
        ParseGraph.RepairAchievementUnlockInfo(achievement);
    end
end

function ParseGraph.GetAchievementUnlockDate(achievement)
    if achievement == nil then
        return NowText();
    end

    local entry = nil;
    if ParseGraph.IsAccountWideAchievement(achievement) then
        local accountAchievements = ParseGraph.GetAccountAchievements();
        entry = accountAchievements[achievement.key];
    else
        entry = ParseGraph.GetViewAchievementEntry(achievement.key);
    end

    if type(entry) == "table" and entry.date ~= nil then
        return tostring(entry.date);
    end

    local earnedInfo = ParseGraph.GetAchievementFirstEarnedInfo(achievement);
    if type(earnedInfo) == "table" and earnedInfo.date ~= nil then
        return tostring(earnedInfo.date);
    end

    return NowText();
end

function ParseGraph.FormatAchievementPostDate(dateText)
    local year, month, day = string.match(tostring(dateText or ""), "^(%d%d%d%d)%-(%d%d)%-(%d%d)");
    if year ~= nil then
        return tostring(day) .. "-" .. tostring(month) .. "-" .. tostring(year);
    end
    return tostring(dateText or "");
end

function ParseGraph.GetAchievementUnlockCharacter(achievement)
    local entry = nil;
    if achievement ~= nil and ParseGraph.IsAccountWideAchievement(achievement) then
        local accountAchievements = ParseGraph.GetAccountAchievements();
        entry = accountAchievements[achievement.key];
    elseif achievement ~= nil then
        entry = ParseGraph.GetViewAchievementEntry(achievement.key);
    end

    if type(entry) == "table" and entry.characterName ~= nil and tostring(entry.characterName) ~= "" then
        return tostring(entry.characterName);
    end

    local earnedInfo = ParseGraph.GetAchievementFirstEarnedInfo(achievement);
    if type(earnedInfo) == "table" and earnedInfo.characterName ~= nil and tostring(earnedInfo.characterName) ~= "" then
        return tostring(earnedInfo.characterName);
    end

    return ParseGraph.GetCharacterDisplayName(ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey());
end

function ParseGraph.GetAchievementIcon(achievement)
    if achievement == nil then
        return "";
    end

    if ParseGraph.IsAchievementUnlocked(achievement.key) then
        return achievement.icon;
    end

    return string.gsub(tostring(achievement.icon or ""), "%.tga$", "_locked.tga");
end

function ParseGraph.PrintAchievementUnlocked(achievement)
    Turbine.Shell.WriteLine(
        "<rgb=#5DA9FF>ParseGraph</rgb>: <rgb=#FFB21A>Achievement unlocked!</rgb>\n"
        .. "<rgb=#FFB21A>" .. tostring(achievement.title or "") .. "</rgb>\n"
        .. "<rgb=#FFFFFF>" .. ParseGraph.GetAchievementDetailText(achievement) .. "</rgb>"
    );
end

function ParseGraph.FindAchievement(identifier)
    local needle = LowerClean(identifier or "");
    needle = string.gsub(needle, "^%s+", "");
    needle = string.gsub(needle, "%s+$", "");

    for categoryIndex = 1, #ParseGraph.AchievementCategories do
        local category = ParseGraph.AchievementCategories[categoryIndex];
        local data = ParseGraph.Achievements[category.key];
        local items = data and data.items or {};
        for i = 1, #items do
            local achievement = items[i];
            if needle == "" then
                return achievement;
            end
            if needle == LowerClean(achievement.key)
                or needle == LowerClean(achievement.title)
                or needle == LowerClean(category.key) then
                return achievement;
            end
        end
    end

    return ParseGraph.Achievements.special.items[1];
end

function ParseGraph.IsAchievementEarned(achievement)
    if achievement == nil then
        return false;
    end

    if achievement.parseCount ~= nil then
        return ParseGraph.GetAccountParseCount() >= achievement.parseCount;
    end

    if achievement.dps ~= nil then
        local highest = ParseGraph.GetHighestParsePointFromParses(ParseGraph.GetAchievementParses());
        return (tonumber(highest.value) or 0) >= achievement.dps;
    end

    if achievement.key == "weeklyWarrior" then
        return HasConsecutiveParseDayStreak(7);
    elseif achievement.key == "seekHelp" then
        return HasConsecutiveParseDayStreak(30);
    elseif achievement.key == "sequentialDamage" then
        local parses = ParseGraph.GetAchievementParses();
        for i = 1, #parses do
            if Round(parses[i].final) == 123456 then
                return true;
            end
        end
    elseif achievement.key == "dejaVu" then
        local seen = {};
        local parses = ParseGraph.GetAchievementParses();
        for i = 1, #parses do
            local value = Round(parses[i].final);
            if seen[value] == true then
                return true;
            end
            seen[value] = true;
        end
    elseif achievement.key == "surelyTheNextOne" or achievement.key == "finally" then
        local best = 0;
        local drySpell = 0;
        local foundDrySpell = false;
        local foundFinally = false;
        local parses = ParseGraph.GetAchievementParses();
        for i = 1, #parses do
            local value = tonumber(parses[i].final) or 0;
            if value > best then
                if best > 0 and drySpell >= 100 then
                    foundFinally = true;
                end
                best = value;
                drySpell = 0;
            else
                drySpell = drySpell + 1;
                if drySpell >= 100 then
                    foundDrySpell = true;
                end
            end
        end

        if achievement.key == "surelyTheNextOne" then
            return foundDrySpell;
        end
        return foundFinally;
    elseif achievement.key == "oneAndDone" then
        return GetOneAndDoneParse() ~= nil;
    elseif achievement.key == "soCloseItHurts" then
        return HasNearPersonalBestMiss(0.001);
    elseif achievement.key == "refuelRequired" then
        return HasParsesInOneDay(50);
    elseif achievement.key == "touchGrassReminder" then
        return HasParsesInOneDay(100);
    elseif achievement.key == "flatlined" then
        return HasFlatParseRun(10, 0.02);
    elseif achievement.key == "theComebackArc" then
        return GetComebackArcParse() ~= nil;
    elseif achievement.key == "lateBloomer" then
        return GetLateBloomerParse() ~= nil;
    elseif achievement.key == "weGoAgain" then
        return (tonumber(ParseGraph.SessionDiscardCount) or 0) >= 10;
    elseif achievement.key == "weDontTalkAboutThose" then
        return GetAchievementDiscardCount() >= 100;
    elseif achievement.key == "mathematicallySuspicious" then
        return GetMathematicallySuspiciousParse() ~= nil;
    end

    return false;
end

function ParseGraph.SyncAchievements(announce)
    if type(ParseGraph.UnlockedAchievements) ~= "table" then
        ParseGraph.UnlockedAchievements = {};
    end

    local changed = false;
    local previousSyncing = ParseGraph.SyncingAchievements;
    ParseGraph.SyncingAchievements = true;
    for categoryIndex = 1, #ParseGraph.AchievementCategories do
        local category = ParseGraph.AchievementCategories[categoryIndex];
        local data = ParseGraph.Achievements[category.key];
        local items = data and data.items or {};
        for i = 1, #items do
            local achievement = items[i];
            if ParseGraph.IsAchievementRecordedUnlocked(achievement) then
                if ParseGraph.RepairAchievementUnlockInfo(achievement) then
                    changed = true;
                end
            elseif ParseGraph.IsAchievementEarned(achievement) then
                ParseGraph.RecordAchievementUnlocked(achievement);
                changed = true;
                if announce then
                    ParseGraph.PrintAchievementUnlocked(achievement);
                    ParseGraph.ShowAchievementPopup(achievement);
                end
            end
        end
    end
    ParseGraph.SyncingAchievements = previousSyncing;

    return changed;
end

function ParseGraph.GetAverages()
    local parses = ParseGraph.GetViewParses();
    local count = #parses;
    if count == 0 then return 0, 0, 0, 0 end
    local total, m1, m2, m3 = 0, 0, 0, 0;
    local c1, c2, c3 = 0, 0, 0;
    for i = 1, count do
        local p = parses[i];
        total = total + (tonumber(p.final) or 0);
        if p.minutes and tonumber(p.minutes[1]) then m1 = m1 + tonumber(p.minutes[1]); c1 = c1 + 1 end
        if p.minutes and tonumber(p.minutes[2]) then m2 = m2 + tonumber(p.minutes[2]); c2 = c2 + 1 end
        if p.minutes and tonumber(p.minutes[3]) then m3 = m3 + tonumber(p.minutes[3]); c3 = c3 + 1 end
    end
    return total / count, c1 > 0 and m1 / c1 or 0, c2 > 0 and m2 / c2 or 0, c3 > 0 and m3 / c3 or 0;
end

function ParseGraph.GetHighestParse()
    local highest = ParseGraph.GetHighestParsePoint();
    return highest.value;
end

function ParseGraph.GetHighestParsePointFromParses(parses)
    local highest = 0;
    local highestIndex = nil;
    parses = parses or {};
    for i = 1, #parses do
        local value = tonumber(parses[i].final);
        if value ~= nil and value >= highest then
            highest = value;
            highestIndex = i;
        end
    end
    return { value = highest, index = highestIndex };
end

function ParseGraph.GetHighestParsePoint()
    return ParseGraph.GetHighestParsePointFromParses(ParseGraph.GetViewParses());
end

function ParseGraph.FormatGraphMin(value)
    value = tonumber(value) or 0;
    if value == 0 then
        return "0";
    end
    return FormatNumber(value);
end

function ParseGraph.SetGraphMin(value)
    value = tonumber(value) or 100000;
    value = math.floor((value / ParseGraph.GraphMinStep) + 0.5) * ParseGraph.GraphMinStep;
    if value < ParseGraph.GraphMinMin then
        value = ParseGraph.GraphMinMin;
    elseif value > ParseGraph.GraphMinMax then
        value = ParseGraph.GraphMinMax;
    end
    ParseGraph.GraphMin = value;
    ParseGraph.Save(false, ParseGraph.ViewCharacterKey ~= ParseGraph.GetCurrentCharacterKey());
    ParseGraph.Refresh();
end

function ParseGraph.GetGraphMinIndex()
    local value = tonumber(ParseGraph.GraphMin) or 100000;
    value = math.max(ParseGraph.GraphMinMin, math.min(ParseGraph.GraphMinMax, value));
    return math.floor((value - ParseGraph.GraphMinMin) / ParseGraph.GraphMinStep) + 1;
end

function ParseGraph.UpdateGraphMinDropdownText()
    if ParseGraph.GraphMinValueButton ~= nil then
        ParseGraph.GraphMinValueButton:SetText(ParseGraph.FormatGraphMin(ParseGraph.GraphMin));
    end
end

function ParseGraph.ChangeGraphMin(delta)
    local value = (tonumber(ParseGraph.GraphMin) or 100000) + ((tonumber(delta) or 0) * ParseGraph.GraphMinStep);
    if value < ParseGraph.GraphMinMin then
        value = ParseGraph.GraphMinMax;
    elseif value > ParseGraph.GraphMinMax then
        value = ParseGraph.GraphMinMin;
    end

    ParseGraph.SetGraphMin(value);
    ParseGraph.UpdateGraphMinDropdownText();
end

function ParseGraph.GetTodayDatePrefix()
    local d = Turbine.Engine.GetDate();
    if d ~= nil and d.Month ~= nil then
        return string.format("%04d-%02d-%02d", d.Year, d.Month, d.Day);
    end
    return string.sub(NowText(), 1, 10);
end

function ParseGraph.ParseIsToday(parse)
    return GetParseResetDayNumber(parse) == GetCurrentResetDayNumber();
end

function ParseGraph.ShouldDisplayParse(parse, index)
    if not ParseGraph.ParseMatchesSpecFilter(parse) then
        return false;
    end

    local mode = NormalizeShowMode(ParseGraph.ShowMode);
    if mode == "session" then
        return (tonumber(index) or 0) > (tonumber(ParseGraph.SessionStartCount) or 0);
    elseif mode == "today" then
        return ParseGraph.ParseIsToday(parse);
    end
    return true;
end

function ParseGraph.GetDisplayedParsePoints(maxShown, sourceParses)
    local points = {};
    local mode = NormalizeShowMode(ParseGraph.ShowMode);
    local parses = sourceParses or (mode == "session" and (ParseGraph.Parses or {}) or ParseGraph.GetViewParses());
    points.sourceParses = parses;
    -- The graph and recent list only need the newest matching records.
    if type(maxShown) == "number" and maxShown >= 0 and maxShown == math.floor(maxShown) then
        if maxShown == 0 then return points end
        for i = #parses, 1, -1 do
            if ParseGraph.ShouldDisplayParse(parses[i], i) then
                points[#points + 1] = { index = i, parse = parses[i] };
                if #points >= maxShown then break end
            end
        end
        for i = 1, math.floor(#points / 2) do
            local opposite = #points - i + 1;
            points[i], points[opposite] = points[opposite], points[i];
        end
        return points;
    end
    for i = 1, #parses do
        local parse = parses[i];
        if ParseGraph.ShouldDisplayParse(parse, i) then
            table.insert(points, { index = i, parse = parse });
        end
    end

    if maxShown ~= nil and #points > maxShown then
        local trimmed = {};
        trimmed.sourceParses = parses;
        for i = #points - maxShown + 1, #points do
            table.insert(trimmed, points[i]);
        end
        return trimmed;
    end

    return points;
end

function ParseGraph.GetParseHistoryPoints(maxShown)
    local points = {};
    local parses = ParseGraph.GetViewParses();
    points.sourceParses = parses;
    local firstIndex = 1;
    if type(maxShown) == "number" and maxShown >= 0 and maxShown == math.floor(maxShown) then
        firstIndex = math.max(1, #parses - maxShown + 1);
    end
    for i = firstIndex, #parses do
        local parse = parses[i];
        local sourceIndex = tonumber(parse and parse.__sourceIndex) or i;
        table.insert(points, {
            index = sourceIndex,
            parse = parse,
            sourceKey = parse and parse.__sourceKey or ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey(),
            sourceIndex = sourceIndex,
            sourceName = parse and parse.__sourceName
        });
    end

    if maxShown ~= nil and #points > maxShown then
        local trimmed = {};
        trimmed.sourceParses = parses;
        for i = #points - maxShown + 1, #points do
            table.insert(trimmed, points[i]);
        end
        return trimmed;
    end

    return points;
end

function ParseGraph.GetViewedClassKey()
    local entry = ParseGraph.GetViewCharacterEntry();
    local classKey = ParseGraph.GetCharacterClassKey(entry);
    if classKey ~= nil and classKey ~= "" then
        return classKey;
    end

    local classInfo = ParseGraph.GetCurrentPlayerClassInfo();
    if classInfo ~= nil and classInfo.key ~= nil then
        return LowerClean(classInfo.key);
    end

    return "";
end

function ParseGraph.GetParsePointClassKey(point)
    if type(point) ~= "table" then
        return "";
    end

    local parse = point.parse;
    local parseClassKey = parse ~= nil and tostring(parse.__classKey or "") or "";
    if parseClassKey ~= "" then
        return LowerClean(parseClassKey);
    end

    local pointClassKey = tostring(point.classKey or "");
    if pointClassKey ~= "" then
        return LowerClean(pointClassKey);
    end

    local sourceKey = tostring(point.sourceKey or (parse and parse.__sourceKey) or "");
    local entry = ParseGraph.AccountData and ParseGraph.AccountData.characters and ParseGraph.AccountData.characters[sourceKey] or nil;
    local classKey = ParseGraph.GetCharacterClassKey(entry);
    return classKey or "";
end

function ParseGraph.GetParsePointClassIcon(point)
    if type(point) ~= "table" then
        return nil;
    end

    local parse = point.parse;
    local sourceKey = tostring(point.sourceKey or (parse and parse.__sourceKey) or "");
    local entry = ParseGraph.AccountData and ParseGraph.AccountData.characters and ParseGraph.AccountData.characters[sourceKey] or nil;
    local classKey = ParseGraph.GetParsePointClassKey(point);
    local icon = tostring((parse and parse.__classIcon) or point.classIcon or (entry and entry.classIcon) or "");
    return NormalizeClassIconPath(icon, classKey);
end

function ParseGraph.NormalizeParseSpecKey(specKey)
    local key = LowerClean(specKey or "");
    key = string.gsub(key, "^%s+", "");
    key = string.gsub(key, "%s+$", "");
    if key == "b" then key = "blue"; end
    if key == "r" then key = "red"; end
    if key == "y" then key = "yellow"; end
    if key == "blue" or key == "red" or key == "yellow" then
        return key;
    end
    return nil;
end

function ParseGraph.GetCurrentPlayerClassId()
    local ok, player = pcall(function()
        if Turbine.Gameplay ~= nil and Turbine.Gameplay.LocalPlayer ~= nil then
            return Turbine.Gameplay.LocalPlayer.GetInstance();
        end
        return nil;
    end);
    if not ok or player == nil or player.GetClass == nil then
        return nil;
    end

    local okClass, classId = pcall(function()
        return player:GetClass();
    end);
    if okClass then
        return classId;
    end
    return nil;
end

function ParseGraph.ClassMatches(playerClass, ...)
    if playerClass == nil then
        return false;
    end

    for i = 1, select("#", ...) do
        local classId = select(i, ...);
        if classId ~= nil and playerClass == classId then
            return true;
        end
    end
    return false;
end

function ParseGraph.SpecTextContains(message, needle)
    local haystack = LowerClean(message or "");
    local text = LowerClean(needle or "");
    return text ~= "" and string.find(haystack, text, 1, true) ~= nil;
end

function ParseGraph.GetSpecDetectionFromText(message, playerClass)
    if message == nil then
        return nil, nil;
    end
    if playerClass == nil then
        playerClass = ParseGraph.GetCurrentPlayerClassId();
    end

    local classes = Turbine.Gameplay and Turbine.Gameplay.Class or {};
    local function Has(needle)
        return ParseGraph.SpecTextContains(message, needle);
    end

    -- This mirrors Prime's RoleHandler: line 1 = Blue, 2 = Red, 3 = Yellow.
    if ParseGraph.ClassMatches(playerClass, classes.Beorning) then
        if Has("The Hide") or Has("Counter") then return "blue", 1; end
        if Has("The Claw") or Has("Expose (Man)") then return "red", 4; end
        if Has("The Roar") or Has("Mark of Grimbeorn") then return "yellow", 2; end
    elseif ParseGraph.ClassMatches(playerClass, classes.Brawler) then
        if Has("Fulcrum") or Has("Come At Me") then return "blue", 1; end
        if Has("Maelstrom") or Has("Shattering Fist") then return "red", 4; end
    elseif ParseGraph.ClassMatches(playerClass, classes.Burglar) then
        if Has("Gambler") or Has("Lucky Strike") then return "blue", 4; end
        if Has("Quiet Knife") or Has("Feint Attack") then return "red", 4; end
        if Has("Mischief-maker") or Has("Trick: Enrage") then return "yellow", 3; end
    elseif ParseGraph.ClassMatches(playerClass, classes.Champion) then
        if Has("Martial Champion") or Has("Sudden Defence") or Has("Der Meister der Kampfkunst") then return "blue", 1; end
        if Has("The Berserker") or Has("Remorseless Strike") or Has("Der Berserker") then return "red", 4; end
        if Has("The Deadly Storm") or Has("Blade Storm") then return "yellow", 4; end
    elseif ParseGraph.ClassMatches(playerClass, classes.Captain) then
        if Has("Hands of Healing") or Has("Valiant Strike") then return "blue", 2; end
        if Has("Lead the Charge") or Has("Shadow's Lament") then return "red", 4; end
        if Has("Leader of Men") or Has("Elendil's Roar") then return "yellow", 1; end
    elseif ParseGraph.ClassMatches(playerClass, classes.Mariner, classes.Corsair) then
        if Has("Shanty-caller") or Has("Dramatic Flourish") then return "blue", 3; end
        if Has("Duellist") or Has("Feint") then return "red", 4; end
        if Has("Rover") or Has("Draining Strike") then return "yellow", 3; end
    elseif ParseGraph.ClassMatches(playerClass, classes.Guardian) then
        if Has("Defender of the Free") or Has("Litany of Defiance") or Has("Der Verteidiger der Freien") then return "blue", 1; end
        if Has("Keen") or Has("Overwhelm") then return "red", 4; end
    elseif ParseGraph.ClassMatches(playerClass, classes.Hunter) then
        if Has("Huntsman") or Has("Barrage") then return "blue", 4; end
        if Has("Bowmaster") or Has("Long Shot") then return "red", 4; end
        if Has("Trapper of Foes") or Has("Kingsfoil Knowledge") then return "yellow", 4; end
    elseif ParseGraph.ClassMatches(playerClass, classes.LoreMaster) then
        if Has("Keeper of Animals") or Has("Sign of the Wild: Rage") then return "blue", 3; end
        if Has("Master of Nature") then return "red", 4; end
        if Has("Ancient Master") or Has("Test of Will") then return "yellow", 3; end
    elseif ParseGraph.ClassMatches(playerClass, classes.Minstrel) then
        if Has("Watcher of Resolve") or Has("Soliloquy of Spirit") then return "blue", 2; end
        if Has("Warrior-skald") or Has("Call to Fate") then return "red", 4; end
    elseif ParseGraph.ClassMatches(playerClass, classes.RuneKeeper) then
        if Has("Benedictions of Peace") or Has("Writ of Health") then return "blue", 2; end
        if Has("Cleansing Flame") or Has("Writ of Fire") then return "red", 4; end
        if Has("Thunder") or Has("Writ of Lightning") then return "yellow", 4; end
    elseif ParseGraph.ClassMatches(playerClass, classes.Warden) then
        if Has("Determination") or Has("Warning Shot") then return "blue", 1; end
        if Has("Recklessness") then return "red", 4; end
    end

    return nil, nil;
end

function ParseGraph.ApplyDetectedSpec(specKey, roleId, reason)
    local key = ParseGraph.NormalizeParseSpecKey(specKey);
    if key == nil then
        return false;
    end

    local changed = ParseGraph.CurrentSpecKey ~= key or tonumber(ParseGraph.CurrentSpecRole) ~= (tonumber(roleId) or 0);
    ParseGraph.CurrentSpecKey = key;
    ParseGraph.CurrentSpecRole = tonumber(roleId) or 0;
    ParseGraph.CurrentSpecReason = tostring(reason or "detected");
    if Turbine.Engine ~= nil and Turbine.Engine.GetGameTime ~= nil then
        ParseGraph.CurrentSpecDetectedAt = Turbine.Engine.GetGameTime();
    end

    if changed then
        ParseGraph.SaveSpecDetectionData();
        if ParseGraph.Debug then
            Turbine.Shell.WriteLine("ParseGraph: detected spec " .. tostring(key) .. ".");
        end
    end
    return true;
end

function ParseGraph.DetectSpecFromText(message, reason)
    local specKey, roleId = ParseGraph.GetSpecDetectionFromText(message);
    if specKey ~= nil then
        return ParseGraph.ApplyDetectedSpec(specKey, roleId, reason);
    end
    return false;
end

function ParseGraph.SaveSpecDetectionData()
    local data = {
        specKey = ParseGraph.CurrentSpecKey,
        role = tonumber(ParseGraph.CurrentSpecRole) or 0,
        name = ParseGraph.GetPlayerName and ParseGraph.GetPlayerName() or "",
        server = _G.ServerName or ""
    };
    pcall(function()
        Turbine.PluginData.Save(Turbine.DataScope.Character, ParseGraph.SpecDataSaveKey, data);
    end);
end

function ParseGraph.LoadSpecDetectionData()
    local ok, data = pcall(function()
        return Turbine.PluginData.Load(Turbine.DataScope.Character, ParseGraph.SpecDataSaveKey);
    end);
    if ok and type(data) == "table" then
        ParseGraph.CurrentSpecKey = ParseGraph.NormalizeParseSpecKey(data.specKey);
        ParseGraph.CurrentSpecRole = tonumber(data.role) or 0;
    end

    local okPrime, primeData = pcall(function()
        return Turbine.PluginData.Load(Turbine.DataScope.Character, "PrimeGroupParseLineData");
    end);
    if okPrime and type(primeData) == "table" then
        local primeKey = ParseGraph.NormalizeParseSpecKey(primeData.Line);
        if primeKey ~= nil then
            ParseGraph.CurrentSpecKey = primeKey;
        end
    end
end

function ParseGraph.ScanTrainedSkillsForSpec()
    local ok, player = pcall(function()
        if Turbine.Gameplay ~= nil and Turbine.Gameplay.LocalPlayer ~= nil then
            return Turbine.Gameplay.LocalPlayer.GetInstance();
        end
        return nil;
    end);
    if not ok or player == nil or player.GetTrainedSkills == nil then
        return false;
    end

    local playerClass = ParseGraph.GetCurrentPlayerClassId();
    local okSkills, trainedSkills = pcall(function()
        return player:GetTrainedSkills();
    end);
    if not okSkills or trainedSkills == nil or trainedSkills.GetCount == nil then
        return false;
    end

    local okCount, count = pcall(function()
        return trainedSkills:GetCount();
    end);
    if not okCount then
        return false;
    end

    local detectedSpecKey = nil;
    local detectedRoleId = nil;
    for i = 1, (tonumber(count) or 0) do
        local okItem, item = pcall(function()
            return trainedSkills:GetItem(i);
        end);
        if okItem and item ~= nil and item.GetSkillInfo ~= nil then
            local okInfo, info = pcall(function()
                return item:GetSkillInfo();
            end);
            if okInfo and info ~= nil and info.GetName ~= nil then
                local okName, name = pcall(function()
                    return info:GetName();
                end);
                if okName and name ~= nil then
                    local specKey, roleId = ParseGraph.GetSpecDetectionFromText(name, playerClass);
                    if specKey ~= nil then
                        detectedSpecKey = specKey;
                        detectedRoleId = roleId;
                    end
                end
            end
        end
    end
    if detectedSpecKey ~= nil then
        return ParseGraph.ApplyDetectedSpec(detectedSpecKey, detectedRoleId, "trained skill");
    end
    return false;
end

function ParseGraph.InitializeSpecDetection()
    ParseGraph.LoadSpecDetectionData();
    ParseGraph.ScanTrainedSkillsForSpec();
end

function ParseGraph.GetCurrentDetectedSpecKey()
    ParseGraph.ScanTrainedSkillsForSpec();
    return ParseGraph.NormalizeParseSpecKey(ParseGraph.CurrentSpecKey);
end

function ParseGraph.GetParseSpecDefinition(specKey)
    local key = ParseGraph.NormalizeParseSpecKey(specKey);
    if key == nil then
        return nil;
    end

    local options = ParseGraph.SpecOptions or {};
    for i = 1, #options do
        if options[i].key == key then
            return options[i];
        end
    end
    return nil;
end

function ParseGraph.GetParseSpecKey(parseOrPoint)
    if type(parseOrPoint) ~= "table" then
        return nil;
    end

    local parse = parseOrPoint.parse;
    if type(parse) ~= "table" then
        parse = parseOrPoint;
    end

    return ParseGraph.NormalizeParseSpecKey(parse.specKey or parse.spec or parseOrPoint.specKey or parseOrPoint.spec);
end

function ParseGraph.GetParseSpecIconPath(parseOrPoint)
    local spec = ParseGraph.GetParseSpecDefinition(ParseGraph.GetParseSpecKey(parseOrPoint));
    if spec ~= nil and spec.icon ~= nil then
        return (ParseGraph.SpecIconPath or "") .. tostring(spec.icon);
    end
    return (ParseGraph.SpecIconPath or "") .. "spec_none.tga";
end

function ParseGraph.SetParseSpec(point, specKey)
    if type(point) ~= "table" then
        return false;
    end

    local key = ParseGraph.NormalizeParseSpecKey(specKey);
    if key == nil then
        return false;
    end

    local currentKey = ParseGraph.GetCurrentCharacterKey();
    local sourceKey = tostring(point.sourceKey or (point.parse and point.parse.__sourceKey) or ParseGraph.ViewCharacterKey or currentKey);
    local sourceIndex = tonumber(point.sourceIndex or (point.parse and point.parse.__sourceIndex) or point.index) or 0;
    local parse = ParseGraph.GetParseBySource(sourceKey, sourceIndex) or point.parse;
    if type(parse) ~= "table" then
        return false;
    end

    parse.specKey = key;
    if type(point.parse) == "table" then
        point.parse.specKey = key;
    end

    if ParseGraph.IsImportedParse({ sourceKey = sourceKey, parse = parse }) then
        ParseGraph.SaveAccountData();
    else
        ParseGraph.Save(false, sourceKey ~= currentKey);
    end

    if ParseGraph.CurrentView == "history" then
        ParseGraph.DrawParseHistoryView();
    else
        ParseGraph.Refresh();
    end
    return true;
end

function ParseGraph.NormalizeParseSpecFilterKey(specKey)
    local key = tostring(specKey or "all");
    if LowerClean(key) == "all" or key == "" then
        return "all";
    end
    return ParseGraph.NormalizeParseSpecKey(key) or "all";
end

function ParseGraph.GetParseSpecFilterLabel(specKey)
    local key = ParseGraph.NormalizeParseSpecFilterKey(specKey or ParseGraph.ParseSpecFilterKey);
    if key == "all" then
        return "All";
    end
    local spec = ParseGraph.GetParseSpecDefinition(key);
    if spec ~= nil and spec.label ~= nil then
        return tostring(spec.label);
    end
    return "All";
end

function ParseGraph.ParseMatchesSpecFilter(parse, filterKey)
    local key = ParseGraph.NormalizeParseSpecFilterKey(filterKey or ParseGraph.ParseSpecFilterKey);
    if key == "all" then
        return true;
    end
    return ParseGraph.GetParseSpecKey(parse) == key;
end

function ParseGraph.GetSpecFilteredParses(parses, filterKey)
    local key = ParseGraph.NormalizeParseSpecFilterKey(filterKey or ParseGraph.ParseSpecFilterKey);
    parses = parses or {};
    if key == "all" then
        return parses;
    end

    local filtered = {};
    for i = 1, #parses do
        local parse = parses[i];
        if ParseGraph.ParseMatchesSpecFilter(parse, key) then
            table.insert(filtered, parse);
        end
    end
    return filtered;
end

function ParseGraph.UpdateParseSpecFilterButtonText()
    if ParseGraph.ParseSpecFilterButton ~= nil and ParseGraph.ParseSpecFilterButton.actionButtonLabel ~= nil then
        ParseGraph.ParseSpecFilterButton.actionButtonLabel:SetText(ParseGraph.GetParseSpecFilterLabel());
    end
end

function ParseGraph.SetParseSpecFilter(specKey)
    ParseGraph.ParseSpecFilterKey = ParseGraph.NormalizeParseSpecFilterKey(specKey);
    ParseGraph.UpdateParseSpecFilterButtonText();
    ParseGraph.Refresh();
end

function ParseGraph.GetCompareSelectionClassKey(selection)
    if type(selection) ~= "table" then
        return "";
    end

    local classKey = tostring(selection.classKey or "");
    if classKey ~= "" then
        return LowerClean(classKey);
    end

    return ParseGraph.GetParsePointClassKey(selection);
end

function ParseGraph.ParsePointMatchesViewedClass(point)
    local viewedClassKey = ParseGraph.GetViewedClassKey();
    if viewedClassKey == "" then
        return true;
    end

    local pointClassKey = ParseGraph.GetParsePointClassKey(point);
    return pointClassKey == viewedClassKey;
end

function ParseGraph.CanCompareParsePoint(point)
    return type(point) == "table" and point.parse ~= nil;
end

function ParseGraph.GetClassParseHistoryPoints(maxShown)
    local points = {};
    local viewedClassKey = ParseGraph.GetViewedClassKey();
    local currentKey = ParseGraph.GetCurrentCharacterKey();
    local viewKey = tostring(ParseGraph.ViewCharacterKey or currentKey);
    local characters = ParseGraph.AccountData and ParseGraph.AccountData.characters or {};
    local seen = {};

    local function addCharacter(key, entry, sourceParses)
        key = tostring(key or "");
        if key == "" or seen[key] == true or type(entry) ~= "table" or type(sourceParses) ~= "table" then
            return;
        end

        entry = NormalizeCharacterData(entry, key, entry.name);
        local classKey = ParseGraph.GetCharacterClassKey(entry) or "";
        if viewedClassKey ~= "" and classKey ~= viewedClassKey then
            return;
        end

        seen[key] = true;
        local sourceName = entry.name or key;
        for i = 1, #sourceParses do
            local parse = CopyShallow(sourceParses[i]);
            parse.__sourceKey = key;
            parse.__sourceName = sourceName;
            parse.__sourceIndex = i;
            parse.__classKey = classKey;
            table.insert(points, {
                index = i,
                parse = parse,
                sourceKey = key,
                sourceIndex = i,
                sourceName = sourceName
            });
        end
    end

    addCharacter(viewKey, ParseGraph.GetViewCharacterEntry(), ParseGraph.Parses or {});
    for key, entry in pairs(characters) do
        if key ~= viewKey then
            addCharacter(key, entry, entry.parses or {});
        end
    end

    table.sort(points, function(a, b)
        local at = tostring(a and a.parse and a.parse.time or "");
        local bt = tostring(b and b.parse and b.parse.time or "");
        if at == bt then
            local ak = tostring(a and a.sourceKey or "");
            local bk = tostring(b and b.sourceKey or "");
            if ak == bk then
                return (tonumber(a and a.sourceIndex) or 0) < (tonumber(b and b.sourceIndex) or 0);
            end
            return ak < bk;
        end
        if at == "" then return false end
        if bt == "" then return true end
        return at < bt;
    end);

    if maxShown ~= nil and #points > maxShown then
        local trimmed = {};
        for i = #points - maxShown + 1, #points do
            table.insert(trimmed, points[i]);
        end
        return trimmed;
    end

    return points;
end

