function ParseGraph.GetFavouriteParseHistoryPoints()
    local favourites = {};
    local points = ParseGraph.GetAllCharacterParseHistoryPoints(10000);
    for i = 1, #points do
        local parse = points[i].parse;
        if type(parse) == "table" and parse.favorite == true then
            table.insert(favourites, points[i]);
        end
    end

    local imported = ParseGraph.GetImportedParseHistoryPoints();
    for i = 1, #imported do
        local point = imported[i];
        local parse = point ~= nil and point.parse or nil;
        if type(parse) == "table" and parse.favorite == true then
            table.insert(favourites, point);
        end
    end

    table.sort(favourites, function(a, b)
        local at = tostring(a and a.parse and a.parse.time or "");
        local bt = tostring(b and b.parse and b.parse.time or "");
        if at == bt then
            local ak = tostring(a and a.sourceKey or "");
            local bk = tostring(b and b.sourceKey or "");
            if ak == bk then
                return (tonumber(a and a.sourceIndex) or 0) < (tonumber(b and b.sourceIndex) or 0);
            end
            return ak < bk;
        end
        if at == "" then return false end
        if bt == "" then return true end
        return at < bt;
    end);

    return favourites;
end

function ParseGraph.GetImportedParseHistoryPoints()
    local imported = {};
    local source = ParseGraph.ImportedParses or {};
    imported.sourceParses = source;
    for i = 1, #source do
        local point = source[i];
        if type(point) == "table" and point.parse ~= nil then
            table.insert(imported, point);
        end
    end
    return imported;
end

function ParseGraph.GetParseHistoryPointName(point)
    if type(point) ~= "table" then
        return "";
    end

    local parse = point.parse;
    local name = tostring(point.sourceName or (parse and parse.__sourceName) or (parse and parse.character) or "");
    if name ~= "" then
        return name;
    end

    local sourceKey = tostring(point.sourceKey or (parse and parse.__sourceKey) or "");
    local entry = ParseGraph.AccountData and ParseGraph.AccountData.characters and ParseGraph.AccountData.characters[sourceKey] or nil;
    name = tostring(entry and entry.name or "");
    if name ~= "" then
        return name;
    end

    return sourceKey;
end

function ParseGraph.GetParseHistoryPointClassName(point)
    if type(point) ~= "table" then
        return "";
    end

    local parse = point.parse;
    local className = tostring((parse and parse.__className) or point.className or "");
    if className ~= "" then
        return className;
    end

    local sourceKey = tostring(point.sourceKey or (parse and parse.__sourceKey) or "");
    local entry = ParseGraph.AccountData and ParseGraph.AccountData.characters and ParseGraph.AccountData.characters[sourceKey] or nil;
    className = tostring(entry and entry.className or "");
    if className ~= "" then
        return className;
    end

    return ParseGraph.GetParsePointClassKey(point) or "";
end

function ParseGraph.GetParseHistorySortValue(point, sortKey)
    sortKey = tostring(sortKey or "number");
    local parse = type(point) == "table" and point.parse or nil;

    if sortKey == "final" then
        return tonumber(parse and parse.final) or 0, true;
    elseif sortKey == "name" then
        return LowerClean(ParseGraph.GetParseHistoryPointName(point)), false;
    elseif sortKey == "class" then
        return LowerClean(ParseGraph.GetParseHistoryPointClassName(point)), false;
    end

    return tonumber(point and (point.sourceIndex or point.index) or nil) or tonumber(parse and parse.__sourceIndex) or 0, true;
end

function ParseGraph.SortParseHistoryPoints(points)
    local sorted = {};
    if type(points) ~= "table" then
        return sorted;
    end

    for i = 1, #points do
        sorted[i] = points[i];
    end

    local sortKey = tostring(ParseGraph.ParseHistorySortKey or "number");
    if sortKey ~= "number" and sortKey ~= "final" and sortKey ~= "name" and sortKey ~= "class" then
        sortKey = "number";
    end

    local descending = ParseGraph.ParseHistorySortDescending ~= false;
    table.sort(sorted, function(a, b)
        local av, numeric = ParseGraph.GetParseHistorySortValue(a, sortKey);
        local bv = ParseGraph.GetParseHistorySortValue(b, sortKey);
        if av == bv then
            local at = tostring(a and a.parse and a.parse.time or "");
            local bt = tostring(b and b.parse and b.parse.time or "");
            if at ~= bt then
                return at > bt;
            end

            local an = tonumber(a and (a.sourceIndex or a.index) or nil) or 0;
            local bn = tonumber(b and (b.sourceIndex or b.index) or nil) or 0;
            if an ~= bn then
                return an > bn;
            end

            return tostring(a and a.sourceKey or "") < tostring(b and b.sourceKey or "");
        end

        if numeric == true then
            if descending then
                return av > bv;
            end
            return av < bv;
        end

        av = tostring(av or "");
        bv = tostring(bv or "");
        if descending then
            return av > bv;
        end
        return av < bv;
    end);

    return sorted;
end

function ParseGraph.SetShowMode(mode)
    ParseGraph.ShowMode = NormalizeShowMode(mode);
    ParseGraph.Save(false, ParseGraph.ViewCharacterKey ~= ParseGraph.GetCurrentCharacterKey());
    ParseGraph.Refresh();
end

function ParseGraph.UpdateShowModeButtons()
    if ParseGraph.ShowSessionButton == nil or ParseGraph.ShowTodayButton == nil or ParseGraph.ShowAllButton == nil then
        return;
    end

    local mode = NormalizeShowMode(ParseGraph.ShowMode);
    if ParseGraph.ShowSessionButton.isActionButton == true then
        ParseGraph.SetActionButtonSelected(ParseGraph.ShowSessionButton, mode == "session");
        ParseGraph.SetActionButtonSelected(ParseGraph.ShowTodayButton, mode == "today");
        ParseGraph.SetActionButtonSelected(ParseGraph.ShowAllButton, mode == "all");
    elseif ParseGraph.ShowSessionButton.isSidebarButton == true then
        ParseGraph.SetSidebarButtonSelected(ParseGraph.ShowSessionButton, mode == "session");
        ParseGraph.SetSidebarButtonSelected(ParseGraph.ShowTodayButton, mode == "today");
        ParseGraph.SetSidebarButtonSelected(ParseGraph.ShowAllButton, mode == "all");
    else
        ParseGraph.ShowSessionButton:SetEnabled(mode ~= "session");
        ParseGraph.ShowTodayButton:SetEnabled(mode ~= "today");
        ParseGraph.ShowAllButton:SetEnabled(mode ~= "all");
    end
end

function ParseGraph.GetPostChannelInfo(channel)
    local normalized = NormalizePostChannel(channel or ParseGraph.PostChannel);
    for i = 1, #ParseGraph.PostChannels do
        if ParseGraph.PostChannels[i].key == normalized then
            if normalized == "faillowship" and ParseGraph.FaillowshipCommand ~= nil then
                ParseGraph.PostChannels[i].command = tostring(ParseGraph.FaillowshipCommand);
            end
            return ParseGraph.PostChannels[i];
        end
    end
    return ParseGraph.PostChannels[1];
end

function ParseGraph.GetPostChannelIcon(channel)
    local key = tostring(channel or "say");
    local base = ParseGraph.GeneralIconPath or "";

    if key == "fellowship" then
        return base .. "fellowship_channel_icon.tga";
    elseif key == "raid" then
        return base .. "raid_channel_icon.tga";
    elseif key == "kinship" then
        return base .. "kinship_channel_icon.tga";
    elseif key == "faillowship" then
        return base .. "faillowship_channel_icon.tga";
    end

    return base .. "say_channel_icon.tga";
end

function ParseGraph.UpdatePostChannelButtons()
    if ParseGraph.PostChannelButtons == nil then
        return;
    end

    local selected = NormalizePostChannel(ParseGraph.PostChannel);
    if selected ~= ParseGraph.PostChannel then
        ParseGraph.PostChannel = selected;
        if type(ParseGraph.AccountData) == "table" then
            ParseGraph.AccountData.postChannel = selected;
        end
    end

    if ParseGraph.PostChannelSelectorButton ~= nil then
        local selectedInfo = ParseGraph.GetPostChannelInfo(selected);
        local selectedLabel = tostring((selectedInfo ~= nil and selectedInfo.label) or "Say");
        if selected == "faillowship" then
            selectedLabel = tostring(ParseGraph.FaillowshipRoomName or selectedLabel);
        end
        local selectedIcon = ParseGraph.GetPostChannelIcon(selected);

        if ParseGraph.PostChannelSelectorButton.sidebarLabel ~= nil then
            ParseGraph.PostChannelSelectorButton.sidebarLabel:SetText(selectedLabel);
        end
        ParseGraph.PostChannelSelectorButton.sidebarIconPath = selectedIcon;
        ParseGraph.PostChannelSelectorButton.sidebarIconHoverPath = string.gsub(selectedIcon, "%.tga$", "_hover.tga");
        ParseGraph.PostChannelSelectorButton.sidebarIconSelectedPath = string.gsub(selectedIcon, "%.tga$", "_selected.tga");
        ParseGraph.SetSidebarButtonSelected(ParseGraph.PostChannelSelectorButton, true);
    end

    local sidebarY = 400;
    for i = 1, #ParseGraph.PostChannels do
        local info = ParseGraph.PostChannels[i];
        local key = info.key;
        local button = ParseGraph.PostChannelButtons[key];
        if button ~= nil then
            local available = ParseGraph.IsPostChannelAvailable(info);
            if button.SetVisible ~= nil then
                button:SetVisible(available);
            end
            if button.isSidebarButton == true and available then
                button:SetPosition(18, sidebarY);
                sidebarY = sidebarY + 43;
            end
            if button.isSidebarButton == true then
                ParseGraph.SetSidebarButtonSelected(button, available and key == selected);
            elseif button.SetEnabled ~= nil then
                button:SetEnabled(available and key ~= selected);
            end
        end
    end
end

function ParseGraph.RefreshPostAliasesForCurrentView()
    if ParseGraph.CurrentView == "main" then
        ParseGraph.DrawSavedParseList();
    elseif ParseGraph.CurrentView == "achievements" then
        ParseGraph.DrawAchievementsView();
    elseif ParseGraph.CurrentView == "instances" and ParseGraph.InstanceViewMode == "groupLists" then
        ParseGraph.RefreshGroupListsPostCommand();
    else
        ParseGraph.ClearPostButtonWindows();
        ParseGraph.UpdatePostButtonWindowPositions();
    end
end

