function ParseGraph.UpdateLauncherSizeControls()
    local enabled = ParseGraph.ShowLauncherButton == true;
    local selected = ParseGraph.GetLauncherButtonSizeKey();
    local selectedDirection = ParseGraph.GetLauncherFlyoutDirection();
    local activeGold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local inactiveGrey = Turbine.UI.Color(0.70, 0.55, 0.55, 0.55);
    local checkboxColor = enabled and activeGold or inactiveGrey;

    if ParseGraph.IconSizeLabel ~= nil then
        ParseGraph.IconSizeLabel:SetForeColor(checkboxColor);
    end
    if ParseGraph.LauncherFlyoutDirectionLabel ~= nil then
        ParseGraph.LauncherFlyoutDirectionLabel:SetForeColor(checkboxColor);
    end

    if ParseGraph.ShowLauncherTimerCheckbox ~= nil then
        if ParseGraph.ShowLauncherTimerCheckbox.SetEnabled ~= nil then
            ParseGraph.ShowLauncherTimerCheckbox:SetEnabled(enabled);
        end
        ParseGraph.ShowLauncherTimerCheckbox:SetMouseVisible(enabled);
    end
    if ParseGraph.ShowLauncherTimerLabel ~= nil then
        ParseGraph.ShowLauncherTimerLabel:SetForeColor(checkboxColor);
        ParseGraph.ShowLauncherTimerLabel:SetMouseVisible(enabled);
    end
    if ParseGraph.ShowLauncherTimerDetail1 ~= nil then
        ParseGraph.ShowLauncherTimerDetail1:SetForeColor(enabled and Turbine.UI.Color(0.95, 0.92, 0.88, 0.82) or inactiveGrey);
    end
    if ParseGraph.ShowLauncherTimerDetail2 ~= nil then
        ParseGraph.ShowLauncherTimerDetail2:SetForeColor(enabled and Turbine.UI.Color(0.95, 0.92, 0.88, 0.82) or inactiveGrey);
    end

    for key, checkbox in pairs(ParseGraph.LauncherSizeCheckboxes or {}) do
        ParseGraph.UpdatingLauncherSizeCheckboxes = true;
        checkbox:SetChecked(key == selected);
        ParseGraph.UpdatingLauncherSizeCheckboxes = false;
        if checkbox.SetEnabled ~= nil then
            checkbox:SetEnabled(enabled);
        end
        checkbox:SetMouseVisible(enabled);
    end

    for _, label in pairs(ParseGraph.LauncherSizeLabels or {}) do
        label:SetForeColor(checkboxColor);
        label:SetMouseVisible(enabled);
    end

    for key, checkbox in pairs(ParseGraph.LauncherFlyoutDirectionCheckboxes or {}) do
        ParseGraph.UpdatingLauncherFlyoutDirectionCheckboxes = true;
        checkbox:SetChecked(key == selectedDirection);
        ParseGraph.UpdatingLauncherFlyoutDirectionCheckboxes = false;
        if checkbox.SetEnabled ~= nil then
            checkbox:SetEnabled(enabled);
        end
        checkbox:SetMouseVisible(enabled);
    end

    for _, label in pairs(ParseGraph.LauncherFlyoutDirectionLabels or {}) do
        label:SetForeColor(checkboxColor);
        label:SetMouseVisible(enabled);
    end
end

