    ParseGraph.AccountData.onlySaveInstanceParsesOnKill = ParseGraph.OnlySaveInstanceParsesOnKill;
    ParseGraph.SaveAccountData();
    if ParseGraph.UpdatingOnlySaveInstanceParsesOnKillCheckbox ~= true then
        ParseGraph.UpdateOnlySaveInstanceParsesOnKillCheckbox();
    end
end

