    end
end
local function BuildProtectedParseSet(parses, characterKey, characterName)
    local protected = {};
    local dates = {};
    local keyText = tostring(characterKey or "");
    local nameText = LowerClean(characterName or "");
    local bestParse = nil;
    local bestValue = 0;

    if type(parses) ~= "table" then
        return protected;
    end

    for i = 1, #parses do
        local parse = parses[i];
        if type(parse) == "table" then
            if parse.favorite == true then
                protected[parse] = true;
            end

            local value = tonumber(parse.final) or 0;
            if value > bestValue then
                bestValue = value;
                bestParse = parse;
            end
        end
    end

    if bestParse ~= nil then
        protected[bestParse] = true;
    end

    local function collectDates(storage)
        if type(storage) ~= "table" then
            return;
        end

        for _, entry in pairs(storage) do
            if type(entry) == "table" and entry.unlocked == true then
                local entryKey = tostring(entry.characterKey or "");
                local entryName = LowerClean(entry.characterName or "");
                if entryKey == keyText or (nameText ~= "" and entryName == nameText) then
                    local date = tostring(entry.date or "");
                    if date ~= "" then
                        dates[date] = true;
                    end
                end
            end
        end
    end

    collectDates(ParseGraph.AccountData and ParseGraph.AccountData.achievements);
    local characters = ParseGraph.AccountData and ParseGraph.AccountData.characters or {};
    local entry = characters[keyText];
    if type(entry) == "table" then
        collectDates(entry.achievements);
    end
    if keyText == tostring(ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey()) then
        collectDates(ParseGraph.UnlockedAchievements);
    end

    for i = 1, #parses do
        local parse = parses[i];
        if type(parse) == "table" and dates[tostring(parse.time or "")] == true then
            protected[parse] = true;
        end
    end

    return protected;
end

function ParseGraph.SetCleanupStatus(text)
    if ParseGraph.CleanupStatusLabel ~= nil then
        ParseGraph.CleanupStatusLabel:SetText(tostring(text or ""));
    end
end

function ParseGraph.StripOldParseDetailsFromParses(parses, keepLatest, characterKey, characterName)
    keepLatest = tonumber(keepLatest) or 100;
    if type(parses) ~= "table" or #parses <= keepLatest then
        return 0;
    end

    local protected = BuildProtectedParseSet(parses, characterKey, characterName);
    local cutoff = #parses - keepLatest;
    local stripped = 0;
    for i = 1, cutoff do
        local parse = parses[i];
        if type(parse) == "table" and protected[parse] ~= true and parse.combat ~= nil then
            parse.combat = nil;
            stripped = stripped + 1;
        end
    end

    return stripped;
end

function ParseGraph.ApplyAutoStripOldParseDetails(keepLatest)
    if ParseGraph.AutoStripOldParseDetails ~= true then
        return 0;
    end

    keepLatest = tonumber(keepLatest) or 100;
    local stripped = 0;
    local currentKey = tostring(ParseGraph.GetCurrentCharacterKey());
    local viewKey = tostring(ParseGraph.ViewCharacterKey or currentKey);
    local viewEntry = ParseGraph.GetViewCharacterEntry();
    if type(viewEntry) == "table" then
        stripped = stripped + ParseGraph.StripOldParseDetailsFromParses(ParseGraph.Parses, keepLatest, viewKey, viewEntry.name or viewKey);
    end

    return stripped;
end

function ParseGraph.RunManualStripOldParseDetails()
    local stripped = ParseGraph.ApplyAutoStripOldParseDetails(100);
    if ParseGraph.AutoStripOldParseDetails ~= true then
        local wasEnabled = ParseGraph.AutoStripOldParseDetails;
        ParseGraph.AutoStripOldParseDetails = true;
        stripped = ParseGraph.ApplyAutoStripOldParseDetails(100);
        ParseGraph.AutoStripOldParseDetails = wasEnabled;
    end

    if stripped > 0 then
        ParseGraph.Save(false, ParseGraph.ViewCharacterKey ~= ParseGraph.GetCurrentCharacterKey());
        ParseGraph.SetCleanupStatus("Stripped " .. tostring(stripped) .. " old parse breakdowns.");
        ParseGraph.Refresh();
    else
        ParseGraph.SetCleanupStatus("No old parse breakdowns needed stripping.");
    end
end

function ParseGraph.DeleteOldestSafeParses(count)
    count = tonumber(count) or 50;
    local parses = ParseGraph.Parses or {};
    local key = tostring(ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey());
    if ParseGraph.IsCombineSameClassActive() then
        ParseGraph.SetCleanupStatus("Turn off Combine same class before deleting parses.");
        return 0, 0;
    end
    if key ~= ParseGraph.GetCurrentCharacterKey() then
        ParseGraph.SetCleanupStatus("Only the logged-in character can delete parses.");
        return 0, 0;
    end

    local entry = ParseGraph.GetViewCharacterEntry();
    local name = entry and entry.name or ParseGraph.GetCharacterDisplayName(key);
    local protected = BuildProtectedParseSet(parses, key, name);
    local removed = 0;
    local skipped = 0;
    local i = 1;

    while i <= #parses and removed < count do
        local parse = parses[i];
        if type(parse) == "table" and protected[parse] == true then
            skipped = skipped + 1;
            i = i + 1;
        else
            table.remove(parses, i);
            removed = removed + 1;
        end
    end

    if removed > 0 then
        ParseGraph.Parses = parses;
        ParseGraph.Save(false, key ~= ParseGraph.GetCurrentCharacterKey());
        ParseGraph.SetCleanupStatus("Deleted " .. tostring(removed) .. " old parses. Protected " .. tostring(skipped) .. ".");
        ParseGraph.Refresh();
    else
        ParseGraph.SetCleanupStatus("No safe old parses could be deleted.");
    end

    return removed, skipped;
end

function ParseGraph.CountInstanceDataRecords(instances, instanceKey)
    if type(instances) ~= "table" then
        return 0;
    end

    local count = 0;
    local function CountInstance(instanceData)
        if type(instanceData) ~= "table" then
            return;
        end
        for _, tierData in pairs(instanceData) do
            if type(tierData) == "table" then
                for _, bossData in pairs(tierData) do
                    if type(bossData) == "table" then
                        for _, records in pairs(bossData) do
                            if type(records) == "table" then
                                count = count + #records;
                            end
                        end
                    end
                end
            end
        end
    end

    if tostring(instanceKey or "") == "all" then
        for _, instanceData in pairs(instances) do
            CountInstance(instanceData);
        end
    else
        CountInstance(instances[tostring(instanceKey or "")]);
    end

    return count;
end

function ParseGraph.DeleteInstanceDataForCurrentCharacter(instanceKey)
    instanceKey = tostring(instanceKey or "all");
    local currentKey = tostring(ParseGraph.GetCurrentCharacterKey() or "");
    local viewKey = tostring(ParseGraph.ViewCharacterKey or currentKey);
    if currentKey == "" then
        ParseGraph.SetCleanupStatus("No current character found.");
        return 0;
    end
    if ParseGraph.IsCombineSameClassActive() then
        ParseGraph.SetCleanupStatus("Turn off Combine same class before deleting instance data.");
        return 0;
    end
    if viewKey ~= currentKey then
        ParseGraph.SetCleanupStatus("Switch to that character before deleting instance data.");
        return 0;
    end

    local entry = ParseGraph.EnsureAccountCharacter(currentKey, ParseGraph.GetCurrentCharacterName());
    if type(entry) ~= "table" then
        ParseGraph.SetCleanupStatus("No character data found.");
        return 0;
    end
    if type(entry.instances) ~= "table" then
        entry.instances = {};
    end

    local removed = ParseGraph.CountInstanceDataRecords(entry.instances, instanceKey);
    if removed <= 0 then
        ParseGraph.SetCleanupStatus("No instance entries found to delete.");
        return 0;
    end

    if instanceKey == "all" then
        entry.instances = {};
    else
        entry.instances[instanceKey] = nil;
    end
    entry.updated = NowText();
    ParseGraph.AccountData.characters[currentKey] = entry;
    ParseGraph.InstanceData = entry.instances;
    ParseGraph.SaveAccountData();
    ParseGraph.SaveCharacterEntryToCharacterScope(entry);
    ParseGraph.SetCleanupStatus("Deleted " .. tostring(removed) .. " instance entries.");
    if ParseGraph.CurrentView == "instances" then
        ParseGraph.DrawInstancesView();
    end
    return removed;
end

function ParseGraph.SetAutoStripOldParseDetails(enabled)
    ParseGraph.AutoStripOldParseDetails = NormalizeBoolean(enabled);
    if type(ParseGraph.AccountData) ~= "table" then
        ParseGraph.AccountData = { characters = {} };
    end
    if type(ParseGraph.AccountData.characters) ~= "table" then
        ParseGraph.AccountData.characters = {};
    end
    if type(ParseGraph.AccountData.achievements) ~= "table" then
        ParseGraph.AccountData.achievements = {};
    end
    ParseGraph.AccountData.autoStripOldParseDetails = ParseGraph.AutoStripOldParseDetails;
    local stripped = 0;
    if ParseGraph.AutoStripOldParseDetails == true then
        stripped = ParseGraph.ApplyAutoStripOldParseDetails(100);
    end
    if stripped > 0 then
        ParseGraph.Save(false, ParseGraph.ViewCharacterKey ~= ParseGraph.GetCurrentCharacterKey());
    else
        ParseGraph.SaveAccountData();
    end
    if ParseGraph.UpdatingAutoStripOldParseDetailsCheckbox ~= true then
        ParseGraph.UpdateAutoStripOldParseDetailsCheckbox();
    end
    if stripped > 0 then
        ParseGraph.SetCleanupStatus("Auto-strip enabled. Stripped " .. tostring(stripped) .. " old breakdowns.");
    elseif ParseGraph.AutoStripOldParseDetails == true then
        ParseGraph.SetCleanupStatus("Auto-strip enabled.");
    else
        ParseGraph.SetCleanupStatus("Auto-strip disabled.");
    end
end

