function ParseGraph.GetGroupListMode()
    ParseGraph.GroupListMode = ParseGraph.NormalizeGroupListMode(ParseGraph.GroupListMode);
    return ParseGraph.GroupListMode;
end

function ParseGraph.GetGroupListFixedLabel(index)
    local mode = ParseGraph.GetGroupListMode();
    if mode == "target" then
        return tostring((ParseGraph.GroupListTargetMarks or {})[index] or "");
    end
    if mode == "numbers" then
        return tostring(index) .. ")";
    end
    return nil;
end

function ParseGraph.NormalizeGroupListLines(lines)
    if type(lines) ~= "table" then
        lines = {};
    end
    for i = 1, 10 do
        if lines[i] == nil then
            lines[i] = { left = "", right = "" };
        elseif type(lines[i]) ~= "table" then
            lines[i] = { left = tostring(lines[i] or ""), right = "" };
        else
            lines[i].left = tostring(lines[i].left or "");
            lines[i].right = tostring(lines[i].right or "");
        end
    end
    return lines;
end

function ParseGraph.EnsureGroupListTemplateLines()
    if type(ParseGraph.GroupListTemplateLines) ~= "table" then
        ParseGraph.GroupListTemplateLines = {};
    end
    local modes = { "custom", "target", "numbers" };
    for i = 1, #modes do
        local mode = modes[i];
        ParseGraph.GroupListTemplateLines[mode] = ParseGraph.NormalizeGroupListLines(ParseGraph.GroupListTemplateLines[mode]);
    end
end

function ParseGraph.CopyGroupListLinesForSave(lines)
    local sourceLines = ParseGraph.NormalizeGroupListLines(lines or ParseGraph.GroupListLines);
    local copiedLines = {};
    for i = 1, 10 do
        local row = sourceLines[i] or {};
        copiedLines[i] = {
            left = tostring(row.left or ""),
            right = tostring(row.right or "")
        };
    end
    return copiedLines;
end

function ParseGraph.CopyGroupListTemplateLinesForSave()
    ParseGraph.EnsureGroupListTemplateLines();
    return {
        custom = ParseGraph.CopyGroupListLinesForSave(ParseGraph.GroupListTemplateLines.custom),
        target = ParseGraph.CopyGroupListLinesForSave(ParseGraph.GroupListTemplateLines.target),
        numbers = ParseGraph.CopyGroupListLinesForSave(ParseGraph.GroupListTemplateLines.numbers)
    };
end

function ParseGraph.UpdateSavedGroupListData(saveNow)
    if type(ParseGraph.AccountData) ~= "table" then
        ParseGraph.AccountData = { characters = {} };
    end
    if type(ParseGraph.AccountData.characters) ~= "table" then
        ParseGraph.AccountData.characters = {};
    end
    if type(ParseGraph.AccountData.achievements) ~= "table" then
        ParseGraph.AccountData.achievements = {};
    end

    ParseGraph.AccountData.groupListSaveEnabled = ParseGraph.GroupListSaveEnabled == true;
    if ParseGraph.GroupListSaveEnabled == true then
        ParseGraph.AccountData.groupListMode = ParseGraph.GetGroupListMode();
        ParseGraph.EnsureGroupListTemplateLines();
        ParseGraph.GroupListTemplateLines[ParseGraph.GroupListMode] = ParseGraph.GroupListLines;
        ParseGraph.AccountData.groupListTemplateLines = ParseGraph.CopyGroupListTemplateLinesForSave();
        ParseGraph.AccountData.groupListLines = nil;
    else
        ParseGraph.AccountData.groupListMode = nil;
        ParseGraph.AccountData.groupListLines = nil;
        ParseGraph.AccountData.groupListTemplateLines = nil;
    end

    if saveNow == true then
        ParseGraph.SaveAccountData();
    end
end

function ParseGraph.UpdateGroupListModeControls()
    local mode = ParseGraph.GetGroupListMode();
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);

    for key, checkbox in pairs(ParseGraph.GroupListModeCheckboxes or {}) do
        ParseGraph.UpdatingGroupListModeCheckboxes = true;
        checkbox:SetChecked(key == mode);
        ParseGraph.UpdatingGroupListModeCheckboxes = false;
    end

    for _, label in pairs(ParseGraph.GroupListModeLabels or {}) do
        label:SetForeColor(gold);
    end

    if ParseGraph.GroupListSaveCheckbox ~= nil then
        ParseGraph.UpdatingGroupListSaveCheckbox = true;
        ParseGraph.GroupListSaveCheckbox:SetChecked(ParseGraph.GroupListSaveEnabled == true);
        ParseGraph.UpdatingGroupListSaveCheckbox = false;
    end
    if ParseGraph.GroupListSaveLabel ~= nil then
        ParseGraph.GroupListSaveLabel:SetForeColor(gold);
    end
end

function ParseGraph.SetGroupListMode(mode)
    mode = ParseGraph.NormalizeGroupListMode(mode);
    ParseGraph.EnsureGroupListTemplateLines();
    ParseGraph.GroupListTemplateLines[ParseGraph.GetGroupListMode()] = ParseGraph.GroupListLines;
    ParseGraph.GroupListMode = mode;
    ParseGraph.GroupListLines = ParseGraph.GroupListTemplateLines[mode];
    ParseGraph.EnsureGroupListLines();
    ParseGraph.UpdateSavedGroupListData(ParseGraph.GroupListSaveEnabled == true);

    if ParseGraph.CurrentView == "instances" and ParseGraph.InstanceViewMode == "groupLists" and ParseGraph.DrawInstancesView ~= nil then
        ParseGraph.DrawInstancesView();
    else
        ParseGraph.UpdateGroupListModeControls();
    end

    ParseGraph.RefreshGroupListsPostCommand();
end

function ParseGraph.SetGroupListSaveEnabled(enabled)
    ParseGraph.GroupListSaveEnabled = NormalizeBoolean(enabled);
    ParseGraph.UpdateSavedGroupListData(true);
    ParseGraph.UpdateGroupListModeControls();
end

function ParseGraph.FormatPostMinute(value)
    if tonumber(value) == nil then
        return "-";
    end
    return FormatNumber(value) .. " DPS";
end

function ParseGraph.FormatPostDps(value, numberColor)
    if tonumber(value) == nil then
        return ChatColor(numberColor or "FFFFFF", "-");
    end
    return ChatColor(numberColor or "FFFFFF", FormatNumber(value)) .. ChatColor("FFB21A", " DPS");
end

function ParseGraph.FormatPostTotal(value)
    if tonumber(value) == nil then
        return "-";
    end
    return FormatNumber(value);
end

function ParseGraph.BuildPostCommand(parse, parseNumber, channelOverride)
    local channel = ParseGraph.GetPostChannelInfo(channelOverride);
    local minutes = {};
    if parse ~= nil and type(parse.minutes) == "table" then
        minutes = parse.minutes;
    end
    parseNumber = tonumber(parseNumber) or 0;
    local comparisonStats = ParseGraph.GetParseComparisonStats(parseNumber);
    local averages = comparisonStats.averageMinutes or {};
    local characterName = parse and parse.__sourceName or ParseGraph.GetCharacterDisplayName(ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey());
    return "/" .. tostring(channel.command or "say") .. " "
        .. ChatColor("FFB21A", "ParseGraph:") .. " " .. ChatColor("666666", "#" .. tostring(parseNumber)) .. "\n"
        .. ChatColor("666666", characterName) .. "\n"
        .. ChatColor("FFB21A", "Minute 1:") .. " " .. ParseGraph.FormatPostDps(minutes[1], ParseGraph.GetMinuteSummaryColor(minutes[1], averages[1])) .. "\n"
        .. ChatColor("FFB21A", "Minute 2:") .. " " .. ParseGraph.FormatPostDps(minutes[2], ParseGraph.GetMinuteSummaryColor(minutes[2], averages[2])) .. "\n"
        .. ChatColor("FFB21A", "Minute 3:") .. " " .. ParseGraph.FormatPostDps(minutes[3], ParseGraph.GetMinuteSummaryColor(minutes[3], averages[3])) .. "\n"
        .. ChatColor("FFB21A", "Final DPS:") .. " " .. ChatColor("FFFFFF", ParseGraph.FormatPostTotal(parse and parse.final));
end

function ParseGraph.BuildPersonalBestPostCommand(parse)
    local channel = ParseGraph.GetPostChannelInfo();
    local minutes = {};
    if parse ~= nil and type(parse.minutes) == "table" then
        minutes = parse.minutes;
