function ParseGraph.BuildAchievementPostCommand(achievement)
    local channel = ParseGraph.GetPostChannelInfo();
    local unlockDate = ParseGraph.FormatAchievementPostDate(ParseGraph.GetAchievementUnlockDate(achievement));
    local characterName = ParseGraph.GetAchievementUnlockCharacter(achievement);
    local detail = ParseGraph.GetAchievementDetailText(achievement);
    local detailLabel, detailValue = string.match(detail, "^([^:]+:%s*)(.*)$");
    if detailLabel == nil then
        detailLabel = "";
        detailValue = detail;
    end

    return "/" .. tostring(channel.command or "say") .. " "
        .. ChatColor("FFB21A", "ParseGraph") .. "\n"
        .. ChatColor("FFB21A", "Achievement:") .. " " .. ChatColor("FFFFFF", tostring(achievement and achievement.title or "")) .. "\n"
        .. ChatColor("FFB21A", detailLabel) .. ChatColor("FFFFFF", detailValue) .. "\n"
        .. ChatColor("666666", "Unlocked: " .. unlockDate .. " on " .. characterName);
end

function ParseGraph.EnsureGroupListLines()
    ParseGraph.GroupListLines = ParseGraph.NormalizeGroupListLines(ParseGraph.GroupListLines);
    ParseGraph.EnsureGroupListTemplateLines();
    ParseGraph.GroupListTemplateLines[ParseGraph.GetGroupListMode()] = ParseGraph.GroupListLines;
end

function ParseGraph.SetGroupListLine(index, side, text)
    ParseGraph.EnsureGroupListLines();
    index = tonumber(index);
    if index == nil or index < 1 or index > 10 then
        return;
    end

    side = tostring(side or "left");
    if side ~= "right" then
        side = "left";
    end
    text = tostring(text or "");
    text = string.gsub(text, "[\r\n]+", " ");
    ParseGraph.GroupListLines[index][side] = text;
    ParseGraph.UpdateSavedGroupListData(false);
end

function ParseGraph.ClearGroupListLines()
    ParseGraph.EnsureGroupListLines();
    for i = 1, 10 do
        ParseGraph.GroupListLines[i].left = "";
        ParseGraph.GroupListLines[i].right = "";

        local boxes = ParseGraph.GroupListTextBoxes and ParseGraph.GroupListTextBoxes[i];
        if boxes ~= nil then
            if boxes.left ~= nil then
                boxes.left:SetText("");
            end
            if boxes.right ~= nil then
                boxes.right:SetText("");
            end
        end
    end

    ParseGraph.UpdateSavedGroupListData(ParseGraph.GroupListSaveEnabled == true);
    ParseGraph.RefreshGroupListsPostCommand();
end

function ParseGraph.BuildGroupListsPostCommand(channelOverride)
    local channel = ParseGraph.GetPostChannelInfo(channelOverride);
    ParseGraph.EnsureGroupListLines();

    local mode = ParseGraph.GetGroupListMode();
    local lines = { ChatColor("FFB21A", "ParseGraph") };
    for i = 1, 10 do
        local row = ParseGraph.GroupListLines[i];
        local right = TrimText(row and row.right or "");
        local fixedLeft = ParseGraph.GetGroupListFixedLabel(i);
        local left = fixedLeft or TrimText(row and row.left or "");
        if mode ~= "custom" then
            if right ~= "" then
                if mode == "numbers" then
                    table.insert(lines, ChatColor("FFB21A", left) .. ChatColor("FFFFFF", " ") .. ChatColor("3DFF55", right));
                else
                    table.insert(lines, ChatColor("FFB21A", left) .. ChatColor("FFFFFF", " = ") .. ChatColor("3DFF55", right));
                end
            end
        elseif left ~= "" or right ~= "" then
            table.insert(lines, ChatColor("FFB21A", left) .. ChatColor("FFFFFF", " = ") .. ChatColor("3DFF55", right));
        end
    end

    return "/" .. tostring(channel.command or "say") .. " " .. table.concat(lines, "\n");
end

function ParseGraph.TryExecuteAliasCommand(command)
    if Turbine == nil or Turbine.UI == nil or Turbine.UI.Lotro == nil then
        return false;
    end

    if ParseGraph.GroupListsCommandWindow ~= nil then
        ParseGraph.GroupListsCommandWindow:SetVisible(false);
    end

    local window = Turbine.UI.Window();
    window:SetPosition(-10000, -10000);
    window:SetSize(1, 1);
    window:SetOpacity(0);
    window:SetMouseVisible(false);
    window:SetVisible(true);

    local slot = Turbine.UI.Lotro.Quickslot();
    slot:SetParent(window);
    slot:SetPosition(0, 0);
    slot:SetSize(1, 1);
    slot:SetMouseVisible(false);
    ParseGraph.SetAliasQuickslotCommand(slot, command);

    ParseGraph.GroupListsCommandWindow = window;
    ParseGraph.GroupListsCommandSlot = slot;

    local ok = false;
    if slot.Use ~= nil then
        ok = pcall(function()
            slot:Use();
        end) == true;
    elseif slot.Execute ~= nil then
        ok = pcall(function()
            slot:Execute();
        end) == true;
    elseif slot.DoClick ~= nil then
        ok = pcall(function()
            slot:DoClick();
        end) == true;
    end

    return ok == true;
end

function ParseGraph.PostGroupListsFromCommand()
    local command = ParseGraph.BuildGroupListsPostCommand();
    if ParseGraph.TryExecuteAliasCommand(command) then
        return;
    end

    ParseGraph.OpenSidebarInstanceMode("groupLists");
    Turbine.Shell.WriteLine(ChatColor("FFB21A", "ParseGraph:") .. ChatColor("FFFFFF", " /list prepared the group list. Click Post to send it."));
end

function ParseGraph.ClearPostButtonWindows()
    if ParseGraph.PostButtonWindows ~= nil then
        for i = 1, #ParseGraph.PostButtonWindows do
            local item = ParseGraph.PostButtonWindows[i];
            if item ~= nil and item.window ~= nil then
                item.window:SetVisible(false);
                item.window:SetPosition(-10000, -10000);
                item.window:SetSize(0, 0);
                if item.slot ~= nil and item.slot.SetParent ~= nil then
                    pcall(function()
                        item.slot:SetParent(nil);
                    end);
                end
                if item.window.SetParent ~= nil then
                    pcall(function()
                        item.window:SetParent(nil);
                    end);
                end
                ParseGraph.ApplyAliasButtonVisualState(item.visualButton, "");
            end
        end
    end
    ParseGraph.PostButtonWindows = {};
end

function ParseGraph.HidePostButtonWindows()
    if ParseGraph.PostButtonWindows == nil then
        return;
    end

    for i = 1, #ParseGraph.PostButtonWindows do
        local item = ParseGraph.PostButtonWindows[i];
        if item ~= nil and item.window ~= nil then
            item.window:SetVisible(false);
            item.window:SetPosition(-10000, -10000);
            item.window:SetSize(0, 0);
            ParseGraph.ApplyAliasButtonVisualState(item.visualButton, "");
        end
    end
end

function ParseGraph.GetControlScreenPosition(control)
    local x = 0;
    local y = 0;
    local current = control;

    while current ~= nil do
        local okPos, cx, cy = pcall(function()
            return current:GetPosition();
        end);
        if okPos then
            x = x + (tonumber(cx) or 0);
            y = y + (tonumber(cy) or 0);
        end

        local okParent, parent = pcall(function()
            if current.GetParent == nil then
                return nil;
            end
            return current:GetParent();
        end);
        if not okParent then
            parent = nil;
        end
        current = parent;
    end

    return x, y;
end

function ParseGraph.UpdatePostButtonWindowPositions()
    if ParseGraph.PostButtonWindows == nil then
        return;
    end

    local windowVisible = false;
    if ParseGraph.Window ~= nil and ParseGraph.Window.IsVisible ~= nil then
        local okVisible, visible = pcall(function()
            return ParseGraph.Window:IsVisible();
        end);
        windowVisible = okVisible and visible == true;
    end
    if windowVisible and ParseGraph.Window ~= nil and ParseGraph.Window.GetSize ~= nil then
        local okSize, windowW, windowH = pcall(function()
            return ParseGraph.Window:GetSize();
        end);
        if okSize then
            windowVisible = (tonumber(windowW) or 0) > 100 and (tonumber(windowH) or 0) > 100;
        end
    end

    for i = 1, #ParseGraph.PostButtonWindows do
        local item = ParseGraph.PostButtonWindows[i];
        if item ~= nil and item.window ~= nil then
            local parentVisible = true;
            if item.parent ~= nil and item.parent.IsVisible ~= nil then
                local okParentVisible, visibleParent = pcall(function()
                    return item.parent:IsVisible();
                end);
                parentVisible = okParentVisible and visibleParent == true;
            end
            local visible = windowVisible and parentVisible and (item.view == nil or item.view == ParseGraph.CurrentView);
            if visible then
                local px, py = ParseGraph.GetControlScreenPosition(item.parent);
                if item.clipParent ~= nil then
                    local clipX, clipY = ParseGraph.GetControlScreenPosition(item.clipParent);
                    local clipW, clipH = 0, 0;
                    local okClipSize, gotClipW, gotClipH = pcall(function()
                        return item.clipParent:GetSize();
                    end);
                    if okClipSize then
                        clipW = tonumber(gotClipW) or 0;
                        clipH = tonumber(gotClipH) or 0;
                    end
                    local itemX = px + item.x;
                    local itemY = py + item.y;
                    visible = itemX < (clipX + clipW)
                        and (itemX + item.w) > clipX
                        and itemY < (clipY + clipH)
                        and (itemY + item.h) > clipY;
                end
            end
            if visible then
                local px, py = ParseGraph.GetControlScreenPosition(item.parent);
                item.window:SetPosition(px + item.x, py + item.y);
                item.window:SetSize(item.w, item.h);
                item.window:SetVisible(true);
                item.window:Activate();
            else
                item.window:SetVisible(false);
                item.window:SetPosition(-10000, -10000);
                item.window:SetSize(0, 0);
                ParseGraph.ApplyAliasButtonVisualState(item.visualButton, "");
            end
        end
    end
end

function ParseGraph.CreateAliasQuickslot(parent, command, x, y, w, h, view, visualButton, onClick, clipParent)
    local buttonWindow = Turbine.UI.Window();
    buttonWindow:SetSize(0, 0);
    buttonWindow:SetOpacity(0);
    buttonWindow:SetMouseVisible(true);
    if buttonWindow.SetZOrder ~= nil then
        buttonWindow:SetZOrder(250);
    end
    buttonWindow:SetVisible(false);

    local slot = Turbine.UI.Lotro.Quickslot();
    slot:SetParent(buttonWindow);
    slot:SetPosition(0, 0);
    slot:SetSize(w, h);
    slot:SetZOrder(20);
    slot:SetMouseVisible(true);

    local shortcut = Turbine.UI.Lotro.Shortcut(Turbine.UI.Lotro.ShortcutType.Alias, nil);
    shortcut:SetData(tostring(command or ""));
    slot.shortcut = shortcut;
    slot:SetShortcut(shortcut);
    slot.aliasClickCallback = onClick;
    slot.DragDrop = function(sender)
        sender:SetShortcut(sender.shortcut);
    end
    local aliasCallbackTime = nil;
    local function FireAliasClickCallback(sender)
        if sender ~= nil and sender.aliasClickCallback ~= nil then
            local now = Turbine.Engine.GetGameTime();
            if aliasCallbackTime == nil or now == nil or (now - aliasCallbackTime) > 0.20 then
                aliasCallbackTime = now;
                pcall(sender.aliasClickCallback);
            end
        end
    end
    slot.visualButton = visualButton;
    slot.MouseEnter = function(sender)
        ParseGraph.ApplyAliasButtonVisualState(sender.visualButton, "hover");
    end
    slot.MouseLeave = function(sender)
        ParseGraph.ApplyAliasButtonVisualState(sender.visualButton, "");
    end
    slot.MouseDown = function(sender)
        FireAliasClickCallback(sender);
        ParseGraph.ApplyAliasButtonVisualState(sender.visualButton, "pressed");
    end
    slot.MouseUp = function(sender)
        ParseGraph.ApplyAliasButtonVisualState(sender.visualButton, "hover");
    end

    buttonWindow.visualButton = visualButton;
    buttonWindow.aliasClickCallback = onClick;
    buttonWindow.MouseEnter = function(sender)
        ParseGraph.ApplyAliasButtonVisualState(sender.visualButton, "hover");
    end
    buttonWindow.MouseLeave = function(sender)
        ParseGraph.ApplyAliasButtonVisualState(sender.visualButton, "");
    end
    buttonWindow.MouseDown = function(sender)
        FireAliasClickCallback(sender);
        ParseGraph.ApplyAliasButtonVisualState(sender.visualButton, "pressed");
    end
    buttonWindow.MouseUp = function(sender)
        ParseGraph.ApplyAliasButtonVisualState(sender.visualButton, "hover");
    end

    table.insert(ParseGraph.PostButtonWindows, {
        window = buttonWindow,
        slot = slot,
        shortcut = shortcut,
        visualButton = visualButton,
        parent = parent,
        x = x,
        y = y,
        w = w,
        h = h,
        view = view or ParseGraph.CurrentView,
        clipParent = clipParent
    });
    ParseGraph.UpdatePostButtonWindowPositions();

    return slot;
end

function ParseGraph.CreateInlineAliasQuickslot(parent, command, x, y, w, h, onClick)
    local slot = Turbine.UI.Lotro.Quickslot();
    slot:SetParent(parent);
    slot:SetPosition(x, y);
    slot:SetSize(w, h);
    slot:SetZOrder(5);
    slot:SetMouseVisible(true);
    if slot.SetOpacity ~= nil then
        slot:SetOpacity(0);
    end

    local shortcut = Turbine.UI.Lotro.Shortcut(Turbine.UI.Lotro.ShortcutType.Alias, nil);
    shortcut:SetData(tostring(command or ""));
    slot.shortcut = shortcut;
    slot:SetShortcut(shortcut);
    slot.aliasClickCallback = onClick;
    slot.DragDrop = function(sender)
        sender:SetShortcut(sender.shortcut);
    end

    local aliasCallbackTime = nil;
    local function FireAliasClickCallback(sender)
        if sender ~= nil and sender.aliasClickCallback ~= nil then
            local now = Turbine.Engine.GetGameTime();
            if aliasCallbackTime == nil or now == nil or (now - aliasCallbackTime) > 0.20 then
                aliasCallbackTime = now;
                pcall(sender.aliasClickCallback);
            end
        end
    end

    slot.MouseDown = function(sender)
        FireAliasClickCallback(sender);
    end

    return slot;
end

function ParseGraph.SetAliasQuickslotCommand(slot, command)
    if slot == nil then
        return;
    end

    local shortcut = Turbine.UI.Lotro.Shortcut(Turbine.UI.Lotro.ShortcutType.Alias, nil);
    shortcut:SetData(tostring(command or ""));
    slot.shortcut = shortcut;
    slot:SetShortcut(shortcut);
end

function ParseGraph.RefreshGroupListsPostCommand()
