    ParseGraph.SetAliasQuickslotCommand(ParseGraph.GroupListsPostAlias, ParseGraph.BuildGroupListsPostCommand());
end

function ParseGraph.CreateGroupListsPostQuickslot(parent, visualButton, x, y, w, h)
    local slot = Turbine.UI.Lotro.Quickslot();
    slot:SetParent(parent);
    slot:SetPosition(x, y);
    slot:SetSize(w, h);
    slot:SetZOrder(20);
    slot:SetMouseVisible(true);
    if slot.SetOpacity ~= nil then
        slot:SetOpacity(0);
    end

    ParseGraph.SetAliasQuickslotCommand(slot, ParseGraph.BuildGroupListsPostCommand());
    slot.visualButton = visualButton;
    if visualButton ~= nil then
        visualButton:SetMouseVisible(false);
        visualButton:SetZOrder(60);
    end
    slot.DragDrop = function(sender)
        ParseGraph.SetAliasQuickslotCommand(sender, ParseGraph.BuildGroupListsPostCommand());
    end
    slot.MouseEnter = function(sender)
        ParseGraph.SetAliasQuickslotCommand(sender, ParseGraph.BuildGroupListsPostCommand());
        ParseGraph.ApplyAliasButtonVisualState(sender.visualButton, "hover");
    end
    slot.MouseLeave = function(sender)
        ParseGraph.ApplyAliasButtonVisualState(sender.visualButton, "");
    end
    slot.MouseDown = function(sender)
        ParseGraph.SetAliasQuickslotCommand(sender, ParseGraph.BuildGroupListsPostCommand());
        ParseGraph.ApplyAliasButtonVisualState(sender.visualButton, "pressed");
    end
    slot.MouseUp = function(sender)
        ParseGraph.ApplyAliasButtonVisualState(sender.visualButton, "hover");
    end

    return slot;
end

local function GetContextTargetInstanceKey()
    if type(ParseGraph.ManualInstanceTarget) == "table" and ParseGraph.ManualInstanceTarget.instanceKey ~= nil then
        return tostring(ParseGraph.ManualInstanceTarget.instanceKey);
    end
    if ParseGraph.ActiveInstanceKey ~= nil then
        return ParseGraph.ActiveInstanceKey;
    end
    if ParseGraph.CurrentView == "instances" and ParseGraph.InstanceViewMode == "boss" and ParseGraph.SelectedInstanceKey ~= nil then
        return ParseGraph.SelectedInstanceKey;
    end
    return ParseGraph.SelectedInstanceKey or "folly";
end

