function ParseGraph.GetLatestContextParsePoint()
    local points = ParseGraph.GetDisplayedParsePoints(1);
    if type(points) ~= "table" or #points < 1 then
        return nil;
    end
    return points[#points];
end

function ParseGraph.ClearContextMenuAliasWindows()
    local function clear(list)
        if type(list) ~= "table" then
            return;
        end
        for i = 1, #list do
            local item = list[i];
            if item ~= nil and item.window ~= nil then
                item.window:SetVisible(false);
                item.window:SetSize(0, 0);
            end
            if item ~= nil and item.visualRow ~= nil then
                ParseGraph.ApplyContextMenuRowState(item.visualRow, false);
            end
        end
    end
    clear(ParseGraph.ContextMenuAliasWindows);
    clear(ParseGraph.ContextSubmenuAliasWindows);
    ParseGraph.ContextMenuAliasWindows = {};
    ParseGraph.ContextSubmenuAliasWindows = {};
end

function ParseGraph.ClearContextSubmenuAliasWindows()
    if type(ParseGraph.ContextSubmenuAliasWindows) ~= "table" then
        ParseGraph.ContextSubmenuAliasWindows = {};
        return;
    end
    for i = 1, #ParseGraph.ContextSubmenuAliasWindows do
        local item = ParseGraph.ContextSubmenuAliasWindows[i];
        if item ~= nil and item.window ~= nil then
            item.window:SetVisible(false);
            item.window:SetSize(0, 0);
        end
        if item ~= nil and item.visualRow ~= nil then
            ParseGraph.ApplyContextMenuRowState(item.visualRow, false);
        end
    end
    ParseGraph.ContextSubmenuAliasWindows = {};
end

function ParseGraph.HideLauncherContextSubmenu()
    ParseGraph.ClearContextSubmenuAliasWindows();
    if ParseGraph.ContextSubmenuWindow ~= nil then
        ParseGraph.ContextSubmenuWindow:SetVisible(false);
        ParseGraph.ContextSubmenuWindow:SetSize(0, 0);
    end
    ParseGraph.ContextSubmenuWindow = nil;
end

function ParseGraph.HideLauncherContextMenu()
    ParseGraph.HideLauncherContextSubmenu();
    ParseGraph.ClearContextMenuAliasWindows();
    if ParseGraph.ContextMenuBackdrop ~= nil then
        ParseGraph.ContextMenuBackdrop:SetVisible(false);
        ParseGraph.ContextMenuBackdrop:SetSize(0, 0);
    end
    ParseGraph.ContextMenuBackdrop = nil;
    if ParseGraph.ContextMenuWindow ~= nil then
        ParseGraph.ContextMenuWindow:SetVisible(false);
        ParseGraph.ContextMenuWindow:SetSize(0, 0);
    end
    ParseGraph.ContextMenuWindow = nil;
end

function ParseGraph.ApplyContextMenuRowState(row, hover)
    if row == nil then
        return;
    end
    if hover then
        row:SetBackColor(Turbine.UI.Color(1.00, 0.06, 0.22, 0.38));
    else
        row:SetBackColor(Turbine.UI.Color(1.00, 0.01, 0.03, 0.05));
    end
    if row.contextLabel ~= nil then
        if row.contextSelected == true then
            row.contextLabel:SetForeColor(Turbine.UI.Color(1.00, 0.30, 1.00, 0.30));
        else
            row.contextLabel:SetForeColor(Turbine.UI.Color(1.00, 1.00, 0.85, 0.25));
        end
    end
end

function ParseGraph.GetSpecTextColor(specKey)
    local key = ParseGraph.NormalizeParseSpecKey(specKey);
    if key == "blue" then
        return Turbine.UI.Color(1.00, 0.28, 0.64, 1.00);
    elseif key == "red" then
        return Turbine.UI.Color(1.00, 1.00, 0.24, 0.20);
    elseif key == "yellow" then
        return Turbine.UI.Color(1.00, 1.00, 0.88, 0.16);
    end
    return Turbine.UI.Color(1.00, 1.00, 0.85, 0.25);
end

function ParseGraph.GetSpecContextSegments(specKey)
    local key = ParseGraph.NormalizeParseSpecKey(specKey);
    if key == nil then
        return nil;
    end

    local label = "Blue";
    if key == "red" then
        label = "Red";
    elseif key == "yellow" then
        label = "Yellow";
    end

    return {
        { text = label, color = ParseGraph.GetSpecTextColor(key), width = key == "yellow" and 58 or 42 },
        { text = "spec", color = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16), width = 48 }
    };
end

function ParseGraph.ApplyContextMenuRowSegments(row, segments, hasSubmenu)
    if row == nil or type(segments) ~= "table" then
        return;
    end

    if row.contextLabel ~= nil then
        row.contextLabel:SetText("");
    end

    row.contextSegmentLabels = {};
    local arrowOnLeft = hasSubmenu == true and row.contextArrowOnLeft == true;
    local x = arrowOnLeft and 30 or 10;
    local maxW = row:GetWidth() - (hasSubmenu and 36 or 18);
    for i = 1, #segments do
        local segment = segments[i] or {};
        local segmentW = tonumber(segment.width) or 44;
        local label = Label(row, x, 0, segmentW, row:GetHeight(), tostring(segment.text or ""), "small");
        label:SetFont(Turbine.UI.Lotro.Font.TrajanPro16);
        label:SetForeColor(segment.color or Turbine.UI.Color(1.00, 1.00, 0.85, 0.25));
        label:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
        label:SetMouseVisible(false);
        label:SetZOrder(3);
        table.insert(row.contextSegmentLabels, label);
        x = math.min(maxW, x + segmentW);
    end
end

local function CreateContextMenuBorder(parent, w, h, color)
    DrawBlock(parent, 0, 0, w, 1, color);
    DrawBlock(parent, 0, h - 1, w, 1, color);
    DrawBlock(parent, 0, 0, 1, h, color);
    DrawBlock(parent, w - 1, 0, 1, h, color);
end

function ParseGraph.CreateContextMenuRow(parent, x, y, w, h, text, hasSubmenu, onClick, selected)
    local row = Turbine.UI.Control();
    row:SetParent(parent);
    row:SetPosition(x, y);
    row:SetSize(w, h);
    row:SetMouseVisible(true);
    row.contextBaseText = tostring(text or "");
    ParseGraph.ApplyContextMenuRowState(row, false);
    CreateContextMenuBorder(row, w, h, Turbine.UI.Color(0.85, 0.70, 0.46, 0.10));

    local arrowOnLeft = hasSubmenu == true and ParseGraph.GetLauncherFlyoutDirection ~= nil and ParseGraph.GetLauncherFlyoutDirection() == "left";
    row.contextArrowOnLeft = arrowOnLeft;
    local labelX = arrowOnLeft and 30 or 10;
    local labelW = hasSubmenu and (arrowOnLeft and (w - 42) or (w - 32)) or (w - 20);
    local label = Label(row, labelX, 0, labelW, h, text or "", "small");
    label:SetFont(Turbine.UI.Lotro.Font.TrajanPro16);
    label:SetForeColor(Turbine.UI.Color(1.00, 1.00, 0.85, 0.25));
    label:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    label:SetMouseVisible(false);
    row.contextLabel = label;
    row.contextSelected = selected == true;
    ParseGraph.ApplyContextMenuRowState(row, false);

    if hasSubmenu then
        local arrow = Label(row, arrowOnLeft and 8 or (w - 26), 0, 18, h, arrowOnLeft and "<" or ">", "small");
        arrow:SetFont(Turbine.UI.Lotro.Font.TrajanPro16);
        arrow:SetForeColor(Turbine.UI.Color(1.00, 1.00, 0.75, 0.15));
        arrow:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        arrow:SetMouseVisible(false);
        row.contextArrow = arrow;
    end

    row.MouseEnter = function(sender)
        ParseGraph.ApplyContextMenuRowState(sender, true);
        if sender.OpenSubmenu ~= nil then
            sender.OpenSubmenu(sender);
        end
    end
    row.MouseLeave = function(sender)
        ParseGraph.ApplyContextMenuRowState(sender, false);
    end
    row.MouseDown = function(sender)
        sender:SetBackColor(Turbine.UI.Color(1.00, 0.09, 0.16, 0.25));
    end
    row.MouseUp = function(sender)
        ParseGraph.ApplyContextMenuRowState(sender, true);
    end
    if onClick ~= nil then
        row.MouseClick = onClick;
    end
    return row;
end

function ParseGraph.HideParseSpecMenu()
    if ParseGraph.ParseSpecMenuBackdrop ~= nil then
        ParseGraph.ParseSpecMenuBackdrop:SetVisible(false);
        ParseGraph.ParseSpecMenuBackdrop:SetSize(0, 0);
    end
    ParseGraph.ParseSpecMenuBackdrop = nil;

    if ParseGraph.ParseSpecMenuWindow ~= nil then
        ParseGraph.ParseSpecMenuWindow:SetVisible(false);
        ParseGraph.ParseSpecMenuWindow:SetSize(0, 0);
    end
    ParseGraph.ParseSpecMenuWindow = nil;
end

function ParseGraph.ShowParseSpecMenu(anchor, point)
    if anchor == nil or type(point) ~= "table" then
        return;
    end

    ParseGraph.HideLauncherContextMenu();
    ParseGraph.HideScoreboardRowContextMenu();
    if ParseGraph.HideParseHistorySortMenu ~= nil then
        ParseGraph.HideParseHistorySortMenu();
    end
    if ParseGraph.HideInstanceDeleteMenu ~= nil then
        ParseGraph.HideInstanceDeleteMenu();
    end
    if ParseGraph.HideParseSpecFilterMenu ~= nil then
        ParseGraph.HideParseSpecFilterMenu();
    end
    ParseGraph.HideParseSpecMenu();

    local options = ParseGraph.SpecOptions or {};
    if #options == 0 then
