function ParseGraph.CreateContextAliasQuickslot(command, x, y, w, h, visualRow, scope)
    local buttonWindow = Turbine.UI.Window();
    buttonWindow:SetPosition(x, y);
    buttonWindow:SetSize(w, h);
    buttonWindow:SetOpacity(0);
    buttonWindow:SetMouseVisible(true);
    if buttonWindow.SetZOrder ~= nil then
        buttonWindow:SetZOrder(330);
    end
    buttonWindow:SetVisible(true);

    local slot = Turbine.UI.Lotro.Quickslot();
    slot:SetParent(buttonWindow);
    slot:SetPosition(0, 0);
    slot:SetSize(w, h);
    slot:SetZOrder(20);
    slot:SetMouseVisible(true);

    local shortcut = Turbine.UI.Lotro.Shortcut(Turbine.UI.Lotro.ShortcutType.Alias, nil);
    shortcut:SetData(tostring(command or ""));
    slot.shortcut = shortcut;
    slot:SetShortcut(shortcut);
    slot.DragDrop = function(sender)
        sender:SetShortcut(sender.shortcut);
    end
    slot.MouseEnter = function()
        ParseGraph.ApplyContextMenuRowState(visualRow, true);
        if visualRow ~= nil and visualRow.OpenSubmenu ~= nil then
            visualRow.OpenSubmenu(visualRow);
        end
    end
    slot.MouseLeave = function()
        ParseGraph.ApplyContextMenuRowState(visualRow, false);
    end
    slot.MouseDown = function()
        if visualRow ~= nil then
            visualRow:SetBackColor(Turbine.UI.Color(1.00, 0.09, 0.16, 0.25));
        end
    end
    slot.MouseUp = function()
        ParseGraph.HideLauncherContextMenu();
    end

    local list = ParseGraph.ContextMenuAliasWindows;
    if scope == "submenu" then
        if type(ParseGraph.ContextSubmenuAliasWindows) ~= "table" then
            ParseGraph.ContextSubmenuAliasWindows = {};
        end
        list = ParseGraph.ContextSubmenuAliasWindows;
    end
    table.insert(list, {
        window = buttonWindow,
        slot = slot,
        visualRow = visualRow
    });
    return slot;
end

function ParseGraph.ClampContextMenuPosition(x, y, w, h)
    local displayW, displayH = 0, 0;
    if Turbine.UI ~= nil and Turbine.UI.Display ~= nil then
        displayW = tonumber(Turbine.UI.Display.GetWidth()) or 0;
        displayH = tonumber(Turbine.UI.Display.GetHeight()) or 0;
    end
    if displayW > 0 and x + w > displayW - 6 then
        x = math.max(6, displayW - w - 6);
    end
    if displayH > 0 and y + h > displayH - 6 then
        y = math.max(6, displayH - h - 6);
    end
    return x, y;
end


