function ParseGraph.RemoveScoreboardEntry(boardKey, entryKey)
    boardKey = tostring(boardKey or "");
    entryKey = tostring(entryKey or "");
    if entryKey == "" then
        return false;
    end

    local boards = ParseGraph.ScoreboardBoards;
    if type(boards) ~= "table" then
        return false;
    end

    local removed = false;
    if boardKey == "__overall" then
        for _, board in pairs(boards) do
            if type(board) == "table" and type(board.entries) == "table" and board.entries[entryKey] ~= nil then
                board.entries[entryKey] = nil;
                board.updatedAt = ScoreboardNow();
                removed = true;
            end
        end
    else
        local board = boards[boardKey];
        if type(board) == "table" and type(board.entries) == "table" and board.entries[entryKey] ~= nil then
            board.entries[entryKey] = nil;
            board.updatedAt = ScoreboardNow();
            removed = true;
        end
    end

    if removed then
        ParseGraph.ScoreboardBoards = boards;
        if ParseGraph.AccountData ~= nil then
            ParseGraph.AccountData.scoreboards = boards;
            ParseGraph.SaveAccountData();
        end
        if ParseGraph.DrawScoreboardView ~= nil then
            ParseGraph.DrawScoreboardView();
        end
    end

    return removed;
end

