function ParseGraph.ApplyScoreboardRowHover(row, hover)
    if row == nil then
        return;
    end

    local fill = row.normalFill;
    if hover then
        fill = row.hoverFill;
    end

    row:SetBackColor(fill);
    if row.rowBack ~= nil then
        row.rowBack:SetBackColor(fill);
    end
    if row.iconBack ~= nil then
        row.iconBack:SetBackColor(fill);
    end
end

function ParseGraph.AttachScoreboardRowContextHandler(control, row)
    if control == nil or row == nil then
        return;
    end

    local function openMenu(_, args)
        if ParseGraph.IsRightMouseButton(args) then
            ParseGraph.ShowScoreboardRowContextMenu(row, row.scoreboardBoardKey, row.scoreboardEntryKey, args);
        end
    end

    control:SetMouseVisible(true);
    control.MouseEnter = function()
        ParseGraph.ApplyScoreboardRowHover(row, true);
    end
    control.MouseLeave = function()
        ParseGraph.ApplyScoreboardRowHover(row, false);
    end
    control.MouseDown = openMenu;
    control.MouseClick = openMenu;
end
function ParseGraph.ShowLauncherSubmenu(anchorRow, items, width)
    ParseGraph.HideLauncherContextSubmenu();
    if anchorRow == nil or type(items) ~= "table" then
        return;
    end

    local rowH = 28;
    local pad = 6;
    local menuW = tonumber(width) or 230;
    local menuH = pad * 2 + math.max(1, #items) * rowH;
    local anchorX, anchorY = ParseGraph.GetControlScreenPosition(anchorRow);
    local subX = anchorX + anchorRow:GetWidth() + 4;
    if ParseGraph.GetLauncherFlyoutDirection() == "left" then
        subX = anchorX - menuW - 4;
    end
    local subY = anchorY - pad;
    subX, subY = ParseGraph.ClampContextMenuPosition(subX, subY, menuW, menuH);

    local submenu = Turbine.UI.Window();
    ParseGraph.ContextSubmenuWindow = submenu;
    submenu:SetPosition(subX, subY);
    submenu:SetSize(menuW, menuH);
    submenu:SetOpacity(1);
    submenu:SetMouseVisible(true);
    submenu:SetBackColor(Turbine.UI.Color(1.00, 0.00, 0.00, 0.00));
    if submenu.SetZOrder ~= nil then
        submenu:SetZOrder(320);
    end
    CreateContextMenuBorder(submenu, menuW, menuH, Turbine.UI.Color(1.00, 0.95, 0.55, 0.05));

    for i = 1, #items do
        local item = items[i];
        local row = ParseGraph.CreateContextMenuRow(submenu, pad, pad + (i - 1) * rowH, menuW - pad * 2, rowH - 1, item.text, false, item.onClick, item.selected == true);
        if item.segments ~= nil then
            ParseGraph.ApplyContextMenuRowSegments(row, item.segments, false);
        end
        if item.disabled == true then
            row:SetMouseVisible(false);
            row.contextLabel:SetForeColor(Turbine.UI.Color(0.70, 0.55, 0.55, 0.55));
        elseif item.aliasCommand ~= nil then
            row:SetMouseVisible(false);
            ParseGraph.CreateContextAliasQuickslot(item.aliasCommand, subX + pad, subY + pad + (i - 1) * rowH, menuW - pad * 2, rowH - 1, row, "submenu");
        end
    end
    submenu:SetVisible(true);
    submenu:Activate();
end

function ParseGraph.HideSidebarParsesFlyout()
    ParseGraph.SidebarParsesFlyoutHideAt = nil;

    if ParseGraph.SidebarParsesFlyoutTimer ~= nil then
        ParseGraph.SidebarParsesFlyoutTimer:SetWantsUpdates(false);
    end

    if ParseGraph.SidebarParsesFlyoutWindow ~= nil then
        ParseGraph.SidebarParsesFlyoutWindow:SetVisible(false);
        ParseGraph.SidebarParsesFlyoutWindow:SetSize(0, 0);
    end
    ParseGraph.SidebarParsesFlyoutWindow = nil;
end

function ParseGraph.CancelSidebarParsesFlyoutHide()
    ParseGraph.SidebarParsesFlyoutHideAt = nil;

    if ParseGraph.SidebarParsesFlyoutTimer ~= nil then
        ParseGraph.SidebarParsesFlyoutTimer:SetWantsUpdates(false);
    end
end

function ParseGraph.ScheduleSidebarParsesFlyoutHide()
    if ParseGraph.SidebarParsesFlyoutWindow == nil then return end

    ParseGraph.SidebarParsesFlyoutHideAt = Turbine.Engine.GetGameTime() + 0.18;

    if ParseGraph.SidebarParsesFlyoutTimer == nil then
        ParseGraph.SidebarParsesFlyoutTimer = Turbine.UI.Control();
        ParseGraph.SidebarParsesFlyoutTimer:SetSize(1, 1);
        ParseGraph.SidebarParsesFlyoutTimer:SetVisible(false);
        ParseGraph.SidebarParsesFlyoutTimer.Update = function()
            if ParseGraph.SidebarParsesFlyoutHideAt == nil then
                ParseGraph.SidebarParsesFlyoutTimer:SetWantsUpdates(false);
                return;
            end

            if Turbine.Engine.GetGameTime() >= ParseGraph.SidebarParsesFlyoutHideAt then
                ParseGraph.HideSidebarParsesFlyout();
            end
        end;
    end

    if ParseGraph.RootPanel ~= nil then
        ParseGraph.SidebarParsesFlyoutTimer:SetParent(ParseGraph.RootPanel);
        ParseGraph.SidebarParsesFlyoutTimer:SetPosition(0, 0);
    end

    ParseGraph.SidebarParsesFlyoutTimer:SetWantsUpdates(true);
end

