function ParseGraph.ShowSidebarParsesFlyout(anchorButton)
    if anchorButton == nil then return end

    ParseGraph.CancelSidebarParsesFlyoutHide();

    if ParseGraph.HideLauncherContextMenu ~= nil then
        ParseGraph.HideLauncherContextMenu();
    end
    if ParseGraph.HideParseHistorySortMenu ~= nil then
        ParseGraph.HideParseHistorySortMenu();
    end
    if ParseGraph.HideSidebarPostChannelFlyout ~= nil then
        ParseGraph.HideSidebarPostChannelFlyout();
    end
    if ParseGraph.HideSidebarHistoryFlyout ~= nil then
        ParseGraph.HideSidebarHistoryFlyout();
    end
    if ParseGraph.HideSidebarAchievementsFlyout ~= nil then
        ParseGraph.HideSidebarAchievementsFlyout();
    end
    if ParseGraph.HideSidebarInstancesFlyout ~= nil then
        ParseGraph.HideSidebarInstancesFlyout();
    end
    if ParseGraph.HideSidebarScoreboardFlyout ~= nil then
        ParseGraph.HideSidebarScoreboardFlyout();
    end

    if ParseGraph.SidebarParsesFlyoutWindow ~= nil then
        ParseGraph.SidebarParsesFlyoutWindow:SetVisible(false);
        ParseGraph.SidebarParsesFlyoutWindow:SetSize(0, 0);
        ParseGraph.SidebarParsesFlyoutWindow = nil;
    end

    local menuW = 140;
    local rowH = 31;
    local pad = 6;
    local items = {
        {
            text = "Import",
            selected = false,
            onClick = function()
                if ParseGraph.ShowParseStringImportWindow ~= nil then
                    ParseGraph.ShowParseStringImportWindow();
                end
            end
        }
    };
    local menuH = pad * 2 + rowH * #items;
    local anchorX, anchorY = ParseGraph.GetControlScreenPosition(anchorButton);
    local menuX = (anchorX or 0) + anchorButton:GetWidth() + 8;
    local menuY = (anchorY or 0) - 2;
    menuX, menuY = ParseGraph.ClampContextMenuPosition(menuX, menuY, menuW, menuH);

    local menu = Turbine.UI.Window();
    ParseGraph.SidebarParsesFlyoutWindow = menu;
    menu:SetPosition(menuX, menuY);
    menu:SetSize(menuW, menuH);
    menu:SetOpacity(1);
    menu:SetMouseVisible(true);
    menu:SetBackColor(Turbine.UI.Color(1.00, 0.00, 0.00, 0.00));
    if menu.SetZOrder ~= nil then
        menu:SetZOrder(330);
    end
    CreateContextMenuBorder(menu, menuW, menuH, Turbine.UI.Color(1.00, 0.95, 0.55, 0.05));

    menu.MouseEnter = function()
        ParseGraph.CancelSidebarParsesFlyoutHide();
    end;
    menu.MouseLeave = function()
        ParseGraph.ScheduleSidebarParsesFlyoutHide();
    end;

    for i = 1, #items do
        local item = items[i];
        ParseGraph.CreateContextMenuRow(menu, pad, pad + (i - 1) * rowH, menuW - pad * 2, rowH - 1, item.text, false, function()
            ParseGraph.HideSidebarParsesFlyout();
            item.onClick();
        end, item.selected == true);
    end

    menu:SetVisible(true);
    menu:Activate();
end

function ParseGraph.AttachParsesSidebarFlyout(button)
    if button == nil or button.ParseGraphParsesFlyoutAttached == true then return end

    button.ParseGraphParsesFlyoutAttached = true;

    local originalMouseEnter = button.MouseEnter;
    local originalMouseLeave = button.MouseLeave;
    local originalMouseClick = button.MouseClick;

    button.MouseEnter = function(sender, args)
        if originalMouseEnter ~= nil then
            originalMouseEnter(sender, args);
        end
        ParseGraph.ShowSidebarParsesFlyout(sender);
    end;

    button.MouseLeave = function(sender, args)
        if originalMouseLeave ~= nil then
            originalMouseLeave(sender, args);
        end
        ParseGraph.ScheduleSidebarParsesFlyoutHide();
    end;

    button.MouseClick = function(sender, args)
        ParseGraph.HideSidebarParsesFlyout();
        if originalMouseClick ~= nil then
            originalMouseClick(sender, args);
        end
    end;
end

function ParseGraph.HideSidebarHistoryFlyout()
    ParseGraph.SidebarHistoryFlyoutHideAt = nil;

    if ParseGraph.SidebarHistoryFlyoutTimer ~= nil then
