function ParseGraph.OpenSidebarInstanceMode(mode)
    mode = tostring(mode or "damage");
    ParseGraph.ClearTemporaryInstanceTarget();

    if mode == "unmatched" then
        ParseGraph.InstanceViewMode = "unmatched";
    elseif mode == "statistics" then
        ParseGraph.InstanceViewMode = "statistics";
    elseif mode == "groupLists" then
        ParseGraph.InstanceViewMode = "groupLists";
    else
        ParseGraph.InstanceMetricMode = ParseGraph.NormalizeInstanceMetricMode(mode);
        ParseGraph.InstanceViewMode = "overview";
    end

    ParseGraph.SetView("instances");
end

