        ParseGraph.ShowSidebarAchievementsFlyout(sender);
    end;

    button.MouseLeave = function(sender, args)
        if originalMouseLeave ~= nil then
            originalMouseLeave(sender, args);
        end
        ParseGraph.ScheduleSidebarAchievementsFlyoutHide();
    end;

    button.MouseClick = function(sender, args)
        ParseGraph.HideSidebarAchievementsFlyout();
        if originalMouseClick ~= nil then
            originalMouseClick(sender, args);
        end
    end;
end

function ParseGraph.HideSidebarPostChannelFlyout()
    ParseGraph.SidebarPostChannelFlyoutHideAt = nil;

    if ParseGraph.SidebarPostChannelFlyoutTimer ~= nil then
        ParseGraph.SidebarPostChannelFlyoutTimer:SetWantsUpdates(false);
    end

    if ParseGraph.SidebarPostChannelFlyoutWindow ~= nil then
        ParseGraph.SidebarPostChannelFlyoutWindow:SetVisible(false);
        ParseGraph.SidebarPostChannelFlyoutWindow:SetSize(0, 0);
    end
    ParseGraph.SidebarPostChannelFlyoutWindow = nil;
end

function ParseGraph.CancelSidebarPostChannelFlyoutHide()
    ParseGraph.SidebarPostChannelFlyoutHideAt = nil;

    if ParseGraph.SidebarPostChannelFlyoutTimer ~= nil then
        ParseGraph.SidebarPostChannelFlyoutTimer:SetWantsUpdates(false);
    end
end

function ParseGraph.ScheduleSidebarPostChannelFlyoutHide()
    if ParseGraph.SidebarPostChannelFlyoutWindow == nil then return end

    ParseGraph.SidebarPostChannelFlyoutHideAt = Turbine.Engine.GetGameTime() + 0.18;

    if ParseGraph.SidebarPostChannelFlyoutTimer == nil then
        ParseGraph.SidebarPostChannelFlyoutTimer = Turbine.UI.Control();
        ParseGraph.SidebarPostChannelFlyoutTimer:SetSize(1, 1);
        ParseGraph.SidebarPostChannelFlyoutTimer:SetVisible(false);
        ParseGraph.SidebarPostChannelFlyoutTimer.Update = function()
            if ParseGraph.SidebarPostChannelFlyoutHideAt == nil then
                ParseGraph.SidebarPostChannelFlyoutTimer:SetWantsUpdates(false);
                return;
            end

            if Turbine.Engine.GetGameTime() >= ParseGraph.SidebarPostChannelFlyoutHideAt then
                ParseGraph.HideSidebarPostChannelFlyout();
            end
        end;
    end

    if ParseGraph.RootPanel ~= nil then
        ParseGraph.SidebarPostChannelFlyoutTimer:SetParent(ParseGraph.RootPanel);
        ParseGraph.SidebarPostChannelFlyoutTimer:SetPosition(0, 0);
    end

    ParseGraph.SidebarPostChannelFlyoutTimer:SetWantsUpdates(true);
end

function ParseGraph.ShowSidebarPostChannelFlyout(anchorButton)
    if anchorButton == nil then return end

    ParseGraph.CancelSidebarPostChannelFlyoutHide();

    if ParseGraph.HideLauncherContextMenu ~= nil then
        ParseGraph.HideLauncherContextMenu();
    end
    if ParseGraph.HideParseHistorySortMenu ~= nil then
        ParseGraph.HideParseHistorySortMenu();
    end
    if ParseGraph.HideSidebarParsesFlyout ~= nil then
        ParseGraph.HideSidebarParsesFlyout();
    end
    if ParseGraph.HideSidebarHistoryFlyout ~= nil then
        ParseGraph.HideSidebarHistoryFlyout();
    end
    if ParseGraph.HideSidebarAchievementsFlyout ~= nil then
        ParseGraph.HideSidebarAchievementsFlyout();
    end
    if ParseGraph.HideSidebarInstancesFlyout ~= nil then
        ParseGraph.HideSidebarInstancesFlyout();
    end
    if ParseGraph.HideSidebarScoreboardFlyout ~= nil then
        ParseGraph.HideSidebarScoreboardFlyout();
    end

    if ParseGraph.SidebarPostChannelFlyoutWindow ~= nil then
        ParseGraph.SidebarPostChannelFlyoutWindow:SetVisible(false);
        ParseGraph.SidebarPostChannelFlyoutWindow:SetSize(0, 0);
        ParseGraph.SidebarPostChannelFlyoutWindow = nil;
    end

    local menuW = 268;
    local rowH = 31;
    local pad = 6;
    local selected = NormalizePostChannel(ParseGraph.PostChannel);
    local items = {};

    for i = 1, #ParseGraph.PostChannels do
        local info = ParseGraph.PostChannels[i];
        if ParseGraph.IsPostChannelAvailable(info) then
            local key = info.key;
            local text = tostring(info.label or key);
            if key == "faillowship" then
                text = tostring(ParseGraph.FaillowshipRoomName or info.label or key);
            end
            table.insert(items, {
                text = text,
                selected = key == selected,
                onClick = function()
                    ParseGraph.SetPostChannel(key);
                end
            });
        end
    end

    local menuH = pad * 2 + rowH * #items;
    local anchorX, anchorY = ParseGraph.GetControlScreenPosition(anchorButton);
    local menuX = (anchorX or 0) + anchorButton:GetWidth() + 8;
    local menuY = (anchorY or 0) - 2;
    menuX, menuY = ParseGraph.ClampContextMenuPosition(menuX, menuY, menuW, menuH);

    local menu = Turbine.UI.Window();
    ParseGraph.SidebarPostChannelFlyoutWindow = menu;
    menu:SetPosition(menuX, menuY);
    menu:SetSize(menuW, menuH);
    menu:SetOpacity(1);
    menu:SetMouseVisible(true);
    menu:SetBackColor(Turbine.UI.Color(1.00, 0.00, 0.00, 0.00));
    if menu.SetZOrder ~= nil then
        menu:SetZOrder(330);
    end
    CreateContextMenuBorder(menu, menuW, menuH, Turbine.UI.Color(1.00, 0.95, 0.55, 0.05));

    menu.MouseEnter = function()
        ParseGraph.CancelSidebarPostChannelFlyoutHide();
    end;
    menu.MouseLeave = function()
        ParseGraph.ScheduleSidebarPostChannelFlyoutHide();
    end;

    for i = 1, #items do
        local item = items[i];
        ParseGraph.CreateContextMenuRow(menu, pad, pad + (i - 1) * rowH, menuW - pad * 2, rowH - 1, item.text, false, function()
            ParseGraph.HideSidebarPostChannelFlyout();
            item.onClick();
        end, item.selected == true);
    end

    menu:SetVisible(true);
    menu:Activate();
end

function ParseGraph.AttachPostChannelSidebarFlyout(button)
    if button == nil or button.ParseGraphPostChannelFlyoutAttached == true then return end

    button.ParseGraphPostChannelFlyoutAttached = true;

    local originalMouseEnter = button.MouseEnter;
    local originalMouseLeave = button.MouseLeave;

    button.MouseEnter = function(sender, args)
        if originalMouseEnter ~= nil then
            originalMouseEnter(sender, args);
        end
    end;

    button.MouseLeave = function(sender, args)
        if originalMouseLeave ~= nil then
            originalMouseLeave(sender, args);
        end
        ParseGraph.ScheduleSidebarPostChannelFlyoutHide();
    end;

    button.MouseClick = function(sender)
        ParseGraph.ShowSidebarPostChannelFlyout(sender);
    end;
end

function ParseGraph.HideParseHistorySortMenu()
    if ParseGraph.ParseHistorySortMenuBackdrop ~= nil then
        ParseGraph.ParseHistorySortMenuBackdrop:SetVisible(false);
        ParseGraph.ParseHistorySortMenuBackdrop:SetSize(0, 0);
    end
    ParseGraph.ParseHistorySortMenuBackdrop = nil;

    if ParseGraph.ParseHistorySortMenuWindow ~= nil then
        ParseGraph.ParseHistorySortMenuWindow:SetVisible(false);
        ParseGraph.ParseHistorySortMenuWindow:SetSize(0, 0);
    end
    ParseGraph.ParseHistorySortMenuWindow = nil;
end

function ParseGraph.BuildParseHistorySortMenuItems()
    local current = tostring(ParseGraph.ParseHistorySortKey or "number");
    local items = {
        { key = "number", label = "Parse number" },
        { key = "final", label = "Final DPS" },
        { key = "name", label = "Name" },
        { key = "class", label = "Class" }
    };

    for i = 1, #items do
        local item = items[i];
        local sortKey = item.key;
        local selected = item.key == current;
        local text = item.label;
        if selected then
            text = text .. " - " .. ParseGraph.GetParseHistorySortDirectionText();
        end
        item.text = text;
        item.selected = selected;
        item.onClick = function()
            ParseGraph.HideParseHistorySortMenu();
            ParseGraph.SetParseHistorySort(sortKey);
        end
    end

    return items;
end

function ParseGraph.ShowParseHistorySortMenu()
    if ParseGraph.ParseHistorySortMenuWindow ~= nil and ParseGraph.ParseHistorySortMenuWindow:IsVisible() then
        ParseGraph.HideParseHistorySortMenu();
        return;
    end

    ParseGraph.HideLauncherContextMenu();
    if ParseGraph.HideParseSpecMenu ~= nil then
        ParseGraph.HideParseSpecMenu();
    end
    if ParseGraph.HideParseSpecFilterMenu ~= nil then
        ParseGraph.HideParseSpecFilterMenu();
    end
    ParseGraph.HideParseHistorySortMenu();

    local anchor = ParseGraph.ParseHistorySortButton;
    if anchor == nil then
        return;
    end

    local items = ParseGraph.BuildParseHistorySortMenuItems();
    local menuW = 255;
    local rowH = 30;
    local pad = 7;
    local menuH = pad * 2 + (rowH * #items);
    local x, y = ParseGraph.GetControlScreenPosition(anchor);
    y = y + anchor:GetHeight() + 4;
    x, y = ParseGraph.ClampContextMenuPosition(x, y, menuW, menuH);

    local backdrop = Turbine.UI.Window();
    ParseGraph.ParseHistorySortMenuBackdrop = backdrop;
    local displayW, displayH = 2000, 1200;
    if Turbine.UI ~= nil and Turbine.UI.Display ~= nil then
        displayW = tonumber(Turbine.UI.Display.GetWidth()) or displayW;
        displayH = tonumber(Turbine.UI.Display.GetHeight()) or displayH;
    end
    backdrop:SetPosition(0, 0);
    backdrop:SetSize(displayW, displayH);
    backdrop:SetOpacity(0);
    backdrop:SetMouseVisible(true);
    if backdrop.SetZOrder ~= nil then
        backdrop:SetZOrder(300);
    end
    backdrop.MouseDown = function()
        ParseGraph.HideParseHistorySortMenu();
    end
    backdrop.MouseClick = function()
        ParseGraph.HideParseHistorySortMenu();
    end
    backdrop:SetVisible(true);

    local menu = Turbine.UI.Window();
    ParseGraph.ParseHistorySortMenuWindow = menu;
    menu:SetPosition(x, y);
    menu:SetSize(menuW, menuH);
    menu:SetOpacity(1);
    menu:SetMouseVisible(true);
    menu:SetBackColor(Turbine.UI.Color(1.00, 0.00, 0.00, 0.00));
    if menu.SetZOrder ~= nil then
        menu:SetZOrder(310);
    end
    CreateContextMenuBorder(menu, menuW, menuH, Turbine.UI.Color(1.00, 0.95, 0.55, 0.05));

    for i = 1, #items do
        local item = items[i];
        ParseGraph.CreateContextMenuRow(menu, pad, pad + ((i - 1) * rowH), menuW - (pad * 2), rowH - 1, item.text, false, item.onClick, item.selected == true);
    end

    menu:SetVisible(true);
    menu:Activate();
end

function ParseGraph.ShowUnmatchedSelectionSubmenu(anchorRow, items, width)
    ParseGraph.HideLauncherContextMenu();
    if anchorRow == nil or type(items) ~= "table" then
        return;
    end

    local backdrop = Turbine.UI.Window();
    ParseGraph.ContextMenuBackdrop = backdrop;
    local displayW, displayH = 2000, 1200;
    if Turbine.UI ~= nil and Turbine.UI.Display ~= nil then
        displayW = tonumber(Turbine.UI.Display.GetWidth()) or displayW;
        displayH = tonumber(Turbine.UI.Display.GetHeight()) or displayH;
    end
    backdrop:SetPosition(0, 0);
    backdrop:SetSize(displayW, displayH);
    backdrop:SetOpacity(0);
    backdrop:SetMouseVisible(true);
    if backdrop.SetZOrder ~= nil then
        backdrop:SetZOrder(300);
    end
    backdrop.MouseDown = function()
        ParseGraph.HideLauncherContextMenu();
    end
    backdrop.MouseClick = function()
        ParseGraph.HideLauncherContextMenu();
    end
    backdrop:SetVisible(true);

    ParseGraph.ShowLauncherSubmenu(anchorRow, items, width);
end

function ParseGraph.SetContextInstance(instanceKey)
    local instance = ParseGraph.GetInstanceDefinition(instanceKey);
    if instance == nil then
        return;
    end
    local tierKey = GetContextTargetTierKey();
    ParseGraph.ActiveInstanceKey = instance.key;
    ParseGraph.ActiveInstanceTierKey = tierKey;
    ParseGraph.AutoInstanceBossIndex = nil;
    ParseGraph.AutoInstanceDefeats = nil;
    ParseGraph.SelectedInstanceKey = instance.key;
    ParseGraph.ClearTemporaryInstanceTarget();
    ParseGraph.ManualInstanceTarget = nil;
    ParseGraph.PrintInstanceMessage("Active instance set: " .. tostring(instance.name or "") .. " - " .. ParseGraph.GetInstanceTierLabel(tierKey) .. ".");
    ParseGraph.SetLauncherButtonState();
    if ParseGraph.CurrentView == "instances" then
        ParseGraph.DrawInstancesView();
    end
end

function ParseGraph.SetContextBossTarget(bossIndex)
    local instance = ParseGraph.GetInstanceDefinition(GetContextTargetInstanceKey());
    if instance == nil or type(instance.bosses) ~= "table" then
        return;
    end
    bossIndex = tonumber(bossIndex) or 1;
    if instance.bosses[bossIndex] == nil then
        return;
    end
    local tierKey = GetContextTargetTierKey();
    ParseGraph.ActiveInstanceKey = instance.key;
    ParseGraph.ActiveInstanceTierKey = tierKey;
    ParseGraph.AutoInstanceBossIndex = bossIndex;
    if ParseGraph.ResetAutoInstanceBossDefeats ~= nil then
        ParseGraph.ResetAutoInstanceBossDefeats(instance.key, tierKey, bossIndex);
    end
    ParseGraph.SelectedInstanceKey = instance.key;
    ParseGraph.SelectedInstanceTierKey = tierKey;
    ParseGraph.SelectedInstanceBossIndex = bossIndex;
    ParseGraph.ManualInstanceTarget = {
        instanceKey = instance.key,
        tierKey = tierKey,
        bossIndex = bossIndex
    };
    ParseGraph.PrintInstanceMessage("Manual boss target set: " .. tostring(instance.name or "") .. " - " .. ParseGraph.GetInstanceTierLabel(tierKey) .. " - Boss " .. tostring(bossIndex) .. ".");
    ParseGraph.SetLauncherButtonState();
    if ParseGraph.CurrentView == "instances" then
        ParseGraph.DrawInstancesView();
    end
end

function ParseGraph.BuildPostParseContextItems()
    local items = {};
    local point = ParseGraph.GetLatestContextParsePoint();
    if point == nil or point.parse == nil then
        table.insert(items, { text = "No parse saved", disabled = true });
        return items;
    end

    for i = 1, #ParseGraph.PostChannels do
        local channel = ParseGraph.PostChannels[i];
        if channel.requiresFaillowship ~= true or ParseGraph.FaillowshipJoined == true then
            table.insert(items, {
                text = tostring(channel.label or channel.key),
                selected = channel.key == NormalizePostChannel(ParseGraph.PostChannel),
                aliasCommand = ParseGraph.BuildPostCommand(point.parse, point.index, channel.key)
            });
        end
    end
    return items;
end

function ParseGraph.BuildSelectedPostParseContextCommand()
    local point = ParseGraph.GetLatestContextParsePoint();
    if point == nil or point.parse == nil then
        return nil;
    end
    return ParseGraph.BuildPostCommand(point.parse, point.index);
end

function ParseGraph.BuildPostListContextItems()
    local items = {};
    for i = 1, #ParseGraph.PostChannels do
        local channel = ParseGraph.PostChannels[i];
        if channel.requiresFaillowship ~= true or ParseGraph.FaillowshipJoined == true then
            table.insert(items, {
                text = tostring(channel.label or channel.key),
                selected = channel.key == NormalizePostChannel(ParseGraph.PostChannel),
                aliasCommand = ParseGraph.BuildGroupListsPostCommand(channel.key)
            });
        end
    end
    return items;
end

function ParseGraph.BuildDummyPauseContextItems()
    local items = {};
    local paused = ParseGraph.IsDummyParsingPaused();
    local options = {
        { text = "30 minutes", mode = "30m" },
        { text = "1 hour", mode = "1h" },
        { text = "Today", mode = "today" },
        { text = "Until I resume", mode = "manual" }
    };
    for i = 1, #options do
        local option = options[i];
        table.insert(items, {
            text = option.text,
            onClick = function()
                ParseGraph.HideLauncherContextMenu();
                if paused then
                    ParseGraph.ResumeDummyParsing(true);
                else
                    ParseGraph.SetDummyParsePause(option.mode);
                end
            end
        });
    end
    return items;
end

function ParseGraph.BuildSelectedPostListContextCommand()
    return ParseGraph.BuildGroupListsPostCommand();
end

function ParseGraph.BuildTierContextItems()
    local items = {};
    local currentTier = GetContextSelectedTierKey();
    local instanceKey = GetContextExplicitInstanceKey();
    for i = 1, #ParseGraph.InstanceTiers do
        local tier = ParseGraph.InstanceTiers[i];
        local tierKey = tier.key;
        local text = tostring(tier.label or tier.key);
        table.insert(items, {
            text = text,
            selected = tierKey == currentTier,
            onClick = function()
                ParseGraph.HideLauncherContextMenu();
                ParseGraph.ClearTemporaryInstanceTarget();
                if instanceKey ~= nil then
                    ParseGraph.SetActiveInstanceTier(instanceKey, tierKey);
                else
                    ParseGraph.SetContextTierOnly(tierKey);
                end
            end
        });
    end
    return items;
end

function ParseGraph.BuildInstanceContextItems()
    local items = {};
    local currentInstanceKey = GetContextSelectedInstanceKey();
    local orderedInstances = ParseGraph.GetOrderedInstanceDefinitions();
    for i = 1, #orderedInstances do
        local instance = orderedInstances[i];
        local instanceKey = instance.key;
        local line1, line2 = ParseGraph.GetInstanceButtonLines(instance);
        local text = tostring(line1 or instance.name or instance.key);
        if line2 ~= nil and tostring(line2) ~= "" then
            text = text .. " - " .. tostring(line2);
        end
        table.insert(items, {
            text = text,
            selected = instanceKey == currentInstanceKey,
            onClick = function()
                ParseGraph.HideLauncherContextMenu();
                ParseGraph.SetContextInstance(instanceKey);
            end
        });
    end
    return items;
end

function ParseGraph.BuildBossContextItems()
    local items = {};
    local instanceKey = GetContextBossMenuInstanceKey();
    local instance = ParseGraph.GetInstanceDefinition(instanceKey);
    local currentBoss = GetContextSelectedBossIndex();
    if instance == nil or type(instance.bosses) ~= "table" then
        table.insert(items, { text = "No instance selected", disabled = true });
        return items;
    end

    for i = 1, #instance.bosses do
        local boss = instance.bosses[i] or {};
        local bossIndex = i;
        local text = "Boss " .. tostring(i);
        local bossLabel = boss.contextName or boss.name;
        if bossLabel ~= nil and tostring(bossLabel) ~= "" then
            text = text .. " - " .. tostring(bossLabel);
        end
        table.insert(items, {
            text = text,
            selected = bossIndex == currentBoss,
            onClick = function()
                ParseGraph.HideLauncherContextMenu();
                ParseGraph.SetContextBossTarget(bossIndex);
            end
        });
    end
    return items;
end

function ParseGraph.BuildLauncherSpecContextItems()
    local items = {};
    local currentSpec = ParseGraph.GetCurrentDetectedSpecKey();
    local options = ParseGraph.SpecOptions or {};
    for i = 1, #options do
        local option = options[i] or {};
        local optionKey = ParseGraph.NormalizeParseSpecKey(option.key);
        if optionKey ~= nil then
            table.insert(items, {
                text = tostring(option.label or optionKey) .. " spec",
                segments = ParseGraph.GetSpecContextSegments(optionKey),
                selected = optionKey == currentSpec,
                onClick = function()
                    ParseGraph.HideLauncherContextMenu();
                    ParseGraph.ApplyDetectedSpec(optionKey, 0, "launcher menu");
                end
            });
        end
    end
    return items;
end

function ParseGraph.GetLauncherSpecContextText()
    local currentSpec = ParseGraph.GetCurrentDetectedSpecKey();
    if currentSpec == nil then
        return "Spec";
    end

    local spec = ParseGraph.GetParseSpecDefinition(currentSpec);
    return tostring((spec ~= nil and spec.label) or currentSpec) .. " spec";
end

function ParseGraph.GetLauncherSpecContextSegments()
    return ParseGraph.GetSpecContextSegments(ParseGraph.GetCurrentDetectedSpecKey());
end

local function GetContextInstanceShortLabel()
    local instance = ParseGraph.GetInstanceDefinition(GetContextTargetInstanceKey());
    if instance == nil then
        return "None";
    end
    local line1, line2 = ParseGraph.GetInstanceButtonLines(instance);
    if line2 ~= nil and tostring(line2) ~= "" then
        return tostring(line1);
    end
    return tostring(line1 or instance.name or instance.key);
end

function ParseGraph.ShowLauncherContextMenu()
    if ParseGraph.ContextMenuWindow ~= nil and ParseGraph.ContextMenuWindow:IsVisible() then
        ParseGraph.HideLauncherContextMenu();
        return;
    end
    ParseGraph.HideLauncherContextMenu();
    if ParseGraph.HideParseSpecMenu ~= nil then
        ParseGraph.HideParseSpecMenu();
    end
    if ParseGraph.HideParseSpecFilterMenu ~= nil then
        ParseGraph.HideParseSpecFilterMenu();
    end

    local menuW = 140;
    local rowH = 30;
    local pad = 7;
    local menuH = pad * 2 + rowH * 7;
    local x, y = 80, 80;
    if ParseGraph.LauncherButton ~= nil then
        x, y = ParseGraph.GetControlScreenPosition(ParseGraph.LauncherButton);
        if ParseGraph.GetLauncherFlyoutDirection() == "left" then
            x = x - menuW - 5;
        else
            x = x + (tonumber(ParseGraph.LauncherButtonSize) or ParseGraph.GetLauncherButtonSize()) + 5;
        end
    end
    x, y = ParseGraph.ClampContextMenuPosition(x, y, menuW, menuH);

    local menu = Turbine.UI.Window();
    ParseGraph.ContextMenuWindow = menu;
    local backdrop = Turbine.UI.Window();
    ParseGraph.ContextMenuBackdrop = backdrop;
    local displayW, displayH = 2000, 1200;
    if Turbine.UI ~= nil and Turbine.UI.Display ~= nil then
        displayW = tonumber(Turbine.UI.Display.GetWidth()) or displayW;
        displayH = tonumber(Turbine.UI.Display.GetHeight()) or displayH;
    end
    backdrop:SetPosition(0, 0);
    backdrop:SetSize(displayW, displayH);
    backdrop:SetOpacity(0);
    backdrop:SetMouseVisible(true);
    if backdrop.SetZOrder ~= nil then
        backdrop:SetZOrder(300);
    end
    backdrop.MouseDown = function()
        ParseGraph.HideLauncherContextMenu();
    end
    backdrop.MouseClick = function()
        ParseGraph.HideLauncherContextMenu();
    end
    backdrop:SetVisible(true);

    menu:SetPosition(x, y);
    menu:SetSize(menuW, menuH);
    menu:SetOpacity(1);
    menu:SetMouseVisible(true);
    menu:SetBackColor(Turbine.UI.Color(1.00, 0.00, 0.00, 0.00));
    if menu.SetZOrder ~= nil then
        menu:SetZOrder(310);
    end
    CreateContextMenuBorder(menu, menuW, menuH, Turbine.UI.Color(1.00, 0.95, 0.55, 0.05));

    local rows = {
        { text = "Post parse", items = ParseGraph.BuildPostParseContextItems, width = 190, aliasCommand = ParseGraph.BuildSelectedPostParseContextCommand },
        { text = "Post list", items = ParseGraph.BuildPostListContextItems, width = 190, aliasCommand = ParseGraph.BuildSelectedPostListContextCommand },
        {
            text = ParseGraph.IsDummyParsingPaused() and "Paused" or "Pause",
            segments = ParseGraph.IsDummyParsingPaused() and {
                { text = "Paused", color = Turbine.UI.Color(1.00, 1.00, 0.25, 0.25), width = 70 }
            } or nil,
            items = ParseGraph.BuildDummyPauseContextItems,
            width = 170,
            onClick = ParseGraph.IsDummyParsingPaused() and function()
                ParseGraph.HideLauncherContextMenu();
                ParseGraph.ResumeDummyParsing(true);
            end or nil
        },
        { text = ParseGraph.GetLauncherSpecContextText(), segments = ParseGraph.GetLauncherSpecContextSegments(), items = ParseGraph.BuildLauncherSpecContextItems, width = 145, selected = ParseGraph.GetCurrentDetectedSpecKey() ~= nil },
        { text = "Tier", items = ParseGraph.BuildTierContextItems, width = 170, selected = GetContextSelectedTierKey() ~= nil },
        { text = "Instance", items = ParseGraph.BuildInstanceContextItems, width = 320, selected = GetContextSelectedInstanceKey() ~= nil },
        { text = "Boss", items = ParseGraph.BuildBossContextItems, width = 310, selected = GetContextSelectedBossIndex() ~= nil }
    };

    for i = 1, #rows do
        local rowData = rows[i];
        local rowY = pad + (i - 1) * rowH;
        local row = ParseGraph.CreateContextMenuRow(menu, pad, rowY, menuW - pad * 2, rowH - 1, rowData.text, true, rowData.onClick, rowData.selected == true);
        if rowData.segments ~= nil then
            ParseGraph.ApplyContextMenuRowSegments(row, rowData.segments, true);
        end
        row.contextItems = rowData.items;
        row.contextWidth = rowData.width;
        row.OpenSubmenu = function(sender)
            local items = {};
            if sender.contextItems ~= nil then
                items = sender.contextItems();
            end
            ParseGraph.ShowLauncherSubmenu(sender, items, sender.contextWidth);
        end
        if rowData.aliasCommand ~= nil then
            local aliasCommand = rowData.aliasCommand();
            if aliasCommand ~= nil then
                row:SetMouseVisible(false);
                ParseGraph.CreateContextAliasQuickslot(aliasCommand, x + pad, y + rowY, menuW - pad * 2, rowH - 1, row, "main");
            end
        end
    end

    menu:SetVisible(true);
    menu:Activate();
end

function ParseGraph.CreatePostButton(parent, parse, x, y, w, h, postType, view, parseNumber)
    local button = nil;
    if w <= 70 and h <= 22 then
        button = ParseGraph.CreateRowButton(parent, x, y, w, h, "Post", "row_post_button", nil);
    else
        button = ParseGraph.CreateActionButton(parent, x, y, w, h, "Post", nil);
    end
    button:SetMouseVisible(false);

    local command = nil;
    if postType == "personalBest" then
        command = ParseGraph.BuildPersonalBestPostCommand(parse);
    else
        command = ParseGraph.BuildPostCommand(parse, parseNumber);
    end

    return ParseGraph.CreateAliasQuickslot(parent, command, x, y, w, h, view, button);
end

function ParseGraph.RefreshSummaryPostButton()
    if ParseGraph.MainView == nil or ParseGraph.SummaryPostButton == nil then
        return;
    end

    ParseGraph.CreateAliasQuickslot(
        ParseGraph.MainView,
        ParseGraph.BuildSummaryPostCommand(),
        610,
        551,
        145,
