function ParseGraph.GetSessionProgress(ignoreSpecFilter)
    local sessionStart = tonumber(ParseGraph.SessionStartCount) or 0;
    local sessionTotal = 0;
    local sessionCount = 0;
    local previousTotal = 0;
    local previousCount = 0;
    local parses = ParseGraph.Parses or {};

    for i = 1, #parses do
        local p = parses[i];
        if ignoreSpecFilter == true or ParseGraph.ParseMatchesSpecFilter(p) then
            local value = tonumber(p.final) or 0;

            if i > sessionStart then
                sessionTotal = sessionTotal + value;
                sessionCount = sessionCount + 1;
            else
                previousTotal = previousTotal + value;
                previousCount = previousCount + 1;
            end
        end
    end

    if sessionCount == 0 or previousCount == 0 then
        return nil;
    end

    return (sessionTotal / sessionCount) - (previousTotal / previousCount);
end

function ParseGraph.GetAllTimeProgress(ignoreSpecFilter)
    local parses = ParseGraph.GetViewParses();
    if ignoreSpecFilter ~= true then
        parses = ParseGraph.GetSpecFilteredParses(parses);
    end
    if #parses < 2 then
        return nil;
    end

    local current = ParseGraph.GetParseStats(1, #parses, parses);
    local previous = ParseGraph.GetParseStats(1, #parses - 1, parses);
    if current.average == nil or previous.average == nil then
        return nil;
    end

    return current.average - previous.average;
end

function ParseGraph.GetParseStats(firstIndex, lastIndex, parses)
    local stats = {
        count = 0,
        total = 0,
        average = nil,
        best = nil,
        minuteTotals = { 0, 0, 0 },
        minuteCounts = { 0, 0, 0 },
        averageMinutes = { nil, nil, nil }
    };

    parses = parses or ParseGraph.GetViewParses();
    firstIndex = math.max(1, tonumber(firstIndex) or 1);
    lastIndex = math.min(#parses, tonumber(lastIndex) or #parses);

    for i = firstIndex, lastIndex do
        local p = parses[i];
        local final = tonumber(p and p.final);
        if final ~= nil then
            stats.count = stats.count + 1;
            stats.total = stats.total + final;
            if stats.best == nil or final > stats.best then
                stats.best = final;
            end
        end

        if p ~= nil and p.minutes ~= nil then
            for minute = 1, 3 do
                local value = tonumber(p.minutes[minute]);
                if value ~= nil then
                    stats.minuteTotals[minute] = stats.minuteTotals[minute] + value;
                    stats.minuteCounts[minute] = stats.minuteCounts[minute] + 1;
                end
            end
        end
    end

    if stats.count > 0 then
        stats.average = stats.total / stats.count;
    end

    for minute = 1, 3 do
        if stats.minuteCounts[minute] > 0 then
            stats.averageMinutes[minute] = stats.minuteTotals[minute] / stats.minuteCounts[minute];
        end
    end

    return stats;
end

function ParseGraph.GetSessionStats(ignoreSpecFilter)
    local sessionStart = tonumber(ParseGraph.SessionStartCount) or 0;
    local parses = ParseGraph.Parses or {};
    if ignoreSpecFilter == true then
        return ParseGraph.GetParseStats(sessionStart + 1, #parses, parses);
    end

    local filtered = {};
    for i = sessionStart + 1, #parses do
        local parse = parses[i];
        if ParseGraph.ParseMatchesSpecFilter(parse) then
            table.insert(filtered, parse);
        end
    end
    return ParseGraph.GetParseStats(1, #filtered, filtered);
end

function ParseGraph.GetAllTimeStats(ignoreSpecFilter)
    local parses = ParseGraph.GetViewParses();
    if ignoreSpecFilter ~= true then
        parses = ParseGraph.GetSpecFilteredParses(parses);
    end
    return ParseGraph.GetParseStats(1, #parses, parses);
end

function ParseGraph.FormatSummaryNumber(value)
    if value == nil then
        return "-";
    end
    return FormatNumber(value);
end

function ParseGraph.GetShortCharacterName(name, maxLen)
    local text = tostring(name or "");
    maxLen = tonumber(maxLen) or 10;
    if string.len(text) > maxLen then
        return string.sub(text, 1, maxLen - 2) .. "..";
    end
    return text;
end

function ParseGraph.GetCharacterList()
    local characters = ParseGraph.AccountData and ParseGraph.AccountData.characters or {};
    local currentKey = ParseGraph.GetCurrentCharacterKey();
    local foundCurrent = false;
    local list = {};

    for key, entry in pairs(characters) do
        if type(entry) == "table" then
            entry = NormalizeCharacterData(entry, key, entry.name);
            if key == currentKey then
                local classInfo = ParseGraph.GetCurrentPlayerClassInfo();
                if classInfo ~= nil then
                    entry.classKey = classInfo.key;
                    entry.className = classInfo.name;
                    entry.classIcon = classInfo.icon;
                end
            end
            characters[key] = entry;
            local parseCount = #(entry.parses or {});
            table.insert(list, {
                key = key,
                name = entry.name or tostring(key),
                count = parseCount,
                classKey = entry.classKey,
                className = entry.className,
                classIcon = entry.classIcon
            });
            if key == currentKey then
                foundCurrent = true;
            end
        end
    end

    if not foundCurrent then
        local classInfo = ParseGraph.GetCurrentPlayerClassInfo();
        table.insert(list, {
            key = currentKey,
            name = ParseGraph.GetCurrentCharacterName(),
            count = #ParseGraph.Parses,
            classKey = classInfo and classInfo.key or nil,
            className = classInfo and classInfo.name or nil,
            classIcon = classInfo and classInfo.icon or nil
        });
    end

    table.sort(list, function(a, b)
        if a.key == currentKey then return true end
        if b.key == currentKey then return false end
        return LowerClean(a.name) < LowerClean(b.name);
    end);

    return list;
end

function ParseGraph.UpdateCharacterDropdownText()
    local name = ParseGraph.GetCharacterDisplayName(ParseGraph.ViewCharacterKey);
    if ParseGraph.CharacterNameLabel ~= nil then
        ParseGraph.CharacterNameLabel:SetText(ParseGraph.GetShortCharacterName(name, 18));
    end
    if ParseGraph.CharacterDropdownButton ~= nil and ParseGraph.CharacterDropdownButton.isSidebarButton ~= true then
        ParseGraph.CharacterDropdownButton:SetText(ParseGraph.GetShortCharacterName(name, 18));
    end
end

function ParseGraph.UpdateDeleteButtons()
    if ParseGraph.ClearButton == nil then
        return;
    end

    if ParseGraph.ClearButton.isSidebarButton ~= true and ParseGraph.ClearButton.SetEnabled ~= nil then
        ParseGraph.ClearButton:SetEnabled(ParseGraph.IsViewingCurrentCharacter() and not ParseGraph.IsCombineSameClassActive());
    end
end

function ParseGraph.HideCharacterDropdown()
    if ParseGraph.CharacterDropdownPanel ~= nil then
        ParseGraph.CharacterDropdownPanel:SetVisible(false);
    end
    ParseGraph.CharacterDropdownOpen = false;
end

function ParseGraph.BuildCharacterDropdown()
    if ParseGraph.CharacterDropdownParent == nil then
        return;
    end

    if ParseGraph.CharacterDropdownPanel ~= nil then
        ParseGraph.CharacterDropdownPanel:SetParent(nil);
        ParseGraph.CharacterDropdownPanel = nil;
    end

    local list = ParseGraph.GetCharacterList();
    local rowHeight = 22;
    local panelHeight = math.max(1, #list) * rowHeight + 4;
    local dropdownX = tonumber(ParseGraph.CharacterDropdownX) or 805;
    local dropdownY = tonumber(ParseGraph.CharacterDropdownY) or 36;
    local dropdownW = tonumber(ParseGraph.CharacterDropdownW) or 90;
    local panel = Panel(ParseGraph.CharacterDropdownParent, dropdownX, dropdownY, dropdownW, panelHeight, 0.99);
    ParseGraph.CharacterDropdownPanel = panel;

    for i = 1, #list do
        local item = list[i];
        local row = Turbine.UI.Lotro.Button();
        row:SetParent(panel);
        row:SetPosition(2, 2 + ((i - 1) * rowHeight));
        row:SetSize(dropdownW - 4, 20);
        row:SetText(ParseGraph.GetShortCharacterName(item.name, 18));
        row.key = item.key;
        row.Click = function(sender)
            ParseGraph.SelectCharacter(sender.key);
        end
    end

    panel:SetVisible(true);
    ParseGraph.CharacterDropdownOpen = true;
end

function ParseGraph.ToggleCharacterDropdown()
    if ParseGraph.CharacterDropdownPanel ~= nil and ParseGraph.CharacterDropdownOpen == true then
        ParseGraph.HideCharacterDropdown();
        return;
    end

    ParseGraph.BuildCharacterDropdown();
end

function ParseGraph.SelectCharacter(key, suppressRefresh)
    local currentKey = ParseGraph.GetCurrentCharacterKey();
    key = tostring(key or currentKey);

    if ParseGraph.ActiveParse ~= nil and key ~= currentKey then
        Turbine.Shell.WriteLine("ParseGraph: finish or discard the current parse before viewing another character.");
        ParseGraph.HideCharacterDropdown();
        return false;
    end

    local oldKey = ParseGraph.ViewCharacterKey or currentKey;
    ParseGraph.SessionStartByCharacter[oldKey] = ParseGraph.SessionStartCount;

    if oldKey == key then
        ParseGraph.HideCharacterDropdown();
        ParseGraph.UpdateCharacterDropdownText();
        return true;
    end

    ParseGraph.Save();

    local entry = ParseGraph.AccountData.characters[key];
    if type(entry) ~= "table" then
        key = currentKey;
        entry = ParseGraph.EnsureAccountCharacter(currentKey, ParseGraph.GetCurrentCharacterName());
    else
        entry = NormalizeCharacterData(entry, key, entry.name);
        ParseGraph.AccountData.characters[key] = entry;
    end

    ParseGraph.ViewCharacterKey = key;
    ParseGraph.Parses = entry.parses or {};
    ParseGraph.InstanceData = entry.instances or {};
    ParseGraph.CharacterStats = entry.stats or {};
    ParseGraph.GraphMin = tonumber(entry.graphMin) or 100000;
    ParseGraph.ShowMode = NormalizeShowMode(entry.showMode);
    ParseGraph.UnlockedAchievements = entry.achievements or {};
    if ParseGraph.SyncAchievements(false) then
        entry.achievements = ParseGraph.UnlockedAchievements;
        ParseGraph.SaveAccountData();
    end
    ParseGraph.SessionStartCount = tonumber(ParseGraph.SessionStartByCharacter[key]) or #ParseGraph.Parses;
    if ParseGraph.SessionStartCount > #ParseGraph.Parses then
        ParseGraph.SessionStartCount = #ParseGraph.Parses;
    end

    ParseGraph.HideCharacterDropdown();
    ParseGraph.UpdateCharacterDropdownText();

    if not suppressRefresh then
        ParseGraph.Refresh();
    end
    return true;
end

function ParseGraph.SwitchToCurrentCharacterForParse()
    local currentKey = ParseGraph.GetCurrentCharacterKey();
    if ParseGraph.ViewCharacterKey ~= currentKey then
        ParseGraph.SelectCharacter(currentKey);
        Turbine.Shell.WriteLine("ParseGraph: switched to the current character for the new parse.");
    end
end

function ParseGraph.DeleteViewedParses()
    local key = ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey();
    if ParseGraph.IsCombineSameClassActive() then
        Turbine.Shell.WriteLine("ParseGraph: turn off Combine same class before deleting parses.");
        return false;
    end
    if key ~= ParseGraph.GetCurrentCharacterKey() then
        Turbine.Shell.WriteLine("ParseGraph: switch to that character before deleting its parses.");
        return false;
    end

    ParseGraph.Parses = {};
    ParseGraph.SessionStartCount = 0;
    ParseGraph.SessionStartByCharacter[key] = 0;
    ParseGraph.Save();
    return true;
end

function ParseGraph.DeleteParseBySource(sourceKey, sourceIndex)
    local currentKey = ParseGraph.GetCurrentCharacterKey();
    local viewKey = tostring(ParseGraph.ViewCharacterKey or currentKey);
    sourceKey = tostring(sourceKey or "");
    if sourceKey ~= currentKey then
        Turbine.Shell.WriteLine("ParseGraph: switch to that character before deleting its parses.");
        ParseGraph.Refresh();
        return false;
    end

    if viewKey ~= currentKey then
        Turbine.Shell.WriteLine("ParseGraph: switch to the current character before deleting parses.");
        ParseGraph.Refresh();
        return false;
    end
    local targetParses = ParseGraph.Parses or {};

    local deleteIndex = tonumber(sourceIndex);
    if deleteIndex == nil or deleteIndex < 1 or deleteIndex > #targetParses then
        ParseGraph.Refresh();
        return false;
    end

    if deleteIndex <= (tonumber(ParseGraph.SessionStartCount) or 0) then
        ParseGraph.SessionStartCount = math.max(0, (tonumber(ParseGraph.SessionStartCount) or 0) - 1);
    end
    table.remove(targetParses, deleteIndex);
    ParseGraph.Parses = targetParses;
    ParseGraph.SessionStartByCharacter[currentKey] = ParseGraph.SessionStartCount;
    ParseGraph.Save();
    ParseGraph.Refresh();
    return true;
end

