local function ApplySidebarButtonState(button)
    if button == nil or button.isSidebarButton ~= true then
        return;
    end

    local selected = button.selected == true;
    local hover = button.hover == true;
    local pressed = button.pressed == true;
    local border = Turbine.UI.Color(1.00, 0.58, 0.58, 0.58);
    local textColor = Turbine.UI.Color(1.00, 0.93, 0.76, 0.50);
    local fill = Turbine.UI.Color(1.00, 0.02, 0.06, 0.10);
    local theme = button.sidebarTheme;
    if selected then
        border = Turbine.UI.Color(1.00, 1.00, 0.76, 0.18);
        textColor = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
        fill = Turbine.UI.Color(1.00, 0.03, 0.15, 0.32);
    elseif pressed then
        border = Turbine.UI.Color(1.00, 1.00, 0.76, 0.18);
        textColor = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
        fill = Turbine.UI.Color(1.00, 0.03, 0.15, 0.32);
    elseif hover then
        border = Turbine.UI.Color(1.00, 0.95, 0.72, 0.24);
        textColor = Turbine.UI.Color(1.00, 1.00, 0.88, 0.28);
        fill = Turbine.UI.Color(1.00, 0.03, 0.11, 0.20);
    end
    if type(theme) == "table" then
        if selected then
            border = theme.selectedBorder or border;
            textColor = theme.selectedText or textColor;
            fill = theme.selectedFill or fill;
        elseif pressed then
            border = theme.selectedBorder or theme.pressedBorder or border;
            textColor = theme.selectedText or theme.pressedText or theme.hoverText or textColor;
            fill = theme.selectedFill or theme.pressedFill or fill;
        elseif hover then
            border = theme.hoverBorder or border;
            textColor = theme.hoverText or textColor;
            fill = theme.hoverFill or fill;
        else
            border = theme.border or border;
            textColor = theme.text or textColor;
            fill = theme.fill or fill;
        end
    end

    local assetBase = button.sidebarAssetBase or (type(theme) == "table" and theme.assetBase) or nil;
    local backgroundPath = nil;
    if assetBase ~= nil and tostring(assetBase) ~= "" then
        local suffix = "";
        local assetName = tostring(assetBase);
        if selected then
            suffix = "_selected";
        elseif pressed then
            suffix = "_selected";
        elseif hover then
            suffix = "_hover";
        end
        if type(theme) == "table" and type(theme.assetByState) == "table" then
            if selected and theme.assetByState.selected ~= nil then
                assetName = tostring(theme.assetByState.selected);
                suffix = "";
            elseif pressed and theme.assetByState.selected ~= nil then
                assetName = tostring(theme.assetByState.selected);
                suffix = "";
            elseif hover and theme.assetByState.hover ~= nil then
                assetName = tostring(theme.assetByState.hover);
                suffix = "";
            elseif theme.assetByState.normal ~= nil then
                assetName = tostring(theme.assetByState.normal);
                suffix = "";
            end
        end
        backgroundPath = (ParseGraph.GeneralIconPath or "") .. assetName .. suffix .. ".tga";
        pcall(function()
            button:SetBackground(backgroundPath);
        end);
    else
        button:SetBackColor(fill);
    end
    if button.sidebarIconBack ~= nil then
        button.sidebarIconBack:SetBackColor(fill);
    end
    if button.sidebarIconBackTexture ~= nil and backgroundPath ~= nil then
        pcall(function()
            button.sidebarIconBackTexture:SetBackground(backgroundPath);
        end);
    end
    if button.sidebarLabel ~= nil then
        button.sidebarLabel:SetForeColor(textColor);
    end
    if type(button.sidebarLabels) == "table" then
        for i = 1, #button.sidebarLabels do
            if button.sidebarLabels[i] ~= nil then
                button.sidebarLabels[i]:SetForeColor(textColor);
            end
        end
    end
    if type(button.sidebarBorders) == "table" then
        for i = 1, #button.sidebarBorders do
            if button.sidebarBorders[i] ~= nil then
                if assetBase ~= nil and tostring(assetBase) ~= "" then
                    button.sidebarBorders[i]:SetVisible(false);
                else
                    button.sidebarBorders[i]:SetVisible(true);
                    button.sidebarBorders[i]:SetBackColor(border);
                end
            end
        end
    end
    if button.sidebarIcon ~= nil and button.sidebarIconPath ~= nil then
        local iconPath = button.sidebarIconPath;
        if (selected or pressed) and button.sidebarIconSelectedPath ~= nil then
            iconPath = button.sidebarIconSelectedPath;
        elseif hover and button.sidebarIconHoverPath ~= nil then
            iconPath = button.sidebarIconHoverPath;
        end
        pcall(function()
            button.sidebarIcon:SetBackground(iconPath);
        end);
    end
end

function ParseGraph.SetSidebarButtonSelected(button, selected)
    if button ~= nil and button.isSidebarButton == true then
        button.selected = selected == true;
        ApplySidebarButtonState(button);
    elseif button ~= nil and button.SetEnabled ~= nil then
        button:SetEnabled(selected ~= true);
    end
end

local function SidebarButton(parent, x, y, w, h, text, icon, onClick)
    local button = Turbine.UI.Control();
    button:SetParent(parent);
    button:SetPosition(x, y);
    button:SetSize(w, h);
    button:SetMouseVisible(true);
    button.isSidebarButton = true;
    button.sidebarAssetBase = "action_button_" .. tostring(w) .. "x" .. tostring(h);
    button.sidebarBorders = {
        DrawBlock(button, 0, 0, w, 1, Turbine.UI.Color(0.95, 0.58, 0.58, 0.58)),
        DrawBlock(button, 0, h - 1, w, 1, Turbine.UI.Color(0.95, 0.58, 0.58, 0.58)),
        DrawBlock(button, 0, 0, 1, h, Turbine.UI.Color(0.95, 0.58, 0.58, 0.58)),
        DrawBlock(button, w - 1, 0, 1, h, Turbine.UI.Color(0.95, 0.58, 0.58, 0.58))
    };

    if icon ~= nil and tostring(icon) ~= "" then
        local iconText = tostring(icon);
        local iconOnly = text == nil or tostring(text) == "";
        local iconSize = 32;
        if iconOnly then
            iconSize = math.max(12, math.min(32, math.min(w - 8, h - 4)));
        end
        local iconX = iconOnly and math.floor((w - iconSize) / 2) or 13;
        local iconY = math.floor((h - iconSize) / 2);
        local iconBack = Turbine.UI.Control();
        iconBack:SetParent(button);
        iconBack:SetPosition(iconX, iconY);
        iconBack:SetSize(iconSize, iconSize);
        iconBack:SetBackColor(Turbine.UI.Color(1.00, 0.02, 0.06, 0.10));
        iconBack:SetMouseVisible(false);
        iconBack:SetZOrder(1);
        pcall(function()
            iconBack:SetClipMode(true);
        end);
        button.sidebarIconBack = iconBack;

        local iconBackTexture = Turbine.UI.Control();
        iconBackTexture:SetParent(iconBack);
        iconBackTexture:SetPosition(-iconX, -iconY);
        iconBackTexture:SetSize(w, h);
        iconBackTexture:SetMouseVisible(false);
        iconBackTexture:SetZOrder(1);
        button.sidebarIconBackTexture = iconBackTexture;
        button.sidebarIconPath = iconText;
        button.sidebarIconHoverPath = string.gsub(iconText, "%.tga$", "_hover.tga");
        button.sidebarIconSelectedPath = string.gsub(iconText, "%.tga$", "_selected.tga");

        local iconControl = Turbine.UI.Control();
        iconControl:SetParent(button);
        iconControl:SetPosition(iconX, iconY);
        iconControl:SetSize(iconSize, iconSize);
        iconControl:SetBackground(iconText);
        iconControl:SetMouseVisible(false);
        iconControl:SetZOrder(2);
        button.sidebarIcon = iconControl;
    end

    local textX = icon ~= nil and 54 or 0;
    if text ~= nil and tostring(text) ~= "" then
        local labelW = icon ~= nil and (w - textX - 12) or w;
        local label = Label(button, textX, 0, labelW, h, text or "", "achievement");
        label:SetFont(Turbine.UI.Lotro.Font.TrajanProBold22);
        label:SetTextAlignment(icon ~= nil and Turbine.UI.ContentAlignment.MiddleLeft or Turbine.UI.ContentAlignment.MiddleCenter);
        label:SetMouseVisible(false);
        label:SetZOrder(3);
        button.sidebarLabel = label;
    end

    button.MouseEnter = function(sender)
        sender.hover = true;
        ApplySidebarButtonState(sender);
    end
    button.MouseLeave = function(sender)
        sender.hover = false;
        sender.pressed = false;
        ApplySidebarButtonState(sender);
    end
    button.MouseDown = function(sender)
        sender.pressed = true;
        ApplySidebarButtonState(sender);
    end
    button.MouseUp = function(sender)
        sender.pressed = false;
        ApplySidebarButtonState(sender);
    end
    if onClick ~= nil then
        button.MouseClick = onClick;
    end
    ApplySidebarButtonState(button);
    return button;
end

function ParseGraph.CreateStyledButton(parent, x, y, w, h, text, icon, onClick)
    return SidebarButton(parent, x, y, w, h, text, icon, onClick);
end

function ParseGraph.RoundButtonCorners(button, radius)
    if button == nil then
        return;
    end

    local w, h = button:GetSize();
    radius = tonumber(radius) or 2;
    radius = math.max(1, math.min(radius, 4));
    local mask = Turbine.UI.Color(1.00, 0, 0, 0);

    local function Corner(x, y, cw, ch)
        local c = DrawBlock(button, x, y, cw, ch, mask);
        c:SetMouseVisible(false);
        c:SetZOrder(20);
        return c;
    end

    Corner(0, 0, radius, 1);
    Corner(0, 0, 1, radius);
    Corner(w - radius, 0, radius, 1);
    Corner(w - 1, 0, 1, radius);
    Corner(0, h - 1, radius, 1);
    Corner(0, h - radius, 1, radius);
    Corner(w - radius, h - 1, radius, 1);
    Corner(w - 1, h - radius, 1, radius);
end

function ParseGraph.CreateRowButton(parent, x, y, w, h, text, assetBase, onClick)
    local button = Turbine.UI.Control();
    button:SetParent(parent);
    button:SetPosition(x, y);
    button:SetSize(w, h);
    button:SetMouseVisible(true);
    button.rowButtonAssetBase = assetBase or "row_button";

    local function SetRowButtonBackground(sender, suffix)
        local path = (ParseGraph.GeneralIconPath or "") .. sender.rowButtonAssetBase .. (suffix or "") .. ".tga";
        pcall(function()
            sender:SetBackground(path);
        end);
    end

    button.SetRowButtonBackground = SetRowButtonBackground;

    SetRowButtonBackground(button, "");

    local label = Label(button, 0, 0, w, h, text or "", "small");
    label:SetFont(Turbine.UI.Lotro.Font.TrajanPro14);
    label:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    label:SetMouseVisible(false);
    label:SetZOrder(2);
    button.rowButtonLabel = label;

    button.MouseEnter = function(sender)
        SetRowButtonBackground(sender, "_hover");
    end
    button.MouseLeave = function(sender)
        SetRowButtonBackground(sender, "");
    end
    button.MouseDown = function(sender)
        SetRowButtonBackground(sender, "_pressed");
    end
    button.MouseUp = function(sender)
        SetRowButtonBackground(sender, "_hover");
    end

    if onClick ~= nil then
        button.MouseClick = onClick;
    end

    return button;
end

function ParseGraph.ApplyActionButtonState(button)
    if button == nil or button.isActionButton ~= true then
        return;
    end

    local suffix = "";
    local textColor = Turbine.UI.Color(1.00, 0.93, 0.76, 0.50);
    if button.actionSelected == true then
        suffix = "_selected";
        textColor = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    elseif button.pressed == true then
        suffix = "_pressed";
        textColor = Turbine.UI.Color(1.00, 1.00, 0.88, 0.28);
    elseif button.hover == true then
        suffix = "_hover";
        textColor = Turbine.UI.Color(1.00, 1.00, 0.88, 0.28);
    end

    local path = (ParseGraph.GeneralIconPath or "") .. button.actionButtonAssetBase .. suffix .. ".tga";
    pcall(function()
        button:SetBackground(path);
    end);

    if button.actionButtonLabel ~= nil then
        button.actionButtonLabel:SetForeColor(textColor);
    end
    if button.actionButtonIcon ~= nil and button.actionButtonIconBase ~= nil then
        pcall(function()
            button.actionButtonIcon:SetBackground(button.actionButtonIconBase .. suffix .. ".tga");
        end);
    end
end

function ParseGraph.SetActionButtonSelected(button, selected)
    if button ~= nil and button.isActionButton == true then
        button.actionSelected = selected == true;
        ParseGraph.ApplyActionButtonState(button);
    end
end

function ParseGraph.CreateActionButton(parent, x, y, w, h, text, onClick)
    local assetBase = "action_button_" .. tostring(w) .. "x" .. tostring(h);
    local button = Turbine.UI.Control();
    button:SetParent(parent);
    button:SetPosition(x, y);
    button:SetSize(w, h);
    button:SetMouseVisible(true);
    button.isActionButton = true;
    button.actionButtonAssetBase = assetBase;

    local label = Label(button, 0, 0, w, h, text or "", "big");
    label:SetFont(Turbine.UI.Lotro.Font.TrajanPro16);
    label:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    label:SetMouseVisible(false);
    label:SetZOrder(2);
    button.actionButtonLabel = label;

    button.MouseEnter = function(sender)
        sender.hover = true;
        ParseGraph.ApplyActionButtonState(sender);
    end
    button.MouseLeave = function(sender)
        sender.hover = false;
        sender.pressed = false;
        ParseGraph.ApplyActionButtonState(sender);
    end
    button.MouseDown = function(sender)
        sender.pressed = true;
        ParseGraph.ApplyActionButtonState(sender);
    end
    button.MouseUp = function(sender)
        sender.pressed = false;
        ParseGraph.ApplyActionButtonState(sender);
    end

    if onClick ~= nil then
        button.MouseClick = onClick;
    end

    ParseGraph.ApplyActionButtonState(button);
    return button;
end

function ParseGraph.ApplyAliasButtonVisualState(button, state)
    if button == nil then
        return;
    end

    state = tostring(state or "");
    if button.isActionButton == true then
        button.hover = state == "hover" or state == "pressed";
        button.pressed = state == "pressed";
        ParseGraph.ApplyActionButtonState(button);
    elseif button.rowButtonAssetBase ~= nil then
        local suffix = "";
        if state == "pressed" then
            suffix = "_pressed";
        elseif state == "hover" then
            suffix = "_hover";
        end

        if button.SetRowButtonBackground ~= nil then
            button:SetRowButtonBackground(suffix);
        else
            local path = (ParseGraph.GeneralIconPath or "") .. button.rowButtonAssetBase .. suffix .. ".tga";
            pcall(function()
                button:SetBackground(path);
            end);
        end
    end
end

function ParseGraph.CreateIconActionButton(parent, x, y, w, h, icon, onClick)
    local button = ParseGraph.CreateActionButton(parent, x, y, w, h, "", onClick);
    local iconText = tostring(icon or "");
    local iconBase = string.gsub(iconText, "%.tga$", "");
    local iconSize = math.max(12, math.min(18, math.min(w - 8, h - 4)));
    local iconControl = Turbine.UI.Control();
    iconControl:SetParent(button);
    iconControl:SetPosition(math.floor((w - iconSize) / 2), math.floor((h - iconSize) / 2));
    iconControl:SetSize(iconSize, iconSize);
    iconControl:SetMouseVisible(false);
    iconControl:SetZOrder(3);
    button.actionButtonIcon = iconControl;
    button.actionButtonIconBase = iconBase;
    ParseGraph.ApplyActionButtonState(button);
    return button;
end

local function TwoLineSidebarButton(parent, x, y, w, h, line1, line2, onClick)
    local button = Turbine.UI.Control();
    button:SetParent(parent);
    button:SetPosition(x, y);
    button:SetSize(w, h);
    button:SetMouseVisible(true);
    button.isSidebarButton = true;
    button.sidebarAssetBase = "action_button_" .. tostring(w) .. "x" .. tostring(h);
    button.sidebarBorders = {
        DrawBlock(button, 0, 0, w, 1, Turbine.UI.Color(0.95, 0.58, 0.58, 0.58)),
        DrawBlock(button, 0, h - 1, w, 1, Turbine.UI.Color(0.95, 0.58, 0.58, 0.58)),
        DrawBlock(button, 0, 0, 1, h, Turbine.UI.Color(0.95, 0.58, 0.58, 0.58)),
        DrawBlock(button, w - 1, 0, 1, h, Turbine.UI.Color(0.95, 0.58, 0.58, 0.58))
    };

    local top = Label(button, 6, 5, w - 12, 20, line1 or "", "big");
    top:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    top:SetMouseVisible(false);
    top:SetZOrder(2);

    local bottom = Label(button, 6, 25, w - 12, 18, line2 or "", "achievementDetail");
    bottom:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    bottom:SetMouseVisible(false);
    bottom:SetZOrder(2);

    button.sidebarLabels = { top, bottom };

    button.MouseEnter = function(sender)
        sender.hover = true;
        ApplySidebarButtonState(sender);
    end
    button.MouseLeave = function(sender)
        sender.hover = false;
        sender.pressed = false;
        ApplySidebarButtonState(sender);
    end
    button.MouseDown = function(sender)
        sender.pressed = true;
        ApplySidebarButtonState(sender);
    end
    button.MouseUp = function(sender)
        sender.pressed = false;
        ApplySidebarButtonState(sender);
    end
    if onClick ~= nil then
        button.MouseClick = onClick;
    end
    ApplySidebarButtonState(button);
    return button;
end

function ParseGraph.UpdateSidebarNavButtons()
    if ParseGraph.SidebarNavButtons == nil then
        return;
    end

    local current = ParseGraph.CurrentView or "main";
    for key, button in pairs(ParseGraph.SidebarNavButtons) do
        if button ~= nil then
            ParseGraph.SetSidebarButtonSelected(button, key == current);
        end
    end
    if ParseGraph.SidebarNavButtons.achievements ~= nil then
        ParseGraph.SetSidebarButtonSelected(ParseGraph.SidebarNavButtons.achievements, current == "achievements" and ParseGraph.AchievementCategory ~= "personalBest");
    end
    if ParseGraph.SidebarNavButtons.personalBest ~= nil then
        ParseGraph.SetSidebarButtonSelected(ParseGraph.SidebarNavButtons.personalBest, current == "achievements" and ParseGraph.AchievementCategory == "personalBest");
    end
    if ParseGraph.SidebarNavButtons.compare ~= nil then
        ParseGraph.SetSidebarButtonSelected(ParseGraph.SidebarNavButtons.compare, current == "parseDetail" and ParseGraph.ParseCompareViewActive == true);
    end
    if ParseGraph.CharacterDropdownButton ~= nil then
        if ParseGraph.CharacterDropdownButton.isSidebarButton == true then
            ParseGraph.SetSidebarButtonSelected(ParseGraph.CharacterDropdownButton, current == "characters");
        else
            ParseGraph.CharacterDropdownButton:SetEnabled(current ~= "characters");
        end
    end
end

