local function SummaryLabel(parent, x, y, w, h, text, color, font, align)
    local l = Turbine.UI.Label();
    l:SetParent(parent);
    l:SetPosition(x, y);
    l:SetSize(w, h);
    l:SetFont(font or Turbine.UI.Lotro.Font.TrajanPro14);
    l:SetForeColor(color or Turbine.UI.Color(1.00, 0.93, 0.62));
    l:SetTextAlignment(align or Turbine.UI.ContentAlignment.MiddleLeft);
    l:SetText(text or "");
    return l;
end

function ParseGraph.BuildSummaryPanel(parent, x, y, w, h, title, rows)
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local labelColor = Turbine.UI.Color(1.00, 0.93, 0.76, 0.28);
    local beige = Turbine.UI.Color(1.00, 0.93, 0.62);
    local white = Turbine.UI.Color(0.95, 0.92, 0.88, 0.82);

    local panel = Panel(parent, x, y, w, h, 1.00);
    DrawBlock(panel, 0, 0, w, 1, border);
    DrawBlock(panel, 0, h - 1, w, 1, border);
    DrawBlock(panel, 0, 0, 1, h, border);
    DrawBlock(panel, w - 1, 0, 1, h, border);

    SummaryLabel(panel, 0, 8, w, 28, title, beige, Turbine.UI.Lotro.Font.TrajanProBold22, Turbine.UI.ContentAlignment.MiddleCenter);
    DrawBlock(panel, 18, 42, w - 36, 1, border);

    local yPos = 52;
    for i = 1, #rows do
        local row = rows[i];
        if row.separatorBefore then
            yPos = yPos + 9;
            DrawBlock(panel, 18, yPos - 4, w - 36, 1, border);
        end

        if row.type == "averages" then
            SummaryLabel(panel, 26, yPos, w - 52, 18, "Averages", beige, Turbine.UI.Lotro.Font.TrajanPro16, Turbine.UI.ContentAlignment.MiddleCenter);

            local colW = 118;
            local colGap = 10;
            local startX = math.floor((w - ((colW * 3) + (colGap * 2))) / 2);
            for col = 1, 3 do
                local colX = startX + ((col - 1) * (colW + colGap));
                SummaryLabel(panel, colX, yPos + 20, colW, 18, row.labels[col], labelColor, Turbine.UI.Lotro.Font.TrajanPro14, Turbine.UI.ContentAlignment.MiddleCenter);
                local value = SummaryLabel(panel, colX, yPos + 39, colW, 20, "-", row.valueColor or white, Turbine.UI.Lotro.Font.TrajanPro14, Turbine.UI.ContentAlignment.MiddleCenter);
                ParseGraph.SummaryValues[row.keys[col]] = value;
            end

            yPos = yPos + 61;
        else
            SummaryLabel(panel, 26, yPos, w - 170, 20, row.label, labelColor, Turbine.UI.Lotro.Font.TrajanPro16, Turbine.UI.ContentAlignment.MiddleLeft);
            local value = SummaryLabel(panel, w - 145, yPos, 115, 20, "-", row.valueColor or white, Turbine.UI.Lotro.Font.TrajanPro16, Turbine.UI.ContentAlignment.MiddleRight);
            ParseGraph.SummaryValues[row.key] = value;
            if type(row.onClick) == "function" then
                local clickLayer = Turbine.UI.Control();
                clickLayer:SetParent(panel);
                clickLayer:SetPosition(18, yPos);
                clickLayer:SetSize(w - 36, 20);
                clickLayer:SetMouseVisible(true);
                clickLayer:SetZOrder(50);
                clickLayer.MouseClick = row.onClick;
            end
            yPos = yPos + 22;
        end
    end

    return panel;
end

function ParseGraph.BuildSummaryPanels(parent)
    ParseGraph.SummaryValues = {};
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);

    ParseGraph.BuildSummaryPanel(parent, 15, 334, 425, 214, "Current Session", {
        { key = "sessionParses", label = "Session parses" },
        { key = "sessionAverage", label = "Session average" },
        { key = "sessionProgress", label = "Session progress" },
        { key = "sessionBest", label = "Best parse", valueColor = gold },
        { type = "averages", separatorBefore = true, keys = { "sessionM1", "sessionM2", "sessionM3" }, labels = { "1st minute", "2nd minute", "3rd minute" } }
    });

    ParseGraph.BuildSummaryPanel(parent, 470, 334, 425, 214, "All-time Summary", {
        { key = "totalParses", label = "Total parses" },
        { key = "allAverage", label = "All-time average" },
        { key = "allProgress", label = "All-time progress" },
        { key = "personalBest", label = "Personal best", valueColor = gold, onClick = function()
            ParseGraph.AchievementCategory = "personalBest";
            ParseGraph.SetView("achievements");
        end },
        { type = "averages", separatorBefore = true, keys = { "allM1", "allM2", "allM3" }, labels = { "1st minute", "2nd minute", "3rd minute" } }
    });
end

function ParseGraph.SetSummaryValue(key, value, color)
    if ParseGraph.SummaryValues == nil or ParseGraph.SummaryValues[key] == nil then
        return;
    end
    ParseGraph.SummaryValues[key]:SetText(value or "-");
    if color ~= nil then
        ParseGraph.SummaryValues[key]:SetForeColor(color);
    end
end

function ParseGraph.UpdateSummaryStats()
    if ParseGraph.SummaryValues == nil then return end

    local session = ParseGraph.GetSessionStats();
    local allTime = ParseGraph.GetAllTimeStats();
    local progress = ParseGraph.GetSessionProgress();
    local allProgress = ParseGraph.GetAllTimeProgress();
    local neutral = Turbine.UI.Color(0.95, 0.92, 0.88, 0.82);
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local green = Turbine.UI.Color(1.00, 0.25, 0.95, 0.25);
    local red = Turbine.UI.Color(1.00, 1.00, 0.25, 0.25);

    local function SetProgressValue(key, value)
        if value == nil then
            ParseGraph.SetSummaryValue(key, "-", neutral);
            return;
        end

        local rounded = Round(value);
        local prefix = "";
        local color = neutral;
        if rounded > 0 then
            prefix = "+";
            color = green;
        elseif rounded < 0 then
            color = red;
        end

        ParseGraph.SetSummaryValue(key, prefix .. FormatNumber(rounded), color);
    end

    ParseGraph.SetSummaryValue("sessionParses", tostring(session.count), neutral);
    ParseGraph.SetSummaryValue("sessionAverage", ParseGraph.FormatSummaryNumber(session.average), neutral);
    SetProgressValue("sessionProgress", progress);
    ParseGraph.SetSummaryValue("sessionBest", ParseGraph.FormatSummaryNumber(session.best), gold);
    ParseGraph.SetSummaryValue("sessionM1", ParseGraph.FormatSummaryNumber(session.averageMinutes[1]), neutral);
    ParseGraph.SetSummaryValue("sessionM2", ParseGraph.FormatSummaryNumber(session.averageMinutes[2]), neutral);
    ParseGraph.SetSummaryValue("sessionM3", ParseGraph.FormatSummaryNumber(session.averageMinutes[3]), neutral);

    ParseGraph.SetSummaryValue("totalParses", tostring(allTime.count), neutral);
    ParseGraph.SetSummaryValue("allAverage", ParseGraph.FormatSummaryNumber(allTime.average), neutral);
    SetProgressValue("allProgress", allProgress);
    ParseGraph.SetSummaryValue("personalBest", ParseGraph.FormatSummaryNumber(allTime.best), gold);
    ParseGraph.SetSummaryValue("allM1", ParseGraph.FormatSummaryNumber(allTime.averageMinutes[1]), neutral);
    ParseGraph.SetSummaryValue("allM2", ParseGraph.FormatSummaryNumber(allTime.averageMinutes[2]), neutral);
    ParseGraph.SetSummaryValue("allM3", ParseGraph.FormatSummaryNumber(allTime.averageMinutes[3]), neutral);
end

function ParseGraph.ClearSession()
    ParseGraph.SessionStartCount = #ParseGraph.Parses;
    ParseGraph.SessionStartByCharacter[ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey()] = ParseGraph.SessionStartCount;
    ParseGraph.Refresh();
    Turbine.Shell.WriteLine("ParseGraph: current session cleared. Saved parses were kept.");
end

function ParseGraph.ShowCleanupConfirm(titleText, messageText, confirmText, onConfirm)
    if ParseGraph.ClearConfirmWindow ~= nil then
        ParseGraph.ClearConfirmWindow:SetVisible(false);
        ParseGraph.ClearConfirmWindow:SetSize(0, 0);
    end
    local confirm = Turbine.UI.Lotro.Window();
    ParseGraph.ClearConfirmWindow = confirm;
    confirm:SetSize(420, 185);
    confirm:SetPosition(260, 230);
    confirm:SetText(tostring(titleText or "Confirm cleanup"));
    confirm:SetVisible(true);

    local bg = Panel(confirm, 15, 35, 390, 125, 0.92);

    local msg = Label(bg, 20, 10, 350, 54, tostring(messageText or "Are you sure?"), "big");
    msg:SetFont(Turbine.UI.Lotro.Font.TrajanPro16);
    msg:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);

    local function ConfirmButton(x, text, fill, hoverFill, borderColor, clickHandler)
        local button = Turbine.UI.Control();
        button:SetParent(bg);
        button:SetPosition(x, 82);
        button:SetSize(115, 28);
        button:SetBackColor(fill);
        button.normalFill = fill;
        button.hoverFill = hoverFill;
        DrawBlock(button, 0, 0, 115, 1, borderColor);
        DrawBlock(button, 0, 27, 115, 1, borderColor);
        DrawBlock(button, 0, 0, 1, 28, borderColor);
        DrawBlock(button, 114, 0, 1, 28, borderColor);

        local buttonText = Label(button, 0, 0, 115, 28, text, "big");
        buttonText:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        buttonText:SetMouseVisible(false);

        button.MouseEnter = function(sender)
            sender:SetBackColor(sender.hoverFill);
        end
        button.MouseLeave = function(sender)
            sender:SetBackColor(sender.normalFill);
        end
        button.MouseClick = clickHandler;
        return button;
    end

    ConfirmButton(
        80,
        "Cancel",
        Turbine.UI.Color(0.95, 0.03, 0.25, 0.08),
        Turbine.UI.Color(0.95, 0.05, 0.40, 0.12),
        Turbine.UI.Color(1.00, 0.42, 0.92, 0.34),
        function()
            confirm:SetVisible(false);
        end
    );

    local delete = ConfirmButton(
        220,
        tostring(confirmText or "Delete"),
        Turbine.UI.Color(0.95, 0.46, 0.04, 0.04),
        Turbine.UI.Color(0.95, 0.62, 0.08, 0.08),
        Turbine.UI.Color(1.00, 0.95, 0.46, 0.22),
        nil
    );
    delete.MouseClick = function()
        if onConfirm ~= nil then
            onConfirm();
        end
        confirm:SetVisible(false);
    end
end

function ParseGraph.ShowClearConfirm()
    ParseGraph.ShowCleanupConfirm(
        "Delete all parses?",
        "Are you sure you want to delete\nall saved parses?",
        "Delete",
        function()
            local deleted = ParseGraph.DeleteViewedParses();
            if deleted then
                Turbine.Shell.WriteLine("ParseGraph: all parses deleted.");
                ParseGraph.SetCleanupStatus("All parses deleted.");
            end
            ParseGraph.Refresh();
        end
    );
end

