end

function ParseGraph.HideInstanceDeleteMenu()
    if ParseGraph.InstanceDeleteMenuBackdrop ~= nil then
        ParseGraph.InstanceDeleteMenuBackdrop:SetVisible(false);
        ParseGraph.InstanceDeleteMenuBackdrop:SetSize(0, 0);
    end
    ParseGraph.InstanceDeleteMenuBackdrop = nil;

    if ParseGraph.InstanceDeleteMenuWindow ~= nil then
        ParseGraph.InstanceDeleteMenuWindow:SetVisible(false);
        ParseGraph.InstanceDeleteMenuWindow:SetSize(0, 0);
    end
    ParseGraph.InstanceDeleteMenuWindow = nil;
end

function ParseGraph.ShowInstanceDeleteMenu()
    if ParseGraph.InstanceDeleteMenuWindow ~= nil and ParseGraph.InstanceDeleteMenuWindow:IsVisible() then
        ParseGraph.HideInstanceDeleteMenu();
        return;
    end

    ParseGraph.HideLauncherContextMenu();
    if ParseGraph.HideParseHistorySortMenu ~= nil then
        ParseGraph.HideParseHistorySortMenu();
    end
    if ParseGraph.HideParseSpecMenu ~= nil then
        ParseGraph.HideParseSpecMenu();
    end
    if ParseGraph.HideParseSpecFilterMenu ~= nil then
        ParseGraph.HideParseSpecFilterMenu();
    end
    ParseGraph.HideInstanceDeleteMenu();
    if ParseGraph.HideInstanceBossContextMenu ~= nil then
        ParseGraph.HideInstanceBossContextMenu();
    end

    local anchor = ParseGraph.CleanupInstanceDeleteButton;
    if anchor == nil then
        return;
    end

    local items = {
        { key = "all", text = "All instances", label = "all instances" }
    };
    local instances = ParseGraph.GetOrderedInstanceDefinitions();
    for i = 1, #instances do
        local instance = instances[i];
        items[#items + 1] = {
            key = instance.key,
            text = tostring(instance.name or instance.key),
            label = tostring(instance.name or instance.key)
        };
    end

    local menuW = 365;
    local rowH = 30;
    local pad = 7;
    local menuH = pad * 2 + (rowH * #items);
    local x, y = ParseGraph.GetControlScreenPosition(anchor);
    x = x + anchor:GetWidth() + 6;
    y = y - pad;
    x, y = ParseGraph.ClampContextMenuPosition(x, y, menuW, menuH);

    local backdrop = Turbine.UI.Window();
    ParseGraph.InstanceDeleteMenuBackdrop = backdrop;
    local displayW, displayH = 2000, 1200;
    if Turbine.UI ~= nil and Turbine.UI.Display ~= nil then
        displayW = tonumber(Turbine.UI.Display.GetWidth()) or displayW;
        displayH = tonumber(Turbine.UI.Display.GetHeight()) or displayH;
    end
    backdrop:SetPosition(0, 0);
    backdrop:SetSize(displayW, displayH);
    backdrop:SetOpacity(0);
    backdrop:SetMouseVisible(true);
    if backdrop.SetZOrder ~= nil then
        backdrop:SetZOrder(300);
    end
    backdrop.MouseDown = function()
        ParseGraph.HideInstanceDeleteMenu();
    end
    backdrop.MouseClick = function()
        ParseGraph.HideInstanceDeleteMenu();
    end
    backdrop:SetVisible(true);

    local menu = Turbine.UI.Window();
    ParseGraph.InstanceDeleteMenuWindow = menu;
    menu:SetPosition(x, y);
    menu:SetSize(menuW, menuH);
    menu:SetOpacity(1);
    menu:SetMouseVisible(true);
    menu:SetBackColor(Turbine.UI.Color(1.00, 0.00, 0.00, 0.00));
    if menu.SetZOrder ~= nil then
        menu:SetZOrder(310);
    end
    CreateContextMenuBorder(menu, menuW, menuH, Turbine.UI.Color(1.00, 0.95, 0.55, 0.05));

    for i = 1, #items do
        local item = items[i];
        local key = item.key;
        local labelText = item.label;
        ParseGraph.CreateContextMenuRow(menu, pad, pad + ((i - 1) * rowH), menuW - (pad * 2), rowH - 1, item.text, false, function()
            ParseGraph.HideInstanceDeleteMenu();
            ParseGraph.ConfirmDeleteInstanceData(key, labelText);
        end, false);
    end

    menu:SetVisible(true);
    menu:Activate();
end

function ParseGraph.IsRewardPopupActive()
    return (ParseGraph.PersonalBestPopup ~= nil and ParseGraph.PersonalBestPopup.active == true)
        or (ParseGraph.AchievementPopup ~= nil and ParseGraph.AchievementPopup.active == true);
end

function ParseGraph.QueueRewardPopup(item)
    if type(ParseGraph.RewardPopupQueue) ~= "table" then
        ParseGraph.RewardPopupQueue = {};
    end
    table.insert(ParseGraph.RewardPopupQueue, item);
end

function ParseGraph.ShowNextRewardPopup()
    if ParseGraph.IsRewardPopupActive() then
        return;
    end
    if type(ParseGraph.RewardPopupQueue) ~= "table" or #ParseGraph.RewardPopupQueue == 0 then
        return;
    end

    local nextPopup = table.remove(ParseGraph.RewardPopupQueue, 1);
    if nextPopup.kind == "personalBest" then
        ParseGraph.ShowPersonalBestPopup(nextPopup.gain, nextPopup.bestValue);
    elseif nextPopup.kind == "achievement" then
        ParseGraph.ShowAchievementPopup(nextPopup.achievement);
    end
end

