function ParseGraph.BuildWindow(startVisible)
    if ParseGraph.EnforceAccessUnavailable ~= nil and ParseGraph.EnforceAccessUnavailable() then
        return;
    end

    local w = Turbine.UI.Lotro.Window();
    ParseGraph.Window = w;
    if startVisible == nil then
        startVisible = true;
    end
    local savedX, savedY = ParseGraph.GetSavedWindowPosition();
    local sidebarW = 245;
    local contentGap = 10;
    local contentW = 910;
    local rootW = sidebarW + contentGap + contentW;
    w:SetSize(rootW + 30, 815);
    w:SetPosition(savedX, savedY);
    w:SetText("ParseGraph");
    w:SetVisible(startVisible == true);
    w:SetWantsKeyEvents(true);
    w.KeyDown = function(sender, args)
        if args ~= nil and args.Action == Turbine.UI.Lotro.Action.Escape then
            if ParseGraph.CloseParseFullView ~= nil and ParseGraph.CloseParseFullView() == true then
                args.Handled = true;
                return true;
            end
            ParseGraph.CloseWindow();
            args.Handled = true;
            return true;
        end
    end
    w.PositionChanged = function()
        ParseGraph.RememberWindowPosition(false);
        ParseGraph.UpdatePostButtonWindowPositions();
    end
    w.SizeChanged = function()
        ParseGraph.UpdatePostButtonWindowPositions();
    end
    w.VisibleChanged = function()
        if w:IsVisible() then
            ParseGraph.UpdatePostButtonWindowPositions();
        else
            ParseGraph.HidePostButtonWindows();
            if ParseGraph.HideInstanceDeleteMenu ~= nil then
                ParseGraph.HideInstanceDeleteMenu();
            end
        end
        ParseGraph.SetLauncherButtonState();
    end
    w.Closing = function()
        ParseGraph.AutoHideForCombat = false;
        ParseGraph.AutoHideCombatWasVisible = false;
        ParseGraph.ClearTemporaryInstanceTarget();
        ParseGraph.HidePostButtonWindows();
        if ParseGraph.HideInstanceDeleteMenu ~= nil then
            ParseGraph.HideInstanceDeleteMenu();
        end
    end

    local bg = Panel(w, 15, 35, rootW, 760, 1.00);
    ParseGraph.RootPanel = bg;
    ParseGraph.BuildSidebar(bg);

    local content = Turbine.UI.Control();
    content:SetParent(bg);
    content:SetPosition(sidebarW + contentGap, 0);
    content:SetSize(contentW, 760);
    ParseGraph.ContentPanel = content;

    ParseGraph.MainView = Turbine.UI.Control();
    ParseGraph.MainView:SetParent(content);
    ParseGraph.MainView:SetPosition(0, 0);
    ParseGraph.MainView:SetSize(contentW, 760);
    local main = ParseGraph.MainView;

    ParseGraph.GraphPanel = Panel(main, 15, 68, 880, 262, 1.00);
    ParseGraph.BuildSummaryPanels(main);
    ParseGraph.BuildGraphMinDropdown(main);
    ParseGraph.BuildGraphLegend(main);
    ParseGraph.ListTitle = Label(main, 30, 582, 200, 20, "Latest parses", "big");
    ParseGraph.ListPanel = Panel(main, 15, 605, 880, 110, 1.00);

    ParseGraph.SessionPostButton = ParseGraph.CreateActionButton(main, 93, 551, 125, 22, "Post session", nil);
    ParseGraph.SessionPostButton:SetMouseVisible(false);

    ParseGraph.SessionClearButton = ParseGraph.CreateActionButton(main, 228, 551, 135, 22, "Clear session", function()
        ParseGraph.ClearSession();
    end);

    ParseGraph.SummaryPostButton = ParseGraph.CreateActionButton(main, 610, 551, 145, 22, "Post summary", nil);
    ParseGraph.SummaryPostButton:SetMouseVisible(false);
    ParseGraph.ClearButton = nil;

    ParseGraph.ParseRunningPanel = Turbine.UI.Control();
    ParseGraph.ParseRunningPanel:SetParent(main);
    ParseGraph.ParseRunningPanel:SetPosition(15, 728);
    ParseGraph.ParseRunningPanel:SetSize(330, 24);
    ParseGraph.ParseRunningPanel:SetBackColor(Turbine.UI.Color(0.92, 0.00, 0.00, 0.00));
    ParseGraph.ParseRunningPanel:SetVisible(false);
    ParseGraph.ParseRunningPanel:SetMouseVisible(true);
    if ParseGraph.ParseRunningPanel.SetZOrder ~= nil then
        ParseGraph.ParseRunningPanel:SetZOrder(80);
    end

    ParseGraph.ParseRunningLabel = Label(ParseGraph.ParseRunningPanel, 15, 0, 160, 24, "Parse running...", "huge");
    ParseGraph.ParseRunningLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);

    ParseGraph.StopButton = ParseGraph.CreateActionButton(ParseGraph.ParseRunningPanel, 178, 1, 135, 22, "Discard parse", function()
        ParseGraph.DiscardActiveParse(true);
    end);

    ParseGraph.BuildInstancesView(content);
    ParseGraph.BuildScoreboardView(content);
    ParseGraph.BuildAchievementsView(content);
    ParseGraph.BuildCharactersView(content);
    ParseGraph.BuildSettingsView(content);
    ParseGraph.BuildHelpView(content);
    ParseGraph.BuildParseHistoryView(content);
    ParseGraph.BuildParseDetailView(content);
    ParseGraph.SetView(ParseGraph.CurrentView or "main");
    w:SetVisible(startVisible == true);
    ParseGraph.BuildLauncherButton();
    ParseGraph.EnsureGameUiKeyWatcher();
    ParseGraph.UpdatePostButtonWindowPositions();
end

local function ClearChildren(control)
    local children = control:GetControls();
    for i = children:GetCount(), 1, -1 do
        local child = children:Get(i);
        -- Detached lists must release their update callbacks when rebuilt.
        if child.Update ~= nil then
            pcall(function() child:SetWantsUpdates(false); end);
            child.Update = nil;
        end
        child:SetParent(nil);
    end
end

local function GetScoreboardTierLabel(tierKey)
    for i = 1, #(ParseGraph.InstanceTiers or {}) do
        local tier = ParseGraph.InstanceTiers[i];
        if tier ~= nil and tier.key == tierKey then
            return tostring(tier.label or tierKey or "");
        end
    end
    return tostring(tierKey or "");
end

local function GetScoreboardBoardsSorted()
    ParseGraph.PruneScoreboardBoards();
    local boards = {};
    local source = ParseGraph.ScoreboardBoards or {};
    for key, board in pairs(source) do
        if type(board) == "table" and type(board.entries) == "table" then
            boards[#boards + 1] = board;
        end
    end
    table.sort(boards, function(a, b)
        local au = tonumber(a.updatedAt) or 0;
        local bu = tonumber(b.updatedAt) or 0;
        if au == bu then
            return tostring(a.bossName or "") < tostring(b.bossName or "");
        end
        return au > bu;
    end);
    return boards;
end

function ParseGraph.GetScoreboardOverallBoard(boards)
    local overall = {
        key = "__overall",
        isOverall = true,
        bossName = "Overall",
        instanceName = "All scoreboard bosses",
        updatedAt = 0,
        entries = {}
    };

    for i = 1, #(boards or {}) do
        local board = boards[i];
        if type(board) == "table" and type(board.entries) == "table" then
            overall.updatedAt = math.max(tonumber(overall.updatedAt) or 0, tonumber(board.updatedAt) or 0);
            for characterKey, entry in pairs(board.entries) do
                if type(entry) == "table" then
                    local key = tostring(characterKey or "");
                    if key == "" then
                        key = LowerClean(entry.character or "Someone");
                    end
                    if key == "" then
                        key = "someone";
                    end

                    if ParseGraph.IsScoreboardEntryHidden(key) ~= true and ParseGraph.IsScoreboardEntryHidden(entry.character) ~= true then
                        local combined = overall.entries[key];
                        if type(combined) ~= "table" then
                            combined = {
                                character = entry.character or "Someone",
                                classKey = entry.classKey,
                                className = entry.className,
                                classIcon = entry.classIcon,
                                totalDamage = 0,
                                rateTotal = 0,
                                highestRate = 0,
                                posts = 0,
                                percentTotal = 0,
                                percentPosts = 0,
                                deaths = 0
                            };
                            overall.entries[key] = combined;
                        end

                        combined.character = entry.character or combined.character;
                        combined.classKey = entry.classKey or combined.classKey;
                        combined.className = entry.className or combined.className;
                        combined.classIcon = entry.classIcon or combined.classIcon;
                        combined.totalDamage = (tonumber(combined.totalDamage) or 0) + (tonumber(entry.totalDamage) or 0);
                        combined.rateTotal = (tonumber(combined.rateTotal) or 0) + (tonumber(entry.rateTotal) or 0);
                        combined.highestRate = math.max(tonumber(combined.highestRate) or 0, tonumber(entry.highestRate) or tonumber(entry.lastRate) or 0);
                        combined.posts = (tonumber(combined.posts) or 0) + (tonumber(entry.posts) or 0);
                        local entryPercent = ParseGraph.GetScoreboardEntryAveragePercent(entry);
                        local entryPercentPosts = tonumber(entry.percentPosts) or 0;
                        if entryPercent ~= nil then
                            if entryPercentPosts <= 0 then
                                entryPercentPosts = math.max(1, tonumber(entry.posts) or 1);
                            end
                            combined.percentTotal = (tonumber(combined.percentTotal) or 0) + (entryPercent * entryPercentPosts);
                            combined.percentPosts = (tonumber(combined.percentPosts) or 0) + entryPercentPosts;
                        end
                        combined.deaths = (tonumber(combined.deaths) or 0) + (tonumber(entry.deaths) or 0);
                        combined.updatedAt = math.max(tonumber(combined.updatedAt) or 0, tonumber(entry.updatedAt) or 0);
                    end
                end
            end
        end
    end

    return overall;
end

function ParseGraph.GetScoreboardEntryAverageRate(entry)
    local posts = math.max(1, tonumber(entry and entry.posts) or 1);
    return (tonumber(entry and entry.rateTotal) or 0) / posts;
end

function ParseGraph.GetScoreboardEntryAveragePercent(entry)
    local percentPosts = tonumber(entry and entry.percentPosts) or 0;
    if percentPosts > 0 then
        return (tonumber(entry.percentTotal) or 0) / percentPosts;
    end
    if tonumber(entry and entry.lastPercent) ~= nil then
        return tonumber(entry.lastPercent);
    end
    return nil;
end

function ParseGraph.GetScoreboardDeathColor(deaths)
    deaths = tonumber(deaths) or 0;
    if deaths <= 0 then
        return Turbine.UI.Color(1.00, 0.30, 1.00, 0.30);
    elseif deaths <= 2 then
        return Turbine.UI.Color(1.00, 1.00, 0.92, 0.18);
    elseif deaths <= 5 then
        return Turbine.UI.Color(1.00, 1.00, 0.56, 0.10);
    elseif deaths <= 10 then
        return Turbine.UI.Color(1.00, 1.00, 0.24, 0.06);
    elseif deaths <= 15 then
        return Turbine.UI.Color(1.00, 1.00, 0.12, 0.05);
    end
    return Turbine.UI.Color(1.00, 1.00, 0.05, 0.05);
end

function ParseGraph.GetScoreboardSortValue(entry, key)
    if key == "average" then
        return ParseGraph.GetScoreboardEntryAverageRate(entry);
    elseif key == "highest" then
        return tonumber(entry and entry.highestRate) or tonumber(entry and entry.lastRate) or ParseGraph.GetScoreboardEntryAverageRate(entry);
    elseif key == "percent" then
        return ParseGraph.GetScoreboardEntryAveragePercent(entry) or 0;
    elseif key == "deaths" then
        return tonumber(entry and entry.deaths) or 0;
    elseif key == "posts" then
        return tonumber(entry and entry.posts) or 0;
    end
    return tonumber(entry and entry.totalDamage) or 0;
end

function ParseGraph.SetScoreboardSort(key)
    key = key or "total";
    if ParseGraph.ScoreboardSortKey == key then
        ParseGraph.ScoreboardSortDescending = not (ParseGraph.ScoreboardSortDescending ~= false);
    else
        ParseGraph.ScoreboardSortKey = key;
        ParseGraph.ScoreboardSortDescending = true;
    end

    ParseGraph.DrawScoreboardView();
end

function ParseGraph.CreateScoreboardSortHeader(parent, x, y, w, h, text, key)
    local control = Turbine.UI.Control();
    control:SetParent(parent);
    control:SetPosition(x, y);
    control:SetSize(w, h);
    control:SetMouseVisible(true);
    control.sortKey = key;

    local normalColor = Turbine.UI.Color(1.00, 1.00, 0.70, 0.10);
    local hoverColor = Turbine.UI.Color(1.00, 1.00, 0.88, 0.24);
    control.labels = {};

    if type(text) == "table" then
        local labelWidth = w - 14;
        local lineH = 14;
        local startY = math.floor((h - (lineH * 2)) / 2);
        if startY < 0 then
            startY = 0;
            lineH = math.floor(h / 2);
        end
        local first = Label(control, 0, startY, labelWidth, lineH, tostring(text[1] or ""), "achievementDetail");
        first:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        first:SetForeColor(normalColor);
        first:SetMouseVisible(false);
        local second = Label(control, 0, startY + lineH, labelWidth, lineH, tostring(text[2] or ""), "achievementDetail");
        second:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        second:SetForeColor(normalColor);
        second:SetMouseVisible(false);
        control.labels[1] = first;
        control.labels[2] = second;
    else
        local label = Label(control, 0, 0, w - 16, h, text or "", "achievementDetail");
        label:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        label:SetForeColor(normalColor);
        label:SetMouseVisible(false);
        control.labels[1] = label;
    end

    if ParseGraph.ScoreboardSortKey == key then
        local arrowPath = (ParseGraph.ScoreboardIconPath or "") .. ((ParseGraph.ScoreboardSortDescending ~= false) and "sort_down.tga" or "sort_up.tga");
        local iconBack = DrawBlock(control, w - 12, math.floor((h - 11) / 2), 11, 11, Turbine.UI.Color(1.00, 0.00, 0.00, 0.00));
        iconBack:SetMouseVisible(false);
        local icon, loaded = ParseGraph.CreateManagedIcon(iconBack, 0, 0, 11, 11, arrowPath);
        if not loaded then
            ParseGraph.DisposeManagedIconControl(icon);
            ParseGraph.DisposeManagedIconControl(iconBack);
        end
    end

    control.MouseEnter = function(sender)
        if sender.labels ~= nil then
            for i = 1, #sender.labels do
                sender.labels[i]:SetForeColor(hoverColor);
            end
        end
    end
    control.MouseLeave = function(sender)
        if sender.labels ~= nil then
            for i = 1, #sender.labels do
                sender.labels[i]:SetForeColor(normalColor);
            end
        end
    end
    control.MouseClick = function(sender)
        ParseGraph.SetScoreboardSort(sender.sortKey);
    end

    return control;
end

function ParseGraph.GetScoreboardTabLabelLines(text)
    local label = tostring(text or "Boss");
    if string.len(label) <= 18 then
        return { label };
    end

    local best = 0;
    local middle = math.floor(string.len(label) / 2);
    for i = 1, string.len(label) do
        local ch = string.sub(label, i, i);
        if ch == " " or ch == "-" then
            if best == 0 or math.abs(i - middle) < math.abs(best - middle) then
                best = i;
            end
        end
    end

    if best > 0 then
        local first = string.gsub(string.sub(label, 1, best), "%s+$", "");
        local second = string.gsub(string.sub(label, best + 1), "^%s+", "");
        if string.len(first) > 0 and string.len(second) > 0 then
            if string.len(first) > 24 then first = string.sub(first, 1, 22) .. "..."; end
            if string.len(second) > 24 then second = string.sub(second, 1, 22) .. "..."; end
            return { first, second };
        end
    end

    return { string.sub(label, 1, 22) .. "..." };
end

function ParseGraph.ApplyScoreboardTabState(tab)
    if tab == nil then return end
    local selected = tab.selected == true;
    local hover = tab.hover == true;
    local pressed = tab.pressed == true;
    local fill = Turbine.UI.Color(1.00, 0.02, 0.06, 0.10);
    local border = Turbine.UI.Color(1.00, 0.58, 0.58, 0.58);
    local text = Turbine.UI.Color(1.00, 0.93, 0.76, 0.50);
    if selected or pressed then
        fill = Turbine.UI.Color(1.00, 0.03, 0.15, 0.32);
        border = Turbine.UI.Color(1.00, 1.00, 0.76, 0.18);
        text = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    elseif hover then
        fill = Turbine.UI.Color(1.00, 0.03, 0.11, 0.20);
        border = Turbine.UI.Color(1.00, 0.95, 0.72, 0.24);
        text = Turbine.UI.Color(1.00, 1.00, 0.88, 0.28);
    end

    if type(tab.scoreboardTabFills) == "table" then
        for i = 1, #tab.scoreboardTabFills do
            if tab.scoreboardTabFills[i] ~= nil then tab.scoreboardTabFills[i]:SetBackColor(fill); end
        end
    end
    if type(tab.scoreboardTabBorders) == "table" then
        for i = 1, #tab.scoreboardTabBorders do
            if tab.scoreboardTabBorders[i] ~= nil then tab.scoreboardTabBorders[i]:SetBackColor(border); end
        end
    end
    if type(tab.scoreboardTabLabels) == "table" then
        for i = 1, #tab.scoreboardTabLabels do
            if tab.scoreboardTabLabels[i] ~= nil then tab.scoreboardTabLabels[i]:SetForeColor(text); end
        end
    end
end

function ParseGraph.SetScoreboardTabSelected(tab, selected)
    if tab ~= nil then
        tab.selected = selected == true;
        ParseGraph.ApplyScoreboardTabState(tab);
    end
end

function ParseGraph.CreateScoreboardTabButton(parent, x, y, w, h, label, onClick)
    local tab = Turbine.UI.Control();
    tab:SetParent(parent);
    tab:SetPosition(x, y);
    tab:SetSize(w, h);
    tab:SetMouseVisible(true);

    local black = Turbine.UI.Color(1.00, 0.00, 0.00, 0.00);
    tab:SetBackColor(black);
    tab.scoreboardTabFills = {
        DrawBlock(tab, 0, 0, w, h, black),
        DrawBlock(tab, 4, 0, w - 8, h, black),
        DrawBlock(tab, 2, 2, w - 4, h - 2, black),
        DrawBlock(tab, 0, 5, w, h - 5, black)
    };
    tab.scoreboardTabBorders = {
        DrawBlock(tab, 5, 0, w - 10, 1, black),
        DrawBlock(tab, 3, 1, 2, 1, black),
        DrawBlock(tab, w - 5, 1, 2, 1, black),
        DrawBlock(tab, 1, 3, 1, 2, black),
        DrawBlock(tab, w - 2, 3, 1, 2, black),
        DrawBlock(tab, 0, 5, 1, h - 5, black),
        DrawBlock(tab, w - 1, 5, 1, h - 5, black),
        DrawBlock(tab, 0, h - 1, w, 1, black)
    };

    for i = 1, #tab.scoreboardTabFills do
        if tab.scoreboardTabFills[i] ~= nil then
            tab.scoreboardTabFills[i]:SetMouseVisible(false);
            tab.scoreboardTabFills[i]:SetZOrder(10);
        end
    end
    for i = 1, #tab.scoreboardTabBorders do
        if tab.scoreboardTabBorders[i] ~= nil then
            tab.scoreboardTabBorders[i]:SetMouseVisible(false);
            tab.scoreboardTabBorders[i]:SetZOrder(11);
        end
    end

    tab.scoreboardTabLabels = {};
    local labelLines = ParseGraph.GetScoreboardTabLabelLines(label);
    if #labelLines == 1 then
        local text = Label(tab, 8, 0, w - 16, h, labelLines[1], "achievement");
        text:SetFont(Turbine.UI.Lotro.Font.TrajanPro16);
        text:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        text:SetMouseVisible(false);
        text:SetZOrder(20);
        tab.scoreboardTabLabels[1] = text;
    else
        local first = Label(tab, 8, 5, w - 16, 18, labelLines[1], "achievement");
        first:SetFont(Turbine.UI.Lotro.Font.TrajanPro16);
        first:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        first:SetMouseVisible(false);
        first:SetZOrder(20);
        local second = Label(tab, 8, 21, w - 16, 18, labelLines[2], "achievement");
        second:SetFont(Turbine.UI.Lotro.Font.TrajanPro16);
        second:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        second:SetMouseVisible(false);
        second:SetZOrder(20);
        tab.scoreboardTabLabels[1] = first;
        tab.scoreboardTabLabels[2] = second;
    end

    tab.MouseEnter = function(sender)
        sender.hover = true;
        ParseGraph.ApplyScoreboardTabState(sender);
    end
    tab.MouseLeave = function(sender)
        sender.hover = false;
        sender.pressed = false;
        ParseGraph.ApplyScoreboardTabState(sender);
    end
    tab.MouseDown = function(sender)
        sender.pressed = true;
        ParseGraph.ApplyScoreboardTabState(sender);
    end
    tab.MouseUp = function(sender)
        sender.pressed = false;
        ParseGraph.ApplyScoreboardTabState(sender);
    end
    if onClick ~= nil then
        tab.MouseClick = function()
            onClick(tab);
        end
    end

    tab.scoreboardClickCatcher = Turbine.UI.Control();
    tab.scoreboardClickCatcher:SetParent(tab);
    tab.scoreboardClickCatcher:SetPosition(0, 0);
    tab.scoreboardClickCatcher:SetSize(w, h);
    tab.scoreboardClickCatcher:SetBackColor(Turbine.UI.Color(0.00, 0.00, 0.00, 0.00));
    tab.scoreboardClickCatcher:SetMouseVisible(true);
    tab.scoreboardClickCatcher:SetZOrder(1);
    tab.scoreboardClickCatcher.MouseEnter = function()
        tab.hover = true;
        ParseGraph.ApplyScoreboardTabState(tab);
    end
    tab.scoreboardClickCatcher.MouseLeave = function()
        tab.hover = false;
        tab.pressed = false;
        ParseGraph.ApplyScoreboardTabState(tab);
    end
    tab.scoreboardClickCatcher.MouseDown = function()
        tab.pressed = true;
        ParseGraph.ApplyScoreboardTabState(tab);
    end
    tab.scoreboardClickCatcher.MouseUp = function()
        tab.pressed = false;
        ParseGraph.ApplyScoreboardTabState(tab);
    end
    tab.scoreboardClickCatcher.MouseClick = function()
        if onClick ~= nil then
            onClick(tab);
        end
    end

    ParseGraph.ApplyScoreboardTabState(tab);
    return tab;
end

function ParseGraph.RemoveSelectedScoreboardBoard()
    local selectedKey = tostring(ParseGraph.ScoreboardSelectedKey or "__overall");
    if selectedKey == "__overall" then
        ParseGraph.ScoreboardBoards = {};
    else
        local boards = ParseGraph.ScoreboardBoards;
        if type(boards) ~= "table" then
            boards = {};
        end
        boards[selectedKey] = nil;
        ParseGraph.ScoreboardBoards = boards;
    end

    if ParseGraph.AccountData ~= nil then
        ParseGraph.AccountData.scoreboards = ParseGraph.ScoreboardBoards;
        ParseGraph.SaveAccountData();
    end

    ParseGraph.ScoreboardSelectedKey = "__overall";
    if ParseGraph.DrawScoreboardView ~= nil then
        ParseGraph.DrawScoreboardView();
    end
end

function ParseGraph.DrawScoreboardHiddenView()
    if ParseGraph.ScoreboardContentPanel == nil then
        return;
    end

    if ParseGraph.ScoreboardTierButton ~= nil then
        ParseGraph.ScoreboardTierButton:SetVisible(false);
        ParseGraph.ScoreboardTierButton:SetMouseVisible(false);
    end
    if ParseGraph.ScoreboardClearButton ~= nil then
        ParseGraph.ScoreboardClearButton:SetVisible(false);
        ParseGraph.ScoreboardClearButton:SetMouseVisible(false);
    end
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local orange = Turbine.UI.Color(1.00, 1.00, 0.70, 0.10);
    local white = Turbine.UI.Color(0.95, 0.92, 0.88, 0.82);
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local tableFill = Turbine.UI.Color(1.00, 0.01, 0.01, 0.01);
    local rowNormalFill = Turbine.UI.Color(1.00, 0.012, 0.012, 0.012);
    local rowAlternateFill = Turbine.UI.Color(1.00, 0.055, 0.055, 0.060);

    local title = Label(ParseGraph.ScoreboardContentPanel, 0, 2, 860, 34, "Hidden", "huge");
    title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    title:SetForeColor(gold);

    local subtitle = Label(ParseGraph.ScoreboardContentPanel, 0, 35, 860, 22, "Hidden scoreboard entries", "big");
    subtitle:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    subtitle:SetForeColor(white);

    local searchLabel = Label(ParseGraph.ScoreboardContentPanel, 48, 74, 70, 22, "Search", "achievementDetail");
    searchLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    searchLabel:SetForeColor(orange);

    DrawBlock(ParseGraph.ScoreboardContentPanel, 116, 72, 306, 1, border);
    DrawBlock(ParseGraph.ScoreboardContentPanel, 116, 96, 306, 1, border);
    DrawBlock(ParseGraph.ScoreboardContentPanel, 116, 72, 1, 25, border);
    DrawBlock(ParseGraph.ScoreboardContentPanel, 421, 72, 1, 25, border);

    local searchBox = Turbine.UI.Lotro.TextBox();
    searchBox:SetParent(ParseGraph.ScoreboardContentPanel);
    searchBox:SetPosition(120, 74);
    searchBox:SetSize(298, 20);
    searchBox:SetFont(Turbine.UI.Lotro.Font.TrajanPro14);
    searchBox:SetBackColor(Turbine.UI.Color(1.00, 0.02, 0.02, 0.02));
    searchBox:SetForeColor(white);
    searchBox:SetText(tostring(ParseGraph.ScoreboardHiddenSearchText or ""));
    searchBox:SetZOrder(20);
    ParseGraph.ScoreboardHiddenSearchBox = searchBox;

    DrawBlock(ParseGraph.ScoreboardContentPanel, 13, 112, 834, 1, border);
    local characterHeader = Label(ParseGraph.ScoreboardContentPanel, 48, 124, 260, 20, "Character", "achievementDetail");
    characterHeader:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    characterHeader:SetForeColor(orange);
    local actionHeader = Label(ParseGraph.ScoreboardContentPanel, 674, 124, 145, 20, "Action", "achievementDetail");
    actionHeader:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    actionHeader:SetForeColor(orange);
    DrawBlock(ParseGraph.ScoreboardContentPanel, 13, 148, 834, 1, border);

    local hiddenEntries = ParseGraph.GetScoreboardHiddenList();
    local rowH = 32;
    local startY = 158;
    local listW = 834;
    local listH = 342;
    local rowsBack = DrawBlock(ParseGraph.ScoreboardContentPanel, 13, startY, listW, listH, tableFill);
    rowsBack:SetMouseVisible(false);
    rowsBack:SetZOrder(1);

    local rowsList = Turbine.UI.ListBox();
    rowsList:SetParent(ParseGraph.ScoreboardContentPanel);
    rowsList:SetPosition(13, startY);
    rowsList:SetSize(listW, listH);
    rowsList:SetOrientation(Turbine.UI.Orientation.Vertical);
    rowsList:SetBackColor(tableFill);
    rowsList:SetMouseVisible(true);
    rowsList:SetZOrder(2);
    pcall(function()
        rowsList:SetClipMode(true);
    end);

    local rowsScroll = Turbine.UI.Lotro.ScrollBar();
    rowsScroll:SetParent(ParseGraph.ScoreboardContentPanel);
    rowsScroll:SetOrientation(Turbine.UI.Orientation.Vertical);
    rowsScroll:SetPosition(850, startY);
    rowsScroll:SetSize(10, listH);
    rowsScroll:SetBackColor(tableFill);
    rowsScroll:SetZOrder(3);
    rowsList:SetVerticalScrollBar(rowsScroll);

    local empty = Label(ParseGraph.ScoreboardContentPanel, 0, 260, 860, 30, "No hidden scoreboard entries.", "big");
    empty:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    empty:SetForeColor(white);
    empty:SetMouseVisible(false);
    empty:SetZOrder(30);
    empty:SetVisible(false);

    local function ClearHiddenRows()
        while rowsList:GetItemCount() > 0 do
            local item = rowsList:GetItem(1);
            if item == nil then
                break;
            end
            rowsList:RemoveItem(item);
        end
    end

    local function DrawHiddenRows()
        ClearHiddenRows();
        local query = string.lower(tostring(ParseGraph.ScoreboardHiddenSearchText or ""));
        query = string.gsub(query, "^%s+", "");
        query = string.gsub(query, "%s+$", "");
        local shownCount = 0;

        for i = 1, #hiddenEntries do
            local hiddenEntry = hiddenEntries[i] or {};
            local nameText = tostring(hiddenEntry.name or hiddenEntry.key or "");
            local keyText = tostring(hiddenEntry.key or "");
            local haystack = string.lower(nameText .. " " .. keyText);
            if query == "" or string.find(haystack, query, 1, true) ~= nil then
                shownCount = shownCount + 1;
                local rowFill = rowNormalFill;
                if shownCount % 2 == 0 then
                    rowFill = rowAlternateFill;
                end

                local row = Turbine.UI.Control();
                row:SetSize(listW, rowH);
                row:SetBackColor(rowFill);
                row:SetMouseVisible(true);
                rowsList:AddItem(row);
                row.rowBack = DrawBlock(row, 0, 0, listW, rowH, rowFill);
                row.rowBack:SetMouseVisible(false);
                row.rowBack:SetZOrder(1);
                row.normalFill = rowFill;
                row.hoverFill = ParseGraph.ParseRowHoverFill or Turbine.UI.Color(1.00, 0.04, 0.18, 0.34);
                row.MouseEnter = function(sender)
                    ParseGraph.ApplyScoreboardRowHover(sender, true);
                end
                row.MouseLeave = function(sender)
                    ParseGraph.ApplyScoreboardRowHover(sender, false);
                end

                local name = Label(row, 35, 0, 420, rowH, nameText, "big");
                name:SetFont(Turbine.UI.Lotro.Font.VerdanaBold16);
                name:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
                name:SetForeColor(white);
                name:SetMouseVisible(false);
                name:SetZOrder(5);

                local button = ParseGraph.CreateActionButton(row, 674, 5, 145, 22, "Unhide", function(sender)
                    ParseGraph.UnhideScoreboardEntry(sender.hiddenEntryKey);
                end);
                button.hiddenEntryKey = keyText;
                button:SetZOrder(10);
            end
        end

        rowsScroll:SetVisible((shownCount * rowH) > listH);
        empty:SetVisible(shownCount == 0);
        if #hiddenEntries == 0 then
            empty:SetText("No hidden scoreboard entries.");
        else
            empty:SetText("No hidden scoreboard entries match that search.");
        end
    end

    searchBox.TextChanged = function(sender)
        ParseGraph.ScoreboardHiddenSearchText = tostring(sender:GetText() or "");
        DrawHiddenRows();
    end

    DrawHiddenRows();
end

