    ParseGraph.ScoreboardTabsPanel = Turbine.UI.Control();
    ParseGraph.ScoreboardTabsPanel:SetParent(view);
    ParseGraph.ScoreboardTabsPanel:SetPosition(28, 66);
    ParseGraph.ScoreboardTabsPanel:SetSize(824, 64);
    ParseGraph.ScoreboardTabsPanel:SetMouseVisible(true);

    DrawBlock(view, 35, 134, 810, 1, border);

    ParseGraph.ScoreboardContentPanel = Turbine.UI.Control();
    ParseGraph.ScoreboardContentPanel:SetParent(view);
    ParseGraph.ScoreboardContentPanel:SetPosition(10, 146);
    ParseGraph.ScoreboardContentPanel:SetSize(860, 505);
    ParseGraph.ScoreboardContentPanel:SetBackColor(Turbine.UI.Color(1.00, 0.01, 0.01, 0.01));
    ParseGraph.ScoreboardContentPanel:SetMouseVisible(true);

    ParseGraph.ScoreboardTierButton = ParseGraph.CreateActionButton(view, 540, 688, 145, 22, "Tier", function(sender)
        ParseGraph.ShowUnmatchedSelectionSubmenu(sender, ParseGraph.BuildScoreboardTierItems(), 150);
    end);
    ParseGraph.ScoreboardTierButton:SetZOrder(100);

    ParseGraph.ScoreboardClearButton = ParseGraph.CreateActionButton(view, 700, 688, 145, 22, "Remove all", function()
        ParseGraph.RemoveSelectedScoreboardBoard();
    end);
    ParseGraph.ScoreboardClearButton:SetZOrder(100);

    view:SetVisible(false);
end

function ParseGraph.DrawScoreboardView()
    if ParseGraph.ScoreboardView == nil then
        return;
    end
    if ParseGraph.ScoreboardTabsPanel == nil or ParseGraph.ScoreboardContentPanel == nil or ParseGraph.ScoreboardOverallTabPanel == nil then
        return;
    end

    ParseGraph.HideScoreboardRowContextMenu();
    ClearChildren(ParseGraph.ScoreboardOverallTabPanel);
    ClearChildren(ParseGraph.ScoreboardTabsPanel);
    ClearChildren(ParseGraph.ScoreboardContentPanel);
    ParseGraph.ScoreboardTabButtons = {};

    local bossBoards = GetScoreboardBoardsSorted();
    local overallBoard = ParseGraph.GetScoreboardOverallBoard(bossBoards);
    local boards = { overallBoard };
    for i = 1, #bossBoards do
        boards[#boards + 1] = bossBoards[i];
    end

    local selectedExists = false;
    for i = 1, #boards do
        if boards[i].key == ParseGraph.ScoreboardSelectedKey then
            selectedExists = true;
            break;
        end
    end
    if selectedExists ~= true then
        ParseGraph.ScoreboardSelectedKey = "__overall";
    end

    local tabW = 194;
    local tabH = 44;
    local gap = 10;

    local overallButton = ParseGraph.CreateScoreboardTabButton(ParseGraph.ScoreboardOverallTabPanel, 0, 0, tabW, 36, "Overall", function()
        ParseGraph.ScoreboardShowingHidden = false;
        ParseGraph.ScoreboardSelectedKey = "__overall";
        ParseGraph.DrawScoreboardView();
    end);
    overallButton.scoreboardKey = "__overall";
    ParseGraph.SetScoreboardTabSelected(overallButton, ParseGraph.ScoreboardSelectedKey == "__overall");
    ParseGraph.ScoreboardTabButtons["__overall"] = overallButton;

    local tabList = Turbine.UI.ListBox();
    tabList:SetParent(ParseGraph.ScoreboardTabsPanel);
    tabList:SetPosition(0, 0);
    tabList:SetSize(824, 46);
    tabList:SetOrientation(Turbine.UI.Orientation.Horizontal);
    tabList:SetBackColor(Turbine.UI.Color(1.00, 0.00, 0.00, 0.00));
    pcall(function()
        tabList:SetClipMode(true);
    end);

    local tabScroll = Turbine.UI.Lotro.ScrollBar();
    tabScroll:SetParent(ParseGraph.ScoreboardTabsPanel);
    tabScroll:SetOrientation(Turbine.UI.Orientation.Horizontal);
    tabScroll:SetPosition(0, 50);
    tabScroll:SetSize(824, 10);
    tabScroll:SetBackColor(Turbine.UI.Color(1.00, 0.00, 0.00, 0.00));
    tabList:SetHorizontalScrollBar(tabScroll);
    tabScroll:SetVisible((#bossBoards * (tabW + gap)) > 824);

    for i = 1, #bossBoards do
        local board = bossBoards[i];
        local boardKey = board.key;
        local item = Turbine.UI.Control();
        item:SetSize(tabW + gap, tabH);
        item:SetBackColor(Turbine.UI.Color(1.00, 0.00, 0.00, 0.00));
        item:SetMouseVisible(true);
        item.scoreboardKey = boardKey;
        tabList:AddItem(item);

        local label = tostring(board.bossName or "Boss");
        local keyForButton = boardKey;
        local button = ParseGraph.CreateScoreboardTabButton(item, 0, 0, tabW, tabH, label, function()
            ParseGraph.ScoreboardShowingHidden = false;
            ParseGraph.ScoreboardSelectedKey = keyForButton;
            ParseGraph.DrawScoreboardView();
        end);
        button.scoreboardKey = keyForButton;
        button:SetMouseVisible(true);
        button:SetZOrder(10);
        item.scoreboardButton = button;
        item.MouseEnter = function(sender)
            if sender.scoreboardButton ~= nil then
                sender.scoreboardButton.hover = true;
                ParseGraph.ApplyScoreboardTabState(sender.scoreboardButton);
            end
        end
        item.MouseLeave = function(sender)
            if sender.scoreboardButton ~= nil then
                sender.scoreboardButton.hover = false;
                sender.scoreboardButton.pressed = false;
                ParseGraph.ApplyScoreboardTabState(sender.scoreboardButton);
            end
        end
        item.MouseDown = function(sender)
            if sender.scoreboardButton ~= nil then
                sender.scoreboardButton.pressed = true;
                ParseGraph.ApplyScoreboardTabState(sender.scoreboardButton);
            end
        end
        item.MouseUp = function(sender)
            if sender.scoreboardButton ~= nil then
                sender.scoreboardButton.pressed = false;
                ParseGraph.ApplyScoreboardTabState(sender.scoreboardButton);
            end
        end
        item.MouseClick = function()
            ParseGraph.ScoreboardShowingHidden = false;
            ParseGraph.ScoreboardSelectedKey = keyForButton;
            ParseGraph.DrawScoreboardView();
        end
        ParseGraph.SetScoreboardTabSelected(button, keyForButton == ParseGraph.ScoreboardSelectedKey);
        ParseGraph.ScoreboardTabButtons[keyForButton] = button;
    end

    local selected = nil;
    for i = 1, #boards do
        if boards[i].key == ParseGraph.ScoreboardSelectedKey then
            selected = boards[i];
            break;
        end
    end
    if selected == nil then
        return;
    end

    if ParseGraph.ScoreboardShowingHidden == true then
        ParseGraph.DrawScoreboardHiddenView();
        return;
    end

    if ParseGraph.ScoreboardTierButton ~= nil then
        local showTierButton = selected.isOverall ~= true;
        ParseGraph.ScoreboardTierButton:SetVisible(showTierButton);
        ParseGraph.ScoreboardTierButton:SetMouseVisible(showTierButton);
    end

    if ParseGraph.ScoreboardClearButton ~= nil and ParseGraph.ScoreboardClearButton.actionButtonLabel ~= nil then
        ParseGraph.ScoreboardClearButton:SetVisible(true);
        ParseGraph.ScoreboardClearButton:SetMouseVisible(true);
        if selected.isOverall == true then
            ParseGraph.ScoreboardClearButton.actionButtonLabel:SetText("Remove all");
        else
            ParseGraph.ScoreboardClearButton.actionButtonLabel:SetText("Remove");
        end
    end

    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local orange = Turbine.UI.Color(1.00, 1.00, 0.70, 0.10);
    local white = Turbine.UI.Color(0.95, 0.92, 0.88, 0.82);
    local blue = Turbine.UI.Color(1.00, 0.31, 0.75, 1.00);
    local green = Turbine.UI.Color(1.00, 0.24, 1.00, 0.34);
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);

    local header = tostring(selected.bossName or "Boss");
    local subtitleText = tostring(selected.instanceName or "");
    if selected.isOverall == true then
        header = "Overall";
        subtitleText = "All scoreboard bosses";
    else
        local tierLabel = GetScoreboardTierLabel(selected.tierKey);
        if tierLabel ~= "" then
            header = header .. " - " .. tierLabel;
        end
    end
    local title = Label(ParseGraph.ScoreboardContentPanel, 0, 2, 860, 34, header, "huge");
    title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    title:SetForeColor(gold);

    local subtitle = Label(ParseGraph.ScoreboardContentPanel, 0, 35, 860, 22, subtitleText, "big");
    subtitle:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    subtitle:SetForeColor(white);

    local tableX = 41;
    local listW = 765;
    DrawBlock(ParseGraph.ScoreboardContentPanel, tableX, 70, listW, 1, border);
    local rankHeader = Label(ParseGraph.ScoreboardContentPanel, tableX + 15, 72, 22, 32, "#", "achievementDetail");
    rankHeader:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    rankHeader:SetForeColor(orange);
    local characterHeader = Label(ParseGraph.ScoreboardContentPanel, tableX + 60, 72, 137, 32, "Character", "achievementDetail");
    characterHeader:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    characterHeader:SetForeColor(orange);
    ParseGraph.CreateScoreboardSortHeader(ParseGraph.ScoreboardContentPanel, tableX + 191, 72, 120, 32, "Total damage", "total");
    ParseGraph.CreateScoreboardSortHeader(ParseGraph.ScoreboardContentPanel, tableX + 321, 72, 80, 32, {"Average", "DPS"}, "average");
    ParseGraph.CreateScoreboardSortHeader(ParseGraph.ScoreboardContentPanel, tableX + 411, 72, 90, 32, {"Highest", "DPS"}, "highest");
    ParseGraph.CreateScoreboardSortHeader(ParseGraph.ScoreboardContentPanel, tableX + 521, 72, 80, 32, {"Average", "%"}, "percent");
    ParseGraph.CreateScoreboardSortHeader(ParseGraph.ScoreboardContentPanel, tableX + 611, 72, 75, 32, "Deaths", "deaths");
    local postsHeader = Label(ParseGraph.ScoreboardContentPanel, tableX + 701, 72, 49, 32, "Posts", "achievementDetail");
    postsHeader:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
    postsHeader:SetForeColor(orange);
    DrawBlock(ParseGraph.ScoreboardContentPanel, tableX, 106, listW, 1, border);

    local rows = {};
    for entryKey, entry in pairs(selected.entries or {}) do
        if type(entry) == "table" and ParseGraph.IsScoreboardPlayerName(entry.character) and ParseGraph.IsScoreboardEntryHidden(entryKey) ~= true and ParseGraph.IsScoreboardEntryHidden(entry.character) ~= true and ((tonumber(entry.totalDamage) or 0) > 0 or (tonumber(entry.deaths) or 0) > 0) then
            rows[#rows + 1] = { key = entryKey, entry = entry };
        end
    end
    local sortKey = ParseGraph.ScoreboardSortKey or "total";
    local sortDescending = ParseGraph.ScoreboardSortDescending ~= false;
    table.sort(rows, function(aRow, bRow)
        local a = aRow.entry or {};
        local b = bRow.entry or {};
        local av = ParseGraph.GetScoreboardSortValue(a, sortKey);
        local bv = ParseGraph.GetScoreboardSortValue(b, sortKey);
        if av == bv then
            local ad = tonumber(a.totalDamage) or 0;
            local bd = tonumber(b.totalDamage) or 0;
            if ad == bd then
                return tostring(a.character or "") < tostring(b.character or "");
            end
            return ad > bd;
        end
        if sortDescending then
            return av > bv;
        end
        return av < bv;
    end);

    local rowH = 32;
    local startY = 116;
    local listH = 384;
    local tableFill = Turbine.UI.Color(1.00, 0.01, 0.01, 0.01);
    local rowNormalFill = Turbine.UI.Color(1.00, 0.012, 0.012, 0.012);
    local rowAlternateFill = Turbine.UI.Color(1.00, 0.055, 0.055, 0.060);
    local rowsBack = DrawBlock(ParseGraph.ScoreboardContentPanel, tableX, startY, listW, listH, tableFill);
    rowsBack:SetMouseVisible(false);
    rowsBack:SetZOrder(1);

    local rowsList = Turbine.UI.ListBox();
    rowsList:SetParent(ParseGraph.ScoreboardContentPanel);
    rowsList:SetPosition(tableX, startY);
    rowsList:SetSize(listW, listH);
    rowsList:SetOrientation(Turbine.UI.Orientation.Vertical);
    rowsList:SetBackColor(tableFill);
    rowsList:SetMouseVisible(true);
    rowsList:SetZOrder(2);
    pcall(function()
        rowsList:SetClipMode(true);
    end);

    local rowsScroll = Turbine.UI.Lotro.ScrollBar();
    rowsScroll:SetParent(ParseGraph.ScoreboardContentPanel);
    rowsScroll:SetOrientation(Turbine.UI.Orientation.Vertical);
    rowsScroll:SetPosition(tableX + listW + 3, startY);
    rowsScroll:SetSize(10, listH);
    rowsScroll:SetBackColor(tableFill);
    rowsScroll:SetZOrder(3);
    rowsList:SetVerticalScrollBar(rowsScroll);
    rowsScroll:SetVisible((#rows * rowH) > listH);

    for i = 1, #rows do
        local rowData = rows[i] or {};
        local entry = rowData.entry or {};
        local entryKey = tostring(rowData.key or "");
        local rowFill = rowNormalFill;
        if i % 2 == 0 then
            rowFill = rowAlternateFill;
        end
        local row = Turbine.UI.Control();
        row:SetSize(listW, rowH);
        row:SetBackColor(rowFill);
        row:SetMouseVisible(true);
        rowsList:AddItem(row);
        row.rowBack = DrawBlock(row, 0, 0, listW, rowH, rowFill);
        row.rowBack:SetMouseVisible(false);
        row.rowBack:SetZOrder(1);
        row.normalFill = rowFill;
        row.hoverFill = ParseGraph.ParseRowHoverFill or Turbine.UI.Color(1.00, 0.04, 0.18, 0.34);
        row.MouseEnter = function(sender)
            ParseGraph.ApplyScoreboardRowHover(sender, true);
        end
        row.MouseLeave = function(sender)
            ParseGraph.ApplyScoreboardRowHover(sender, false);
        end

        row.scoreboardBoardKey = tostring(selected.key or "__overall");
        row.scoreboardEntryKey = entryKey;
        ParseGraph.AttachScoreboardRowContextHandler(row, row);
        local rank = Label(row, 15, 0, 22, rowH, tostring(i), "big");
        rank:SetFont(Turbine.UI.Lotro.Font.Verdana14);
        rank:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        rank:SetForeColor(gold);
        rank:SetMouseVisible(false);
        rank:SetZOrder(5);
        local name = Label(row, 49, 0, 133, rowH, tostring(entry.character or "Someone"), "big");
        name:SetFont(Turbine.UI.Lotro.Font.VerdanaBold16);
        name:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
        name:SetForeColor(white);
        name:SetMouseVisible(false);
        name:SetZOrder(5);
        local hasDamage = (tonumber(entry.totalDamage) or 0) > 0;
        local damageText = hasDamage and FormatNumber(entry.totalDamage) or "-";
        local damage = Label(row, 191, 0, 120, rowH, damageText, "big");
        damage:SetFont(Turbine.UI.Lotro.Font.Verdana14);
        damage:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        damage:SetForeColor(hasDamage and blue or white);
        damage:SetMouseVisible(false);
        damage:SetZOrder(5);
        local avg = (tonumber(entry.rateTotal) or 0) / math.max(1, tonumber(entry.posts) or 1);
        local avgLabel = Label(row, 321, 0, 80, rowH, hasDamage and FormatCompactDps(avg) or "-", "big");
        avgLabel:SetFont(Turbine.UI.Lotro.Font.Verdana14);
        avgLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        avgLabel:SetForeColor(hasDamage and green or white);
        avgLabel:SetMouseVisible(false);
        avgLabel:SetZOrder(5);
        local highest = tonumber(entry.highestRate) or tonumber(entry.lastRate) or avg;
        local highestLabel = Label(row, 411, 0, 90, rowH, hasDamage and FormatCompactDps(highest) or "-", "big");
        highestLabel:SetFont(Turbine.UI.Lotro.Font.Verdana14);
        highestLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        highestLabel:SetForeColor(hasDamage and green or white);
        highestLabel:SetMouseVisible(false);
        highestLabel:SetZOrder(5);
        local avgPercent = ParseGraph.GetScoreboardEntryAveragePercent(entry);
        local percentText = "-";
        if hasDamage and avgPercent ~= nil then
            percentText = string.format("%.1f%%", math.floor((avgPercent * 10) + 0.5) / 10);
        end
        local percentLabel = Label(row, 521, 0, 80, rowH, percentText, "big");
        percentLabel:SetFont(Turbine.UI.Lotro.Font.Verdana14);
        percentLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        percentLabel:SetForeColor(hasDamage and green or white);
        percentLabel:SetMouseVisible(false);
        percentLabel:SetZOrder(5);
        local deathCount = tonumber(entry.deaths) or 0;
        local deaths = Label(row, 611, 0, 75, rowH, tostring(deathCount), "big");
        deaths:SetFont(Turbine.UI.Lotro.Font.Verdana14);
        deaths:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        deaths:SetForeColor(ParseGraph.GetScoreboardDeathColor(deathCount));
        deaths:SetMouseVisible(false);
        deaths:SetZOrder(5);
        local posts = Label(row, 701, 0, 49, rowH, tostring(tonumber(entry.posts) or 0), "big");
        posts:SetFont(Turbine.UI.Lotro.Font.Verdana14);
        posts:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        posts:SetForeColor(white);
        posts:SetMouseVisible(false);
        posts:SetZOrder(5);
    end

    if #rows == 0 then
        local empty = Label(ParseGraph.ScoreboardContentPanel, 0, 220, 860, 30, "No ranked posts for this boss yet.", "big");
        empty:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        empty:SetForeColor(white);
        empty:SetMouseVisible(false);
        empty:SetZOrder(30);
    end
end

local function GetAchievementData(categoryKey)
    local key = categoryKey or ParseGraph.AchievementCategory or "special";
    local data = ParseGraph.Achievements[key];
    if data == nil then
        key = "special";
        data = ParseGraph.Achievements.special;
    end
    return key, data;
end

local function IsAchievementTabKey(categoryKey)
    local key = tostring(categoryKey or "");
    local tabs = ParseGraph.AchievementTabs or ParseGraph.AchievementCategories or {};
    for i = 1, #tabs do
        if tabs[i].key == key then
            return true;
        end
    end
    return false;
end

local function GetAchievementTabText(tab)
    if tab == nil then return "" end
    return tostring(tab.label or "");
end

function ParseGraph.UpdateAchievementCategoryButtons()
    if ParseGraph.AchievementCategoryButtons == nil then return end

    local tabs = ParseGraph.AchievementTabs or ParseGraph.AchievementCategories;
    for i = 1, #tabs do
        local category = tabs[i];
        local button = ParseGraph.AchievementCategoryButtons[category.key];
        if button ~= nil then
            if button.isActionButton == true then
                ParseGraph.SetActionButtonSelected(button, category.key == ParseGraph.AchievementCategory);
            elseif button.SetEnabled ~= nil then
                button:SetEnabled(category.key ~= ParseGraph.AchievementCategory);
            end
        end
    end
end

local function DrawAchievementBorder(parent, w, h, border)
    DrawBlock(parent, 0, 0, w, 1, border);
    DrawBlock(parent, 0, h - 1, w, 1, border);
    DrawBlock(parent, 0, 0, 1, h, border);
    DrawBlock(parent, w - 1, 0, 1, h, border);
end

local function DrawAchievementTile(parent, x, y, w, h, achievement, clipParent)
    local unlocked = ParseGraph.IsAchievementUnlocked(achievement.key);
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    if not unlocked then
        border = Turbine.UI.Color(1.00, 0.72, 0.74, 0.76);
    end
    local tile = Panel(parent, x, y, w, h, 1.00);
    tile:SetMouseVisible(unlocked == true);
    if unlocked then
        tile.MouseClick = function()
            ParseGraph.ShowAchievementPopup(achievement);
        end
    end
    DrawAchievementBorder(tile, w, h, border);

    local tallTile = h > 72;
    local iconY = tallTile and math.floor((h - 54) / 2) or 9;
    local titleH = tallTile and 42 or 30;
    local detailY = tallTile and 55 or 42;

    local iconFrame = Panel(tile, 12, iconY, 54, 54, 1.00);
    DrawAchievementBorder(iconFrame, 54, 54, border);

    local icon = Turbine.UI.Control();
    icon:SetParent(iconFrame);
    icon:SetPosition(3, 3);
    icon:SetSize(48, 48);
    icon:SetBackground(ParseGraph.GetAchievementIcon(achievement));
    icon:SetMouseVisible(false);
    icon:SetZOrder(50);

    if unlocked then
        local achievementForPost = achievement;
        ParseGraph.CreateInlineAliasQuickslot(iconFrame, ParseGraph.BuildAchievementPostCommand(achievementForPost), 3, 3, 48, 48, function()
            ParseGraph.ShowAchievementPopup(achievementForPost);
        end);
    end

    local progressText = ParseGraph.GetAchievementProgressText(achievement);
    local titleWidth = w - 96;
    if progressText ~= "" then
        titleWidth = w - 158;
        local progress = Label(tile, w - 82, 7, 68, 22, progressText, "achievementDetail");
        progress:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        progress:SetForeColor(Turbine.UI.Color(1.00, 1.00, 0.82, 0.16));
        progress:SetMouseVisible(false);
    end

    local title = Label(tile, 80, 8, titleWidth, titleH, achievement.title, "achievementTitle");
    title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    title:SetMouseVisible(false);

    local detail = Label(tile, 82, detailY, w - 96, 24, ParseGraph.GetAchievementDetailText(achievement), "achievementDetail");
    detail:SetForeColor(Turbine.UI.Color(0.85, 0.92, 0.84, 0.66));
    detail:SetMouseVisible(false);

    if unlocked then
        local clickLayer = Turbine.UI.Control();
        clickLayer:SetParent(tile);
        clickLayer:SetPosition(70, 0);
        clickLayer:SetSize(w - 70, h);
        clickLayer:SetMouseVisible(true);
        clickLayer:SetZOrder(90);
        clickLayer.MouseClick = function()
            ParseGraph.ShowAchievementPopup(achievement);
        end
    end
end

local GetParseDetailComparisonParses;
local BuildParseDetailCountAverages;
local GetParseDetailCountColor;

local function DrawPersonalBestTab(parent, w, h)
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local labelColor = Turbine.UI.Color(1.00, 0.93, 0.76, 0.28);
    local white = Turbine.UI.Color(0.95, 0.92, 0.88, 0.82);
    local muted = Turbine.UI.Color(0.90, 0.70, 0.70, 0.70);
    local blue = Turbine.UI.Color(1.00, 0.30, 0.78, 1.00);
    local green = Turbine.UI.Color(1.00, 0.25, 0.95, 0.25);
    local red = Turbine.UI.Color(1.00, 1.00, 0.25, 0.25);
    local black = Turbine.UI.Color(1.00, 0, 0, 0);
    local barColor = Turbine.UI.Color(1.00, 0.345, 0.106, 0.106);

    local highest = ParseGraph.GetHighestParsePoint();
    if highest.index == nil then
        local empty = Label(parent, 0, 225, w, 30, "No personal best recorded yet.", "huge");
        empty:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        empty:SetForeColor(white);
        return;
    end

    local viewParses = ParseGraph.GetViewParses();
    local parse = viewParses[highest.index] or {};
    local finalValue = tonumber(parse.final) or tonumber(highest.value) or 0;
    local sourceKey = tostring(parse.__sourceKey or ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey());
    local sourceIndex = tonumber(parse.__sourceIndex or highest.index) or highest.index;
    local sourceName = tostring(parse.__sourceName or ParseGraph.GetCharacterDisplayName(sourceKey));
    local personalBestPoint = {
        parse = parse,
        index = tonumber(highest.index) or sourceIndex,
        sourceKey = sourceKey,
        sourceIndex = sourceIndex,
        sourceName = sourceName,
        returnView = "achievements"
    };
    local stats = ParseGraph.GetAllTimeStats(true);
    local average = tonumber(stats.average);
    local aboveAverage = nil;
    if average ~= nil then
        aboveAverage = finalValue - average;
    end

    local function PBLabel(parentControl, x, y, width, height, text, font, color, align)
        local l = Turbine.UI.Label();
        l:SetParent(parentControl);
        l:SetPosition(x, y);
        l:SetSize(width, height);
        l:SetFont(font or Turbine.UI.Lotro.Font.TrajanPro16);
        l:SetFontStyle(Turbine.UI.FontStyle.Outline);
        l:SetOutlineColor(black);
        l:SetForeColor(color or white);
        l:SetTextAlignment(align or Turbine.UI.ContentAlignment.MiddleLeft);
        l:SetText(text or "");
        l:SetMouseVisible(false);
        return l;
    end

    local function SignedNumber(value)
        if value == nil then
            return "-";
        end
        value = Round(value);
        if value > 0 then
            return "+" .. FormatNumber(value);
        end
        return FormatNumber(value);
    end

    local listW = math.max(1, w - 18);
    local listH = math.max(1, h - 4);
    local totalHeight = 0;

    local list = Turbine.UI.ListBox();
    list:SetParent(parent);
    list:SetPosition(0, 0);
    list:SetSize(listW, listH);
    list:SetOrientation(Turbine.UI.Orientation.Vertical);
    list:SetBackColor(black);
    pcall(function()
        list:SetClipMode(true);
    end);

    local scroll = Turbine.UI.Lotro.ScrollBar();
    scroll:SetParent(parent);
    scroll:SetOrientation(Turbine.UI.Orientation.Vertical);
    scroll:SetPosition(w - 14, 0);
    scroll:SetSize(12, listH);
    scroll:SetBackColor(black);
    list:SetVerticalScrollBar(scroll);
    scroll:SetVisible(false);

    local function AddPBItem(height)
        local item = Turbine.UI.Control();
        item:SetSize(listW, height);
        item:SetBackColor(black);
        item:SetMouseVisible(true);
        list:AddItem(item);
        totalHeight = totalHeight + height;
        return item;
    end

    local topItem = AddPBItem(305);
    local card = Panel(topItem, 70, 20, listW - 140, 255, 1.00);
    DrawAchievementBorder(card, listW - 140, 255, border);
    PBLabel(card, 0, 18, listW - 140, 34, "Personal Best Parse", Turbine.UI.Lotro.Font.TrajanProBold22, gold, Turbine.UI.ContentAlignment.MiddleCenter);
    DrawBlock(card, 35, 56, listW - 210, 1, border);

    PBLabel(card, 0, 70, listW - 140, 62, FormatNumber(finalValue) .. " DPS", Turbine.UI.Lotro.Font.TrajanProBold36, blue, Turbine.UI.ContentAlignment.MiddleCenter);
    PBLabel(card, 0, 126, listW - 140, 24, sourceName, Turbine.UI.Lotro.Font.TrajanPro16, white, Turbine.UI.ContentAlignment.MiddleCenter);
    DrawBlock(card, 35, 158, listW - 210, 1, border);

    local cardW = listW - 140;
    local splitX = math.floor(cardW / 2);
    local labelW = 210;
    local valueW = 260;
    local leftX = splitX - labelW - 10;
    local valueX = splitX + 10;
    local rowY = 176;
    local rowH = 24;
    PBLabel(card, leftX, rowY, labelW, rowH, "Date / Time", Turbine.UI.Lotro.Font.TrajanPro16, labelColor, Turbine.UI.ContentAlignment.MiddleRight);
    PBLabel(card, valueX, rowY, valueW, rowH, tostring(parse.time or "-"), Turbine.UI.Lotro.Font.TrajanPro16, white, Turbine.UI.ContentAlignment.MiddleLeft);
    rowY = rowY + 25;
    PBLabel(card, leftX, rowY, labelW, rowH, "Parse number", Turbine.UI.Lotro.Font.TrajanPro16, labelColor, Turbine.UI.ContentAlignment.MiddleRight);
    PBLabel(card, valueX, rowY, valueW, rowH, "#" .. tostring(highest.index), Turbine.UI.Lotro.Font.TrajanPro16, white, Turbine.UI.ContentAlignment.MiddleLeft);
    rowY = rowY + 25;
    PBLabel(card, leftX, rowY, labelW, rowH, "Above all-time average", Turbine.UI.Lotro.Font.TrajanPro16, labelColor, Turbine.UI.ContentAlignment.MiddleRight);
    PBLabel(card, valueX, rowY, valueW, rowH, SignedNumber(aboveAverage), Turbine.UI.Lotro.Font.TrajanPro16, aboveAverage ~= nil and aboveAverage >= 0 and green or red, Turbine.UI.ContentAlignment.MiddleLeft);

    local minutes = parse.minutes or {};
    local minuteItem = AddPBItem(205);
    local minuteCard = Panel(minuteItem, 150, 10, listW - 300, 130, 1.00);
    DrawAchievementBorder(minuteCard, listW - 300, 130, border);
    PBLabel(minuteCard, 0, 14, listW - 300, 24, "Minute Breakdown", Turbine.UI.Lotro.Font.TrajanProBold22, gold, Turbine.UI.ContentAlignment.MiddleCenter);
    DrawBlock(minuteCard, 35, 43, listW - 370, 1, border);

    local colW = 150;
    local colGap = 18;
    local startX = math.floor(((listW - 300) - ((colW * 3) + (colGap * 2))) / 2);
    local labels = { "1st minute", "2nd minute", "3rd minute" };
    for i = 1, 3 do
        local x = startX + ((i - 1) * (colW + colGap));
        PBLabel(minuteCard, x, 56, colW, 22, labels[i], Turbine.UI.Lotro.Font.TrajanPro16, labelColor, Turbine.UI.ContentAlignment.MiddleCenter);
        PBLabel(minuteCard, x, 82, colW, 24, ParseGraph.FormatSummaryNumber(minutes[i]), Turbine.UI.Lotro.Font.TrajanPro16, white, Turbine.UI.ContentAlignment.MiddleCenter);
    end

    local pbButtonW = 120;
    local pbButtonGap = 12;
    local pbButtonX = math.floor((listW - ((pbButtonW * 2) + pbButtonGap)) / 2);
    local shareButton = ParseGraph.CreateActionButton(minuteItem, pbButtonX, 160, pbButtonW, 24, "Share", function(sender)
        ParseGraph.ShareParsePoint(sender.parsePoint);
    end);
    shareButton.parsePoint = personalBestPoint;
    shareButton:SetZOrder(100);
    ParseGraph.CreatePostButton(minuteItem, parse, pbButtonX + pbButtonW + pbButtonGap, 160, pbButtonW, 24, "personalBest", "achievements");

    local combat = parse.combat;
    if type(combat) == "table" and (tonumber(combat.attacks) or 0) > 0 then
        local function PBPercent(count, total)
            count = tonumber(count) or 0;
            total = tonumber(total) or 0;
            if total <= 0 then
                return "-";
            end
            return string.format("%.1f%%", (count / total) * 100);
        end

        local function PBRate(count, seconds)
            count = tonumber(count) or 0;
            seconds = tonumber(seconds) or 0;
            if seconds <= 0 then
                return "-";
            end
            return string.format("%.2f", count / seconds);
        end

        local combatItem = AddPBItem(178);
        DrawBlock(combatItem, 35, 18, listW - 70, 1, border);
        PBLabel(combatItem, 0, 34, listW, 30, "Combat Breakdown", Turbine.UI.Lotro.Font.TrajanProBold22, gold, Turbine.UI.ContentAlignment.MiddleCenter);
        DrawBlock(combatItem, 35, 78, listW - 70, 1, border);

        local function PBStat(parentControl, x, y, statW, labelText, valueText, valueColor)
            PBLabel(parentControl, x, y, statW, 20, labelText, Turbine.UI.Lotro.Font.TrajanPro16, labelColor, Turbine.UI.ContentAlignment.MiddleLeft);
            PBLabel(parentControl, x, y + 24, statW, 24, valueText, Turbine.UI.Lotro.Font.TrajanPro16, valueColor or white, Turbine.UI.ContentAlignment.MiddleLeft);
        end

        PBStat(combatItem, 48, 100, 125, "Total damage", FormatNumber(combat.totalDamage), white);
        PBStat(combatItem, 180, 100, 95, "Hits", FormatNumber(combat.hits or combat.attacks), white);
        PBStat(combatItem, 294, 100, 90, "APS", PBRate(combat.hits or combat.attacks, combat.duration), white);
        PBStat(combatItem, 408, 100, 120, "Crit chance", PBPercent(combat.crits, combat.hits or combat.attacks), white);
        PBStat(combatItem, 552, 100, 120, "Dev chance", PBPercent(combat.devs, combat.hits or combat.attacks), white);
        PBStat(combatItem, 696, 100, 110, "Max hit", FormatNumber(combat.max), white);

        local skills = {};
        if type(combat.skills) == "table" then
            for _, bucket in pairs(combat.skills) do
                if type(bucket) == "table" then
                    table.insert(skills, bucket);
                end
            end
        end
        table.sort(skills, function(a, b)
            return (tonumber(a.totalDamage) or 0) > (tonumber(b.totalDamage) or 0);
        end);

        local benefits = {};
        if type(combat.benefits) == "table" then
            for _, bucket in pairs(combat.benefits) do
                if type(bucket) == "table" then
                    table.insert(benefits, bucket);
                end
            end
        end
        table.sort(benefits, function(a, b)
            local ac = tonumber(a.count) or 0;
            local bc = tonumber(b.count) or 0;
            if ac == bc then
                return tostring(a.name or "") < tostring(b.name or "");
            end
            return ac > bc;
        end);

        if #skills > 0 or #benefits > 0 then
            local tableItem = AddPBItem(58);
            PBLabel(tableItem, 48, 4, listW - 96, 28, "Breakdown", Turbine.UI.Lotro.Font.TrajanProBold22, gold, Turbine.UI.ContentAlignment.MiddleCenter);
            local columns = {
                { x = 82, w = 315, text = "Skill" },
                { x = 402, w = 70, text = "Hits", align = Turbine.UI.ContentAlignment.MiddleRight },
                { x = 500, w = 120, text = "Damage", align = Turbine.UI.ContentAlignment.MiddleRight },
                { x = 650, w = 65, text = "Crit", align = Turbine.UI.ContentAlignment.MiddleRight },
                { x = 736, w = 55, text = "Dev", align = Turbine.UI.ContentAlignment.MiddleRight }
            };
            for i = 1, #columns do
                local col = columns[i];
                local label = PBLabel(tableItem, col.x, 34, col.w, 20, col.text, Turbine.UI.Lotro.Font.TrajanPro16, labelColor, col.align or Turbine.UI.ContentAlignment.MiddleLeft);
                label:SetMouseVisible(false);
            end
            DrawBlock(tableItem, 48, 56, listW - 96, 1, border);

            local maxSkillDamage = 0;
            for i = 1, #skills do
                maxSkillDamage = math.max(maxSkillDamage, tonumber(skills[i].totalDamage) or 0);
            end

            local rowH = 28;
            local normalFill = ParseGraph.ParseRowNormalFill or black;
            local hoverFill = ParseGraph.ParseRowHoverFill or Turbine.UI.Color(1.00, 0.08, 0.16, 0.24);
            local pbAverages = { skills = {}, benefits = {}, skillDamage = {}, skillCrit = {}, skillDev = {} };
            if BuildParseDetailCountAverages ~= nil and GetParseDetailComparisonParses ~= nil then
                pbAverages = BuildParseDetailCountAverages(GetParseDetailComparisonParses(personalBestPoint));
            end

            local function DrawPBIcon(row, iconId)
                if iconId == nil then
                    return;
                end
                local iconSlot = DrawBlock(row, 52, 4, 22, 22, normalFill);
                iconSlot:SetMouseVisible(false);
                pcall(function()
                    iconSlot:SetClipMode(true);
                end);

                local icon = nil;
                local iconLoaded = false;
                icon, iconLoaded = ParseGraph.CreateManagedIcon(iconSlot, 3, 3, 16, 16, iconId);
                if iconLoaded ~= true then
                    ParseGraph.DisposeManagedIconControl(iconSlot);
                    return;
                end

                local function UpdateIconVisibility()
                    ParseGraph.UpdateManagedIconClip({
                        iconSlot = iconSlot,
                        icon = icon,
                        row = row,
                        viewportH = listH,
                        slotX = 52,
                        slotY = 4,
                        slotW = 22,
                        slotH = 22,
                        iconX = 3,
                        iconY = 3
                    });
                end

                ParseGraph.ParseCompareIconControls = ParseGraph.ParseCompareIconControls or {};
                table.insert(ParseGraph.ParseCompareIconControls, {
                    iconSlot = iconSlot,
                    icon = icon,
                    update = UpdateIconVisibility
                });

                local oldPositionChanged = row.PositionChanged;
                row.PositionChanged = function(sender, args)
                    if oldPositionChanged ~= nil then
                        oldPositionChanged(sender, args);
                    end
                    UpdateIconVisibility();
                end
                UpdateIconVisibility();
            end

            local function CreatePBRow()
                local row = AddPBItem(rowH);
                row:SetBackColor(normalFill);
                row:SetMouseVisible(true);
                row.MouseEnter = function(sender)
                    sender:SetBackColor(hoverFill);
                end
                row.MouseLeave = function(sender)
                    sender:SetBackColor(normalFill);
                end
                pcall(function()
                    row:SetClipMode(true);
                end);
                return row;
            end

            for i = 1, #skills do
                local skill = skills[i];
                local row = CreatePBRow();
                local skillName = tostring(skill.name or "");
                local skillHits = tonumber(skill.hits or skill.attacks) or 0;
                local skillDamage = tonumber(skill.totalDamage) or 0;
                local skillCritRate = nil;
                local skillDevRate = nil;
                if skillHits > 0 then
                    skillCritRate = (tonumber(skill.crits) or 0) / skillHits;
                    skillDevRate = (tonumber(skill.devs) or 0) / skillHits;
                end
                local hitsColor = GetParseDetailCountColor ~= nil and GetParseDetailCountColor(skillHits, pbAverages.skills[skillName], white) or white;
                local damageColor = GetParseDetailCountColor ~= nil and GetParseDetailCountColor(skillDamage, pbAverages.skillDamage[skillName], white) or white;
                local critColor = GetParseDetailCountColor ~= nil and GetParseDetailCountColor(skillCritRate, pbAverages.skillCrit[skillName], white) or white;
                local devColor = GetParseDetailCountColor ~= nil and GetParseDetailCountColor(skillDevRate, pbAverages.skillDev[skillName], white) or white;
                local barWidth = 0;
                local barX = 82;
                local barMaxWidth = listW - barX - 48;
                if maxSkillDamage > 0 then
                    barWidth = math.floor(barMaxWidth * (skillDamage / maxSkillDamage));
                end
                DrawBlock(row, barX, 3, barWidth, 22, barColor):SetMouseVisible(false);
                DrawPBIcon(row, ParseGraph.GetSkillIconId(skill.name));
                PBLabel(row, 82, 0, 315, rowH, tostring(skill.name or "-"), Turbine.UI.Lotro.Font.TrajanPro16, white, Turbine.UI.ContentAlignment.MiddleLeft);
                PBLabel(row, 402, 0, 70, rowH, FormatNumber(skillHits), Turbine.UI.Lotro.Font.TrajanPro16, hitsColor, Turbine.UI.ContentAlignment.MiddleRight);
                PBLabel(row, 500, 0, 120, rowH, FormatNumber(skillDamage), Turbine.UI.Lotro.Font.TrajanPro16, damageColor, Turbine.UI.ContentAlignment.MiddleRight);
                PBLabel(row, 650, 0, 65, rowH, PBPercent(skill.crits, skill.hits or skill.attacks), Turbine.UI.Lotro.Font.TrajanPro16, critColor, Turbine.UI.ContentAlignment.MiddleRight);
                PBLabel(row, 736, 0, 55, rowH, PBPercent(skill.devs, skill.hits or skill.attacks), Turbine.UI.Lotro.Font.TrajanPro16, devColor, Turbine.UI.ContentAlignment.MiddleRight);
            end

            if #benefits > 0 then
                local separator = AddPBItem(58);
                PBLabel(separator, 48, 14, listW - 96, 26, "Benefits", Turbine.UI.Lotro.Font.TrajanProBold18, gold, Turbine.UI.ContentAlignment.MiddleCenter);
                DrawBlock(separator, 48, 50, listW - 96, 1, border);

                for i = 1, #benefits do
                    local benefit = benefits[i];
                    local row = CreatePBRow();
                    local benefitName = tostring(benefit.name or "");
                    local benefitCount = tonumber(benefit.count) or 0;
                    local benefitColor = GetParseDetailCountColor ~= nil and GetParseDetailCountColor(benefitCount, pbAverages.benefits[benefitName], white) or white;
                    DrawPBIcon(row, ParseGraph.GetSkillIconId(benefit.name));
                    PBLabel(row, 82, 0, 315, rowH, tostring(benefit.name or "-"), Turbine.UI.Lotro.Font.TrajanPro16, white, Turbine.UI.ContentAlignment.MiddleLeft);
                    PBLabel(row, 402, 0, 70, rowH, FormatNumber(benefitCount), Turbine.UI.Lotro.Font.TrajanPro16, benefitColor, Turbine.UI.ContentAlignment.MiddleRight);
                end
            end
        end
    end

    scroll:SetVisible(totalHeight > listH);
end

function ParseGraph.DrawAchievementsView()
    if ParseGraph.AchievementListPanel == nil then return end

    ParseGraph.ClearPostButtonWindows();
    ClearChildren(ParseGraph.AchievementListPanel);
    ParseGraph.UpdateAchievementCategoryButtons();

    if ParseGraph.AchievementCategory == "personalBest" then
        local panel = ParseGraph.AchievementListPanel;
        DrawPersonalBestTab(panel, panel:GetWidth(), panel:GetHeight());
        return;
    end

    local categoryKey, data = GetAchievementData(ParseGraph.AchievementCategory);
    local panel = ParseGraph.AchievementListPanel;
    local w = panel:GetWidth();
    local h = panel:GetHeight();
    local labelColor = Turbine.UI.Color(1.00, 0.93, 0.76, 0.28);

    local rawItems = data.items or {};
    local items = {};
    for i = 1, #rawItems do
        local achievement = rawItems[i];
        if achievement.hiddenUntilUnlocked ~= true or ParseGraph.IsAchievementUnlocked(achievement.key) then
            table.insert(items, achievement);
        end
    end
    local tileW = 400;
    local tileH = 72;
    if categoryKey == "special" then
        tileH = 88;
    end
    local gapX = 20;
    local gapY = 8;
    local startY = 14;
    if categoryKey == "parses" then
        local totalLabel = Label(panel, 0, 8, w, 34, "Total parses: " .. FormatNumber(ParseGraph.GetAccountParseCount()), "huge");
        totalLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        totalLabel:SetForeColor(Turbine.UI.Color(1.00, 1.00, 0.82, 0.16));
        DrawBlock(panel, 120, 46, w - 240, 1, Turbine.UI.Color(1.00, 0.95, 0.56, 0.12));
        startY = 64;
    end

    local listW = 820;
    local listH = math.max(1, h - startY - 6);
    local list = Turbine.UI.ListBox();
    list:SetParent(panel);
    list:SetPosition(10, startY);
    list:SetSize(listW, listH);
    list:SetOrientation(Turbine.UI.Orientation.Vertical);
    list:SetBackColor(Turbine.UI.Color(1.00, 0, 0, 0));
    if list.SetWantsUpdates ~= nil then
        local lastAliasRefresh = 0;
        list:SetWantsUpdates(true);
        list.Update = function()
            local now = Turbine.Engine.GetGameTime();
            if now == nil or (now - lastAliasRefresh) > 0.08 then
                lastAliasRefresh = now or lastAliasRefresh;
                ParseGraph.UpdatePostButtonWindowPositions();
            end
        end
    end

    local scroll = Turbine.UI.Lotro.ScrollBar();
    scroll:SetParent(panel);
    scroll:SetOrientation(Turbine.UI.Orientation.Vertical);
    scroll:SetPosition(w - 22, startY);
    scroll:SetSize(12, listH);
    list:SetVerticalScrollBar(scroll);
    scroll.ValueChanged = function()
        ParseGraph.UpdatePostButtonWindowPositions();
    end

    local rowH = tileH + gapY;
    local rowCount = math.ceil(#items / 2);
    scroll:SetVisible((rowCount * rowH) > listH);

    local currentRowPanel = nil;
    for i = 1, #items do
        if ((i - 1) % 2) == 0 then
            currentRowPanel = Turbine.UI.Control();
            currentRowPanel:SetSize(listW, rowH);
            currentRowPanel:SetMouseVisible(true);
            list:AddItem(currentRowPanel);
        end
        local col = (i - 1) % 2;
        local x = col * (tileW + gapX);
        local y = 0;
        if categoryKey == "damage" and i == #items and (#items % 2) == 1 then
            x = math.floor((listW - tileW) / 2);
        end
        DrawAchievementTile(currentRowPanel, x, y, tileW, tileH, items[i], list);
    end

    local planned = tonumber(data.plannedCount) or #items;
    if #rawItems < planned then
        local missing = planned - #rawItems;
        local footer = Label(panel, 0, h - 34, w, 22, tostring(missing) .. " achievements still need icons.", "small");
        footer:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        footer:SetForeColor(labelColor);
    end
end

function ParseGraph.SetAchievementCategory(categoryKey)
    local key = tostring(categoryKey or "");
    if not IsAchievementTabKey(key) then
        key = GetAchievementData(key);
    end
    ParseGraph.AchievementCategory = key;
    ParseGraph.DrawAchievementsView();
end

function ParseGraph.GetInstanceDefinition(key)
    key = tostring(key or ParseGraph.SelectedInstanceKey or "");
    for i = 1, #ParseGraph.InstanceDefinitions do
        if ParseGraph.InstanceDefinitions[i].key == key then
            return ParseGraph.InstanceDefinitions[i];
        end
    end
    return ParseGraph.InstanceDefinitions[1];
end

function ParseGraph.GetOrderedInstanceDefinitions()
    local ordered = {};
    local seen = {};
    local displayOrder = ParseGraph.InstanceDisplayOrder or {};

    for i = 1, #displayOrder do
        local key = tostring(displayOrder[i] or "");
        for j = 1, #ParseGraph.InstanceDefinitions do
            local instance = ParseGraph.InstanceDefinitions[j];
            if instance ~= nil and instance.key == key and seen[key] ~= true then
                ordered[#ordered + 1] = instance;
                seen[key] = true;
                break;
            end
        end
    end

    for i = 1, #ParseGraph.InstanceDefinitions do
        local instance = ParseGraph.InstanceDefinitions[i];
        local key = instance and instance.key or nil;
        if key ~= nil and seen[key] ~= true then
            ordered[#ordered + 1] = instance;
            seen[key] = true;
        end
    end

    return ordered;
end

function ParseGraph.GetInstanceDefinitionFromQuestText(text)
    local lower = LowerClean(text);
    if string.find(lower, "new quest:", 1, true) == nil then
        return nil, nil;
    end

    local tierNumber = tonumber(string.match(lower, "tier%s*(%d)"));
    if tierNumber == nil or tierNumber < 1 or tierNumber > 3 then
        return nil, nil;
    end

    local matchText = NormalizeBossMatchText(text);
    for i = 1, #ParseGraph.InstanceDefinitions do
        local instance = ParseGraph.InstanceDefinitions[i];
        if instance ~= nil then
            local instanceName = NormalizeBossMatchText(instance.name);
            if instanceName ~= "" and string.find(matchText, instanceName, 1, true) ~= nil then
                return instance, "t" .. tostring(tierNumber);
            end

            local articleStrippedName = string.match(instanceName, "^the%s+(.+)$");
            if articleStrippedName ~= nil and articleStrippedName ~= "" and string.find(matchText, articleStrippedName, 1, true) ~= nil then
                return instance, "t" .. tostring(tierNumber);
            end
        end
    end

    return nil, nil;
end

function ParseGraph.ProcessInstanceQuestText(text)
    local instance, tierKey = ParseGraph.GetInstanceDefinitionFromQuestText(text);
    if instance == nil or tierKey == nil then
        return false;
    end

    ParseGraph.ActiveInstanceKey = instance.key;
    ParseGraph.ActiveInstanceTierKey = tierKey;
    ParseGraph.AutoInstanceBossIndex = nil;
    ParseGraph.AutoInstanceDefeats = nil;
    ParseGraph.SelectedInstanceBossIndex = nil;
    ParseGraph.ManualInstanceTarget = nil;
    ParseGraph.SelectedInstanceKey = instance.key;
    ParseGraph.SelectedInstanceTierKey = tierKey;
    ParseGraph.SetLauncherButtonState();

    if ParseGraph.CurrentView == "instances" then
        ParseGraph.DrawInstancesView();
    end

    return true;
end

local function StripLeadingChatTimestamp(text)
    text = TrimText(text);
    local bracketText = string.match(text, "^%[([^%]]+)%]%s+");
    if bracketText ~= nil and (string.find(bracketText, "%d+/%d+") ~= nil or string.find(bracketText, "%d+:%d+") ~= nil) then
        local closeAt = string.find(text, "]", 1, true);
        if closeAt ~= nil then
            text = TrimText(string.sub(text, closeAt + 1));
        end
    end
    return text;
end

function ParseGraph.ProcessFaillowshipChatText(text)
    local line = StripLeadingChatTimestamp(StripLotroMarkup(text));
    local room, userChat = string.match(line, "^%s*[Yy]ou%s+joined%s+room%s+'([^']+)'%s+%([Uu]ser[Cc]hat(%d+)%)%.%s+Number%s+of%s+members:%s+%d+%.?%s*$");
    if room == nil or userChat == nil then
        return;
    end

    if string.lower(tostring(room)) ~= "faillowship" then
        return;
    end

    local channelNumber = tonumber(userChat);
    if channelNumber == nil or channelNumber < 1 or channelNumber > 8 then
        return;
    end

    ParseGraph.FaillowshipJoined = true;
    ParseGraph.FaillowshipCommand = tostring(channelNumber);
    ParseGraph.FaillowshipRoomName = tostring(room);
    for i = 1, #ParseGraph.PostChannels do
        if ParseGraph.PostChannels[i].key == "faillowship" then
            ParseGraph.PostChannels[i].command = ParseGraph.FaillowshipCommand;
            break;
        end
    end

    ParseGraph.UpdatePostChannelButtons();
    ParseGraph.RefreshPostAliasesForCurrentView();
end

function ParseGraph.GetOwnCombatAnalysisPayload(text)
    local line = StripLeadingChatTimestamp(StripLotroMarkup(text));
    local lower = LowerClean(line);

    if string.find(lower, "^you%s+say,") ~= nil then
        local payload = string.match(line, "^%s*[Yy]ou%s+say,%s*'(.+)'%s*$");
        if payload == nil then
            payload = string.match(line, "^%s*[Yy]ou%s+say,%s*\"(.+)\"%s*$");
        end
        if payload == nil then
            payload = string.match(line, "^%s*[Yy]ou%s+say,%s*(.+)%s*$");
        end
        return TrimText(payload), ParseGraph.GetCurrentCharacterName();
    end

    local channel, payload = string.match(line, "^%s*%[To%s+([^%]]+)%]%s*(.+)%s*$");
    if channel ~= nil and payload ~= nil then
        return TrimText(payload), ParseGraph.GetCurrentCharacterName();
    end

    local incomingSender, incomingPayload = string.match(line, "^%s*%[[^%]]+%]%s*([^:]+):%s*(.+)%s*$");
    if incomingPayload ~= nil then
        incomingPayload = TrimText(string.gsub(incomingPayload, "'%s*$", ""));
        local incomingLower = LowerClean(incomingPayload);
        local incomingFirstLine = string.match(incomingPayload, "^([^\r\n]+)") or incomingPayload;
        if string.find(incomingLower, "^analysis%s+for%s+") ~= nil
            or string.find(incomingLower, "dmg:", 1, true) ~= nil
            or string.find(incomingLower, "heal:", 1, true) ~= nil
            or string.find(incomingLower, "taken:", 1, true) ~= nil
            or string.match(incomingFirstLine, "^%s*[Dd]amage%s+[^|]+%|%s*[%d,%.]+%s*[KkMmBb]?%s*DPS%s*$") ~= nil then
            return incomingPayload, TrimText(incomingSender);
        end
    end

    return nil;
end

local function ParseCompactDamageText(text)
    local raw, suffix = string.match(tostring(text or ""), "([%d,%.]+)%s*([KkMmBb]?)");
    if raw == nil then
        return nil;
    end

    local cleanRaw = string.gsub(raw, ",", "");
    local value = tonumber(cleanRaw);
    if value == nil then
        return nil;
    end

    suffix = string.lower(tostring(suffix or ""));
    if suffix == "k" then
        value = value * 1000;
    elseif suffix == "m" then
        value = value * 1000000;
    elseif suffix == "b" then
        value = value * 1000000000;
    end

    return value;
end

local function ParseDurationSeconds(text)
    text = TrimText(text);
    if text == "" then
        return nil;
    end

    local minutes, seconds = string.match(text, "^(%d+)%s*m%s*([%d%.]+)%s*s?$");
    if minutes ~= nil and seconds ~= nil then
        return (tonumber(minutes) or 0) * 60 + (tonumber(seconds) or 0);
    end

    local value = tonumber(string.match(text, "([%d%.]+)"));
    return value;
end

local function FormatKillTime(seconds)
    seconds = tonumber(seconds);
    if seconds == nil then
        return "-";
    end

    if seconds >= 60 then
        local minutes = math.floor(seconds / 60);
        local rest = seconds - (minutes * 60);
        return tostring(minutes) .. "m " .. string.format("%.1fs", rest);
    end

    return string.format("%.1fs", seconds);
end

local function FormatCompactAmount(value)
    value = tonumber(value);
    if value == nil then
        return "-";
    end

    local absValue = math.abs(value);
    local suffix = "";
    local divisor = 1;
    if absValue >= 1000000000 then
        suffix = "B";
        divisor = 1000000000;
    elseif absValue >= 1000000 then
        suffix = "M";
        divisor = 1000000;
    elseif absValue >= 1000 then
        suffix = "K";
        divisor = 1000;
    else
        return FormatNumber(value);
    end

    local text = string.format("%.2f", value / divisor);
    text = string.gsub(text, "%.00$", "");
    text = string.gsub(text, "(%.[0-9])0$", "%1");
    return text .. suffix;
end

local function NormalizeAnalysisSeparatorText(text)
    text = TrimText(StripLotroMarkup(text));
    text = string.gsub(text, "\226\128\162", "|");
    text = string.gsub(text, "%s*|%s*", "|");
    return text;
end

local function GetModernAnalysisMetric(amountLabel, rateLabel)
    local amountKey = string.lower(TrimText(amountLabel));
    local rateKey = string.lower(TrimText(rateLabel));
    if amountKey == "damage" and rateKey == "dps" then
        return "damage", "DPS", "Damage", "total";
    elseif (amountKey == "heal" or amountKey == "healing") and rateKey == "hps" then
        return "healing", "HPS", "Healing", "healing";
    elseif amountKey == "taken" and rateKey == "tps" then
        return "taken", "TPS", "Taken", "taken";
    end
    return nil, nil, nil, nil;
end

local function ParseModernAnalysisHeader(line)
    return TrimText(string.match(TrimText(line), "^[Aa]nalysis%s+for%s+(.+)%s*$"));
end

local function ParseModernAnalysisTotalLine(line)
    line = NormalizeAnalysisSeparatorText(line);
    local amountLabel, amountText, rateLabel, rateText, durationText = string.match(line, "^[Tt]otal%s+([%a%s]+):%s*([^|]+)|%s*([%a]+):%s*([^|]+)|%s*([^|]+)%s*$");
    if amountLabel == nil then
        return nil;
    end

    local metric, normalizedRateLabel, normalizedAmountLabel, mode = GetModernAnalysisMetric(amountLabel, rateLabel);
    if metric == nil then
        return nil;
    end

    local amountValue = ParseCompactDamageText(amountText);
    local rateValue = ParseCompactDamageText(rateText);
    if amountValue == nil or rateValue == nil then
        return nil;
    end

    return {
        metric = metric,
        mode = mode,
        rateLabel = normalizedRateLabel,
        amountLabel = normalizedAmountLabel,
        amountText = TrimText(amountText),
        amount = amountValue,
        rateText = TrimText(rateText),
        rate = rateValue,
        duration = TrimText(durationText),
        durationSeconds = ParseDurationSeconds(durationText)
    };
end

local function ParseModernAnalysisTargetLine(line, expectedRateLabel)
    line = NormalizeAnalysisSeparatorText(line);
    local targetName, amountText, rateLabel, rateText = string.match(line, "^%s*(.-):%s*([^|]+)|%s*([%a]+):%s*([^|]+)%s*$");
    if targetName == nil then
        return nil;
    end

    targetName = TrimText(targetName);
    if targetName == "" or string.find(string.lower(targetName), "^total%s+") ~= nil then
        return nil;
    end
    if string.lower(TrimText(rateLabel)) ~= string.lower(TrimText(expectedRateLabel)) then
        return nil;
    end

    return {
        name = targetName,
        amountText = TrimText(amountText),
        amount = ParseCompactDamageText(amountText),
        rateText = TrimText(rateText),
        rate = ParseCompactDamageText(rateText)
    };
end

local function LooksLikeModernCombatAnalysisHeaderPayload(payload)
    local character = ParseModernAnalysisHeader(payload);
    if character == "" then
        return false;
    end
    return true;
end

local function LooksLikeModernCombatAnalysisLine(payload)
    if ParseModernAnalysisTotalLine(payload) ~= nil then
        return true;
    end
    return ParseModernAnalysisTargetLine(payload, "DPS") ~= nil
        or ParseModernAnalysisTargetLine(payload, "HPS") ~= nil
        or ParseModernAnalysisTargetLine(payload, "TPS") ~= nil;
end

function ParseGraph.ParseModernCombatAnalysisPayload(payload)
    payload = TrimText(StripLotroMarkup(payload));
    if payload == "" then
        return nil;
    end

    payload = string.gsub(payload, "\r\n", "\n");
    payload = string.gsub(payload, "\r", "\n");
    local lines = {};
    for line in string.gmatch(payload .. "\n", "([^\n]*)\n") do
        line = TrimText(line);
        if line ~= "" then
            lines[#lines + 1] = line;
        end
    end

    local character = nil;
    local headerIndex = nil;
    for i = 1, #lines do
        character = ParseModernAnalysisHeader(lines[i]);
        if character ~= "" then
            headerIndex = i;
            break;
        end
    end
    if headerIndex == nil then
        return nil;
    end

    local total = nil;
    local totalIndex = nil;
    local encounterName = nil;
    for i = headerIndex + 1, #lines do
        total = ParseModernAnalysisTotalLine(lines[i]);
        if total ~= nil then
            totalIndex = i;
            break;
        end
        if encounterName == nil then
            local possibleEncounter = TrimText(lines[i]);
            if possibleEncounter ~= "" and ParseModernAnalysisHeader(possibleEncounter) == "" then
                encounterName = possibleEncounter;
            end
        end
    end
    if totalIndex == nil then
        return nil;
    end

    local targets = {};
    for i = totalIndex + 1, #lines do
        if string.lower(TrimText(lines[i])) == "healed by:" then
            break;
        end
        local target = ParseModernAnalysisTargetLine(lines[i], total.rateLabel);
        if target ~= nil and target.amount ~= nil then
            targets[#targets + 1] = target;
        end
    end

    local targetName = nil;
    local mode = total.mode;
    if total.metric == "damage" and #targets == 1 then
        targetName = targets[1].name;
        if targets[1].amount ~= nil and math.abs(targets[1].amount - total.amount) <= math.max(1000, total.amount * 0.01) then
            mode = "boss";
        end
    end

    local targetText = "";
    for i = 1, #targets do
        if targetText ~= "" then
            targetText = targetText .. " + ";
        end
        targetText = targetText .. tostring(targets[i].name or "");
    end

    return {
        source = "combatAnalysisModern",
        payload = payload,
        encounter = encounterName or (targetText ~= "" and targetText or "CombatAnalysis"),
        target = targetName,
        targets = targets,
        targetText = targetText,
        mode = mode,
        metric = total.metric,
        rateLabel = total.rateLabel,
        amountLabel = total.amountLabel,
        duration = total.duration,
        durationSeconds = total.durationSeconds,
        character = character,
        totalAmountText = total.amountText,
        totalAmount = total.amount,
        totalRate = total.rate,
        amountText = total.amountText,
        amount = total.amount,
        rate = total.rate,
        damageText = total.amountText,
        damage = total.amount,
        dps = total.rate
    };
end

function ParseGraph.ParseCombatAnalysisPayload(payload, preferredCharacter)
    payload = TrimText(StripLotroMarkup(payload));
    if payload == "" then
        return nil;
    end

    local modernData = ParseGraph.ParseModernCombatAnalysisPayload(payload);
    if modernData ~= nil then
        local preferredKey = LowerClean(preferredCharacter);
        if preferredKey ~= "" and LowerClean(modernData.character) ~= preferredKey then
            return nil;
        end
        return modernData;
    end

    local encounterPart, statsPart = string.match(payload, "^%s*(.-)%s*;%s*(.*)$");
    if encounterPart == nil then
        return nil;
    end

    local encounterText = TrimText(encounterPart);
    local durationText = nil;
    local beforeTime, timeText = string.match(encounterText, "^(.-)%s*%(([^%)]+)%)%s*$");
    if beforeTime ~= nil then
        encounterText = TrimText(beforeTime);
        durationText = TrimText(timeText);
    end

    local encounterName = encounterText;
    local targetName = nil;
    local left, right = string.match(encounterText, "^(.-)%s*>%s*(.-)$");
    if left ~= nil and right ~= nil then
        encounterName = TrimText(left);
        targetName = TrimText(right);
    end

    local currentCharacter = LowerClean(ParseGraph.GetCurrentCharacterName());
    local preferredKey = LowerClean(preferredCharacter);
    local statsText = tostring(statsPart or "");
    local fallbackData = nil;
    local currentData = nil;
    for characterName, amountLabel, amountText, rateLabel, rateText in string.gmatch(statsText .. "\n", "([^\n;]-)%s+%-%s+([%a%s]+):%s*([^;]+)%s*;%s*([%a]+):%s*([^;]+)%s*;") do
        local cleanCharacter = TrimText(characterName);
        local amountKey = string.lower(TrimText(amountLabel));
        local rateKey = string.lower(TrimText(rateLabel));
        local metric = nil;
        local mode = targetName ~= nil and "boss" or "total";

        if amountKey == "dmg" and rateKey == "dps" then
            metric = "damage";
        elseif amountKey == "heal" and rateKey == "hps" then
            metric = "healing";
            mode = "healing";
        elseif amountKey == "taken" and rateKey == "tps" then
            metric = "taken";
            mode = "taken";
        end

        if metric ~= nil then
            local rateValue = ParseCompactDamageText(rateText);
            if rateValue ~= nil then
                local cleanAmountText = TrimText(amountText);
                local amountValue = ParseCompactDamageText(cleanAmountText);
                local data = {
                    payload = payload,
                    encounter = encounterName,
                    target = targetName,
                    mode = mode,
                    metric = metric,
                    rateLabel = string.upper(TrimText(rateLabel)),
                    amountLabel = metric == "damage" and "Damage" or (metric == "healing" and "Healing" or "Taken"),
                    duration = durationText,
                    durationSeconds = ParseDurationSeconds(durationText),
                    character = cleanCharacter,
                    amountText = cleanAmountText,
                    amount = amountValue,
                    rate = rateValue,
                    damageText = cleanAmountText,
                    damage = amountValue,
                    dps = rateValue
                };
                local cleanKey = LowerClean(cleanCharacter);
                if preferredKey ~= "" then
                    if cleanKey == preferredKey then
                        return data;
                    end
                elseif cleanKey == currentCharacter then
                    return data;
                end
                if cleanKey == currentCharacter then
                    currentData = data;
                end
                if fallbackData == nil then
                    fallbackData = data;
                end
            end
        end
    end

    if preferredKey ~= "" then
        return nil;
    end
    return currentData or fallbackData;
end

function ParseGraph.ParsePrimeParsePayload(payload)
    payload = TrimText(StripLotroMarkup(payload));
    if payload == "" then
        return nil;
    end

    local firstLine = string.match(payload, "^([^\r\n]+)");
    if firstLine == nil then
        return nil;
    end

    local amountText, rateText = string.match(firstLine, "^%s*[Dd]amage%s+([^|]+)%|%s*([%d,%.]+%s*[KkMmBb]?)%s*DPS%s*$");
    if amountText == nil or rateText == nil then
        return nil;
    end

    amountText = TrimText(amountText);
    rateText = TrimText(rateText);
    local totalAmount = ParseCompactDamageText(amountText);
    local totalRate = ParseCompactDamageText(rateText);
    if totalAmount == nil or totalRate == nil then
        return nil;
    end

    local targets = {};
    local first = true;
    for line in string.gmatch(payload, "[^\r\n]+") do
        if first then
            first = false;
        else
            local targetName, targetAmountText = string.match(line, "^%s*(.-)%s+%-%s+([%d,%.]+%s*[KkMmBb]?)%s*$");
            if targetName ~= nil and targetAmountText ~= nil then
                local cleanTarget = TrimText(targetName);
                local cleanAmount = TrimText(targetAmountText);
                if cleanTarget ~= "" then
                    targets[#targets + 1] = {
                        name = cleanTarget,
                        amountText = cleanAmount,
                        amount = ParseCompactDamageText(cleanAmount)
                    };
                end
            end
        end
    end

    local targetName = nil;
    local mode = "total";
    local savedAmountText = amountText;
    local savedAmount = totalAmount;
    if #targets == 1 then
        targetName = targets[1].name;
        if targets[1].amount ~= nil and math.abs(targets[1].amount - totalAmount) <= math.max(1000, totalAmount * 0.01) then
            mode = "boss";
            savedAmountText = targets[1].amountText;
            savedAmount = targets[1].amount;
        end
    end

    local targetText = "";
    for i = 1, #targets do
        if targetText ~= "" then
            targetText = targetText .. " + ";
        end
        targetText = targetText .. tostring(targets[i].name or "");
    end

    return {
        source = "prime",
        payload = payload,
        encounter = targetText ~= "" and targetText or "Prime Parse",
        target = targetName,
        targets = targets,
        targetText = targetText,
        mode = mode,
        metric = "damage",
        rateLabel = "DPS",
        amountLabel = "Damage",
        duration = nil,
        durationSeconds = nil,
        character = ParseGraph.GetCurrentCharacterName(),
        totalAmountText = amountText,
        totalAmount = totalAmount,
        totalRate = totalRate,
        amountText = savedAmountText,
        amount = savedAmount,
        rate = totalRate,
        damageText = savedAmountText,
        damage = savedAmount,
        dps = totalRate
    };
end

local function AddBossCandidate(candidates, text)
    text = TrimText(text);
    if text == "" then
        return;
    end

    text = string.gsub(text, "^%(", "");
    text = string.gsub(text, "%)$", "");
    text = TrimText(text);
    if text == "" then
        return;
    end

    candidates[#candidates + 1] = text;
    if string.find(text, "+", 1, true) ~= nil then
        for part in string.gmatch(text, "([^+]+)") do
            part = TrimText(part);
            if part ~= "" then
                candidates[#candidates + 1] = part;
            end
        end
    end
end

function ParseGraph.ResetAutoInstanceBossDefeats(instanceKey, tierKey, bossIndex)
    ParseGraph.AutoInstanceDefeats = {
        instanceKey = instanceKey,
        tierKey = tierKey,
        bossIndex = tonumber(bossIndex) or 1,
        kills = {}
    };
end

local function AddBossDefeatRequirement(requirements, byKey, text, exact)
    text = TrimText(text);
    if text == "" or string.find(text, "+", 1, true) ~= nil then
        return;
    end

    text = string.gsub(text, "^%(", "");
    text = string.gsub(text, "%)$", "");
    text = TrimText(text);
    local count = tonumber(string.match(text, "%s+[xX](%d+)%s*$")) or 1;
    text = TrimText(string.gsub(text, "%s+[xX]%d+%s*$", ""));
    if text == "" then
        return;
    end

    local key = NormalizeBossMatchText(text);
    if key == "" then
        return;
    end

    if byKey[key] == nil then
        local item = {
            name = text,
            key = key,
            count = count,
            exact = exact == true
        };
        byKey[key] = item;
        requirements[#requirements + 1] = item;
    elseif count > (tonumber(byKey[key].count) or 1) then
        byKey[key].count = count;
        if exact == true then
            byKey[key].exact = true;
        end
    end
end

local function BossMatchKeys(left, right)
    left = tostring(left or "");
    right = tostring(right or "");
    if left == "" or right == "" then
        return false;
    end
    return left == right
        or string.find(left, right, 1, true) ~= nil
        or string.find(right, left, 1, true) ~= nil;
end

local function FindDefeatRequirementMatch(requirements, enemyKey)
    if type(requirements) ~= "table" then
        return nil;
    end
    enemyKey = tostring(enemyKey or "");
    for i = 1, #requirements do
        local req = requirements[i];
        if req ~= nil and req.key ~= nil and ((req.exact == true and enemyKey == req.key) or (req.exact ~= true and BossMatchKeys(enemyKey, req.key))) then
            return req;
        end
    end
    return nil;
end

function ParseGraph.GetBossDefeatRequirements(instanceKey, tierKey, bossIndex)
    local requirements = {};
    local byKey = {};
    bossIndex = tonumber(bossIndex) or 1;
    local instance = ParseGraph.GetInstanceDefinition(instanceKey);
    local boss = instance and instance.bosses and instance.bosses[bossIndex] or nil;

    if type(boss) == "table" then
        if type(boss.defeatRequirements) == "table" then
            for i = 1, #boss.defeatRequirements do
                AddBossDefeatRequirement(requirements, byKey, boss.defeatRequirements[i], true);
            end
        else
            AddBossDefeatRequirement(requirements, byKey, boss.defeatName, true);
        end
        if #requirements > 0 then
            return requirements;
        end
    end

    local breakdown = nil;
    if type(ParseGraph.InstanceBossHealthBreakdown) == "table"
        and type(ParseGraph.InstanceBossHealthBreakdown[instanceKey]) == "table"
        and type(ParseGraph.InstanceBossHealthBreakdown[instanceKey][tierKey]) == "table" then
        breakdown = ParseGraph.InstanceBossHealthBreakdown[instanceKey][tierKey][bossIndex];
    end

    if type(breakdown) == "table" then
        for i = 1, #breakdown do
            if type(breakdown[i]) == "table" then
                AddBossDefeatRequirement(requirements, byKey, breakdown[i].name);
            end
        end
    end

    if #requirements < 1 then
        local candidates = {};
        if boss ~= nil then
            AddBossCandidate(candidates, boss.name);
            AddBossCandidate(candidates, boss.detail);
        end
        for i = 1, #candidates do
            AddBossDefeatRequirement(requirements, byKey, candidates[i]);
        end
    end

    return requirements;
end

function ParseGraph.GetBossDamageTargetRequirements(instanceKey, tierKey, bossIndex, boss)
    local requirements = {};
    local byKey = {};
    bossIndex = tonumber(bossIndex) or 1;

    local breakdown = nil;
    if type(ParseGraph.InstanceBossHealthBreakdown) == "table"
        and type(ParseGraph.InstanceBossHealthBreakdown[instanceKey]) == "table"
        and type(ParseGraph.InstanceBossHealthBreakdown[instanceKey][tierKey]) == "table" then
        breakdown = ParseGraph.InstanceBossHealthBreakdown[instanceKey][tierKey][bossIndex];
    end

    if type(breakdown) == "table" then
        for i = 1, #breakdown do
            if type(breakdown[i]) == "table" then
                AddBossDefeatRequirement(requirements, byKey, breakdown[i].name);
            end
        end
    end

    if type(boss) == "table" then
        local damageTargets = boss.damageTargets;
        if type(boss.damageTargetsByTier) == "table" and type(boss.damageTargetsByTier[tierKey]) == "table" then
            damageTargets = boss.damageTargetsByTier[tierKey];
        end
        if type(damageTargets) == "table" then
            for i = 1, #damageTargets do
                AddBossDefeatRequirement(requirements, byKey, damageTargets[i], true);
            end
        end
    end

    if #requirements < 1 then
        local candidates = {};
        if boss ~= nil then
            AddBossCandidate(candidates, boss.name);
            AddBossCandidate(candidates, boss.detail);
        end
        for i = 1, #candidates do
            AddBossDefeatRequirement(requirements, byKey, candidates[i]);
        end
    end

    return requirements;
end

function ParseGraph.FindAnyInstanceBossForDefeat(enemyName)
    local enemyKey = NormalizeBossMatchText(enemyName);
    if enemyKey == "" then
        return nil, nil;
    end

    local orderedInstances = ParseGraph.GetOrderedInstanceDefinitions();
    local tiers = ParseGraph.InstanceTiers or {};
    for instanceIndex = 1, #orderedInstances do
        local instance = orderedInstances[instanceIndex];
        local bosses = instance and instance.bosses or nil;
        if instance ~= nil and type(bosses) == "table" then
            for bossIndex = 1, #bosses do
                for tierIndex = 1, #tiers do
                    local tier = tiers[tierIndex];
                    local requirements = ParseGraph.GetBossDefeatRequirements(instance.key, tier.key, bossIndex);
                    if FindDefeatRequirementMatch(requirements, enemyKey) ~= nil then
                        return instance, bossIndex;
                    end
                end
            end
        end
    end

    return nil, nil;
end

function ParseGraph.ApplyInstanceBossDefeatFallback(instance, bossIndex)
    if instance == nil then
        return;
    end

    bossIndex = tonumber(bossIndex) or 1;
    ParseGraph.ActiveInstanceKey = instance.key;
    ParseGraph.AutoInstanceBossIndex = bossIndex;
    ParseGraph.SelectedInstanceKey = instance.key;
    ParseGraph.SelectedInstanceBossIndex = bossIndex;
    ParseGraph.ManualInstanceTarget = nil;

    if ParseGraph.ActiveInstanceTierKey ~= nil and ParseGraph.ResetAutoInstanceBossDefeats ~= nil then
        ParseGraph.ResetAutoInstanceBossDefeats(instance.key, ParseGraph.ActiveInstanceTierKey, bossIndex);
    end
    if ParseGraph.CurrentView == "instances" then
        ParseGraph.DrawInstancesView();
    end
    ParseGraph.SetLauncherButtonState();
end

local function ExtractDefeatedEnemyName(text)
    local line = TrimText(StripLeadingChatTimestamp(StripLotroMarkup(text)));
    if line == "" then
        return nil;
    end
    if string.match(line, "^%s*[Yy]our%s+fellow,") ~= nil then
        return nil;
    end

    local enemy = string.match(line, "^%s*[Yy]our%s+mighty%s+blow%s+defeated%s+(.+)%.%s*$");
    if enemy == nil then
        enemy = string.match(line, "^%s*.-%s+defeated%s+(.+)%.%s*$");
    end
    if enemy == nil then
        enemy = string.match(line, "^%s*(.-)%s+has%s+been%s+defeated[%.!]%s*$");
    end
    if enemy == nil then
        local normalizedLine = NormalizeBossMatchText(line);
        if string.find(normalizedLine, "ratulko the bloody shouts", 1, true) ~= nil
            and string.find(normalizedLine, "i did not slay the king of rohan", 1, true) ~= nil then
            enemy = "Ratúlko the Bloody";
        end
    end
    if enemy == nil then
        return nil;
    end

    enemy = TrimText(enemy);
    if enemy == "" then
        return nil;
    end
    return enemy;
end

function ParseGraph.GetInstanceBossKillKey(instanceKey, tierKey, bossIndex)
    return tostring(instanceKey or "") .. "|" .. tostring(tierKey or "") .. "|" .. tostring(tonumber(bossIndex) or bossIndex or "");
end

function ParseGraph.MarkInstanceBossKill(instanceKey, tierKey, bossIndex)
    if instanceKey == nil or tierKey == nil or bossIndex == nil then
        return;
    end
    if type(ParseGraph.InstanceBossKillLines) ~= "table" then
        ParseGraph.InstanceBossKillLines = {};
    end
    ParseGraph.InstanceBossKillLines[ParseGraph.GetInstanceBossKillKey(instanceKey, tierKey, bossIndex)] = Turbine.Engine.GetGameTime();
    if ParseGraph.IncrementCurrentInstanceBossStat ~= nil then
        ParseGraph.IncrementCurrentInstanceBossStat(instanceKey, tierKey, bossIndex, "kills");
    end
end

function ParseGraph.GetInstanceBossKillLineAge(instanceKey, tierKey, bossIndex)
    if type(ParseGraph.InstanceBossKillLines) ~= "table" then
        return nil;
    end
    local at = tonumber(ParseGraph.InstanceBossKillLines[ParseGraph.GetInstanceBossKillKey(instanceKey, tierKey, bossIndex)]);
    if at == nil then
        return nil;
    end
    return (Turbine.Engine.GetGameTime() or 0) - at;
end

function ParseGraph.HasRecentInstanceBossKillLine(instanceKey, tierKey, bossIndex)
    local age = ParseGraph.GetInstanceBossKillLineAge(instanceKey, tierKey, bossIndex);
    return age ~= nil and age >= 0 and age <= 300;
end

function ParseGraph.HasInstanceBossKillLine(instanceKey, tierKey, bossIndex)
    if ParseGraph.OnlySaveInstanceParsesOnKill ~= true then
        return true;
    end
    return ParseGraph.HasRecentInstanceBossKillLine(instanceKey, tierKey, bossIndex);
end

function ParseGraph.ProcessInstanceDefeatText(text)
    local enemyName = ExtractDefeatedEnemyName(text);
    if enemyName == nil then
        return false;
    end

    local instanceKey = ParseGraph.ActiveInstanceKey;
    local tierKey = ParseGraph.ActiveInstanceTierKey;
    if instanceKey == nil or tierKey == nil then
        local detectedInstance, detectedBossIndex = ParseGraph.FindAnyInstanceBossForDefeat(enemyName);
        if detectedInstance ~= nil and detectedBossIndex ~= nil then
            ParseGraph.ApplyInstanceBossDefeatFallback(detectedInstance, detectedBossIndex);
            instanceKey = ParseGraph.ActiveInstanceKey;
            tierKey = ParseGraph.ActiveInstanceTierKey;
        end
        if instanceKey == nil or tierKey == nil then
            return detectedInstance ~= nil;
        end
    end

    local bossIndex = ParseGraph.GetAutoInstanceBossIndex(instanceKey, tierKey);
    local enemyKey = NormalizeBossMatchText(enemyName);
    local requirements = nil;
    local matched = nil;

    if bossIndex ~= nil then
        requirements = ParseGraph.GetBossDefeatRequirements(instanceKey, tierKey, bossIndex);
        matched = FindDefeatRequirementMatch(requirements, enemyKey);
    end

    if matched == nil and bossIndex ~= nil then
        local instance = ParseGraph.GetInstanceDefinition(instanceKey);
        if instance ~= nil and type(instance.bosses) == "table" then
            for candidateIndex = bossIndex + 1, #instance.bosses do
                local candidateRequirements = ParseGraph.GetBossDefeatRequirements(instanceKey, tierKey, candidateIndex);
                local candidateMatch = FindDefeatRequirementMatch(candidateRequirements, enemyKey);
                if candidateMatch ~= nil then
                    bossIndex = candidateIndex;
                    requirements = candidateRequirements;
                    matched = candidateMatch;
                    break;
                end
            end
        end
    end
    if matched == nil and bossIndex == nil then
        local instance = ParseGraph.GetInstanceDefinition(instanceKey);
        if instance ~= nil and type(instance.bosses) == "table" then
            for candidateIndex = 1, #instance.bosses do
                local candidateRequirements = ParseGraph.GetBossDefeatRequirements(instanceKey, tierKey, candidateIndex);
                local candidateMatch = FindDefeatRequirementMatch(candidateRequirements, enemyKey);
                if candidateMatch ~= nil then
                    bossIndex = candidateIndex;
                    requirements = candidateRequirements;
                    matched = candidateMatch;
                    break;
                end
            end
        end
    end
    if matched == nil then
        local detectedInstance, detectedBossIndex = ParseGraph.FindAnyInstanceBossForDefeat(enemyName);
        if detectedInstance ~= nil and detectedBossIndex ~= nil and detectedInstance.key ~= instanceKey then
            ParseGraph.ApplyInstanceBossDefeatFallback(detectedInstance, detectedBossIndex);
            instanceKey = detectedInstance.key;
            bossIndex = detectedBossIndex;
            requirements = ParseGraph.GetBossDefeatRequirements(instanceKey, tierKey, bossIndex);
            matched = FindDefeatRequirementMatch(requirements, enemyKey);
        end
    end
    if matched == nil then
        return false;
    end

    local state = ParseGraph.AutoInstanceDefeats;
    if type(state) ~= "table"
        or state.instanceKey ~= instanceKey
        or state.tierKey ~= tierKey
        or tonumber(state.bossIndex) ~= tonumber(bossIndex) then
        ParseGraph.ResetAutoInstanceBossDefeats(instanceKey, tierKey, bossIndex);
        state = ParseGraph.AutoInstanceDefeats;
    end
    if type(state.kills) ~= "table" then
        state.kills = {};
    end

    local killCount = (tonumber(state.kills[matched.key]) or 0) + 1;
    state.kills[matched.key] = math.min(killCount, tonumber(matched.count) or 1);

    for i = 1, #requirements do
        local req = requirements[i];
        if (tonumber(state.kills[req.key]) or 0) < (tonumber(req.count) or 1) then
            return true;
        end
    end

    ParseGraph.MarkInstanceBossKill(instanceKey, tierKey, bossIndex);
    ParseGraph.AdvanceAutoInstanceBossDetection(instanceKey, tierKey, bossIndex);
    ParseGraph.EndActiveInstanceEncounter(instanceKey, tierKey, bossIndex);
    return true;
end

function ParseGraph.ExtractInstanceWipeSignal(text)
    local line = TrimText(StripLeadingChatTimestamp(StripLotroMarkup(text)));
    if line == "" then
        return nil, nil;
    end

    local enemyName = string.match(line, "^%s*(.-)%s+incapacitated%s+you%.%s*$");
    if enemyName ~= nil then
        enemyName = TrimText(enemyName);
        if enemyName ~= "" then
            return "incapacitated", enemyName;
        end
    end

    if string.match(line, "^%s*[Yy]ou%s+succumb%s+to%s+your%s+wounds%.%s*$") ~= nil then
        return "succumb", nil;
    end

    if string.match(line, "^%s*[Yy]our%s+fellow,%s+.-%s+has%s+been%s+defeated!%s*$") ~= nil then
        return "fellow", nil;
    end

    return nil, nil;
end

function ParseGraph.RememberInstanceWipeTargetFromEnemy(enemyName)
    if enemyName == nil then
        return false;
    end

    local instance, bossIndex = ParseGraph.FindAnyInstanceBossForDefeat(enemyName);
    if instance == nil or bossIndex == nil then
        return false;
    end

    local tierKey = ParseGraph.ActiveInstanceTierKey or ParseGraph.SelectedInstanceTierKey;
    if tierKey == nil then
        return false;
    end

    ParseGraph.PendingInstanceWipeTarget = {
        instanceKey = instance.key,
        tierKey = tierKey,
        bossIndex = tonumber(bossIndex) or 1,
        at = Turbine.Engine.GetGameTime() or 0
    };
    return true;
end

function ParseGraph.ResolveInstanceWipeTarget()
    local now = Turbine.Engine.GetGameTime() or 0;
    local activeInstanceKey, activeTierKey, activeBossIndex = ParseGraph.GetActiveInstanceEncounterTarget();
    if activeInstanceKey ~= nil and activeTierKey ~= nil and activeBossIndex ~= nil then
        return activeInstanceKey, activeTierKey, activeBossIndex;
    end

    local pending = ParseGraph.PendingInstanceWipeTarget;
    if type(pending) == "table" and pending.instanceKey ~= nil and pending.tierKey ~= nil and pending.bossIndex ~= nil then
        local age = now - (tonumber(pending.at) or now);
        if age >= 0 and age <= 300 then
            return pending.instanceKey, pending.tierKey, tonumber(pending.bossIndex) or 1;
        end
    end

    local instanceKey = ParseGraph.ActiveInstanceKey;
    local tierKey = ParseGraph.ActiveInstanceTierKey;
    if instanceKey == nil or tierKey == nil then
        return nil, nil, nil;
    end

    local bossIndex = ParseGraph.GetAutoInstanceBossIndex(instanceKey, tierKey);
    if bossIndex == nil then
        return nil, nil, nil;
    end

    return instanceKey, tierKey, bossIndex;
end

function ParseGraph.ProcessInstanceWipeText(text)
    local signal, enemyName = ParseGraph.ExtractInstanceWipeSignal(text);
    if signal == nil then
        return false;
    end

    if signal == "incapacitated" then
        ParseGraph.RememberInstanceWipeTargetFromEnemy(enemyName);
        return false;
    end

    if signal == "fellow" then
        local activeInstanceKey, activeTierKey, activeBossIndex = ParseGraph.GetActiveInstanceEncounterTarget();
        if activeInstanceKey == nil or activeTierKey == nil or activeBossIndex == nil then
            return false;
        end
    end

    if signal ~= "succumb" and signal ~= "fellow" then
        return false;
    end

    local instanceKey, tierKey, bossIndex = ParseGraph.ResolveInstanceWipeTarget();
    ParseGraph.PendingInstanceWipeTarget = nil;
    if instanceKey == nil or tierKey == nil or bossIndex == nil then
        return false;
    end

    if ParseGraph.HasRecentInstanceBossKillLine(instanceKey, tierKey, bossIndex) == true then
        return false;
    end

    local currentKey = ParseGraph.GetCurrentCharacterKey();
    local entry = ParseGraph.EnsureAccountCharacter(currentKey, ParseGraph.GetCurrentCharacterName());
    local stats = ParseGraph.GetInstanceBossStatsFromInstances(entry.instances or {}, instanceKey, tierKey, bossIndex);
    local now = Turbine.Engine.GetGameTime() or 0;
    if stats.lastWipeAt ~= nil and now - stats.lastWipeAt >= 0 and now - stats.lastWipeAt <= 30 then
        if ParseGraph.ResetAutoInstanceBossDefeats ~= nil then
            ParseGraph.ResetAutoInstanceBossDefeats(instanceKey, tierKey, bossIndex);
        end
        ParseGraph.EndActiveInstanceEncounter(instanceKey, tierKey, bossIndex);
        return false;
    end

    local recorded = ParseGraph.IncrementCurrentInstanceBossStat(instanceKey, tierKey, bossIndex, "wipes");
    if ParseGraph.ResetAutoInstanceBossDefeats ~= nil then
        ParseGraph.ResetAutoInstanceBossDefeats(instanceKey, tierKey, bossIndex);
    end
    ParseGraph.EndActiveInstanceEncounter(instanceKey, tierKey, bossIndex);
    if recorded == true and ParseGraph.CurrentView == "instances" and ParseGraph.DrawInstancesView ~= nil then
        ParseGraph.DrawInstancesView();
    end
    return recorded == true;
end
function ParseGraph.InstanceBossMatchesCombatAnalysis(boss, combatData)
    if boss == nil or combatData == nil then
        return false;
    end

    local matchTexts = {};
    local function addMatchText(text)
        text = TrimText(text);
        if text ~= "" then
            matchTexts[#matchTexts + 1] = text;
        end
    end

    addMatchText(combatData.target);
    addMatchText(combatData.targetText);
    addMatchText(combatData.encounter);
    if type(combatData.targets) == "table" then
        local parts = {};
        for i = 1, #combatData.targets do
            if combatData.targets[i] ~= nil and TrimText(combatData.targets[i].name) ~= "" then
                parts[#parts + 1] = tostring(combatData.targets[i].name);
            end
        end
        addMatchText(table.concat(parts, " + "));
    end

    local candidates = {};
    AddBossCandidate(candidates, boss.name);
    AddBossCandidate(candidates, boss.detail);

    for textIndex = 1, #matchTexts do
        local haystack = NormalizeBossMatchText(matchTexts[textIndex]);
        if haystack ~= "" then
            for i = 1, #candidates do
                local needle = NormalizeBossMatchText(candidates[i]);
                if string.len(needle) >= 4 and BossMatchKeys(haystack, needle) then
                    return true;
                end
            end
        end
    end

    return false;
end

function ParseGraph.GetInstanceNonBossCombatTarget(instance, combatData)
    if type(instance) ~= "table" or type(instance.nonBossTargets) ~= "table" or type(combatData) ~= "table" then
        return nil;
    end

    local matchTexts = {};
    local function AddMatchText(text)
        text = TrimText(text);
        if text ~= "" then
            matchTexts[#matchTexts + 1] = text;
        end
    end
    AddMatchText(combatData.target);
    AddMatchText(combatData.targetText);
    AddMatchText(combatData.encounter);
    if type(combatData.targets) == "table" then
        for i = 1, #combatData.targets do
            AddMatchText(combatData.targets[i] and combatData.targets[i].name or nil);
        end
    end

    for targetIndex = 1, #instance.nonBossTargets do
        local target = instance.nonBossTargets[targetIndex];
        local targetName = type(target) == "table" and target.name or target;
        local nonBossKey = NormalizeBossMatchText(targetName);
        if nonBossKey ~= "" then
            for textIndex = 1, #matchTexts do
                local matchKey = NormalizeBossMatchText(matchTexts[textIndex]);
                if matchKey ~= "" and BossMatchKeys(matchKey, nonBossKey) then
                    if type(target) == "table" then
                        return target;
                    end
                    return { name = tostring(targetName or "") };
                end
            end
        end
    end

    return nil;
end

function ParseGraph.InstanceNonBossMatchesCombatAnalysis(instance, combatData)
    return ParseGraph.GetInstanceNonBossCombatTarget(instance, combatData) ~= nil;
end

function ParseGraph.FindAnyInstanceNonBossForCombatAnalysis(combatData)
    local orderedInstances = ParseGraph.GetOrderedInstanceDefinitions();
    for i = 1, #orderedInstances do
        local instance = orderedInstances[i];
        local target = ParseGraph.GetInstanceNonBossCombatTarget(instance, combatData);
        if target ~= nil then
            return instance, target;
        end
    end

    return nil, nil;
end

function ParseGraph.ResolveInstanceNonBossHealthTier(instanceKey, target, preferredTierKey)
    if type(target) ~= "table" or type(target.healthByTier) ~= "table" then
        return nil;
    end

    local candidates = { preferredTierKey };
    if ParseGraph.ActiveInstanceKey == instanceKey then
        candidates[#candidates + 1] = ParseGraph.ActiveInstanceTierKey;
    end
    if type(ParseGraph.ManualInstanceTarget) == "table" and ParseGraph.ManualInstanceTarget.instanceKey == instanceKey then
        candidates[#candidates + 1] = ParseGraph.ManualInstanceTarget.tierKey;
    end
    local pageTarget = ParseGraph.GetTemporaryInstanceTarget();
    if type(pageTarget) == "table" and pageTarget.instanceKey == instanceKey then
        candidates[#candidates + 1] = pageTarget.tierKey;
    end
    if ParseGraph.SelectedInstanceKey == instanceKey then
        candidates[#candidates + 1] = ParseGraph.SelectedInstanceTierKey;
    end

    for i = 1, #candidates do
        local tierKey = candidates[i];
        if tierKey ~= nil and (tonumber(target.healthByTier[tierKey]) or 0) > 0 then
            return tierKey;
        end
    end

    return nil;
end

function ParseGraph.FindInstanceBossForCombatAnalysis(instance, combatData)
    if instance == nil or type(instance.bosses) ~= "table" then
        return nil;
    end

    for i = 1, #instance.bosses do
        if ParseGraph.InstanceBossMatchesCombatAnalysis(instance.bosses[i], combatData) then
            return i;
        end
    end

    return nil;
end

function ParseGraph.FindAnyInstanceBossForCombatAnalysis(combatData)
    local orderedInstances = ParseGraph.GetOrderedInstanceDefinitions();
    for i = 1, #orderedInstances do
        local instance = orderedInstances[i];
        local bossIndex = ParseGraph.FindInstanceBossForCombatAnalysis(instance, combatData);
        if bossIndex ~= nil then
            return instance, bossIndex;
        end
    end

    return nil, nil;
end

function ParseGraph.GetSelectedBossForCombatAnalysis(instanceKey, tierKey, combatData)
    if combatData == nil then
        return nil;
    end

    if ParseGraph.CurrentView ~= "instances" or ParseGraph.InstanceViewMode ~= "boss" then
        return nil;
    end

    if ParseGraph.SelectedInstanceKey ~= instanceKey or ParseGraph.SelectedInstanceTierKey ~= tierKey then
        return nil;
    end

    local index = tonumber(ParseGraph.SelectedInstanceBossIndex);
    if index == nil then
        return nil;
    end

    local instance = ParseGraph.GetInstanceDefinition(instanceKey);
    if instance == nil or type(instance.bosses) ~= "table" or instance.bosses[index] == nil then
        return nil;
    end

    return index;
end

function ParseGraph.GetTemporaryInstanceTarget()
    if ParseGraph.CurrentView ~= "instances" or ParseGraph.InstanceViewMode ~= "boss" then
        return nil;
    end
    if type(ParseGraph.TemporaryInstanceTarget) ~= "table" then
        return nil;
    end
    return ParseGraph.TemporaryInstanceTarget;
end

function ParseGraph.ClearTemporaryInstanceTarget()
    ParseGraph.TemporaryInstanceTarget = nil;
end

function ParseGraph.GetAutoInstanceBossIndex(instanceKey, tierKey)
    if ParseGraph.ActiveInstanceKey ~= instanceKey or ParseGraph.ActiveInstanceTierKey ~= tierKey then
        return nil;
    end
    local instance = ParseGraph.GetInstanceDefinition(instanceKey);
    if instance == nil or type(instance.bosses) ~= "table" then
        return nil;
    end
    local index = tonumber(ParseGraph.AutoInstanceBossIndex);
    if index == nil then
        return nil;
    end
    index = math.max(1, math.min(#instance.bosses, index));
    return index;
end

function ParseGraph.AdvanceAutoInstanceBossDetection(instanceKey, tierKey, bossIndex)
    local instance = ParseGraph.GetInstanceDefinition(instanceKey);
    if instance == nil or type(instance.bosses) ~= "table" then
        return;
    end

    bossIndex = tonumber(bossIndex) or 1;
    local completedIndex = math.max(1, math.min(#instance.bosses, bossIndex));
    if ParseGraph.ActiveInstanceKey == instanceKey and ParseGraph.ActiveInstanceTierKey == tierKey then
        ParseGraph.AutoInstanceBossIndex = completedIndex;
        ParseGraph.ResetAutoInstanceBossDefeats(instanceKey, tierKey, completedIndex);
    end
    if type(ParseGraph.ManualInstanceTarget) == "table"
        and ParseGraph.ManualInstanceTarget.instanceKey == instanceKey
        and ParseGraph.ManualInstanceTarget.tierKey == tierKey then
        ParseGraph.ManualInstanceTarget.bossIndex = completedIndex;
    end
end

local function IsInstanceBossMultiTarget(boss)
    if type(boss) ~= "table" then
        return false;
    end
    if boss.detail ~= nil and TrimText(boss.detail) ~= "" then
        return true;
    end
    return string.find(tostring(boss.name or ""), "+", 1, true) ~= nil;
end

local function IsInstanceBossTotalDamageExpected(instanceKey, tierKey, bossIndex, boss)
    if IsInstanceBossMultiTarget(boss) then
        return true;
    end

    local breakdown = ParseGraph.GetInstanceBossHealthBreakdown(instanceKey, tierKey, bossIndex);
    return type(breakdown) == "table" and #breakdown > 1;
end

local function PrimeTargetMatchesRequirement(targetName, requirement, exactOnly)
    if targetName == nil or requirement == nil or requirement.key == nil then
        return false;
    end

    local targetKey = NormalizeBossMatchText(targetName);
    local reqKey = NormalizeBossMatchText(requirement.key);
    if targetKey == "" or reqKey == "" then
        return false;
    end

    if exactOnly == true then
        return targetKey == reqKey;
    end

    return BossMatchKeys(targetKey, reqKey);
end

local function GetPrimeBossTargetAmount(combatData, instanceKey, tierKey, bossIndex, boss, preferExactMatch)
    if type(combatData) ~= "table" or type(combatData.targets) ~= "table" then
        return nil, {};
    end

    local requirements = ParseGraph.GetBossDamageTargetRequirements(instanceKey, tierKey, bossIndex, boss);
    if type(requirements) ~= "table" or #requirements < 1 then
        requirements = {};
        local byKey = {};
        local candidates = {};
        AddBossCandidate(candidates, boss and boss.name);
        AddBossCandidate(candidates, boss and boss.detail);
        for i = 1, #candidates do
            AddBossDefeatRequirement(requirements, byKey, candidates[i]);
        end
    end

    local amount = 0;
    local matchedNames = {};
    local exactAmount = 0;
    local exactMatchedNames = {};
    local looseAmount = 0;
    local looseMatchedNames = {};
    for i = 1, #combatData.targets do
        local target = combatData.targets[i];
        if type(target) == "table" and target.name ~= nil then
            local exactMatched = false;
            local looseMatched = false;
            for j = 1, #requirements do
                if PrimeTargetMatchesRequirement(target.name, requirements[j], true) then
                    exactMatched = true;
                    break;
                elseif PrimeTargetMatchesRequirement(target.name, requirements[j]) then
                    looseMatched = true;
                end
            end
            if target.amount ~= nil then
                if exactMatched then
                    exactAmount = exactAmount + (tonumber(target.amount) or 0);
                    exactMatchedNames[#exactMatchedNames + 1] = tostring(target.name);
                elseif looseMatched then
                    looseAmount = looseAmount + (tonumber(target.amount) or 0);
                    looseMatchedNames[#looseMatchedNames + 1] = tostring(target.name);
                end
                if exactMatched or looseMatched then
                    amount = amount + (tonumber(target.amount) or 0);
                    matchedNames[#matchedNames + 1] = tostring(target.name);
                end
            end
        end
    end

    if preferExactMatch == true then
        if exactAmount > 0 then
            return exactAmount, exactMatchedNames;
        end
        if looseAmount > 0 then
            return looseAmount, looseMatchedNames;
        end
    end

    if amount <= 0 then
        return nil, matchedNames;
    end
    return amount, matchedNames;
end
local function ApplyDamageTargetData(combatData, instanceKey, tierKey, bossIndex, boss, expectedMode)
    if type(combatData) ~= "table" or tostring(combatData.metric or "") ~= "damage" or type(combatData.targets) ~= "table" then
        return true;
    end

    local amount, matchedNames = GetPrimeBossTargetAmount(combatData, instanceKey, tierKey, bossIndex, boss, expectedMode == "boss");
    if amount == nil then
        return false;
    end

    local totalAmount = tonumber(combatData.totalAmount or combatData.amount);
    local totalRate = tonumber(combatData.totalRate or combatData.rate or combatData.dps);
    local rate = totalRate;
    if totalAmount ~= nil and totalAmount > 0 and totalRate ~= nil then
        rate = totalRate * (amount / totalAmount);
    end

    local targetText = table.concat(matchedNames, " + ");
    combatData.mode = expectedMode == "boss" and "boss" or "total";
    combatData.target = #matchedNames == 1 and matchedNames[1] or nil;
    combatData.targetText = targetText;
    combatData.amountText = FormatCompactAmount(amount);
    combatData.damageText = combatData.amountText;
    combatData.amount = amount;
    combatData.damage = amount;
    combatData.rate = rate;
    combatData.dps = rate;
    return true;
end

function ParseGraph.ResolveBossHealthPercentTarget(combatData)
    local tempTarget = ParseGraph.ManualInstanceTarget;
    local pageTarget = ParseGraph.GetTemporaryInstanceTarget();
    if tempTarget == nil then
        tempTarget = pageTarget;
    end

    local nonBossInstance, nonBossTarget = ParseGraph.FindAnyInstanceNonBossForCombatAnalysis(combatData);
    if nonBossInstance ~= nil and nonBossTarget ~= nil then
        local preferredTierKey = nil;
        if type(tempTarget) == "table" and tempTarget.instanceKey == nonBossInstance.key then
            preferredTierKey = tempTarget.tierKey;
        end
        local nonBossTierKey = ParseGraph.ResolveInstanceNonBossHealthTier(nonBossInstance.key, nonBossTarget, preferredTierKey);
        local nonBossHealth = nonBossTierKey ~= nil and tonumber(nonBossTarget.healthByTier[nonBossTierKey]) or nil;
        if nonBossHealth ~= nil and nonBossHealth > 0 then
            nonBossTarget.isNonBoss = true;
            return nonBossInstance.key, nonBossTierKey, 0, nonBossTarget;
        end
    end

    local fallbackBossIndex = nil;
    local instanceKey = ParseGraph.ActiveInstanceKey;
    local tierKey = ParseGraph.ActiveInstanceTierKey;
    if tempTarget ~= nil then
        instanceKey = tempTarget.instanceKey;
        tierKey = tempTarget.tierKey;
        fallbackBossIndex = tonumber(tempTarget.bossIndex);
    end

    local globalInstance = nil;
    local globalBossIndex = nil;
    local globalNonBossTarget = nil;
    if tempTarget == nil then
        globalInstance, globalBossIndex = ParseGraph.FindAnyInstanceBossForCombatAnalysis(combatData);
        if globalInstance == nil then
            globalInstance, globalNonBossTarget = ParseGraph.FindAnyInstanceNonBossForCombatAnalysis(combatData);
            if globalInstance ~= nil and globalNonBossTarget ~= nil then
                tierKey = ParseGraph.ResolveInstanceNonBossHealthTier(globalInstance.key, globalNonBossTarget, tierKey);
            end
        end
        if globalInstance ~= nil then
            instanceKey = globalInstance.key;
        end
    end

    if instanceKey == nil then
        return nil, nil, nil, nil;
    end

    local instance = globalInstance or ParseGraph.GetInstanceDefinition(instanceKey);
    if instance == nil or instance.key ~= instanceKey then
        return nil, nil, nil, nil;
    end

    local bossIndex = globalBossIndex or ParseGraph.FindInstanceBossForCombatAnalysis(instance, combatData);
    if bossIndex == nil then
        local nonBossTarget = ParseGraph.GetInstanceNonBossCombatTarget(instance, combatData);
        local nonBossHealth = nonBossTarget and nonBossTarget.healthByTier and tonumber(nonBossTarget.healthByTier[tierKey]) or nil;
        if nonBossTarget ~= nil and nonBossHealth ~= nil and nonBossHealth > 0 then
            nonBossTarget.isNonBoss = true;
            return instanceKey, tierKey, 0, nonBossTarget;
        elseif nonBossTarget ~= nil then
            return nil, nil, nil, nil;
        end
    end
    if bossIndex == nil and fallbackBossIndex ~= nil then
        bossIndex = fallbackBossIndex;
    end
    if bossIndex == nil then
        bossIndex = ParseGraph.GetSelectedBossForCombatAnalysis(instanceKey, tierKey, combatData);
    end
    if bossIndex == nil then
        bossIndex = ParseGraph.GetAutoInstanceBossIndex(instanceKey, tierKey);
    end
    if bossIndex == nil then
        return nil, nil, nil, nil;
    end

    local boss = instance.bosses and instance.bosses[bossIndex] or {};
    return instanceKey, tierKey, bossIndex, boss;
end

function ParseGraph.GetBossHealthPercentBreakdownTarget(combatData, instanceKey, tierKey, bossIndex)
    if type(combatData) ~= "table" or tostring(combatData.mode or "") ~= "boss" then
        return nil, nil, nil;
    end

    local targetName = TrimText(combatData.target);
    if targetName == "" then
        return nil, nil, nil;
    end

    local breakdown = ParseGraph.GetInstanceBossHealthBreakdown(instanceKey, tierKey, bossIndex);
    if type(breakdown) ~= "table" or #breakdown < 2 then
        return nil, nil, nil;
    end

    local targetKey = NormalizeBossMatchText(targetName);
    if targetKey == "" then
        return nil, nil, nil;
    end

    for i = 1, #breakdown do
        local row = breakdown[i];
        if type(row) == "table" and row.name ~= nil then
            local rowKey = NormalizeBossMatchText(row.name);
            if BossMatchKeys(targetKey, rowKey) then
                local amount = tonumber(combatData.amount or combatData.damage);
                local health = tonumber(row.health);
                if amount ~= nil and amount > 0 and health ~= nil and health > 0 then
                    return amount, health, tostring(row.name);
                end
            end
        end
    end

    return nil, nil, nil;
end

function ParseGraph.GetBossHealthPercentAmount(combatData, instanceKey, tierKey, bossIndex, boss)
    if type(combatData) ~= "table" or tostring(combatData.metric or "") ~= "damage" then
        return nil;
    end

    combatData.bossPercentHealthOverride = nil;
    combatData.bossPercentTargetName = nil;

    if type(boss) == "table" and boss.isNonBoss == true then
        local nonBossHealth = type(boss.healthByTier) == "table" and tonumber(boss.healthByTier[tierKey]) or nil;
        if nonBossHealth == nil or nonBossHealth <= 0 then
            return nil;
        end
        combatData.bossPercentHealthOverride = nonBossHealth;
        combatData.bossPercentTargetName = tostring(boss.name or combatData.target or "");
    end

    local expectedMode = IsInstanceBossTotalDamageExpected(instanceKey, tierKey, bossIndex, boss) and "total" or "boss";
    if type(combatData.targets) == "table" then
        local targetAmount = GetPrimeBossTargetAmount(combatData, instanceKey, tierKey, bossIndex, boss, expectedMode == "boss");
        if targetAmount ~= nil then
            return targetAmount;
        end
    end

    local breakdownAmount, breakdownHealth, breakdownName = ParseGraph.GetBossHealthPercentBreakdownTarget(combatData, instanceKey, tierKey, bossIndex);
    if breakdownAmount ~= nil then
        combatData.bossPercentHealthOverride = breakdownHealth;
        combatData.bossPercentTargetName = breakdownName;
        return breakdownAmount;
    end

    if combatData.mode == expectedMode then
        return tonumber(combatData.amount or combatData.damage);
    end

    return nil;
end

function ParseGraph.BossHealthPercentMessageWasRecent(key)
    key = tostring(key or "");
    if key == "" then
        return false;
    end

    if type(ParseGraph.RecentBossHealthPercentMessages) ~= "table" then
        ParseGraph.RecentBossHealthPercentMessages = {};
    end

    local now = Turbine.Engine.GetGameTime();
    local recentAt = tonumber(ParseGraph.RecentBossHealthPercentMessages[key]);
    ParseGraph.RecentBossHealthPercentMessages[key] = now;
    if recentAt ~= nil and (now - recentAt) < 15 then
        return true;
    end

    return false;
end

function ParseGraph.PrintBossHealthPercentMessage(characterName, percentText, isCombined)
    local character = TrimText(characterName);
    if character == "" then
        character = "Someone";
    end
    local combinedText = "";
    if isCombined == true then
        combinedText = " (Combined)";
    end
    local message = ChatColor("FFB21A", "ParseGraph:")
        .. " " .. ChatColor("3DFF55", character)
        .. ChatColor("FFFFFF", " did ")
        .. ChatColor("3DFF55", tostring(percentText or "-"))
        .. ChatColor("FFFFFF", combinedText .. " damage");
    ParseGraph.PrintDelayedShellLine(message, ParseGraph.InstanceMessageDelay);
end

local function FormatScoreboardPercent(value)
    value = tonumber(value) or 0;
    local rounded = math.floor((value * 10) + 0.5) / 10;
    return string.format("%.1f%%", rounded);
end

function ParseGraph.GetBossHealthPercentCombineScope(combatData)
    if type(combatData) ~= "table" then
        return "unknown";
    end

    local mode = tostring(combatData.mode or "unknown");
    local targetName = TrimText(combatData.bossPercentTargetName or combatData.target or combatData.targetText or "");
    local healthOverride = tonumber(combatData.bossPercentHealthOverride);
    if healthOverride ~= nil and healthOverride > 0 then
        return "breakdown|" .. mode .. "|" .. LowerClean(targetName) .. "|" .. tostring(Round(healthOverride));
    end
    if mode == "boss" then
        return "boss|" .. LowerClean(targetName);
    end
    if mode == "total" then
        return "total";
    end
    return mode;
end

function ParseGraph.GetBossHealthPercentDisplay(characterName, amount, percentValue, instanceKey, tierKey, bossIndex, duplicateKey, combineScope)
    amount = tonumber(amount) or 0;
    percentValue = tonumber(percentValue) or 0;
    local character = TrimText(characterName);
    if character == "" then
        character = "Someone";
    end

    if type(ParseGraph.RecentBossHealthPercentCombines) ~= "table" then
        ParseGraph.RecentBossHealthPercentCombines = {};
    end

    local now = Turbine.Engine.GetGameTime();
    local window = tonumber(ParseGraph.BossHealthPercentCombineWindowSeconds) or 20;
    for key, recent in pairs(ParseGraph.RecentBossHealthPercentCombines) do
        local recentAt = type(recent) == "table" and tonumber(recent.time) or nil;
        if recentAt == nil or (now - recentAt) > window then
            ParseGraph.RecentBossHealthPercentCombines[key] = nil;
        end
    end

    local key = LowerClean(character)
        .. "|" .. tostring(instanceKey or "")
        .. "|" .. tostring(tierKey or "")
        .. "|" .. tostring(bossIndex or "")
        .. "|" .. tostring(combineScope or "unknown");
    local recent = ParseGraph.RecentBossHealthPercentCombines[key];
    local combinedPercent = percentValue;
    local combinedAmount = amount;
    local isCombined = false;

    if type(recent) == "table"
        and tonumber(recent.time) ~= nil
        and (now - tonumber(recent.time)) <= window
        and tostring(recent.duplicateKey or "") ~= tostring(duplicateKey or "") then
        combinedPercent = (tonumber(recent.percentTotal) or 0) + percentValue;
        combinedAmount = (tonumber(recent.amountTotal) or 0) + amount;
        isCombined = true;
    end

    ParseGraph.RecentBossHealthPercentCombines[key] = {
        time = now,
        amountTotal = combinedAmount,
        percentTotal = combinedPercent,
        duplicateKey = duplicateKey
    };

    return FormatScoreboardPercent(combinedPercent), isCombined;
end

function ParseGraph.StopScoreboardRecapTimer()
    if ParseGraph.ScoreboardRecapTimer ~= nil then
        ParseGraph.ScoreboardRecapTimer:SetWantsUpdates(false);
    end
end

function ParseGraph.EnsureScoreboardRecapTimer()
    if ParseGraph.ScoreboardRecapTimer == nil then
        ParseGraph.ScoreboardRecapTimer = Turbine.UI.Control();
        ParseGraph.ScoreboardRecapTimer:SetSize(1, 1);
        ParseGraph.ScoreboardRecapTimer:SetMouseVisible(false);
        ParseGraph.ScoreboardRecapTimer.Update = function()
            if ParseGraph.ScoreboardRecapDue == nil then
                ParseGraph.StopScoreboardRecapTimer();
                return;
            end
            if Turbine.Engine.GetGameTime() >= (tonumber(ParseGraph.ScoreboardRecapDue) or 0) then
                ParseGraph.ScoreboardRecapDue = nil;
                ParseGraph.StopScoreboardRecapTimer();
                ParseGraph.PrintScoreboardRecap();
            end
        end
    end

    if ParseGraph.RootPanel ~= nil then
        ParseGraph.ScoreboardRecapTimer:SetParent(ParseGraph.RootPanel);
        ParseGraph.ScoreboardRecapTimer:SetPosition(0, 0);
    end
    ParseGraph.ScoreboardRecapTimer:SetWantsUpdates(true);
end

function ParseGraph.ScheduleScoreboardRecap()
    ParseGraph.ScoreboardRecapDue = Turbine.Engine.GetGameTime() + (tonumber(ParseGraph.ScoreboardRecapWindowSeconds) or 60);
    ParseGraph.EnsureScoreboardRecapTimer();
end

function ParseGraph.QueueScoreboardRecapEntry(characterName, amount, percentValue, instanceKey, tierKey, bossIndex)
    return;
end

function ParseGraph.PrintScoreboardRecap()
    ParseGraph.ScoreboardRecapEntries = {};
    ParseGraph.ScoreboardRecapKey = nil;
    return;
end
function ParseGraph.MaybePrintBossHealthPercentMessage(combatData, instanceKey, tierKey, bossIndex, boss)
    if type(combatData) ~= "table" or tostring(combatData.metric or "") ~= "damage" then
        return false;
    end

    if instanceKey == nil or bossIndex == nil then
        local resolvedInstanceKey, resolvedTierKey, resolvedBossIndex, resolvedBoss = ParseGraph.ResolveBossHealthPercentTarget(combatData);
        instanceKey = instanceKey or resolvedInstanceKey;
        tierKey = tierKey or resolvedTierKey;
        bossIndex = bossIndex or resolvedBossIndex;
        boss = boss or resolvedBoss;
    end
    if instanceKey == nil or bossIndex == nil then
        return ParseGraph.TryAddFallbackScoreboardEntry(combatData);
    end
    if boss == nil then
        local instance = ParseGraph.GetInstanceDefinition(instanceKey);
        boss = instance ~= nil and instance.bosses and instance.bosses[bossIndex] or {};
    end

    local amount = ParseGraph.GetBossHealthPercentAmount(combatData, instanceKey, tierKey, bossIndex, boss);
    if amount == nil or tonumber(amount) == nil or tonumber(amount) <= 0 then
        return false;
    end
    amount = tonumber(amount);

    local character = TrimText(combatData.character);
    if character == "" then
        character = ParseGraph.GetCurrentCharacterName();
    end

    local percentHealthOverride = tonumber(combatData.bossPercentHealthOverride);
    local percentValue = nil;
    if percentHealthOverride ~= nil and percentHealthOverride > 0 then
        percentValue = (amount / percentHealthOverride) * 100;
    else
        percentValue = ParseGraph.CalculateScoreboardPercentForAmount(amount, instanceKey, tierKey, bossIndex);
    end
    local combineScope = ParseGraph.GetBossHealthPercentCombineScope(combatData);
    local duplicateKey = LowerClean(character) .. "|" .. tostring(instanceKey) .. "|" .. tostring(tierKey) .. "|" .. tostring(bossIndex) .. "|" .. tostring(combineScope) .. "|" .. tostring(Round(amount)) .. "|" .. LowerClean(combatData.duration) .. "|" .. tostring(Round(tonumber(combatData.rate or combatData.dps) or 0));
    if ParseGraph.BossHealthPercentMessageWasRecent(duplicateKey) then
        return true;
    end

    if type(boss) ~= "table" or boss.isNonBoss ~= true then
        ParseGraph.AddScoreboardEntry(combatData, character, amount, percentValue, instanceKey, tierKey, bossIndex, boss);
    end

    if ParseGraph.ShowBossHealthPercentMessages == true and percentValue ~= nil then
        local percentText, percentIsCombined = ParseGraph.GetBossHealthPercentDisplay(character, amount, percentValue, instanceKey, tierKey, bossIndex, duplicateKey, combineScope);
        ParseGraph.PrintBossHealthPercentMessage(character, percentText, percentIsCombined);
    end
    return true;
end

function ParseGraph.EnsureInstanceBossDataBucket(instances, instanceKey, tierKey, bossIndex)
    if type(instances) ~= "table" then
        return nil;
    end
    if type(instances[instanceKey]) ~= "table" then
        instances[instanceKey] = {};
    end
    if type(instances[instanceKey][tierKey]) ~= "table" then
        instances[instanceKey][tierKey] = {};
    end

    local bossKey = "boss" .. tostring(bossIndex);
    if type(instances[instanceKey][tierKey][bossKey]) ~= "table" then
        instances[instanceKey][tierKey][bossKey] = {};
    end
    return instances[instanceKey][tierKey][bossKey];
end

local function EnsureInstanceRecordBucket(instances, instanceKey, tierKey, bossIndex, mode)
    local bossBucket = ParseGraph.EnsureInstanceBossDataBucket(instances, instanceKey, tierKey, bossIndex);
    if bossBucket == nil then
        return {};
    end
    if type(bossBucket[mode]) ~= "table" then
        bossBucket[mode] = {};
    end

    return bossBucket[mode];
end

function ParseGraph.GetInstanceBossStatsFromInstances(instances, instanceKey, tierKey, bossIndex)
    local instanceData = type(instances) == "table" and instances[instanceKey] or nil;
    local tierData = type(instanceData) == "table" and instanceData[tierKey] or nil;
    local bossData = type(tierData) == "table" and tierData["boss" .. tostring(bossIndex)] or nil;
    local stats = type(bossData) == "table" and bossData.stats or nil;
    if type(stats) ~= "table" then
        return { kills = 0, wipes = 0 };
    end
    return {
        kills = tonumber(stats.kills) or 0,
        wipes = tonumber(stats.wipes) or 0,
        lastKillAt = tonumber(stats.lastKillAt),
        lastWipeAt = tonumber(stats.lastWipeAt),
        firstKillAt = tonumber(stats.firstKillAt),
        firstKillTime = stats.firstKillTime,
        firstKillGroup = stats.firstKillGroup
    };
end

function ParseGraph.GetInstanceBossStats(instanceKey, tierKey, bossIndex)
    return ParseGraph.GetInstanceBossStatsFromInstances(ParseGraph.InstanceData or {}, instanceKey, tierKey, bossIndex);
end

function ParseGraph.ResetInstanceBossCounter(instanceKey, tierKey, bossIndex, statName)
    if statName ~= "kills" and statName ~= "wipes" then
        return false;
    end

    local currentKey = ParseGraph.GetCurrentCharacterKey();
    local viewKey = tostring(ParseGraph.ViewCharacterKey or currentKey);
    local entry = nil;
    if viewKey == tostring(currentKey) then
        entry = ParseGraph.EnsureAccountCharacter(currentKey, ParseGraph.GetCurrentCharacterName());
    elseif type(ParseGraph.AccountData) == "table" and type(ParseGraph.AccountData.characters) == "table" then
        entry = ParseGraph.AccountData.characters[viewKey];
        if type(entry) == "table" then
            entry = NormalizeCharacterData(entry, viewKey, entry.name);
        end
    end

    if type(entry) ~= "table" then
        return false;
    end
    if type(entry.instances) ~= "table" then
        entry.instances = {};
    end

    local bossBucket = ParseGraph.EnsureInstanceBossDataBucket(entry.instances, instanceKey, tierKey, bossIndex);
    if bossBucket == nil then
        return false;
    end
    if type(bossBucket.stats) ~= "table" then
        bossBucket.stats = {};
    end

    bossBucket.stats[statName] = 0;
    if statName == "kills" then
        bossBucket.stats.lastKillAt = nil;
        bossBucket.stats.firstKillAt = nil;
        bossBucket.stats.firstKillTime = nil;
        bossBucket.stats.firstKillGroup = nil;
    else
        bossBucket.stats.lastWipeAt = nil;
    end

    entry.updated = NowText();
    ParseGraph.AccountData.characters[viewKey] = entry;
    if viewKey == tostring(ParseGraph.ViewCharacterKey or currentKey) then
        ParseGraph.InstanceData = entry.instances;
    end

    ParseGraph.SaveAccountData();
    if viewKey == tostring(currentKey) then
        ParseGraph.SaveCharacterEntryToCharacterScope(entry);
    end
    if ParseGraph.CurrentView == "instances" and ParseGraph.DrawInstancesView ~= nil then
        ParseGraph.DrawInstancesView();
    end
    return true;
end

function ParseGraph.GetCurrentGroupMembers()
    local names = {};
    local seen = {};

    local function AddName(name)
        name = tostring(name or "");
        name = string.gsub(name, "^%s+", "");
        name = string.gsub(name, "%s+$", "");
        if name == "" then
            return;
        end

        local key = LowerClean(name);
        key = string.gsub(key, "^%s+", "");
        key = string.gsub(key, "%s+$", "");
        if key == "" or seen[key] == true then
            return;
        end

        seen[key] = true;
        names[#names + 1] = name;
    end

    if ParseGraph.GetPlayerName ~= nil then
        AddName(ParseGraph.GetPlayerName());
    end

    local okPlayer, player = pcall(function()
        if Turbine.Gameplay ~= nil and Turbine.Gameplay.LocalPlayer ~= nil then
            return Turbine.Gameplay.LocalPlayer.GetInstance();
        end
        return nil;
    end);
    if not okPlayer or player == nil then
        okPlayer, player = pcall(function()
            if Turbine.Gameplay ~= nil and Turbine.Gameplay.LocalPlayer ~= nil then
                return Turbine.Gameplay.LocalPlayer:GetInstance();
            end
            return nil;
        end);
    end
    if not okPlayer or player == nil or player.GetParty == nil then
        return names;
    end

    local okParty, party = pcall(function()
        return player:GetParty();
    end);
    if not okParty or party == nil then
        return names;
    end

    local okCount, count = pcall(function()
        if party.GetMemberCount ~= nil then
            return party:GetMemberCount();
        end
        return 0;
    end);
    count = okCount and tonumber(count) or 0;
    local maxProbe = math.max(count, 24);

    local function AddMemberAt(index)
        if party.GetMember == nil then
            return;
        end

        local okMember, member = pcall(function()
            return party:GetMember(index);
        end);
        if not okMember or member == nil or member.GetName == nil then
            return;
        end

        local okName, memberName = pcall(function()
            return member:GetName();
        end);
        if okName then
            AddName(memberName);
        end
    end

    for i = 1, maxProbe do
        AddMemberAt(i);
    end
    for i = 0, maxProbe - 1 do
        AddMemberAt(i);
    end

    table.sort(names, function(a, b)
        return LowerClean(a) < LowerClean(b);
    end);
    return names;
end

function ParseGraph.IncrementCurrentInstanceBossStat(instanceKey, tierKey, bossIndex, statName)
    if statName ~= "kills" and statName ~= "wipes" then
        return false;
    end

    local currentKey = ParseGraph.GetCurrentCharacterKey();
    local entry = ParseGraph.EnsureAccountCharacter(currentKey, ParseGraph.GetCurrentCharacterName());
    if type(entry.instances) ~= "table" then
        entry.instances = {};
    end

    local bossBucket = ParseGraph.EnsureInstanceBossDataBucket(entry.instances, instanceKey, tierKey, bossIndex);
    if bossBucket == nil then
        return false;
    end
    if type(bossBucket.stats) ~= "table" then
        bossBucket.stats = {};
    end

    local now = Turbine.Engine.GetGameTime() or 0;
    local lastField = statName == "kills" and "lastKillAt" or "lastWipeAt";
    local lastAt = tonumber(bossBucket.stats[lastField]);
    if lastAt ~= nil and now - lastAt >= 0 and now - lastAt <= 10 then
        return false;
    end

    local previousCount = tonumber(bossBucket.stats[statName]) or 0;
    if statName == "kills" and previousCount <= 0 then
        local existingGroup = bossBucket.stats.firstKillGroup;
        if type(existingGroup) ~= "table" or #existingGroup == 0 then
            bossBucket.stats.firstKillGroup = ParseGraph.GetCurrentGroupMembers();
        end
        if bossBucket.stats.firstKillAt == nil then
            bossBucket.stats.firstKillAt = now;
        end
        if bossBucket.stats.firstKillTime == nil or tostring(bossBucket.stats.firstKillTime or "") == "" then
            bossBucket.stats.firstKillTime = NowText();
        end
    end

    bossBucket.stats[statName] = previousCount + 1;
    bossBucket.stats[lastField] = now;
    entry.updated = NowText();
    ParseGraph.AccountData.characters[currentKey] = entry;

    local viewingCurrentCharacter = (ParseGraph.ViewCharacterKey or currentKey) == currentKey;
    if viewingCurrentCharacter then
        ParseGraph.InstanceData = entry.instances;
    end

    ParseGraph.SaveAccountData();
    ParseGraph.SaveCharacterEntryToCharacterScope(entry);
    return true;
end

local function IsDuplicateInstanceRecord(records, combatData)
    if type(records) ~= "table" or combatData == nil then
        return false;
    end

    local newDamage = Round(tonumber(combatData.amount or combatData.damage) or -1);
    local newRate = Round(tonumber(combatData.rate or combatData.dps) or -1);
    local newDuration = tonumber(combatData.durationSeconds);
    local newDurationText = LowerClean(combatData.duration);
    local newDamageText = LowerClean(combatData.amountText or combatData.damageText);

    for i = 1, #records do
        local record = records[i];
        if type(record) == "table" then
            local sameDamage = false;
            if newDamage >= 0 and (record.amount ~= nil or record.damage ~= nil) then
                sameDamage = Round(tonumber(record.amount or record.damage) or -2) == newDamage;
            elseif newDamageText ~= "" then
                sameDamage = LowerClean(record.amountText or record.damageText) == newDamageText;
            end

            local sameDuration = false;
            if newDuration ~= nil and record.durationSeconds ~= nil then
                sameDuration = math.abs((tonumber(record.durationSeconds) or -9999) - newDuration) < 0.05;
            elseif newDurationText ~= "" then
                sameDuration = LowerClean(record.duration) == newDurationText;
            elseif tostring(combatData.source or "") == "prime" then
                sameDuration = newRate >= 0 and Round(tonumber(record.rate or record.dps) or -2) == newRate;
            end

            if sameDamage and sameDuration then
                return true;
            end
        end
    end

    return false;
end

local function BuildUnmatchedInstanceSignature(combatData)
    if combatData == nil then
        return "";
    end

    local duration = combatData.durationSeconds;
    if duration ~= nil then
        duration = tostring(Round((tonumber(duration) or 0) * 10));
    else
        duration = LowerClean(combatData.duration);
    end

    return table.concat({
        LowerClean(combatData.character),
        LowerClean(combatData.source),
        LowerClean(combatData.metric),
        LowerClean(combatData.mode),
        LowerClean(combatData.encounter),
        LowerClean(combatData.target),
        tostring(Round(tonumber(combatData.amount or combatData.damage) or 0)),
        tostring(Round(tonumber(combatData.rate or combatData.dps) or 0)),
        tostring(duration or "")
    }, "|");
end

local function CopyCombatAnalysisTargets(targets)
    local copied = {};
    if type(targets) ~= "table" then
        return copied;
    end

    for i = 1, #targets do
        local source = targets[i];
        if type(source) == "table" then
            local target = {};
            for key, value in pairs(source) do
                target[key] = value;
            end
            copied[#copied + 1] = target;
        end
    end

    return copied;
end

local function CopyCombatAnalysisDataForUnmatched(combatData)
    local copied = {};
    if type(combatData) ~= "table" then
        return copied;
    end

    for key, value in pairs(combatData) do
        if key ~= "targets" then
            copied[key] = value;
        end
    end
    copied.targets = CopyCombatAnalysisTargets(combatData.targets);
    return copied;
end

local function GetUnmatchedInstanceEntryById(id)
    id = tonumber(id);
    if id == nil or type(ParseGraph.UnmatchedInstanceEntries) ~= "table" then
        return nil, nil;
    end

    for i = 1, #ParseGraph.UnmatchedInstanceEntries do
        if tonumber(ParseGraph.UnmatchedInstanceEntries[i].id) == id then
            return ParseGraph.UnmatchedInstanceEntries[i], i;
        end
    end

    return nil, nil;
end

local function GetInstanceDefinitionStrict(key)
    key = tostring(key or "");
    if key == "" or type(ParseGraph.InstanceDefinitions) ~= "table" then
        return nil;
    end

    for i = 1, #ParseGraph.InstanceDefinitions do
        if ParseGraph.InstanceDefinitions[i] ~= nil and ParseGraph.InstanceDefinitions[i].key == key then
            return ParseGraph.InstanceDefinitions[i];
        end
    end

    return nil;
end

function ParseGraph.RemoveUnmatchedInstanceEntry(id)
    local entry, index = GetUnmatchedInstanceEntryById(id);
    if entry == nil or index == nil then
        return false;
    end

    table.remove(ParseGraph.UnmatchedInstanceEntries, index);
    return true;
end

function ParseGraph.RemoveUnmatchedInstanceEntryForCombatData(combatData)
    local signature = BuildUnmatchedInstanceSignature(combatData);
    if signature == "" or type(ParseGraph.UnmatchedInstanceEntries) ~= "table" then
        return false;
    end

    local removed = false;
    for i = #ParseGraph.UnmatchedInstanceEntries, 1, -1 do
        if ParseGraph.UnmatchedInstanceEntries[i].signature == signature then
            table.remove(ParseGraph.UnmatchedInstanceEntries, i);
            removed = true;
        end
    end

    return removed;
end

function ParseGraph.QueueUnmatchedInstanceEntry(combatData, reason, detected)
    if combatData == nil or combatData.fromUnmatchedQueue == true or combatData.fromExternalSender == true then
        return nil;
    end
    if LowerClean(combatData.character) ~= LowerClean(ParseGraph.GetCurrentCharacterName()) then
        return nil;
    end

    if type(ParseGraph.UnmatchedInstanceEntries) ~= "table" then
        ParseGraph.UnmatchedInstanceEntries = {};
    end

    local signature = BuildUnmatchedInstanceSignature(combatData);
    if signature == "" then
        return nil;
    end

    for i = 1, #ParseGraph.UnmatchedInstanceEntries do
        if ParseGraph.UnmatchedInstanceEntries[i].signature == signature then
            local existing = ParseGraph.UnmatchedInstanceEntries[i];
            existing.reason = reason or existing.reason;
            if type(detected) == "table" then
                existing.selectedTierKey = existing.selectedTierKey or detected.tierKey;
                existing.selectedInstanceKey = existing.selectedInstanceKey or detected.instanceKey;
                existing.selectedBossIndex = existing.selectedBossIndex or detected.bossIndex;
            end
            if ParseGraph.CurrentView == "instances" and ParseGraph.InstanceViewMode == "unmatched" then
                ParseGraph.DrawInstancesView();
            end
            return existing;
        end
    end

    detected = type(detected) == "table" and detected or {};
    ParseGraph.UnmatchedEntryCounter = (tonumber(ParseGraph.UnmatchedEntryCounter) or 0) + 1;
    local entry = {
        id = ParseGraph.UnmatchedEntryCounter,
        time = NowText(),
        gameTime = Turbine.Engine.GetGameTime(),
        reason = reason or "Needs target",
        signature = signature,
        combatData = CopyCombatAnalysisDataForUnmatched(combatData),
        selectedTierKey = detected.tierKey,
        selectedInstanceKey = detected.instanceKey,
        selectedBossIndex = detected.bossIndex
    };

    if entry.selectedTierKey == nil then
        entry.selectedTierKey = ParseGraph.ActiveInstanceTierKey;
    end
    if entry.selectedInstanceKey == nil then
        entry.selectedInstanceKey = ParseGraph.ActiveInstanceKey;
    end
    if entry.selectedBossIndex == nil and entry.selectedInstanceKey ~= nil then
        entry.selectedBossIndex = tonumber(ParseGraph.AutoInstanceBossIndex) or nil;
    end

    table.insert(ParseGraph.UnmatchedInstanceEntries, 1, entry);
    while #ParseGraph.UnmatchedInstanceEntries > 40 do
        table.remove(ParseGraph.UnmatchedInstanceEntries);
    end

    if ParseGraph.CurrentView == "instances" and ParseGraph.InstanceViewMode == "unmatched" then
        ParseGraph.DrawInstancesView();
    end

    return entry;
end

function ParseGraph.RecordUnmatchedInstanceEntry(id)
    local entry = GetUnmatchedInstanceEntryById(id);
    if entry == nil or type(entry.combatData) ~= "table" then
        return false;
    end

    local instance = GetInstanceDefinitionStrict(entry.selectedInstanceKey);
    local bossIndex = tonumber(entry.selectedBossIndex) or 1;
    local tierKey = tostring(entry.selectedTierKey or "");
    if instance == nil or tierKey == "" or instance.bosses == nil or instance.bosses[bossIndex] == nil then
        ParseGraph.PrintInstanceMessage("Unmatched entry needs a tier, instance and boss before it can be added.");
        return false;
    end

    local combatData = CopyCombatAnalysisDataForUnmatched(entry.combatData);
    combatData.fromUnmatchedQueue = true;
    local previousManualTarget = ParseGraph.ManualInstanceTarget;
    ParseGraph.ManualInstanceTarget = {
        instanceKey = instance.key,
        tierKey = tierKey,
        bossIndex = bossIndex
    };

    local ok = ParseGraph.RecordCombatAnalysisInstanceData(combatData);
    ParseGraph.ManualInstanceTarget = previousManualTarget;
    if ok then
        ParseGraph.RemoveUnmatchedInstanceEntry(id);
        if ParseGraph.CurrentView == "instances" and ParseGraph.InstanceViewMode == "unmatched" then
            ParseGraph.DrawInstancesView();
        end
    end

    return ok;
end

function ParseGraph.RecordCombatAnalysisInstanceData(combatData)
    if combatData == nil then
        return false;
    end

    if LowerClean(combatData.character) ~= LowerClean(ParseGraph.GetCurrentCharacterName()) then
        local percentHandled = ParseGraph.MaybePrintBossHealthPercentMessage(combatData);
        if percentHandled ~= true and ParseGraph.ShowBossHealthPercentMessages ~= true and combatData.fromExternalSender ~= true then
            ParseGraph.PrintInstanceMessage("Instance entry not registered: CombatAnalysis character does not match your current character.");
        end
        return false;
    end

    local tempTarget = ParseGraph.ManualInstanceTarget;
    local pageTarget = ParseGraph.GetTemporaryInstanceTarget();
    if tempTarget == nil then
        tempTarget = pageTarget;
    end
    local fallbackBossIndex = nil;
    local instanceKey = ParseGraph.ActiveInstanceKey;
    local tierKey = ParseGraph.ActiveInstanceTierKey;
    if tempTarget ~= nil then
        instanceKey = tempTarget.instanceKey;
        tierKey = tempTarget.tierKey;
        fallbackBossIndex = tonumber(tempTarget.bossIndex);
    end
    local globalInstance = nil;
    local globalBossIndex = nil;
    if tempTarget == nil then
        globalInstance, globalBossIndex = ParseGraph.FindAnyInstanceBossForCombatAnalysis(combatData);
        if globalInstance == nil then
            globalInstance = ParseGraph.FindAnyInstanceNonBossForCombatAnalysis(combatData);
        end
        if globalInstance ~= nil then
            instanceKey = globalInstance.key;
        end
    end
    if instanceKey == nil or tierKey == nil then
        if instanceKey == nil and ParseGraph.TryAddFallbackScoreboardEntry(combatData) then
            return false;
        end
        if instanceKey ~= nil and tierKey == nil then
            local scoreboardInstance = globalInstance or ParseGraph.GetInstanceDefinition(instanceKey);
            local scoreboardBossIndex = fallbackBossIndex or globalBossIndex;
            if scoreboardBossIndex == nil and scoreboardInstance ~= nil then
                scoreboardBossIndex = ParseGraph.FindInstanceBossForCombatAnalysis(scoreboardInstance, combatData);
            end
            if scoreboardInstance ~= nil and scoreboardBossIndex ~= nil then
                local scoreboardBoss = scoreboardInstance.bosses and scoreboardInstance.bosses[scoreboardBossIndex] or {};
                local scoreboardMetric = ParseGraph.NormalizeInstanceMetricMode(combatData.metric or "damage");
                if scoreboardMetric == "damage" then
                    local scoreboardExpectedMode = IsInstanceBossTotalDamageExpected(instanceKey, nil, scoreboardBossIndex, scoreboardBoss) and "total" or "boss";
                    if ApplyDamageTargetData(combatData, instanceKey, nil, scoreboardBossIndex, scoreboardBoss, scoreboardExpectedMode)
                        and combatData.mode == scoreboardExpectedMode then
                        ParseGraph.MaybePrintBossHealthPercentMessage(combatData, instanceKey, nil, scoreboardBossIndex, scoreboardBoss);
                    end
                end
            end
        end
        ParseGraph.QueueUnmatchedInstanceEntry(combatData, "No active instance tier", {
            instanceKey = instanceKey,
            tierKey = tierKey,
            bossIndex = fallbackBossIndex or globalBossIndex
        });
        ParseGraph.PrintInstanceMessage("No active instance tier was detected.");
        return false;
    end

    local instance = globalInstance or ParseGraph.GetInstanceDefinition(instanceKey);
    if instance == nil or instance.key ~= instanceKey then
        ParseGraph.QueueUnmatchedInstanceEntry(combatData, "Active instance could not be matched", {
            instanceKey = instanceKey,
            tierKey = tierKey,
            bossIndex = fallbackBossIndex or globalBossIndex
        });
        ParseGraph.PrintInstanceMessage("Instance entry not registered: active instance could not be matched.");
        return false;
    end

    local bossIndex = globalBossIndex or ParseGraph.FindInstanceBossForCombatAnalysis(instance, combatData);
    if bossIndex == nil and ParseGraph.InstanceNonBossMatchesCombatAnalysis(instance, combatData) then
        ParseGraph.MaybePrintBossHealthPercentMessage(combatData);
        return false;
    end
    if bossIndex == nil and fallbackBossIndex ~= nil then
        bossIndex = fallbackBossIndex;
    end
    if bossIndex == nil then
        bossIndex = ParseGraph.GetSelectedBossForCombatAnalysis(instanceKey, tierKey, combatData);
    end
    if bossIndex == nil then
        bossIndex = ParseGraph.GetAutoInstanceBossIndex(instanceKey, tierKey);
    end
    if bossIndex == nil then
        ParseGraph.QueueUnmatchedInstanceEntry(combatData, "Boss could not be identified", {
            instanceKey = instanceKey,
            tierKey = tierKey,
            bossIndex = fallbackBossIndex or globalBossIndex
        });
        if combatData.target == nil or TrimText(combatData.target) == "" then
            ParseGraph.PrintInstanceMessage("Instance entry not registered: boss could not be identified. Choose a boss in the launcher menu or open the boss page and repost the line.");
        else
            ParseGraph.PrintInstanceMessage("Instance entry not registered: enemy name did not match the active instance.");
        end
        return false;
    end

    local boss = instance.bosses and instance.bosses[bossIndex] or {};
    local metric = ParseGraph.NormalizeInstanceMetricMode(combatData.metric or "damage");
    local expectedMode = metric;
    if metric == "damage" then
        expectedMode = IsInstanceBossTotalDamageExpected(instanceKey, tierKey, bossIndex, boss) and "total" or "boss";
        if not ApplyDamageTargetData(combatData, instanceKey, tierKey, bossIndex, boss, expectedMode) then
            ParseGraph.QueueUnmatchedInstanceEntry(combatData, "Damage target lines did not include selected boss", {
                instanceKey = instanceKey,
                tierKey = tierKey,
                bossIndex = bossIndex
            });
            ParseGraph.PrintInstanceMessage("Instance entry not registered: damage target lines did not include " .. tostring(boss.name or "this boss") .. ".");
            return false;
        end
    end
    if combatData.mode ~= expectedMode then
        ParseGraph.QueueUnmatchedInstanceEntry(combatData, "Posted type did not match selected boss", {
            instanceKey = instanceKey,
            tierKey = tierKey,
            bossIndex = bossIndex
        });
        if expectedMode == "boss" then
            ParseGraph.PrintInstanceMessage("Instance entry not registered: post boss-only damage for " .. tostring(boss.name or "this boss") .. ".");
        elseif expectedMode == "total" then
            ParseGraph.PrintInstanceMessage("Instance entry not registered: post total encounter damage for " .. tostring(boss.name or "this boss") .. ".");
        else
            local metricInfo = ParseGraph.GetInstanceMetricInfo(metric);
            ParseGraph.PrintInstanceMessage("Instance entry not registered: post " .. string.lower(metricInfo.label) .. " data for " .. tostring(boss.name or "this boss") .. ".");
        end
        return false;
    end

    local hadRecentKillLine = ParseGraph.HasRecentInstanceBossKillLine(instanceKey, tierKey, bossIndex);
    if ParseGraph.HasInstanceBossKillLine(instanceKey, tierKey, bossIndex) ~= true then
        ParseGraph.PrintInstanceMessage("Instance entry not registered: matching boss kill was not detected.");
        return false;
    end

    local currentKey = ParseGraph.GetCurrentCharacterKey();
    if (ParseGraph.ViewCharacterKey or currentKey) ~= currentKey then
        ParseGraph.SelectCharacter(currentKey, true);
    end

    local entry = ParseGraph.EnsureAccountCharacter(currentKey, ParseGraph.GetCurrentCharacterName());
    if type(entry.instances) ~= "table" then
        entry.instances = {};
    end

    local mode = combatData.mode == "boss" and "boss" or (combatData.mode == "total" and "total" or metric);
    local records = EnsureInstanceRecordBucket(entry.instances, instanceKey, tierKey, bossIndex, mode);
    if IsDuplicateInstanceRecord(records, combatData) then
        ParseGraph.PrintInstanceMessage("Instance entry not registered: duplicate damage post already saved.");
        return false;
    end
    records[#records + 1] = {
        time = NowText(),
        gameTime = Turbine.Engine.GetGameTime(),
        source = combatData.source or "combatAnalysis",
        encounter = combatData.encounter,
        target = combatData.target,
        duration = combatData.duration,
        durationSeconds = combatData.durationSeconds,
        metric = metric,
        rateLabel = combatData.rateLabel,
        amountLabel = combatData.amountLabel,
        amountText = combatData.amountText or combatData.damageText,
        amount = combatData.amount or combatData.damage,
        rate = combatData.rate or combatData.dps,
        damageText = combatData.damageText,
        damage = combatData.damage,
        dps = combatData.dps,
        killConfirmed = hadRecentKillLine == true
    };

    if metric == "damage" and hadRecentKillLine ~= true then
        ParseGraph.IncrementCurrentInstanceBossStat(instanceKey, tierKey, bossIndex, "wipes");
    end

    entry.updated = NowText();
    ParseGraph.AccountData.characters[currentKey] = entry;
    local viewingCurrentCharacter = (ParseGraph.ViewCharacterKey or currentKey) == currentKey;
    if viewingCurrentCharacter then
        ParseGraph.InstanceData = entry.instances;
    end
    ParseGraph.SaveAccountData();
    ParseGraph.SaveCharacterEntryToCharacterScope(entry);
    ParseGraph.RemoveUnmatchedInstanceEntryForCombatData(combatData);
    ParseGraph.SetLastLauncherTarget({
        view = "instances",
        instanceKey = instanceKey,
        tierKey = tierKey,
        bossIndex = bossIndex,
        metric = metric
    });

    if globalInstance ~= nil then
        ParseGraph.ActiveInstanceKey = instanceKey;
        ParseGraph.ActiveInstanceTierKey = tierKey;
        ParseGraph.SetLauncherButtonState();
    end

    ParseGraph.InstanceMetricMode = metric;
    if viewingCurrentCharacter and ParseGraph.CurrentView == "instances" then
        ParseGraph.SelectedInstanceKey = instanceKey;
        ParseGraph.DrawInstancesView();
    end

    local metricInfo = ParseGraph.GetInstanceMetricInfo(metric);
    ParseGraph.PrintInstanceMessage("Instance entry registered: " .. ParseGraph.GetInstanceTierLabel(tierKey) .. " Boss " .. tostring(bossIndex) .. " - " .. FormatNumber(combatData.rate or combatData.dps) .. " " .. metricInfo.rateLabel .. ".");
    ParseGraph.MaybePrintBossHealthPercentMessage(combatData, instanceKey, tierKey, bossIndex, boss);
    return true;
end

local function LooksLikeCombatAnalysisHeaderPayload(payload)
    payload = TrimText(payload);
    if payload == "" then
        return false;
    end
    if string.find(payload, "%s%-%s") ~= nil then
        return false;
    end
    return string.match(payload, "^.-%([^%)]+%)%s*;%s*$") ~= nil;
end

local function LooksLikeModernCombatAnalysisPendingPayload(payload)
    local data = ParseGraph.ParseModernCombatAnalysisPayload(payload);
    return data ~= nil and type(data.targets) == "table" and #data.targets == 0;
end

local function LooksLikePrimeParseHeaderPayload(payload)
    payload = TrimText(payload);
    if payload == "" or string.find(payload, "\n", 1, true) ~= nil or string.find(payload, "\r", 1, true) ~= nil then
        return false;
    end
    return string.match(payload, "^%s*[Dd]amage%s+[^|]+%|%s*[%d,%.]+%s*[KkMmBb]?%s*DPS%s*$") ~= nil;
end

local function GetPendingPrimeParseContinuation(text)
    local pending = ParseGraph.PendingPrimeParseHeader;
    if type(pending) ~= "table" or pending.payload == nil then
        return nil;
    end

    local now = Turbine.Engine.GetGameTime();
    if (now - (tonumber(pending.gameTime) or 0)) > 4 then
        ParseGraph.PendingPrimeParseHeader = nil;
        return nil;
    end

    local line = TrimText(StripLeadingChatTimestamp(StripLotroMarkup(text)));
    local channelPayload = string.match(line, "^%s*%[To%s+[^%]]+%]%s*(.+)%s*$");
    if channelPayload ~= nil then
        line = TrimText(channelPayload);
    end
    local incomingPayload = string.match(line, "^%s*%[[^%]]+%]%s*[^:]+:%s*(.+)%s*$");
    if incomingPayload ~= nil then
        line = TrimText(incomingPayload);
    end
    line = string.gsub(line, "'%s*$", "");
    line = TrimText(line);

    if string.match(line, "^%s*.-%s+%-%s+[%d,%.]+%s*[KkMmBb]?%s*$") == nil then
        return nil;
    end

    return tostring(pending.payload or "") .. "\n" .. line, pending.sender;
end

local function GetPendingCombatAnalysisContinuation(text)
    local pending = ParseGraph.PendingCombatAnalysisHeader;
    if type(pending) ~= "table" or pending.payload == nil then
        return nil;
    end

    local now = Turbine.Engine.GetGameTime();
    if (now - (tonumber(pending.gameTime) or 0)) > 8 then
        ParseGraph.PendingCombatAnalysisHeader = nil;
        return nil;
    end

    local line = TrimText(StripLeadingChatTimestamp(StripLotroMarkup(text)));
    if line == "" then
        return nil;
    end

    local channelPayload = string.match(line, "^%s*%[To%s+[^%]]+%]%s*(.+)%s*$");
    if channelPayload ~= nil then
        line = TrimText(channelPayload);
    end
    local incomingPayload = string.match(line, "^%s*%[[^%]]+%]%s*[^:]+:%s*(.+)%s*$");
    if incomingPayload ~= nil then
        line = TrimText(incomingPayload);
    end
    line = string.gsub(line, "'%s*$", "");
    line = TrimText(line);

    if pending.format == "modern" then
        if not LooksLikeModernCombatAnalysisLine(line) then
            if string.find(line, ":", 1, true) == nil and string.lower(line) ~= "healed by:" then
                pending.payload = tostring(pending.payload or "") .. "\n" .. line;
                pending.gameTime = now;
            end
            return nil;
        end
        return tostring(pending.payload or "") .. "\n" .. line, pending.sender;
    end

    if string.find(LowerClean(line), LowerClean(ParseGraph.GetCurrentCharacterName()), 1, true) == nil then
        return nil;
    end

    if string.find(line, "%s%-%s") == nil then
        return nil;
    end

    local lower = LowerClean(line);
    if string.find(lower, "dmg:", 1, true) == nil
        and string.find(lower, "heal:", 1, true) == nil
        and string.find(lower, "taken:", 1, true) == nil then
        return nil;
    end

    return tostring(pending.payload or "") .. " " .. line, pending.sender;
end

function ParseGraph.ProcessCombatAnalysisText(text)
    local payload, payloadSender = ParseGraph.GetOwnCombatAnalysisPayload(text);
    if payload == nil then
        payload, payloadSender = GetPendingCombatAnalysisContinuation(text);
        if payload == nil then
            payload, payloadSender = GetPendingPrimeParseContinuation(text);
            if payload == nil then
                return false;
            end
        end
    end
    if string.find(LowerClean(payload), "^parsegraph") ~= nil then
        return false;
    end

    local combatData = ParseGraph.ParseCombatAnalysisPayload(payload, payloadSender);
    local parsedPrimePayload = false;
    if combatData == nil then
        combatData = ParseGraph.ParsePrimeParsePayload(payload);
        parsedPrimePayload = combatData ~= nil;
    end
    if combatData ~= nil and payloadSender ~= nil and TrimText(payloadSender) ~= "" then
        combatData.chatSender = TrimText(payloadSender);
        if parsedPrimePayload then
            combatData.character = TrimText(payloadSender);
        end
        combatData.fromExternalSender = LowerClean(payloadSender) ~= LowerClean(ParseGraph.GetCurrentCharacterName());
    end
    if combatData ~= nil
        and tostring(combatData.source or "") == "combatAnalysisModern"
        and type(combatData.targets) == "table"
        and #combatData.targets == 0
        and tostring(combatData.metric or "") == "damage"
        and LooksLikeModernCombatAnalysisPendingPayload(payload) then
        ParseGraph.PendingCombatAnalysisHeader = {
            payload = payload,
            gameTime = Turbine.Engine.GetGameTime(),
            format = "modern",
            sender = payloadSender
        };
        return false;
    end
    if parsedPrimePayload
        and type(combatData.targets) == "table"
        and #combatData.targets == 0
        and LooksLikePrimeParseHeaderPayload(payload) then
        ParseGraph.PendingPrimeParseHeader = {
            payload = payload,
            gameTime = Turbine.Engine.GetGameTime(),
            sender = payloadSender
        };
        return false;
    end
    if combatData == nil then
        if LooksLikeModernCombatAnalysisHeaderPayload(payload) then
            ParseGraph.PendingCombatAnalysisHeader = {
                payload = payload,
                gameTime = Turbine.Engine.GetGameTime(),
                format = "modern",
                sender = payloadSender
            };
        elseif LooksLikeCombatAnalysisHeaderPayload(payload) then
            ParseGraph.PendingCombatAnalysisHeader = {
                payload = payload,
                gameTime = Turbine.Engine.GetGameTime(),
                format = "old",
                sender = payloadSender
            };
        elseif LooksLikePrimeParseHeaderPayload(payload) then
            ParseGraph.PendingPrimeParseHeader = {
                payload = payload,
                gameTime = Turbine.Engine.GetGameTime(),
                sender = payloadSender
            };
        elseif LooksLikeModernCombatAnalysisLine(payload) then
            return false;
        elseif string.find(LowerClean(payload), "dps:", 1, true) ~= nil
            or string.find(LowerClean(payload), "dmg:", 1, true) ~= nil
            or string.find(LowerClean(payload), "hps:", 1, true) ~= nil
            or string.find(LowerClean(payload), "heal:", 1, true) ~= nil
            or string.find(LowerClean(payload), "tps:", 1, true) ~= nil
            or string.find(LowerClean(payload), "taken:", 1, true) ~= nil then
            ParseGraph.PrintInstanceMessage("Instance entry not registered: damage post format was not recognized.");
        end
        return false;
    end

    ParseGraph.PendingCombatAnalysisHeader = nil;
    ParseGraph.PendingPrimeParseHeader = nil;
    return ParseGraph.RecordCombatAnalysisInstanceData(combatData);
end

function ParseGraph.GetInstanceBossRecords(instanceKey, tierKey, bossIndex, mode)
    if not ParseGraph.IsCombineSameClassActive() then
        return GetRecordsFromInstanceData(ParseGraph.InstanceData or {}, instanceKey, tierKey, bossIndex, mode);
    end

    local combined = {};
    ParseGraph.ForEachViewClassCharacter(function(key, entry, isView)
        local instances = isView and (ParseGraph.InstanceData or {}) or (entry.instances or {});
        local records = GetRecordsFromInstanceData(instances, instanceKey, tierKey, bossIndex, mode);
        for i = 1, #records do
            local record = CopyShallow(records[i]);
            record.sourceKey = key;
            record.sourceName = entry.name or key;
            record.sourceIndex = i;
            combined[#combined + 1] = record;
        end
    end);
    return combined;
end

function ParseGraph.ForEachAccountCharacter(callback)
    if type(callback) ~= "function" then
        return;
    end

    local currentKey = tostring(ParseGraph.GetCurrentCharacterKey());
    local viewKey = tostring(ParseGraph.ViewCharacterKey or currentKey);
    local characters = ParseGraph.AccountData and ParseGraph.AccountData.characters or {};
    local seen = {};

    local function visit(key, entry)
        key = tostring(key or "");
        if key == "" or seen[key] == true or type(entry) ~= "table" then
            return;
        end
        seen[key] = true;
        entry = NormalizeCharacterData(entry, key, entry.name);
        if key == currentKey then
            local classInfo = ParseGraph.GetCurrentPlayerClassInfo();
            if classInfo ~= nil then
                entry.classKey = classInfo.key;
                entry.className = classInfo.name;
                entry.classIcon = classInfo.icon;
            end
        end
        if type(ParseGraph.AccountData) == "table" and type(ParseGraph.AccountData.characters) == "table" then
            ParseGraph.AccountData.characters[key] = entry;
        end
        callback(key, entry, key == viewKey);
    end

    if type(characters) == "table" then
        for key, entry in pairs(characters) do
            visit(key, entry);
        end
    end

    if seen[viewKey] ~= true then
        local viewEntry = ParseGraph.GetViewCharacterEntry();
        if type(viewEntry) == "table" then
            visit(viewKey, viewEntry);
        end
    end
end

function ParseGraph.GetAccountInstanceBossRecords(instanceKey, tierKey, bossIndex, mode)
    local combined = {};
    ParseGraph.ForEachAccountCharacter(function(key, entry, isView)
        local instances = isView and (ParseGraph.InstanceData or {}) or (entry.instances or {});
        local records = GetRecordsFromInstanceData(instances, instanceKey, tierKey, bossIndex, mode);
        for i = 1, #records do
            local record = CopyShallow(records[i]);
            record.sourceKey = key;
            record.sourceName = entry.name or key;
            record.sourceIndex = i;
            combined[#combined + 1] = record;
        end
    end);
    return combined;
end

local function GetBestDpsFromRecords(records)
    local best = nil;
    if type(records) ~= "table" then
        return nil;
    end

    for i = 1, #records do
        local dps = tonumber(records[i] and (records[i].rate or records[i].dps));
        if dps ~= nil and (best == nil or dps > best) then
            best = dps;
        end
    end

    return best;
end

local function AppendRecords(target, source, mode)
    if type(source) ~= "table" then return end
    for i = 1, #source do
        local record = {};
        if type(source[i]) == "table" then
            for k, v in pairs(source[i]) do
                record[k] = v;
            end
        end
        record.sourceMode = mode;
        if record.sourceIndex == nil then
            record.sourceIndex = i;
        end
        target[#target + 1] = record;
    end
end

local function GetAverageDpsFromRecords(records)
    local total = 0;
    local count = 0;
    if type(records) ~= "table" then
        return nil;
    end

    for i = 1, #records do
        local dps = tonumber(records[i] and (records[i].rate or records[i].dps));
        if dps ~= nil then
            total = total + dps;
            count = count + 1;
        end
    end

    if count == 0 then
        return nil;
    end

    return total / count;
end

function ParseGraph.IsKillConfirmedInstanceRecord(record)
    return type(record) == "table" and record.killConfirmed == true;
end

local function GetKillTimeSummaryFromRecords(records)
    local best = nil;
    local total = 0;
    local count = 0;
    if type(records) ~= "table" then
        return nil, nil;
    end

    for i = 1, #records do
        local record = records[i];
        local seconds = tonumber(record and record.durationSeconds);
        if ParseGraph.IsKillConfirmedInstanceRecord(record) and seconds ~= nil and seconds > 0 then
            if best == nil or seconds < best then
                best = seconds;
            end
            total = total + seconds;
            count = count + 1;
        end
    end

    if count == 0 then
        return nil, nil;
    end

    return best, total / count;
end
function ParseGraph.GetInstanceBossSummary(instanceKey, tierKey, bossIndex, metric)
    metric = ParseGraph.NormalizeInstanceMetricMode(metric);
    local stats = ParseGraph.GetInstanceBossStats(instanceKey, tierKey, bossIndex);
    if metric ~= "damage" then
        local metricRecords = ParseGraph.GetInstanceBossRecords(instanceKey, tierKey, bossIndex, metric);
        local metricSummary = ParseGraph.GetInstanceRecordSummary(metricRecords);
        return {
            bestBossDps = metricSummary.bestDps,
            bestTotalDps = metricSummary.bestDps,
            averageBossDps = metricSummary.averageDps,
            averageTotalDps = metricSummary.averageDps,
            bestKillTime = metricSummary.bestKillTime,
            averageKillTime = metricSummary.averageKillTime,
            posts = #metricRecords,
            kills = tonumber(stats.kills) or 0,
            wipes = tonumber(stats.wipes) or 0,
            firstKillAt = stats.firstKillAt,
            firstKillTime = stats.firstKillTime,
            firstKillGroup = stats.firstKillGroup
        };
    end

    local bossRecords = ParseGraph.GetInstanceBossRecords(instanceKey, tierKey, bossIndex, "boss");
    local totalRecords = ParseGraph.GetInstanceBossRecords(instanceKey, tierKey, bossIndex, "total");
    local allRecords = {};
    AppendRecords(allRecords, bossRecords, "boss");
    AppendRecords(allRecords, totalRecords, "total");
    local bestTime, averageTime = GetKillTimeSummaryFromRecords(allRecords);
    return {
        bestBossDps = GetBestDpsFromRecords(bossRecords),
        bestTotalDps = GetBestDpsFromRecords(totalRecords),
        averageBossDps = GetAverageDpsFromRecords(bossRecords),
        averageTotalDps = GetAverageDpsFromRecords(totalRecords),
        bestKillTime = bestTime,
        averageKillTime = averageTime,
        posts = #bossRecords + #totalRecords,
        kills = tonumber(stats.kills) or 0,
        wipes = tonumber(stats.wipes) or 0,
        firstKillAt = stats.firstKillAt,
        firstKillTime = stats.firstKillTime,
        firstKillGroup = stats.firstKillGroup
    };
end

function ParseGraph.GetAccountInstanceBossStats(instanceKey, tierKey, bossIndex)
    local combined = { kills = 0, wipes = 0 };
    ParseGraph.ForEachAccountCharacter(function(key, entry, isView)
        local instances = isView and (ParseGraph.InstanceData or {}) or (entry.instances or {});
        local stats = ParseGraph.GetInstanceBossStatsFromInstances(instances, instanceKey, tierKey, bossIndex);
        combined.kills = combined.kills + (tonumber(stats.kills) or 0);
        combined.wipes = combined.wipes + (tonumber(stats.wipes) or 0);

        local firstTime = tostring(stats.firstKillTime or "");
        local firstAt = tonumber(stats.firstKillAt);
        local shouldUse = false;
        if firstTime ~= "" then
            shouldUse = combined.firstKillTime == nil
                or tostring(combined.firstKillTime or "") == ""
                or firstTime < tostring(combined.firstKillTime or "");
        elseif firstAt ~= nil then
            shouldUse = combined.firstKillTime == nil
                and (combined.firstKillAt == nil or firstAt < (tonumber(combined.firstKillAt) or firstAt));
        end

        if shouldUse then
            combined.firstKillAt = firstAt;
            combined.firstKillTime = stats.firstKillTime;
            combined.firstKillGroup = type(stats.firstKillGroup) == "table" and CopyShallow(stats.firstKillGroup) or stats.firstKillGroup;
            combined.firstKillCharacterKey = key;
            combined.firstKillCharacterName = entry.name or key;
        end
    end);
    return combined;
end

function ParseGraph.GetAccountInstanceBossSummary(instanceKey, tierKey, bossIndex, metric)
    metric = ParseGraph.NormalizeInstanceMetricMode(metric);
    local stats = ParseGraph.GetAccountInstanceBossStats(instanceKey, tierKey, bossIndex);
    if metric ~= "damage" then
        local metricRecords = ParseGraph.GetAccountInstanceBossRecords(instanceKey, tierKey, bossIndex, metric);
        local metricSummary = ParseGraph.GetInstanceRecordSummary(metricRecords);
        return {
            bestBossDps = metricSummary.bestDps,
            bestTotalDps = metricSummary.bestDps,
            averageBossDps = metricSummary.averageDps,
            averageTotalDps = metricSummary.averageDps,
            bestKillTime = metricSummary.bestKillTime,
            averageKillTime = metricSummary.averageKillTime,
            posts = #metricRecords,
            kills = tonumber(stats.kills) or 0,
            wipes = tonumber(stats.wipes) or 0,
            firstKillAt = stats.firstKillAt,
            firstKillTime = stats.firstKillTime,
            firstKillGroup = stats.firstKillGroup
        };
    end

    local bossRecords = ParseGraph.GetAccountInstanceBossRecords(instanceKey, tierKey, bossIndex, "boss");
    local totalRecords = ParseGraph.GetAccountInstanceBossRecords(instanceKey, tierKey, bossIndex, "total");
    local allRecords = {};
    AppendRecords(allRecords, bossRecords, "boss");
    AppendRecords(allRecords, totalRecords, "total");
    local bestTime, averageTime = GetKillTimeSummaryFromRecords(allRecords);
    return {
        bestBossDps = GetBestDpsFromRecords(bossRecords),
        bestTotalDps = GetBestDpsFromRecords(totalRecords),
        averageBossDps = GetAverageDpsFromRecords(bossRecords),
        averageTotalDps = GetAverageDpsFromRecords(totalRecords),
        bestKillTime = bestTime,
        averageKillTime = averageTime,
        posts = #bossRecords + #totalRecords,
        kills = tonumber(stats.kills) or 0,
        wipes = tonumber(stats.wipes) or 0,
        firstKillAt = stats.firstKillAt,
        firstKillTime = stats.firstKillTime,
        firstKillGroup = stats.firstKillGroup
    };
end

function ParseGraph.GetInstanceBossHealth(instanceKey, tierKey, bossIndex)
    instanceKey = tostring(instanceKey or "");
    tierKey = tostring(tierKey or "");
    bossIndex = tonumber(bossIndex) or 1;

    local health = nil;
    local instance = ParseGraph.GetInstanceDefinition(instanceKey);
    local boss = instance and instance.bosses and instance.bosses[bossIndex] or nil;
    if type(boss) == "table" then
        if type(boss.healthByTier) == "table" then
            health = boss.healthByTier[tierKey];
        end
        if health == nil then
            health = boss.health;
        end
    end

    local healthData = ParseGraph.InstanceBossHealth;
    if health == nil and type(healthData) == "table" then
        local instanceHealth = healthData[instanceKey];
        if type(instanceHealth) == "table" then
            local tierHealth = instanceHealth[tierKey];
            if type(tierHealth) == "table" then
                health = tierHealth[bossIndex] or tierHealth["boss" .. tostring(bossIndex)];
            end
        end
    end

    if type(health) == "string" then
        health = ParseCompactDamageText(health);
    end

    health = tonumber(health);
    if health == nil or health <= 0 then
        return nil;
    end
    return health;
end

function ParseGraph.GetInstanceBossHealthBreakdown(instanceKey, tierKey, bossIndex)
    instanceKey = tostring(instanceKey or "");
    tierKey = tostring(tierKey or "");
    bossIndex = tonumber(bossIndex) or 1;

    local breakdownData = ParseGraph.InstanceBossHealthBreakdown;
    if type(breakdownData) == "table" then
        local instanceBreakdown = breakdownData[instanceKey];
        if type(instanceBreakdown) == "table" then
            local tierBreakdown = instanceBreakdown[tierKey];
            if type(tierBreakdown) == "table" and type(tierBreakdown[bossIndex]) == "table" then
                return tierBreakdown[bossIndex];
            end
        end
    end

    local health = ParseGraph.GetInstanceBossHealth(instanceKey, tierKey, bossIndex);
    if health == nil then
        return nil;
    end

    local instance = ParseGraph.GetInstanceDefinition(instanceKey);
    local boss = instance and instance.bosses and instance.bosses[bossIndex] or nil;
    local bossName = boss and boss.name or ("Boss " .. tostring(bossIndex));
    return { { name = bossName, health = health } };
end

local function FormatInstanceHealthTooltip(instanceKey, tierKey, bossIndex)
    local rows = ParseGraph.GetInstanceBossHealthBreakdown(instanceKey, tierKey, bossIndex);
    if type(rows) ~= "table" or #rows == 0 then
        return nil;
    end

    local tooltipRows = {};
    local total = 0;
    for i = 1, #rows do
        local row = rows[i];
        local health = tonumber(row.health);
        if health ~= nil and health > 0 then
            total = total + health;
            tooltipRows[#tooltipRows + 1] = {
                name = tostring(row.name or ("Enemy " .. tostring(i))),
                health = FormatNumber(health)
            };
        end
    end

    if total <= 0 then
        return nil;
    end

    if #rows > 1 then
        tooltipRows[#tooltipRows + 1] = {
            name = "Total",
            health = FormatNumber(total)
        };
    end
    return tooltipRows;
end

function ParseGraph.HideInstanceHealthTooltip()
    if ParseGraph.InstanceHealthTooltip ~= nil then
        ParseGraph.InstanceHealthTooltip:SetVisible(false);
    end
end

function ParseGraph.ResetInstanceHealthTooltip()
    ParseGraph.HideInstanceHealthTooltip();
    ParseGraph.InstanceHealthTooltip = nil;
    ParseGraph.InstanceHealthTooltipParent = nil;
end

function ParseGraph.ShowInstanceHealthTooltip(parent, rows, rowY)
    if type(rows) ~= "table" or #rows == 0 or parent == nil then
        return;
    end

    if ParseGraph.InstanceHealthTooltip == nil or ParseGraph.InstanceHealthTooltipParent ~= parent then
        local tip = Turbine.UI.Control();
        tip:SetParent(parent);
        tip:SetSize(420, 76);
        tip:SetBackColor(Turbine.UI.Color(0.98, 0.01, 0.01, 0.01));
        tip:SetMouseVisible(false);
        tip:SetZOrder(1000);

        tip.topBorder = DrawBlock(tip, 0, 0, 420, 1, Turbine.UI.Color(1, 0.94, 0.64, 0.06));
        tip.bottomBorder = DrawBlock(tip, 0, 75, 420, 1, Turbine.UI.Color(1, 0.94, 0.64, 0.06));
        tip.leftBorder = DrawBlock(tip, 0, 0, 1, 76, Turbine.UI.Color(1, 0.94, 0.64, 0.06));
        tip.rightBorder = DrawBlock(tip, 419, 0, 1, 76, Turbine.UI.Color(1, 0.94, 0.64, 0.06));

        local title = Label(tip, 10, 6, 400, 20, "Boss health", "big");
        title:SetFont(Turbine.UI.Lotro.Font.TrajanProBold16);
        title:SetForeColor(Turbine.UI.Color(1.00, 1.00, 1.00, 1.00));
        title:SetZOrder(1005);

        tip.title = title;
        tip.nameLabels = {};
        tip.healthLabels = {};
        for i = 1, 5 do
            local name = Label(tip, 10, 28 + ((i - 1) * 20), 290, 20, "", "big");
            name:SetFont(Turbine.UI.Lotro.Font.TrajanPro16);
            name:SetForeColor(Turbine.UI.Color(1.00, 1.00, 0.62, 0.12));
            name:SetZOrder(1005);
            local health = Label(tip, 305, 28 + ((i - 1) * 20), 105, 20, "", "big");
            health:SetFont(Turbine.UI.Lotro.Font.TrajanPro16);
            health:SetForeColor(Turbine.UI.Color(1.00, 1.00, 1.00, 1.00));
            health:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
            health:SetZOrder(1005);
            tip.nameLabels[i] = name;
            tip.healthLabels[i] = health;
        end

        ParseGraph.InstanceHealthTooltip = tip;
        ParseGraph.InstanceHealthTooltipParent = parent;
    end

    local width = 420;
    local height = 38 + (math.min(#rows, 5) * 20);
    ParseGraph.InstanceHealthTooltip:SetSize(width, height);
    ParseGraph.InstanceHealthTooltip.topBorder:SetSize(width, 1);
    ParseGraph.InstanceHealthTooltip.bottomBorder:SetPosition(0, height - 1);
    ParseGraph.InstanceHealthTooltip.bottomBorder:SetSize(width, 1);
    ParseGraph.InstanceHealthTooltip.leftBorder:SetSize(1, height);
    ParseGraph.InstanceHealthTooltip.rightBorder:SetPosition(width - 1, 0);
    ParseGraph.InstanceHealthTooltip.rightBorder:SetSize(1, height);

    for i = 1, 5 do
        local row = rows[i];
        if row ~= nil then
            ParseGraph.InstanceHealthTooltip.nameLabels[i]:SetText(tostring(row.name or "") .. ":");
            ParseGraph.InstanceHealthTooltip.nameLabels[i]:SetVisible(true);
            ParseGraph.InstanceHealthTooltip.healthLabels[i]:SetText(tostring(row.health or ""));
            ParseGraph.InstanceHealthTooltip.healthLabels[i]:SetVisible(true);
        else
            ParseGraph.InstanceHealthTooltip.nameLabels[i]:SetText("");
            ParseGraph.InstanceHealthTooltip.nameLabels[i]:SetVisible(false);
            ParseGraph.InstanceHealthTooltip.healthLabels[i]:SetText("");
            ParseGraph.InstanceHealthTooltip.healthLabels[i]:SetVisible(false);
        end
    end

    local y = tonumber(rowY) or 464;
    if y > (height + 8) then
        y = y - height - 8;
    else
        y = y + 26;
    end

    ParseGraph.InstanceHealthTooltip:SetPosition(372, y);
    ParseGraph.InstanceHealthTooltip:SetVisible(true);
end

function ParseGraph.BindInstanceHealthTooltip(control, parent, rows, rowY)
    if control == nil or type(rows) ~= "table" or #rows == 0 then
        return;
    end

    pcall(function()
        control:SetMouseVisible(true);
    end);
    control.MouseEnter = function()
        ParseGraph.ShowInstanceHealthTooltip(parent, rows, rowY);
    end
    control.MouseLeave = function()
        ParseGraph.HideInstanceHealthTooltip();
    end
end

function ParseGraph.GetInstanceTierLabel(tierKey)
    tierKey = tostring(tierKey or "");
    for i = 1, #ParseGraph.InstanceTiers do
        if ParseGraph.InstanceTiers[i].key == tierKey then
            return ParseGraph.InstanceTiers[i].label;
        end
    end
    return tierKey;
end

function ParseGraph.GetInstanceButtonLines(instance)
    instance = instance or {};
    local key = tostring(instance.key or "");
    local name = tostring(instance.name or "");
    if key == "folly" then
        return "The Folly", string.gsub(name, "^The Folly%s+", "");
    elseif key == "ekalNebi" then
        return "The Fallen Palace", string.match(name, "^(.-),") or "Ekal-nebi";
    elseif key == "hurumKana" then
        return "The Treasure Caves", string.gsub(name, "^The Treasure Caves%s+", "");
    elseif key == "kothRau" then
        return "The Wailing Hold", string.match(name, "^(.-),") or "Koth Rau";
    elseif key == "pagruKirit" then
        return "Garden of Corpses", string.match(name, "^(.-),") or "Pagru-kirit";
    end
    return name, "";
end

function ParseGraph.SetActiveInstanceTier(instanceKey, tierKey)
    local instance = ParseGraph.GetInstanceDefinition(instanceKey);
    if instance == nil then
        return;
    end

    local selectedTier = nil;
    for i = 1, #ParseGraph.InstanceTiers do
        if ParseGraph.InstanceTiers[i].key == tierKey then
            selectedTier = ParseGraph.InstanceTiers[i];
            break;
        end
    end
    if selectedTier == nil then
        return;
    end

    local preservedBossIndex = nil;
    if ParseGraph.ActiveInstanceKey == instance.key
        and ParseGraph.ActiveInstanceTierKey == nil
        and ParseGraph.AutoInstanceBossIndex ~= nil then
        local bossCount = type(instance.bosses) == "table" and #instance.bosses or 1;
        preservedBossIndex = math.max(1, math.min(bossCount, tonumber(ParseGraph.AutoInstanceBossIndex) or 1));
    end

    ParseGraph.ActiveInstanceKey = instance.key;
    ParseGraph.ActiveInstanceTierKey = selectedTier.key;
    ParseGraph.AutoInstanceBossIndex = preservedBossIndex;
    if preservedBossIndex ~= nil and ParseGraph.ResetAutoInstanceBossDefeats ~= nil then
        ParseGraph.ResetAutoInstanceBossDefeats(instance.key, selectedTier.key, preservedBossIndex);
    else
        ParseGraph.AutoInstanceDefeats = nil;
    end
    ParseGraph.SelectedInstanceKey = instance.key;
    ParseGraph.ManualInstanceTarget = nil;
    ParseGraph.PrintInstanceMessage("Active instance tier set: " .. tostring(instance.name or "") .. " - " .. selectedTier.label .. ".");
    ParseGraph.SetLauncherButtonState();
    if ParseGraph.CurrentView == "instances" then
        ParseGraph.DrawInstancesView();
    end
end

function ParseGraph.SetContextTierOnly(tierKey)
    local selectedTier = nil;
    for i = 1, #ParseGraph.InstanceTiers do
        if ParseGraph.InstanceTiers[i].key == tierKey then
            selectedTier = ParseGraph.InstanceTiers[i];
            break;
        end
    end
    if selectedTier == nil then
        return;
    end

    local instanceKey = ParseGraph.ActiveInstanceKey;
    local bossIndex = tonumber(ParseGraph.AutoInstanceBossIndex);
    ParseGraph.ActiveInstanceTierKey = selectedTier.key;
    if instanceKey ~= nil and bossIndex ~= nil then
        local instance = ParseGraph.GetInstanceDefinition(instanceKey);
        if instance ~= nil and type(instance.bosses) == "table" and #instance.bosses > 0 then
            bossIndex = math.max(1, math.min(#instance.bosses, bossIndex));
            ParseGraph.ActiveInstanceKey = instance.key;
            ParseGraph.AutoInstanceBossIndex = bossIndex;
            ParseGraph.SelectedInstanceKey = instance.key;
            ParseGraph.SelectedInstanceBossIndex = bossIndex;
            if ParseGraph.ResetAutoInstanceBossDefeats ~= nil then
                ParseGraph.ResetAutoInstanceBossDefeats(instance.key, selectedTier.key, bossIndex);
            end
        else
            ParseGraph.AutoInstanceBossIndex = nil;
            ParseGraph.AutoInstanceDefeats = nil;
        end
    else
        ParseGraph.AutoInstanceBossIndex = nil;
        ParseGraph.AutoInstanceDefeats = nil;
    end
    ParseGraph.ManualInstanceTarget = nil;
    ParseGraph.PrintInstanceMessage("Active instance tier set: " .. selectedTier.label .. ".");
    ParseGraph.SetLauncherButtonState();
    if ParseGraph.CurrentView == "instances" then
        ParseGraph.DrawInstancesView();
    end
end

function ParseGraph.GetInstanceBossCombinedRecords(instanceKey, tierKey, bossIndex, metric)
    local records = {};
    metric = ParseGraph.NormalizeInstanceMetricMode(metric);
    if metric == "healing" or metric == "taken" then
        AppendRecords(records, ParseGraph.GetInstanceBossRecords(instanceKey, tierKey, bossIndex, metric), metric);
    else
        AppendRecords(records, ParseGraph.GetInstanceBossRecords(instanceKey, tierKey, bossIndex, "boss"), "boss");
        AppendRecords(records, ParseGraph.GetInstanceBossRecords(instanceKey, tierKey, bossIndex, "total"), "total");
    end
    return records;
end

local function GetRecordDisplayDps(record)
    if type(record) ~= "table" then
        return nil;
    end
    return tonumber(record.rate or record.dps);
end

local function GetRecordTypeLabel(record)
    if type(record) ~= "table" then
        return "";
    end
    if record.metric == "healing" or record.sourceMode == "healing" then
        return "Heal";
    end
    if record.metric == "taken" or record.sourceMode == "taken" then
        return "Taken";
    end
    if record.target ~= nil and tostring(record.target) ~= "" then
        return "Boss";
    end
    return "Total";
end

function ParseGraph.GetInstanceRecordSummary(records)
    local bestDps = nil;
    local totalDps = 0;
    local dpsCount = 0;
    local bestTime, averageTime = GetKillTimeSummaryFromRecords(records);

    if type(records) == "table" then
        for i = 1, #records do
            local dps = GetRecordDisplayDps(records[i]);
            if dps ~= nil then
                if bestDps == nil or dps > bestDps then
                    bestDps = dps;
                end
                totalDps = totalDps + dps;
                dpsCount = dpsCount + 1;
            end
        end
    end

    return {
        count = dpsCount,
        averageDps = dpsCount > 0 and (totalDps / dpsCount) or nil,
        bestDps = bestDps,
        bestKillTime = bestTime,
        averageKillTime = averageTime
    };
end

function ParseGraph.Utf8Prefix(text, maxChars)
    local value = tostring(text or "");
    maxChars = tonumber(maxChars) or 0;
    if maxChars <= 0 then
        return "", value ~= "";
    end

    local length = string.len(value);
    local pos = 1;
    local chars = 0;
    local last = 0;
    while pos <= length and chars < maxChars do
        local byte = string.byte(value, pos) or 0;
        local step = 1;
        if byte >= 240 then
            step = 4;
        elseif byte >= 224 then
            step = 3;
        elseif byte >= 192 then
            step = 2;
        end

        if pos + step - 1 > length then
            break;
        end

        last = pos + step - 1;
        pos = pos + step;
        chars = chars + 1;
    end

    if last <= 0 then
        return "", value ~= "";
    end
    return string.sub(value, 1, last), last < length;
end

function ParseGraph.TruncateStatisticsText(text, maxChars)
    local value = tostring(text or "");
    maxChars = tonumber(maxChars) or 32;
    local prefix, truncated = ParseGraph.Utf8Prefix(value, maxChars);
    if truncated ~= true then
        return value;
    end
    if maxChars <= 3 then
        return prefix;
    end

    prefix = ParseGraph.Utf8Prefix(value, maxChars - 3);
    return prefix .. "...";
end

function ParseGraph.GetFirstKillGroupText(group)
    if type(group) == "string" then
        group = string.gsub(group, "^%s+", "");
        group = string.gsub(group, "%s+$", "");
        if group ~= "" then
            return group;
        end
        return "-";
    end

    if type(group) ~= "table" or #group == 0 then
        return "-";
    end

    local text = "";
    for i = 1, #group do
        local name = tostring(group[i] or "");
        name = string.gsub(name, "^%s+", "");
        name = string.gsub(name, "%s+$", "");
        if name ~= "" then
            if text ~= "" then
                text = text .. ", ";
            end
            text = text .. name;
        end
    end

    if text == "" then
        return "-";
    end
    return text;
end

function ParseGraph.ExtractSayInfoText(text)
    local line = TrimText(StripLeadingChatTimestamp(StripLotroMarkup(text)));
    if line == "" then
        return nil, nil;
    end

    local source, message = string.match(line, "^(.-)%s+says,%s+'(.*)'%s*$");
    if source == nil or message == nil then
        return nil, nil;
    end

    return TrimText(source), TrimText(message);
end

function ParseGraph.GetInstanceEncounterStartTarget(text)
    local source, message = ParseGraph.ExtractSayInfoText(text);
    if source == nil or message == nil then
        return nil, nil;
    end

    local sourceKey = NormalizeBossMatchText(source);
    local messageKey = NormalizeBossMatchText(message);
    if sourceKey == "" or messageKey == "" then
        return nil, nil;
    end

    local instances = ParseGraph.GetOrderedInstanceDefinitions();
    for instanceIndex = 1, #instances do
        local instance = instances[instanceIndex];
        local bosses = type(instance and instance.bosses) == "table" and instance.bosses or {};
        for bossIndex = 1, #bosses do
            local boss = bosses[bossIndex];
            local startLines = type(boss) == "table" and boss.encounterStartLines or nil;
            if type(startLines) == "table" then
                for i = 1, #startLines do
                    local startLine = startLines[i];
                    if type(startLine) == "table"
                        and NormalizeBossMatchText(startLine.source) == sourceKey
                        and NormalizeBossMatchText(startLine.line) == messageKey then
                        return instance, bossIndex;
                    end
                end
            end
        end
    end

    return nil, nil;
end

function ParseGraph.BeginInstanceBossEncounter(instanceKey, tierKey, bossIndex)
    if instanceKey == nil or tierKey == nil or bossIndex == nil then
        return false;
    end

    local instance = ParseGraph.GetInstanceDefinition(instanceKey);
    bossIndex = tonumber(bossIndex) or 1;
    if instance == nil or type(instance.bosses) ~= "table" or instance.bosses[bossIndex] == nil then
        return false;
    end

    ParseGraph.ActiveInstanceKey = instanceKey;
    ParseGraph.ActiveInstanceTierKey = tierKey;
    ParseGraph.AutoInstanceBossIndex = bossIndex;
    ParseGraph.SelectedInstanceKey = instanceKey;
    ParseGraph.SelectedInstanceTierKey = tierKey;
    ParseGraph.SelectedInstanceBossIndex = bossIndex;
    ParseGraph.ManualInstanceTarget = nil;
    ParseGraph.PendingInstanceWipeTarget = nil;
    if ParseGraph.ResetAutoInstanceBossDefeats ~= nil then
        ParseGraph.ResetAutoInstanceBossDefeats(instanceKey, tierKey, bossIndex);
    end
    ParseGraph.ActiveInstanceEncounter = {
        instanceKey = instanceKey,
        tierKey = tierKey,
        bossIndex = bossIndex,
        startedAt = Turbine.Engine.GetGameTime() or 0
    };
    ParseGraph.SetLauncherButtonState();
    if ParseGraph.CurrentView == "instances" then
        ParseGraph.DrawInstancesView();
    end
    return true;
end

function ParseGraph.ProcessInstanceEncounterStartText(text)
    local instance, bossIndex = ParseGraph.GetInstanceEncounterStartTarget(text);
    if instance == nil or bossIndex == nil then
        return false;
    end

    local tierKey = ParseGraph.ActiveInstanceTierKey or ParseGraph.SelectedInstanceTierKey;
    if tierKey == nil then
        return false;
    end

    return ParseGraph.BeginInstanceBossEncounter(instance.key, tierKey, bossIndex);
end

function ParseGraph.GetActiveInstanceEncounterTarget()
    local active = ParseGraph.ActiveInstanceEncounter;
    if type(active) ~= "table" then
        return nil, nil, nil;
    end

    local now = Turbine.Engine.GetGameTime() or 0;
    local age = now - (tonumber(active.startedAt) or now);
    if age < 0 or age > 1800 then
        ParseGraph.ActiveInstanceEncounter = nil;
        return nil, nil, nil;
    end

    if active.instanceKey == nil or active.tierKey == nil or active.bossIndex == nil then
        ParseGraph.ActiveInstanceEncounter = nil;
        return nil, nil, nil;
    end

    return active.instanceKey, active.tierKey, tonumber(active.bossIndex) or 1;
end

function ParseGraph.EndActiveInstanceEncounter(instanceKey, tierKey, bossIndex)
    local active = ParseGraph.ActiveInstanceEncounter;
    if type(active) ~= "table" then
        return;
    end

    if active.instanceKey == instanceKey
        and active.tierKey == tierKey
        and tonumber(active.bossIndex) == tonumber(bossIndex) then
        ParseGraph.ActiveInstanceEncounter = nil;
    end
end

function ParseGraph.HideStatisticsFirstKillTooltip()
    if ParseGraph.StatisticsFirstKillTooltip ~= nil then
        ParseGraph.StatisticsFirstKillTooltip:SetVisible(false);
    end
end

