        tip.timeLabel:SetForeColor(Turbine.UI.Color(1.00, 0.93, 0.76, 0.28));
        tip.timeValue = Label(tip, 112, 32, 290, 18, "", "achievementDetail");
        tip.timeValue:SetForeColor(Turbine.UI.Color(0.95, 0.92, 0.88, 0.82));
        tip.playersLabel = Label(tip, 14, 56, 392, 18, "Players", "achievementDetail");
        tip.playersLabel:SetForeColor(Turbine.UI.Color(1.00, 0.93, 0.76, 0.28));
        tip.playerLineLabels = {};
        for i = 1, 12 do
            local playerLine = Label(tip, 20, 78 + ((i - 1) * 18), 380, 18, "", "achievementDetail");
            playerLine:SetForeColor(Turbine.UI.Color(0.95, 0.92, 0.88, 0.82));
            tip.playerLineLabels[i] = playerLine;
        end
        ParseGraph.StatisticsFirstKillTooltip = tip;
        ParseGraph.StatisticsFirstKillTooltipParent = parent;
    end

    local players = {};
    local seen = {};
    local function AddPlayerName(name)
        name = TrimText(name);
        if name == "" or name == "-" then
            return;
        end
        local key = LowerClean(name);
        if seen[key] == true then
            return;
        end
        seen[key] = true;
        players[#players + 1] = name;
    end

    if type(row.firstKillGroup) == "table" then
        for i = 1, #row.firstKillGroup do
            AddPlayerName(row.firstKillGroup[i]);
        end
    end
    if #players == 0 then
        local groupText = TrimText(row.firstKillGroupText);
        if groupText ~= "" and groupText ~= "-" then
            for name in string.gmatch(groupText, "([^,]+)") do
                AddPlayerName(name);
            end
        end
    end
    if #players == 0 then
        players[1] = "-";
    end
    table.sort(players, function(a, b)
        return LowerClean(a) < LowerClean(b);
    end);

    local playerLines = {};
    local currentLine = "";
    local maxLineChars = 58;
    for i = 1, #players do
        local part = tostring(players[i] or "");
        local candidate = currentLine == "" and part or (currentLine .. ", " .. part);
        if currentLine ~= "" and string.len(candidate) > maxLineChars then
            playerLines[#playerLines + 1] = currentLine .. ",";
            currentLine = part;
        else
            currentLine = candidate;
        end
    end
    if currentLine ~= "" then
        playerLines[#playerLines + 1] = currentLine;
    end
    if #playerLines == 0 then
        playerLines[1] = "-";
    end
    local visibleLines = math.min(#playerLines, 12);
    if #playerLines > visibleLines then
        playerLines[visibleLines] = tostring(playerLines[visibleLines] or "") .. "...";
    end

    local width = 420;
    local height = 82 + (visibleLines * 18);
    ParseGraph.StatisticsFirstKillTooltip:SetSize(width, height);
    ParseGraph.StatisticsFirstKillTooltip.topBorder:SetSize(width, 1);
    ParseGraph.StatisticsFirstKillTooltip.bottomBorder:SetPosition(0, height - 1);
    ParseGraph.StatisticsFirstKillTooltip.bottomBorder:SetSize(width, 1);
    ParseGraph.StatisticsFirstKillTooltip.leftBorder:SetSize(1, height);
    ParseGraph.StatisticsFirstKillTooltip.rightBorder:SetPosition(width - 1, 0);
    ParseGraph.StatisticsFirstKillTooltip.rightBorder:SetSize(1, height);
    ParseGraph.StatisticsFirstKillTooltip.timeValue:SetText(tostring(row.firstKillTime or "-"));
    for i = 1, 12 do
        local label = ParseGraph.StatisticsFirstKillTooltip.playerLineLabels[i];
        if i <= visibleLines then
            label:SetText(tostring(playerLines[i]));
            label:SetVisible(true);
        else
            label:SetText("");
            label:SetVisible(false);
        end
    end
    local parentWidth = parent.GetWidth ~= nil and parent:GetWidth() or 880;
    local x = math.max(8, math.min(420, parentWidth - width - 36));
    ParseGraph.StatisticsFirstKillTooltip:SetPosition(x, 124);
    ParseGraph.StatisticsFirstKillTooltip:SetVisible(true);
end

function ParseGraph.BindStatisticsFirstKillTooltip(control, parent, row)
    if control == nil then
        return;
    end
    control:SetMouseVisible(true);
    control.MouseEnter = function()
        ParseGraph.ShowStatisticsFirstKillTooltip(parent, row);
    end
    control.MouseLeave = function()
        ParseGraph.HideStatisticsFirstKillTooltip();
    end
end

function ParseGraph.IsStatisticsInstanceExpanded(instanceKey)
    if type(ParseGraph.StatisticsExpandedInstances) ~= "table" then
        ParseGraph.StatisticsExpandedInstances = {};
    end
    return ParseGraph.StatisticsExpandedInstances[tostring(instanceKey or "")] == true;
end

function ParseGraph.ToggleStatisticsInstanceExpanded(instanceKey)
    if type(ParseGraph.StatisticsExpandedInstances) ~= "table" then
        ParseGraph.StatisticsExpandedInstances = {};
    end
    instanceKey = tostring(instanceKey or "");
    ParseGraph.StatisticsExpandedInstances[instanceKey] = not (ParseGraph.StatisticsExpandedInstances[instanceKey] == true);
end

function ParseGraph.GetCombinedInstanceStatistics()
    local rows = {};
    local total = { name = "All instances", bestTime = nil, kills = 0, wipes = 0, mostCompletions = nil };
    local instances = ParseGraph.GetOrderedInstanceDefinitions();
    local tiers = ParseGraph.InstanceTiers or {};
    ParseGraph.StatisticsSearchLower = NormalizeBossMatchText(ParseGraph.InstanceStatisticsSearchText or "");
    table.sort(instances, function(a, b)
        local left = LowerClean((a and a.name) or "");
        local right = LowerClean((b and b.name) or "");
        left = string.gsub(left, "^the%s+", "");
        right = string.gsub(right, "^the%s+", "");
        if left == right then
            return LowerClean((a and a.key) or "") < LowerClean((b and b.key) or "");
        end
        return left < right;
    end);

    for instanceIndex = 1, #instances do
        local instance = instances[instanceIndex];
        local instanceKey = tostring(instance.key or "");
        local instanceRow = {
            rowType = "category",
            key = instanceKey,
            name = tostring(instance.name or ""),
            searchText = NormalizeBossMatchText(instance.name),
            bestTime = nil,
            kills = 0,
            wipes = 0
        };
        local detailRows = {};
        local bosses = type(instance.bosses) == "table" and instance.bosses or {};

        for tierIndex = 1, #tiers do
            local tier = tiers[tierIndex] or {};
            local tierKey = tostring(tier.key or "");
            local tierRow = {
                rowType = "tier",
                instanceKey = instanceKey,
                tierKey = tierKey,
                tierLabel = tostring(tier.label or tierKey),
                searchText = NormalizeBossMatchText(tostring(instance.name or "") .. " " .. tostring(tier.label or tierKey)),
                bestTime = nil,
                kills = 0,
                wipes = 0
            };
            local tierBossRows = {};

            for bossIndex = 1, #bosses do
                local boss = bosses[bossIndex] or {};
                local summary = ParseGraph.GetAccountInstanceBossSummary(instanceKey, tierKey, bossIndex, "damage");
                local bestTime = tonumber(summary.bestKillTime);
                if bestTime ~= nil and bestTime > 0 then
                    if instanceRow.bestTime == nil or bestTime < instanceRow.bestTime then
                        instanceRow.bestTime = bestTime;
                    end
                    if total.bestTime == nil or bestTime < total.bestTime then
                        total.bestTime = bestTime;
                    end
                    if tierRow.bestTime == nil or bestTime < tierRow.bestTime then
                        tierRow.bestTime = bestTime;
                    end
                end

                instanceRow.kills = instanceRow.kills + (tonumber(summary.kills) or 0);
                instanceRow.wipes = instanceRow.wipes + (tonumber(summary.wipes) or 0);
                tierRow.kills = tierRow.kills + (tonumber(summary.kills) or 0);
                tierRow.wipes = tierRow.wipes + (tonumber(summary.wipes) or 0);
                local killCount = tonumber(summary.kills) or 0;
                if killCount > 0 and (total.mostCompletions == nil or killCount > (tonumber(total.mostCompletions.kills) or 0)) then
                    total.mostCompletions = {
                        kills = killCount,
                        instanceKey = instanceKey,
                        instanceName = tostring(instance.name or ""),
                        bossIndex = bossIndex,
                        bossName = tostring(boss.name or ("Boss " .. tostring(bossIndex))),
                        tierKey = tierKey,
                        tierLabel = tostring(tier.label or tierKey)
                    };
                end
                tierBossRows[#tierBossRows + 1] = {
                    rowType = "boss",
                    instanceKey = instanceKey,
                    bossIndex = bossIndex,
                    bossName = tostring(boss.name or ("Boss " .. tostring(bossIndex))),
                    tierKey = tierKey,
                    tierLabel = tostring(tier.label or tierKey),
                    searchText = NormalizeBossMatchText(tostring(instance.name or "") .. " " .. tostring(boss.name or ("Boss " .. tostring(bossIndex))) .. " " .. tostring(tier.label or tierKey) .. " boss " .. tostring(bossIndex)),
                    bestTime = bestTime,
                    kills = tonumber(summary.kills) or 0,
                    wipes = tonumber(summary.wipes) or 0,
                    firstKillAt = summary.firstKillAt,
                    firstKillTime = summary.firstKillTime,
                    firstKillGroup = summary.firstKillGroup,
                    firstKillGroupText = ParseGraph.GetFirstKillGroupText(summary.firstKillGroup)
                };
            end

            detailRows[#detailRows + 1] = tierRow;
            for i = 1, #tierBossRows do
                detailRows[#detailRows + 1] = tierBossRows[i];
            end
        end

        total.kills = total.kills + instanceRow.kills;
        total.wipes = total.wipes + instanceRow.wipes;
        if ParseGraph.StatisticsSearchLower == "" then
            rows[#rows + 1] = instanceRow;
        else
            detailRows.searchRows = {};
            detailRows.instanceMatches = string.find(instanceRow.searchText or "", ParseGraph.StatisticsSearchLower, 1, true) ~= nil;
            detailRows.currentTier = nil;
            detailRows.currentTierMatches = false;
            detailRows.currentTierAdded = false;
            for i = 1, #detailRows do
                if detailRows[i].rowType == "tier" then
                    detailRows.currentTier = detailRows[i];
                    detailRows.currentTierMatches = detailRows.instanceMatches or (string.find(detailRows[i].searchText or "", ParseGraph.StatisticsSearchLower, 1, true) ~= nil);
                    detailRows.currentTierAdded = false;
                else
                    detailRows.rowMatches = detailRows.instanceMatches or detailRows.currentTierMatches or (string.find(detailRows[i].searchText or "", ParseGraph.StatisticsSearchLower, 1, true) ~= nil);
                    if detailRows.rowMatches then
                        if detailRows.currentTier ~= nil and detailRows.currentTierAdded ~= true then
                            detailRows.searchRows[#detailRows.searchRows + 1] = detailRows.currentTier;
                            detailRows.currentTierAdded = true;
                        end
                        detailRows.searchRows[#detailRows.searchRows + 1] = detailRows[i];
                    end
                end
            end
            if detailRows.instanceMatches or #detailRows.searchRows > 0 then
                rows[#rows + 1] = instanceRow;
            end
        end
        if ParseGraph.StatisticsSearchLower ~= "" and detailRows.instanceMatches then
            for i = 1, #detailRows do
                rows[#rows + 1] = detailRows[i];
            end
        elseif ParseGraph.StatisticsSearchLower ~= "" then
            for i = 1, #(detailRows.searchRows or {}) do
                rows[#rows + 1] = detailRows.searchRows[i];
            end
        elseif ParseGraph.IsStatisticsInstanceExpanded(instanceKey) then
            for i = 1, #detailRows do
                rows[#rows + 1] = detailRows[i];
            end
        end
    end

    return total, rows;
end

function ParseGraph.DeleteInstanceRecord(instanceKey, tierKey, bossIndex, mode, sourceIndex, sourceKey)
    instanceKey = tostring(instanceKey or "");
    tierKey = tostring(tierKey or "");
    mode = tostring(mode or "");
    sourceIndex = tonumber(sourceIndex);
    if sourceIndex == nil or sourceIndex < 1 then
        return;
    end

    local currentKey = ParseGraph.GetCurrentCharacterKey();
    local key = tostring(sourceKey or ParseGraph.ViewCharacterKey or currentKey);
    if key ~= currentKey then
        Turbine.Shell.WriteLine("ParseGraph: you can only delete instance entries for your current character.");
        return;
    end

    local entry = nil;
    if key == currentKey then
        entry = ParseGraph.EnsureAccountCharacter(currentKey, ParseGraph.GetCurrentCharacterName());
    else
        entry = ParseGraph.AccountData and ParseGraph.AccountData.characters and ParseGraph.AccountData.characters[key];
        if type(entry) == "table" then
            entry = NormalizeCharacterData(entry, key, entry.name);
        end
    end
    if type(entry) ~= "table" or type(entry.instances) ~= "table" then
        return;
    end

    local bossKey = "boss" .. tostring(tonumber(bossIndex) or 1);
    local records = entry.instances[instanceKey]
        and entry.instances[instanceKey][tierKey]
        and entry.instances[instanceKey][tierKey][bossKey]
        and entry.instances[instanceKey][tierKey][bossKey][mode];

    if type(records) ~= "table" or records[sourceIndex] == nil then
        return;
    end

    table.remove(records, sourceIndex);
    entry.updated = NowText();
    ParseGraph.AccountData.characters[key] = entry;
    ParseGraph.InstanceData = entry.instances;
    ParseGraph.SaveAccountData();
    if key == currentKey then
        ParseGraph.SaveCharacterEntryToCharacterScope(entry);
    end
    ParseGraph.DrawInstancesView();
end

function ParseGraph.NormalizeInstanceMetricMode(mode)
    mode = tostring(mode or ParseGraph.InstanceMetricMode or "damage");
    for i = 1, #ParseGraph.InstanceMetricModes do
        if ParseGraph.InstanceMetricModes[i].key == mode then
            return mode;
        end
    end
    return "damage";
end

function ParseGraph.GetInstanceMetricInfo(mode)
    mode = ParseGraph.NormalizeInstanceMetricMode(mode);
    for i = 1, #ParseGraph.InstanceMetricModes do
        if ParseGraph.InstanceMetricModes[i].key == mode then
            return ParseGraph.InstanceMetricModes[i];
        end
    end
    return ParseGraph.InstanceMetricModes[1];
end

function ParseGraph.UpdateInstanceMetricButtons()
    if ParseGraph.InstanceMetricButtons == nil then return end

    local selected = ParseGraph.NormalizeInstanceMetricMode(ParseGraph.InstanceMetricMode);
    local suppressSelection = ParseGraph.InstanceViewMode == "unmatched" or ParseGraph.InstanceViewMode == "statistics";
    for key, button in pairs(ParseGraph.InstanceMetricButtons) do
        if button ~= nil then
            ParseGraph.SetSidebarButtonSelected(button, suppressSelection ~= true and key == selected);
        end
    end
end

function ParseGraph.SetInstanceMetricMode(mode)
    ParseGraph.InstanceMetricMode = ParseGraph.NormalizeInstanceMetricMode(mode);
    if ParseGraph.InstanceViewMode == "unmatched" or ParseGraph.InstanceViewMode == "statistics" then
        ParseGraph.InstanceViewMode = "overview";
    end
    ParseGraph.UpdateInstanceMetricButtons();
    if ParseGraph.CurrentView == "instances" then
        ParseGraph.DrawInstancesView();
    end
end

function ParseGraph.UpdateInstanceButtons()
    if ParseGraph.InstanceButtons == nil then return end

    local selected = ParseGraph.GetInstanceDefinition(ParseGraph.SelectedInstanceKey);
    local selectedKey = selected and selected.key or "";
    for key, button in pairs(ParseGraph.InstanceButtons) do
        if button ~= nil then
            ParseGraph.SetSidebarButtonSelected(button, key == selectedKey);
        end
    end
end

function ParseGraph.SetSelectedInstance(key)
    local instance = ParseGraph.GetInstanceDefinition(key);
    if instance ~= nil then
        ParseGraph.SelectedInstanceKey = instance.key;
    end
    ParseGraph.ClearTemporaryInstanceTarget();
    ParseGraph.InstanceViewMode = "overview";
    ParseGraph.DrawInstancesView();
end

function ParseGraph.SetInstanceBossDetail(instanceKey, tierKey, bossIndex)
    local instance = ParseGraph.GetInstanceDefinition(instanceKey or ParseGraph.SelectedInstanceKey or "folly");
    if instance == nil then
        return;
    end
    local selectedTierKey = tostring(tierKey or "t1");
    ParseGraph.SelectedInstanceKey = instance.key;
    ParseGraph.SelectedInstanceTierKey = selectedTierKey;
    ParseGraph.SelectedInstanceBossIndex = tonumber(bossIndex) or 1;
    ParseGraph.TemporaryInstanceTarget = {
        instanceKey = instance.key,
        tierKey = selectedTierKey,
        bossIndex = ParseGraph.SelectedInstanceBossIndex
    };
    ParseGraph.InstanceViewMode = "boss";
    ParseGraph.DrawInstancesView();
end

local function DrawInstanceBossCard(parent, x, y, w, h, instanceKey, tierKey, bossIndex, boss, border)
    local labelColor = Turbine.UI.Color(1.00, 0.93, 0.76, 0.28);
    local valueColor = Turbine.UI.Color(0.95, 0.92, 0.88, 0.82);
    local normalFill = Turbine.UI.Color(1.00, 0.00, 0.00, 0.00);
    local hoverFill = ParseGraph.ParseRowHoverFill or Turbine.UI.Color(1.00, 0.04, 0.18, 0.34);
    local card = Panel(parent, x, y, w, h, 1.00);
    card:SetBackColor(normalFill);
    card.normalFill = normalFill;
    card.hoverFill = hoverFill;
    card:SetMouseVisible(true);
    card.instanceKey = instanceKey;
    card.tierKey = tierKey;
    card.bossIndex = bossIndex;
    card.MouseClick = function(sender, args)
        if ParseGraph.IsRightMouseButton(args) then
            ParseGraph.ShowInstanceBossContextMenu(sender, sender.instanceKey, sender.tierKey, sender.bossIndex, args);
            return;
        end
        if ParseGraph.IsLeftMouseButton(args) then
            ParseGraph.HideInstanceBossContextMenu();
            ParseGraph.SetInstanceBossDetail(sender.instanceKey, sender.tierKey, sender.bossIndex);
        end
    end
    DrawAchievementBorder(card, w, h, border);

    boss = boss or {};
    local title = Label(card, 0, 2, w, 28, "Boss " .. tostring(bossIndex), "achievementTitle");
    title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    title:SetMouseVisible(false);

    local bossName = Label(card, 10, 27, w - 20, 18, tostring(boss.name or ""), "achievementDetail");
    bossName:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    bossName:SetForeColor(Turbine.UI.Color(1.00, 0.93, 0.82, 0.42));
    bossName:SetMouseVisible(false);
        bossName:SetZOrder(5);

    local lineY = 50;

    DrawBlock(card, 18, lineY, w - 36, 1, border);

    local metric = ParseGraph.NormalizeInstanceMetricMode(ParseGraph.InstanceMetricMode);
    local summary = ParseGraph.GetInstanceBossSummary(instanceKey, tierKey, bossIndex, metric);
    local rows = nil;
    if metric == "healing" then
        rows = {
            { label = "HPS", value = summary.bestTotalDps ~= nil and FormatNumber(summary.bestTotalDps) or "-" },
            { label = "Average HPS", value = summary.averageTotalDps ~= nil and FormatNumber(summary.averageTotalDps) or "-" },
            { label = "Best time", value = FormatKillTime(summary.bestKillTime) },
            { label = "Average time", value = FormatKillTime(summary.averageKillTime) }
        };
    elseif metric == "taken" then
        rows = {
            { label = "TPS", value = summary.bestTotalDps ~= nil and FormatNumber(summary.bestTotalDps) or "-" },
            { label = "Average TPS", value = summary.averageTotalDps ~= nil and FormatNumber(summary.averageTotalDps) or "-" },
            { label = "Best time", value = FormatKillTime(summary.bestKillTime) },
            { label = "Average time", value = FormatKillTime(summary.averageKillTime) }
        };
    elseif IsInstanceBossMultiTarget(boss) then
        rows = {
            { label = "Total DPS", value = summary.bestTotalDps ~= nil and FormatNumber(summary.bestTotalDps) or "-" },
            { label = "Average DPS", value = summary.averageTotalDps ~= nil and FormatNumber(summary.averageTotalDps) or "-" },
            { label = "Best time", value = FormatKillTime(summary.bestKillTime) },
            { label = "Average time", value = FormatKillTime(summary.averageKillTime) }
        };
    else
        rows = {
            { label = "Boss DPS", value = summary.bestBossDps ~= nil and FormatNumber(summary.bestBossDps) or "-" },
            { label = "Average DPS", value = summary.averageBossDps ~= nil and FormatNumber(summary.averageBossDps) or "-" },
            { label = "Best time", value = FormatKillTime(summary.bestKillTime) },
            { label = "Average time", value = FormatKillTime(summary.averageKillTime) }
        };
    end
    rows[#rows + 1] = { label = "Kills", value = FormatNumber(tonumber(summary.kills) or 0) };
    rows[#rows + 1] = { label = "Wipes", value = FormatNumber(tonumber(summary.wipes) or 0) };

    local rowY = lineY + 6;
    for i = 1, #rows do
        local row = rows[i];
        local l = Label(card, 18, rowY, 120, 17, row.label, "achievementDetail");
        l:SetFont(Turbine.UI.Lotro.Font.TrajanPro15);
        l:SetForeColor(labelColor);
        l:SetMouseVisible(false);
        local v = Label(card, w - 108, rowY, 86, 17, row.value, "achievementDetail");
        v:SetFont(Turbine.UI.Lotro.Font.TrajanPro15);
        v:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        v:SetForeColor(valueColor);
        v:SetMouseVisible(false);
        rowY = rowY + 14;
    end

    local clickLayer = Turbine.UI.Control();
    clickLayer:SetParent(card);
    clickLayer:SetPosition(0, 0);
    clickLayer:SetSize(w, h);
    clickLayer:SetMouseVisible(true);
    clickLayer:SetZOrder(100);
    clickLayer.instanceKey = instanceKey;
    clickLayer.tierKey = tierKey;
    clickLayer.bossIndex = bossIndex;
    clickLayer.card = card;
    clickLayer.MouseEnter = function(sender)
        if sender.card ~= nil then
            sender.card:SetBackColor(sender.card.hoverFill or hoverFill);
        end
    end
    clickLayer.MouseLeave = function(sender)
        if sender.card ~= nil then
            sender.card:SetBackColor(sender.card.normalFill or normalFill);
        end
    end
    clickLayer.MouseClick = function(sender, args)
        if ParseGraph.IsRightMouseButton(args) then
            ParseGraph.ShowInstanceBossContextMenu(sender.card or sender, sender.instanceKey, sender.tierKey, sender.bossIndex, args);
            return;
        end
        if ParseGraph.IsLeftMouseButton(args) then
            ParseGraph.HideInstanceBossContextMenu();
            ParseGraph.SetInstanceBossDetail(sender.instanceKey, sender.tierKey, sender.bossIndex);
        end
    end
end

local function GetSortedInstanceRecords(instanceKey, tierKey, bossIndex, metric)
    local records = ParseGraph.GetInstanceBossCombinedRecords(instanceKey, tierKey, bossIndex, metric);
    table.sort(records, function(a, b)
        local at = tonumber(a and a.gameTime) or 0;
        local bt = tonumber(b and b.gameTime) or 0;
        if at == bt then
            return tostring(a and a.time or "") < tostring(b and b.time or "");
        end
        return at < bt;
    end);
    return records;
end

local function DrawInstanceDetailSummaryBox(parent, x, y, w, h, title, stats, border, metric)
    local labelColor = Turbine.UI.Color(1.00, 0.93, 0.76, 0.28);
