local function DrawInstanceBossDetailGraph(parent, x, y, w, h, records, metric)
    local axisColor = Turbine.UI.Color(1.00, 0.42, 0.42, 0.42);
    local gridColor = Turbine.UI.Color(1.00, 0.24, 0.24, 0.24);
    local entryColor = Turbine.UI.Color(0.95, 0.18, 0.55, 0.90);
    local avgColor = Turbine.UI.Color(0.95, 0.96, 0.50, 0.16);
    local bestColor = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local metricInfo = ParseGraph.GetInstanceMetricInfo(metric);
    local graph = Panel(parent, x, y, w, h, 1.00);
    DrawBlock(graph, 0, 0, w, h, Turbine.UI.Color(1.00, 0.02, 0.02, 0.03));

    local function DrawGraphPoint(parentControl, px, py, size, color)
        DrawBlock(parentControl, px - math.floor(size / 2), py - math.floor(size / 2), size, size, color);
    end

    local function DrawGraphLine(parentControl, x1, y1, x2, y2, size, color)
        local dx = x2 - x1;
        local dy = y2 - y1;
        local distance = math.max(math.abs(dx), math.abs(dy));
        if distance < 1 then
            DrawGraphPoint(parentControl, x1, y1, size, color);
            return;
        end

        local steps = math.max(1, math.ceil(distance / 6));
        for i = 0, steps do
            local t = i / steps;
            DrawGraphPoint(parentControl, math.floor(x1 + (dx * t)), math.floor(y1 + (dy * t)), size, color);
        end
    end

    local function DrawGraphImageMarker(parentControl, cx, cy, size, image)
        if image == nil or tostring(image) == "" then
            return nil;
        end

        local marker = Turbine.UI.Control();
        marker:SetParent(parentControl);
        marker:SetPosition(math.floor(cx - (size / 2)), math.floor(cy - (size / 2)));
        marker:SetSize(size, size);
        local ok = pcall(function()
            marker:SetBackground(tostring(image));
        end);
        if not ok then
            marker:SetParent(nil);
            return nil;
        end
        marker:SetMouseVisible(false);
        return marker;
    end

    local function DrawGraphLabel(parentControl, lx, ly, lw, lh, text, alignRight)
        local label = Label(parentControl, lx, ly, lw, lh, text, "small");
        label:SetForeColor(Turbine.UI.Color(0.85, 0.84, 0.84, 0.84));
        if alignRight then
            label:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        else
            label:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
        end
        return label;
    end

    local function GetNiceTickStep(range)
        range = tonumber(range) or 0;
        if range <= 0 then
            return 1;
        end

        local rough = math.max(1, range / 4);
        local exponent = math.floor(math.log(rough) / math.log(10));
        local magnitude = math.pow(10, exponent);
        local normalized = rough / magnitude;
        local nice = 10;
        if normalized <= 1 then
            nice = 1;
        elseif normalized <= 2 then
            nice = 2;
        elseif normalized <= 5 then
            nice = 5;
        end

        return nice * magnitude;
    end

    local graphIconPath = ParseGraph.GraphIconPath or "";
    local legendY = 5;
    DrawGraphLine(graph, 18, legendY + 8, 38, legendY + 8, 2, entryColor);
    DrawGraphImageMarker(graph, 28, legendY + 8, 5, graphIconPath .. "graph_dot.tga");
    DrawGraphLabel(graph, 44, legendY, 64, 16, metricInfo.rateLabel, false);
    DrawGraphLine(graph, 120, legendY + 8, 140, legendY + 8, 2, avgColor);
    DrawGraphLabel(graph, 146, legendY, 112, 16, "All-time avg", false);
    DrawGraphImageMarker(graph, 272, legendY + 8, 7, graphIconPath .. "personal_best_star.tga");
    local bestLegend = DrawGraphLabel(graph, 286, legendY, 60, 16, "Best", false);
    bestLegend:SetForeColor(bestColor);

    if type(records) ~= "table" or #records == 0 then
        local empty = Label(graph, 0, 28, w, h - 28, "No CombatAnalysis posts saved for this boss yet.", "small");
        empty:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        return;
    end

    local maxShown = 60;
    local firstRecordIndex = math.max(1, #records - maxShown + 1);
    local points = {};
    local runningTotal = 0;
    local runningCount = 0;
    local bestIndex = nil;
    local bestValue = nil;

    for i = 1, #records do
        local value = GetRecordDisplayDps(records[i]);
        if value ~= nil then
            runningTotal = runningTotal + value;
            runningCount = runningCount + 1;
            if bestValue == nil or value > bestValue then
                bestValue = value;
                bestIndex = i;
            end
            if i >= firstRecordIndex then
                points[#points + 1] = {
                    index = i,
                    value = value,
                    avg = runningTotal / runningCount
                };
            end
        end
    end

    local shown = #points;
    if shown == 0 then
        local empty = Label(graph, 0, 28, w, h - 28, "No CombatAnalysis posts saved for this boss yet.", "small");
        empty:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        return;
    end

    local minValue = nil;
    local maxValue = nil;
    for i = 1, shown do
        local value = tonumber(points[i].value) or 0;
        local avg = tonumber(points[i].avg) or value;
        if minValue == nil or value < minValue then minValue = value end
        if maxValue == nil or value > maxValue then maxValue = value end
        if avg ~= nil then
            if minValue == nil or avg < minValue then minValue = avg end
            if maxValue == nil or avg > maxValue then maxValue = avg end
        end
    end

    minValue = tonumber(minValue) or 0;
    maxValue = tonumber(maxValue) or (minValue + 1);
    if maxValue <= minValue then
        local padding = math.max(1, maxValue * 0.05);
        minValue = math.max(0, minValue - padding);
        maxValue = maxValue + padding;
    else
        local padding = math.max(1, (maxValue - minValue) * 0.08);
        minValue = math.max(0, minValue - padding);
        maxValue = maxValue + padding;
    end

    local tickStep = GetNiceTickStep(maxValue - minValue);
    minValue = math.floor(minValue / tickStep) * tickStep;
    maxValue = math.ceil(maxValue / tickStep) * tickStep;
    if maxValue <= minValue then
        maxValue = minValue + tickStep;
    end

    local plotX = 64;
    local plotY = 30;
    local plotW = w - 78;
    local plotH = h - 54;

    local function ToY(value)
        local ratio = (value - minValue) / (maxValue - minValue);
        if ratio < 0 then ratio = 0 end
        if ratio > 1 then ratio = 1 end
        return plotY + plotH - (ratio * plotH);
    end

    local function ToX(pointIndex)
        if shown <= 1 then return plotX + (plotW / 2) end
        return plotX + ((pointIndex - 1) / (shown - 1)) * plotW;
    end

    DrawBlock(graph, plotX, plotY + plotH, plotW, 1, axisColor);
    DrawBlock(graph, plotX, plotY, 1, plotH, axisColor);

    local tickValue = minValue;
    local guard = 0;
    while tickValue <= maxValue and guard < 12 do
        local gy = ToY(tickValue);
        DrawBlock(graph, plotX, gy, plotW, 1, gridColor);
        DrawGraphLabel(graph, 2, gy - 8, plotX - 8, 16, FormatNumber(tickValue), true);
        tickValue = tickValue + tickStep;
        guard = guard + 1;
    end

    local labelEvery = 1;
    if shown > 45 then
        labelEvery = 10;
    elseif shown > 25 then
        labelEvery = 5;
    elseif shown > 14 then
        labelEvery = 2;
    end

    for pointIndex = 1, shown do
        local gx = ToX(pointIndex);
        DrawBlock(graph, gx, plotY, 1, plotH, gridColor);
        if ((pointIndex - 1) % labelEvery == 0) or pointIndex == shown then
            local tickLabel = DrawGraphLabel(graph, gx - 16, plotY + plotH + 3, 32, 16, tostring(points[pointIndex].index), false);
            tickLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        end
    end

    for i = 2, shown do
        DrawGraphLine(graph, ToX(i - 1), ToY(points[i - 1].avg), ToX(i), ToY(points[i].avg), 2, avgColor);
    end

    for i = 2, shown do
        DrawGraphLine(graph, ToX(i - 1), ToY(points[i - 1].value), ToX(i), ToY(points[i].value), 2, entryColor);
    end

    for i = 1, shown do
        DrawGraphImageMarker(graph, ToX(i), ToY(points[i].value), 5, graphIconPath .. "graph_dot.tga");
    end

    if bestIndex ~= nil then
        for i = 1, shown do
            if points[i].index == bestIndex then
                DrawGraphImageMarker(graph, ToX(i), ToY(points[i].value), 7, graphIconPath .. "personal_best_star.tga");
                break;
            end
        end
    end
end

function ParseGraph.DrawInstanceBossDetailView(panel, instance, tierKey, bossIndex)
    ParseGraph.ResetInstanceHealthTooltip();
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local lineColor = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local boss = instance.bosses[bossIndex] or {};
    local tierLabel = ParseGraph.GetInstanceTierLabel(tierKey);
    local metric = ParseGraph.NormalizeInstanceMetricMode(ParseGraph.InstanceMetricMode);
    local metricInfo = ParseGraph.GetInstanceMetricInfo(metric);
    local records = GetSortedInstanceRecords(instance.key, tierKey, bossIndex, metric);
    local sessionRecords = {};
    for i = 1, #records do
        if (not ParseGraph.IsCombineSameClassActive() or tostring(records[i].sourceKey or ParseGraph.GetCurrentCharacterKey()) == ParseGraph.GetCurrentCharacterKey())
            and tonumber(records[i].gameTime) ~= nil
            and tonumber(records[i].gameTime) >= (tonumber(ParseGraph.InstanceSessionStartGameTime) or 0) then
            sessionRecords[#sessionRecords + 1] = records[i];
        end
    end

    local title = Label(panel, 0, 6, panel:GetWidth(), 26, tierLabel .. " - Boss " .. tostring(bossIndex), "huge");
    title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    title:SetForeColor(gold);
    local name = Label(panel, 0, 34, panel:GetWidth(), 20, tostring(boss.name or ""), "big");
    name:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);

    local back = ParseGraph.CreateActionButton(panel, 690, panel:GetHeight() - 23, 130, 22, "Back", function()
        ParseGraph.ClearTemporaryInstanceTarget();
        ParseGraph.InstanceViewMode = "overview";
        ParseGraph.DrawInstancesView();
    end);

    DrawInstanceBossDetailGraph(panel, 38, 64, 764, 150, records, metric);
    DrawInstanceDetailSummaryBox(panel, 15, 228, 395, 160, "Current Session", ParseGraph.GetInstanceRecordSummary(sessionRecords), border, metric);
    DrawInstanceDetailSummaryBox(panel, 430, 228, 395, 160, "All-time Summary", ParseGraph.GetInstanceRecordSummary(records), border, metric);

    local latestTitle = Label(panel, 15, 402, 220, 24, "Latest entries", "big");
    latestTitle:SetForeColor(gold);

    local healthTooltipText = metric == "damage" and FormatInstanceHealthTooltip(instance.key, tierKey, bossIndex) or nil;
    local headers = {
        { text = "#", x = 15, w = 40, align = "left" },
        { text = "Date / Time", x = 70, w = 120, align = "left" },
        { text = "Type", x = 205, w = 70, align = "center" },
        { text = metricInfo.rateLabel, x = 300, w = 80, align = "right" },
        { text = "Kill time", x = 405, w = 95, align = "right" },
        { text = metricInfo.amountLabel, x = 500, w = 160, align = "center", key = "amount" },
        { text = "%", x = 670, w = 45, align = "right" }
    };
    for i = 1, #headers do
        local header = headers[i];
        local h = Label(panel, header.x, 436, header.w, 22, header.text, "achievementDetail");
        if header.align == "right" then
            h:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        elseif header.align == "center" then
            h:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        else
            h:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
        end
        if metric == "damage" and header.key == "amount" then
            ParseGraph.BindInstanceHealthTooltip(h, panel, healthTooltipText, 436);
        end
    end
    DrawBlock(panel, 15, 460, 810, 1, lineColor);

    local rowY = 464;
    local rowColor = Turbine.UI.Color(1.00, 1.00, 1.00, 1.00);
    local damageColor = Turbine.UI.Color(1.00, 0.45, 0.78, 1.00);
    local healingColor = Turbine.UI.Color(1.00, 0.30, 1.00, 0.30);
    local takenColor = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local percentColor = Turbine.UI.Color(1.00, 0.30, 1.00, 0.30);
    local shown = 0;
    for i = #records, 1, -1 do
        shown = shown + 1;
        if shown > 3 then break end
        local record = records[i];
        Label(panel, 15, rowY, 40, 22, "#" .. tostring(i), "achievementDetail"):SetForeColor(rowColor);
        Label(panel, 70, rowY, 120, 22, tostring(record.time or ""), "achievementDetail"):SetForeColor(rowColor);
        local typeLabel = Label(panel, 205, rowY, 70, 22, GetRecordTypeLabel(record), "achievementDetail");
        typeLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        typeLabel:SetForeColor(rowColor);
        local rateColor = rowColor;
        if metric == "healing" then
            rateColor = healingColor;
        elseif metric == "taken" then
            rateColor = takenColor;
        end
        local dps = Label(panel, 300, rowY, 80, 22, FormatNumber(GetRecordDisplayDps(record)), "achievementDetail");
        dps:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        dps:SetForeColor(rateColor);
        local time = Label(panel, 405, rowY, 95, 22, FormatKillTime(record.durationSeconds), "achievementDetail");
        time:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        time:SetForeColor(rowColor);
        local amountText = tostring(record.amountText or record.damageText or "-");
        local health = metric == "damage" and ParseGraph.GetInstanceBossHealth(instance.key, tierKey, bossIndex) or nil;
        local healthText = health ~= nil and FormatCompactAmount(health) or "-";
        local percentText = "-";
        if metric == "damage" and health ~= nil and tonumber(record.amount or record.damage) ~= nil then
            percentText = tostring(Round(((tonumber(record.amount or record.damage) or 0) / health) * 100)) .. "%";
        end
        if metric == "damage" then
            local amount = Label(panel, 500, rowY, 78, 22, amountText, "achievementDetail");
            amount:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
            amount:SetForeColor(damageColor);
            ParseGraph.BindInstanceHealthTooltip(amount, panel, healthTooltipText, rowY);
            local divider = Label(panel, 582, rowY, 12, 22, "/", "achievementDetail");
            divider:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
            divider:SetForeColor(rowColor);
            local bossHealth = Label(panel, 598, rowY, 68, 22, healthText, "achievementDetail");
            bossHealth:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
            bossHealth:SetForeColor(rowColor);
            ParseGraph.BindInstanceHealthTooltip(bossHealth, panel, healthTooltipText, rowY);
        else
            local amount = Label(panel, 500, rowY, 160, 22, amountText, "achievementDetail");
            amount:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
            amount:SetForeColor(rowColor);
        end
        local percent = Label(panel, 670, rowY, 45, 22, percentText, "achievementDetail");
        percent:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        percent:SetForeColor(percentText ~= "-" and percentColor or rowColor);
        local recordSourceKey = tostring(record.sourceKey or ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey());
        local canDelete = recordSourceKey == ParseGraph.GetCurrentCharacterKey();
        if canDelete then
            local del = ParseGraph.CreateRowButton(panel, 765, rowY, 60, 20, "Delete", "row_delete_button", function(sender)
                ParseGraph.DeleteInstanceRecord(sender.instanceKey, sender.tierKey, sender.bossIndex, sender.sourceMode, sender.sourceIndex, sender.sourceKey);
            end);
            del.instanceKey = instance.key;
            del.tierKey = tierKey;
            del.bossIndex = bossIndex;
            del.sourceMode = record.sourceMode;
            del.sourceIndex = record.sourceIndex;
            del.sourceKey = recordSourceKey;
        end
        DrawBlock(panel, 15, rowY + 24, 810, 1, lineColor);
        rowY = rowY + 28;
    end

    if #records == 0 then
        local empty = Label(panel, 15, 464, 810, 26, "Post your CombatAnalysis line after this boss to start filling this page.", "achievementDetail");
        empty:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    end
end

function ParseGraph.DrawInstanceStatisticsView(panel)
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local labelColor = Turbine.UI.Color(1.00, 0.93, 0.76, 0.28);
    local valueColor = Turbine.UI.Color(0.95, 0.92, 0.88, 0.82);
    local mutedColor = Turbine.UI.Color(0.72, 0.80, 0.76, 0.72);
    local tableFill = Turbine.UI.Color(1.00, 0.00, 0.00, 0.00);
    local rowNormalFill = Turbine.UI.Color(1.00, 0.012, 0.012, 0.012);
    local rowAlternateFill = Turbine.UI.Color(1.00, 0.055, 0.055, 0.060);
    local rowHoverFill = ParseGraph.ParseRowHoverFill or Turbine.UI.Color(1.00, 0.04, 0.18, 0.34);
    local categoryFill = Turbine.UI.Color(1.00, 0.11, 0.08, 0.02);
    local categoryHoverFill = Turbine.UI.Color(1.00, 0.18, 0.12, 0.03);
    local tierFill = Turbine.UI.Color(1.00, 0.035, 0.045, 0.052);
    local tierHoverFill = Turbine.UI.Color(1.00, 0.08, 0.11, 0.13);
    local total, rows = ParseGraph.GetCombinedInstanceStatistics();

    local title = Label(panel, 0, 4, panel:GetWidth(), 28, "Statistics", "huge");
    title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    title:SetForeColor(gold);
    local subtitle = Label(panel, 0, 32, panel:GetWidth(), 20, "Combined instance stats", "big");
    subtitle:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    subtitle:SetForeColor(valueColor);

    local cardH = 64;
    local gap = 14;
    local most = total.mostCompletions;
    local mostBoss = "-";
    local mostInstance = "-";
    local mostCount = "-";
    if most ~= nil then
        local mostKills = tonumber(most.kills) or 0;
        mostBoss = ParseGraph.TruncateStatisticsText(tostring(most.bossName or "-") .. " - " .. tostring(most.tierLabel or ""), 34);
        mostInstance = ParseGraph.TruncateStatisticsText(tostring(most.instanceName or "-"), 38);
        mostCount = FormatNumber(mostKills);
    end
    local cards = {
        { label = "Most completions", value = mostBoss, detail = mostInstance, countValue = mostCount, w = 430 },
        { label = "Total kills", value = FormatNumber(total.kills), w = 145 },
        { label = "Total wipes", value = FormatNumber(total.wipes), w = 145 }
    };
    local cardsW = 0;
    for i = 1, #cards do
        cardsW = cardsW + (tonumber(cards[i].w) or 0);
        if i > 1 then
            cardsW = cardsW + gap;
        end
    end

    local cardX = math.floor((panel:GetWidth() - cardsW) / 2);
    for i = 1, #cards do
        local cardW = tonumber(cards[i].w) or 145;
        local card = Panel(panel, cardX, 62, cardW, cardH, 1.00);
        DrawAchievementBorder(card, cardW, cardH, border);
        if cards[i].countValue ~= nil then
            local splitX = math.floor(cardW * 0.65) + 70;
            DrawBlock(card, splitX, 10, 1, cardH - 18, border);
            local leftW = splitX - 14;
            local rightW = cardW - splitX - 10;
            local cardLabel = Label(card, 10, 8, leftW, 18, cards[i].label, "achievementDetail");
            cardLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
            cardLabel:SetForeColor(labelColor);
            local cardValue = Label(card, 10, 29, leftW, 18, cards[i].value, "achievementDetail");
            cardValue:SetFont(Turbine.UI.Lotro.Font.TrajanProBold16);
            cardValue:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
            cardValue:SetForeColor(gold);
            local cardDetail = Label(card, 10, 47, leftW, 14, cards[i].detail, "small");
            cardDetail:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
            cardDetail:SetForeColor(valueColor);
            local cardCount = Label(card, splitX + 5, 6, rightW, cardH - 12, cards[i].countValue, "achievementTitle");
            cardCount:SetFont(Turbine.UI.Lotro.Font.TrajanProBold36);
            cardCount:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
            cardCount:SetForeColor(gold);
        else
            local cardLabel = Label(card, 0, 8, cardW, 18, cards[i].label, "achievementDetail");
            cardLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
            cardLabel:SetForeColor(labelColor);
            local cardValue = Label(card, 0, 22, cardW, cardH - 26, cards[i].value, "achievementTitle");
            cardValue:SetFont(Turbine.UI.Lotro.Font.TrajanProBold36);
            cardValue:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
            cardValue:SetForeColor(gold);
        end
        cardX = cardX + cardW + gap;
    end

    ParseGraph.InstanceStatisticsSearchLabel = Label(panel, 38, 136, 70, 22, "Search", "achievementDetail");
    ParseGraph.InstanceStatisticsSearchLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    ParseGraph.InstanceStatisticsSearchLabel:SetForeColor(labelColor);
    DrawBlock(panel, 104, 134, 716, 1, border);
    DrawBlock(panel, 104, 158, 716, 1, border);
    DrawBlock(panel, 104, 134, 1, 25, border);
    DrawBlock(panel, 819, 134, 1, 25, border);
    ParseGraph.InstanceStatisticsSearchBox = Turbine.UI.Lotro.TextBox();
    ParseGraph.InstanceStatisticsSearchBox:SetParent(panel);
    ParseGraph.InstanceStatisticsSearchBox:SetPosition(108, 136);
    ParseGraph.InstanceStatisticsSearchBox:SetSize(708, 20);
    ParseGraph.InstanceStatisticsSearchBox:SetFont(Turbine.UI.Lotro.Font.TrajanPro14);
    ParseGraph.InstanceStatisticsSearchBox:SetBackColor(Turbine.UI.Color(1.00, 0.02, 0.02, 0.02));
    ParseGraph.InstanceStatisticsSearchBox:SetForeColor(valueColor);
    ParseGraph.InstanceStatisticsSearchBox:SetText(tostring(ParseGraph.InstanceStatisticsSearchText or ""));
    ParseGraph.InstanceStatisticsSearchBox:SetZOrder(20);

    local headerY = 176;
    DrawBlock(panel, 13, headerY - 8, 814, 1, border);

    local function Header(x, w, text, alignment)
        local header = Label(panel, x, headerY, w, 22, text, "achievementDetail");
        header:SetTextAlignment(alignment);
        header:SetForeColor(labelColor);
        return header;
    end

    Header(38, 275, "Boss", Turbine.UI.ContentAlignment.MiddleLeft);
    Header(328, 54, "Tier", Turbine.UI.ContentAlignment.MiddleCenter);
    Header(397, 92, "Best time", Turbine.UI.ContentAlignment.MiddleRight);
    Header(512, 55, "Kills", Turbine.UI.ContentAlignment.MiddleRight);
    Header(582, 55, "Wipes", Turbine.UI.ContentAlignment.MiddleRight);
    Header(670, 120, "First kill", Turbine.UI.ContentAlignment.MiddleCenter);
    DrawBlock(panel, 13, headerY + 26, 814, 1, border);

    local rowH = 32;
    local categoryH = 30;
    local tierH = 26;
    local listX = 13;
    local listY = headerY + 34;
    local listW = 814;
    local listH = panel:GetHeight() - listY - 8;
    local rowsBack = DrawBlock(panel, listX, listY, listW, listH, tableFill);
    rowsBack:SetMouseVisible(false);
    rowsBack:SetZOrder(1);

    local list = Turbine.UI.ListBox();
    list:SetParent(panel);
    list:SetPosition(listX, listY);
    list:SetSize(listW, listH);
    list:SetOrientation(Turbine.UI.Orientation.Vertical);
    list:SetBackColor(tableFill);
    list:SetMouseVisible(true);
    list:SetZOrder(2);
    pcall(function()
        list:SetClipMode(true);
    end);

    local scroll = Turbine.UI.Lotro.ScrollBar();
    scroll:SetParent(panel);
    scroll:SetOrientation(Turbine.UI.Orientation.Vertical);
    scroll:SetPosition(830, listY);
    scroll:SetSize(10, listH);
    scroll:SetBackColor(tableFill);
    scroll:SetZOrder(3);
    list:SetVerticalScrollBar(scroll);

    local function AddCell(parent, x, y, w, h, text, size, alignment, color, font)
        local cell = Label(parent, x, y, w, h, text, size);
        if font ~= nil then
            cell:SetFont(font);
        end
        cell:SetTextAlignment(alignment);
        cell:SetForeColor(color);
        cell:SetMouseVisible(false);
        cell:SetZOrder(5);
        return cell;
    end

    local function DrawStatisticsRows()
        ParseGraph.HideStatisticsFirstKillTooltip();
        total, rows = ParseGraph.GetCombinedInstanceStatistics();
        list:ClearItems();

        local totalHeight = 0;
        for i = 1, #rows do
            if rows[i].rowType == "category" then
                totalHeight = totalHeight + categoryH;
            elseif rows[i].rowType == "tier" then
                totalHeight = totalHeight + tierH;
            else
                totalHeight = totalHeight + rowH;
            end
        end
        scroll:SetVisible(totalHeight > listH);

        local dataRowIndex = 0;
        for i = 1, #rows do
            local row = rows[i];
            local isCategory = row.rowType == "category";
            local isTier = row.rowType == "tier";
            local height = isCategory and categoryH or (isTier and tierH or rowH);
            local rowFill = categoryFill;
            local hoverFill = categoryHoverFill;
            if isTier then
                rowFill = tierFill;
                hoverFill = tierHoverFill;
            elseif not isCategory then
                dataRowIndex = dataRowIndex + 1;
                rowFill = rowNormalFill;
                if dataRowIndex % 2 == 0 then
                    rowFill = rowAlternateFill;
                end
                hoverFill = rowHoverFill;
            end

            local rowPanel = Turbine.UI.Control();
            rowPanel:SetSize(listW, height);
            rowPanel:SetBackColor(rowFill);
            rowPanel:SetMouseVisible(true);
            rowPanel.instanceKey = row.key;
            rowPanel.normalFill = rowFill;
            rowPanel.hoverFill = hoverFill;
            rowPanel.MouseEnter = function(sender)
                sender:SetBackColor(sender.hoverFill);
            end
            rowPanel.MouseLeave = function(sender)
                sender:SetBackColor(sender.normalFill);
            end
            pcall(function()
                rowPanel:SetClipMode(true);
            end);
            list:AddItem(rowPanel);
            local divider = DrawBlock(rowPanel, 0, height - 1, listW, 1, Turbine.UI.Color(1.00, 0.22, 0.18, 0.08));
            divider:SetMouseVisible(false);

            if isCategory then
                rowPanel.MouseClick = function(sender)
                    ParseGraph.ToggleStatisticsInstanceExpanded(sender.instanceKey);
                    DrawStatisticsRows();
                end
                AddCell(rowPanel, 20, 0, 18, height, (ParseGraph.StatisticsSearchLower ~= "" or ParseGraph.IsStatisticsInstanceExpanded(row.key)) and "-" or "+", "achievementDetail", Turbine.UI.ContentAlignment.MiddleCenter, labelColor, Turbine.UI.Lotro.Font.TrajanProBold16);
                AddCell(rowPanel, 42, 0, 342, height, tostring(row.name or ""), "big", Turbine.UI.ContentAlignment.MiddleLeft, gold, Turbine.UI.Lotro.Font.TrajanProBold16);
                AddCell(rowPanel, 397, 0, 92, height, "", "achievementDetail", Turbine.UI.ContentAlignment.MiddleRight, gold, Turbine.UI.Lotro.Font.TrajanPro14);
                AddCell(rowPanel, 512, 0, 55, height, FormatNumber(row.kills), "achievementDetail", Turbine.UI.ContentAlignment.MiddleRight, valueColor, Turbine.UI.Lotro.Font.TrajanPro14);
                AddCell(rowPanel, 582, 0, 55, height, FormatNumber(row.wipes), "achievementDetail", Turbine.UI.ContentAlignment.MiddleRight, valueColor, Turbine.UI.Lotro.Font.TrajanPro14);
            elseif isTier then
                AddCell(rowPanel, 48, 0, 265, height, tostring(row.tierLabel or ""), "achievementDetail", Turbine.UI.ContentAlignment.MiddleLeft, labelColor, Turbine.UI.Lotro.Font.TrajanProBold16);
                AddCell(rowPanel, 397, 0, 92, height, "", "achievementDetail", Turbine.UI.ContentAlignment.MiddleRight, gold, Turbine.UI.Lotro.Font.TrajanPro14);
                AddCell(rowPanel, 512, 0, 55, height, FormatNumber(row.kills), "achievementDetail", Turbine.UI.ContentAlignment.MiddleRight, valueColor, Turbine.UI.Lotro.Font.TrajanPro14);
                AddCell(rowPanel, 582, 0, 55, height, FormatNumber(row.wipes), "achievementDetail", Turbine.UI.ContentAlignment.MiddleRight, valueColor, Turbine.UI.Lotro.Font.TrajanPro14);
            else
                local bossText = tostring(row.bossIndex or "") .. ". " .. tostring(row.bossName or "");
                AddCell(rowPanel, 36, 0, 278, height, ParseGraph.TruncateStatisticsText(bossText, 34), "achievementDetail", Turbine.UI.ContentAlignment.MiddleLeft, valueColor, Turbine.UI.Lotro.Font.TrajanPro14);
                AddCell(rowPanel, 328, 0, 54, height, "", "achievementDetail", Turbine.UI.ContentAlignment.MiddleCenter, labelColor, Turbine.UI.Lotro.Font.TrajanPro14);
                AddCell(rowPanel, 397, 0, 92, height, FormatKillTime(row.bestTime), "achievementDetail", Turbine.UI.ContentAlignment.MiddleRight, gold, Turbine.UI.Lotro.Font.TrajanPro14);
                AddCell(rowPanel, 512, 0, 55, height, FormatNumber(row.kills), "achievementDetail", Turbine.UI.ContentAlignment.MiddleRight, valueColor, Turbine.UI.Lotro.Font.TrajanPro14);
                AddCell(rowPanel, 582, 0, 55, height, FormatNumber(row.wipes), "achievementDetail", Turbine.UI.ContentAlignment.MiddleRight, valueColor, Turbine.UI.Lotro.Font.TrajanPro14);
                local hasFirstKill = row.firstKillTime ~= nil or (row.firstKillGroupText ~= nil and row.firstKillGroupText ~= "-");
                local firstKillCell = Turbine.UI.Control();
                firstKillCell:SetParent(rowPanel);
                firstKillCell:SetPosition(670, 0);
                firstKillCell:SetSize(120, height);
                firstKillCell:SetMouseVisible(hasFirstKill);
                firstKillCell:SetZOrder(6);
                local firstKillText = Label(firstKillCell, 0, 0, 120, height, hasFirstKill and "Details" or "-", "achievementDetail");
                firstKillText:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
                firstKillText:SetForeColor(hasFirstKill and valueColor or mutedColor);
                firstKillText:SetMouseVisible(false);
                if hasFirstKill then
                    ParseGraph.BindStatisticsFirstKillTooltip(firstKillCell, panel, row);
                end
            end
        end
    end

    ParseGraph.InstanceStatisticsSearchBox.TextChanged = function(sender)
        ParseGraph.InstanceStatisticsSearchText = tostring(sender:GetText() or "");
        DrawStatisticsRows();
    end

    DrawStatisticsRows();
end

local function GetUnmatchedTierText(entry)
    if entry ~= nil and entry.selectedTierKey ~= nil then
        return ParseGraph.GetInstanceTierLabel(entry.selectedTierKey);
    end
    return "Tier";
end

local function GetUnmatchedInstanceText(entry)
    if entry ~= nil and entry.selectedInstanceKey ~= nil then
        local instance = GetInstanceDefinitionStrict(entry.selectedInstanceKey);
        if instance ~= nil then
            local line1 = ParseGraph.GetInstanceButtonLines(instance);
            return line1 or tostring(instance.name or "Instance");
        end
    end
    return "Instance";
end

local function GetUnmatchedBossText(entry)
    if entry ~= nil and tonumber(entry.selectedBossIndex) ~= nil then
        return "Boss " .. tostring(tonumber(entry.selectedBossIndex));
    end
    return "Boss";
end

local function GetUnmatchedInstanceDisplayText(entry)
    if entry ~= nil and entry.selectedInstanceKey ~= nil then
        local instance = GetInstanceDefinitionStrict(entry.selectedInstanceKey);
        if instance ~= nil then
            return tostring(instance.name or GetUnmatchedInstanceText(entry));
        end
    end
    return "No instance detected";
end

local function GetUnmatchedBossDisplayText(entry)
    if entry ~= nil and tonumber(entry.selectedBossIndex) ~= nil then
        local bossIndex = tonumber(entry.selectedBossIndex);
        local instance = GetInstanceDefinitionStrict(entry.selectedInstanceKey);
        if instance ~= nil and type(instance.bosses) == "table" and instance.bosses[bossIndex] ~= nil then
            local boss = instance.bosses[bossIndex];
            if boss.name ~= nil and tostring(boss.name) ~= "" then
                return "Boss " .. tostring(bossIndex) .. " - " .. tostring(boss.name);
            end
        end
        return "Boss " .. tostring(bossIndex);
    end
    return "No boss detected";
end

local function GetUnmatchedTierDisplayText(entry)
    if entry ~= nil and entry.selectedTierKey ~= nil then
        return ParseGraph.GetInstanceTierLabel(entry.selectedTierKey);
    end
    return "No tier detected";
end

local function CycleUnmatchedTier(entry)
    if entry == nil then return end
    local tiers = ParseGraph.InstanceTiers or {};
    if #tiers == 0 then return end

    local index = 0;
    for i = 1, #tiers do
        if tiers[i].key == entry.selectedTierKey then
            index = i;
            break;
        end
    end
    index = index + 1;
    if index > #tiers then index = 1 end
    entry.selectedTierKey = tiers[index].key;
end

local function CycleUnmatchedInstance(entry)
    if entry == nil then return end
    local instances = ParseGraph.GetOrderedInstanceDefinitions();
    if #instances == 0 then return end

    local index = 0;
    for i = 1, #instances do
        if instances[i].key == entry.selectedInstanceKey then
            index = i;
            break;
        end
    end
    index = index + 1;
    if index > #instances then index = 1 end
    entry.selectedInstanceKey = instances[index].key;
    local bossCount = type(instances[index].bosses) == "table" and #instances[index].bosses or 1;
    if entry.selectedBossIndex == nil then
        entry.selectedBossIndex = 1;
    else
        entry.selectedBossIndex = math.max(1, math.min(bossCount, tonumber(entry.selectedBossIndex) or 1));
    end
end

local function CycleUnmatchedBoss(entry)
    if entry == nil then return end
    local instance = GetInstanceDefinitionStrict(entry.selectedInstanceKey);
    if instance == nil then
        CycleUnmatchedInstance(entry);
        instance = GetInstanceDefinitionStrict(entry.selectedInstanceKey);
    end
    if instance == nil then return end

    local bossCount = type(instance.bosses) == "table" and #instance.bosses or 1;
    local bossIndex = (tonumber(entry.selectedBossIndex) or 0) + 1;
    if bossIndex > bossCount then bossIndex = 1 end
    entry.selectedBossIndex = bossIndex;
end

local function BuildUnmatchedTierItems(entryId)
    local entry = GetUnmatchedInstanceEntryById(entryId);
    local items = {};
    local tiers = ParseGraph.InstanceTiers or {};
    for i = 1, #tiers do
        local tier = tiers[i];
        local tierKey = tier.key;
        table.insert(items, {
            text = tostring(tier.label or tier.key),
            selected = entry ~= nil and tierKey == entry.selectedTierKey,
            onClick = function()
                local selected = GetUnmatchedInstanceEntryById(entryId);
                if selected ~= nil then
                    selected.selectedTierKey = tierKey;
                end
                ParseGraph.HideLauncherContextMenu();
                ParseGraph.DrawInstancesView();
            end
        });
    end
    return items;
end

local function BuildUnmatchedInstanceItems(entryId)
    local entry = GetUnmatchedInstanceEntryById(entryId);
    local items = {};
    local orderedInstances = ParseGraph.GetOrderedInstanceDefinitions();
    for i = 1, #orderedInstances do
        local instance = orderedInstances[i];
        local instanceKey = instance.key;
        local line1, line2 = ParseGraph.GetInstanceButtonLines(instance);
        local text = tostring(line1 or instance.name or instance.key);
        if line2 ~= nil and tostring(line2) ~= "" then
            text = text .. " - " .. tostring(line2);
        end
        table.insert(items, {
            text = text,
            selected = entry ~= nil and instanceKey == entry.selectedInstanceKey,
            onClick = function()
                local selected = GetUnmatchedInstanceEntryById(entryId);
                if selected ~= nil then
                    selected.selectedInstanceKey = instanceKey;
                    local bossCount = type(instance.bosses) == "table" and #instance.bosses or 1;
                    if selected.selectedBossIndex == nil then
                        selected.selectedBossIndex = 1;
                    else
                        selected.selectedBossIndex = math.max(1, math.min(bossCount, tonumber(selected.selectedBossIndex) or 1));
                    end
                end
                ParseGraph.HideLauncherContextMenu();
                ParseGraph.DrawInstancesView();
            end
        });
    end
    return items;
end

local function BuildUnmatchedBossItems(entryId)
    local entry = GetUnmatchedInstanceEntryById(entryId);
    local items = {};
    local instance = entry ~= nil and GetInstanceDefinitionStrict(entry.selectedInstanceKey) or nil;
    if instance == nil or type(instance.bosses) ~= "table" then
        table.insert(items, { text = "Choose instance first", disabled = true });
        return items;
    end

    for i = 1, #instance.bosses do
        local boss = instance.bosses[i] or {};
        local bossIndex = i;
        local text = "Boss " .. tostring(i);
        local bossLabel = boss.contextName or boss.name;
        if bossLabel ~= nil and tostring(bossLabel) ~= "" then
            text = text .. " - " .. tostring(bossLabel);
        end
        table.insert(items, {
            text = text,
            selected = entry ~= nil and bossIndex == tonumber(entry.selectedBossIndex),
            onClick = function()
                local selected = GetUnmatchedInstanceEntryById(entryId);
                if selected ~= nil then
                    selected.selectedBossIndex = bossIndex;
                end
                ParseGraph.HideLauncherContextMenu();
                ParseGraph.DrawInstancesView();
            end
        });
    end
    return items;
end

local function DrawUnmatchedEntryTile(parent, x, y, w, h, entry, border)
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local labelColor = Turbine.UI.Color(1.00, 0.93, 0.76, 0.28);
    local white = Turbine.UI.Color(0.95, 0.92, 0.88, 0.82);
    local red = Turbine.UI.Color(1.00, 0.86, 0.27, 0.42);
    local green = Turbine.UI.Color(1.00, 0.25, 0.95, 0.25);
    local brown = Turbine.UI.Color(1.00, 0.86, 0.50, 0.22);
    local panel = Panel(parent, x, y, w, h, 1.00);
    DrawAchievementBorder(panel, w, h, border);

    local data = type(entry.combatData) == "table" and entry.combatData or {};
    local metric = ParseGraph.NormalizeInstanceMetricMode(data.metric or "damage");
    local metricInfo = ParseGraph.GetInstanceMetricInfo(metric);
    local rate = FormatNumber(data.rate or data.dps);
    local amount = tostring(data.amountText or data.damageText or "-");
    local duration = FormatKillTime(data.durationSeconds);
    if duration == "-" and data.duration ~= nil then
        duration = tostring(data.duration);
    end

    local separatorX = w - 180;
    DrawBlock(panel, separatorX, 12, 1, h - 24, border);

    local title = Label(panel, 18, 10, separatorX - 36, 24, "#" .. tostring(entry.id or "?") .. " Unmatched", "achievement");
    title:SetForeColor(gold);
    local metricColor = red;
    if metric == "healing" then
        metricColor = green;
    elseif metric == "taken" then
        metricColor = brown;
    end

    local metricLineY = 36;
    local amountName = tostring(metricInfo.amountLabel or "Damage") .. ":";
    local rateName = tostring(metricInfo.rateLabel or "");
    local amountTitle = Label(panel, 18, metricLineY, 82, 26, amountName, "achievement");
    amountTitle:SetForeColor(white);
    local amountValue = Label(panel, 100, metricLineY, 105, 26, amount, "achievement");
    amountValue:SetForeColor(metricColor);
    local firstSeparator = Label(panel, 208, metricLineY, 18, 26, "•", "achievement");
    firstSeparator:SetForeColor(white);
    local rateValue = Label(panel, 229, metricLineY, 88, 26, rate, "achievement");
    rateValue:SetForeColor(metricColor);
    local rateUnit = Label(panel, 319, metricLineY, 48, 26, rateName, "achievement");
    rateUnit:SetForeColor(white);
    local secondSeparator = Label(panel, 370, metricLineY, 18, 26, "•", "achievement");
    secondSeparator:SetForeColor(white);
    local durationLine = Label(panel, 390, metricLineY, separatorX - 408, 26, duration, "achievement");
    durationLine:SetForeColor(white);

    local tierLine = Label(panel, 18, 66, separatorX - 36, 20, GetUnmatchedTierDisplayText(entry), "achievementDetail");
    tierLine:SetForeColor(labelColor);
    local instanceLine = Label(panel, 18, 91, separatorX - 36, 20, "Instance: " .. GetUnmatchedInstanceDisplayText(entry), "achievementDetail");
    instanceLine:SetForeColor(white);
    local bossLine = Label(panel, 18, 116, separatorX - 36, 20, GetUnmatchedBossDisplayText(entry), "achievementDetail");
    bossLine:SetForeColor(white);

    local buttonX = w - 162;
    local tierButton = ParseGraph.CreateActionButton(panel, buttonX, 14, 145, 22, "Tier", function(sender)
        ParseGraph.ShowUnmatchedSelectionSubmenu(sender, BuildUnmatchedTierItems(sender.entryId), 170);
    end);
    tierButton.entryId = entry.id;

    local instanceButton = ParseGraph.CreateActionButton(panel, buttonX, 48, 145, 22, "Instance", function(sender)
        ParseGraph.ShowUnmatchedSelectionSubmenu(sender, BuildUnmatchedInstanceItems(sender.entryId), 320);
    end);
    instanceButton.entryId = entry.id;

    local bossButton = ParseGraph.CreateActionButton(panel, buttonX, 82, 145, 22, "Boss", function(sender)
        ParseGraph.ShowUnmatchedSelectionSubmenu(sender, BuildUnmatchedBossItems(sender.entryId), 335);
    end);
    bossButton.entryId = entry.id;

    local add = ParseGraph.CreateActionButton(panel, buttonX, 122, 66, 22, "Add", function(sender)
        ParseGraph.RecordUnmatchedInstanceEntry(sender.entryId);
    end);
    add.entryId = entry.id;

    local remove = ParseGraph.CreateActionButton(panel, buttonX + 74, 122, 72, 22, "Remove", function(sender)
        if ParseGraph.RemoveUnmatchedInstanceEntry(sender.entryId) then
            ParseGraph.DrawInstancesView();
        end
    end);
    remove.entryId = entry.id;
end

local function DrawUnmatchedEntryCard(parent, x, y, w, h, entry, border)
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local white = Turbine.UI.Color(0.95, 0.92, 0.88, 0.82);
    local muted = Turbine.UI.Color(0.90, 0.62, 0.62, 0.56);
    local chipFill = Turbine.UI.Color(1.00, 0.01, 0.03, 0.05);
    local chipBorder = Turbine.UI.Color(1.00, 0.60, 0.46, 0.20);
    local red = Turbine.UI.Color(1.00, 0.95, 0.20, 0.18);
    local green = Turbine.UI.Color(1.00, 0.25, 0.95, 0.25);
    local brown = Turbine.UI.Color(1.00, 0.86, 0.50, 0.22);

    local panel = Panel(parent, x, y, w, h, 1.00);
    DrawAchievementBorder(panel, w, h, border);

    local data = type(entry.combatData) == "table" and entry.combatData or {};
    local metric = ParseGraph.NormalizeInstanceMetricMode(data.metric or "damage");
    local metricInfo = ParseGraph.GetInstanceMetricInfo(metric);
    local rate = FormatNumber(data.rate or data.dps);
    local amount = tostring(data.amountText or data.damageText or "-");
    local duration = FormatKillTime(data.durationSeconds);
    if duration == "-" and data.duration ~= nil then
        duration = tostring(data.duration);
    end

    local metricColor = red;
    if metric == "healing" then
        metricColor = green;
    elseif metric == "taken" then
        metricColor = brown;
    end

    local separatorX = w - 174;
    DrawBlock(panel, separatorX, 12, 1, 80, Turbine.UI.Color(1.00, 0.36, 0.26, 0.18));

    local badgeW = 52;
    local badge = Panel(panel, 14, 16, badgeW, 48, 1.00);
    badge:SetBackColor(chipFill);
    DrawAchievementBorder(badge, badgeW, 48, chipBorder);
    local badgeText = Label(badge, 0, 0, badgeW, 48, "#" .. tostring(entry.id or "?"), "achievementTitle");
    badgeText:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    badgeText:SetForeColor(gold);

    local contentX = 80;
    local title = Label(panel, contentX, 10, separatorX - contentX - 18, 28, "Unmatched Parse", "achievementTitle");
    title:SetForeColor(gold);

    local metricLineY = 40;
    local amountTitle = Label(panel, contentX, metricLineY, 78, 26, tostring(metricInfo.amountLabel or "Damage") .. ":", "achievement");
    amountTitle:SetForeColor(white);
    local amountValue = Label(panel, contentX + 75, metricLineY, 105, 26, amount, "achievement");
    amountValue:SetForeColor(metricColor);
    local rateTitle = Label(panel, contentX + 190, metricLineY, 60, 26, tostring(metricInfo.rateLabel or "") .. ":", "achievement");
    rateTitle:SetForeColor(white);
    local rateValue = Label(panel, contentX + 250, metricLineY, 80, 26, rate, "achievement");
    rateValue:SetForeColor(metricColor);
    local timeTitle = Label(panel, contentX + 340, metricLineY, 44, 26, "Time:", "achievement");
    timeTitle:SetForeColor(white);
    local durationLine = Label(panel, contentX + 384, metricLineY, separatorX - contentX - 394, 26, duration, "achievement");
    durationLine:SetForeColor(white);

    local function DrawStatusChip(xPos, yPos, width, text, detected, onClick)
        local chipH = 22;
        local chip = Panel(panel, xPos, yPos, width, chipH, 1.00);
        chip:SetBackColor(chipFill);
        chip:SetMouseVisible(true);
        DrawAchievementBorder(chip, width, chipH, chipBorder);
        local textX = 10;
        if detected ~= true then
            local bang = Label(chip, 8, 0, 18, chipH, "!", "achievement");
            bang:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
            bang:SetForeColor(gold);
            bang:SetMouseVisible(false);
            textX = 28;
        end
        local status = Label(chip, textX, 0, width - textX - 8, chipH, text, "achievementDetail");
        status:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
        status:SetForeColor(detected == true and white or muted);
        status:SetMouseVisible(false);
        chip.MouseEnter = function(sender)
            sender:SetBackColor(Turbine.UI.Color(1.00, 0.03, 0.08, 0.12));
        end
        chip.MouseLeave = function(sender)
            sender:SetBackColor(chipFill);
        end
        chip.MouseClick = function(sender)
            if type(onClick) == "function" then
                onClick(sender);
            end
        end
    end

    local tierDetected = entry ~= nil and entry.selectedTierKey ~= nil;
    local instanceDetected = entry ~= nil and entry.selectedInstanceKey ~= nil;
    local bossDetected = entry ~= nil and tonumber(entry.selectedBossIndex) ~= nil;
    local chipY = 100;
    local chipX = 14;
    local chipGap = 8;
    local tierW = 150;
    local instanceW = 260;
    local bossW = w - chipX - 14 - tierW - instanceW - (chipGap * 2);
    DrawStatusChip(chipX, chipY, tierW, GetUnmatchedTierDisplayText(entry), tierDetected, function(sender)
        sender.entryId = entry.id;
        ParseGraph.ShowUnmatchedSelectionSubmenu(sender, BuildUnmatchedTierItems(sender.entryId), 170);
    end);
    DrawStatusChip(chipX + tierW + chipGap, chipY, instanceW, GetUnmatchedInstanceDisplayText(entry), instanceDetected, function(sender)
        sender.entryId = entry.id;
        ParseGraph.ShowUnmatchedSelectionSubmenu(sender, BuildUnmatchedInstanceItems(sender.entryId), 320);
    end);
    DrawStatusChip(chipX + tierW + chipGap + instanceW + chipGap, chipY, bossW, GetUnmatchedBossDisplayText(entry), bossDetected, function(sender)
        sender.entryId = entry.id;
        ParseGraph.ShowUnmatchedSelectionSubmenu(sender, BuildUnmatchedBossItems(sender.entryId), 335);
    end);

    local buttonX = separatorX + 27;
    local buttonW = 120;
    local remove = ParseGraph.CreateActionButton(panel, buttonX, 14, buttonW, 24, "Remove", function(sender)
        if ParseGraph.RemoveUnmatchedInstanceEntry(sender.entryId) then
            ParseGraph.DrawInstancesView();
        end
    end);
    remove.entryId = entry.id;

    local add = ParseGraph.CreateActionButton(panel, buttonX, 48, buttonW, 24, "Add", function(sender)
        ParseGraph.RecordUnmatchedInstanceEntry(sender.entryId);
    end);
    add.entryId = entry.id;
end

function ParseGraph.DrawUnmatchedInstancesView(panel)
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local entries = type(ParseGraph.UnmatchedInstanceEntries) == "table" and ParseGraph.UnmatchedInstanceEntries or {};

    local title = Label(panel, 0, 2, panel:GetWidth(), 30, "Unmatched", "huge");
    title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    title:SetForeColor(gold);
    local count = Label(panel, 0, 31, panel:GetWidth(), 20, tostring(#entries) .. " waiting", "achievementDetail");
    count:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    count:SetForeColor(Turbine.UI.Color(0.95, 0.92, 0.88, 0.82));
    DrawBlock(panel, 35, 58, 770, 1, border);

    if #entries == 0 then
        local empty = Label(panel, 0, 140, panel:GetWidth(), 60, "No unmatched instance entries this session.", "big");
        empty:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        return;
    end

    local list = Turbine.UI.ListBox();
    list:SetParent(panel);
    list:SetPosition(24, 76);
    list:SetSize(792, 480);
    list:SetOrientation(Turbine.UI.Orientation.Vertical);
    list:SetBackColor(Turbine.UI.Color(1.00, 0, 0, 0));

    local scroll = Turbine.UI.Lotro.ScrollBar();
    scroll:SetParent(panel);
    scroll:SetOrientation(Turbine.UI.Orientation.Vertical);
    scroll:SetPosition(824, 76);
    scroll:SetSize(12, 480);
    list:SetVerticalScrollBar(scroll);

    local tileW = 782;
    local tileH = 132;
    local gapY = 10;
    local rowH = tileH + gapY;
    local totalRows = #entries;
    local visibleRows = math.floor(480 / rowH);
    scroll:SetVisible(totalRows > visibleRows);

    for row = 0, totalRows - 1 do
        local rowPanel = Turbine.UI.Control();
        rowPanel:SetSize(list:GetWidth(), rowH);
        rowPanel:SetMouseVisible(true);

        local entry = entries[row + 1];
        if entry ~= nil then
            DrawUnmatchedEntryCard(rowPanel, 0, 0, tileW, tileH, entry, border);
    end

    list:AddItem(rowPanel);
    end
end

function ParseGraph.DrawGroupListsView(panel)
    if panel == nil then
        return;
    end

    ParseGraph.EnsureGroupListLines();
    ParseGraph.GroupListTextBoxes = {};
    ParseGraph.GroupListLeftTextBoxes = {};
    ParseGraph.GroupListRightTextBoxes = {};
    ParseGraph.GroupListModeCheckboxes = {};
    ParseGraph.GroupListModeLabels = {};
    ParseGraph.GroupListSaveCheckbox = nil;
    ParseGraph.GroupListSaveLabel = nil;
    ParseGraph.GroupListsPostAlias = nil;

    local w = panel:GetWidth();
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local white = Turbine.UI.Color(0.95, 0.92, 0.88, 0.82);
    local green = Turbine.UI.Color(1.00, 0.24, 1.00, 0.33);
    local fill = Turbine.UI.Color(1.00, 0.02, 0.02, 0.02);

    local title = Label(panel, 0, 2, w, 30, "Group Lists", "huge");
    title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    title:SetForeColor(gold);

    local explanation = Label(panel, 82, 34, w - 164, 18, "Fill matching rows to build a multi-line group message.", "achievementDetail");
    explanation:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    explanation:SetForeColor(white);
    explanation:SetMouseVisible(false);
    local explanation2 = Label(panel, 82, 54, w - 164, 18, "Each filled row posts with the left side orange and the right side green.", "achievementDetail");
    explanation2:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    explanation2:SetForeColor(white);
    explanation2:SetMouseVisible(false);

    local modeY = 80;
    local optionTooltip = nil;
    local function HideGroupListOptionTooltip()
        if optionTooltip ~= nil then
            optionTooltip:SetVisible(false);
        end
    end

    local function ShowGroupListOptionTooltip(titleText, bodyLines, x)
        if optionTooltip == nil then
            optionTooltip = Turbine.UI.Control();
            optionTooltip:SetParent(panel);
            optionTooltip:SetSize(366, 92);
            optionTooltip:SetBackColor(Turbine.UI.Color(0.98, 0.01, 0.01, 0.01));
            optionTooltip:SetMouseVisible(false);
            optionTooltip:SetZOrder(1000);

            optionTooltip.topBorder = DrawBlock(optionTooltip, 0, 0, 366, 1, border);
            optionTooltip.bottomBorder = DrawBlock(optionTooltip, 0, 91, 366, 1, border);
            optionTooltip.leftBorder = DrawBlock(optionTooltip, 0, 0, 1, 92, border);
            optionTooltip.rightBorder = DrawBlock(optionTooltip, 365, 0, 1, 92, border);

            optionTooltip.title = Label(optionTooltip, 10, 6, 346, 20, "", "achievement");
            optionTooltip.title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
            optionTooltip.title:SetForeColor(gold);
            optionTooltip.title:SetMouseVisible(false);
            optionTooltip.body = {};
            for lineIndex = 1, 3 do
                local body = Label(optionTooltip, 10, 26 + ((lineIndex - 1) * 18), 346, 18, "", "achievementDetail");
                body:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
                body:SetForeColor(white);
                body:SetMouseVisible(false);
                optionTooltip.body[lineIndex] = body;
            end
        end

        optionTooltip.title:SetText(tostring(titleText or ""));
        for lineIndex = 1, 3 do
            local body = optionTooltip.body[lineIndex];
            if body ~= nil then
                body:SetText(tostring((bodyLines or {})[lineIndex] or ""));
            end
        end

        x = tonumber(x) or 220;
        local y = modeY + 28;
        if x + 366 > w then
            x = math.max(0, w - 372);
        end
        optionTooltip:SetPosition(x, y);
        optionTooltip:SetVisible(true);
    end

    local function BindGroupListOptionTooltip(control, titleText, bodyLines, x)
        if control == nil then
            return;
        end
        control.MouseEnter = function()
            ShowGroupListOptionTooltip(titleText, bodyLines, x);
        end
        control.MouseLeave = function()
            HideGroupListOptionTooltip();
        end
    end

    local function DrawModeOption(key, labelText, x, tooltipLines, optionLabelW)
        local checkbox = Turbine.UI.Lotro.CheckBox();
        checkbox:SetParent(panel);
        checkbox:SetPosition(x, modeY);
        checkbox:SetSize(24, 24);
        checkbox:SetText("");
        checkbox.groupListModeKey = key;
        checkbox.CheckedChanged = function(sender)
            if ParseGraph.UpdatingGroupListModeCheckboxes == true then
                return;
            end
            if sender:IsChecked() then
                ParseGraph.SetGroupListMode(sender.groupListModeKey);
            elseif ParseGraph.GetGroupListMode() == sender.groupListModeKey then
                ParseGraph.SetGroupListMode("custom");
            else
                ParseGraph.UpdateGroupListModeControls();
            end
        end
        ParseGraph.GroupListModeCheckboxes[key] = checkbox;

        local optionLabel = Label(panel, x + 30, modeY, optionLabelW or 150, 24, labelText, "achievementDetail");
        optionLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
        optionLabel:SetForeColor(gold);
        optionLabel:SetMouseVisible(true);
        optionLabel.MouseClick = function()
            if ParseGraph.GetGroupListMode() == key then
                ParseGraph.SetGroupListMode("custom");
            else
                ParseGraph.SetGroupListMode(key);
            end
        end
        ParseGraph.GroupListModeLabels[key] = optionLabel;
        BindGroupListOptionTooltip(checkbox, labelText, tooltipLines, x);
        BindGroupListOptionTooltip(optionLabel, labelText, tooltipLines, x);
    end

    local function DrawSaveOption(x, tooltipLines)
        local checkbox = Turbine.UI.Lotro.CheckBox();
        checkbox:SetParent(panel);
        checkbox:SetPosition(x, modeY);
        checkbox:SetSize(24, 24);
        checkbox:SetText("");
        checkbox.CheckedChanged = function(sender)
            if ParseGraph.UpdatingGroupListSaveCheckbox == true then
                return;
            end
            ParseGraph.SetGroupListSaveEnabled(sender:IsChecked());
        end
        ParseGraph.GroupListSaveCheckbox = checkbox;

        local optionLabel = Label(panel, x + 30, modeY, 110, 24, "Save list", "achievementDetail");
        optionLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
        optionLabel:SetForeColor(gold);
        optionLabel:SetMouseVisible(true);
        optionLabel.MouseClick = function()
            ParseGraph.SetGroupListSaveEnabled(ParseGraph.GroupListSaveEnabled ~= true);
        end
        ParseGraph.GroupListSaveLabel = optionLabel;
        BindGroupListOptionTooltip(checkbox, "Save list", tooltipLines, x - 120);
        BindGroupListOptionTooltip(optionLabel, "Save list", tooltipLines, x - 120);
    end

    DrawModeOption("custom", "Custom", 112, {
        "Default layout with editable left and right text fields.",
        "Rows post as left text = right text.",
        "Useful for free-form assignments or notes."
    }, 90);
    DrawModeOption("target", "Target marking", 242, {
        "Uses LOTRO target marks as fixed left-side labels.",
        "Only rows with a right-side player name are posted.",
        "Useful for assigning Skull, Shield, Moon, and more."
    });
    DrawModeOption("numbers", "Numbers", 452, {
        "Uses 1) through 10) as fixed left-side labels.",
        "Only rows with a right-side value are posted.",
        "Numbers post without an equals sign."
    });
    DrawSaveOption(602, {
        "Keeps separate rows for Custom, Target marking, and Numbers.",
        "All three templates are saved account-wide after reloads.",
        "Leave unchecked for a temporary session list."
    });
    ParseGraph.UpdateGroupListModeControls();

    DrawBlock(panel, 13, 112, w - 26, 1, border);

    local labelX = 44;
    local labelW = 58;
    local leftX = 118;
    local leftW = 298;
    local equalsX = 426;
    local equalsW = 28;
    local rightX = 464;
    local rightW = 318;
    local startY = 134;
    local rowH = 34;
    local boxH = 22;
    local mode = ParseGraph.GetGroupListMode();
    if mode == "target" then
        leftW = 118;
        equalsW = 28;
        local gap = 12;
        local groupW = leftW + gap + equalsW + gap + rightW;
        leftX = math.floor((w - groupW) / 2);
        equalsX = leftX + leftW + gap;
        rightX = equalsX + equalsW + gap;
    elseif mode == "numbers" then
        leftW = 56;
        local gap = 12;
        local groupW = leftW + gap + rightW;
        leftX = math.floor((w - groupW) / 2);
        equalsX = leftX + leftW;
        rightX = leftX + leftW + gap;
    end

    local function DrawGroupListTextBox(index, side, x, y, boxW, text, textColor)
        local back = DrawBlock(panel, x, y, boxW, boxH, fill);
        back:SetMouseVisible(false);
        DrawBlock(panel, x, y, boxW, 1, border);
        DrawBlock(panel, x, y + boxH - 1, boxW, 1, border);
        DrawBlock(panel, x, y, 1, boxH, border);
        DrawBlock(panel, x + boxW - 1, y, 1, boxH, border);

        local textBox = Turbine.UI.Lotro.TextBox();
        textBox:SetParent(panel);
        textBox:SetPosition(x + 5, y + 2);
        textBox:SetSize(boxW - 10, boxH - 4);
        textBox:SetFont(Turbine.UI.Lotro.Font.TrajanPro14);
        textBox:SetBackColor(fill);
        textBox:SetForeColor(textColor);
        textBox:SetZOrder(20);
        textBox.groupListIndex = index;
        textBox.groupListSide = side;
        textBox:SetText(tostring(text or ""));
        textBox.TextChanged = function(sender)
            ParseGraph.SetGroupListLine(sender.groupListIndex, sender.groupListSide, sender:GetText());
        end
        return textBox;
    end

    for i = 1, 10 do
        local y = startY + ((i - 1) * rowH);
        local row = ParseGraph.GroupListLines[i] or {};
        local fixedLeft = ParseGraph.GetGroupListFixedLabel(i);
        local leftBox = nil;
        if fixedLeft == nil then
            local lineLabel = Label(panel, labelX, y + 1, labelW, boxH, "Line " .. tostring(i), "achievementDetail");
            lineLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
            lineLabel:SetForeColor(gold);
            lineLabel:SetMouseVisible(false);
            leftBox = DrawGroupListTextBox(i, "left", leftX, y, leftW, row.left, gold);
        else
            local fixedLabel = Label(panel, leftX, y + 1, leftW, boxH, fixedLeft, "achievementDetail");
            fixedLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
            fixedLabel:SetForeColor(gold);
            fixedLabel:SetMouseVisible(false);
        end

        if mode ~= "numbers" then
            local equalsLabel = Label(panel, equalsX, y + 1, equalsW, boxH, "=", "achievementDetail");
            equalsLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
            equalsLabel:SetForeColor(white);
            equalsLabel:SetMouseVisible(false);
        end

        local rightBox = DrawGroupListTextBox(i, "right", rightX, y, rightW, row.right, green);
        ParseGraph.GroupListTextBoxes[i] = { left = leftBox, right = rightBox };
        ParseGraph.GroupListLeftTextBoxes[i] = leftBox;
        ParseGraph.GroupListRightTextBoxes[i] = rightBox;
    end

    local postW = 145;
    local postH = 22;
    local buttonGap = 18;
    local buttonTotalW = (postW * 2) + buttonGap;
    local postX = math.floor((w - buttonTotalW) / 2);
    local clearX = postX + postW + buttonGap;
    local postY = startY + (rowH * 10) + 12;
    if postY > panel:GetHeight() - postH - 12 then
        postY = panel:GetHeight() - postH - 12;
    end
    local post = ParseGraph.CreateActionButton(panel, postX, postY, postW, postH, "Post", nil);
    post:SetMouseVisible(false);
    post:SetZOrder(10);
    ParseGraph.GroupListsPostAlias = ParseGraph.CreateGroupListsPostQuickslot(panel, post, postX, postY, postW, postH);
    local clear = ParseGraph.CreateActionButton(panel, clearX, postY, postW, postH, "Clear", function()
        ParseGraph.ClearGroupListLines();
    end);
    clear:SetZOrder(10);

    local exampleY = postY + 38;
    local exampleTitle = Label(panel, 0, exampleY, w, 18, "Example", "achievementDetail");
    exampleTitle:SetFont(Turbine.UI.Lotro.Font.Verdana14);
    exampleTitle:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    exampleTitle:SetForeColor(white);
    exampleTitle:SetMouseVisible(false);

    local function DrawGroupListExampleRow(y, leftText, rightText, separatorText)
        if separatorText == nil then
            separatorText = "=";
        end
        local left = Label(panel, 270, y, 130, 18, leftText, "achievementDetail");
        left:SetFont(Turbine.UI.Lotro.Font.Verdana14);
        left:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        left:SetForeColor(gold);
        left:SetMouseVisible(false);

        local rightX = 440;
        local rightW = 150;
        if separatorText ~= "" then
            local equals = Label(panel, 408, y, 24, 18, separatorText, "achievementDetail");
            equals:SetFont(Turbine.UI.Lotro.Font.Verdana14);
            equals:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
            equals:SetForeColor(white);
            equals:SetMouseVisible(false);
        else
            rightX = 408;
            rightW = 182;
        end

        local right = Label(panel, rightX, y, rightW, 18, rightText, "achievementDetail");
        right:SetFont(Turbine.UI.Lotro.Font.Verdana14);
        right:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
        right:SetForeColor(green);
        right:SetMouseVisible(false);
    end

    if mode == "numbers" then
        DrawGroupListExampleRow(exampleY + 22, "1)", "Player #1", "");
        DrawGroupListExampleRow(exampleY + 42, "2)", "Player #2", "");
        DrawGroupListExampleRow(exampleY + 62, "3)", "Player #3", "");
    elseif mode == "target" then
        DrawGroupListExampleRow(exampleY + 22, "Skull", "Player #1");
        DrawGroupListExampleRow(exampleY + 42, "Shield", "Player #2");
        DrawGroupListExampleRow(exampleY + 62, "Sun", "Player #3");
    else
        DrawGroupListExampleRow(exampleY + 22, "Main tank", "Player #1");
        DrawGroupListExampleRow(exampleY + 42, "Off tank", "Player #2");
        DrawGroupListExampleRow(exampleY + 62, "Backup", "Player #3");
    end
end

function ParseGraph.DrawInstancesView()
    if ParseGraph.InstanceContentPanel == nil then return end

    if ParseGraph.HideInstanceBossContextMenu ~= nil then
        ParseGraph.HideInstanceBossContextMenu();
    end
    ParseGraph.ClearPostButtonWindows();
    ClearChildren(ParseGraph.InstanceContentPanel);
    ParseGraph.UpdateInstanceButtons();
    ParseGraph.UpdateInstanceMetricButtons();

    local showingUnmatched = ParseGraph.InstanceViewMode == "unmatched";
    local showingStatistics = ParseGraph.InstanceViewMode == "statistics";
    local showingGroupLists = ParseGraph.InstanceViewMode == "groupLists";
    local showingFullPage = showingUnmatched or showingStatistics or showingGroupLists;
    if ParseGraph.InstanceMetricButtons ~= nil then
        for _, button in pairs(ParseGraph.InstanceMetricButtons) do
            if button ~= nil then
                button:SetVisible(not showingGroupLists);
                button:SetMouseVisible(not showingGroupLists);
            end
        end
    end
    if ParseGraph.InstanceMetricSeparator ~= nil then
        ParseGraph.InstanceMetricSeparator:SetVisible(not showingGroupLists);
    end
    if ParseGraph.InstanceButtons ~= nil then
        for _, button in pairs(ParseGraph.InstanceButtons) do
            if button ~= nil then
                button:SetVisible(not showingFullPage);
            end
        end
    end
    if ParseGraph.InstanceButtonsSeparator ~= nil then
        ParseGraph.InstanceButtonsSeparator:SetVisible(not showingFullPage);
    end
    if showingGroupLists then
        ParseGraph.InstanceContentPanel:SetPosition(20, 20);
        ParseGraph.InstanceContentPanel:SetSize(840, 696);
    elseif showingFullPage then
        ParseGraph.InstanceContentPanel:SetPosition(20, 72);
        ParseGraph.InstanceContentPanel:SetSize(840, 644);
    else
        ParseGraph.InstanceContentPanel:SetPosition(20, 142);
        ParseGraph.InstanceContentPanel:SetSize(840, 574);
    end

    local panel = ParseGraph.InstanceContentPanel;
    local w = panel:GetWidth();
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);

    if showingUnmatched then
        ParseGraph.DrawUnmatchedInstancesView(panel);
        return;
    end
    if showingStatistics then
        ParseGraph.DrawInstanceStatisticsView(panel);
        return;
    end
    if showingGroupLists then
        ParseGraph.DrawGroupListsView(panel);
        return;
    end

    local instance = ParseGraph.GetInstanceDefinition(ParseGraph.SelectedInstanceKey);
    if instance == nil then
        return;
    end

    if ParseGraph.InstanceViewMode == "boss" then
        ParseGraph.DrawInstanceBossDetailView(panel, instance, ParseGraph.SelectedInstanceTierKey or "t1", tonumber(ParseGraph.SelectedInstanceBossIndex) or 1);
        return;
    end

    local title = Label(panel, 0, 2, w, 30, instance.name, "huge");
    title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    title:SetForeColor(gold);

    local bosses = instance.bosses or {};
    local tiers = ParseGraph.InstanceTiers or {};
    local activeTierKey = nil;
    if ParseGraph.ActiveInstanceKey == instance.key then
        activeTierKey = ParseGraph.ActiveInstanceTierKey;
    end
    local columnW = 258;
    local gapX = 18;
    local listX = 6;
    local listY = 60;
    local listW = w - 30;
    local listH = panel:GetHeight() - listY - 4;
    local totalColumnW = (columnW * 3) + (gapX * 2);
    local startX = math.floor((listW - totalColumnW) / 2);
    local headerY = 32;
    local cardW = columnW;
    local cardGapY = 8;
    local cardH = 150;
    local rowH = cardH + cardGapY;

    local list = Turbine.UI.ListBox();
    list:SetParent(panel);
    list:SetPosition(listX, listY);
    list:SetSize(listW, listH);
    list:SetOrientation(Turbine.UI.Orientation.Vertical);
    list:SetBackColor(Turbine.UI.Color(1.00, 0, 0, 0));

    local scroll = Turbine.UI.Lotro.ScrollBar();
    scroll:SetParent(panel);
    scroll:SetOrientation(Turbine.UI.Orientation.Vertical);
    scroll:SetPosition(w - 16, listY);
    scroll:SetSize(12, listH);
    list:SetVerticalScrollBar(scroll);
    local visibleRows = math.floor(listH / rowH);
    scroll:SetVisible(#bosses > visibleRows);

    for tierIndex = 1, #tiers do
        local tier = tiers[tierIndex];
        local columnX = listX + startX + ((tierIndex - 1) * (columnW + gapX));
        local tierLabel = Label(panel, columnX, headerY, columnW, 24, tier.label, "achievement");
        tierLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        tierLabel:SetMouseVisible(false);
        if activeTierKey == tier.key then
            tierLabel:SetForeColor(Turbine.UI.Color(0.95, 0.18, 0.55, 0.90));
        else
            tierLabel:SetForeColor(gold);
        end
        local tierClick = Turbine.UI.Control();
        tierClick:SetParent(panel);
        tierClick:SetPosition(columnX, headerY);
        tierClick:SetSize(columnW, 34);
        tierClick:SetMouseVisible(true);
        tierClick:SetZOrder(50);
        tierClick.instanceKey = instance.key;
        tierClick.tierKey = tier.key;
        tierClick.MouseClick = function(sender)
            ParseGraph.SetActiveInstanceTier(sender.instanceKey, sender.tierKey);
        end
    end

    for bossIndex = 1, #bosses do
        local rowPanel = Turbine.UI.Control();
        rowPanel:SetSize(listW, rowH);
        rowPanel:SetMouseVisible(false);

        for tierIndex = 1, #tiers do
            local tier = tiers[tierIndex];
            local columnX = startX + ((tierIndex - 1) * (columnW + gapX));
            DrawInstanceBossCard(rowPanel, columnX, 0, cardW, cardH, instance.key, tier.key, bossIndex, bosses[bossIndex], border);
        end

        list:AddItem(rowPanel);
    end
end

function ParseGraph.SetView(view)
    if view ~= "achievements" and view ~= "instances" and view ~= "scoreboard" and view ~= "characters" and view ~= "settings" and view ~= "help" and view ~= "history" and view ~= "parseDetail" then
        view = "main";
    end

    local previousView = ParseGraph.CurrentView or "main";
    if view == "characters" and previousView ~= "characters" then
        ParseGraph.CharacterReturnView = previousView;
    end

    if view ~= "instances" then
        ParseGraph.ClearTemporaryInstanceTarget();
    end
    if previousView == "history" and view ~= "history" and ParseGraph.ClearParseHistoryCardIcons ~= nil then
        ParseGraph.ClearParseHistoryCardIcons();
    end
    if view ~= "history" and ParseGraph.HideParseHistorySortMenu ~= nil then
        ParseGraph.HideParseHistorySortMenu();
    end
    if ParseGraph.HideParseSpecMenu ~= nil then
        ParseGraph.HideParseSpecMenu();
    end
    if ParseGraph.HideParseSpecFilterMenu ~= nil then
        ParseGraph.HideParseSpecFilterMenu();
    end
    if ParseGraph.HideSidebarParsesFlyout ~= nil then
        ParseGraph.HideSidebarParsesFlyout();
    end
    if ParseGraph.HideSidebarHistoryFlyout ~= nil then
        ParseGraph.HideSidebarHistoryFlyout();
    end
    if ParseGraph.HideSidebarAchievementsFlyout ~= nil then
        ParseGraph.HideSidebarAchievementsFlyout();
    end
    if ParseGraph.HideSidebarInstancesFlyout ~= nil then
        ParseGraph.HideSidebarInstancesFlyout();
    end
    if ParseGraph.HideSidebarScoreboardFlyout ~= nil then
        ParseGraph.HideSidebarScoreboardFlyout();
    end
    if ParseGraph.HideSidebarPostChannelFlyout ~= nil then
        ParseGraph.HideSidebarPostChannelFlyout();
    end
    if view ~= "settings" and ParseGraph.HideInstanceDeleteMenu ~= nil then
        ParseGraph.HideInstanceDeleteMenu();
    end
    if ParseGraph.HideInstanceBossContextMenu ~= nil then
        ParseGraph.HideInstanceBossContextMenu();
    end

    ParseGraph.CurrentView = view;
    ParseGraph.UpdateSidebarNavButtons();

    if ParseGraph.CharacterDropdownPanel ~= nil then
        ParseGraph.CharacterDropdownPanel:SetVisible(false);
    end
    if ParseGraph.MainView ~= nil then
        ParseGraph.MainView:SetVisible(view == "main");
    end
    if ParseGraph.AchievementsView ~= nil then
        ParseGraph.AchievementsView:SetVisible(view == "achievements");
    end
    if ParseGraph.InstancesView ~= nil then
        ParseGraph.InstancesView:SetVisible(view == "instances");
    end
    if ParseGraph.ScoreboardView ~= nil then
        ParseGraph.ScoreboardView:SetVisible(view == "scoreboard");
    end
    if ParseGraph.CharactersView ~= nil then
        ParseGraph.CharactersView:SetVisible(view == "characters");
    end
    if ParseGraph.SettingsView ~= nil then
        ParseGraph.SettingsView:SetVisible(view == "settings");
    end
    if ParseGraph.HelpView ~= nil then
        ParseGraph.HelpView:SetVisible(view == "help");
    end
    if ParseGraph.ParseHistoryView ~= nil then
        ParseGraph.ParseHistoryView:SetVisible(view == "history");
    end
    if ParseGraph.ParseDetailView ~= nil then
        ParseGraph.ParseDetailView:SetVisible(view == "parseDetail");
    end

    if view == "achievements" then
        if ParseGraph.Window ~= nil then
            ParseGraph.Window:SetText("Achievements");
        end
        ParseGraph.DrawAchievementsView();
    elseif view == "instances" then
        if ParseGraph.Window ~= nil then
            ParseGraph.Window:SetText("InstanceGraph");
        end
        ParseGraph.DrawInstancesView();
    elseif view == "scoreboard" then
        if ParseGraph.Window ~= nil then
            ParseGraph.Window:SetText("Scoreboard");
        end
        ParseGraph.DrawScoreboardView();
    elseif view == "characters" then
        if ParseGraph.Window ~= nil then
            ParseGraph.Window:SetText("Characters");
        end
        ParseGraph.DrawCharactersView();
    elseif view == "settings" then
        if ParseGraph.Window ~= nil then
            ParseGraph.Window:SetText("Settings");
        end
        ParseGraph.UpdateStartMinimizedCheckbox();
        ParseGraph.UpdateCombineSameClassCheckbox();
        ParseGraph.UpdateShowLauncherButtonCheckbox();
        ParseGraph.UpdateOpenAfterFinishedParseCheckbox();
        ParseGraph.UpdateBossHealthPercentMessagesCheckbox();
        ParseGraph.UpdateOnlySaveInstanceParsesOnKillCheckbox();
        ParseGraph.UpdateScoreboardRecapMessagesCheckbox();
        ParseGraph.UpdateLauncherSizeControls();
    elseif view == "help" then
        if ParseGraph.Window ~= nil then
            ParseGraph.Window:SetText("Help");
        end
    elseif view == "history" then
        if ParseGraph.Window ~= nil then
            ParseGraph.Window:SetText("Parse History");
        end
        ParseGraph.DrawParseHistoryView();
    elseif view == "parseDetail" then
        if ParseGraph.Window ~= nil then
            ParseGraph.Window:SetText("Parse Details");
        end
        ParseGraph.DrawParseDetailView();
    else
        if ParseGraph.Window ~= nil then
            ParseGraph.Window:SetText("ParseGraph");
        end
        ParseGraph.Refresh();
    end
    ParseGraph.UpdatePostButtonWindowPositions();
end

function ParseGraph.DrawCharactersView()
    if ParseGraph.CharacterListPanel == nil then return end

    if ParseGraph.CurrentCharacterPanel ~= nil then
        ClearChildren(ParseGraph.CurrentCharacterPanel);
    end
    while ParseGraph.CharacterListPanel:GetItemCount() > 0 do
        local item = ParseGraph.CharacterListPanel:GetItem(1);
        if item == nil then
            break;
        end
        ParseGraph.CharacterListPanel:RemoveItem(item);
    end
    local panel = ParseGraph.CharacterListPanel;
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local selectedBorder = Turbine.UI.Color(1.00, 1.00, 0.76, 0.18);
    local labelColor = Turbine.UI.Color(1.00, 0.93, 0.76, 0.28);
    local valueColor = Turbine.UI.Color(0.95, 0.92, 0.88, 0.82);
    local selectedKey = ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey();
    local currentKey = ParseGraph.GetCurrentCharacterKey();
    local characters = ParseGraph.GetCharacterList();
    local currentCharacter = nil;
    local listedCharacters = {};
    for i = 1, #characters do
        if characters[i].key == currentKey then
            currentCharacter = characters[i];
        else
            listedCharacters[#listedCharacters + 1] = characters[i];
        end
    end
    if currentCharacter == nil then
        local classInfo = ParseGraph.GetCurrentPlayerClassInfo();
        currentCharacter = {
            key = currentKey,
            name = ParseGraph.GetCurrentCharacterName(),
            count = #ParseGraph.Parses,
            classKey = classInfo and classInfo.key or nil,
            className = classInfo and classInfo.name or nil,
            classIcon = classInfo and classInfo.icon or nil
        };
    end
    local tileW = 380;
    local tileH = 58;
    local gapX = 24;
    local gapY = 12;
    local rowH = tileH + gapY;
    local startX = 12;
    local totalRows = math.ceil(#listedCharacters / 2);
    local visibleRows = math.floor((panel:GetHeight() or 1) / rowH);

    if ParseGraph.CharacterListScrollBar ~= nil then
        ParseGraph.CharacterListScrollBar:SetVisible(totalRows > visibleRows);
    end

    local function DrawCharacterTile(parent, x, y, w, h, character)
        local isCurrentCharacter = character.key == currentKey;
        local isSelectedCharacter = character.key == selectedKey;
        local tile = Panel(parent, x, y, w, h, 1.00);
        tile:SetMouseVisible(true);
        tile.characterKey = character.key;
        tile.normalFill = Turbine.UI.Color(1.00, 0, 0, 0);
        tile.selectedFill = Turbine.UI.Color(1.00, 0.03, 0.13, 0.25);
        tile.hoverFill = Turbine.UI.Color(1.00, 0.04, 0.18, 0.34);
        tile:SetBackColor(isSelectedCharacter and tile.selectedFill or tile.normalFill);
        tile.currentFill = isSelectedCharacter and tile.selectedFill or tile.normalFill;
        DrawAchievementBorder(tile, w, h, isSelectedCharacter and selectedBorder or border);

        local textX = 18;
        if character.classIcon ~= nil and tostring(character.classIcon) ~= "" then
            local iconY = math.floor((h - 40) / 2);
            local iconBack = DrawBlock(tile, 16, iconY, 40, 40, tile.currentFill);
            iconBack:SetMouseVisible(false);
            iconBack:SetZOrder(1);
            tile.classIconBack = iconBack;

            local icon = Turbine.UI.Control();
            icon:SetParent(tile);
            icon:SetPosition(16, iconY);
            icon:SetSize(40, 40);
            local normalIconPath = tostring(character.classIcon);
            local hoverIconPath = GetIconVariantPath(normalIconPath, "hover");
            local selectedIconPath = GetIconVariantPath(normalIconPath, "selected");
            local initialIconPath = isSelectedCharacter and selectedIconPath or normalIconPath;
            local iconLoaded = pcall(function()
                icon:SetBackground(initialIconPath);
            end);
            icon:SetMouseVisible(false);
            icon:SetZOrder(2);
            if iconLoaded then
                tile.classIcon = icon;
                tile.classIconNormalPath = normalIconPath;
                tile.classIconHoverPath = hoverIconPath;
                tile.classIconSelectedPath = selectedIconPath;
                textX = 70;
            else
                icon:SetParent(nil);
                iconBack:SetParent(nil);
            end
        end

        if isCurrentCharacter then
            local name = Label(tile, textX, 0, w - textX - 250, h, tostring(character.name or ""), "achievementTitle");
            name:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
            name:SetMouseVisible(false);
        name:SetZOrder(5);
            name:SetZOrder(3);
            name:SetForeColor(Turbine.UI.Color(1.00, 1.00, 0.82, 0.16));

            local parses = Label(tile, w - 235, 0, 215, h, "Parses: " .. FormatNumber(character.count or 0), "achievementTitle");
            parses:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
            parses:SetMouseVisible(false);
            parses:SetZOrder(3);
            parses:SetForeColor(valueColor);
        else
            local name = Label(tile, textX, 6, w - textX - 18, 26, tostring(character.name or ""), "achievement");
            name:SetMouseVisible(false);
        name:SetZOrder(5);
            name:SetZOrder(3);
            name:SetForeColor(isSelectedCharacter and Turbine.UI.Color(1.00, 1.00, 0.82, 0.16) or labelColor);

            local detail = "Parses: " .. FormatNumber(character.count or 0);
            local sub = Label(tile, textX, 32, w - textX - 18, 18, detail, "achievementDetail");
            sub:SetMouseVisible(false);
            sub:SetZOrder(3);
            sub:SetForeColor(valueColor);
        end

        tile.MouseClick = function(sender)
            local returnView = ParseGraph.CharacterReturnView or "main";
            if returnView == "characters" then
                returnView = "main";
            end
            if ParseGraph.SelectCharacter(sender.characterKey, true) ~= false then
                ParseGraph.CharacterReturnView = nil;
                ParseGraph.SetView(returnView);
            end
        end
        tile.MouseEnter = function(sender)
            sender:SetBackColor(sender.hoverFill);
            if sender.classIconBack ~= nil then
                sender.classIconBack:SetBackColor(sender.hoverFill);
            end
            if sender.classIcon ~= nil then
                pcall(function()
                    sender.classIcon:SetBackground(sender.classIconHoverPath);
                end);
            end
        end
        tile.MouseLeave = function(sender)
            local fill = sender.characterKey == selectedKey and sender.selectedFill or sender.normalFill;
            sender:SetBackColor(fill);
            if sender.classIconBack ~= nil then
                sender.classIconBack:SetBackColor(fill);
            end
            if sender.classIcon ~= nil then
                local iconPath = sender.characterKey == selectedKey and sender.classIconSelectedPath or sender.classIconNormalPath;
                pcall(function()
                    sender.classIcon:SetBackground(iconPath);
                end);
            end
        end
        return tile;
    end

    if ParseGraph.CurrentCharacterPanel ~= nil then
        DrawCharacterTile(ParseGraph.CurrentCharacterPanel, 12, 0, 784, 68, currentCharacter);
    end

    for row = 0, totalRows - 1 do
        local rowPanel = Turbine.UI.Control();
        rowPanel:SetSize(panel:GetWidth(), rowH);
        rowPanel:SetMouseVisible(true);

        for col = 0, 1 do
            local i = (row * 2) + col + 1;
            local character = listedCharacters[i];
            if character ~= nil then
                local x = startX + (col * (tileW + gapX));
                DrawCharacterTile(rowPanel, x, 0, tileW, tileH, character);
            end
        end

        panel:AddItem(rowPanel);
    end
end

