    ParseGraph.CharacterListPanel:SetVerticalScrollBar(ParseGraph.CharacterListScrollBar);
    ParseGraph.CharacterListPanel:SetBackColor(Turbine.UI.Color(1.00, 0, 0, 0));
    ParseGraph.CharacterListPanel:SetZOrder(1);
    view:SetVisible(false);
end

function ParseGraph.BuildSettingsView(parent)
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local white = Turbine.UI.Color(0.95, 0.92, 0.88, 0.82);
    local view = Panel(parent, 15, 15, 880, 725, 0.96);
    ParseGraph.SettingsView = view;
    DrawAchievementBorder(view, 880, 725, border);

    local title = Label(view, 0, 18, 880, 34, "Settings", "huge");
    title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    DrawBlock(view, 35, 74, 810, 1, border);

    local list = Turbine.UI.ListBox();
    list:SetParent(view);
    list:SetPosition(46, 94);
    list:SetSize(790, 592);
    list:SetOrientation(Turbine.UI.Orientation.Vertical);
    list:SetBackColor(Turbine.UI.Color(1.00, 0, 0, 0));
    ParseGraph.SettingsList = list;

    local scroll = Turbine.UI.Lotro.ScrollBar();
    scroll:SetParent(view);
    scroll:SetOrientation(Turbine.UI.Orientation.Vertical);
    scroll:SetPosition(846, 94);
    scroll:SetSize(12, 592);
    list:SetVerticalScrollBar(scroll);
    ParseGraph.SettingsScrollBar = scroll;

    local boxW = 764;
    local function AddSection(titleText, height)
        local row = Turbine.UI.Control();
        row:SetSize(boxW, height + 12);
        row:SetBackColor(Turbine.UI.Color(1.00, 0, 0, 0));

        local section = Panel(row, 0, 0, boxW, height, 1.00);
        DrawAchievementBorder(section, boxW, height, border);

        local sectionTitle = Label(section, 0, 16, boxW, 28, titleText, "achievementTitle");
        sectionTitle:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        sectionTitle:SetForeColor(gold);
        DrawBlock(section, 48, 54, boxW - 96, 1, border);
        list:AddItem(row);
        return section;
    end

    local function SettingCheckbox(section, y, checkboxField, labelField, updatingField, labelText, detailLines, setter)
        local checkbox = Turbine.UI.Lotro.CheckBox();
        checkbox:SetParent(section);
        checkbox:SetPosition(82, y);
        checkbox:SetSize(24, 24);
        checkbox:SetText("");
        checkbox.CheckedChanged = function(sender)
            if ParseGraph[updatingField] == true then
                return;
            end
            setter(sender:IsChecked());
        end
        ParseGraph[checkboxField] = checkbox;

        local label = Label(section, 120, y, 286, 26, labelText, "achievement");
        label:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
        label:SetForeColor(gold);
        label:SetMouseVisible(true);
        label.MouseClick = function()
            checkbox:SetChecked(not checkbox:IsChecked());
        end
        ParseGraph[labelField] = label;

        if type(detailLines) == "table" then
            for i = 1, #detailLines do
                local detail = Label(section, 410, y - 4 + ((i - 1) * 20), 330, 20, detailLines[i], "achievementDetail");
                detail:SetForeColor(white);
                detail:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
            end
        end

        return checkbox, label;
    end

    local general = AddSection("General", 226);
    SettingCheckbox(general, 76, "StartMinimizedCheckbox", "StartMinimizedLabel", "UpdatingStartMinimizedCheckbox", "Start minimized", {
        "Do not open the window automatically",
        "when the plugin loads."
    }, ParseGraph.SetStartMinimized);
    SettingCheckbox(general, 126, "CombineSameClassCheckbox", "CombineSameClassLabel", "UpdatingCombineSameClassCheckbox", "Combine same class", {
        "Show parses, achievements, and instances",
        "across characters of the same class."
    }, ParseGraph.SetCombineSameClass);
    SettingCheckbox(general, 176, "OpenAfterFinishedParseCheckbox", "OpenAfterFinishedParseLabel", "UpdatingOpenAfterFinishedParseCheckbox", "Open after finished parse", {
        "Show the window after a successful",
        "dummy parse."
    }, ParseGraph.SetOpenAfterFinishedParse);

    local launcher = AddSection("Launcher Icon", 310);
    SettingCheckbox(launcher, 76, "ShowLauncherButtonCheckbox", "ShowLauncherButtonLabel", "UpdatingShowLauncherButtonCheckbox", "Show ParseGraph icon", {
        "Show the draggable icon for opening",
        "and closing ParseGraph."
    }, ParseGraph.SetShowLauncherButton);

    ParseGraph.IconSizeLabel = Label(launcher, 120, 126, 130, 26, "Icon size:", "achievement");
    ParseGraph.IconSizeLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    ParseGraph.IconSizeLabel:SetForeColor(gold);

    ParseGraph.LauncherSizeCheckboxes = {};
    ParseGraph.LauncherSizeLabels = {};
    local function SizeOption(key, labelText, x)
        local checkbox = Turbine.UI.Lotro.CheckBox();
        checkbox:SetParent(launcher);
        checkbox:SetPosition(x, 126);
        checkbox:SetSize(24, 24);
        checkbox:SetText("");
        checkbox.sizeKey = key;
        checkbox.CheckedChanged = function(sender)
            if ParseGraph.UpdatingLauncherSizeCheckboxes == true then
                return;
            end
            if ParseGraph.ShowLauncherButton ~= true then
                ParseGraph.UpdateLauncherSizeControls();
                return;
            end
            if sender:IsChecked() then
                ParseGraph.SetLauncherButtonSize(sender.sizeKey);
            else
                ParseGraph.UpdateLauncherSizeControls();
            end
        end
        ParseGraph.LauncherSizeCheckboxes[key] = checkbox;

        local optionLabel = Label(launcher, x + 30, 126, 90, 26, labelText, "achievement");
        optionLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
        optionLabel:SetForeColor(gold);
        optionLabel:SetMouseVisible(true);
        optionLabel.MouseClick = function()
            if ParseGraph.ShowLauncherButton == true then
                ParseGraph.SetLauncherButtonSize(key);
            end
        end
        ParseGraph.LauncherSizeLabels[key] = optionLabel;
    end

    SizeOption("small", "Small", 276);
    SizeOption("medium", "Medium", 406);
    SizeOption("large", "Large", 554);

    ParseGraph.LauncherFlyoutDirectionLabel = Label(launcher, 120, 178, 170, 26, "Flyout direction:", "achievement");
    ParseGraph.LauncherFlyoutDirectionLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    ParseGraph.LauncherFlyoutDirectionLabel:SetForeColor(gold);
    ParseGraph.LauncherFlyoutDirectionCheckboxes = {};
    ParseGraph.LauncherFlyoutDirectionLabels = {};
    local function DirectionOption(key, labelText, x)
        local checkbox = Turbine.UI.Lotro.CheckBox();
        checkbox:SetParent(launcher);
        checkbox:SetPosition(x, 178);
        checkbox:SetSize(24, 24);
        checkbox:SetText("");
        checkbox.directionKey = key;
        checkbox.CheckedChanged = function(sender)
            if ParseGraph.UpdatingLauncherFlyoutDirectionCheckboxes == true then
                return;
            end
            if ParseGraph.ShowLauncherButton ~= true then
                ParseGraph.UpdateLauncherSizeControls();
                return;
            end
            if sender:IsChecked() then
                ParseGraph.SetLauncherFlyoutDirection(sender.directionKey);
            else
                ParseGraph.UpdateLauncherSizeControls();
            end
        end
        ParseGraph.LauncherFlyoutDirectionCheckboxes[key] = checkbox;

        local optionLabel = Label(launcher, x + 30, 178, 90, 26, labelText, "achievement");
        optionLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
        optionLabel:SetForeColor(gold);
        optionLabel:SetMouseVisible(true);
        optionLabel.MouseClick = function()
            if ParseGraph.ShowLauncherButton == true then
                ParseGraph.SetLauncherFlyoutDirection(key);
            end
        end
        ParseGraph.LauncherFlyoutDirectionLabels[key] = optionLabel;
    end

    DirectionOption("left", "Left", 326);
    DirectionOption("right", "Right", 456);

    SettingCheckbox(launcher, 230, "ShowLauncherTimerCheckbox", "ShowLauncherTimerLabel", "UpdatingShowLauncherTimerCheckbox", "Show parse icon timer", nil, function(enabled)
        if ParseGraph.ShowLauncherButton ~= true then
            ParseGraph.UpdateLauncherSizeControls();
            return;
        end
        ParseGraph.SetShowLauncherTimer(enabled);
    end);
    ParseGraph.ShowLauncherTimerDetail1 = Label(launcher, 410, 226, 330, 20, "Show a timer on the icon", "achievementDetail");
    ParseGraph.ShowLauncherTimerDetail1:SetForeColor(white);
    ParseGraph.ShowLauncherTimerDetail2 = Label(launcher, 410, 246, 330, 20, "while a dummy parse is running.", "achievementDetail");
    ParseGraph.ShowLauncherTimerDetail2:SetForeColor(white);

    local instances = AddSection("Instances", 190);
    SettingCheckbox(instances, 76, "BossHealthPercentMessagesCheckbox", "BossHealthPercentMessagesLabel", "UpdatingBossHealthPercentMessagesCheckbox", "Boss percent messages", {
        "Show boss health percent messages",
        "when damage posts are recognized."
    }, ParseGraph.SetBossHealthPercentMessages);
    SettingCheckbox(instances, 126, "OnlySaveInstanceParsesOnKillCheckbox", "OnlySaveInstanceParsesOnKillLabel", "UpdatingOnlySaveInstanceParsesOnKillCheckbox", "Only save on successful kill", {
        "Save instance parses only after",
        "the matching boss kill line is seen."
    }, ParseGraph.SetOnlySaveInstanceParsesOnKill);
    local cleanup = AddSection("Cleanup", 510);
    SettingCheckbox(cleanup, 76, "AutoStripOldParseDetailsCheckbox", "AutoStripOldParseDetailsLabel", "UpdatingAutoStripOldParseDetailsCheckbox", "Auto-strip old details", {
        "Keep full parse breakdowns on the",
        "latest 100 parses, with safe exceptions."
    }, ParseGraph.SetAutoStripOldParseDetails);

    local stripLabel = Label(cleanup, 82, 136, 300, 24, "Strip old parse data", "achievement");
    stripLabel:SetForeColor(gold);
    stripLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    local stripDetail1 = Label(cleanup, 410, 132, 330, 20, "Removes old parse breakdown data only.", "achievementDetail");
    stripDetail1:SetForeColor(white);
    local stripDetail2 = Label(cleanup, 410, 152, 330, 20, "Final DPS and minute data remain.", "achievementDetail");
    stripDetail2:SetForeColor(white);
    ParseGraph.CleanupStripButton = ParseGraph.CreateActionButton(cleanup, 82, 168, 165, 22, "Strip parses", function()
        ParseGraph.ConfirmManualStripOldParseDetails();
    end);

    local deleteLabel = Label(cleanup, 82, 226, 300, 24, "Delete old parses", "achievement");
    deleteLabel:SetForeColor(gold);
    deleteLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    local deleteDetail1 = Label(cleanup, 410, 222, 330, 20, "Deletes up to 50 oldest parses for", "achievementDetail");
    deleteDetail1:SetForeColor(white);
    local deleteDetail2 = Label(cleanup, 410, 242, 330, 20, "the selected character, skipping protected parses.", "achievementDetail");
    deleteDetail2:SetForeColor(white);
    ParseGraph.CleanupDeleteButton = ParseGraph.CreateActionButton(cleanup, 82, 258, 165, 22, "Delete 50 oldest", function()
        ParseGraph.ConfirmDeleteOldestSafeParses();
    end);

    local deleteAllLabel = Label(cleanup, 82, 316, 300, 24, "Delete all parses", "achievement");
    deleteAllLabel:SetForeColor(gold);
    deleteAllLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    local deleteAllDetail1 = Label(cleanup, 410, 312, 330, 20, "Deletes every saved parse for", "achievementDetail");
    deleteAllDetail1:SetForeColor(white);
    local deleteAllDetail2 = Label(cleanup, 410, 332, 330, 20, "the logged-in character.", "achievementDetail");
    deleteAllDetail2:SetForeColor(white);
    ParseGraph.CleanupDeleteAllButton = ParseGraph.CreateActionButton(cleanup, 82, 348, 165, 22, "Delete all parses", function()
        if ParseGraph.IsCombineSameClassActive() then
            ParseGraph.SetCleanupStatus("Turn off Combine same class before deleting parses.");
            return;
        end
        if not ParseGraph.IsViewingCurrentCharacter() then
            ParseGraph.SetCleanupStatus("Switch to that character before deleting its parses.");
            return;
        end
        ParseGraph.ShowClearConfirm();
    end);

    local instanceDeleteLabel = Label(cleanup, 82, 406, 300, 24, "Delete instance data", "achievement");
    instanceDeleteLabel:SetForeColor(gold);
    instanceDeleteLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    local instanceDeleteDetail1 = Label(cleanup, 410, 402, 330, 20, "Choose one instance or all", "achievementDetail");
    instanceDeleteDetail1:SetForeColor(white);
    local instanceDeleteDetail2 = Label(cleanup, 410, 422, 330, 20, "instance entries to delete.", "achievementDetail");
    instanceDeleteDetail2:SetForeColor(white);
    ParseGraph.CleanupInstanceDeleteButton = ParseGraph.CreateActionButton(cleanup, 82, 438, 165, 22, "Choose instance", function()
        ParseGraph.ShowInstanceDeleteMenu();
    end);

    ParseGraph.CleanupStatusLabel = Label(cleanup, 82, 476, 660, 22, "", "achievementDetail");
    ParseGraph.CleanupStatusLabel:SetForeColor(white);
    ParseGraph.CleanupStatusLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);

    ParseGraph.UpdateStartMinimizedCheckbox();
    ParseGraph.UpdateCombineSameClassCheckbox();
    ParseGraph.UpdateShowLauncherButtonCheckbox();
    ParseGraph.UpdateShowLauncherTimerCheckbox();
    ParseGraph.UpdateOpenAfterFinishedParseCheckbox();
    ParseGraph.UpdateBossHealthPercentMessagesCheckbox();
    ParseGraph.UpdateOnlySaveInstanceParsesOnKillCheckbox();
    ParseGraph.UpdateScoreboardRecapMessagesCheckbox();
    ParseGraph.UpdateAutoStripOldParseDetailsCheckbox();
    ParseGraph.UpdateLauncherSizeControls();
    view:SetVisible(false);
end

function ParseGraph.BuildHelpView(parent)
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local white = Turbine.UI.Color(0.95, 0.92, 0.88, 0.82);
    local view = Panel(parent, 15, 15, 880, 725, 0.96);
    ParseGraph.HelpView = view;
    DrawAchievementBorder(view, 880, 725, border);

    local title = Label(view, 0, 18, 880, 34, "Help", "huge");
    title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    DrawBlock(view, 35, 74, 810, 1, border);

    local list = Turbine.UI.ListBox();
    list:SetParent(view);
    list:SetPosition(46, 94);
    list:SetSize(790, 590);
    list:SetOrientation(Turbine.UI.Orientation.Vertical);
    list:SetBackColor(Turbine.UI.Color(1.00, 0, 0, 0));

    local scroll = Turbine.UI.Lotro.ScrollBar();
    scroll:SetParent(view);
    scroll:SetOrientation(Turbine.UI.Orientation.Vertical);
    scroll:SetPosition(846, 94);
    scroll:SetSize(12, 590);
    list:SetVerticalScrollBar(scroll);

    local boxW = 764;
    local lineH = 22;
    local function HelpSection(heading, lines)
        local boxH = math.max(128, 78 + (#lines * lineH));
        local row = Turbine.UI.Control();
        row:SetSize(boxW, boxH + 12);
        row:SetBackColor(Turbine.UI.Color(1.00, 0, 0, 0));

        local inner = Panel(row, 0, 0, boxW, boxH, 1.00);
        DrawAchievementBorder(inner, boxW, boxH, border);

        local h = Label(inner, 0, 16, boxW, 28, heading, "achievementTitle");
        h:SetForeColor(gold);
        h:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        DrawBlock(inner, 48, 54, boxW - 96, 1, border);

        for i = 1, #lines do
            local line = Label(inner, 44, 68 + ((i - 1) * lineH), boxW - 88, lineH, lines[i], "achievementDetail");
            line:SetForeColor(white);
            line:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
        end
        list:AddItem(row);
    end

    HelpSection("Getting Started", {
        "Open or hide ParseGraph with /parsegraph or /pg. The draggable launcher icon can also",
        "open the window, and the icon can be moved anywhere on screen. Window position, icon",
        "position, graph baseline, and other preferences are saved so they survive reloads.",
        "Use the sidebar to move between Parses, Instances, Scoreboard, Achievements, History,",
        "Settings, and Help. Some sidebar buttons have flyouts for related pages or modes.",
        "The launcher right-click menu can post parses or group lists, choose spec, and set",
        "tier, instance, or boss when automatic detection needs help.",
        "Choose a post channel in the sidebar before using Post buttons. Change opens the",
        "character browser so you can inspect another character's saved data without relogging."
    });

    HelpSection("Dummy Parses", {
        "ParseGraph listens for supported training dummy start, minute, final DPS, and total",
        "damage lines. It supports Training Snowman, Dummy Warg, DPS target dummy, No Mits, and",
        "Ettenmoors Training-dummy targets such as Orion, Jalessa, Kelsen, and the Gramsfoot",
        "light, medium, and heavy dummies. Landscape dummies that do not announce DPS in /say",
        "are tracked from your combat log and saved when combat ends.",
        "A parse only becomes valid when the plugin sees that you are actually in combat during",
        "the opening window. This helps avoid saving a nearby player's parse as your own.",
        "If a new dummy start line appears while a parse is already running, the old attempt is",
        "discarded and the minute counter restarts from minute one. This protects laggy restarts.",
        "When the dummy posts its final line, or when an Ettenmoors dummy parse leaves combat,",
        "the parse is saved to the logged-in character.",
        "The combat breakdown is captured from your combat log, while total damage uses the",
        "dummy's own final damage phrase whenever that phrase is available."
    });

    HelpSection("The Parses Page", {
        "The main graph can show the current Session, Today, or the latest 100 parses. Graph",
        "starts at changes the baseline in 5,000 DPS steps and is saved per character.",
        "Spec can filter the graph, Current Session, and All-time Summary to All, Blue, Red,",
        "or Yellow parses. The filter does not delete or rewrite saved parse data.",
        "The blue line shows parse DPS, the orange dotted line shows all-time average, and the",
        "gold marker shows personal best. Hovering a graph point shows minute one, minute two,",
        "minute three, and final DPS for that parse.",
        "Current Session summarizes only the current session, including session average, session",
        "progress, best parse, and minute averages. All-time Summary shows the same style of",
        "information across saved history, including all-time progress and personal best.",
        "Latest parses show a spec circle between parse number and date. Click an empty or",
