function ParseGraph.GetParseBySource(sourceKey, sourceIndex)
    sourceIndex = tonumber(sourceIndex) or 0;
    if sourceIndex <= 0 then
        return nil;
    end

    local key = tostring(sourceKey or ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey());
    if key == ParseGraph.GetCurrentCharacterKey() and ParseGraph.Parses ~= nil and ParseGraph.Parses[sourceIndex] ~= nil then
        return ParseGraph.Parses[sourceIndex];
    end

    if string.sub(key, 1, 14) == "__ParseString_" then
        local imported = ParseGraph.ImportedParses or {};
        for i = 1, #imported do
            local point = imported[i];
            if type(point) == "table" then
                local pointKey = tostring(point.sourceKey or (point.parse and point.parse.__sourceKey) or "");
                local pointIndex = tonumber(point.sourceIndex or (point.parse and point.parse.__sourceIndex) or point.index) or 0;
                if pointKey == key or pointIndex == sourceIndex then
                    return point.parse;
                end
            end
        end
    end

    local characters = ParseGraph.AccountData and ParseGraph.AccountData.characters or {};
    local entry = characters[key];
    if type(entry) == "table" and type(entry.parses) == "table" then
        return entry.parses[sourceIndex];
    end

    return nil;
end

function ParseGraph.IsParseFavourite(point)
    if type(point) ~= "table" or point.parse == nil then
        return false;
    end

    local parse = ParseGraph.GetParseBySource(point.sourceKey or point.parse.__sourceKey, point.sourceIndex or point.parse.__sourceIndex or point.index) or point.parse;
    return type(parse) == "table" and parse.favorite == true;
end

function ParseGraph.ToggleParseFavourite(point)
    if type(point) ~= "table" or point.parse == nil then
        return;
    end

    local sourceKey = tostring(point.sourceKey or point.parse.__sourceKey or ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey());
    local sourceIndex = tonumber(point.sourceIndex or point.parse.__sourceIndex or point.index) or 0;
    local parse = ParseGraph.GetParseBySource(sourceKey, sourceIndex);
    if type(parse) ~= "table" then
        return;
    end

    parse.favorite = not (parse.favorite == true);
    point.parse.favorite = parse.favorite;
    if string.sub(sourceKey, 1, 14) == "__ParseString_" then
        ParseGraph.SaveAccountData();
    else
        ParseGraph.Save(false, ParseGraph.ViewCharacterKey ~= ParseGraph.GetCurrentCharacterKey());
    end
    if ParseGraph.CurrentView == "history" then
        ParseGraph.DrawParseHistoryView();
    end
end

function ParseGraph.GetSavedImportedParses()
    if type(ParseGraph.AccountData) ~= "table" then
        ParseGraph.AccountData = { characters = {}, importedParses = {} };
    end
    if type(ParseGraph.AccountData.importedParses) ~= "table" then
        ParseGraph.AccountData.importedParses = {};
    end
    return ParseGraph.AccountData.importedParses;
end

function ParseGraph.RestoreImportedParses()
    ParseGraph.ImportedParses = {};
    ParseGraph.ImportedParseCounter = 0;

    local saved = ParseGraph.GetSavedImportedParses();
    for i = 1, #saved do
        local parse = saved[i];
        if type(parse) == "table" then
            local sourceIndex = tonumber(parse.__sourceIndex) or i;
            local sourceKey = tostring(parse.__sourceKey or ("__ParseString_" .. tostring(sourceIndex)));
            parse.__sourceKey = sourceKey;
            parse.__sourceIndex = sourceIndex;
            parse.__sourceName = tostring(parse.__sourceName or "Shared parse");
            parse.__displayIndex = tostring(parse.__displayIndex or "Shared parse");
            if tostring(parse.__classKey or "") == "" then
                parse.__classKey = ParseGraph.GetViewedClassKey();
            end
            ParseGraph.ImportedParseCounter = math.max(tonumber(ParseGraph.ImportedParseCounter) or 0, sourceIndex);
            ParseGraph.AddImportedParse(parse, sourceIndex, sourceKey, true);
        end
    end
end

function ParseGraph.AddImportedParse(parse, sourceIndex, sourceKey, skipPersist)
    if type(parse) ~= "table" then
        return nil;
    end

    sourceIndex = tonumber(sourceIndex) or 0;
    sourceKey = tostring(sourceKey or ("__ParseString_" .. tostring(sourceIndex)));
    parse.__sourceKey = sourceKey;
    parse.__sourceIndex = sourceIndex;
    parse.__sourceName = tostring(parse.__sourceName or "Shared parse");
    parse.__displayIndex = tostring(parse.__displayIndex or "Shared parse");
    if tostring(parse.__classKey or "") == "" then
        parse.__classKey = ParseGraph.GetViewedClassKey();
    end

    local point = {
        parse = parse,
        index = sourceIndex,
        sourceKey = sourceKey,
        sourceIndex = sourceIndex,
        sourceName = tostring(parse.__sourceName or "Shared parse"),
        displayIndex = "Shared parse",
        returnView = "history",
        imported = true
    };
    ParseGraph.ImportedParses = ParseGraph.ImportedParses or {};
    table.insert(ParseGraph.ImportedParses, point);
    if skipPersist ~= true then
        local saved = ParseGraph.GetSavedImportedParses();
        table.insert(saved, parse);
        ParseGraph.SaveAccountData();
    end
    return point;
end

function ParseGraph.DeleteImportedParse(sourceKey, sourceIndex)
    sourceKey = tostring(sourceKey or "");
    sourceIndex = tonumber(sourceIndex) or 0;
    local imported = ParseGraph.ImportedParses or {};
    local removed = false;
    for i = #imported, 1, -1 do
        local point = imported[i];
        if type(point) == "table" then
            local pointKey = tostring(point.sourceKey or (point.parse and point.parse.__sourceKey) or "");
            local pointIndex = tonumber(point.sourceIndex or (point.parse and point.parse.__sourceIndex) or point.index) or 0;
            if pointKey == sourceKey or (sourceKey == "" and sourceIndex > 0 and pointIndex == sourceIndex) then
                table.remove(imported, i);
                removed = true;
            end
        end
    end

    if removed == true then
        ParseGraph.ImportedParses = imported;
        local saved = ParseGraph.GetSavedImportedParses();
        for i = #saved, 1, -1 do
            local parse = saved[i];
            if type(parse) == "table" then
                local parseKey = tostring(parse.__sourceKey or "");
                local parseIndex = tonumber(parse.__sourceIndex) or 0;
                if parseKey == sourceKey or (sourceKey == "" and sourceIndex > 0 and parseIndex == sourceIndex) then
                    table.remove(saved, i);
                end
            end
        end
        ParseGraph.SaveAccountData();
        local compareKey = ParseGraph.GetParseCompareKey(sourceKey, sourceIndex);
        for i = #(ParseGraph.ParseCompareSelections or {}), 1, -1 do
            if ParseGraph.ParseCompareSelections[i].key == compareKey then
                table.remove(ParseGraph.ParseCompareSelections, i);
            end
        end
        if ParseGraph.CurrentView == "history" then
            ParseGraph.DrawParseHistoryView();
        else
            ParseGraph.Refresh();
        end
    end
    return removed;
end

function ParseGraph.EncodeParseStringField(value)
    value = tostring(value or "");
    local encoded = string.gsub(value, "([^A-Za-z0-9_%.%-])", function(char)
        return string.format("%%%02X", string.byte(char));
    end);
    return encoded;
end

function ParseGraph.DecodeParseStringField(value)
    value = tostring(value or "");
    local decoded = string.gsub(value, "%%(%x%x)", function(hex)
        return string.char(tonumber(hex, 16) or 0);
    end);
    return decoded;
end

ParseGraph.ParseStringPayloadPrefix = "PG2:";
local ParseStringAlphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789()";
local ParseStringAlphabetLookup = nil;
local ParseStringKey = "ParseGraph-ParseString";

local function GetParseStringAlphabetLookup()
    if ParseStringAlphabetLookup == nil then
        ParseStringAlphabetLookup = {};
        for i = 1, string.len(ParseStringAlphabet) do
            ParseStringAlphabetLookup[string.sub(ParseStringAlphabet, i, i)] = i - 1;
        end
    end
    return ParseStringAlphabetLookup;
end

local function ParseStringXorByte(a, b)
    a = tonumber(a) or 0;
    b = tonumber(b) or 0;
    local result = 0;
    local bit = 1;
    for _ = 1, 8 do
        local aa = a % 2;
        local bb = b % 2;
        if aa ~= bb then
            result = result + bit;
        end
        a = math.floor(a / 2);
        b = math.floor(b / 2);
        bit = bit * 2;
    end
    return result;
end

local function TransformParseStringBytes(value)
    value = tostring(value or "");
    local keyLen = string.len(ParseStringKey);
    local bytes = {};
    for i = 1, string.len(value) do
        local source = string.byte(value, i) or 0;
        local key = string.byte(ParseStringKey, ((i - 1) % keyLen) + 1) or 0;
        bytes[i] = string.char(ParseStringXorByte(source, key));
    end
    return table.concat(bytes);
end

local function EncodeParseStringBytes(value)
    value = tostring(value or "");
    local out = {};
    local outIndex = 1;
    for i = 1, string.len(value), 3 do
        local b1, b2, b3 = string.byte(value, i, i + 2);
        b1 = b1 or 0;
        b2 = b2 or 0;
        b3 = b3 or 0;
        local c1 = math.floor(b1 / 4);
        local c2 = ((b1 % 4) * 16) + math.floor(b2 / 16);
        local c3 = ((b2 % 16) * 4) + math.floor(b3 / 64);
        local c4 = b3 % 64;
        out[outIndex] = string.sub(ParseStringAlphabet, c1 + 1, c1 + 1);
        out[outIndex + 1] = string.sub(ParseStringAlphabet, c2 + 1, c2 + 1);
        out[outIndex + 2] = string.sub(ParseStringAlphabet, c3 + 1, c3 + 1);
        out[outIndex + 3] = string.sub(ParseStringAlphabet, c4 + 1, c4 + 1);
        outIndex = outIndex + 4;
    end
    return table.concat(out);
end

local function DecodeParseStringBytes(value, byteLength)
    value = tostring(value or "");
    byteLength = tonumber(byteLength) or 0;
    local lookup = GetParseStringAlphabetLookup();
    local out = {};
    local outIndex = 1;
    for i = 1, string.len(value), 4 do
        local c1 = lookup[string.sub(value, i, i)];
        local c2 = lookup[string.sub(value, i + 1, i + 1)];
        local c3 = lookup[string.sub(value, i + 2, i + 2)];
        local c4 = lookup[string.sub(value, i + 3, i + 3)];
        if c1 == nil or c2 == nil or c3 == nil or c4 == nil then
            return nil;
        end
        local b1 = (c1 * 4) + math.floor(c2 / 16);
        local b2 = ((c2 % 16) * 16) + math.floor(c3 / 4);
        local b3 = ((c3 % 4) * 64) + c4;
        if outIndex <= byteLength then
            out[outIndex] = string.char(b1);
            outIndex = outIndex + 1;
        end
        if outIndex <= byteLength then
            out[outIndex] = string.char(b2);
            outIndex = outIndex + 1;
        end
        if outIndex <= byteLength then
            out[outIndex] = string.char(b3);
            outIndex = outIndex + 1;
        end
    end
    return table.concat(out);
end

function ParseGraph.EncodeParseStringPayload(payload)
    payload = tostring(payload or "");
    local scrambled = TransformParseStringBytes(payload);
    return ParseGraph.ParseStringPayloadPrefix .. tostring(string.len(payload)) .. ":" .. EncodeParseStringBytes(scrambled);
end

function ParseGraph.DecodeParseStringPayload(payload)
    payload = TrimText(payload or "");
    local len, encoded = string.match(payload, "^PG2:(%d+):(.+)$");
    if len == nil then
        return payload, nil;
    end

    local scrambled = DecodeParseStringBytes(encoded, tonumber(len));
    if scrambled == nil then
        return nil, "That ParseString could not be decoded.";
    end
    return TransformParseStringBytes(scrambled), nil;
end

local function ParseStringNumber(value)
    if value == nil then
        return "";
    end
    return tostring(value);
end

local function ParseStringNumberOrNil(value)
    value = tostring(value or "");
    if value == "" then
        return nil;
    end
    return tonumber(value);
end

local function EncodeParseStringRecord(values)
    local encoded = {};
    for i = 1, #values do
        encoded[i] = ParseGraph.EncodeParseStringField(values[i]);
    end
    return table.concat(encoded, "|");
end

local function SplitParseStringFields(record)
    local fields = {};
    record = tostring(record or "");
    local startIndex = 1;
    while true do
        local separator = string.find(record, "|", startIndex, true);
        if separator == nil then
            table.insert(fields, ParseGraph.DecodeParseStringField(string.sub(record, startIndex)));
            break;
        end
        table.insert(fields, ParseGraph.DecodeParseStringField(string.sub(record, startIndex, separator - 1)));
        startIndex = separator + 1;
    end
    return fields;
end

local function AddParseStringBucket(records, prefix, bucket)
    if type(bucket) ~= "table" then
        return;
    end

    table.insert(records, EncodeParseStringRecord({
        prefix,
        bucket.name or "",
        ParseStringNumber(bucket.totalDamage),
        ParseStringNumber(bucket.attacks),
        ParseStringNumber(bucket.hits),
        ParseStringNumber(bucket.normals),
        ParseStringNumber(bucket.normalDamage),
        ParseStringNumber(bucket.crits),
        ParseStringNumber(bucket.critDamage),
        ParseStringNumber(bucket.devs),
        ParseStringNumber(bucket.devDamage),
        ParseStringNumber(bucket.min),
        ParseStringNumber(bucket.max),
        bucket.maxSkill or "",
        bucket.maxTarget or ""
    }));
end

local function DecodeParseStringBucket(fields)
    return {
        name = fields[2],
        totalDamage = tonumber(fields[3]) or 0,
        attacks = tonumber(fields[4]) or 0,
        hits = tonumber(fields[5]) or 0,
        normals = tonumber(fields[6]) or 0,
        normalDamage = tonumber(fields[7]) or 0,
        crits = tonumber(fields[8]) or 0,
        critDamage = tonumber(fields[9]) or 0,
        devs = tonumber(fields[10]) or 0,
        devDamage = tonumber(fields[11]) or 0,
        min = ParseStringNumberOrNil(fields[12]),
        max = tonumber(fields[13]) or 0,
        maxSkill = fields[14],
        maxTarget = fields[15]
    };
end

function ParseGraph.BuildParseString(point)
    if point == nil or point.parse == nil then
        return nil;
    end

    local parse = point.parse;
    local sourceName = tostring(parse.__sourceName or point.sourceName or ParseGraph.GetCharacterDisplayName(point.sourceKey));
    local sourceKey = tostring(point.sourceKey or parse.__sourceKey or ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey());
    local sourceEntry = ParseGraph.AccountData and ParseGraph.AccountData.characters and ParseGraph.AccountData.characters[sourceKey] or nil;
    local sourceClassKey = tostring(parse.__classKey or point.classKey or ParseGraph.GetCharacterClassKey(sourceEntry) or "");
    local parseIndex = tonumber(point.index or parse.__sourceIndex or point.sourceIndex) or 0;
    local minutes = parse.minutes or {};
    local records = {
        EncodeParseStringRecord({
            "PG",
            "1"
        }),
        EncodeParseStringRecord({
            "P",
            sourceName,
            parse.time or "",
            ParseStringNumber(parseIndex),
            ParseStringNumber(parse.final),
            ParseStringNumber(minutes[1]),
            ParseStringNumber(minutes[2]),
            ParseStringNumber(minutes[3])
        })
    };

    if sourceClassKey ~= "" then
        table.insert(records, EncodeParseStringRecord({
            "K",
            sourceClassKey
        }));
    end

    local specKey = ParseGraph.GetParseSpecKey(parse);
    if specKey ~= nil then
        table.insert(records, EncodeParseStringRecord({
            "SP",
            specKey
        }));
    end

    local combat = parse.combat;
    if type(combat) == "table" then
        table.insert(records, EncodeParseStringRecord({
            "C",
            ParseStringNumber(combat.totalDamage),
            ParseStringNumber(combat.attacks),
            ParseStringNumber(combat.hits),
            ParseStringNumber(combat.normals),
            ParseStringNumber(combat.normalDamage),
            ParseStringNumber(combat.crits),
            ParseStringNumber(combat.critDamage),
            ParseStringNumber(combat.devs),
            ParseStringNumber(combat.devDamage),
            ParseStringNumber(combat.min),
            ParseStringNumber(combat.max),
            combat.maxSkill or "",
            combat.maxTarget or "",
            ParseStringNumber(combat.duration),
            ParseStringNumber(combat.benefitCount)
        }));

        if type(combat.skills) == "table" then
            for _, bucket in pairs(combat.skills) do
                AddParseStringBucket(records, "S", bucket);
            end
        end
        if type(combat.benefits) == "table" then
            for _, bucket in pairs(combat.benefits) do
                if type(bucket) == "table" then
                    table.insert(records, EncodeParseStringRecord({
                        "B",
                        bucket.name or "",
                        ParseStringNumber(bucket.count)
                    }));
                end
            end
        end
    end

    return "<ParseString>" .. ParseGraph.EncodeParseStringPayload(table.concat(records, ";")) .. "<ParseString>";
end

function ParseGraph.ShareParsePoint(point)
    local parseString = ParseGraph.BuildParseString(point);
    ParseGraph.ShowParseStringExportWindow(parseString);
end

function ParseGraph.ParseParseString(text)
    text = TrimText(text or "");
    if text == "" then
        return nil, "Paste a ParseString first.";
    end

    local payload = string.match(text, "<ParseString>(.-)<ParseString>") or string.match(text, "<ParseString>(.-)</ParseString>");
    if payload == nil then
        payload = text;
    end
    payload = TrimText(payload);
    local decodedPayload, decodeErr = ParseGraph.DecodeParseStringPayload(payload);
    if decodedPayload == nil then
        return nil, decodeErr or "That ParseString could not be decoded.";
    end
    payload = decodedPayload;

    local parse = {
        final = 0,
        minutes = {},
        time = "",
        __sourceName = "Shared parse",
        __displayIndex = "Shared parse"
    };
    local combat = nil;
    local headerOk = false;
    local parseOk = false;

    for record in string.gmatch(payload .. ";", "(.-);") do
        if record ~= "" then
            local fields = SplitParseStringFields(record);
            local kind = fields[1];
            if kind == "PG" and fields[2] == "1" then
                headerOk = true;
            elseif kind == "P" then
                parse.__sourceName = tostring(fields[2] or "Shared parse");
                parse.time = tostring(fields[3] or "");
                parse.__sharedOriginalIndex = tonumber(fields[4]) or 0;
                parse.final = tonumber(fields[5]) or 0;
                parse.minutes = {
                    ParseStringNumberOrNil(fields[6]),
                    ParseStringNumberOrNil(fields[7]),
                    ParseStringNumberOrNil(fields[8])
                };
                parseOk = true;
            elseif kind == "K" then
                parse.__classKey = tostring(fields[2] or "");
            elseif kind == "SP" then
                parse.specKey = ParseGraph.NormalizeParseSpecKey(fields[2]);
            elseif kind == "C" then
                combat = {
                    version = 1,
                    totalDamage = tonumber(fields[2]) or 0,
                    attacks = tonumber(fields[3]) or 0,
                    hits = tonumber(fields[4]) or 0,
                    normals = tonumber(fields[5]) or 0,
                    normalDamage = tonumber(fields[6]) or 0,
                    crits = tonumber(fields[7]) or 0,
                    critDamage = tonumber(fields[8]) or 0,
                    devs = tonumber(fields[9]) or 0,
                    devDamage = tonumber(fields[10]) or 0,
                    min = ParseStringNumberOrNil(fields[11]),
                    max = tonumber(fields[12]) or 0,
                    maxSkill = fields[13],
                    maxTarget = fields[14],
                    duration = tonumber(fields[15]) or 0,
                    benefitCount = tonumber(fields[16]) or 0,
                    skills = {},
                    benefits = {}
                };
                parse.combat = combat;
            elseif kind == "S" then
                if combat == nil then
                    combat = ParseGraph.NewParseCombatSummary();
                    parse.combat = combat;
                end
                local bucket = DecodeParseStringBucket(fields);
                if tostring(bucket.name or "") ~= "" then
                    combat.skills[bucket.name] = bucket;
                end
            elseif kind == "B" then
                if combat == nil then
                    combat = ParseGraph.NewParseCombatSummary();
                    parse.combat = combat;
                end
                local name = tostring(fields[2] or "");
                if name ~= "" then
                    combat.benefits[name] = {
                        name = name,
                        count = tonumber(fields[3]) or 0
                    };
                end
            end
        end
    end

    if headerOk ~= true or parseOk ~= true then
        return nil, "That does not look like a valid ParseString.";
    end

    return parse, nil;
end

local function CenterParseStringWindow(window)
    local displayW = Turbine.UI.Display.GetWidth();
    local displayH = Turbine.UI.Display.GetHeight();
    window:SetPosition(math.floor((displayW - window:GetWidth()) / 2), math.floor((displayH - window:GetHeight()) / 2));
end

function ParseGraph.ShowParseStringExportWindow(parseString)
    if parseString == nil or parseString == "" then
        Turbine.Shell.WriteLine("ParseGraph: could not create ParseString for this parse.");
        return;
    end

    if ParseGraph.ParseStringExportWindow == nil then
        local window = Turbine.UI.Lotro.Window();
        ParseGraph.ParseStringExportWindow = window;
        window:SetSize(720, 420);
        window:SetText("ParseString");
        window:SetVisible(false);
        window:SetZOrder(200);
        CenterParseStringWindow(window);

        local panel = Panel(window, 12, 34, 696, 350, 1.00);
        panel:SetBackColor(Turbine.UI.Color(1.00, 0, 0, 0));
        DrawAchievementBorder(panel, 696, 350, Turbine.UI.Color(1.00, 0.95, 0.56, 0.12));

        local instruction = Label(panel, 12, 8, 672, 24, "Select all, then press Ctrl+C to copy this ParseString.", "big");
        instruction:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        instruction:SetForeColor(Turbine.UI.Color(1.00, 1.00, 0.82, 0.16));

        local textBox = Turbine.UI.Lotro.TextBox();
        textBox:SetParent(panel);
        textBox:SetPosition(16, 42);
        textBox:SetSize(664, 250);
        textBox:SetFont(Turbine.UI.Lotro.Font.Arial12);
        pcall(function()
            textBox:SetMultiline(true);
        end);
        textBox:SetBackColor(Turbine.UI.Color(1.00, 0.02, 0.02, 0.02));
        textBox:SetForeColor(Turbine.UI.Color(1.00, 0.92, 0.90, 0.84));
        pcall(function()
            textBox:SetReadOnly(true);
        end);
        window.TextBox = textBox;

        local selectAll = ParseGraph.CreateActionButton(panel, 208, 312, 145, 22, "Select all", function()
            pcall(function()
                window.TextBox:Focus();
            end);
            pcall(function()
                window.TextBox:SelectAll();
            end);
        end);
        selectAll:SetZOrder(10);

        local close = ParseGraph.CreateActionButton(panel, 372, 312, 145, 22, "Close", function()
            window:SetVisible(false);
        end);
        close:SetZOrder(10);
    end

    ParseGraph.ParseStringExportWindow.TextBox:SetText(parseString);
    ParseGraph.ParseStringExportWindow:SetVisible(true);
    ParseGraph.ParseStringExportWindow:Activate();
    pcall(function()
        ParseGraph.ParseStringExportWindow.TextBox:Focus();
    end);
    pcall(function()
        ParseGraph.ParseStringExportWindow.TextBox:SelectAll();
    end);
end

function ParseGraph.ShowParseStringImportWindow()
    if ParseGraph.ParseStringImportWindow == nil then
        local window = Turbine.UI.Lotro.Window();
        ParseGraph.ParseStringImportWindow = window;
        window:SetSize(720, 420);
        window:SetText("Import ParseString");
        window:SetVisible(false);
        window:SetZOrder(200);
