        local instruction = Label(panel, 12, 8, 672, 24, "Paste a ParseString here. Imported parses are saved for later compare.", "big");
        instruction:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        instruction:SetForeColor(Turbine.UI.Color(1.00, 1.00, 0.82, 0.16));

        local textBox = Turbine.UI.Lotro.TextBox();
        textBox:SetParent(panel);
        textBox:SetPosition(16, 42);
        textBox:SetSize(664, 238);
        textBox:SetFont(Turbine.UI.Lotro.Font.Arial12);
        pcall(function()
            textBox:SetMultiline(true);
        end);
        textBox:SetBackColor(Turbine.UI.Color(1.00, 0.02, 0.02, 0.02));
        textBox:SetForeColor(Turbine.UI.Color(1.00, 0.92, 0.90, 0.84));
        window.TextBox = textBox;

        local status = Label(panel, 16, 286, 664, 20, "", "achievementDetail");
        status:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        status:SetForeColor(Turbine.UI.Color(1.00, 1.00, 0.82, 0.16));
        window.StatusLabel = status;

        local import = ParseGraph.CreateActionButton(panel, 208, 312, 145, 22, "Import", function()
            local parse, err = ParseGraph.ParseParseString(window.TextBox:GetText());
            if parse == nil then
                window.StatusLabel:SetText(err or "Could not import that ParseString.");
                window.StatusLabel:SetForeColor(Turbine.UI.Color(1.00, 1.00, 0.25, 0.25));
                return;
            end

            ParseGraph.ImportedParseCounter = (tonumber(ParseGraph.ImportedParseCounter) or 0) + 1;
            local sourceIndex = ParseGraph.ImportedParseCounter;
            local sourceKey = "__ParseString_" .. tostring(sourceIndex);
            parse.__sourceKey = sourceKey;
            parse.__sourceIndex = sourceIndex;
            parse.__sourceName = tostring(parse.__sourceName or "Shared parse");
            parse.__displayIndex = "Shared parse";
            local importedPoint = ParseGraph.AddImportedParse(parse, sourceIndex, sourceKey);

            window:SetVisible(false);
            ParseGraph.OpenParseDetail(importedPoint, "history");
        end);
        import:SetZOrder(10);

        local close = ParseGraph.CreateActionButton(panel, 372, 312, 145, 22, "Close", function()
            window:SetVisible(false);
        end);
        close:SetZOrder(10);
    end

    ParseGraph.ParseStringImportWindow.TextBox:SetText("");
    ParseGraph.ParseStringImportWindow.StatusLabel:SetText("");
    ParseGraph.ParseStringImportWindow:SetVisible(true);
    ParseGraph.ParseStringImportWindow:Activate();
    pcall(function()
        ParseGraph.ParseStringImportWindow.TextBox:Focus();
    end);
end

function ParseGraph.GetParseCompareKey(sourceKey, sourceIndex)
    return tostring(sourceKey or "") .. "|" .. tostring(tonumber(sourceIndex) or 0);
end

function ParseGraph.MakeParseCompareSelection(point, returnView)
    if point == nil or point.parse == nil then
        return nil;
    end

    local parse = point.parse;
    local parseIndex = tonumber(point.index) or 0;
    local sourceKey = tostring(parse.__sourceKey or point.sourceKey or ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey());
    local sourceIndex = tonumber(parse.__sourceIndex or point.sourceIndex or parseIndex) or parseIndex;
    if sourceIndex <= 0 then
        return nil;
    end

    return {
        parse = parse,
        index = parseIndex > 0 and parseIndex or sourceIndex,
        sourceKey = sourceKey,
        sourceIndex = sourceIndex,
        sourceName = tostring(parse.__sourceName or point.sourceName or ParseGraph.GetCharacterDisplayName(sourceKey)),
        classKey = ParseGraph.GetParsePointClassKey(point),
        key = ParseGraph.GetParseCompareKey(sourceKey, sourceIndex),
        displayIndex = point.displayIndex or parse.__displayIndex,
        returnView = tostring(returnView or point.returnView or ParseGraph.CurrentView or "history")
    };
end

function ParseGraph.IsParseCompareSelected(sourceKey, sourceIndex)
    local key = ParseGraph.GetParseCompareKey(sourceKey, sourceIndex);
    for i = 1, #(ParseGraph.ParseCompareSelections or {}) do
        if ParseGraph.ParseCompareSelections[i].key == key then
            return true;
        end
    end
    return false;
end

function ParseGraph.GetActiveCompareSelections()
    local valid = {};
    for i = 1, #(ParseGraph.ParseCompareSelections or {}) do
        local selection = ParseGraph.ParseCompareSelections[i];
        local parse = ParseGraph.GetParseBySource(selection.sourceKey, selection.sourceIndex) or selection.parse;
        if parse ~= nil then
            selection.parse = parse;
            selection.index = tonumber(selection.index) or tonumber(selection.sourceIndex) or 0;
            selection.sourceName = tostring(selection.sourceName or parse.__sourceName or ParseGraph.GetCharacterDisplayName(selection.sourceKey));
            selection.displayIndex = selection.displayIndex or parse.__displayIndex;
            selection.classKey = ParseGraph.GetCompareSelectionClassKey(selection);
            selection.key = ParseGraph.GetParseCompareKey(selection.sourceKey, selection.sourceIndex);
            if ParseGraph.CanCompareParsePoint(selection) then
                table.insert(valid, selection);
            end
        end
    end
    ParseGraph.ParseCompareSelections = valid;
    return valid;
end

function ParseGraph.ClearParseCompareSelections()
    ParseGraph.ParseCompareSelections = {};
    if ParseGraph.CurrentView == "parseDetail" then
        ParseGraph.ParseCompareViewActive = true;
        ParseGraph.DrawParseDetailView();
    elseif ParseGraph.CurrentView == "history" then
        ParseGraph.DrawParseHistoryView();
    end
end

function ParseGraph.OpenParseCompareView(returnView)
    ParseGraph.HideParseDetailTooltip();
    local active = ParseGraph.GetActiveCompareSelections();
    local latest = active[#active];
    ParseGraph.ParseCompareViewActive = true;
    if latest ~= nil then
        ParseGraph.SelectedParseDetail = {
            parse = latest.parse,
            index = latest.index,
            sourceKey = latest.sourceKey,
            sourceIndex = latest.sourceIndex,
            sourceName = latest.sourceName,
            returnView = tostring(returnView or latest.returnView or "history")
        };
    else
        ParseGraph.SelectedParseDetail = {
            returnView = tostring(returnView or ParseGraph.CurrentView or "history")
        };
    end
    ParseGraph.SetView("parseDetail");
end

function ParseGraph.SetParseCompareSelected(point, selected, openWhenReady)
    local selection = ParseGraph.MakeParseCompareSelection(point, point and point.returnView);
    if selection == nil then
        return;
    end

    if selected == true and not ParseGraph.CanCompareParsePoint(selection) then
        ParseGraph.PrintParseMessage({
            { text = " You can only compare parses from the same class.", color = "FF4444" }
        });
        return false;
    end

    local key = selection.key;
    local existingIndex = nil;
    for i = 1, #(ParseGraph.ParseCompareSelections or {}) do
        if ParseGraph.ParseCompareSelections[i].key == key then
            existingIndex = i;
            break;
        end
    end

    if selected == true then
        local selectionClassKey = ParseGraph.GetCompareSelectionClassKey(selection);
        for i = 1, #(ParseGraph.ParseCompareSelections or {}) do
            local existing = ParseGraph.ParseCompareSelections[i];
            if type(existing) == "table" and existing.key ~= key then
                local existingClassKey = ParseGraph.GetCompareSelectionClassKey(existing);
                if selectionClassKey ~= "" and existingClassKey ~= "" and selectionClassKey ~= existingClassKey then
                    ParseGraph.PrintParseMessage({
                        { text = " You can only compare parses from the same class.", color = "FF4444" }
                    });
                    return false;
                end
            end
        end

        if existingIndex == nil then
            table.insert(ParseGraph.ParseCompareSelections, selection);
        else
            ParseGraph.ParseCompareSelections[existingIndex] = selection;
        end
        while #ParseGraph.ParseCompareSelections > 2 do
            table.remove(ParseGraph.ParseCompareSelections, 1);
        end
    elseif existingIndex ~= nil then
        table.remove(ParseGraph.ParseCompareSelections, existingIndex);
    end

    local active = ParseGraph.GetActiveCompareSelections();
    if openWhenReady == true and #active >= 2 then
        ParseGraph.OpenParseCompareView();
        return;
    end

    if ParseGraph.CurrentView == "parseDetail" then
        ParseGraph.DrawParseDetailView();
    elseif ParseGraph.CurrentView == "history" then
        ParseGraph.DrawParseHistoryView();
    end
    return true;
end

function ParseGraph.OpenParseDetail(point, returnView)
    if point == nil or point.parse == nil then
        return;
    end

    ParseGraph.ParseCompareViewActive = false;
    local parse = point.parse;
    local parseIndex = tonumber(point.index) or 0;
    local sourceKey = tostring(parse.__sourceKey or ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey());
    local sourceIndex = tonumber(parse.__sourceIndex or parseIndex) or parseIndex;
    local backView = tostring(returnView or ParseGraph.CurrentView or "history");
    if backView == "parseDetail" then
        backView = "history";
    end
    ParseGraph.SelectedParseDetail = {
        parse = parse,
        index = parseIndex,
        sourceKey = sourceKey,
        sourceIndex = sourceIndex,
        sourceName = tostring(parse.__sourceName or ParseGraph.GetCharacterDisplayName(sourceKey)),
        returnView = backView
    };
    ParseGraph.SetView("parseDetail");
end

local function FormatCombatPercent(count, total)
    count = tonumber(count) or 0;
    total = tonumber(total) or 0;
    if total <= 0 then
        return "-";
    end
    return string.format("%.1f%%", (count / total) * 100);
end

local function FormatCombatRate(count, seconds)
    count = tonumber(count) or 0;
    seconds = tonumber(seconds) or 0;
    if seconds <= 0 then
        return "-";
    end
    return string.format("%.2f", count / seconds);
end

function ParseGraph.GetSkillIconTable()
    if type(ParseGraph.SkillIconTable) == "table" then
        return ParseGraph.SkillIconTable;
    end

    -- Combat capture does not need the large artwork lookup modules.
    -- Keep the existing fallback when an optional lookup cannot be loaded.
    if type(ParseGraph_GetIcons) ~= "function" then
        pcall(import, "Arebel.ParseGraph.SkillIcons");
    end
    if type(ParseGraph_GetIconLUT) ~= "function" then
        pcall(import, "Arebel.ParseGraph.SkillIconLUT");
    end

    local player = nil;
    pcall(function()
        if Turbine.Gameplay ~= nil and Turbine.Gameplay.LocalPlayer ~= nil then
            player = Turbine.Gameplay.LocalPlayer.GetInstance();
        end
    end);

    local icons = nil;
    if type(ParseGraph_GetIconLUT) == "function" then
        local ok, result = pcall(ParseGraph_GetIconLUT, player);
        if ok and type(result) == "table" then
            icons = result;
        end
    end

    if icons == nil and type(ParseGraph_GetIcons) == "function" then
        local ok, result = pcall(ParseGraph_GetIcons);
        if ok and type(result) == "table" then
            icons = result;
        end
    end

    ParseGraph.SkillIconTable = icons or {};
    return ParseGraph.SkillIconTable;
end

