function ParseGraph.GetSkillIconId(skillName)
    local name = tostring(skillName or "");
    local trimmedName = TrimText(name);
    if (name == "Conviction" or trimmedName == "Conviction") and ParseGraph.GetViewedClassKey() == "burglar" then
        return 1090552337;
    end
    if (name == "Grievous Wounds" or trimmedName == "Grievous Wounds") and ParseGraph.GetViewedClassKey() == "burglar" then
        return 1091414337;
    end
    local override = ParseGraph.SkillIconOverrides[name] or ParseGraph.SkillIconOverrides[trimmedName];
    if override ~= nil then
        if override == false then
            return nil;
        end
        return tonumber(override) or override;
    end

    local icons = ParseGraph.GetSkillIconTable();
    if type(icons) == "table" then
        local icon = icons[name];
        if icon == nil then
            icon = icons[trimmedName];
        end
        if icon ~= nil then
            return tonumber(icon) or icon;
        end
    end
    return nil;
end

local function DrawParseDetailStat(parent, x, y, w, labelText, valueText, valueColor, valueSize, valueHeight)
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local label = Label(parent, x, y, w, 20, labelText, "achievementDetail");
    label:SetForeColor(gold);
    local value = Label(parent, x, y + 20, w, valueHeight or 24, valueText, valueSize or "big");
    value:SetForeColor(valueColor or Turbine.UI.Color(1.00, 0.92, 0.90, 0.84));
    return label, value;
end

function ParseGraph.DisposeManagedIconControl(control)
    if control == nil then
        return;
    end
    pcall(function()
        if control.SetStretchMode ~= nil then
            control:SetStretchMode(nil);
        end
    end);
    pcall(function()
        control:SetVisible(false);
    end);
    pcall(function()
        control:SetPosition(-10000, -10000);
    end);
    pcall(function()
        control:SetSize(0, 0);
    end);
    pcall(function()
        control:SetBackground(nil);
    end);
    pcall(function()
        control:SetParent(nil);
    end);
end

function ParseGraph.DisposeManagedIconItem(item)
    if type(item) ~= "table" then
        return;
    end
    ParseGraph.DisposeManagedIconControl(item.icon);
    ParseGraph.DisposeManagedIconControl(item.iconSlot);
    ParseGraph.DisposeManagedIconControl(item.slot);
    ParseGraph.DisposeManagedIconControl(item.star);
    ParseGraph.DisposeManagedIconControl(item.back);
    ParseGraph.DisposeManagedIconControl(item.viewport);
end

function ParseGraph.SetManagedIconBackground(icon, background)
    if icon == nil or background == nil or tostring(background) == "" then
        return false;
    end

    local ok = pcall(function()
        if icon.SetBlendMode ~= nil and Turbine.UI.BlendMode ~= nil then
            icon:SetBlendMode(Turbine.UI.BlendMode.AlphaBlend);
        end
        icon:SetBackground(background);
        if icon.SetStretchMode ~= nil then
            icon:SetStretchMode(nil);
            icon:SetStretchMode(2);
            icon:SetStretchMode(1);
        end
        icon:SetMouseVisible(false);
    end);
    return ok == true;
end

function ParseGraph.CreateManagedIcon(parent, x, y, w, h, background)
    if parent == nil or background == nil or tostring(background) == "" then
        return nil, false;
    end

    local icon = Turbine.UI.Label();
    icon:SetParent(parent);
    icon:SetPosition(x, y);
    icon:SetSize(w, h);
    icon:SetMouseVisible(false);
    pcall(function()
        icon:SetClipMode(true);
    end);

    if ParseGraph.SetManagedIconBackground(icon, background) == true then
        return icon, true;
    end

    ParseGraph.DisposeManagedIconControl(icon);
    return nil, false;
end

function ParseGraph.CreateStableManagedIcon(parent, x, y, w, h, background, padding, backColor)
    if parent == nil or background == nil or tostring(background) == "" then
        return nil, nil, false;
    end

    local pad = tonumber(padding) or 0;
    local slot = Turbine.UI.Control();
    slot:SetParent(parent);
    slot:SetPosition(x, y);
    slot:SetSize(w, h);
    slot:SetMouseVisible(false);
    if backColor ~= nil then
        slot:SetBackColor(backColor);
    end
    pcall(function()
        slot:SetClipMode(true);
    end);

    local icon = Turbine.UI.Label();
    icon:SetParent(slot);
    icon:SetPosition(pad, pad);
    icon:SetSize(math.max(1, w - (pad * 2)), math.max(1, h - (pad * 2)));
    icon:SetMouseVisible(false);
    pcall(function()
        icon:SetClipMode(true);
    end);

    if ParseGraph.SetManagedIconBackground(icon, background) == true then
        return slot, icon, true;
    end

    ParseGraph.DisposeManagedIconControl(icon);
    ParseGraph.DisposeManagedIconControl(slot);
    return nil, nil, false;
end
function ParseGraph.SetHistoryCardIconItemVisible(item, visible)
    if type(item) ~= "table" then
        return;
    end

    if item.viewport ~= nil then item.viewport:SetVisible(visible); end
    if item.back ~= nil then item.back:SetVisible(visible); end
    if item.slot ~= nil then item.slot:SetVisible(visible); end
    if item.iconSlot ~= nil then item.iconSlot:SetVisible(visible); end
    if item.icon ~= nil then item.icon:SetVisible(visible); end
    if item.star ~= nil then item.star:SetVisible(visible); end
end

function ParseGraph.GetHistoryCardIconRowTop(item)
    if type(item) ~= "table" then
        return 0;
    end

    -- Match the BossCodex immunity/effect icon pattern: use the live row
    -- position and clip the managed icon viewport every frame. ScrollBar values
    -- are not reliable enough for LOTRO ListBox clipping and can leave stale
    -- image controls outside the panel.
    if item.row ~= nil then
        local okTop, rowTop = pcall(function()
            return item.row:GetTop();
        end);
        if okTop then
            rowTop = tonumber(rowTop);
            if rowTop ~= nil then
                return rowTop;
            end
        end
    end

    if item.scroll ~= nil and item.rowIndex ~= nil and item.rowH ~= nil then
        local okScroll, scrollValue = pcall(function()
            return item.scroll:GetValue();
        end);
        if okScroll then
            return ((tonumber(item.rowIndex) or 1) - 1) * (tonumber(item.rowH) or 0) - (tonumber(scrollValue) or 0);
        end
    end

    return 0;
end

function ParseGraph.RestoreHistoryCardIconBounds(item)
    if type(item) ~= "table" then
        return;
    end

    if item.viewport ~= nil then
        item.viewport:SetPosition(tonumber(item.viewX) or 0, tonumber(item.viewY) or 0);
        item.viewport:SetSize(math.max(1, tonumber(item.viewW) or 1), math.max(1, tonumber(item.viewH) or 1));
    end
    if item.back ~= nil then
        item.back:SetPosition(tonumber(item.backX) or 0, tonumber(item.backY) or 0);
        item.back:SetSize(math.max(1, tonumber(item.backW) or 1), math.max(1, tonumber(item.backH) or 1));
    end
    if item.slot ~= nil then
        item.slot:SetPosition(tonumber(item.slotX) or 0, tonumber(item.slotY) or 0);
        item.slot:SetSize(math.max(1, tonumber(item.slotW) or 1), math.max(1, tonumber(item.slotH) or 1));
    end
    if item.icon ~= nil then
        item.icon:SetPosition(tonumber(item.iconX) or 0, tonumber(item.iconY) or 0);
        item.icon:SetSize(math.max(1, tonumber(item.iconW) or 1), math.max(1, tonumber(item.iconH) or 1));
    end
    if item.star ~= nil then
        item.star:SetPosition(tonumber(item.starX) or 0, tonumber(item.starY) or 0);
        item.star:SetSize(math.max(1, tonumber(item.starW) or 1), math.max(1, tonumber(item.starH) or 1));
    end
end

function ParseGraph.UpdateHistoryCardIconVisibility(item)
    if type(item) ~= "table" or item.row == nil then
        return false;
    end

    local viewportH = tonumber(item.viewportH) or 0;
    local viewX = tonumber(item.viewX) or tonumber(item.backX) or tonumber(item.slotX) or 0;
    local viewY = tonumber(item.viewY) or tonumber(item.backY) or tonumber(item.slotY) or 0;
    local viewW = math.max(1, tonumber(item.viewW) or tonumber(item.backW) or tonumber(item.slotW) or 1);
    local viewH = math.max(1, tonumber(item.viewH) or tonumber(item.backH) or tonumber(item.slotH) or 1);
    local backX = tonumber(item.backX) or 0;
    local backY = tonumber(item.backY) or 0;
    local visible = true;
    local visibleH = viewH;
    local clipTop = 0;

    if viewportH > 0 and viewH > 0 then
        local rowTop = ParseGraph.GetHistoryCardIconRowTop(item);
        local absoluteTop = rowTop + viewY;
        local absoluteBottom = absoluteTop + viewH;
        local visibleTop = math.max(0, absoluteTop);
        local visibleBottom = math.min(viewportH, absoluteBottom);
        visibleH = visibleBottom - visibleTop;
        visible = visibleH > 0;
        clipTop = visibleTop - absoluteTop;
    end

    if ParseGraph.ParseHistoryView ~= nil and ParseGraph.ParseHistoryView.IsVisible ~= nil then
        local okView, viewVisible = pcall(function()
            return ParseGraph.ParseHistoryView:IsVisible();
        end);
        visible = visible and okView and viewVisible == true;
    end

    if not visible then
        ParseGraph.SetHistoryCardIconItemVisible(item, false);
        if item.viewport ~= nil then
            item.viewport:SetPosition(viewX, -10000);
            item.viewport:SetSize(0, 0);
        elseif item.back ~= nil then
            item.back:SetPosition(backX, -10000);
            item.back:SetSize(0, 0);
        elseif item.slot ~= nil then
            item.slot:SetPosition(tonumber(item.slotX) or 0, -10000);
            item.slot:SetSize(0, 0);
        end
        return false;
    end

    ParseGraph.RestoreHistoryCardIconBounds(item);
    ParseGraph.SetHistoryCardIconItemVisible(item, true);

    if item.viewport ~= nil then
        item.viewport:SetPosition(viewX, viewY + clipTop);
        item.viewport:SetSize(viewW, math.max(1, visibleH));
        if item.back ~= nil then
            item.back:SetPosition(backX, backY - clipTop);
        end
        if item.star ~= nil then
            item.star:SetPosition(tonumber(item.starX) or 0, (tonumber(item.starY) or 0) - clipTop);
        end
    else
        if item.back ~= nil then
            item.back:SetPosition(backX, backY + clipTop);
            item.back:SetSize(math.max(1, tonumber(item.backW) or 1), math.max(1, visibleH));
        end
        if item.slot ~= nil then
            item.slot:SetPosition(tonumber(item.slotX) or 0, (tonumber(item.slotY) or 0) - clipTop);
        end
        if item.star ~= nil then
            item.star:SetPosition(tonumber(item.starX) or 0, (tonumber(item.starY) or 0) - clipTop);
        end
    end

    return true;
end

function ParseGraph.UpdateParseHistoryCardIcons()
    local controls = ParseGraph.ParseHistoryCardIconControls or {};
    for i = 1, #controls do
        local item = controls[i];
        if type(item) == "table" then
            ParseGraph.UpdateHistoryCardIconVisibility(item);
        end
    end
end

function ParseGraph.RegisterHistoryCardIconControl(item)
    if type(item) ~= "table" then
        return;
    end

    ParseGraph.ParseHistoryCardIconControls = ParseGraph.ParseHistoryCardIconControls or {};
    table.insert(ParseGraph.ParseHistoryCardIconControls, item);

    ParseGraph.UpdateHistoryCardIconVisibility(item);
end

function ParseGraph.ParseHistoryMouseWheelDirection(args)
    local direction = 0;
    if type(args) == "table" then
        if args.Direction ~= nil then
            direction = tonumber(args.Direction) or 0;
        elseif args.WheelDelta ~= nil then
            direction = tonumber(args.WheelDelta) or 0;
        elseif args.Forward ~= nil or args.Backward ~= nil then
            if args.Forward == true then
                direction = 1;
            elseif args.Backward == true then
                direction = -1;
            end
        end
    elseif args ~= nil then
        direction = tonumber(args) or 0;
    end
    return direction;
end

function ParseGraph.ScrollParseHistoryListByWheel(args)
    local direction = ParseGraph.ParseHistoryMouseWheelDirection(args);
    if direction == 0 or ParseGraph.ParseHistoryScrollBar == nil then
        return;
    end
    local okValue, current = pcall(function()
        return ParseGraph.ParseHistoryScrollBar:GetValue();
    end);
    if not okValue then
        return;
    end
    local step = 3;
    local nextValue = tonumber(current) or 0;
    if direction > 0 then
        nextValue = nextValue - step;
    else
        nextValue = nextValue + step;
    end
    pcall(function()
        ParseGraph.ParseHistoryScrollBar:SetValue(nextValue);
    end);
    if type(args) == "table" then
        args.Handled = true;
    end
    ParseGraph.UpdateParseHistoryCardIcons();
end

function ParseGraph.AttachParseHistoryWheel(control)
    if control == nil then
        return;
    end
    if control.SetMouseVisible ~= nil then
        control:SetMouseVisible(true);
    end
    control.MouseWheel = function(sender, args)
        ParseGraph.ScrollParseHistoryListByWheel(args);
    end
end

function ParseGraph.UpdateManagedIconClip(item)
    if type(item) ~= "table" or item.iconSlot == nil or item.icon == nil or item.row == nil then
        return false;
    end

    local viewportH = tonumber(item.viewportH);
    local slotX = tonumber(item.slotX) or 0;
    local slotY = tonumber(item.slotY) or 0;
    local slotW = tonumber(item.slotW) or 0;
    local slotH = tonumber(item.slotH) or 0;
    local iconX = tonumber(item.iconX) or 0;
    local iconY = tonumber(item.iconY) or 0;
    local iconW = tonumber(item.iconW);
    local iconH = tonumber(item.iconH);
    local keepSize = item.keepSize == true;

    if viewportH == nil or viewportH <= 0 or slotW <= 0 or slotH <= 0 then
        item.iconSlot:SetVisible(true);
        item.icon:SetVisible(true);
        item.iconSlot:SetPosition(slotX, slotY);
        item.iconSlot:SetSize(slotW, slotH);
        item.icon:SetPosition(iconX, iconY);
        if iconW ~= nil and iconH ~= nil then
            item.icon:SetSize(iconW, iconH);
        end
        return true;
    end

    local okTop, rowTop = pcall(function()
        return item.row:GetTop();
    end);
    if not okTop then
        return false;
    end

    rowTop = tonumber(rowTop) or 0;
    local absoluteTop = rowTop + slotY;
    local absoluteBottom = absoluteTop + slotH;
    local visibleTop = math.max(0, absoluteTop);
    local visibleBottom = math.min(viewportH, absoluteBottom);
    local visibleH = visibleBottom - visibleTop;
    local visible = visibleH > 0;

    item.iconSlot:SetVisible(visible);
    item.icon:SetVisible(visible);
    if visible then
        if keepSize then
            item.iconSlot:SetPosition(slotX, slotY);
            item.iconSlot:SetSize(slotW, slotH);
            item.icon:SetPosition(iconX, iconY);
        else
            local clipTop = visibleTop - absoluteTop;
            item.iconSlot:SetPosition(slotX, slotY + clipTop);
            item.iconSlot:SetSize(slotW, visibleH);
            item.icon:SetPosition(iconX, iconY - clipTop);
        end
        if iconW ~= nil and iconH ~= nil then
            item.icon:SetSize(iconW, iconH);
        end
    end

    return visible;
end
function ParseGraph.SetParseCompareIconsSuppressed(suppressed)
    ParseGraph.ParseCompareIconsSuppressed = suppressed == true;
    ParseGraph.UpdateParseCompareIcons();
end

function ParseGraph.UpdateParseCompareIcons()
    local controls = ParseGraph.ParseCompareIconControls or {};
    for i = 1, #controls do
        local item = controls[i];
        if type(item) == "table" then
            if type(item.update) == "function" then
                pcall(item.update);
            else
                pcall(function()
                    if item.iconSlot ~= nil then
                        item.iconSlot:SetVisible(ParseGraph.ParseCompareIconsSuppressed ~= true);
                    end
                    if item.icon ~= nil then
                        item.icon:SetVisible(ParseGraph.ParseCompareIconsSuppressed ~= true);
                    end
                end);
            end
        end
    end
end

function ParseGraph.ClearParseCompareIcons()
    local controls = ParseGraph.ParseCompareIconControls or {};
    for i = 1, #controls do
        ParseGraph.DisposeManagedIconItem(controls[i]);
    end
    ParseGraph.ParseCompareIconControls = {};
    ParseGraph.ParseCompareIconsSuppressed = false;
    ParseGraph.ParseCompareTooltipRect = nil;
    ParseGraph.ParseCompareListBox = nil;
end

function ParseGraph.HideParseDetailTooltip()
    if ParseGraph.ParseDetailTooltip ~= nil then
        ParseGraph.ParseDetailTooltip:SetVisible(false);
    end
    if ParseGraph.ParseDetailHitsTooltip ~= nil then
        ParseGraph.ParseDetailHitsTooltip:SetVisible(false);
    end
    ParseGraph.ParseCompareTooltipRect = nil;
    ParseGraph.SetParseCompareIconsSuppressed(false);
end

function ParseGraph.ShowParseDetailTooltip(parent, titleText, valueText, x, y)
    if parent == nil then
        return;
    end

    if ParseGraph.ParseDetailTooltip == nil or ParseGraph.ParseDetailTooltipParent ~= parent then
        local tip = Turbine.UI.Control();
        tip:SetParent(parent);
        tip:SetSize(270, 70);
        tip:SetBackColor(Turbine.UI.Color(0.98, 0.01, 0.01, 0.01));
        tip:SetMouseVisible(false);
        tip:SetZOrder(1000);

        local border = Turbine.UI.Color(1, 0.94, 0.64, 0.06);
        tip.topBorder = DrawBlock(tip, 0, 0, 270, 1, border);
        tip.bottomBorder = DrawBlock(tip, 0, 69, 270, 1, border);
        tip.leftBorder = DrawBlock(tip, 0, 0, 1, 70, border);
        tip.rightBorder = DrawBlock(tip, 269, 0, 1, 70, border);

        tip.title = Label(tip, 10, 6, 250, 20, "", "big");
        tip.title:SetFont(Turbine.UI.Lotro.Font.TrajanProBold16);
        tip.title:SetForeColor(Turbine.UI.Color(1.00, 1.00, 1.00, 1.00));
        tip.title:SetZOrder(1005);

        tip.value = Label(tip, 10, 28, 250, 32, "", "big");
        tip.value:SetFont(Turbine.UI.Lotro.Font.TrajanPro16);
        tip.value:SetForeColor(Turbine.UI.Color(1.00, 1.00, 0.82, 0.16));
        tip.value:SetZOrder(1005);

        ParseGraph.ParseDetailTooltip = tip;
        ParseGraph.ParseDetailTooltipParent = parent;
    end

    local width = 270;
    local height = 70;
    ParseGraph.ParseDetailTooltip:SetSize(width, height);
    ParseGraph.ParseDetailTooltip.topBorder:SetSize(width, 1);
    ParseGraph.ParseDetailTooltip.bottomBorder:SetPosition(0, height - 1);
    ParseGraph.ParseDetailTooltip.bottomBorder:SetSize(width, 1);
    ParseGraph.ParseDetailTooltip.leftBorder:SetSize(1, height);
    ParseGraph.ParseDetailTooltip.rightBorder:SetPosition(width - 1, 0);
    ParseGraph.ParseDetailTooltip.rightBorder:SetSize(1, height);
    ParseGraph.ParseDetailTooltip.title:SetText(tostring(titleText or ""));
    ParseGraph.ParseDetailTooltip.value:SetText(tostring(valueText or ""));

    x = tonumber(x) or 520;
    y = tonumber(y) or 230;
    if x + width > parent:GetWidth() then
        x = math.max(0, parent:GetWidth() - width - 6);
    end
    if y + height > parent:GetHeight() then
        y = math.max(0, y - height - 8);
    end
    ParseGraph.ParseDetailTooltip:SetPosition(x, y);
    ParseGraph.ParseDetailTooltip:SetVisible(true);
    ParseGraph.ParseCompareTooltipRect = { x = x, y = y, w = width, h = height };
end

local function BindParseDetailTooltip(control, parent, titleText, valueText, x, y)
    if control == nil or tostring(valueText or "") == "" then
        return;
    end

    pcall(function()
        control:SetMouseVisible(true);
    end);
    control.MouseEnter = function()
        ParseGraph.ShowParseDetailTooltip(parent, titleText, valueText, x, y);
    end
    control.MouseLeave = function()
        ParseGraph.HideParseDetailTooltip();
    end
end

function ParseGraph.ShowHitsColourTooltip(parent, x, y, titleText)
    if parent == nil then
        return;
    end

    local width = 330;
    local height = 112;
    local border = Turbine.UI.Color(1, 0.94, 0.64, 0.06);
    local white = Turbine.UI.Color(1.00, 0.92, 0.90, 0.84);
    local green = Turbine.UI.Color(1.00, 0.35, 1.00, 0.30);
    local red = Turbine.UI.Color(1.00, 1.00, 0.25, 0.25);

    if ParseGraph.ParseDetailHitsTooltip == nil or ParseGraph.ParseDetailHitsTooltipParent ~= parent then
        local tip = Turbine.UI.Control();
        tip:SetParent(parent);
        tip:SetSize(width, height);
        tip:SetBackColor(Turbine.UI.Color(0.98, 0.01, 0.01, 0.01));
        tip:SetMouseVisible(false);
        tip:SetZOrder(1000);

        tip.topBorder = DrawBlock(tip, 0, 0, width, 1, border);
        tip.bottomBorder = DrawBlock(tip, 0, height - 1, width, 1, border);
        tip.leftBorder = DrawBlock(tip, 0, 0, 1, height, border);
        tip.rightBorder = DrawBlock(tip, width - 1, 0, 1, height, border);

        tip.title = Label(tip, 10, 6, width - 20, 20, "", "big");
        tip.title:SetFont(Turbine.UI.Lotro.Font.TrajanProBold16);
        tip.title:SetForeColor(Turbine.UI.Color(1.00, 1.00, 1.00, 1.00));
        tip.title:SetZOrder(1005);

        local function AddLine(lineY, word, wordColor, text)
            local wordLabel = Label(tip, 14, lineY, 56, 18, word, "achievementDetail");
            wordLabel:SetForeColor(wordColor);
            wordLabel:SetZOrder(1005);
            local textLabel = Label(tip, 72, lineY, width - 88, 18, text, "achievementDetail");
            textLabel:SetForeColor(white);
            textLabel:SetZOrder(1005);
        end

        AddLine(32, "Green", green, "= More than 2.5% of average");
        AddLine(56, "White", white, "= Around average");
        AddLine(80, "Red", red, "= Lower than 2.5% of average");

        ParseGraph.ParseDetailHitsTooltip = tip;
        ParseGraph.ParseDetailHitsTooltipParent = parent;
    end

    ParseGraph.ParseDetailHitsTooltip.title:SetText(tostring(titleText or "Hits colours"));

    x = tonumber(x) or 180;
    y = tonumber(y) or 150;
    if x + width > parent:GetWidth() then
        x = math.max(0, parent:GetWidth() - width - 6);
    end
    if y + height > parent:GetHeight() then
        y = math.max(0, y - height - 8);
    end
    ParseGraph.ParseDetailHitsTooltip:SetPosition(x, y);
    ParseGraph.ParseDetailHitsTooltip:SetVisible(true);
    ParseGraph.ParseCompareTooltipRect = { x = x, y = y, w = width, h = height };
end

local function BindParseHitsTooltip(control, parent, x, y, titleText)
    if control == nil then
        return;
    end

    pcall(function()
        control:SetMouseVisible(true);
    end);
    control.MouseEnter = function()
        ParseGraph.ShowHitsColourTooltip(parent, x, y, titleText);
    end
    control.MouseLeave = function()
        ParseGraph.HideParseDetailTooltip();
    end
end

GetParseDetailComparisonParses = function(selection)
    if ParseGraph.IsCombineSameClassActive() then
        return ParseGraph.GetViewParses();
    end

    local currentKey = ParseGraph.GetCurrentCharacterKey();
    local viewKey = tostring(ParseGraph.ViewCharacterKey or currentKey);
    local sourceKey = tostring(selection and selection.sourceKey or viewKey);
    if sourceKey == viewKey then
        return ParseGraph.Parses or {};
    end

    local characters = ParseGraph.AccountData and ParseGraph.AccountData.characters or {};
    local entry = characters[sourceKey];
    if type(entry) == "table" and type(entry.parses) == "table" then
        return entry.parses;
    end

    return {};
end

BuildParseDetailCountAverages = function(parses)
    local totals = {
        skills = {},
        benefits = {},
        skillDamage = {},
        skillCrit = {},
        skillDev = {}
    };
    local samples = {
        skills = {},
        benefits = {},
        skillDamage = {},
        skillCrit = {},
        skillDev = {}
    };

    local function add(kind, name, count)
        name = tostring(name or "");
        count = tonumber(count) or 0;
        if name == "" or count <= 0 then
            return;
        end
        totals[kind][name] = (tonumber(totals[kind][name]) or 0) + count;
        samples[kind][name] = (tonumber(samples[kind][name]) or 0) + 1;
    end

    if type(parses) == "table" then
        for i = 1, #parses do
            local combat = parses[i] and parses[i].combat;
            if type(combat) == "table" then
                if type(combat.skills) == "table" then
                    for _, bucket in pairs(combat.skills) do
                        if type(bucket) == "table" then
                            local hits = tonumber(bucket.hits or bucket.attacks) or 0;
                            add("skills", bucket.name, hits);
                            add("skillDamage", bucket.name, bucket.totalDamage);
                            if hits > 0 then
                                add("skillCrit", bucket.name, (tonumber(bucket.crits) or 0) / hits);
                                add("skillDev", bucket.name, (tonumber(bucket.devs) or 0) / hits);
                            end
                        end
                    end
                end
                if type(combat.benefits) == "table" then
                    for _, bucket in pairs(combat.benefits) do
                        if type(bucket) == "table" then
                            add("benefits", bucket.name, bucket.count);
                        end
                    end
                end
            end
        end
    end

    local averages = {
        skills = {},
        benefits = {},
        skillDamage = {},
        skillCrit = {},
        skillDev = {}
    };
    for kind, kindTotals in pairs(totals) do
        for name, total in pairs(kindTotals) do
            local sampleCount = tonumber(samples[kind][name]) or 0;
            if sampleCount > 0 then
                averages[kind][name] = total / sampleCount;
            end
        end
    end

    return averages;
end

GetParseDetailCountColor = function(value, average, defaultColor)
    value = tonumber(value);
    average = tonumber(average);
    if value == nil or average == nil or average <= 0 then
        return defaultColor;
    end
    if value >= average * 1.025 then
        return Turbine.UI.Color(1.00, 0.24, 1.00, 0.33);
    elseif value <= average * 0.975 then
        return Turbine.UI.Color(1.00, 1.00, 0.26, 0.26);
    end
    return defaultColor;
end

local function GetParseDetailBucketRate(bucket, field)
    if type(bucket) ~= "table" then
        return nil;
    end

    local hits = tonumber(bucket.hits or bucket.attacks) or 0;
    if hits <= 0 then
        return nil;
    end
    return (tonumber(bucket[field]) or 0) / hits;
end

local function GetParseDetailSkillMetricColors(bucket, countAverages, defaultColor)
    countAverages = type(countAverages) == "table" and countAverages or {};
    local skillName = tostring(bucket and bucket.name or "");
    local hits = tonumber(bucket and (bucket.hits or bucket.attacks)) or 0;
    local damage = tonumber(bucket and bucket.totalDamage) or 0;
    local critRate = GetParseDetailBucketRate(bucket, "crits");
    local devRate = GetParseDetailBucketRate(bucket, "devs");

    return
        GetParseDetailCountColor(hits, (countAverages.skills or {})[skillName], defaultColor),
        GetParseDetailCountColor(damage, (countAverages.skillDamage or {})[skillName], defaultColor),
        GetParseDetailCountColor(critRate, (countAverages.skillCrit or {})[skillName], defaultColor),
        GetParseDetailCountColor(devRate, (countAverages.skillDev or {})[skillName], defaultColor);
end

local function DrawParseCompareCheckbox(parent, x, y, point, openWhenReady, openWithOne, hideLabel)
    local selection = ParseGraph.MakeParseCompareSelection(point);
    if selection == nil then
        return nil;
    end
    if not ParseGraph.CanCompareParsePoint(selection) then
        return nil;
    end

    local checkbox = Turbine.UI.Lotro.CheckBox();
    checkbox:SetParent(parent);
    checkbox:SetPosition(x, y);
    checkbox:SetSize(22, 22);
    checkbox:SetText("");
    checkbox:SetChecked(ParseGraph.IsParseCompareSelected(selection.sourceKey, selection.sourceIndex));
    checkbox:SetZOrder(120);
    checkbox.comparePoint = point;
    checkbox.openWithOne = openWithOne == true;
    checkbox.CheckedChanged = function(sender)
        if sender.suppressCompareChanged == true then
            return;
        end
        ParseGraph.HideParseDetailTooltip();
        local checked = sender:IsChecked();
        if checked == true and sender.openWithOne == true then
            local accepted = ParseGraph.SetParseCompareSelected(sender.comparePoint, true, false);
            if accepted == false then
                sender.suppressCompareChanged = true;
                sender:SetChecked(false);
                sender.suppressCompareChanged = false;
                return;
            end
            ParseGraph.OpenParseCompareView("parseDetail");
        else
            local accepted = ParseGraph.SetParseCompareSelected(sender.comparePoint, checked, openWhenReady == true);
            if accepted == false and checked == true then
                sender.suppressCompareChanged = true;
                sender:SetChecked(false);
                sender.suppressCompareChanged = false;
            end
        end
    end

    if hideLabel ~= true then
        local label = Label(parent, x + 25, y + 3, 86, 22, "Compare", "achievementDetail");
        label:SetForeColor(Turbine.UI.Color(1.00, 1.00, 0.82, 0.16));
        label:SetZOrder(120);
        label:SetMouseVisible(true);
        label.MouseClick = function()
            checkbox:SetChecked(not checkbox:IsChecked());
        end
    end

    return checkbox;
end

local function DrawCompareModeCheckbox(parent, x, y)
    local checkbox = Turbine.UI.Lotro.CheckBox();
    checkbox:SetParent(parent);
    checkbox:SetPosition(x, y);
    checkbox:SetSize(22, 22);
    checkbox:SetText("");
    checkbox:SetChecked(true);
    checkbox:SetZOrder(120);
    checkbox.CheckedChanged = function(sender)
        if sender:IsChecked() ~= true then
            ParseGraph.ClearParseCompareSelections();
        end
    end

    local label = Label(parent, x + 25, y + 3, 86, 22, "Compare", "achievementDetail");
    label:SetForeColor(Turbine.UI.Color(1.00, 1.00, 0.82, 0.16));
    label:SetZOrder(120);
    label:SetMouseVisible(true);
    label.MouseClick = function()
        checkbox:SetChecked(false);
    end
end

local function DrawParseCompareSlotCheckbox(parent, x, y, selection)
    if selection == nil then
        return nil;
    end

    local checkbox = Turbine.UI.Lotro.CheckBox();
    checkbox:SetParent(parent);
    checkbox:SetPosition(x, y);
    checkbox:SetSize(22, 22);
    checkbox:SetText("");
    checkbox:SetChecked(true);
    checkbox:SetZOrder(120);
    checkbox.comparePoint = selection;
    checkbox.CheckedChanged = function(sender)
        if sender:IsChecked() ~= true then
            ParseGraph.ParseCompareViewActive = true;
            ParseGraph.SetParseCompareSelected(sender.comparePoint, false, false);
        end
    end

    return checkbox;
end

local function GetParseCombatLists(combat)
    local skills = {};
    if type(combat) == "table" and type(combat.skills) == "table" then
        for _, bucket in pairs(combat.skills) do
            if type(bucket) == "table" then
                table.insert(skills, bucket);
            end
        end
    end
    table.sort(skills, function(a, b)
        return (tonumber(a.totalDamage) or 0) > (tonumber(b.totalDamage) or 0);
    end);

    local benefits = {};
    if type(combat) == "table" and type(combat.benefits) == "table" then
        for _, bucket in pairs(combat.benefits) do
            if type(bucket) == "table" then
                table.insert(benefits, bucket);
            end
        end
    end
    table.sort(benefits, function(a, b)
        local ac = tonumber(a.count) or 0;
        local bc = tonumber(b.count) or 0;
        if ac == bc then
            return tostring(a.name or "") < tostring(b.name or "");
        end
        return ac > bc;
    end);

    return skills, benefits;
end

local function DrawParseCompareStat(parent, x, y, w, labelText, valueText, valueColor)
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local label = Label(parent, x, y, w, 18, labelText, "achievementDetail");
    label:SetForeColor(gold);
    label:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    label:SetMouseVisible(false);

    local value = Label(parent, x, y + 18, w, 20, valueText, "small");
    value:SetForeColor(valueColor or Turbine.UI.Color(1.00, 0.92, 0.90, 0.84));
    value:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    value:SetMouseVisible(false);
    return value;
end

local function GetCompareSkillCounts(selection)
    local counts = {};
    if selection == nil then
        return counts;
    end

    local parse = ParseGraph.GetParseBySource(selection.sourceKey, selection.sourceIndex) or selection.parse;
    local combat = parse ~= nil and parse.combat or nil;
    if type(combat) == "table" and type(combat.skills) == "table" then
        for _, bucket in pairs(combat.skills) do
            if type(bucket) == "table" then
                counts[tostring(bucket.name or "")] = tonumber(bucket.hits or bucket.attacks) or 0;
            end
        end
    end
    return counts;
end

local function GetCompareValueColor(current, peer, defaultColor, tolerance)
    current = tonumber(current) or 0;
    peer = tonumber(peer) or 0;
    tolerance = tonumber(tolerance) or 0;

    if tolerance > 0 then
        local floor = peer * (1 - tolerance);
        local ceiling = peer * (1 + tolerance);
        if current > ceiling then
            return Turbine.UI.Color(1.00, 0.24, 1.00, 0.33);
        elseif current < floor then
            return Turbine.UI.Color(1.00, 1.00, 0.26, 0.26);
        end
        return defaultColor;
    end

    if current > peer then
        return Turbine.UI.Color(1.00, 0.24, 1.00, 0.33);
    elseif current < peer then
        return Turbine.UI.Color(1.00, 1.00, 0.26, 0.26);
    end
    return defaultColor;
end

local function GetCompareRate(bucket, countField)
    if type(bucket) ~= "table" then
        return 0;
    end

    local total = tonumber(bucket.hits or bucket.attacks) or 0;
    if total <= 0 then
        return 0;
    end

    return (tonumber(bucket[countField]) or 0) / total;
end

local function GetComparePointColor(current, peer, defaultColor, tolerance)
    current = tonumber(current) or 0;
    peer = tonumber(peer) or 0;
    tolerance = tonumber(tolerance) or 0;

    if current > peer + tolerance then
        return Turbine.UI.Color(1.00, 0.24, 1.00, 0.33);
    elseif current < peer - tolerance then
        return Turbine.UI.Color(1.00, 1.00, 0.26, 0.26);
    end
    return defaultColor;
end

local function TruncateCompareText(text, maxChars)
    text = tostring(text or "-");
    maxChars = tonumber(maxChars) or 24;
    if string.len(text) <= maxChars then
        return text;
    end
    if maxChars <= 3 then
        return string.sub(text, 1, maxChars);
    end
    return string.sub(text, 1, maxChars - 3) .. "...";
end

local function DrawParseCompareColumn(parent, x, y, w, h, selection, peerSelection)
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local white = Turbine.UI.Color(1.00, 0.92, 0.90, 0.84);
    local muted = Turbine.UI.Color(0.90, 0.70, 0.70, 0.70);
    local parseBlue = Turbine.UI.Color(1.00, 0.45, 0.78, 1.00);
    local black = Turbine.UI.Color(1.00, 0, 0, 0);
    local barColor = Turbine.UI.Color(1.00, 0.345, 0.106, 0.106);

    local panel = Panel(parent, x, y, w, h, 1.00);
    panel:SetBackColor(black);

    local parse = ParseGraph.GetParseBySource(selection.sourceKey, selection.sourceIndex) or selection.parse;
    if parse == nil then
        local missing = Label(panel, 0, 250, w, 40, "That parse could not be found.", "big");
        missing:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        missing:SetForeColor(white);
        return;
    end

    local titleText = selection.displayIndex or selection.index or selection.sourceIndex or "?";
    if tonumber(titleText) ~= nil then
        titleText = "Parse #" .. tostring(titleText);
    else
        titleText = tostring(titleText);
    end
    local title = Label(panel, 0, 0, w, 28, titleText, "achievementTitle");
    title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    title:SetForeColor(gold);
    DrawParseCompareSlotCheckbox(panel, w - 34, 3, selection);
    local subtitle = Label(panel, 0, 28, w, 20, tostring(selection.sourceName or "") .. "   " .. tostring(parse.time or ""), "small");
    subtitle:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    subtitle:SetForeColor(muted);
    DrawBlock(panel, 10, 54, w - 20, 1, border);

    local minutes = parse.minutes or {};
    local statW = math.floor((w - 24) / 4);
    DrawParseCompareStat(panel, 8, 68, statW, "1st", ParseGraph.FormatSummaryNumber(minutes[1]), white);
    DrawParseCompareStat(panel, 8 + statW, 68, statW, "2nd", ParseGraph.FormatSummaryNumber(minutes[2]), white);
    DrawParseCompareStat(panel, 8 + (statW * 2), 68, statW, "3rd", ParseGraph.FormatSummaryNumber(minutes[3]), white);
    DrawParseCompareStat(panel, 8 + (statW * 3), 64, statW, "Final", FormatNumber(parse.final), parseBlue);
    DrawBlock(panel, 10, 120, w - 20, 1, border);

    local combat = parse.combat;
    if type(combat) ~= "table" or (tonumber(combat.attacks) or 0) <= 0 then
        local empty = Label(panel, 0, 245, w, 50, "No detailed combat breakdown was saved for this parse.", "big");
        empty:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        empty:SetForeColor(white);
        return;
    end

    local combatW = math.floor((w - 32) / 3);
    DrawParseCompareStat(panel, 8, 136, combatW, "Damage", FormatNumber(combat.totalDamage), white);
    DrawParseCompareStat(panel, 8 + combatW, 136, combatW, "Hits", FormatNumber(combat.hits or combat.attacks), white);
    DrawParseCompareStat(panel, 8 + (combatW * 2), 136, combatW, "APS", FormatCombatRate(combat.hits or combat.attacks, combat.duration), white);
    DrawParseCompareStat(panel, 8, 184, combatW, "Crit", FormatCombatPercent(combat.crits, combat.hits or combat.attacks), white);
    DrawParseCompareStat(panel, 8 + combatW, 184, combatW, "Dev", FormatCombatPercent(combat.devs, combat.hits or combat.attacks), white);
    DrawParseCompareStat(panel, 8 + (combatW * 2), 184, combatW, "Max hit", FormatNumber(combat.max), white);

    return combat;
end

local function BuildCompareBucketMap(combat, collectionName)
    local map = {};
    if type(combat) ~= "table" or type(combat[collectionName]) ~= "table" then
        return map;
    end

    for _, bucket in pairs(combat[collectionName]) do
        if type(bucket) == "table" then
            local name = tostring(bucket.name or "");
            if name ~= "" then
                map[name] = bucket;
            end
        end
    end
    return map;
end

local function BuildSharedCompareRows(leftMap, rightMap, metricName)
    local rows = {};
    local seen = {};

    for name, bucket in pairs(leftMap or {}) do
        seen[name] = true;
        table.insert(rows, {
            name = name,
            left = bucket,
            right = rightMap and rightMap[name] or nil
        });
    end

    for name, bucket in pairs(rightMap or {}) do
        if seen[name] ~= true then
            table.insert(rows, {
                name = name,
                left = leftMap and leftMap[name] or nil,
                right = bucket
            });
        end
    end

    table.sort(rows, function(a, b)
        local aHasLeft = a.left ~= nil;
        local bHasLeft = b.left ~= nil;
        if aHasLeft ~= bHasLeft then
            return aHasLeft;
        end

        local av = 0;
        local bv = 0;
        if aHasLeft then
            av = tonumber(a.left and a.left[metricName]) or 0;
            bv = tonumber(b.left and b.left[metricName]) or 0;
        else
            av = tonumber(a.right and a.right[metricName]) or 0;
            bv = tonumber(b.right and b.right[metricName]) or 0;
        end
        if av == bv then
            return tostring(a.name or "") < tostring(b.name or "");
        end
        return av > bv;
    end);

    return rows;
end

local function DrawSharedParseCompareBreakdown(parent, leftCombat, rightCombat)
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local white = Turbine.UI.Color(1.00, 0.92, 0.90, 0.84);
    local muted = Turbine.UI.Color(0.90, 0.70, 0.70, 0.70);
    local black = Turbine.UI.Color(1.00, 0, 0, 0);
    local barColor = Turbine.UI.Color(1.00, 0.345, 0.106, 0.106);
    ParseGraph.ClearParseCompareIcons();

    local leftSkills = BuildCompareBucketMap(leftCombat, "skills");
    local rightSkills = BuildCompareBucketMap(rightCombat, "skills");
    local leftBenefits = BuildCompareBucketMap(leftCombat, "benefits");
    local rightBenefits = BuildCompareBucketMap(rightCombat, "benefits");
    local skillRows = BuildSharedCompareRows(leftSkills, rightSkills, "totalDamage");
    local benefitRows = BuildSharedCompareRows(leftBenefits, rightBenefits, "count");

    local maxSkillDamage = 0;
    for i = 1, #skillRows do
        maxSkillDamage = math.max(maxSkillDamage, tonumber(skillRows[i].left and skillRows[i].left.totalDamage) or 0);
        maxSkillDamage = math.max(maxSkillDamage, tonumber(skillRows[i].right and skillRows[i].right.totalDamage) or 0);
    end

    local titleY = 282;
    local tableY = 318;
    local listX = 0;
    local listY = tableY + 28;
    local listW = 852;
    local listH = 292;
    local rowH = 36;
    local sideW = 416;
    local leftX = 0;
    local rightX = 436;

    local title = Label(parent, 0, titleY, 868, 28, "Breakdown", "achievementTitle");
    title:SetFont(Turbine.UI.Lotro.Font.VerdanaBold16);
    title:SetForeColor(gold);
    title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);

    local function DrawHeaders(baseX)
        local columns = {
            { x = 40, w = 128, text = "Skill" },
            { x = 172, w = 42, text = "Hits", align = Turbine.UI.ContentAlignment.MiddleRight, tip = "Green = more hits, red = fewer." },
            { x = 220, w = 84, text = "Damage", align = Turbine.UI.ContentAlignment.MiddleRight, tip = "+/- 5% counts as same." },
            { x = 310, w = 50, text = "Crit", align = Turbine.UI.ContentAlignment.MiddleCenter, tip = "+/- 5 pts counts as same." },
            { x = 366, w = 50, text = "Dev", align = Turbine.UI.ContentAlignment.MiddleCenter, tip = "+/- 1 pt counts as same." }
        };
        for i = 1, #columns do
            local col = columns[i];
            local label = Label(parent, listX + baseX + col.x, tableY, col.w, 18, col.text, "achievementDetail");
            if col.text == "Skill" then
                label:SetFont(Turbine.UI.Lotro.Font.VerdanaBold16);
            else
                label:SetFont(Turbine.UI.Lotro.Font.Verdana14);
            end
            label:SetForeColor(gold);
            label:SetTextAlignment(col.align or Turbine.UI.ContentAlignment.MiddleLeft);
            if col.tip ~= nil then
                BindParseDetailTooltip(label, parent, col.text .. " comparison", col.tip, listX + baseX + col.x - 30, tableY + 24);
            end
        end
    end
    DrawHeaders(leftX);
    DrawHeaders(rightX);
    DrawBlock(parent, listX, tableY + 22, listW, 1, border);

    local list = Turbine.UI.TreeView();
    list:SetParent(parent);
    list:SetPosition(listX, listY);
    list:SetSize(listW, listH);
    list:SetBackColor(black);
    local rootNodes = list:GetNodes();

    local scroll = Turbine.UI.Lotro.ScrollBar();
    scroll:SetParent(parent);
    scroll:SetOrientation(Turbine.UI.Orientation.Vertical);
    scroll:SetPosition(listX + listW + 4, listY);
    scroll:SetSize(12, listH);
    scroll:SetBackColor(black);
    list:SetVerticalScrollBar(scroll);

    local totalHeight = (#skillRows * rowH) + (#benefitRows > 0 and (42 + (#benefitRows * rowH)) or 0);
    scroll:SetVisible(totalHeight > listH);
    ParseGraph.ParseCompareListBox = list;

    local function DrawSide(row, baseX, bucket, peerBucket, rowName, isBenefit)
        local count = 0;
        local barX = baseX + 38;
        local barMaxWidth = sideW - 38;
        if isBenefit == true then
            count = tonumber(bucket and bucket.count) or 0;
        else
            count = tonumber(bucket and (bucket.hits or bucket.attacks)) or 0;
            local damageAmount = tonumber(bucket and bucket.totalDamage) or 0;
            if maxSkillDamage > 0 and damageAmount > 0 then
                local barWidth = math.floor(barMaxWidth * (damageAmount / maxSkillDamage));
                DrawBlock(row, barX, 6, barWidth, 24, barColor):SetMouseVisible(false);
            end
        end

        local peerCount = 0;
        if isBenefit == true then
            peerCount = tonumber(peerBucket and peerBucket.count) or 0;
        else
            peerCount = tonumber(peerBucket and (peerBucket.hits or peerBucket.attacks)) or 0;
        end

        if bucket ~= nil then
            local iconId = ParseGraph.GetSkillIconId(rowName);
            if iconId ~= nil then
                local iconBack = DrawBlock(row, baseX + 2, 2, 36, 32, ParseGraph.ParseRowNormalFill);
                iconBack:SetMouseVisible(false);
                iconBack:SetZOrder(1);
                row.compareIconBacks = row.compareIconBacks or {};

                local icon = Turbine.UI.Control();
                icon:SetParent(row);
                icon:SetPosition(baseX + 4, 2);
                icon:SetSize(32, 32);
                icon:SetMouseVisible(false);
                icon:SetZOrder(2);
                -- Keep game-resource icons at their native 32px size. Stretching them makes
                -- LOTRO render them outside the TreeView clipping layer during fast scrolling.
                local graphicCreated, iconGraphic = pcall(Turbine.UI.Graphic, iconId);
                local iconLoaded = false;
                if graphicCreated == true and iconGraphic ~= nil then
                    iconLoaded = pcall(function()
                        icon:SetBlendMode(Turbine.UI.BlendMode.AlphaBlend);
                        icon:SetBackground(iconGraphic);
                        icon:SetMouseVisible(false);
                    end);
                end
                if iconLoaded ~= true then
                    ParseGraph.DisposeManagedIconControl(iconBack);
                    ParseGraph.DisposeManagedIconControl(icon);
                    iconBack = nil;
                    icon = nil;
                end

                if iconLoaded == true then
                    table.insert(row.compareIconBacks, iconBack);
                    table.insert(ParseGraph.ParseCompareIconControls, {
                        back = iconBack,
                        icon = icon
                    });
                end
            end
        end

        local nameText = bucket == nil and "-" or TruncateCompareText(rowName, 26);
        local name = Label(row, baseX + 40, 5, 128, rowH - 10, nameText, "small");
        name:SetFont(Turbine.UI.Lotro.Font.VerdanaBold16);
        name:SetForeColor(bucket == nil and muted or white);
        name:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
        pcall(function()
            if name.SetMultiline ~= nil then
                name:SetMultiline(false);
            end
        end);
        name:SetMouseVisible(false);
        name:SetZOrder(5);

        local hits = Label(row, baseX + 172, 0, 42, rowH, bucket == nil and "-" or FormatNumber(count), "small");
        hits:SetFont(Turbine.UI.Lotro.Font.Verdana14);
        hits:SetForeColor(bucket == nil and muted or GetCompareValueColor(count, peerCount, white, 0));
        hits:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        hits:SetMouseVisible(false);

        if isBenefit ~= true then
            local damageAmount = tonumber(bucket and bucket.totalDamage) or 0;
            local peerDamageAmount = tonumber(peerBucket and peerBucket.totalDamage) or 0;
            local damage = Label(row, baseX + 220, 0, 84, rowH, bucket == nil and "-" or FormatNumber(bucket.totalDamage), "small");
            damage:SetFont(Turbine.UI.Lotro.Font.Verdana14);
            damage:SetForeColor(bucket == nil and muted or GetCompareValueColor(damageAmount, peerDamageAmount, white, 0.05));
            damage:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
            damage:SetMouseVisible(false);
        damage:SetZOrder(5);

            local critRate = GetCompareRate(bucket, "crits");
            local peerCritRate = GetCompareRate(peerBucket, "crits");
            local crit = Label(row, baseX + 310, 0, 50, rowH, bucket == nil and "-" or FormatCombatPercent(bucket.crits, bucket.hits or bucket.attacks), "small");
            crit:SetFont(Turbine.UI.Lotro.Font.Verdana14);
            crit:SetForeColor(bucket == nil and muted or GetComparePointColor(critRate, peerCritRate, white, 0.05));
            crit:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
            crit:SetMouseVisible(false);
            pcall(function()
                if crit.SetMultiline ~= nil then
                    crit:SetMultiline(false);
                end
            end);

            local devRate = GetCompareRate(bucket, "devs");
            local peerDevRate = GetCompareRate(peerBucket, "devs");
            local dev = Label(row, baseX + 366, 0, 50, rowH, bucket == nil and "-" or FormatCombatPercent(bucket.devs, bucket.hits or bucket.attacks), "small");
            dev:SetFont(Turbine.UI.Lotro.Font.Verdana14);
            dev:SetForeColor(bucket == nil and muted or GetComparePointColor(devRate, peerDevRate, white, 0.01));
            dev:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
            dev:SetMouseVisible(false);
            pcall(function()
                if dev.SetMultiline ~= nil then
                    dev:SetMultiline(false);
                end
            end);
        end
    end

    local function CreateSharedRow()
        local node = Turbine.UI.TreeNode();
        node:SetSize(listW, rowH);
        local row = Panel(node, 0, 0, listW, rowH, 1.00);
        row:SetSize(listW, rowH);
        row:SetBackColor(ParseGraph.ParseRowNormalFill);
        row:SetMouseVisible(true);
        row.MouseEnter = function(sender)
            sender:SetBackColor(ParseGraph.ParseRowHoverFill);
            for i = 1, #(sender.compareIconBacks or {}) do
                sender.compareIconBacks[i]:SetBackColor(ParseGraph.ParseRowHoverFill);
            end
        end
        row.MouseLeave = function(sender)
            sender:SetBackColor(ParseGraph.ParseRowNormalFill);
            for i = 1, #(sender.compareIconBacks or {}) do
                sender.compareIconBacks[i]:SetBackColor(ParseGraph.ParseRowNormalFill);
            end
        end
        pcall(function()
            row:SetClipMode(true);
        end);
        return node, row;
    end

    for i = 1, #skillRows do
        local item = skillRows[i];
        local node, row = CreateSharedRow();
        DrawSide(row, leftX, item.left, item.right, item.name, false);
        DrawSide(row, rightX, item.right, item.left, item.name, false);
        rootNodes:Add(node);
    end

    if #benefitRows > 0 then
        local separatorNode = Turbine.UI.TreeNode();
        separatorNode:SetSize(listW, 42);
        local separator = Turbine.UI.Control();
        separator:SetParent(separatorNode);
        separator:SetSize(listW, 42);
        separator:SetBackColor(black);
        separator:SetMouseVisible(false);
        local benefitTitle = Label(separator, 0, 10, listW, 24, "Benefits", "achievementDetail");
        benefitTitle:SetFont(Turbine.UI.Lotro.Font.VerdanaBold16);
        benefitTitle:SetForeColor(gold);
        benefitTitle:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        DrawBlock(separator, 0, 36, listW, 1, border);
        rootNodes:Add(separatorNode);

        for i = 1, #benefitRows do
            local item = benefitRows[i];
            local node, row = CreateSharedRow();
            DrawSide(row, leftX, item.left, item.right, item.name, true);
            DrawSide(row, rightX, item.right, item.left, item.name, true);
            rootNodes:Add(node);
        end
    end
end

local function GetParseCompareDamage(selection)
    if selection == nil then
        return 0;
    end

    local parse = ParseGraph.GetParseBySource(selection.sourceKey, selection.sourceIndex) or selection.parse;
    if type(parse) ~= "table" then
        return 0;
    end

    if type(parse.combat) == "table" and tonumber(parse.combat.totalDamage) ~= nil then
        return tonumber(parse.combat.totalDamage) or 0;
    end

    return tonumber(parse.final) or 0;
end

local function DrawParseCompareEmptySlot(parent, x, y, w, h)
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local white = Turbine.UI.Color(1.00, 0.92, 0.90, 0.84);
    local black = Turbine.UI.Color(1.00, 0, 0, 0);

    local panel = Panel(parent, x, y, w, h, 1.00);
    panel:SetBackColor(black);
    DrawBlock(panel, 10, 54, w - 20, 1, border);

    local empty = Label(panel, 0, 92, w, 28, "Choose another parse to compare.", "big");
    empty:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    empty:SetForeColor(white);

    local button = ParseGraph.CreateActionButton(panel, math.floor((w - 145) / 2), 132, 145, 22, "Browse", function()
        ParseGraph.ParseCompareViewActive = false;
        ParseGraph.SetView("history");
    end);
    button:SetZOrder(120);
    ParseGraph.ApplyActionButtonState(button);

    local import = ParseGraph.CreateActionButton(panel, math.floor((w - 145) / 2), 162, 145, 22, "Import", function()
        ParseGraph.ShowParseStringImportWindow();
    end);
    import:SetZOrder(120);
    ParseGraph.ApplyActionButtonState(import);

    local hint = Label(panel, 0, 190, w, 24, "Tick a compare box in Parse History.", "achievementDetail");
    hint:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    hint:SetForeColor(gold);

    return nil;
end

local function DrawParseCompareView(selections)
    ParseGraph.HideParseDetailTooltip();
    local parent = ParseGraph.ParseDetailContent;
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);

    parent:SetPosition(6, 20);
    parent:SetSize(868, 700);

    local topParent = Turbine.UI.Control();
    topParent:SetParent(parent);
    topParent:SetPosition(14, 0);
    topParent:SetSize(840, 280);

    if ParseGraph.ParseDetailClearCompareButton ~= nil then
        ParseGraph.ParseDetailClearCompareButton:SetVisible(true);
    end

    local title = Label(topParent, 0, 0, 840, 30, "Compare Parses", "huge");
    title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    title:SetForeColor(gold);
    DrawBlock(topParent, 35, 34, 770, 1, border);
    DrawBlock(topParent, 420, 48, 1, 218, border);

    selections = selections or {};
    local leftSelection = selections[1];
    local rightSelection = selections[2];
    if GetParseCompareDamage(rightSelection) > GetParseCompareDamage(leftSelection) then
        leftSelection = selections[2];
        rightSelection = selections[1];
    end

    local leftCombat = nil;
    local rightCombat = nil;
    if leftSelection ~= nil then
        leftCombat = DrawParseCompareColumn(topParent, 0, 48, 405, 232, leftSelection, rightSelection);
    else
        DrawParseCompareEmptySlot(topParent, 0, 48, 405, 232);
    end
    if rightSelection ~= nil then
        rightCombat = DrawParseCompareColumn(topParent, 435, 48, 405, 232, rightSelection, leftSelection);
    else
        DrawParseCompareEmptySlot(topParent, 435, 48, 405, 232);
    end
    DrawSharedParseCompareBreakdown(parent, leftCombat, rightCombat);
end

local function FullViewNoWrap(label)
    if label == nil then
        return;
    end

    pcall(function()
        if label.SetMultiline ~= nil then
            label:SetMultiline(false);
        end
    end);
end

local function TruncateFullViewText(text, maxChars)
    local value = tostring(text or "");
    maxChars = tonumber(maxChars) or 24;
    if string.len(value) <= maxChars then
        return value;
    end
    if maxChars <= 3 then
        return string.sub(value, 1, maxChars);
    end
    return string.sub(value, 1, maxChars - 3) .. "...";
end

function ParseGraph.BuildParseFullViewRows(combat)
    local skills, benefits = GetParseCombatLists(combat);
    local rows = {};

    for i = 1, #skills do
        table.insert(rows, {
            kind = "skill",
            bucket = skills[i],
            name = tostring(skills[i].name or "")
        });
    end

    return rows, skills, benefits;
end

function ParseGraph.GetParseFullViewMaxSkillDamage(skills)
    local maxSkillDamage = 0;
    for i = 1, #(skills or {}) do
        maxSkillDamage = math.max(maxSkillDamage, tonumber(skills[i].totalDamage) or 0);
    end
    return maxSkillDamage;
end

local function DrawParseFullViewIcon(parent, x, y, size, iconId)
    if iconId == nil then
        return;
    end

    local slot = DrawBlock(parent, x, y, size, size, Turbine.UI.Color(1.00, 0, 0, 0));
    slot:SetMouseVisible(false);
    pcall(function()
        slot:SetClipMode(true);
    end);

    local icon, loaded = ParseGraph.CreateManagedIcon(slot, 2, 2, math.max(10, size - 4), math.max(10, size - 4), iconId);
    if loaded ~= true then
        ParseGraph.DisposeManagedIconControl(slot);
    end
end

local function DrawParseFullViewStat(parent, x, y, w, labelText, valueText, valueColor, valueSize, valueHeight)
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local black = Turbine.UI.Color(1.00, 0, 0, 0);
    local white = valueColor or Turbine.UI.Color(1.00, 0.92, 0.90, 0.84);
    local labelFont = Turbine.UI.Lotro.Font.TrajanProBold24;
    local valueFont = Turbine.UI.Lotro.Font.TrajanProBold30;
    local valueH = valueHeight or 46;

    local label = Turbine.UI.Label();
    label:SetParent(parent);
    label:SetPosition(x, y);
    label:SetSize(w, 30);
    label:SetFont(labelFont);
    label:SetFontStyle(Turbine.UI.FontStyle.Outline);
    label:SetOutlineColor(black);
    label:SetForeColor(gold);
    label:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    label:SetText(labelText or "");
    label:SetMouseVisible(false);
    FullViewNoWrap(label);

    local value = Turbine.UI.Label();
    value:SetParent(parent);
    value:SetPosition(x, y + 30);
    value:SetSize(w, valueH);
    if valueSize == "huge" then
        valueFont = Turbine.UI.Lotro.Font.TrajanProBold36;
        valueH = valueHeight or 52;
        value:SetSize(w, valueH);
    end
    value:SetFont(valueFont);
    value:SetFontStyle(Turbine.UI.FontStyle.Outline);
    value:SetOutlineColor(black);
    value:SetForeColor(white);
    value:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    value:SetText(valueText or "");
    value:SetMouseVisible(false);
    FullViewNoWrap(value);
    return label, value;
end

local function DrawParseFullViewColumnHeader(parent, x, y, colW, tooltipParent)
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local headers = {
        { x = 22, w = colW - 262, text = "Skill", align = Turbine.UI.ContentAlignment.MiddleLeft },
        { x = colW - 236, w = 42, text = "Hits", align = Turbine.UI.ContentAlignment.MiddleRight },
        { x = colW - 190, w = 84, text = "Damage", align = Turbine.UI.ContentAlignment.MiddleRight },
        { x = colW - 102, w = 48, text = "Crit", align = Turbine.UI.ContentAlignment.MiddleRight },
        { x = colW - 50, w = 50, text = "Dev", align = Turbine.UI.ContentAlignment.MiddleRight }
    };

    for i = 1, #headers do
        local h = headers[i];
        local label = Label(parent, x + h.x, y, h.w, 18, h.text, "small");
        if h.text == "Skill" then
            label:SetFont(Turbine.UI.Lotro.Font.VerdanaBold16);
        else
            label:SetFont(Turbine.UI.Lotro.Font.Verdana14);
        end
        label:SetForeColor(gold);
        label:SetTextAlignment(h.align);
        label:SetMouseVisible(false);
        FullViewNoWrap(label);
        if tooltipParent ~= nil and (h.text == "Hits" or h.text == "Damage" or h.text == "Crit" or h.text == "Dev") then
            BindParseHitsTooltip(label, tooltipParent, x + h.x - 110, y + 24, h.text .. " colours");
        end
    end
end

local function DrawParseFullViewRow(parent, rowData, x, y, colW, rowH, maxSkillDamage, countAverages, rowIndex)
    local white = Turbine.UI.Color(1.00, 0.92, 0.90, 0.84);
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local barColor = Turbine.UI.Color(1.00, 0.345, 0.106, 0.106);
    local lineColor = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local normalFill = ParseGraph.ParseRowNormalFill or Turbine.UI.Color(1.00, 0, 0, 0);
    local alternateFill = Turbine.UI.Color(1.00, 0.11, 0.11, 0.11);
    local hoverFill = ParseGraph.ParseRowHoverFill or Turbine.UI.Color(1.00, 0.04, 0.18, 0.34);

    if rowData.kind == "benefitHeader" then
        local title = Label(parent, x, y + 2, colW, rowH - 2, tostring(rowData.name or "Benefits"), "achievementDetail");
        title:SetFont(Turbine.UI.Lotro.Font.VerdanaBold16);
        title:SetForeColor(gold);
        title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        title:SetMouseVisible(false);
        DrawBlock(parent, x, y + rowH - 2, colW, 1, lineColor);
        return;
    end

    local bucket = rowData.bucket or {};
    local name = tostring(rowData.name or bucket.name or "-");
    local rowFill = normalFill;
    if (tonumber(rowIndex) or 0) % 2 == 0 then
        rowFill = alternateFill;
    end
    local hover = DrawBlock(parent, x, y, colW, rowH, rowFill);
    hover:SetMouseVisible(true);
    hover.MouseEnter = function(sender)
        sender:SetBackColor(hoverFill);
    end
    hover.MouseLeave = function(sender)
        sender:SetBackColor(rowFill);
    end

    local iconSize = math.max(12, math.min(18, rowH - 3));
    local iconId = ParseGraph.GetSkillIconId(name);
    DrawParseFullViewIcon(parent, x, y + math.floor((rowH - iconSize) / 2), iconSize, iconId);

    if rowData.kind == "skill" then
        local barX = x + 22;
        local barW = math.max(1, colW - 258);
        local barWidth = 0;
        if (tonumber(maxSkillDamage) or 0) > 0 then
            barWidth = math.floor(barW * ((tonumber(bucket.totalDamage) or 0) / maxSkillDamage));
        end
        local bar = DrawBlock(parent, barX, y + 2, barWidth, math.max(1, rowH - 4), barColor);
        bar:SetMouseVisible(false);
    end

    local nameMax = 24;
    if colW >= 760 then
        nameMax = 58;
    elseif colW >= 650 then
        nameMax = 48;
    elseif colW >= 520 then
        nameMax = 38;
    elseif colW >= 390 then
        nameMax = 30;
    elseif colW >= 350 then
        nameMax = 26;
    elseif colW < 320 then
        nameMax = 18;
    end
    local nameLabel = Label(parent, x + 22, y, colW - 262, rowH, TruncateFullViewText(name, nameMax), "big");
    nameLabel:SetFont(Turbine.UI.Lotro.Font.VerdanaBold16);
    nameLabel:SetForeColor(white);
    nameLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    nameLabel:SetMouseVisible(false);
    FullViewNoWrap(nameLabel);

    local count = tonumber(bucket.hits or bucket.attacks or bucket.count) or 0;
    local countKey = rowData.kind == "benefit" and "benefits" or "skills";
    local hits = Label(parent, x + colW - 236, y, 42, rowH, FormatNumber(count), "big");
    hits:SetFont(Turbine.UI.Lotro.Font.Verdana14);
    local hitsColor, damageColor, critColor, devColor = GetParseDetailSkillMetricColors(bucket, countAverages, white);
    if rowData.kind == "benefit" then
        hitsColor = GetParseDetailCountColor(count, (countAverages[countKey] or {})[name], white);
    end
    hits:SetForeColor(hitsColor);
    hits:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
    hits:SetMouseVisible(false);

    if rowData.kind == "skill" then
        local damage = Label(parent, x + colW - 190, y, 84, rowH, FormatNumber(bucket.totalDamage), "big");
        damage:SetFont(Turbine.UI.Lotro.Font.Verdana14);
        damage:SetForeColor(damageColor);
        damage:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        damage:SetMouseVisible(false);
        damage:SetZOrder(5);

        local crit = Label(parent, x + colW - 102, y, 48, rowH, FormatCombatPercent(bucket.crits, bucket.hits or bucket.attacks), "big");
        crit:SetFont(Turbine.UI.Lotro.Font.Verdana14);
        crit:SetForeColor(critColor);
        crit:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        crit:SetMouseVisible(false);

        local dev = Label(parent, x + colW - 50, y, 50, rowH, FormatCombatPercent(bucket.devs, bucket.hits or bucket.attacks), "big");
        dev:SetFont(Turbine.UI.Lotro.Font.Verdana14);
        dev:SetForeColor(devColor);
        dev:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        dev:SetMouseVisible(false);
    end
end

function ParseGraph.DrawCompactParseDetailRow(row, rowData, colW, rowH, maxSkillDamage, countAverages, rowIndex, listH)
    local white = Turbine.UI.Color(1.00, 0.92, 0.90, 0.84);
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local barColor = Turbine.UI.Color(1.00, 0.345, 0.106, 0.106);
    local lineColor = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local normalFill = ParseGraph.ParseRowNormalFill or Turbine.UI.Color(1.00, 0, 0, 0);
    local alternateFill = Turbine.UI.Color(1.00, 0.11, 0.11, 0.11);
    local hoverFill = ParseGraph.ParseRowHoverFill or Turbine.UI.Color(1.00, 0.04, 0.18, 0.34);
    local black = Turbine.UI.Color(1.00, 0, 0, 0);

    if rowData.kind == "benefitHeader" then
        local title = Label(row, 0, 2, colW, rowH - 2, tostring(rowData.name or "Benefits"), "achievementDetail");
        title:SetFont(Turbine.UI.Lotro.Font.VerdanaBold16);
        title:SetForeColor(gold);
        title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        title:SetMouseVisible(false);
        DrawBlock(row, 0, rowH - 2, colW, 1, lineColor);
        return;
    end

    local bucket = rowData.bucket or {};
    local name = tostring(rowData.name or bucket.name or "-");
    local rowFill = normalFill;
    if (tonumber(rowIndex) or 0) % 2 == 0 then
        rowFill = alternateFill;
    end

    local hover = DrawBlock(row, 0, 0, colW, rowH, rowFill);
    hover:SetMouseVisible(true);
    hover.MouseEnter = function(sender)
        sender:SetBackColor(hoverFill);
    end
    hover.MouseLeave = function(sender)
        sender:SetBackColor(rowFill);
    end

    local iconSize = math.max(12, math.min(18, rowH - 3));
    local iconId = ParseGraph.GetSkillIconId(name);
    local iconUpdate = nil;
    if iconId ~= nil then
        local iconSlot = DrawBlock(row, 0, math.floor((rowH - iconSize) / 2), iconSize, iconSize, black);
        iconSlot:SetMouseVisible(false);
        pcall(function()
            iconSlot:SetClipMode(true);
        end);

        local icon = nil;
        local iconLoaded = false;
        icon, iconLoaded = ParseGraph.CreateManagedIcon(iconSlot, 2, 2, math.max(10, iconSize - 4), math.max(10, iconSize - 4), iconId);
        if iconLoaded ~= true then
            ParseGraph.DisposeManagedIconControl(iconSlot);
            iconSlot = nil;
        end

        local function UpdateIconVisibility()
            if iconSlot == nil or icon == nil then
                return;
            end
            ParseGraph.UpdateManagedIconClip({
                iconSlot = iconSlot,
                icon = icon,
                row = row,
                viewportH = listH,
                slotX = 0,
                slotY = math.floor((rowH - iconSize) / 2),
                slotW = iconSize,
                slotH = iconSize,
                iconX = 2,
                iconY = 2
            });
        end

        if iconLoaded == true then
            ParseGraph.ParseCompareIconControls = ParseGraph.ParseCompareIconControls or {};
            table.insert(ParseGraph.ParseCompareIconControls, {
                iconSlot = iconSlot,
                icon = icon,
                update = UpdateIconVisibility
            });
            iconUpdate = UpdateIconVisibility;
            local oldPositionChanged = row.PositionChanged;
            row.PositionChanged = function(sender, args)
                if oldPositionChanged ~= nil then
                    oldPositionChanged(sender, args);
                end
                UpdateIconVisibility();
            end
            UpdateIconVisibility();
        end
    end

    if rowData.kind == "skill" then
        local barX = 22;
        local barW = math.max(1, colW - barX);
        local barWidth = 0;
        if (tonumber(maxSkillDamage) or 0) > 0 then
            barWidth = math.floor(barW * ((tonumber(bucket.totalDamage) or 0) / maxSkillDamage));
        end
        local bar = DrawBlock(row, barX, 2, barWidth, math.max(1, rowH - 4), barColor);
        bar:SetMouseVisible(false);
    end

    local nameMax = 24;
    if colW >= 760 then
        nameMax = 58;
    elseif colW >= 650 then
        nameMax = 48;
    elseif colW >= 520 then
        nameMax = 38;
    elseif colW >= 390 then
        nameMax = 30;
    elseif colW >= 350 then
        nameMax = 26;
    elseif colW < 320 then
        nameMax = 18;
    end

    local nameLabel = Label(row, 22, 0, colW - 262, rowH, TruncateFullViewText(name, nameMax), "big");
    nameLabel:SetFont(Turbine.UI.Lotro.Font.VerdanaBold16);
    nameLabel:SetForeColor(white);
    nameLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    nameLabel:SetMouseVisible(false);
    FullViewNoWrap(nameLabel);

    local count = tonumber(bucket.hits or bucket.attacks or bucket.count) or 0;
    local countKey = rowData.kind == "benefit" and "benefits" or "skills";
    local hitsColor, damageColor, critColor, devColor = GetParseDetailSkillMetricColors(bucket, countAverages, white);
    if rowData.kind == "benefit" then
        hitsColor = GetParseDetailCountColor(count, (countAverages[countKey] or {})[name], white);
    end

    local hits = Label(row, colW - 236, 0, 42, rowH, FormatNumber(count), "big");
    hits:SetFont(Turbine.UI.Lotro.Font.Verdana14);
    hits:SetForeColor(hitsColor);
    hits:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
    hits:SetMouseVisible(false);

    if rowData.kind == "skill" then
        local damage = Label(row, colW - 190, 0, 84, rowH, FormatNumber(bucket.totalDamage), "big");
        damage:SetFont(Turbine.UI.Lotro.Font.Verdana14);
        damage:SetForeColor(damageColor);
        damage:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        damage:SetMouseVisible(false);
        damage:SetZOrder(5);

        local crit = Label(row, colW - 102, 0, 48, rowH, FormatCombatPercent(bucket.crits, bucket.hits or bucket.attacks), "big");
        crit:SetFont(Turbine.UI.Lotro.Font.Verdana14);
        crit:SetForeColor(critColor);
        crit:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        crit:SetMouseVisible(false);

        local dev = Label(row, colW - 50, 0, 50, rowH, FormatCombatPercent(bucket.devs, bucket.hits or bucket.attacks), "big");
        dev:SetFont(Turbine.UI.Lotro.Font.Verdana14);
        dev:SetForeColor(devColor);
        dev:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        dev:SetMouseVisible(false);
    end

    return iconUpdate;
end

function ParseGraph.DrawParseFullViewBox(parent, x, y, w, h, titleText, borderColor, fillColor)
    local fill = fillColor or Turbine.UI.Color(1.00, 0, 0, 0);
    local border = borderColor or Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local box = DrawBlock(parent, x, y, w, h, fill);
    box:SetMouseVisible(false);
    DrawBlock(parent, x, y, w, 1, border);
    DrawBlock(parent, x, y + h - 1, w, 1, border);
    DrawBlock(parent, x, y, 1, h, border);
    DrawBlock(parent, x + w - 1, y, 1, h, border);

    if titleText ~= nil and tostring(titleText) ~= "" then
        local title = Label(parent, x, y + 4, w, 24, tostring(titleText), "achievementDetail");
        local titleFont = Turbine.UI.Lotro.Font.TrajanProBold16;
        if titleText == "Breakdown" or titleText == "Key Stats" or titleText == "Benefits" then
            titleFont = Turbine.UI.Lotro.Font.VerdanaBold16;
        end
        title:SetFont(titleFont);
        title:SetForeColor(Turbine.UI.Color(1.00, 1.00, 0.82, 0.16));
        title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        title:SetMouseVisible(false);
    end

    return box;
end

