function ParseGraph.DrawParseFullViewBenefits(parent, x, y, w, h, benefits, countAverages, border, white)
    ParseGraph.DrawParseFullViewBox(parent, x, y, w, h, "Benefits", border);
    local averages = type(countAverages) == "table" and countAverages or {};
    local benefitAverages = type(averages.benefits) == "table" and averages.benefits or {};
    local rowY = y + 34;
    local rowH = 22;
    local shown = false;
    for i = 1, #(benefits or {}) do
        if rowY + rowH > y + h - 8 then
            break;
        end
        local benefit = benefits[i] or {};
        local name = tostring(benefit.name or "-");
        local count = tonumber(benefit.count) or 0;
        local countColor = GetParseDetailCountColor(count, benefitAverages[name], white);
        DrawParseFullViewIcon(parent, x + 18, rowY + 2, 18, ParseGraph.GetSkillIconId(name));

        local nameLabel = Label(parent, x + 44, rowY, w - 110, rowH, TruncateFullViewText(name, 28), "achievementDetail");
        nameLabel:SetFont(Turbine.UI.Lotro.Font.VerdanaBold16);
        nameLabel:SetForeColor(white);
        nameLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
        nameLabel:SetMouseVisible(false);
        FullViewNoWrap(nameLabel);

        local countLabel = Label(parent, x + w - 58, rowY, 36, rowH, FormatNumber(count), "achievementDetail");
        countLabel:SetFont(Turbine.UI.Lotro.Font.VerdanaBold16);
        countLabel:SetForeColor(countColor);
        countLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        countLabel:SetMouseVisible(false);
        shown = true;
        rowY = rowY + rowH;
    end

    if shown ~= true then
        local none = Label(parent, x, y + 42, w, 24, "-", "achievementDetail");
        none:SetFont(Turbine.UI.Lotro.Font.VerdanaBold16);
        none:SetForeColor(white);
        none:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        none:SetMouseVisible(false);
    end
end

function ParseGraph.CloseParseFullView(targetWindow)
    local windows = ParseGraph.ParseFullViewWindows;
    if type(windows) ~= "table" then
        windows = {};
        if ParseGraph.ParseFullViewWindow ~= nil then
            table.insert(windows, ParseGraph.ParseFullViewWindow);
        end
    end

    if targetWindow ~= nil then
        local wasVisible = false;
        pcall(function()
            wasVisible = targetWindow:IsVisible();
        end);
        pcall(function()
            targetWindow:SetVisible(false);
        end);
        for i = #windows, 1, -1 do
            if windows[i] == targetWindow then
                table.remove(windows, i);
            end
        end
        ParseGraph.ParseFullViewWindows = windows;
        if ParseGraph.ParseFullViewWindow == targetWindow then
            ParseGraph.ParseFullViewWindow = windows[#windows];
        end
        return wasVisible == true;
    end

    local closed = false;
    for i = #windows, 1, -1 do
        local window = windows[i];
        if window ~= nil then
            local wasVisible = false;
            pcall(function()
                wasVisible = window:IsVisible();
            end);
            pcall(function()
                window:SetVisible(false);
            end);
            if wasVisible == true then
                closed = true;
            end
            table.remove(windows, i);
        end
    end
    ParseGraph.ParseFullViewWindows = {};
    ParseGraph.ParseFullViewWindow = nil;
    return closed;
end

function ParseGraph.ShowParseFullView(point)
    local selection = point or {};
    local parse = ParseGraph.GetParseBySource(selection.sourceKey, selection.sourceIndex) or selection.parse;
    if type(parse) ~= "table" then
        return;
    end

    local combat = parse.combat;
    local rows, skills, benefits = ParseGraph.BuildParseFullViewRows(combat);
    local rowCount = math.max(1, #rows);

    local displayW = 1200;
    local displayH = 900;
    pcall(function()
        displayW = tonumber(Turbine.UI.Display.GetWidth()) or displayW;
        displayH = tonumber(Turbine.UI.Display.GetHeight()) or displayH;
    end);

    local windowW = math.min(1040, math.max(940, displayW - 24));
    local windowH = math.min(displayH - 8, math.max(780, 240 + (rowCount * 22)));
    local panelW = windowW - 24;
    local panelH = windowH - 54;
    local leftX = 24;
    local sideW = math.min(390, math.max(340, math.floor(panelW * 0.29)));
    local gap = 18;
    local leftW = panelW - (leftX * 2) - sideW - gap;
    local sideX = leftX + leftW + gap;
    local breakdownY = 80;
    local breakdownH = panelH - 104;
    local tableX = leftX + 12;
    local tableW = leftW - 24;
    local headerY = breakdownY + 38;
    local rowStartY = headerY + 25;
    local availableRowsH = math.max(220, breakdownY + breakdownH - rowStartY - 12);
    local rowH = math.floor(availableRowsH / rowCount);
    rowH = math.max(15, math.min(24, rowH));
    local hasCombat = type(combat) == "table" and (tonumber(combat.attacks) or 0) > 0;

    ParseGraph.ParseFullViewWindows = ParseGraph.ParseFullViewWindows or {};
    local window = Turbine.UI.Lotro.Window();
    table.insert(ParseGraph.ParseFullViewWindows, window);
    ParseGraph.ParseFullViewWindow = window;
    window:SetZOrder(240 + #ParseGraph.ParseFullViewWindows);
    window:SetSize(windowW, windowH);
    window:SetText("Parse Full View");
    window:SetWantsKeyEvents(true);
    window.KeyDown = function(sender, args)
        if args ~= nil and args.Action == Turbine.UI.Lotro.Action.Escape then
            ParseGraph.CloseParseFullView(sender);
            args.Handled = true;
            return true;
        end
    end
    CenterParseStringWindow(window);

    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local white = Turbine.UI.Color(1.00, 0.92, 0.90, 0.84);
    local muted = Turbine.UI.Color(0.90, 0.70, 0.70, 0.70);
    local parseBlue = Turbine.UI.Color(1.00, 0.45, 0.78, 1.00);
    local sourceGreen = Turbine.UI.Color(1.00, 0.42, 1.00, 0.38);
    local black = Turbine.UI.Color(1.00, 0, 0, 0);

    local panel = Panel(window, 12, 34, panelW, panelH, 1.00);
    panel:SetBackColor(black);
    DrawAchievementBorder(panel, panelW, panelH, border);

    local logo = Turbine.UI.Control();
    logo:SetParent(panel);
    local logoX = leftX + 4;
    logo:SetPosition(logoX, 14);
    logo:SetSize(30, 30);
    logo:SetMouseVisible(false);
    logo:SetZOrder(4);
    pcall(function()
        logo:SetBackground((ParseGraph.GeneralIconPath or "") .. "parsegraph_launcher_medium.tga");
    end);
    pcall(function()
        logo:SetStretchMode(2);
        logo:SetStretchMode(1);
    end);

    local brandParse = Label(panel, logoX - 25, 46, 40, 16, "Parse", "small");
    brandParse:SetForeColor(gold);
    brandParse:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
    brandParse:SetMouseVisible(false);
    local brandGraph = Label(panel, logoX + 15, 46, 48, 16, "Graph", "small");
    brandGraph:SetForeColor(white);
    brandGraph:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    brandGraph:SetMouseVisible(false);

    local titleNumber = tostring(selection.index or selection.sourceIndex or "?");
    local title = Label(panel, leftX, 8, leftW, 30, "Parse #" .. titleNumber, "huge");
    title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    title:SetForeColor(gold);
    local nameLabel = Label(panel, leftX, 38, leftW, 28, tostring(selection.sourceName or ""), "achievementTitle");
    nameLabel:SetFont(Turbine.UI.Lotro.Font.TrajanProBold22);
    nameLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    nameLabel:SetForeColor(sourceGreen);
    FullViewNoWrap(nameLabel);
    DrawBlock(panel, leftX, 70, leftW - 12, 1, border);
    DrawBlock(panel, sideX - 10, 12, 1, panelH - 24, border);

    if hasCombat ~= true then
        ParseGraph.DrawParseFullViewBox(panel, leftX, breakdownY, leftW, breakdownH, "Breakdown", border);
        local empty = Label(panel, leftX, breakdownY + 120, leftW, 60, "No detailed combat breakdown was saved for this parse.", "big");
        empty:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        empty:SetForeColor(white);
    else
        ParseGraph.DrawParseFullViewBox(panel, leftX, breakdownY, leftW, breakdownH, "Breakdown", border);
        local maxSkillDamage = ParseGraph.GetParseFullViewMaxSkillDamage(skills);
        local countAverages = BuildParseDetailCountAverages(GetParseDetailComparisonParses(selection));
        DrawParseFullViewColumnHeader(panel, tableX, headerY, tableW);
        DrawBlock(panel, tableX, headerY + 20, tableW, 1, border);
        for i = 1, #rows do
            local rowY = rowStartY + ((i - 1) * rowH);
            DrawParseFullViewRow(panel, rows[i], tableX, rowY, tableW, rowH, maxSkillDamage, countAverages, i);
        end
    end

    local finalBoxY = 16;
    ParseGraph.DrawParseFullViewBox(panel, sideX, finalBoxY, sideW, 92, nil, border);
    local finalTitle = Label(panel, sideX, finalBoxY + 8, sideW, 22, "Final Parse", "achievementDetail");
    finalTitle:SetFont(Turbine.UI.Lotro.Font.TrajanProBold16);
    finalTitle:SetForeColor(gold);
    finalTitle:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    finalTitle:SetMouseVisible(false);
    local finalValue = Label(panel, sideX, finalBoxY + 32, sideW, 48, FormatNumber(parse.final), "huge");
    finalValue:SetFont(Turbine.UI.Lotro.Font.TrajanProBold36);
    finalValue:SetFontStyle(Turbine.UI.FontStyle.Outline);
    finalValue:SetOutlineColor(black);
    finalValue:SetForeColor(parseBlue);
    finalValue:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    finalValue:SetMouseVisible(false);

    local minutesY = 120;
    ParseGraph.DrawParseFullViewBox(panel, sideX, minutesY, sideW, 112, "Minute Breakdown", border);
    local minuteGap = 8;
    local minuteW = math.floor((sideW - 32 - (minuteGap * 2)) / 3);
    local minuteX = sideX + 16;
    ParseGraph.DrawParseFullViewMinuteCard(panel, minuteX, minutesY + 42, minuteW, 58, "1st minute", ParseGraph.FormatSummaryNumber(parse.minutes and parse.minutes[1]), white);
    ParseGraph.DrawParseFullViewMinuteCard(panel, minuteX + minuteW + minuteGap, minutesY + 42, minuteW, 58, "2nd minute", ParseGraph.FormatSummaryNumber(parse.minutes and parse.minutes[2]), white);
    ParseGraph.DrawParseFullViewMinuteCard(panel, minuteX + ((minuteW + minuteGap) * 2), minutesY + 42, minuteW, 58, "3rd minute", ParseGraph.FormatSummaryNumber(parse.minutes and parse.minutes[3]), white);

    local keyY = 246;
    ParseGraph.DrawParseFullViewBox(panel, sideX, keyY, sideW, 180, "Key Stats", border);
    local statLabelW = 132;
    local statValueW = 150;
    local statRowX = sideX + math.floor((sideW - statLabelW - 12 - statValueW) / 2);
    ParseGraph.DrawParseFullViewSidebarRow(panel, statRowX, keyY + 40, statLabelW, statValueW, "Total Damage", hasCombat and FormatNumber(combat.totalDamage) or "-", white);
    ParseGraph.DrawParseFullViewSidebarRow(panel, statRowX, keyY + 62, statLabelW, statValueW, "Hits", hasCombat and FormatNumber(combat.hits or combat.attacks) or "-", white);
    ParseGraph.DrawParseFullViewSidebarRow(panel, statRowX, keyY + 84, statLabelW, statValueW, "APS", hasCombat and FormatCombatRate(combat.hits or combat.attacks, combat.duration) or "-", white);
    ParseGraph.DrawParseFullViewSidebarRow(panel, statRowX, keyY + 106, statLabelW, statValueW, "Crit Chance", hasCombat and FormatCombatPercent(combat.crits, combat.hits or combat.attacks) or "-", white);
    ParseGraph.DrawParseFullViewSidebarRow(panel, statRowX, keyY + 128, statLabelW, statValueW, "Dev Chance", hasCombat and FormatCombatPercent(combat.devs, combat.hits or combat.attacks) or "-", white);
    ParseGraph.DrawParseFullViewSidebarRow(panel, statRowX, keyY + 150, statLabelW, statValueW, "Max Hit", hasCombat and FormatNumber(combat.max) or "-", white);

    local closeY = panelH - 32;
    local metaH = 58;
    local metaY = closeY - metaH - 8;
    local benefitsY = 440;
    local benefitsH = math.max(96, metaY - benefitsY - 12);
    local comparisonParses = GetParseDetailComparisonParses(selection);
    local countAverages = BuildParseDetailCountAverages(comparisonParses);
    ParseGraph.DrawParseFullViewBenefits(panel, sideX, benefitsY, sideW, benefitsH, benefits, countAverages, border, white);

    ParseGraph.DrawParseFullViewBox(panel, sideX, metaY, sideW, metaH, "Meta", border);
    ParseGraph.DrawParseFullViewSidebarRow(panel, statRowX, metaY + 34, statLabelW, statValueW, "Logged At", tostring(parse.time or "-"), muted, Turbine.UI.Lotro.Font.VerdanaBold16, Turbine.UI.Lotro.Font.Verdana14);

    local close = ParseGraph.CreateActionButton(panel, sideX + sideW - 165, closeY, 145, 22, "Close", function()
        ParseGraph.CloseParseFullView(window);
    end);
    close:SetZOrder(100);

    window:SetVisible(true);
    window:Activate();
end

function ParseGraph.UpdateParseHistoryCompareButton()
    local tab = tostring(ParseGraph.ParseHistoryTab or "history");

    if ParseGraph.ParseHistoryImportButton ~= nil then
        local showImport = tab == "imported";
        ParseGraph.ParseHistoryImportButton:SetVisible(showImport);
        ParseGraph.ParseHistoryImportButton:SetMouseVisible(showImport);
    end

    local button = ParseGraph.ParseHistoryCompareButton;
    if button == nil then
        return;
    end

    button:SetVisible(false);
    button:SetMouseVisible(false);
    button.hover = false;
    button.pressed = false;
    button.actionSelected = false;
    ParseGraph.ApplyActionButtonState(button);
end
function ParseGraph.DrawCompactParseDetailView(selection, parse, comparePoint)
    local parent = ParseGraph.ParseDetailContent;
    if parent == nil or parse == nil then
        return;
    end

    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local white = Turbine.UI.Color(1.00, 0.92, 0.90, 0.84);
    local muted = Turbine.UI.Color(0.90, 0.70, 0.70, 0.70);
    local parseBlue = Turbine.UI.Color(1.00, 0.45, 0.78, 1.00);
    local sourceGreen = Turbine.UI.Color(1.00, 0.42, 1.00, 0.38);
    local black = Turbine.UI.Color(1.00, 0, 0, 0);

    local combat = parse.combat;
    local hasCombat = type(combat) == "table" and (tonumber(combat.attacks) or 0) > 0;
    local rows, skills, benefits = {}, {}, {};
    if hasCombat then
        rows, skills, benefits = ParseGraph.BuildParseFullViewRows(combat);
    end

    local contentW = parent:GetWidth();
    local leftX = 12;
    local sideW = 250;
    local sideX = contentW - sideW - 8;
    local gap = 10;

    local title = Label(parent, sideX, 6, 118, 26, "Parse #" .. tostring(selection.index or selection.sourceIndex or "?"), "huge");
    title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    title:SetForeColor(gold);

    local name = Label(parent, sideX + 128, 6, sideW - 154, 26, tostring(selection.sourceName or ""), "big");
    name:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
    name:SetForeColor(sourceGreen);
    name:SetFont(Turbine.UI.Lotro.Font.TrajanProBold18);

    local compareParent = ParseGraph.ParseDetailView or parent;
    local compareX = sideX + sideW + 1;
    local compareY = -15;
    local tooltipX = sideX - 41;
    local tooltipY = 13;
    if compareParent ~= parent then
        compareX = compareX + 20;
        compareY = compareY + 20;
        tooltipX = tooltipX + 20;
        tooltipY = tooltipY + 20;
    end
    local compareCheckbox = DrawParseCompareCheckbox(compareParent, compareX, compareY, comparePoint, false, true, true);
    if compareCheckbox ~= nil then
        compareCheckbox:SetZOrder(200);
        ParseGraph.ParseDetailOverlayCompareCheckbox = compareCheckbox;
    end
    BindParseDetailTooltip(compareCheckbox, compareParent, "Compare", "Tick this checkbox to compare this parse", tooltipX, tooltipY);

    local comparisonParses = GetParseDetailComparisonParses(selection);
    local countAverages = BuildParseDetailCountAverages(comparisonParses);
    local minuteAverages = (ParseGraph.GetParseComparisonStats(nil, parse).averageMinutes or {});
    local breakdownY = 6;
    local breakdownH = 694;
    local breakdownDividerX = sideX - math.floor(gap / 2);

    if hasCombat ~= true then
        local empty = Label(parent, leftX, breakdownY + 210, breakdownDividerX - leftX - 12, 60, "No detailed combat breakdown was saved for this parse.", "big");
        empty:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        empty:SetForeColor(white);
    else
        local tableX = leftX + 4;
        local tableY = breakdownY + 8;
        local listW = breakdownDividerX - tableX - 18;
        local listY = tableY + 24;
        local listH = breakdownH - 32;
        local rowH = 22;
        local maxSkillDamage = ParseGraph.GetParseFullViewMaxSkillDamage(skills);

        DrawParseFullViewColumnHeader(parent, tableX, tableY, listW, parent);
        DrawBlock(parent, tableX, tableY + 22, listW, 1, border);

        local list = Turbine.UI.ListBox();
        list:SetParent(parent);
        list:SetPosition(tableX, listY);
        list:SetSize(listW, listH);
        list:SetOrientation(Turbine.UI.Orientation.Vertical);
        list:SetBackColor(black);
        list:SetZOrder(1);
        pcall(function()
            list:SetClipMode(true);
        end);

        local scroll = Turbine.UI.Lotro.ScrollBar();
        scroll:SetParent(parent);
        scroll:SetOrientation(Turbine.UI.Orientation.Vertical);
        scroll:SetPosition(tableX + listW + 2, listY);
        scroll:SetSize(10, listH);
        scroll:SetBackColor(black);
        list:SetVerticalScrollBar(scroll);
        scroll:SetVisible(#rows * rowH > listH);

        for i = 1, #rows do
            local row = Turbine.UI.Control();
            row:SetSize(listW, rowH);
            row:SetBackColor(black);
            row:SetMouseVisible(true);
            pcall(function()
                row:SetClipMode(true);
            end);
            local updateIcon = ParseGraph.DrawCompactParseDetailRow(row, rows[i], listW, rowH, maxSkillDamage, countAverages, i, listH);
            list:AddItem(row);
            if updateIcon ~= nil then
                pcall(updateIcon);
            end
        end

    end

    ParseGraph.DrawParseFullViewBox(parent, sideX, 36, sideW, 84, nil, border);
    local finalLabel = Label(parent, sideX + 4, 44, sideW - 8, 24, "Final Parse", "achievementDetail");
    finalLabel:SetFont(Turbine.UI.Lotro.Font.TrajanProBold16);
    finalLabel:SetForeColor(gold);
    finalLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    finalLabel:SetMouseVisible(false);
    local finalValue = Label(parent, sideX + 8, 68, sideW - 16, 44, FormatNumber(parse.final), "achievementTitle");
    finalValue:SetFont(Turbine.UI.Lotro.Font.TrajanProBold30);
    finalValue:SetForeColor(parseBlue);
    finalValue:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    finalValue:SetMouseVisible(false);

    local minutesY = 130;
    ParseGraph.DrawParseFullViewBox(parent, sideX, minutesY, sideW, 104, "Minute Breakdown", border);
    local minuteGap = 6;
    local minuteW = math.floor((sideW - 24 - (minuteGap * 2)) / 3);
    local minuteX = sideX + 12;
    ParseGraph.DrawParseFullViewMinuteCard(parent, minuteX, minutesY + 38, minuteW, 54, "1st", ParseGraph.FormatSummaryNumber(parse.minutes and parse.minutes[1]), ParseGraph.GetMinuteSummaryUiColorForParse(parse, parse.minutes and parse.minutes[1], minuteAverages[1], white), Turbine.UI.Lotro.Font.TrajanProBold16);
    ParseGraph.DrawParseFullViewMinuteCard(parent, minuteX + minuteW + minuteGap, minutesY + 38, minuteW, 54, "2nd", ParseGraph.FormatSummaryNumber(parse.minutes and parse.minutes[2]), ParseGraph.GetMinuteSummaryUiColorForParse(parse, parse.minutes and parse.minutes[2], minuteAverages[2], white), Turbine.UI.Lotro.Font.TrajanProBold16);
    ParseGraph.DrawParseFullViewMinuteCard(parent, minuteX + ((minuteW + minuteGap) * 2), minutesY + 38, minuteW, 54, "3rd", ParseGraph.FormatSummaryNumber(parse.minutes and parse.minutes[3]), ParseGraph.GetMinuteSummaryUiColorForParse(parse, parse.minutes and parse.minutes[3], minuteAverages[3], white), Turbine.UI.Lotro.Font.TrajanProBold16);

    local keyY = 244;
    ParseGraph.DrawParseFullViewBox(parent, sideX, keyY, sideW, 170, "Key Stats", border);
    local rowX = sideX + 14;
    local labelW = 118;
    local valueW = sideW - labelW - 42;
    ParseGraph.DrawParseFullViewSidebarRow(parent, rowX, keyY + 36, labelW, valueW, "Total Damage", hasCombat and FormatNumber(combat.totalDamage) or "-", white);
    ParseGraph.DrawParseFullViewSidebarRow(parent, rowX, keyY + 58, labelW, valueW, "Hits", hasCombat and FormatNumber(combat.hits or combat.attacks) or "-", white);
    ParseGraph.DrawParseFullViewSidebarRow(parent, rowX, keyY + 80, labelW, valueW, "APS", hasCombat and FormatCombatRate(combat.hits or combat.attacks, combat.duration) or "-", white);
    ParseGraph.DrawParseFullViewSidebarRow(parent, rowX, keyY + 102, labelW, valueW, "Crit Chance", hasCombat and FormatCombatPercent(combat.crits, combat.hits or combat.attacks) or "-", white);
    ParseGraph.DrawParseFullViewSidebarRow(parent, rowX, keyY + 124, labelW, valueW, "Dev Chance", hasCombat and FormatCombatPercent(combat.devs, combat.hits or combat.attacks) or "-", white);

    local maxHitSkill = hasCombat and tostring(combat.maxSkill or "") or "";
    if hasCombat and maxHitSkill == "" and type(combat.skills) == "table" then
        local maxHitValue = tonumber(combat.max) or 0;
        for _, bucket in pairs(combat.skills) do
            if type(bucket) == "table" and math.abs((tonumber(bucket.max) or 0) - maxHitValue) < 0.001 then
                maxHitSkill = tostring(bucket.name or "");
                break;
            end
        end
    end
    if maxHitSkill == "" then
        maxHitSkill = "Unknown skill";
    end
    local maxHitLabel, maxHitValue = ParseGraph.DrawParseFullViewSidebarRow(parent, rowX, keyY + 146, labelW, valueW, "Max Hit", hasCombat and FormatNumber(combat.max) or "-", white);
    BindParseDetailTooltip(maxHitLabel, parent, "Max hit skill", maxHitSkill, sideX - 40, keyY + 116);
    BindParseDetailTooltip(maxHitValue, parent, "Max hit skill", maxHitSkill, sideX - 40, keyY + 116);

    local benefitsY = 424;
    ParseGraph.DrawParseFullViewBenefits(parent, sideX, benefitsY, sideW, 122, benefits, countAverages, border, white);

    local metaY = 556;
    ParseGraph.DrawParseFullViewBox(parent, sideX, metaY, sideW, 52, "Meta", border);
    ParseGraph.DrawParseFullViewSidebarRow(parent, sideX + 4, metaY + 32, 98, sideW - 114, "Logged At", tostring(parse.time or "-"), muted, Turbine.UI.Lotro.Font.VerdanaBold16, Turbine.UI.Lotro.Font.Verdana14);
end

function ParseGraph.DrawParseDetailView()
    if ParseGraph.ParseDetailContent == nil then
        return;
    end

    ParseGraph.ParseDetailContent:SetPosition(20, 20);
    ParseGraph.ParseDetailContent:SetSize(840, 700);
    ParseGraph.ClearParseCompareIcons();
    ClearChildren(ParseGraph.ParseDetailContent);
    ParseGraph.ParseDetailTooltip = nil;
    ParseGraph.ParseDetailTooltipParent = nil;
    ParseGraph.ParseDetailHitsTooltip = nil;
    ParseGraph.ParseDetailHitsTooltipParent = nil;
    if ParseGraph.ParseDetailOverlayCompareCheckbox ~= nil then
        ParseGraph.ParseDetailOverlayCompareCheckbox:SetParent(nil);
        ParseGraph.ParseDetailOverlayCompareCheckbox = nil;
    end
    if ParseGraph.ParseDetailClearCompareButton ~= nil then
        ParseGraph.ParseDetailClearCompareButton:SetVisible(false);
    end
    if ParseGraph.ParseDetailShareButton ~= nil then
        ParseGraph.ParseDetailShareButton:SetVisible(false);
    end
    if ParseGraph.ParseDetailFullViewButton ~= nil then
        ParseGraph.ParseDetailFullViewButton:SetVisible(false);
    end
    if ParseGraph.ParseDetailBrandPanel ~= nil then
        ParseGraph.ParseDetailBrandPanel:SetVisible(false);
    end
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local white = Turbine.UI.Color(1.00, 0.92, 0.90, 0.84);
    local muted = Turbine.UI.Color(0.90, 0.70, 0.70, 0.70);
    local parseBlue = Turbine.UI.Color(1.00, 0.45, 0.78, 1.00);

    local compareSelections = ParseGraph.GetActiveCompareSelections();
    if ParseGraph.ParseCompareViewActive == true or #compareSelections >= 2 then
        ParseGraph.ParseCompareViewActive = true;
        DrawParseCompareView(compareSelections);
        return;
    end

    local selection = ParseGraph.SelectedParseDetail or {};
    local parse = ParseGraph.GetParseBySource(selection.sourceKey, selection.sourceIndex) or selection.parse;
    if parse == nil then
        local missing = Label(ParseGraph.ParseDetailContent, 0, 210, ParseGraph.ParseDetailContent:GetWidth(), 40, "That parse could not be found.", "big");
        missing:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        return;
    end

    local comparePoint = {
        parse = parse,
        index = selection.index,
        sourceKey = selection.sourceKey,
        sourceIndex = selection.sourceIndex,
        sourceName = selection.sourceName,
        returnView = selection.returnView
    };
    if ParseGraph.ParseDetailShareButton ~= nil then
        ParseGraph.ParseDetailShareButton.parsePoint = comparePoint;
        ParseGraph.ParseDetailShareButton:SetVisible(true);
    end
    if ParseGraph.ParseDetailFullViewButton ~= nil then
        ParseGraph.ParseDetailFullViewButton.parsePoint = comparePoint;
        ParseGraph.ParseDetailFullViewButton:SetVisible(false);
    end
    if ParseGraph.ParseDetailBrandPanel ~= nil then
        ParseGraph.ParseDetailBrandPanel:SetVisible(true);
    end
    do
        ParseGraph.DrawCompactParseDetailView(selection, parse, comparePoint);
        return;
    end
    DrawParseCompareCheckbox(ParseGraph.ParseDetailContent, 724, 8, comparePoint, false, true);

    local title = Label(ParseGraph.ParseDetailContent, 0, 6, 840, 30, "Parse #" .. tostring(selection.index or selection.sourceIndex or "?"), "huge");
    title:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    title:SetForeColor(gold);
    local subtitle = Label(ParseGraph.ParseDetailContent, 0, 38, 840, 22, tostring(selection.sourceName or "") .. "     " .. tostring(parse.time or ""), "big");
    subtitle:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    subtitle:SetForeColor(muted);
    DrawBlock(ParseGraph.ParseDetailContent, 35, 68, 770, 1, border);

    DrawParseDetailStat(ParseGraph.ParseDetailContent, 48, 88, 150, "1st minute", ParseGraph.FormatSummaryNumber(parse.minutes and parse.minutes[1]), white);
    DrawParseDetailStat(ParseGraph.ParseDetailContent, 214, 88, 150, "2nd minute", ParseGraph.FormatSummaryNumber(parse.minutes and parse.minutes[2]), white);
    DrawParseDetailStat(ParseGraph.ParseDetailContent, 380, 88, 150, "3rd minute", ParseGraph.FormatSummaryNumber(parse.minutes and parse.minutes[3]), white);
    DrawParseDetailStat(ParseGraph.ParseDetailContent, 568, 84, 190, "Final parse", FormatNumber(parse.final), parseBlue, "achievementTitle", 34);

    local combat = parse.combat;
    if type(combat) ~= "table" or (tonumber(combat.attacks) or 0) <= 0 then
        local empty = Label(ParseGraph.ParseDetailContent, 0, 245, 840, 60, "No detailed combat breakdown was saved for this parse.", "big");
        empty:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        empty:SetForeColor(white);
        return;
    end

    DrawBlock(ParseGraph.ParseDetailContent, 35, 158, 770, 1, border);
    DrawParseDetailStat(ParseGraph.ParseDetailContent, 48, 178, 125, "Total damage", FormatNumber(combat.totalDamage), white);
    DrawParseDetailStat(ParseGraph.ParseDetailContent, 180, 178, 95, "Hits", FormatNumber(combat.hits or combat.attacks), white);
    DrawParseDetailStat(ParseGraph.ParseDetailContent, 294, 178, 90, "APS", FormatCombatRate(combat.hits or combat.attacks, combat.duration), white);
    DrawParseDetailStat(ParseGraph.ParseDetailContent, 408, 178, 120, "Crit chance", FormatCombatPercent(combat.crits, combat.hits or combat.attacks), white);
    DrawParseDetailStat(ParseGraph.ParseDetailContent, 552, 178, 120, "Dev chance", FormatCombatPercent(combat.devs, combat.hits or combat.attacks), white);
    local maxHitSkill = tostring(combat.maxSkill or "");
    if maxHitSkill == "" and type(combat.skills) == "table" then
        local maxHitValue = tonumber(combat.max) or 0;
        for _, bucket in pairs(combat.skills) do
            if type(bucket) == "table" and math.abs((tonumber(bucket.max) or 0) - maxHitValue) < 0.001 then
                maxHitSkill = tostring(bucket.name or "");
                break;
            end
        end
    end
    if maxHitSkill == "" then
        maxHitSkill = "Unknown skill";
    end
    local maxHitLabel, maxHitValue = DrawParseDetailStat(ParseGraph.ParseDetailContent, 696, 178, 110, "Max hit", FormatNumber(combat.max), white);
    BindParseDetailTooltip(maxHitLabel, ParseGraph.ParseDetailContent, "Max hit skill", maxHitSkill, 560, 228);
    BindParseDetailTooltip(maxHitValue, ParseGraph.ParseDetailContent, "Max hit skill", maxHitSkill, 560, 228);

    local skills = {};
    if type(combat.skills) == "table" then
        for _, bucket in pairs(combat.skills) do
            if type(bucket) == "table" then
                table.insert(skills, bucket);
            end
        end
    end
    table.sort(skills, function(a, b)
        return (tonumber(a.totalDamage) or 0) > (tonumber(b.totalDamage) or 0);
    end);

    local benefits = {};
    if type(combat.benefits) == "table" then
        for _, bucket in pairs(combat.benefits) do
            if type(bucket) == "table" then
                table.insert(benefits, bucket);
            end
        end
    end
    table.sort(benefits, function(a, b)
        local ac = tonumber(a.count) or 0;
        local bc = tonumber(b.count) or 0;
        if ac == bc then
            return tostring(a.name or "") < tostring(b.name or "");
        end
        return ac > bc;
    end);

    local countAverages = BuildParseDetailCountAverages(GetParseDetailComparisonParses(selection));

    local tableY = 278;
    local header = Label(ParseGraph.ParseDetailContent, 48, tableY - 42, 744, 30, "Breakdown", "achievementTitle");
    header:SetForeColor(gold);
    header:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    local columns = {
        { x = 82, w = 315, text = "Skill" },
        { x = 402, w = 70, text = "Hits", align = Turbine.UI.ContentAlignment.MiddleRight },
        { x = 500, w = 120, text = "Damage", align = Turbine.UI.ContentAlignment.MiddleRight },
        { x = 650, w = 65, text = "Crit", align = Turbine.UI.ContentAlignment.MiddleRight },
        { x = 736, w = 55, text = "Dev", align = Turbine.UI.ContentAlignment.MiddleRight }
    };
    for i = 1, #columns do
        local col = columns[i];
        local label = Label(ParseGraph.ParseDetailContent, col.x, tableY, col.w, 20, col.text, "achievementDetail");
        label:SetForeColor(gold);
        label:SetTextAlignment(col.align or Turbine.UI.ContentAlignment.MiddleLeft);
        if col.text == "Hits" or col.text == "Damage" or col.text == "Crit" or col.text == "Dev" then
            BindParseHitsTooltip(label, ParseGraph.ParseDetailContent, col.x - 75, tableY - 132, col.text .. " colours");
        end
    end
    DrawBlock(ParseGraph.ParseDetailContent, 48, tableY + 24, 744, 1, border);

    local maxSkillDamage = 0;
    for i = 1, #skills do
        maxSkillDamage = math.max(maxSkillDamage, tonumber(skills[i].totalDamage) or 0);
    end

    local listY = tableY + 28;
    local listH = 322;
    local listW = 744;
    local rowH = 28;
    local benefitSeparatorH = 46;
    local list = Turbine.UI.ListBox();
    list:SetParent(ParseGraph.ParseDetailContent);
    list:SetPosition(48, listY);
    list:SetSize(listW, listH);
    list:SetOrientation(Turbine.UI.Orientation.Vertical);
    list:SetBackColor(Turbine.UI.Color(1.00, 0, 0, 0));
    list:SetZOrder(1);
    pcall(function()
        list:SetClipMode(true);
    end);

    local scroll = Turbine.UI.Lotro.ScrollBar();
    scroll:SetParent(ParseGraph.ParseDetailContent);
    scroll:SetOrientation(Turbine.UI.Orientation.Vertical);
    scroll:SetPosition(795, listY);
    scroll:SetSize(12, listH);
    scroll:SetBackColor(Turbine.UI.Color(1.00, 0, 0, 0));
    list:SetVerticalScrollBar(scroll);
    ParseGraph.ParseDetailSkillDivider = DrawBlock(ParseGraph.ParseDetailContent, 397, tableY, 1, (listY + listH) - tableY, border);
    ParseGraph.ParseDetailSkillDivider:SetZOrder(6);
    ParseGraph.ParseDetailSkillDivider:SetMouseVisible(false);
    local totalHeight = #skills * rowH;
    if #benefits > 0 then
        totalHeight = totalHeight + benefitSeparatorH + (#benefits * rowH);
    end
    scroll:SetVisible(totalHeight > listH);

    local function CreateBreakdownRow(fill)
        local row = Panel(nil, 0, 0, listW, rowH, 1.00);
        row:SetSize(listW, rowH);
        row:SetMouseVisible(true);
        row.normalFill = fill or ParseGraph.ParseRowNormalFill;
        row.hoverFill = ParseGraph.ParseRowHoverFill;
        row:SetBackColor(row.normalFill);
        pcall(function()
            row:SetClipMode(true);
        end);
        row.MouseEnter = function(sender)
            sender:SetBackColor(sender.hoverFill);
        end
        row.MouseLeave = function(sender)
            sender:SetBackColor(sender.normalFill);
        end
        return row;
    end

    local function DrawBreakdownIcon(row, iconId)
        if iconId == nil then
            return false;
        end
        local iconSlot = DrawBlock(row, 4, 4, 22, 22, row.normalFill);
        iconSlot:SetMouseVisible(false);
        pcall(function()
            iconSlot:SetClipMode(true);
        end);

        local icon = nil;
        local iconLoaded = false;
        icon, iconLoaded = ParseGraph.CreateManagedIcon(iconSlot, 3, 3, 16, 16, iconId);
        if iconLoaded ~= true then
            ParseGraph.DisposeManagedIconControl(iconSlot);
            return false;
        end

        local function UpdateIconVisibility()
            ParseGraph.UpdateManagedIconClip({
                iconSlot = iconSlot,
                icon = icon,
                row = row,
                viewportH = listH,
                slotX = 4,
                slotY = 4,
                slotW = 22,
                slotH = 22,
                iconX = 3,
                iconY = 3
            });
        end
        ParseGraph.ParseCompareIconControls = ParseGraph.ParseCompareIconControls or {};
        table.insert(ParseGraph.ParseCompareIconControls, {
            iconSlot = iconSlot,
            icon = icon,
            update = UpdateIconVisibility
        });
        row.PositionChanged = function()
            UpdateIconVisibility();
        end
        UpdateIconVisibility();
        return true;
    end

    for i = 1, #skills do
        local skill = skills[i];
        local row = CreateBreakdownRow((i % 2 == 0) and ParseGraph.ParseRowAlternateFill or ParseGraph.ParseRowNormalFill);

        local barWidth = 0;
        local barX = 34;
        local barMaxWidth = listW - barX;
        if maxSkillDamage > 0 then
            barWidth = math.floor(barMaxWidth * ((tonumber(skill.totalDamage) or 0) / maxSkillDamage));
        end
        local bar = DrawBlock(row, barX, 3, barWidth, 22, Turbine.UI.Color(1.00, 0.345, 0.106, 0.106));
        bar:SetMouseVisible(false);

        local iconId = ParseGraph.GetSkillIconId(skill.name);
        DrawBreakdownIcon(row, iconId);

        local name = Label(row, 34, 0, 314, rowH, tostring(skill.name or "-"), "big");
        name:SetForeColor(white);
        name:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
        name:SetMouseVisible(false);
        name:SetZOrder(5);
        local hitsColor, damageColor, critColor, devColor = GetParseDetailSkillMetricColors(skill, countAverages, white);
        local hits = Label(row, 354, 0, 70, rowH, FormatNumber(skill.hits or skill.attacks), "big");
        hits:SetForeColor(hitsColor);
        hits:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        hits:SetMouseVisible(false);
        local damage = Label(row, 452, 0, 120, rowH, FormatNumber(skill.totalDamage), "big");
        damage:SetForeColor(damageColor);
        damage:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        damage:SetMouseVisible(false);
        damage:SetZOrder(5);
        local crit = Label(row, 602, 0, 65, rowH, FormatCombatPercent(skill.crits, skill.hits or skill.attacks), "big");
        crit:SetForeColor(critColor);
        crit:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        crit:SetMouseVisible(false);
        local dev = Label(row, 688, 0, 55, rowH, FormatCombatPercent(skill.devs, skill.hits or skill.attacks), "big");
        dev:SetForeColor(devColor);
        dev:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
        dev:SetMouseVisible(false);
        list:AddItem(row);
    end

    if #benefits > 0 then
        local separator = Turbine.UI.Control();
        separator:SetSize(listW, benefitSeparatorH);
        separator:SetBackColor(Turbine.UI.Color(1.00, 0, 0, 0));
        separator:SetMouseVisible(false);
        pcall(function()
            separator:SetClipMode(true);
        end);
        local benefitTitle = Label(separator, 34, 8, 220, 24, "Benefits", "achievementDetail");
        benefitTitle:SetForeColor(gold);
        benefitTitle:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
        benefitTitle:SetMouseVisible(false);
        DrawBlock(separator, 0, benefitSeparatorH - 8, listW, 1, border);
        list:AddItem(separator);

        for i = 1, #benefits do
            local benefit = benefits[i];
            local row = CreateBreakdownRow((i % 2 == 0) and ParseGraph.ParseRowAlternateFill or ParseGraph.ParseRowNormalFill);
            local iconId = ParseGraph.GetSkillIconId(benefit.name);
            DrawBreakdownIcon(row, iconId);

            local name = Label(row, 34, 0, 314, rowH, tostring(benefit.name or "-"), "big");
            name:SetForeColor(white);
            name:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
            name:SetMouseVisible(false);
        name:SetZOrder(5);
            local count = tonumber(benefit.count) or 0;
            local hits = Label(row, 354, 0, 70, rowH, FormatNumber(count), "big");
            hits:SetForeColor(GetParseDetailCountColor(count, countAverages.benefits[tostring(benefit.name or "")], white));
            hits:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
            hits:SetMouseVisible(false);
            list:AddItem(row);
        end
    end
end

function ParseGraph.BuildParseDetailView(parent)
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local view = Panel(parent, 15, 15, 880, 725, 0.96);
    ParseGraph.ParseDetailView = view;
    DrawAchievementBorder(view, 880, 725, border);

    ParseGraph.ParseDetailContent = Panel(view, 20, 20, 840, 700, 1.00);
    ParseGraph.ParseDetailContent:SetZOrder(1);

    ParseGraph.ParseDetailClearCompareButton = ParseGraph.CreateActionButton(view, 570, 688, 145, 22, "Clear", function()
        ParseGraph.ParseCompareSelections = {};
        ParseGraph.ParseCompareViewActive = true;
        ParseGraph.DrawParseDetailView();
    end);
    ParseGraph.ParseDetailClearCompareButton:SetZOrder(100);
    ParseGraph.ParseDetailClearCompareButton:SetVisible(false);

    ParseGraph.ParseDetailShareButton = ParseGraph.CreateActionButton(view, 730, 657, 145, 22, "Share", function(sender)
        ParseGraph.ShareParsePoint(sender.parsePoint);
    end);
    ParseGraph.ParseDetailShareButton:SetZOrder(100);
    ParseGraph.ParseDetailShareButton:SetVisible(false);

    ParseGraph.ParseDetailFullViewButton = ParseGraph.CreateActionButton(view, 730, 626, 145, 22, "Full view", function(sender)
        ParseGraph.ShowParseFullView(sender.parsePoint);
    end);
    ParseGraph.ParseDetailFullViewButton:SetZOrder(100);
    ParseGraph.ParseDetailFullViewButton:SetVisible(false);

    local brandPanel = Turbine.UI.Control();
    brandPanel:SetParent(view);
    brandPanel:SetPosition(614, 657);
    brandPanel:SetSize(90, 42);
    brandPanel:SetMouseVisible(false);
    brandPanel:SetZOrder(100);
    local compactLogo = Turbine.UI.Control();
    compactLogo:SetParent(brandPanel);
    compactLogo:SetPosition(33, 0);
    compactLogo:SetSize(24, 24);
    compactLogo:SetMouseVisible(false);
    pcall(function()
        compactLogo:SetBackground((ParseGraph.GeneralIconPath or "") .. "parsegraph_launcher_medium.tga");
    end);
    pcall(function()
        compactLogo:SetStretchMode(2);
        compactLogo:SetStretchMode(1);
    end);
    local compactBrandParse = Label(brandPanel, 0, 25, 45, 14, "Parse", "small");
    compactBrandParse:SetForeColor(Turbine.UI.Color(1.00, 1.00, 0.82, 0.16));
    compactBrandParse:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
    compactBrandParse:SetMouseVisible(false);
    local compactBrandGraph = Label(brandPanel, 45, 25, 45, 14, "Graph", "small");
    compactBrandGraph:SetForeColor(Turbine.UI.Color(1.00, 0.92, 0.90, 0.84));
    compactBrandGraph:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    compactBrandGraph:SetMouseVisible(false);
    brandPanel:SetVisible(false);
    ParseGraph.ParseDetailBrandPanel = brandPanel;

    ParseGraph.ParseDetailBackButton = ParseGraph.CreateActionButton(view, 730, 688, 145, 22, "Back", function()
        ParseGraph.ParseCompareViewActive = false;
        local returnView = ParseGraph.SelectedParseDetail and ParseGraph.SelectedParseDetail.returnView or "history";
        if returnView == nil or returnView == "" or returnView == "parseDetail" then
            returnView = "history";
        end
        ParseGraph.SetView(returnView);
    end);
    ParseGraph.ParseDetailBackButton:SetZOrder(100);
    view:SetVisible(false);
end

ParseGraph.ParseRowNormalFill = Turbine.UI.Color(1.00, 0, 0, 0);
ParseGraph.ParseRowAlternateFill = Turbine.UI.Color(1.00, 0.11, 0.11, 0.11);
ParseGraph.ParseRowHoverFill = Turbine.UI.Color(1.00, 0.04, 0.18, 0.34);

function ParseGraph.ApplyParseSpecSlotState(slot, hover)
    if slot == nil then
        return;
    end

    local fill = hover and ParseGraph.ParseRowHoverFill or ParseGraph.ParseRowNormalFill;
    slot:SetBackColor(fill);
    if slot.iconBack ~= nil then
        slot.iconBack:SetBackColor(fill);
    end
end

function ParseGraph.DrawParseSpecSelector(parent, x, y, size, point, rowHighlight)
    local slot = DrawBlock(parent, x, y, size, size, ParseGraph.ParseRowNormalFill);
    slot:SetMouseVisible(true);
    slot:SetZOrder(135);
    pcall(function()
        slot:SetClipMode(true);
    end);
    slot.parsePoint = point;
    slot.rowHighlight = rowHighlight;

    local iconPath = ParseGraph.GetParseSpecIconPath(point);
    local icon, loaded = ParseGraph.CreateManagedIcon(slot, 0, 0, size, size, iconPath);
    if loaded then
        slot.specIcon = icon;
    else
        local fallback = Label(slot, 0, 0, size, size, "?", "small");
        fallback:SetForeColor(Turbine.UI.Color(1.00, 0.60, 0.60, 0.60));
        fallback:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        fallback:SetMouseVisible(false);
        slot.specIcon = fallback;
    end

    slot.MouseEnter = function(sender)
        if sender.rowHighlight ~= nil then
            sender.rowHighlight:SetBackColor(ParseGraph.ParseRowHoverFill);
        end
        ParseGraph.ApplyParseSpecSlotState(sender, true);
    end
    slot.MouseLeave = function(sender)
        if sender.rowHighlight ~= nil then
            sender.rowHighlight:SetBackColor(ParseGraph.ParseRowNormalFill);
        end
        ParseGraph.ApplyParseSpecSlotState(sender, false);
    end
    slot.MouseClick = function(sender)
        ParseGraph.ShowParseSpecMenu(sender, sender.parsePoint);
    end

    return slot;
end

local function DrawParseFavouriteStar(parent, x, y, size, point)
    local star = Turbine.UI.Label();
    star:SetParent(parent);
    star:SetPosition(x, y);
    star:SetSize(size, size);
    star:SetMouseVisible(true);
    star:SetZOrder(140);
    star.parsePoint = point;
    pcall(function()
        star:SetClipMode(true);
    end);
    pcall(function()
        if Turbine.UI.BlendMode ~= nil and star.SetBlendMode ~= nil then
            star:SetBlendMode(Turbine.UI.BlendMode.AlphaBlend);
        end
    end);

    local function SetStarTexture(sender, state)
        local texture = (ParseGraph.GraphIconPath or "") .. "history_star_" .. tostring(state) .. ".tga";
        pcall(function()
            sender:SetBackground(texture);
        end);
        sender:SetOpacity(1.00);
    end

    local function ApplyStarState(sender, hover, cardHover)
        hover = hover == true;
        cardHover = cardHover == true;

        local isFavourite = ParseGraph.IsParseFavourite(sender.parsePoint);
        if hover == true and cardHover ~= true then
            SetStarTexture(sender, "icon_hover");
        elseif cardHover == true and isFavourite then
            SetStarTexture(sender, "hover_favourited");
        elseif isFavourite then
            SetStarTexture(sender, "selected");
        elseif hover == true then
            SetStarTexture(sender, "hover");
        else
            SetStarTexture(sender, "inactive");
        end
    end

    star.ApplyFavouriteState = ApplyStarState;
    ApplyStarState(star, false, false);
    star.MouseEnter = function(sender)
        ApplyStarState(sender, true, false);
    end
    star.MouseLeave = function(sender)
        ApplyStarState(sender, false, false);
    end
    star.MouseClick = function(sender)
        ParseGraph.ToggleParseFavourite(sender.parsePoint);
    end
    star.MouseWheel = function(sender, args)
        ParseGraph.ScrollParseHistoryListByWheel(args);
    end

    return star;
end
function ParseGraph.ClearParseHistoryCardIcons()
    ParseGraph.ParseHistoryListBox = nil;
    local controls = ParseGraph.ParseHistoryCardIconControls or {};
    for i = 1, #controls do
        ParseGraph.DisposeManagedIconItem(controls[i]);
    end
    ParseGraph.ParseHistoryCardIconControls = {};
end

function ParseGraph.ApplyParseHistoryClassIconHover(card, hover)
    if card == nil then
        return;
    end

    local fill = hover == true and ParseGraph.ParseRowHoverFill or ParseGraph.ParseRowNormalFill;
    if card.classIconBack ~= nil then
        card.classIconBack:SetBackColor(fill);
    end
    if card.classIcon ~= nil then
        local iconPath = hover == true and card.classIconHoverPath or card.classIconNormalPath;
        pcall(function()
            card.classIcon:SetBackground(iconPath);
        end);
    end
    if card.specIconBack ~= nil then
        card.specIconBack:SetBackColor(fill);
    end
    if card.specIcon ~= nil then
        local specPath = hover == true and card.specIconHoverPath or card.specIconNormalPath;
        pcall(function()
            card.specIcon:SetBackground(specPath);
        end);
    end
end

local function DrawParseHistoryCard(parent, x, y, w, h, point, border, viewportH, rowIndex, rowH, scroll)
    local gold = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local white = Turbine.UI.Color(1.00, 0.92, 0.90, 0.84);
    local muted = Turbine.UI.Color(0.95, 0.70, 0.70, 0.70);
    local sourceGreen = Turbine.UI.Color(1.00, 0.42, 1.00, 0.38);
    local parseBlue = Turbine.UI.Color(1.00, 0.45, 0.78, 1.00);
    local card = Panel(parent, x, y, w, h, 1.00);
    DrawAchievementBorder(card, w, h, border);
    card:SetMouseVisible(false);
    card:SetBackColor(ParseGraph.ParseRowNormalFill);
    pcall(function()
        card:SetClipMode(true);
    end);

    local parse = point ~= nil and point.parse or nil;
    local parseIndex = tonumber(point ~= nil and point.index) or 0;
    local currentKey = ParseGraph.GetCurrentCharacterKey();
    local sourceKey = tostring((point ~= nil and point.sourceKey) or (parse and parse.__sourceKey) or ParseGraph.ViewCharacterKey or currentKey);
    local sourceIndex = tonumber((point ~= nil and point.sourceIndex) or (parse and parse.__sourceIndex) or parseIndex) or parseIndex;
    local sourceName = tostring((point ~= nil and point.sourceName) or (parse and parse.__sourceName) or ParseGraph.GetCharacterDisplayName(sourceKey));
    local imported = point ~= nil and point.imported == true;
    local canDelete = sourceKey == currentKey;
    local canDeleteImported = imported == true;
    local timeText = tostring(parse and parse.time or "");
    local datePart, timePart = string.match(timeText, "^(%d%d%d%d%-%d%d%-%d%d)%s+(.+)$");
    local dateTimeText = timeText;
    if datePart ~= nil and timePart ~= nil then
        dateTimeText = tostring(timePart) .. "  •  " .. tostring(datePart);
    end

    local classIconPath = ParseGraph.GetParsePointClassIcon(point);
    if classIconPath ~= nil and tostring(classIconPath) ~= "" then
        local iconBack = DrawBlock(card, 24, 34, 40, 40, ParseGraph.ParseRowNormalFill);
        iconBack:SetMouseVisible(false);
        iconBack:SetZOrder(1);

        local icon = Turbine.UI.Control();
        icon:SetParent(card);
        icon:SetPosition(24, 34);
        icon:SetSize(40, 40);
        local normalIconPath = tostring(classIconPath);
        local hoverIconPath = GetIconVariantPath(normalIconPath, "hover");
        local iconLoaded = pcall(function()
            icon:SetBackground(normalIconPath);
        end);
        icon:SetMouseVisible(false);
        icon:SetZOrder(2);
        if iconLoaded then
            card.classIcon = icon;
            card.classIconBack = iconBack;
            card.classIconNormalPath = normalIconPath;
            card.classIconHoverPath = hoverIconPath;
        else
            icon:SetParent(nil);
            iconBack:SetParent(nil);
        end
    end

    local specSize = 18;
    local specX = 24 + math.floor((40 - specSize) / 2);
    local specIconPath = ParseGraph.GetParseSpecIconPath(point);
    if specIconPath ~= nil and tostring(specIconPath) ~= "" then
        local normalSpecIconPath = string.gsub(tostring(specIconPath), "%.tga$", "_history.tga");
        local hoverSpecIconPath = string.gsub(tostring(specIconPath), "%.tga$", "_history_hover.tga");
        local specBack = DrawBlock(card, specX, 78, specSize, specSize, ParseGraph.ParseRowNormalFill);
        specBack:SetMouseVisible(false);
        specBack:SetZOrder(1);

        local specIcon = Turbine.UI.Control();
        specIcon:SetParent(card);
        specIcon:SetPosition(specX, 78);
        specIcon:SetSize(specSize, specSize);
        local specLoaded = pcall(function()
            specIcon:SetBackground(normalSpecIconPath);
        end);
        specIcon:SetMouseVisible(false);
        specIcon:SetZOrder(2);
        if specLoaded then
            card.specIconBack = specBack;
            card.specIcon = specIcon;
            card.specIconNormalPath = normalSpecIconPath;
            card.specIconHoverPath = hoverSpecIconPath;
        else
