    DrawBlock(statsPanel, 90, 10, 1, statsH - 20, border);
    DrawBlock(statsPanel, 181, 10, 1, statsH - 20, border);
    DrawBlock(statsPanel, finalColumnX, 1, 1, statsH - 2, border);

