        { x = 2, w = 88, label = "1st min", value = ParseGraph.FormatSummaryNumber(parse and parse.minutes and parse.minutes[1]), color = ParseGraph.GetMinuteSummaryUiColorForParse(point or parse, parse and parse.minutes and parse.minutes[1], minuteAverages[1], white), valueFont = "big" },
        { x = 93, w = 86, label = "2nd min", value = ParseGraph.FormatSummaryNumber(parse and parse.minutes and parse.minutes[2]), color = ParseGraph.GetMinuteSummaryUiColorForParse(point or parse, parse and parse.minutes and parse.minutes[2], minuteAverages[2], white), valueFont = "big" },
        { x = 184, w = 86, label = "3rd min", value = ParseGraph.FormatSummaryNumber(parse and parse.minutes and parse.minutes[3]), color = ParseGraph.GetMinuteSummaryUiColorForParse(point or parse, parse and parse.minutes and parse.minutes[3], minuteAverages[3], white), valueFont = "big" },
        { x = finalColumnX + 3, w = statsW - finalColumnX - 6, label = "Final parse", value = FormatNumber(parse and parse.final), color = parseBlue, valueFont = "achievementTitle" }
    };
    for i = 1, #columns do
