    };
    DrawBlock(card, 624, 20, 1, h - 40, border);
    if ParseGraph.CanCompareParsePoint(comparePoint) then
        DrawParseCompareCheckbox(card, w - 30, 12, comparePoint, true, false, true);
    end
    local actionX = 634;
    local actionW = 120;
    local hasDelete = canDelete or canDeleteImported;
    local firstButtonY = hasDelete and 18 or 32;

    local fullView = ParseGraph.CreateActionButton(card, actionX, firstButtonY, actionW, 24, "Full view", function(sender)
        ParseGraph.ShowParseFullView(sender.parsePoint);
    end);
