    fullView:SetZOrder(120);

    local share = ParseGraph.CreateActionButton(card, actionX, firstButtonY + 28, actionW, 24, "Share", function(sender)
        ParseGraph.ShareParsePoint(sender.parsePoint);
    end);
    share.parsePoint = comparePoint;
    share:SetZOrder(120);

    if hasDelete then
        local del = ParseGraph.CreateActionButton(card, actionX, firstButtonY + 56, actionW, 24, "Delete", function(sender)
            if sender.imported == true then
                ParseGraph.DeleteImportedParse(sender.sourceKey, sender.sourceIndex);
            else
                ParseGraph.DeleteParseBySource(sender.sourceKey, sender.sourceIndex);
            end
        end);
        del.sourceKey = sourceKey;
        del.sourceIndex = sourceIndex;
        del.imported = canDeleteImported;
        del:SetZOrder(120);
    end

    local clickSurface = Turbine.UI.Control();
    clickSurface:SetParent(card);
    clickSurface:SetPosition(0, 0);
    clickSurface:SetSize(math.max(0, 604), h);
    clickSurface:SetMouseVisible(true);
