    clickSurface.favouriteStar = favouriteStar;
    clickSurface.MouseEnter = function(sender)
        sender.card:SetBackColor(ParseGraph.ParseRowHoverFill);
        ParseGraph.ApplyParseHistoryClassIconHover(sender.card, true);
        if sender.favouriteStar ~= nil and sender.favouriteStar.ApplyFavouriteState ~= nil then
            sender.favouriteStar.ApplyFavouriteState(sender.favouriteStar, true, true);
        end
    end
    clickSurface.MouseLeave = function(sender)
        sender.card:SetBackColor(ParseGraph.ParseRowNormalFill);
        ParseGraph.ApplyParseHistoryClassIconHover(sender.card, false);
        if sender.favouriteStar ~= nil and sender.favouriteStar.ApplyFavouriteState ~= nil then
            sender.favouriteStar.ApplyFavouriteState(sender.favouriteStar, false, false);
        end
    end
    clickSurface.MouseClick = function(sender)
        ParseGraph.OpenParseDetail(sender.parsePoint, "history");
    end
    clickSurface.MouseWheel = function(sender, args)
        ParseGraph.ScrollParseHistoryListByWheel(args);
    end
end

function ParseGraph.GetParseHistoryTabLabel(tab)
    tab = tostring(tab or "history");
    if tab == "favourites" then
        return "Favourites";
    elseif tab == "imported" then
        return "Imported";
    end
    return "History";
end

function ParseGraph.GetParseHistoryTabPoints(tab)
    tab = tostring(tab or ParseGraph.ParseHistoryTab or "history");
    if tab == "favourites" then
        return ParseGraph.GetFavouriteParseHistoryPoints(), "Favourite parses", "No favourite parses saved yet.";
    elseif tab == "imported" then
        return ParseGraph.GetImportedParseHistoryPoints(), "Imported parses", "No imported parses saved yet.";
    end
    return ParseGraph.GetParseHistoryPoints(100), "Latest 100 parses", "No parses saved yet.";
end

function ParseGraph.UpdateParseHistoryTabButtons()
    if type(ParseGraph.ParseHistoryTabButtons) ~= "table" then
        return;
    end

    local current = tostring(ParseGraph.ParseHistoryTab or "history");
    for key, button in pairs(ParseGraph.ParseHistoryTabButtons) do
        ParseGraph.SetActionButtonSelected(button, key == current);
    end
end

function ParseGraph.GetParseHistorySortLabel(sortKey)
    sortKey = tostring(sortKey or "number");
    if sortKey == "final" then
        return "Final DPS";
    elseif sortKey == "name" then
        return "Name";
    elseif sortKey == "class" then
        return "Class";
    end
    return "Number";
end

function ParseGraph.GetParseHistorySortDirectionText()
    local sortKey = tostring(ParseGraph.ParseHistorySortKey or "number");
    local descending = ParseGraph.ParseHistorySortDescending ~= false;
    if sortKey == "name" or sortKey == "class" then
        return descending and "Z-A" or "A-Z";
    elseif sortKey == "final" then
        return descending and "High first" or "Low first";
    end
    return descending and "Newest first" or "Oldest first";
end

function ParseGraph.IsParseHistorySearchTab(tab)
    tab = tostring(tab or ParseGraph.ParseHistoryTab or "history");
    return tab == "favourites" or tab == "imported";
end

function ParseGraph.GetParseHistorySearchText(tab)
    tab = tostring(tab or ParseGraph.ParseHistoryTab or "history");
    if type(ParseGraph.ParseHistorySearchTexts) ~= "table" then
        ParseGraph.ParseHistorySearchTexts = {};
    end
    return tostring(ParseGraph.ParseHistorySearchTexts[tab] or "");
end

function ParseGraph.SetParseHistorySearchText(tab, text)
    tab = tostring(tab or ParseGraph.ParseHistoryTab or "history");
    if type(ParseGraph.ParseHistorySearchTexts) ~= "table" then
        ParseGraph.ParseHistorySearchTexts = {};
    end
    ParseGraph.ParseHistorySearchTexts[tab] = tostring(text or "");
end

function ParseGraph.GetParseHistorySearchHaystack(point)
    local parse = type(point) == "table" and point.parse or nil;
    local finalValue = tonumber(parse and parse.final) or 0;
    local formattedFinal = FormatNumber(finalValue);
    local compactFinal = "";
    if finalValue > 0 then
        compactFinal = tostring(math.floor((finalValue / 1000) + 0.5)) .. "k";
    end

    local text = table.concat({
        ParseGraph.GetParseHistoryPointName(point),
        ParseGraph.GetParseHistoryPointClassName(point),
        tostring(finalValue),
        tostring(formattedFinal or ""),
        string.gsub(tostring(formattedFinal or ""), ",", ""),
        compactFinal,
        "dps"
    }, " ");
    return string.lower(text);
end

function ParseGraph.FilterParseHistoryPointsBySearch(points, searchText)
    local filtered = {};
    if type(points) ~= "table" then
        return filtered, false;
    end

    local query = string.lower(TrimText(searchText or ""));
    if query == "" then
        for i = 1, #points do
            filtered[i] = points[i];
        end
        return filtered, false;
    end

    local queryNoComma = string.gsub(query, ",", "");
    for i = 1, #points do
        local haystack = ParseGraph.GetParseHistorySearchHaystack(points[i]);
        local haystackNoComma = string.gsub(haystack, ",", "");
        if string.find(haystack, query, 1, true) ~= nil or string.find(haystackNoComma, queryNoComma, 1, true) ~= nil then
            filtered[#filtered + 1] = points[i];
        end
    end

    return filtered, true;
end

function ParseGraph.UpdateParseHistorySearchControls(tab)
    tab = tostring(tab or ParseGraph.ParseHistoryTab or "history");
    local enabled = ParseGraph.IsParseHistorySearchTab(tab);

    if type(ParseGraph.ParseHistorySearchControls) == "table" then
        for i = 1, #ParseGraph.ParseHistorySearchControls do
            local control = ParseGraph.ParseHistorySearchControls[i];
            if control ~= nil then
                control:SetVisible(enabled);
            end
        end
    end

    if ParseGraph.ParseHistorySearchBox ~= nil then
        ParseGraph.ParseHistorySearchBox:SetVisible(enabled);
        ParseGraph.ParseHistorySearchBox:SetMouseVisible(enabled);
        if enabled then
            local text = ParseGraph.GetParseHistorySearchText(tab);
            ParseGraph.UpdatingParseHistorySearchBox = true;
            if tostring(ParseGraph.ParseHistorySearchBox:GetText() or "") ~= text then
                ParseGraph.ParseHistorySearchBox:SetText(text);
            end
            ParseGraph.UpdatingParseHistorySearchBox = false;
        end
    end

    local headerY = enabled and 142 or 108;
    local listY = enabled and 180 or 146;
    local listH = enabled and 493 or 527;
    if ParseGraph.ParseHistoryHeaderPanel ~= nil then
        ParseGraph.ParseHistoryHeaderPanel:SetPosition(20, headerY);
    end
    if ParseGraph.ParseHistoryListPanel ~= nil then
        ParseGraph.ParseHistoryListPanel:SetPosition(20, listY);
        ParseGraph.ParseHistoryListPanel:SetSize(840, listH);
    end
end

function ParseGraph.CreateParseHistorySortHeader(parent, x, y, w, h, text, key, alignment)
    local control = Turbine.UI.Control();
    control:SetParent(parent);
    control:SetPosition(x, y);
    control:SetSize(w, h);
    control:SetMouseVisible(true);
    control.sortKey = key;

    local normalColor = Turbine.UI.Color(1.00, 1.00, 0.70, 0.10);
    local hoverColor = Turbine.UI.Color(1.00, 1.00, 0.88, 0.24);
    local selected = ParseGraph.ParseHistorySortKey == key;
    local labelX = selected and 24 or 0;
    local labelW = w - labelX;
    local label = Label(control, labelX, 0, labelW, h, text or "", "achievementDetail");
    label:SetTextAlignment(alignment or Turbine.UI.ContentAlignment.MiddleCenter);
    label:SetForeColor(normalColor);
    label:SetMouseVisible(false);
    control.label = label;

    if selected then
        local arrowPath = (ParseGraph.ScoreboardIconPath or "") .. ((ParseGraph.ParseHistorySortDescending ~= false) and "sort_down.tga" or "sort_up.tga");
        local iconBack = DrawBlock(control, 20, math.floor((h - 11) / 2), 11, 11, Turbine.UI.Color(1.00, 0.00, 0.00, 0.00));
        iconBack:SetMouseVisible(false);
        local icon, loaded = ParseGraph.CreateManagedIcon(iconBack, 0, 0, 11, 11, arrowPath);
        if not loaded then
            ParseGraph.DisposeManagedIconControl(icon);
            ParseGraph.DisposeManagedIconControl(iconBack);
        end
    end

    control.MouseEnter = function(sender)
        if sender.label ~= nil then
            sender.label:SetForeColor(hoverColor);
        end
    end
    control.MouseLeave = function(sender)
        if sender.label ~= nil then
            sender.label:SetForeColor(normalColor);
        end
    end
    control.MouseClick = function(sender)
        ParseGraph.SetParseHistorySort(sender.sortKey);
    end

    return control;
end

function ParseGraph.DrawParseHistorySortHeaders()
    if ParseGraph.ParseHistoryHeaderPanel == nil then
        return;
    end

    ClearChildren(ParseGraph.ParseHistoryHeaderPanel);
    ParseGraph.ParseHistorySortHeaders = {};

    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local labelColor = Turbine.UI.Color(1.00, 1.00, 0.70, 0.10);
    DrawBlock(ParseGraph.ParseHistoryHeaderPanel, 0, 0, 840, 1, border);
    DrawBlock(ParseGraph.ParseHistoryHeaderPanel, 0, 30, 840, 1, border);
    local sortLabel = Label(ParseGraph.ParseHistoryHeaderPanel, 28, 2, 90, 26, "Sorting:", "achievementDetail");
    sortLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    sortLabel:SetForeColor(labelColor);
    sortLabel:SetMouseVisible(false);

    local headers = {
        { key = "class", label = "Class", x = 145, w = 90 },
        { key = "number", label = "Number", x = 265, w = 105 },
        { key = "name", label = "Character", x = 405, w = 140 },
        { key = "final", label = "Final DPS", x = 580, w = 130 }
    };

    for i = 1, #headers do
        local item = headers[i];
        ParseGraph.ParseHistorySortHeaders[item.key] = ParseGraph.CreateParseHistorySortHeader(
            ParseGraph.ParseHistoryHeaderPanel,
            item.x,
            2,
            item.w,
            26,
            item.label,
            item.key,
            Turbine.UI.ContentAlignment.MiddleCenter
        );
    end
end

function ParseGraph.UpdateParseHistorySortButtons()
    if type(ParseGraph.ParseHistorySortButtons) ~= "table" then
        return;
    end

    local current = tostring(ParseGraph.ParseHistorySortKey or "number");
    for key, button in pairs(ParseGraph.ParseHistorySortButtons) do
        ParseGraph.SetActionButtonSelected(button, key == current);
    end

    if ParseGraph.ParseHistorySortDirectionLabel ~= nil then
        ParseGraph.ParseHistorySortDirectionLabel:SetText(ParseGraph.GetParseHistorySortDirectionText());
    end
end

function ParseGraph.SetParseHistorySort(sortKey)
    sortKey = tostring(sortKey or "number");
    if sortKey ~= "number" and sortKey ~= "final" and sortKey ~= "name" and sortKey ~= "class" then
        sortKey = "number";
    end

    if tostring(ParseGraph.ParseHistorySortKey or "number") == sortKey then
        ParseGraph.ParseHistorySortDescending = not (ParseGraph.ParseHistorySortDescending ~= false);
    else
        ParseGraph.ParseHistorySortKey = sortKey;
        ParseGraph.ParseHistorySortDescending = sortKey == "number" or sortKey == "final";
    end

    ParseGraph.UpdateParseHistorySortButtons();
    ParseGraph.DrawParseHistoryView();
end

function ParseGraph.SetParseHistoryTab(tab)
    tab = tostring(tab or "history");
    if tab ~= "history" and tab ~= "favourites" and tab ~= "imported" then
        tab = "history";
    end

    ParseGraph.ParseHistoryTab = tab;
    ParseGraph.UpdateParseHistoryTabButtons();
    ParseGraph.DrawParseHistoryView();
end

function ParseGraph.DrawParseHistoryView()
    if ParseGraph.ParseHistoryListPanel == nil then
        return;
    end

    ParseGraph.ClearParseHistoryCardIcons();
    local activeTab = tostring(ParseGraph.ParseHistoryTab or "history");
    ParseGraph.UpdateParseHistorySearchControls(activeTab);
    if ParseGraph.ParseHistoryHeaderPanel ~= nil then
        ParseGraph.DrawParseHistorySortHeaders();
    end
    ClearChildren(ParseGraph.ParseHistoryListPanel);
    ParseGraph.UpdateParseHistoryCompareButton();
    ParseGraph.UpdateParseHistoryTabButtons();
    ParseGraph.UpdateParseHistorySortButtons();
    local border = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local points, countText, emptyText = ParseGraph.GetParseHistoryTabPoints(activeTab);
    if ParseGraph.IsParseHistorySearchTab(activeTab) then
        local searchActive = false;
        points, searchActive = ParseGraph.FilterParseHistoryPointsBySearch(points, ParseGraph.GetParseHistorySearchText(activeTab));
        if searchActive and #points == 0 then
            emptyText = "No parses match that search.";
        end
    end
    points = ParseGraph.SortParseHistoryPoints(points);
    if ParseGraph.ParseHistoryCountLabel ~= nil then
        ParseGraph.ParseHistoryCountLabel:SetText(countText);
    end

    if #points == 0 then
        local emptyY = math.floor((ParseGraph.ParseHistoryListPanel:GetHeight() - 40) / 2);
        local empty = Label(ParseGraph.ParseHistoryListPanel, 0, emptyY, ParseGraph.ParseHistoryListPanel:GetWidth(), 40, emptyText, "big");
        empty:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        return;
    end

    local listH = ParseGraph.ParseHistoryListPanel:GetHeight();
    local list = Turbine.UI.ListBox();
    list:SetParent(ParseGraph.ParseHistoryListPanel);
    list:SetPosition(10, 0);
    list:SetSize(800, listH);
    list:SetOrientation(Turbine.UI.Orientation.Vertical);
    list:SetBackColor(Turbine.UI.Color(1.00, 0, 0, 0));
    pcall(function()
        list:SetClipMode(true);
    end);

    local scroll = Turbine.UI.Lotro.ScrollBar();
    scroll:SetParent(ParseGraph.ParseHistoryListPanel);
    scroll:SetOrientation(Turbine.UI.Orientation.Vertical);
    scroll:SetPosition(818, 0);
    scroll:SetSize(12, listH);
    list:SetVerticalScrollBar(scroll);
    ParseGraph.ParseHistoryScrollBar = scroll;
    scroll.ValueChanged = function()
        ParseGraph.UpdateParseHistoryCardIcons();
    end
    ParseGraph.AttachParseHistoryWheel(list);

    ParseGraph.ParseHistoryListBox = list;
    pcall(function()
        list:SetWantsUpdates(true);
    end);
    list.Update = function(sender)
        if ParseGraph.ParseHistoryListBox == sender then
            ParseGraph.UpdateParseHistoryCardIcons();
        end
    end
    list.MouseWheel = function(sender, args)
        ParseGraph.ScrollParseHistoryListByWheel(args);
    end

    local rowH = 126;
    scroll:SetVisible((#points * rowH) > listH);
    for i = 1, #points do
        local row = Turbine.UI.Control();
        row:SetSize(list:GetWidth(), rowH);
        row:SetMouseVisible(true);
        pcall(function()
            row:SetClipMode(true);
        end);
        ParseGraph.AttachParseHistoryWheel(row);
        DrawParseHistoryCard(row, 0, 0, 790, 116, points[i], border, listH, i, rowH, scroll);
        list:AddItem(row);
    end
    ParseGraph.UpdateParseHistoryCardIcons();
end

function ParseGraph.BuildParseHistoryView(parent)
