    ParseGraph.ParseHistoryListPanel = Panel(view, 20, 146, 840, 527, 1.00);
    ParseGraph.ParseHistoryListPanel:SetZOrder(1);
    pcall(function()
        ParseGraph.ParseHistoryListPanel:SetClipMode(true);
