function ParseGraph.UpdateStopButton()
    local isRunning = ParseGraph.ActiveParse ~= nil;
    if ParseGraph.ParseRunningPanel ~= nil then
        ParseGraph.ParseRunningPanel:SetVisible(isRunning);
        if isRunning and ParseGraph.ParseRunningPanel.SetZOrder ~= nil then
            ParseGraph.ParseRunningPanel:SetZOrder(80);
        end
    end
    if ParseGraph.ParseRunningLabel ~= nil then
        ParseGraph.ParseRunningLabel:SetVisible(isRunning);
    end
    if ParseGraph.StopButton ~= nil then
        ParseGraph.StopButton:SetVisible(isRunning);
    end
    ParseGraph.SetLauncherButtonState();
end

function ParseGraph.DiscardActiveParse(showWindow, reason)
    if ParseGraph.ActiveParse == nil then
        return false;
    end

    ParseGraph.ActiveParse = nil;
    ParseGraph.PendingCombatDummyStartTime = 0;
    ParseGraph.StopPreParseCombatCapture();
    ParseGraph.SessionDiscardCount = (tonumber(ParseGraph.SessionDiscardCount) or 0) + 1;
    if type(ParseGraph.CharacterStats) ~= "table" then
        ParseGraph.CharacterStats = {};
    end
    ParseGraph.CharacterStats.discardedRunningParses = (tonumber(ParseGraph.CharacterStats.discardedRunningParses) or 0) + 1;
    ParseGraph.PendingStartTime = 0;
    ParseGraph.StopStartConfirmTimer();
    ParseGraph.StopCombatDummyParseTimer();
    if showWindow == true then
        ParseGraph.ShowWindowAfterParse(true, true);
    else
        ParseGraph.StopParseVisibilityTimer();
        ParseGraph.AutoHideForParse = false;
        ParseGraph.AutoHideWasVisible = false;
        ParseGraph.AutoHideSawCombat = false;
    end
    ParseGraph.UpdateStopButton();
    ParseGraph.UpdatePostButtonWindowPositions();
    ParseGraph.PrintParseDiscarded(reason);
    ParseGraph.SyncAchievements(true);
    ParseGraph.Save();
    ParseGraph.Refresh();
    ParseGraph.SetLauncherButtonState();
    return true;
end


local function Clamp(v, lo, hi)
    if v < lo then return lo end
    if v > hi then return hi end
    return v
end

local function DrawPoint(parent, x, y, size, color)
    return DrawBlock(parent, x - math.floor(size / 2), y - math.floor(size / 2), size, size, color);
end

local function DrawCircleMarker(parent, x, y, size, color)
    local radius = math.max(3, math.floor(size / 2));
    for dy = -radius, radius do
        local width = math.floor(math.sqrt((radius * radius) - (dy * dy)) * 2) + 1;
        DrawBlock(parent, x - math.floor(width / 2), y + dy, width, 1, color);
    end
end

local function DrawImageMarker(parent, x, y, size, image)
    if image == nil or tostring(image) == "" then
        return nil;
    end

    local marker = Turbine.UI.Control();
    marker:SetParent(parent);
    marker:SetPosition(math.floor(x - (size / 2)), math.floor(y - (size / 2)));
    marker:SetSize(size, size);
    local ok = pcall(function()
        marker:SetBackground(tostring(image));
    end);
    if not ok then
        marker:SetParent(nil);
        return nil;
    end
    marker:SetMouseVisible(false);
    return marker;
end

local function DrawLine(parent, x1, y1, x2, y2, size, color)
    local dx = x2 - x1;
    local dy = y2 - y1;
    local distance = math.max(math.abs(dx), math.abs(dy));

    if distance < 1 then
        DrawPoint(parent, x1, y1, size, color);
        return;
    end

    -- Performance note:
    -- Older versions drew one tiny UI control per pixel of line. In LOTRO's Lua UI,
    -- that can become hundreds/thousands of controls and cause FPS stutter.
    -- This samples the line every ~6 pixels instead, which is visually close enough
    -- but much lighter.
    local steps = math.max(1, math.ceil(distance / 6));

    for i = 0, steps do
        local t = i / steps;
        local x = x1 + dx * t;
        local y = y1 + dy * t;
        DrawPoint(parent, x, y, size, color);
    end
end

function ParseGraph.AddAllTimeAverageValues(points)
    local pointByIndex = {};
    for i = 1, #points do
        pointByIndex[points[i].index] = points[i];
    end

    local total = 0;
    local count = 0;
    local parses = points.sourceParses or ParseGraph.GetViewParses();

    -- Build the average from parse #1, even if the graph is filtered by time/session.
    -- The spec filter still applies so the average line matches the selected spec.
    for i = 1, #parses do
        if ParseGraph.ParseMatchesSpecFilter(parses[i]) then
            total = total + (tonumber(parses[i].final) or 0);
            count = count + 1;
            if pointByIndex[i] ~= nil and count > 0 then
                pointByIndex[i].avg = total / count;
            end
        end
    end
end

local function CreateSmallLabel(parent, x, y, w, h, text, rightAlign, font)
    local l = Turbine.UI.Label();
    l:SetParent(parent);
    l:SetPosition(x, y);
    l:SetSize(w, h);
    l:SetFont(font or Turbine.UI.Lotro.Font.TrajanPro13);
    l:SetForeColor(Turbine.UI.Color(0.85, 0.84, 0.84, 0.84));
    l:SetText(text or "");
    if rightAlign then
        l:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
    else
        l:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleLeft);
    end
    return l;
end

