function ParseGraph.HideGraphPointTooltip()
    if ParseGraph.GraphPointTooltip ~= nil then
        ParseGraph.GraphPointTooltip:SetVisible(false);
    end
end

local function ResetGraphPointTooltip()
    ParseGraph.HideGraphPointTooltip();
    ParseGraph.GraphPointTooltip = nil;
    ParseGraph.GraphPointTooltipParent = nil;
end

function ParseGraph.ShowGraphPointTooltip(parent, point, dotX, dotY)
    if parent == nil or point == nil or point.parse == nil then
        return;
    end

    local width = 136;
    local height = 94;
    local border = Turbine.UI.Color(1, 0.94, 0.64, 0.06);
    local labelColor = Turbine.UI.Color(1.00, 1.00, 0.62, 0.12);
    local valueColor = Turbine.UI.Color(1.00, 1.00, 1.00, 1.00);
    local finalParseColor = Turbine.UI.Color(1.00, 0.45, 0.78, 1.00);

    if ParseGraph.GraphPointTooltip == nil or ParseGraph.GraphPointTooltipParent ~= parent then
        local tip = Turbine.UI.Control();
        tip:SetParent(parent);
        tip:SetSize(width, height);
        tip:SetBackColor(Turbine.UI.Color(0.98, 0.01, 0.01, 0.01));
        tip:SetMouseVisible(false);
        tip:SetZOrder(1000);

        tip.topBorder = DrawBlock(tip, 0, 0, width, 1, border);
        tip.bottomBorder = DrawBlock(tip, 0, height - 1, width, 1, border);
        tip.leftBorder = DrawBlock(tip, 0, 0, 1, height, border);
        tip.rightBorder = DrawBlock(tip, width - 1, 0, 1, height, border);
        tip.labelRows = {};
        tip.valueRows = {};

        local labels = { "Minute 1:", "Minute 2:", "Minute 3:", "Final DPS:" };
        for i = 1, #labels do
            local rowY = 8 + ((i - 1) * 21);
            local label = Label(tip, 10, rowY, 74, 20, labels[i], "achievementDetail");
            label:SetFont(Turbine.UI.Lotro.Font.TrajanPro14);
            label:SetForeColor(labelColor);
            label:SetZOrder(1005);

            local value = Label(tip, 64, rowY, 62, 20, "", "achievementDetail");
            value:SetFont(Turbine.UI.Lotro.Font.TrajanPro14);
            value:SetForeColor(i == 4 and finalParseColor or valueColor);
            value:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleRight);
            value:SetZOrder(1005);

            tip.labelRows[i] = label;
            tip.valueRows[i] = value;
        end

        ParseGraph.GraphPointTooltip = tip;
        ParseGraph.GraphPointTooltipParent = parent;
    end

    local parse = point.parse;
    local minutes = parse.minutes or {};
    local minuteAverages = (ParseGraph.GetParseComparisonStats(nil, parse).averageMinutes or {});
    ParseGraph.GraphPointTooltip.valueRows[1]:SetText(ParseGraph.FormatSummaryNumber(minutes[1]));
    ParseGraph.GraphPointTooltip.valueRows[2]:SetText(ParseGraph.FormatSummaryNumber(minutes[2]));
    ParseGraph.GraphPointTooltip.valueRows[3]:SetText(ParseGraph.FormatSummaryNumber(minutes[3]));
    ParseGraph.GraphPointTooltip.valueRows[4]:SetText(ParseGraph.FormatSummaryNumber(parse.final));
    ParseGraph.GraphPointTooltip.valueRows[1]:SetForeColor(ParseGraph.GetMinuteSummaryUiColorForParse(point or parse, minutes[1], minuteAverages[1], valueColor));
    ParseGraph.GraphPointTooltip.valueRows[2]:SetForeColor(ParseGraph.GetMinuteSummaryUiColorForParse(point or parse, minutes[2], minuteAverages[2], valueColor));
    ParseGraph.GraphPointTooltip.valueRows[3]:SetForeColor(ParseGraph.GetMinuteSummaryUiColorForParse(point or parse, minutes[3], minuteAverages[3], valueColor));
    ParseGraph.GraphPointTooltip.valueRows[4]:SetForeColor(finalParseColor);

    local parentW = tonumber(parent:GetWidth()) or 0;
    local parentH = tonumber(parent:GetHeight()) or 0;
    local x = math.floor((tonumber(dotX) or 0) + 14);
    local y = math.floor((tonumber(dotY) or 0) - height - 12);
    if x + width > parentW then
        x = math.floor((tonumber(dotX) or 0) - width - 14);
    end
    if x < 0 then x = 0 end
    if y < 0 then
        y = math.floor((tonumber(dotY) or 0) + 14);
    end
    if y + height > parentH then
        y = math.max(0, parentH - height);
    end

    ParseGraph.GraphPointTooltip:SetPosition(x, y);
    ParseGraph.GraphPointTooltip:SetVisible(true);
end

local function BindGraphPointTooltip(control, parent, point, dotX, dotY)
    if control == nil or point == nil then
        return;
    end

    pcall(function()
        control:SetMouseVisible(true);
    end);
    control.MouseEnter = function()
        ParseGraph.ShowGraphPointTooltip(parent, point, dotX, dotY);
    end
    control.MouseLeave = function()
        ParseGraph.HideGraphPointTooltip();
    end
end

function ParseGraph.DrawTrendGraph()
    ResetGraphPointTooltip();
    ClearChildren(ParseGraph.GraphPanel);

    local mode = NormalizeShowMode(ParseGraph.ShowMode);
    local graphParses = mode == "session" and (ParseGraph.Parses or {}) or ParseGraph.GetViewParses();
    if #graphParses == 0 then
        CreateSmallLabel(ParseGraph.GraphPanel, 10, 10, 400, 20, "No saved parses yet.", false);
        return;
    end

    local panel = ParseGraph.GraphPanel;
    local graphW = panel:GetWidth();
    local graphH = panel:GetHeight();
    local marginL, marginR, marginT, marginB = 64, 14, 20, 24;
    local plotX, plotY = marginL, marginT;
    local plotW = graphW - marginL - marginR;
    local plotH = graphH - marginT - marginB;

    DrawBlock(panel, 0, 0, graphW, graphH, Turbine.UI.Color(1.00, 0.02, 0.02, 0.03));

    local maxShown = 100;
    local points = ParseGraph.GetDisplayedParsePoints(maxShown, graphParses);
    local shown = #points;
    ParseGraph.AddAllTimeAverageValues(points);

    if shown == 0 then
        local message = "No parses match the current filter.";
        local mode = NormalizeShowMode(ParseGraph.ShowMode);
        if mode == "session" then
            message = "No parses saved this session.";
        elseif mode == "today" then
            message = "No parses saved for today.";
        end
        CreateSmallLabel(panel, 10, 10, 400, 20, message, false);
        return;
    end

    local minVal = nil;
    local maxVal = nil;
    for i = 1, shown do
        local v = tonumber(points[i].parse.final) or 0;
        if minVal == nil or v < minVal then minVal = v end
        if maxVal == nil or v > maxVal then maxVal = v end
        local mv = points[i].avg;
        if mv ~= nil then
            if minVal == nil or mv < minVal then minVal = mv end
            if maxVal == nil or mv > maxVal then maxVal = mv end
        end
    end

    -- Keep the Y-axis readable for Snowman parses.
    -- The lower bound can be selected in the dropdown below the graph.
    local tickStep = 10000;
    minVal = tonumber(ParseGraph.GraphMin) or 100000;
    maxVal = maxVal or minVal + tickStep;
    if maxVal < minVal + tickStep then
        maxVal = minVal + tickStep;
    end
    maxVal = math.ceil(maxVal / tickStep) * tickStep;

    local function ToY(v)
        local ratio = (v - minVal) / (maxVal - minVal);
        ratio = Clamp(ratio, 0, 1);
        return plotY + plotH - ratio * plotH;
    end

    local function ToX(pointIndex)
        if shown <= 1 then return plotX + plotW / 2 end
        local pos = (pointIndex - 1) / (shown - 1);
        return plotX + pos * plotW;
    end

    local gridColor = Turbine.UI.Color(1.00, 0.24, 0.24, 0.24);
    local axisColor = Turbine.UI.Color(1.00, 0.42, 0.42, 0.42);
    local parseColor = Turbine.UI.Color(0.95, 0.18, 0.55, 0.90);
    local avgColor = Turbine.UI.Color(0.95, 0.96, 0.50, 0.16);
    local pbColor = Turbine.UI.Color(1.00, 1.00, 0.82, 0.16);
    local personalBestValue = tonumber(ParseGraph.GetAllTimeStats().best);
    local personalBestPointIndex = nil;
    if personalBestValue ~= nil then
        local roundedBest = Round(personalBestValue);
        for i = 1, shown do
            local value = tonumber(points[i].parse and points[i].parse.final);
            if value ~= nil and Round(value) == roundedBest then
                personalBestPointIndex = i;
            end
        end
    end

    DrawBlock(panel, plotX, plotY + plotH, plotW, 1, axisColor);
    DrawBlock(panel, plotX, plotY, 1, plotH, axisColor);

    local tickValue = minVal;
    while tickValue <= maxVal do
        local y = ToY(tickValue);
        DrawBlock(panel, plotX, y, plotW, 1, gridColor);
        CreateSmallLabel(panel, 2, y - 8, marginL - 8, 16, FormatNumber(tickValue), true);
        tickValue = tickValue + tickStep;
    end

    -- Draw a vertical guide line for every visible parse.
    -- Older versions only drew 5 x-axis guide lines, which made parse numbers like
    -- 2, 4, and 7 look missing when only a few parses were shown.
    local labelEvery = 1;
    if shown > 45 then
        labelEvery = 10;
    elseif shown > 25 then
        labelEvery = 5;
    elseif shown > 14 then
        labelEvery = 2;
    end

    for pointIndex = 1, shown do
        local x = ToX(pointIndex);
        DrawBlock(panel, x, plotY, 1, plotH, Turbine.UI.Color(1.00, 0.24, 0.24, 0.24));

        if ((pointIndex - 1) % labelEvery == 0) or pointIndex == shown then
            local tickLabel = CreateSmallLabel(panel, x - 16, plotY + plotH + 3, 32, 16, tostring(points[pointIndex].index), false);
            tickLabel:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
        end
    end

    -- Draw all-time average first so the parse line sits on top.
    for i = 2, shown do
        local prev = points[i - 1].avg;
        local cur = points[i].avg;
        if prev ~= nil and cur ~= nil then
            DrawLine(panel, ToX(i - 1), ToY(prev), ToX(i), ToY(cur), 2, avgColor);
        end
    end

    for i = 2, shown do
        local prev = tonumber(points[i - 1].parse.final) or 0;
        local cur = tonumber(points[i].parse.final) or 0;
        DrawLine(panel, ToX(i - 1), ToY(prev), ToX(i), ToY(cur), 2, parseColor);
    end

    for i = 1, shown do
        local cur = tonumber(points[i].parse.final) or 0;
        DrawImageMarker(panel, ToX(i), ToY(cur), 5, (ParseGraph.GraphIconPath or "") .. "graph_dot.tga");
    end

    for i = 1, shown do
        if personalBestPointIndex ~= nil and i == personalBestPointIndex then
            local cur = tonumber(points[i].parse.final) or 0;
            local x = ToX(i);
            local y = ToY(cur);
            DrawImageMarker(panel, x, y, 7, (ParseGraph.GraphIconPath or "") .. "personal_best_star.tga");
            break;
        end
    end

    for i = 1, shown do
        local cur = tonumber(points[i].parse.final) or 0;
        local x = ToX(i);
        local y = ToY(cur);
        local hitSize = shown > 80 and 10 or 14;
        local hit = Turbine.UI.Control();
        hit:SetParent(panel);
        hit:SetPosition(math.floor(x - (hitSize / 2)), math.floor(y - (hitSize / 2)));
        hit:SetSize(hitSize, hitSize);
        hit:SetZOrder(900);
        hit:SetMouseVisible(true);
        BindGraphPointTooltip(hit, panel, points[i], x, y);
    end
end

function ParseGraph.DrawSavedParseList()
    ParseGraph.ClearPostButtonWindows();
    ParseGraph.RefreshSessionPostButton();
    ParseGraph.RefreshSummaryPostButton();
    ClearChildren(ParseGraph.ListPanel);

    local panel = ParseGraph.ListPanel;
    local w = panel:GetWidth();
    local headerColor = Turbine.UI.Color(1.00, 0.93, 0.76, 0.28);
    local rowColor = Turbine.UI.Color(0.95, 0.92, 0.88, 0.82);
    local parseColor = Turbine.UI.Color(1.00, 0.45, 0.78, 1.00);
    local lineColor = Turbine.UI.Color(1.00, 0.95, 0.56, 0.12);
    local tableFont = Turbine.UI.Lotro.Font.TrajanPro14;
    local headerLineY = 26;
    local rowHeight = 27;
    local rowLabelHeight = 22;
    local buttonHeight = 20;
    local currentKey = ParseGraph.GetCurrentCharacterKey();

    DrawBlock(panel, 15, headerLineY, w - 30, 1, lineColor);

    local headers = {
        { x = 15, w = 42, text = "#" },
        { x = 60, w = 38, text = "Spec" },
        { x = 100, w = 125, text = "Date / Time" },
        { x = 230, w = 80, text = "1st minute", rightAlign = true },
        { x = 320, w = 90, text = "2nd minute", rightAlign = true },
        { x = 420, w = 90, text = "3rd minute", rightAlign = true },
        { x = 520, w = 85, text = "Final parse", rightAlign = true }
    };

    for i = 1, #headers do
        local h = headers[i];
        local label = CreateSmallLabel(panel, h.x, 2, h.w, rowLabelHeight, h.text, h.rightAlign, tableFont);
        label:SetForeColor(headerColor);
    end
    local actionHeader = CreateSmallLabel(panel, 645, 2, 220, rowLabelHeight, "Actions", false, tableFont);
    actionHeader:SetTextAlignment(Turbine.UI.ContentAlignment.MiddleCenter);
    actionHeader:SetForeColor(headerColor);

    local mode = NormalizeShowMode(ParseGraph.ShowMode);
    local listParses = mode == "session" and (ParseGraph.Parses or {}) or ParseGraph.GetViewParses();
    if #listParses == 0 then
        Label(panel, 20, 34, 500, 20, "No saved parses yet.", "small");
        return;
    end

    local points = ParseGraph.GetDisplayedParsePoints(3);
    if #points == 0 then
        local message = "No parses match the current filter.";
        local mode = NormalizeShowMode(ParseGraph.ShowMode);
        if mode == "session" then
            message = "No parses saved this session.";
        elseif mode == "today" then
            message = "No parses saved for today.";
        end
        Label(panel, 20, 34, 500, 20, message, "small");
        return;
    end

    local y = headerLineY + 1;
    for pointIndex = #points, 1, -1 do
        local p = points[pointIndex].parse;
        local parseIndex = points[pointIndex].index;
        local sourceKey = tostring(p.__sourceKey or (mode == "session" and currentKey or ParseGraph.ViewCharacterKey) or currentKey);
        local sourceIndex = tonumber(p.__sourceIndex or parseIndex) or parseIndex;
        local sourceName = tostring(p.__sourceName or ParseGraph.GetCharacterDisplayName(sourceKey));
        local rowPoint = {
            parse = p,
            index = parseIndex,
            sourceKey = sourceKey,
            sourceIndex = sourceIndex,
            sourceName = sourceName,
            returnView = "main"
        };
        local canDeleteRow = sourceKey == currentKey and ParseGraph.IsViewingCurrentCharacter();
        local textY = y + math.floor((rowHeight - rowLabelHeight) / 2);
        local buttonY = y + math.floor((rowHeight - buttonHeight) / 2);
        local minuteAverages = (ParseGraph.GetParseComparisonStats(nil, p).averageMinutes or {});
        local rowHighlight = DrawBlock(panel, 15, y + 1, 625, rowHeight - 1, ParseGraph.ParseRowNormalFill);
        rowHighlight:SetMouseVisible(false);
        DrawBlock(panel, 15, y + rowHeight, w - 30, 1, lineColor);

        CreateSmallLabel(panel, 15, textY, 42, rowLabelHeight, "#" .. tostring(parseIndex), false, tableFont):SetForeColor(rowColor);
        local specSlot = ParseGraph.DrawParseSpecSelector(panel, 70, y + math.floor((rowHeight - 18) / 2), 18, rowPoint, rowHighlight);
        CreateSmallLabel(panel, 100, textY, 125, rowLabelHeight, tostring(p.time or ""), false, tableFont):SetForeColor(rowColor);
        CreateSmallLabel(panel, 230, textY, 80, rowLabelHeight, ParseGraph.FormatSummaryNumber(p.minutes and p.minutes[1]), true, tableFont):SetForeColor(ParseGraph.GetMinuteSummaryUiColorForParse(p, p.minutes and p.minutes[1], minuteAverages[1], rowColor));
        CreateSmallLabel(panel, 320, textY, 90, rowLabelHeight, ParseGraph.FormatSummaryNumber(p.minutes and p.minutes[2]), true, tableFont):SetForeColor(ParseGraph.GetMinuteSummaryUiColorForParse(p, p.minutes and p.minutes[2], minuteAverages[2], rowColor));
        CreateSmallLabel(panel, 420, textY, 90, rowLabelHeight, ParseGraph.FormatSummaryNumber(p.minutes and p.minutes[3]), true, tableFont):SetForeColor(ParseGraph.GetMinuteSummaryUiColorForParse(p, p.minutes and p.minutes[3], minuteAverages[3], rowColor));
        CreateSmallLabel(panel, 520, textY, 85, rowLabelHeight, FormatNumber(p.final), true, tableFont):SetForeColor(parseColor);

        local rowClick = Turbine.UI.Control();
        rowClick:SetParent(panel);
        rowClick:SetPosition(15, y);
        rowClick:SetSize(625, rowHeight);
        rowClick:SetMouseVisible(true);
        rowClick:SetZOrder(80);
        rowClick.parsePoint = rowPoint;
        rowClick.highlight = rowHighlight;
        rowClick.specSlot = specSlot;
        rowClick.MouseEnter = function(sender)
            sender.highlight:SetBackColor(ParseGraph.ParseRowHoverFill);
            ParseGraph.ApplyParseSpecSlotState(sender.specSlot, true);
        end
        rowClick.MouseLeave = function(sender)
            sender.highlight:SetBackColor(ParseGraph.ParseRowNormalFill);
            ParseGraph.ApplyParseSpecSlotState(sender.specSlot, false);
        end
        rowClick.MouseClick = function(sender)
            ParseGraph.OpenParseDetail(sender.parsePoint, "main");
        end

        local sharePoint = {
            parse = p,
            index = parseIndex,
            sourceKey = sourceKey,
            sourceIndex = sourceIndex,
            sourceName = sourceName,
            returnView = "main"
        };
        local compareCheckbox = DrawParseCompareCheckbox(panel, 654, buttonY - 1, sharePoint, true, false, true);
        local compareTooltipParent = ParseGraph.MainView or panel;
        local compareTooltipX = 535;
        local compareTooltipY = y + 519;
        if compareTooltipParent == panel then
            compareTooltipX = 520;
            compareTooltipY = math.max(0, y - 86);
        end
        BindParseDetailTooltip(compareCheckbox, compareTooltipParent, "Compare", "Tick this checkbox to compare this parse", compareTooltipX, compareTooltipY);

        local share = ParseGraph.CreateRowButton(panel, 682, buttonY, 58, buttonHeight, "Share", "row_post_button", function(sender)
            ParseGraph.ShareParsePoint(sender.parsePoint);
        end);
        share.parsePoint = sharePoint;
        share:SetZOrder(120);

        ParseGraph.CreatePostButton(panel, p, 744, buttonY, 58, buttonHeight, nil, "main", parseIndex);

        if canDeleteRow then
            local del = ParseGraph.CreateRowButton(panel, 806, buttonY, 60, buttonHeight, "Delete", "row_delete_button", function(sender)
                ParseGraph.DeleteParseBySource(sender.sourceKey, sender.sourceIndex);
            end);
            del.index = parseIndex;
            del.sourceKey = sourceKey;
            del.sourceIndex = sourceIndex;
        end
        y = y + rowHeight;
    end
end

function ParseGraph.Refresh()
    if ParseGraph.Window == nil then return end
    ParseGraph.UpdateStopButton();
    ParseGraph.UpdateGraphMinDropdownText();
    ParseGraph.UpdateParseSpecFilterButtonText();
    ParseGraph.UpdateShowModeButtons();
    ParseGraph.UpdateSidebarNavButtons();
    ParseGraph.UpdatePostChannelButtons();
    ParseGraph.UpdateCharacterDropdownText();
    ParseGraph.UpdateStartMinimizedCheckbox();
    ParseGraph.UpdateCombineSameClassCheckbox();
    ParseGraph.UpdateShowLauncherButtonCheckbox();
    ParseGraph.UpdateShowLauncherTimerCheckbox();
    ParseGraph.UpdateOpenAfterFinishedParseCheckbox();
    ParseGraph.UpdateBossHealthPercentMessagesCheckbox();
    ParseGraph.UpdateOnlySaveInstanceParsesOnKillCheckbox();
    ParseGraph.UpdateScoreboardRecapMessagesCheckbox();
    ParseGraph.UpdateAutoStripOldParseDetailsCheckbox();
    ParseGraph.UpdateLauncherSizeControls();
    ParseGraph.UpdateDeleteButtons();
    ParseGraph.UpdateSummaryStats();
    ParseGraph.DrawTrendGraph();
    ParseGraph.DrawSavedParseList();
    if ParseGraph.CurrentView == "achievements" then
        ParseGraph.DrawAchievementsView();
    elseif ParseGraph.CurrentView == "instances" then
        ParseGraph.DrawInstancesView();
    elseif ParseGraph.CurrentView == "characters" then
        ParseGraph.DrawCharactersView();
    elseif ParseGraph.CurrentView == "settings" then
        ParseGraph.UpdateStartMinimizedCheckbox();
        ParseGraph.UpdateCombineSameClassCheckbox();
        ParseGraph.UpdateShowLauncherButtonCheckbox();
        ParseGraph.UpdateShowLauncherTimerCheckbox();
        ParseGraph.UpdateOpenAfterFinishedParseCheckbox();
        ParseGraph.UpdateBossHealthPercentMessagesCheckbox();
        ParseGraph.UpdateOnlySaveInstanceParsesOnKillCheckbox();
        ParseGraph.UpdateScoreboardRecapMessagesCheckbox();
        ParseGraph.UpdateAutoStripOldParseDetailsCheckbox();
        ParseGraph.UpdateLauncherSizeControls();
    elseif ParseGraph.CurrentView == "history" then
        ParseGraph.DrawParseHistoryView();
    end
end

function ParseGraph.StartParse(dummyKey, source)
    if ParseGraph.IsDummyParsingPaused() then
        return;
    end
    local now = Turbine.Engine.GetGameTime();
    dummyKey = tostring(dummyKey or "regular");
    if dummyKey ~= "snowman" and dummyKey ~= "warg" and dummyKey ~= "regular" then
        dummyKey = "regular";
    end
    source = tostring(source or "say");
    if source ~= "combat" then
        source = "say";
    end

    ParseGraph.PendingCombatDummyStartTime = 0;
    ParseGraph.StopCombatDummyParseTimer();

    if now < (tonumber(ParseGraph.PostFinalCooldownUntil) or 0) then
        ParseGraph.PendingStartTime = 0;
        ParseGraph.StopPreParseCombatCapture();
        if ParseGraph.Debug then
            Turbine.Shell.WriteLine("ParseGraph: start line ignored during post-final cooldown.");
        end
        return;
    end

    ParseGraph.SwitchToCurrentCharacterForParse();

    -- A new dummy start line means the dummy has started a fresh parse.
    -- If another parse was already running, scrap that unfinished parse instead of
    -- letting timeout/despawn weirdness corrupt the next result.
    local wasRunning = ParseGraph.ActiveParse ~= nil;
    local confirmedByRecentHit = ParseGraph.HasPreStartConfirmHit(now);
    local confirmedByCombat = ParseGraph.IsPlayerInCombat();
    local startsConfirmed = confirmedByRecentHit or confirmedByCombat;
    local preParseCombat = ParseGraph.PreParseCombat;
    local combatSummary = nil;
    local combatStart = now;
    if type(preParseCombat) == "table" and type(preParseCombat.combat) == "table" then
        local preCombat = preParseCombat.combat;
        if (tonumber(preCombat.attacks) or 0) > 0 or (tonumber(preCombat.benefitCount) or 0) > 0 then
            combatSummary = preCombat;
            combatStart = tonumber(preParseCombat.start) or now;
        end
    end
    ParseGraph.StopPreParseCombatCapture();

    ParseGraph.ActiveParse = {
        start = now,
        combatStart = combatStart,
        minutes = {},
        minuteCount = 0,
        dummyKey = dummyKey,
        source = source,
        confirmed = startsConfirmed,
        confirmDeadline = startsConfirmed and nil or (now + ParseGraph.StartConfirmWindowSeconds),
        startedAnnounced = true,
        combat = combatSummary or ParseGraph.NewParseCombatSummary()
    };
    ParseGraph.PendingStartTime = now;
    ParseGraph.LastStartTime = now;
    ParseGraph.StopStartConfirmTimer();
    if startsConfirmed then
        ParseGraph.PendingStartTime = 0;
        if source ~= "combat" then
            ParseGraph.HideWindowForParse();
        end
    else
        ParseGraph.EnsureStartConfirmTimer();
    end

    if wasRunning then
        ParseGraph.PrintParseMessage({ { text = " Unfinished parse scrapped; new parse started.", color = "FFFFFF" } });
    else
        ParseGraph.PrintParseStarted();
    end

    -- Avoid rebuilding the chart while combat/parsing is happening.
    -- The saved parse result will refresh the graph when the parse finishes.
    ParseGraph.UpdateStopButton();
    ParseGraph.SetLauncherButtonState();

end

function ParseGraph.RecordMinute(value)
    if ParseGraph.ActiveParse == nil then
        -- Never start a parse from the minute line. Kinship/fellowship/raid chat can quote
        -- the dummy text, so a valid parse must always begin with the dummy intro line
        -- in /say first.
        return;
    end
    local now = Turbine.Engine.GetGameTime();
    local elapsed = now - (tonumber(ParseGraph.ActiveParse.start) or now);
    local n = ParseGraph.ActiveParse.minuteCount + 1;
    local minimumElapsed = (n * 60) - ParseGraph.MinuteLineEarlyGraceSeconds;
    if n <= 3 and elapsed < minimumElapsed then
        if ParseGraph.Debug then
            Turbine.Shell.WriteLine("ParseGraph: early minute " .. tostring(n) .. " line ignored after fresh start: " .. FormatNumber(value));
        end
        return;
    end
    if n <= 3 then
        ParseGraph.ActiveParse.minuteCount = n;
        ParseGraph.ActiveParse.minutes[n] = value;
        ParseGraph.PrintParseMinute(n, value);
    else
        ParseGraph.PrintParseMessage({
            { text = " Extra minute line ignored: " .. FormatNumber(value), color = "FFFFFF" }
        });
    end

    -- Do not rebuild the chart for each minute tick; wait until the final parse is saved.
    ParseGraph.UpdateStopButton();

end

function ParseGraph.FinishParse(value)
    local now = Turbine.Engine.GetGameTime();

    if ParseGraph.ActiveParse == nil then
        -- Do not save final dummy text unless the matching intro line started a parse.
        return;
    end
    if not ParseGraph.IsActiveParseConfirmed(now) then
        ParseGraph.ActiveParse = nil;
        ParseGraph.PendingCombatDummyStartTime = 0;
        ParseGraph.StopPreParseCombatCapture();
        ParseGraph.PendingStartTime = 0;
        ParseGraph.StopStartConfirmTimer();
        ParseGraph.StopCombatDummyParseTimer();
        ParseGraph.UpdateStopButton();
        ParseGraph.StopParseVisibilityTimer();
        ParseGraph.AutoHideForParse = false;
        ParseGraph.AutoHideWasVisible = false;
        ParseGraph.AutoHideSawCombat = false;
        ParseGraph.UpdatePostButtonWindowPositions();
        ParseGraph.PrintParseDiscarded("no player dummy hit was detected.");
        ParseGraph.Refresh();
        return;
    end

    if ParseGraph.ViewCharacterKey ~= ParseGraph.GetCurrentCharacterKey() then
        ParseGraph.SelectCharacter(ParseGraph.GetCurrentCharacterKey(), true);
    end

    -- Guard against the final Snowman line being delivered twice.
    if ParseGraph.LastFinalValue ~= nil and math.abs((tonumber(value) or 0) - (tonumber(ParseGraph.LastFinalValue) or 0)) < 0.001 and (now - ParseGraph.LastFinalTime) < 5 then
        ParseGraph.PrintParseMessage({
            { text = " Duplicate final parse ignored: " .. FormatNumber(value), color = "FFFFFF" }
        });
        ParseGraph.Refresh();
        return;
    end

    local minutes = {};
    if ParseGraph.ActiveParse ~= nil and ParseGraph.ActiveParse.minutes ~= nil then
        minutes = ParseGraph.ActiveParse.minutes;
    end

    local previousBest = ParseGraph.GetHighestParse();
    local previousStats = ParseGraph.GetAllTimeStats(true);
    local finalValue = tonumber(value) or 0;
    local personalBestGain = finalValue - previousBest;

    local detectedSpecKey = ParseGraph.GetCurrentDetectedSpecKey();
    local savedParse = {
        time = NowText(),
        final = value,
        minutes = { minutes[1], minutes[2], minutes[3] },
        combat = ParseGraph.BuildSavedParseCombatSummary(ParseGraph.ActiveParse)
    };
    if detectedSpecKey ~= nil then
        savedParse.specKey = detectedSpecKey;
    end
    table.insert(ParseGraph.Parses, savedParse);
    local savedParseIndex = #ParseGraph.Parses;
    ParseGraph.ActiveParse = nil;
    ParseGraph.PendingCombatDummyStartTime = 0;
    ParseGraph.StopPreParseCombatCapture();
    ParseGraph.StopStartConfirmTimer();
    ParseGraph.StopCombatDummyParseTimer();
    ParseGraph.UpdateStopButton();
    ParseGraph.LastFinalValue = value;
    ParseGraph.LastFinalTime = now;
    ParseGraph.LastSavedParseIndex = savedParseIndex;
    ParseGraph.LastSavedParseTime = now;
    ParseGraph.PostFinalCooldownUntil = now + ParseGraph.PostFinalCooldownSeconds;
    ParseGraph.SyncAchievements(true);
    ParseGraph.Save();
    ParseGraph.SetLastLauncherTarget({ view = "main", parseIndex = savedParseIndex });
    ParseGraph.ScheduleParseSummary(savedParse, savedParseIndex, previousStats);
    if ParseGraph.OpenAfterFinishedParse == true then
        ParseGraph.ShowWindowAfterParse(true, true);
    else
        ParseGraph.ShowWindowAfterParse(true, false, true);
    end
    if previousBest > 0 and personalBestGain > 0 then
        ParseGraph.ShowPersonalBestPopup(personalBestGain, finalValue);
    end
    ParseGraph.Refresh();
end

function ParseGraph.ProcessText(text)
    if text == nil then return end
    if ParseGraph.IsDummyParsingPaused() then return end
    text = tostring(text);

    -- Debounce exact duplicate chat payloads. This keeps repeated chat events from
    -- starting two parses, double-counting minute lines, or saving twice.
    local now = Turbine.Engine.GetGameTime();
    if ParseGraph.LastProcessedText == text and (now - ParseGraph.LastProcessedTime) < 1.25 then
        return;
    end
    ParseGraph.LastProcessedText = text;
    ParseGraph.LastProcessedTime = now;

    local lower = LowerClean(text);
    local relevant = false;
    if string.find(lower, "training snowman", 1, true) ~= nil then relevant = true end
    if string.find(lower, "dummy warg", 1, true) ~= nil then relevant = true end
    if string.find(lower, "ummy warg", 1, true) ~= nil then relevant = true end -- tolerate missing leading D in copied chat
    if string.find(lower, "dps target dummy", 1, true) ~= nil then relevant = true end
    if string.find(lower, "training-dummy", 1, true) ~= nil then relevant = true end
    if string.find(lower, "training dummy", 1, true) ~= nil then relevant = true end
    if string.find(lower, "light dummy", 1, true) ~= nil then relevant = true end
    if string.find(lower, "medium dummy", 1, true) ~= nil then relevant = true end
    if string.find(lower, "heavy dummy", 1, true) ~= nil then relevant = true end
    if string.find(lower, "merry yule", 1, true) ~= nil then relevant = true end
    if string.find(lower, "grargh", 1, true) ~= nil then relevant = true end
    if string.find(lower, "en guarde", 1, true) ~= nil then relevant = true end
    if string.find(lower, "dislodged roughly", 1, true) ~= nil then relevant = true end
    if string.find(lower, "struck me for", 1, true) ~= nil then relevant = true end
    if string.find(lower, "thy dps was", 1, true) ~= nil then relevant = true end
    if string.find(lower, "tempestuous rate", 1, true) ~= nil then relevant = true end
    if string.find(lower, "course of our battle", 1, true) ~= nil then relevant = true end
    if string.find(lower, "momentous conflict", 1, true) ~= nil then relevant = true end
    if string.find(lower, "have lost", 1, true) ~= nil then relevant = true end
    if string.find(lower, "awooo", 1, true) ~= nil then relevant = true end
    if string.find(lower, "entirety of our match", 1, true) ~= nil then relevant = true end
    if string.find(lower, "hath suffered", 1, true) ~= nil then relevant = true end

    if not relevant then return end

    ParseGraph.LastDummyLine = text;

    if IsStartLine(text) then
        ParseGraph.StartParse(GetDummyKeyFromText(text));
        return;
    end

    if IsMinuteLine(text) then
        local value = ParseNumberFromText(text);
        if value ~= nil then
            ParseGraph.RecordMinute(value);
        else
            Turbine.Shell.WriteLine("ParseGraph: minute line seen, but no number could be read.");
        end
        return;
    end

    if IsFinalLine(text) then
        local value = ParseNumberFromText(text);
        if value ~= nil then
            ParseGraph.FinishParse(value);
        else
            Turbine.Shell.WriteLine("ParseGraph: final line seen, but no number could be read.");
        end
        return;
    end

    if IsTotalDamageLine(text) then
        local value = ParseTotalDamageFromText(text);
        if value ~= nil then
            ParseGraph.RecordDummyTotalDamage(value);
        elseif ParseGraph.Debug then
            Turbine.Shell.WriteLine("ParseGraph: total damage line seen, but no number could be read.");
        end
        return;
    end

    ParseGraph.Refresh();
end

local function IsSayChat(args)
    if args == nil then return false end

    -- LOTRO clients/plugins have used slightly different field names for chat type,
    -- so check the common ones defensively.
    local chatType = args.ChatType or args.Type or args.Channel or args.ChatChannel;

    if chatType == nil then
        -- Do not process unknown chat channels. This prevents kinship/fellowship/raid
        -- quoted dummy messages from being treated as real dummy /say text.
        return false;
    end

    if Turbine.ChatType ~= nil and Turbine.ChatType.Say ~= nil and chatType == Turbine.ChatType.Say then
        return true;
    end

    local channelText = string.lower(tostring(chatType));
    if channelText == "say" or string.find(channelText, "say", 1, true) ~= nil then
        return true;
    end

    return false;
end

function ParseGraph.IsAdvancementChat(args, msg)
    msg = tostring(msg or "");
    if string.find(msg, "Class Specialization Bonus Trait:", 1, true) ~= nil
        or string.find(msg, "You have acquired the Class Specialization Bonus Trait:", 1, true) ~= nil
        or string.find(msg, "Ihr habt diese Bonus", 1, true) ~= nil then
        return true;
    end
    return false;
end

function ParseGraph.ProcessSpecDetectionChat(args, msg)
    if msg == nil then
        return;
    end
    if ParseGraph.IsAdvancementChat(args, msg) then
        ParseGraph.DetectSpecFromText(msg, "advancement chat");
    end
end

function ParseGraph.HandleChatReceived(sender, args)
    local msg = GetChatMessage(args);
    if msg == nil then
        return;
    end

    ParseGraph.ProcessSpecDetectionChat(args, msg);
    ParseGraph.RecordActiveParseDamageEvent(msg);
    ParseGraph.ObservePlayerDummyHit(msg);
    ParseGraph.ObserveFallbackScoreboardEncounter(msg);
    ParseGraph.ProcessFaillowshipChatText(msg);
    ParseGraph.ProcessInstanceQuestText(msg);
    ParseGraph.ProcessInstanceEncounterStartText(msg);
    ParseGraph.ProcessInstanceDefeatText(msg);
    ParseGraph.ProcessInstanceWipeText(msg);
    ParseGraph.ProcessScoreboardDeathText(msg);
    ParseGraph.ProcessCombatAnalysisText(msg);

    if IsSayChat(args) then
        ParseGraph.ProcessText(msg);
    end
end

function ParseGraph.RegisterChatHook()
    local previous = Turbine.Chat.Received;
    if previous == ParseGraph.ChatReceivedWrapper then
        previous = ParseGraph.PreviousChatReceived;
    end

    ParseGraph.PreviousChatReceived = previous;
    ParseGraph.ChatReceivedWrapper = function(sender, args)
        ParseGraph.DispatchExternalEventHandler(ParseGraph.PreviousChatReceived, sender, args, ParseGraph.ChatReceivedWrapper);
        ParseGraph.HandleChatReceived(sender, args);
    end
    Turbine.Chat.Received = ParseGraph.ChatReceivedWrapper;
end

function ParseGraph.CloseWindow()
    ParseGraph.AutoHideForCombat = false;
    ParseGraph.AutoHideCombatWasVisible = false;
    ParseGraph.ClearTemporaryInstanceTarget();
    ParseGraph.HideLauncherContextMenu();
    if ParseGraph.HideParseSpecMenu ~= nil then
        ParseGraph.HideParseSpecMenu();
    end
    if ParseGraph.HideParseSpecFilterMenu ~= nil then
        ParseGraph.HideParseSpecFilterMenu();
    end
    if ParseGraph.Window ~= nil then
        ParseGraph.Window:SetVisible(false);
        ParseGraph.UpdatePostButtonWindowPositions();
        ParseGraph.RememberWindowPosition(false);
    end
    ParseGraph.SetLauncherButtonState();
end

function ParseGraph.ToggleWindow()
    if ParseGraph.EnforceAccessUnavailable ~= nil and ParseGraph.EnforceAccessUnavailable() then
        return;
    end

    if ParseGraph.Window == nil then
        ParseGraph.BuildWindow(true);
    else
        ParseGraph.HideLauncherContextMenu();
        if ParseGraph.HideParseSpecMenu ~= nil then
            ParseGraph.HideParseSpecMenu();
        end
        if ParseGraph.HideParseSpecFilterMenu ~= nil then
            ParseGraph.HideParseSpecFilterMenu();
        end
        ParseGraph.AutoHideForCombat = false;
        ParseGraph.AutoHideCombatWasVisible = false;
        local show = not ParseGraph.Window:IsVisible();
        if not show then
            ParseGraph.ClearTemporaryInstanceTarget();
        end
        ParseGraph.Window:SetVisible(show);
        ParseGraph.UpdatePostButtonWindowPositions();
    end
    ParseGraph.SetLauncherButtonState();
end

if ParseGraph.Command ~= nil and Turbine.Shell.RemoveCommand ~= nil then
    pcall(function()
        Turbine.Shell.RemoveCommand(ParseGraph.Command);
    end);
end

ParseGraph.Command = Turbine.ShellCommand();
function ParseGraph.Command:Execute(command, arguments)
    if ParseGraph.EnforceAccessUnavailable ~= nil and ParseGraph.EnforceAccessUnavailable() then
        return;
    end

    local cmd = string.lower(tostring(command or ""));
    local args = string.lower(tostring(arguments or ""));
    if cmd == "pgbesttest" or cmd == "parsegraphtestbest" then
        ParseGraph.ShowPersonalBestPopup(2418, 193180);
        Turbine.Shell.WriteLine("ParseGraph: test personal best popup shown.");
        return;
    end
    if cmd == "pgachtest" or cmd == "pgachievementtest" or cmd == "parsegraphtestach" or cmd == "parsegraphtestachievement" then
        local achievement = ParseGraph.FindAchievement(args ~= "" and args or "weeklyWarrior");
        ParseGraph.PrintAchievementUnlocked(achievement);
        ParseGraph.ShowAchievementPopup(achievement);
        Turbine.Shell.WriteLine("ParseGraph: test achievement popup shown.");
        return;
    end
    if cmd == "list" then
        ParseGraph.PostGroupListsFromCommand();
        return;
    end
    if args == "test" then
        ParseGraph.ProcessText("Training Snowman says, 'Merry Yule! Shall we exchange a boisterous flurry of blows to celebrate the season?'");
        ParseGraph.ObservePlayerDummyHit("You scored a hit with Test Skill on the Training Snowman for 1 damage.");
        if ParseGraph.ActiveParse ~= nil then
            ParseGraph.ActiveParse.start = Turbine.Engine.GetGameTime() - 61;
        end
        ParseGraph.ProcessText("Training Snowman says, 'Thou hast dislodged roughly 193,658.938 snowflakes with each passing second!'");
        if ParseGraph.ActiveParse ~= nil then
            ParseGraph.ActiveParse.start = Turbine.Engine.GetGameTime() - 121;
        end
        ParseGraph.ProcessText("Training Snowman says, 'Thou hast dislodged roughly 182,123.333 snowflakes with each passing second!'");
        if ParseGraph.ActiveParse ~= nil then
            ParseGraph.ActiveParse.start = Turbine.Engine.GetGameTime() - 181;
        end
        ParseGraph.ProcessText("Training Snowman says, 'Thou hast dislodged roughly 200,999.000 snowflakes with each passing second!'");
        ParseGraph.ProcessText("Training Snowman says, 'You dids\'t mantain a tempestuous rate of 175,264.110 snowflakes for each moment over the span of our game.'");
        return;
    end
    ParseGraph.ToggleWindow();
end
Turbine.Shell.AddCommand("parsegraph:pg:list:pgbesttest:pgachtest:pgachievementtest:parsegraphtestbest:parsegraphtestach:parsegraphtestachievement", ParseGraph.Command);

Turbine.Plugin.Unload = function()
    ParseGraph.RememberWindowPosition(true);
    ParseGraph.RememberLauncherButtonPosition(true);
    ParseGraph.UpdateSavedGroupListData(ParseGraph.GroupListSaveEnabled == true);
    ParseGraph.HideLauncherContextMenu();
    ParseGraph.ClearPostButtonWindows();
    if ParseGraph.GroupListsCommandWindow ~= nil then
        ParseGraph.GroupListsCommandWindow:SetVisible(false);
        if ParseGraph.GroupListsCommandSlot ~= nil and ParseGraph.GroupListsCommandSlot.SetParent ~= nil then
            pcall(function()
                ParseGraph.GroupListsCommandSlot:SetParent(nil);
            end);
        end
        if ParseGraph.GroupListsCommandWindow.SetParent ~= nil then
            pcall(function()
                ParseGraph.GroupListsCommandWindow:SetParent(nil);
            end);
        end
    end
    if ParseGraph.LauncherButton ~= nil then
        ParseGraph.LauncherButton:SetVisible(false);
    end
    if ParseGraph.LauncherTimerBack ~= nil then
        ParseGraph.LauncherTimerBack:SetVisible(false);
    end
    if ParseGraph.GameUiKeyWatcher ~= nil then
        ParseGraph.GameUiKeyWatcher:SetVisible(false);
        ParseGraph.GameUiKeyWatcher:SetWantsKeyEvents(false);
        ParseGraph.GameUiKeyWatcher = nil;
    end
    if ParseGraph.LocalPlayer ~= nil then
        if ParseGraph.LocalPlayer.InCombatChanged == ParseGraph.CombatChangedWrapper then
            ParseGraph.LocalPlayer.InCombatChanged = ParseGraph.PreviousInCombatChanged;
        else
            ParseGraph.RemoveExternalEventHandler(ParseGraph.LocalPlayer.InCombatChanged, ParseGraph.CombatChangedWrapper);
        end
    end
    if Turbine.Chat ~= nil then
        if Turbine.Chat.Received == ParseGraph.ChatReceivedWrapper then
            Turbine.Chat.Received = ParseGraph.PreviousChatReceived;
        else
            ParseGraph.RemoveExternalEventHandler(Turbine.Chat.Received, ParseGraph.ChatReceivedWrapper);
        end
    end
end

ParseGraph.Load();
if ParseGraph.EnforceAccessUnavailable() then
    return;
end
ParseGraph.InitializeSpecDetection();
ParseGraph.SessionStartCount = #ParseGraph.Parses;
ParseGraph.SessionStartByCharacter[ParseGraph.ViewCharacterKey or ParseGraph.GetCurrentCharacterKey()] = ParseGraph.SessionStartCount;
ParseGraph.BuildWindow(ParseGraph.StartMinimized ~= true);
ParseGraph.RegisterChatHook();
ParseGraph.RegisterCombatHook();
if ParseGraph.IsPlayerInCombat() then
    ParseGraph.HandleCombatChanged(true);
end
Turbine.Shell.WriteLine("ParseGraph " .. ParseGraph.VERSION .. " loaded. Parses loaded: " .. tostring(#ParseGraph.Parses) .. ". Use /parsegraph or /pg to show and hide the window.");

